def rial(n) -> str:
    return f"{int(n):,} تومان"


# بزرگ‌ترین عددی که اصلاً جایی در دیتابیس جا می‌شود (ستون‌هایِ پولی NUMERIC(14,0)
# هستند؛ آیدیِ تلگرام هم خیلی کمتر از این است). قبلاً عددهایی مثلِ
# 550045757643676767 بی‌قیدوشرط قبول می‌شد و commit با overflow می‌ترکید.
FA_INT_MAX = 10 ** 13

# سقفِ «تعدادِ استفاده»/شمارنده‌ها که در ستون‌هایِ INTEGER (int32) ذخیره می‌شوند.
MAX_USES = 1_000_000


def fa_to_int(text: str) -> int | None:
    trans = str.maketrans("۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩", "01234567890123456789")
    digits = (text or "").translate(trans).replace(",", "").replace("،", "").strip()
    if not digits.isdigit() or len(digits) > 14:
        return None
    n = int(digits)
    return n if n <= FA_INT_MAX else None


# === PATCH_PERSIAN_DIGITS_RTL_V1 ===
_FA_DIGIT_MAP = str.maketrans("0123456789", "۰۱۲۳۴۵۶۷۸۹")


def fa_digits(s) -> str:
    """ارقامِ لاتین رو به ارقامِ فارسی تبدیل می‌کنه.

    چرا برایِ چیدمانِ راست‌به‌چپ مهمه: ارقامِ لاتین تویِ استانداردِ متنِ
    دوجهته کلاسِ EN دارن و وقتی کنارِ متنِ فارسی و جداکننده‌ای مثلِ «/»
    قرار می‌گیرن، ترتیبشون جابه‌جا می‌شه — مثلاً «2 گیگ/30 روز» بهم‌ریخته
    نمایش داده می‌شه. ارقامِ فارسی کلاسِ AN دارن و سرِ جایِ خودشون می‌مونن.
    """
    return str(s).translate(_FA_DIGIT_MAP)


def cancel_kb() -> ReplyKeyboardMarkup:
    return ReplyKeyboardMarkup(
        keyboard=[[KeyboardButton(text="❌ لغو")]],
        resize_keyboard=True,
    )


async def smart_cancel_kb(bot: Bot):
    """کیبوردِ «لغو» هماهنگ با نوعِ منوی ربات.

    در حالتِ «شیشه‌ای» یک دکمهٔ اینلاینِ «❌ لغو» برمی‌گرداند (تا هیچ کیبوردِ
    پایینِ صفحه‌ای در آن حالت ظاهر نشود)؛ در حالتِ «کیبورد» همان کیبوردِ
    معمولیِ قبلی را برمی‌گرداند. لغوِ واقعی برای هر دو حالت به‌صورت یکپارچه از
    طریق fsm_cancel_inline (برای اینلاین) و خودِ متنِ «❌ لغو» (برای کیبورد)
    انجام می‌شود.
    """
    row = await get_bot_row(bot)
    if row and await get_setting(row.id, "menu_mode", "reply") == "inline":
        return InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text="❌ لغو", callback_data="fsm:cancel")]
        ])
    return cancel_kb()


@tenant_router.callback_query(F.data == "fsm:cancel")
async def fsm_cancel_inline(cb: CallbackQuery, state: FSMContext, bot: Bot):
    """لغوِ عمومیِ هر فرآیندِ متنیِ در حالِ انتظار (نسخهٔ اینلاینِ دکمهٔ «❌ لغو»).

    === PATCH_DISCOUNT_CANCEL_BACK_V1 ===
    قبلاً برای *همهٔ* حالت‌ها (از جمله وسطِ واردکردنِ کدِ تخفیف حینِ خرید)
    فقط یه پیامِ خشکِ «❌ لغو شد.» بدونِ هیچ دکمه‌ای نشون داده می‌شد — یعنی
    کاربر دقیقاً همون‌جا گیر می‌کرد و مجبور بود /start بزنه. برای سه تا
    حالتِ خاصِ واردکردنِ کدِ تخفیف (فروشگاهِ محدود، فروشگاهِ نامحدود، و
    پیش‌فاکتورِ دستیِ کانفیگ)، الان به‌جایِ اون پیامِ خشک، دقیقاً همون
    صفحه‌ای که قبل از زدنِ «کد تخفیف» توش بود رو (بدونِ تخفیف) دوباره
    نشون می‌دیم — یعنی «لغو» واقعاً یعنی برگشت به مرحلهٔ قبل، نه بن‌بست.
    """
    cur_state = await state.get_state()
    # === PATCH_ADMIN_USER_CANCEL_BACK_V1 ===
    # همان الگویِ «لغو یعنی برگشت به همون صفحه، نه بن‌بست» را برایِ
    # فرآیندهایِ مدیریتِ کاربر (افزودن/کاهشِ کیف‌پول، روز، حجم) هم اضافه
    # می‌کنیم — قبلاً لغوِ هرکدام کاربر را به منویِ اصلی می‌فرستاد، پس
    # ادمین برایِ ادامهٔ کار مجبور بود دوباره آیدیِ عددیِ همان شخص را بزند.
    if cur_state in (AdminFSM.adjust_days.state, AdminFSM.adjust_gb.state,
                    AdminFSM.adjust_amount.state):
        data = await state.get_data()
        target_uid = data.get("target_uid")
        await state.clear()
        if target_uid:
            try:
                await cb.message.delete()
            except Exception:
                logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
            await _render_user_detail(cb.message, bot, int(target_uid))
            await cb.answer()
            return
    # === PATCH_VPN_PLAN_CATEGORY_RENAME_V1 ===
    from tenant.bots.vpn.vpn_admin import VpnCatRenameFSM, vpn_plans
    if cur_state == VpnCatRenameFSM.name.state:
        data = await state.get_data()
        key = data.get("cat_panel_key")
        await state.clear()
        if key:
            fake_cb = type("CB", (), {
                "data": f"tvpn:plans:{key}", "answer": cb.answer,
                "message": cb.message, "from_user": cb.from_user,
            })()
            await vpn_plans(fake_cb, bot)
            return
    if cur_state == _ManualCfgDiscountFSM.entering.state:
        # پیش‌فاکتورِ دستیِ کانفیگ: کد رو لغو کن و همون پیش‌فاکتور رو دوباره نشون بده
        await state.set_state(None)
        try:
            await cb.message.delete()
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        try:
            await _show_manual_preinvoice(cb.message, bot, cb.from_user, state)
            await cb.answer()
            return
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (بازگشت به پیش‌فاکتور بعد از لغوِ کدِ تخفیف)")
    if cur_state in (BuyFSM.discount.state, BuyFSM.discount_unlimited.state):
        data = await state.get_data()
        await state.clear()
        row = await get_bot_row(bot)
        try:
            if cur_state == BuyFSM.discount.state:
                mbid, vi, di, c = data.get("disc_mbid"), data.get("disc_vi"), \
                    data.get("disc_di"), data.get("disc_c")
                res = await get_btn_cfg(mbid) if mbid is not None else None
                if row and res:
                    cfg, _ = res
                    is_owner = (cb.from_user.id == row.owner_id)
                    await cb.message.edit_text(
                        "🛒 سفارش:",
                        reply_markup=await buy_kb(mbid, vi, di, c, cfg, 0, plan=row.plan, is_owner=is_owner, bot_id=row.id))
                    await cb.answer()
                    return
            else:
                mbid, di, c = data.get("discu_mbid"), data.get("discu_di"), data.get("discu_c")
                if row and mbid is not None:
                    cfg = await get_unlimited_cfg(row.id)
                    is_owner = (cb.from_user.id == row.owner_id)
                    await cb.message.edit_text(
                        "♾️ سفارش:",
                        reply_markup=await buy_unlimited_kb(mbid, di, c, cfg, 0, plan=row.plan, is_owner=is_owner, bot_id=row.id))
                    await cb.answer()
                    return
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (بازگشت به صفحهٔ خرید بعد از لغوِ کدِ تخفیف)")
        # اگه به هر دلیلی (مثلاً سفارش/دکمه دیگه وجود نداشت) نشد برگردونیمش
        # به صفحهٔ خرید، حداقل مثلِ قبل رفتار کن (نه کرش)
    else:
        await state.clear()
    # === PATCH_CANCEL_BUTTONS_SHOW_MENU_V1 ===
    # قبلاً همینجا فقط «❌ لغو شد.» بدونِ هیچ دکمه‌ای نشون داده می‌شد —
    # برایِ هر فرآیندی که بالاتر موردِ خاصش تعریف نشده بود (خریدِ تون،
    # گیفت، پرمیوم، استارز، و خیلی جاهایِ دیگه که همه از همین دکمهٔ
    # مشترکِ «❌ لغو» استفاده می‌کنن). چون این تابع مشترکه، درست‌کردنِ همین
    # مسیرِ پیش‌فرض یعنی همه‌ی اون جاها یک‌جا درست می‌شن: به‌جایِ پیامِ
    # خشک، منویِ اصلی رو با دکمه‌هاش نشون می‌ده.
    row = await get_bot_row(bot)
    if not row:
        try:
            await cb.message.edit_text("❌ لغو شد.")
        except Exception:
            await cb.message.answer("❌ لغو شد.")
        await cb.answer()
        return
    if await get_setting(row.id, "menu_mode", "reply") == "inline":
        # === PATCH_GLASS_EDIT_IN_PLACE_V1 === همان پیام به منوی اصلی تبدیل می‌شود
        ikb = await main_inline_kb(row.id, row.owner_id, cb.from_user.id)
        await send_home_menu(cb, row.id, ikb, prefer_edit=True)
    else:
        try:
            await cb.message.delete()
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        kb = await main_kb_or_remove(row.id, row.owner_id, cb.from_user.id)
        await send_home_menu(cb.message, row.id, kb or ReplyKeyboardRemove())
    await cb.answer()


