async def edit_or_replace(cb_msg, text: str,
                          reply_markup=None, parse_mode: str = "HTML") -> None:
    """در حالت inline: اول سعی می‌کند پیام را edit کند.
    اگر نشد (پیام قدیمی، media، یا محتوای یکسان) پیام فعلی را حذف و
    یک پیام جدید ارسال می‌کند — بدون انباشته شدن پیام در چت."""
    try:
        await cb_msg.edit_text(text, reply_markup=reply_markup, parse_mode=parse_mode)
        return
    except Exception:
        logger.debug("تمیزکاریِ ظاهریِ پیام ناموفق بود (بی‌اهمیت)")
    try:
        await cb_msg.delete()
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    try:
        await cb_msg.answer(text, reply_markup=reply_markup, parse_mode=parse_mode)
    except Exception:
        # === PATCH_BUTTON_URL_GUARD_V1 ===
        # اگه ارسالِ پیام با reply_markup هم fail بشه (مثلاً به‌خاطرِ یه دکمهٔ
        # لینکِ نامعتبر که از این تابع لو نمی‌ره)، به‌جایِ کرشِ کلِ هندلر و
        # ترِیس‌بکِ خام تو لاگ، پیام رو بدونِ دکمه می‌فرستیم تا کاربر حداقل
        # متن رو ببینه.
        logger.warning("edit_or_replace: ارسال با reply_markup fail شد — تلاشِ مجدد بدونِ دکمه")
        try:
            await cb_msg.answer(text, parse_mode=parse_mode)
        except Exception:
            logger.exception("edit_or_replace: ارسالِ بدونِ دکمه هم fail شد")


# === PATCH_GLASS_EDIT_IN_PLACE_V1 ===
# منوی شیشه‌ای: قبلاً با هر بار زدنِ دکمه، پیامِ قبلی حذف و پیامِ جدید فرستاده
# می‌شد (پیوی شلوغ می‌شد). حالا اولین پیامِ متنیِ «صفحهٔ بعدی» که هندلر
# می‌فرستد، به‌جایِ ارسالِ جدید، رویِ *همان پیامِ منو* ویرایش می‌شود.
# اگر ویرایش ممکن نبود (پیامِ مدیا/کپشن‌دار، قدیمی، ...) یا هندلر مدیا/استیکر
# فرستاد، رفتارِ قبلی (حذفِ پیامِ قدیمی + ارسالِ جدید) اجرا می‌شود.
from contextvars import ContextVar as _ContextVar
_GLASS_EDIT: "_ContextVar[dict | None]" = _ContextVar("glass_edit_target", default=None)


async def _glass_generic_step(st, make_request, bot, method, name):
    """=== PATCH_GLASS_EDIT_GENERIC_V1 === حالتِ عمومی (برایِ *همهٔ* دکمه‌هایِ کاربر در منوی شیشه‌ای).

    قاعده‌ها (محافظه‌کارانه‌تر از حالتِ «دکمهٔ منوی اصلی»):
      • فقط اولین ارسالِ *متنی* که *صفحه* باشد (دکمهٔ اینلاین دارد) به ویرایشِ همان پیام تبدیل می‌شود.
        پیامِ بی‌دکمه (مثلاً «⏳ صبر کن»، «✅ ثبت شد») و مدیا و کیبوردِ پایین دست‌نخورده می‌روند.
      • اگر هندلر پیش از ارسال خودش پیامِ قبلی را ویرایش/حذف کرده، دخالت نمی‌کنیم.
      • بعد از تبدیل: حذفِ همان پیام (الگوی «صفحهٔ تازه بفرست، قدیمی را پاک کن») و برداشتنِ دکمه‌هایش
        نادیده گرفته می‌شود، چون همان پیام دیگر «صفحهٔ تازه» است.
      • اگر ویرایش ممکن نشد، ارسالِ معمولی (بدونِ حذفِ پیامِ قبلی)."""
    from aiogram.methods import EditMessageText, SendMessage
    same_chat = getattr(method, "chat_id", None) == st["chat_id"]
    same_msg = same_chat and getattr(method, "message_id", None) == st["message_id"]
    if name in ("EditMessageText", "EditMessageCaption", "EditMessageMedia", "EditMessageReplyMarkup"):
        if same_msg:
            if not st.get("converted"):
                st["done"] = True                      # هندلر خودش پیام را مدیریت می‌کند
            elif name == "EditMessageReplyMarkup" and not getattr(method, "reply_markup", None):
                return True                            # «دکمه‌ها را بردار» رویِ صفحهٔ تازه
        return await make_request(bot, method)
    if name == "DeleteMessage":
        if same_msg:
            if st.get("converted"):
                return True                            # صفحهٔ تازه همین پیام است؛ پاکش نکن
            st["done"] = True
        return await make_request(bot, method)
    if not name.startswith("Send") or name == "SendChatAction" or not same_chat:
        return await make_request(bot, method)
    if st.get("sent") or getattr(method, "reply_parameters", None) is not None:
        return await make_request(bot, method)
    st["sent"] = True                                  # فقط اولین ارسال بررسی می‌شود
    markup = getattr(method, "reply_markup", None)
    is_page = (isinstance(method, SendMessage) and isinstance(markup, InlineKeyboardMarkup)
               and bool(markup.inline_keyboard))
    if not is_page:
        st["done"] = True
        return await make_request(bot, method)
    try:
        res = await make_request(bot, EditMessageText(
            chat_id=st["chat_id"], message_id=st["message_id"], text=method.text,
            parse_mode=method.parse_mode, entities=method.entities,
            link_preview_options=method.link_preview_options, reply_markup=markup))
        st["converted"] = True
        return res
    except Exception as e:  # noqa: BLE001
        if "not modified" in str(e).lower():
            st["converted"] = True
            return st["msg"]                           # همین صفحه از قبل رویِ پیام بود
        st["done"] = True
        logger.info("ویرایشِ درجا ممکن نشد؛ ارسالِ معمولی: %s", e)
        return await make_request(bot, method)


async def _glass_edit_session_mw(make_request, bot, method):
    st = _GLASS_EDIT.get()
    if st is None or st["done"]:
        return await make_request(bot, method)
    if st.get("generic"):
        return await _glass_generic_step(st, make_request, bot, method, type(method).__name__)
    from aiogram.methods import EditMessageText, SendMessage
    name = type(method).__name__
    if not name.startswith("Send") or name == "SendChatAction":
        return await make_request(bot, method)
    if getattr(method, "chat_id", None) != st["chat_id"]:
        return await make_request(bot, method)
    if getattr(method, "reply_parameters", None) is not None:
        return await make_request(bot, method)
    st["done"] = True   # فقط اولین ارسال
    if isinstance(method, SendMessage) and (
            method.reply_markup is None or isinstance(method.reply_markup, InlineKeyboardMarkup)):
        try:
            return await make_request(bot, EditMessageText(
                chat_id=st["chat_id"], message_id=st["message_id"], text=method.text,
                parse_mode=method.parse_mode, entities=method.entities,
                link_preview_options=method.link_preview_options,
                reply_markup=method.reply_markup))
        except Exception as e:
            if "not modified" in str(e).lower():
                return st["msg"]   # همان صفحه از قبل روی پیام بوده
            logger.info("ویرایشِ درجایِ منوی شیشه‌ای ممکن نشد؛ حذف و ارسالِ تازه: %s", e)
    # مدیا/استیکر/ویرایشِ ناموفق: مثلِ قبل پیامِ قدیمی را پاک کن
    try:
        await st["msg"].delete()
    except Exception:
        logger.debug("حذفِ پیامِ قدیمیِ منوی شیشه‌ای ممکن نشد (بی‌اهمیت)")
    return await make_request(bot, method)


def _glass_edit_begin(bot: Bot, cb_msg, generic: bool = False):
    """شروعِ حالتِ «ویرایشِ درجا» برایِ همین هندلر. توکن را به _glass_edit_end بده.
    generic=True (PATCH_GLASS_EDIT_GENERIC_V1): قاعده‌هایِ محافظه‌کارانهٔ همهٔ دکمه‌هایِ کاربر."""
    if not getattr(bot.session, "_glass_edit_mw", False):
        bot.session.middleware(_glass_edit_session_mw)
        bot.session._glass_edit_mw = True
    # پیامِ ساختگی (_FakeCbMessage — مثلاً وقتی mbtn_tap از دیپ‌لینکِ /start
    # صدا زده می‌شود) chat/message_id ندارد و پیامِ کاربر هم قابلِ ویرایش
    # نیست؛ پس ویرایشِ درجا را از همان اول خاموش می‌کنیم (done=True) به‌جای
    # AttributeError که قبلاً کلِ دکمه را از کار می‌انداخت.
    chat = getattr(cb_msg, "chat", None)
    st = {"chat_id": getattr(chat, "id", None), "message_id": getattr(cb_msg, "message_id", None),
          "msg": cb_msg, "done": chat is None or getattr(cb_msg, "_is_fake", False),
          "generic": generic, "sent": False, "converted": False}
    return st, _GLASS_EDIT.set(st)


def _glass_edit_end(st, token) -> None:
    st["done"] = True
    try:
        _GLASS_EDIT.reset(token)
    except Exception:
        logger.debug("reset glass edit ctx failed (بی‌اهمیت)")


_BOT_ROW_CACHE: dict[str, tuple["BotRow", float]] = {}
_BOT_ROW_CACHE_TTL = 20.0  # ثانیه


# === PATCH_BLOCKED_USERS_V1 ===

async def mark_blocked(bot_id: int, telegram_id: int, blocked: bool = True) -> None:
    """ثبت/پاک‌کردنِ وضعیتِ «ربات را بلاک کرده».

    تلگرام هیچ APIی برایِ پرسیدنِ اینکه کاربر ربات را بلاک کرده یا نه ندارد؛
    تنها نشانه، خطایِ Forbidden هنگامِ ارسالِ پیام است. پس هرجا ارسال شکست
    خورد اینجا ثبت می‌شود، و به‌محضِ اینکه کاربر دوباره با ربات کار کند
    (هر پیامی بفرستد) پاک می‌شود.
    """
    from sqlalchemy import update as _sa_update
    try:
        async with Session() as s:
            await s.execute(
                _sa_update(BotUser)
                .where(BotUser.bot_id == bot_id, BotUser.telegram_id == telegram_id)
                .values(is_blocked=blocked,
                        blocked_at=(_dt.datetime.utcnow() if blocked else None)))
            await s.commit()
    except Exception:
        logger.exception("mark_blocked failed for %s", telegram_id)


def _is_blocked_error(exc: Exception) -> bool:
    """آیا این خطا یعنی کاربر ربات را بلاک کرده / چت در دسترس نیست؟"""
    txt = str(exc).lower()
    return ("blocked" in txt or "user is deactivated" in txt
            or "chat not found" in txt or "bot was kicked" in txt)


# === PATCH_PARTNER_V11 ===
def invalidate_bot_row_cache(token: str | None = None) -> None:
    """کشِ ردیفِ ربات را باطل می‌کند تا تغییرِ وضعیت فوراً اثر کند.

    بدونِ این، بعد از خاموش/روشن‌کردنِ ربات تا _BOT_ROW_CACHE_TTL ثانیه
    (۲۰ ثانیه) رفتارِ قدیمی ادامه داشت — کاربران به رباتِ «متوقف» هنوز
    دسترسی داشتند و مالک فکر می‌کرد دکمه کار نکرده.

    نکته: این فقط کشِ *همین پروسه* را پاک می‌کند. برایِ پروسه‌هایِ دیگر
    باید tenant_status_bus.publish_tenant_invalidate هم صدا زده شود.
    """
    if token:
        _BOT_ROW_CACHE.pop(token, None)
    else:
        _BOT_ROW_CACHE.clear()


async def get_bot_row(bot: Bot) -> BotRow | None:
    # === PATCH_BOTROW_TTL_CACHE_V1 ===
    # get_bot_row در ابتدای تقریباً هر هندلری صدا زده می‌شود (پرتکرارترین
    # کوئریِ کل پروژه). کشِ کوتاه‌مدت (۲۰ ثانیه) رفت‌وبرگشتِ تکراری به DB را
    # برای دکمه‌هایی که سریع/پشتِ‌سرهم زده می‌شوند (مثلِ استپرِ ➕➖) حذف
    # می‌کند. چون BotRow به‌ندرت (status/plan توسطِ ادمینِ پلتفرم) تغییر
    # می‌کند، تاخیرِ حداکثر ۲۰ثانیه‌ای در دیدنِ آن تغییرات قابلِ قبول است.
    import time as _time
    cached = _BOT_ROW_CACHE.get(bot.token)
    if cached is not None and cached[1] > _time.monotonic():
        return cached[0]
    async with Session() as s:
        row = await s.scalar(select(BotRow).where(BotRow.token == bot.token))
    if row is not None:
        _BOT_ROW_CACHE[bot.token] = (row, _time.monotonic() + _BOT_ROW_CACHE_TTL)
    return row


import string as _string


def _gen_tracking() -> str:
    """کد پیگیری ۸ کاراکتری (حروف بزرگ + عدد)."""
    import secrets
    chars = _string.ascii_uppercase + _string.digits
    return "".join(secrets.choice(chars) for _ in range(8))


async def _gen_invoice_no(bot_id: int) -> str:
    """شماره فاکتور = همان شناسهٔ واحدِ سفارش (کدِ پیگیریِ ترتیبی)."""
    from models import next_tracking as _nt
    return await _nt(bot_id)


async def _attach_invoice(order_id: int, bot_id: int):
    """شناسهٔ واحدِ سفارش: شماره فاکتور و کد پیگیری یکی‌اند.
    سفارش موقعِ درج خودش شمارهٔ ترتیبی گرفته؛ همان را برمی‌گردانیم (شمارنده دوباره بالا نمی‌رود)."""
    from models import alloc_tracking_in as _alloc_in  # PATCH_SEQ_TRACKING_V1
    async with Session() as s:
        o = await s.get(Order, order_id)
        if not o:
            return "", ""
        trk = o.tracking_code
        if not trk:
            trk = await _alloc_in(s, bot_id)
            o.tracking_code = trk
        o.invoice_no = trk
        await s.commit()
    return trk, trk


# === PATCH_SETTING_TTL_CACHE_V1 ===
# get_setting در کل پروژه ۳۰۰+ بار صدا زده می‌شود و هر بار یک Session/کانکشنِ
# جداگانه از DB باز می‌کند — حتی برای تنظیماتی که به‌ندرت تغییر می‌کنند (مثلاً
# card_enabled، menu_mode، nowpay_enabled). زیرِ بار، همین رفت‌وبرگشت‌های کوچکِ
# پشتِ‌سرهم جمع می‌شوند و کند حس می‌شوند. اینجا یک کشِ سبکِ حافظه‌ای با TTL کوتاه
# اضافه شده: تا وقتی مقدار عوض نشده (یا TTL تمام نشده)، از DB دوباره خوانده
# نمی‌شود. چون بعضی مسیرها مستقیم روی جدولِ Setting می‌نویسند (بدونِ عبور از
# set_setting)، TTL کوتاه (به‌جای کشِ دائمی+invalidation) انتخاب شده تا حداکثر
# چند ثانیه تاخیر در دیدنِ تغییرات باشد، نه ریسکِ دیتای همیشه بات‌مانده.
_SETTING_CACHE: dict[tuple[int, str], tuple[str, float]] = {}
_SETTING_CACHE_TTL = 10.0  # ثانیه


async def get_setting(bot_id: int, key: str, default: str = "") -> str:
    import time as _time
    cache_key = (bot_id, key)
    cached = _SETTING_CACHE.get(cache_key)
    if cached is not None and cached[1] > _time.monotonic():
        return cached[0] or default
    async with Session() as s:
        row = await s.scalar(select(Setting).where(Setting.bot_id == bot_id, Setting.key == key))
    value = row.value if row else ""
    _SETTING_CACHE[cache_key] = (value, _time.monotonic() + _SETTING_CACHE_TTL)
    return value or default


# === PATCH_CUSTOM_HOME_MENU_TEXT_V1 ===
HOME_MENU_TEXT_DEFAULT = "🏠 منوی اصلی:"


# === PATCH_CUSTOM_HOME_MENU_TEXT_HIDE_V1 ===
# تلگرام اجازهٔ ارسالِ پیامِ کاملاً خالی را نمی‌دهد، ولی هر کدام از این ۲۵ جایِ
# کد باید همچنان کیبوردِ منوی اصلی را بفرستد. پس در حالتِ «مخفی» به‌جای متن،
# یک کاراکترِ نامرئی (WORD JOINER) فرستاده می‌شود؛ نتیجه برایِ کاربر یعنی
# پیامی بدونِ هیچ متنی، فقط با دکمه‌ها.
HOME_MENU_TEXT_HIDDEN_MARK = "\u2060"


async def home_menu_text_hidden(bot_id: int) -> bool:
    """آیا مالکِ ربات متنِ بازگشت به صفحهٔ اصلی را مخفی کرده است؟"""
    return (await get_setting(bot_id, "home_menu_text_hidden", "")) == "1"


async def home_menu_text(bot_id: int) -> str:
    """متنی که موقعِ برگشت به صفحهٔ اصلی نشون داده می‌شه. قبلاً تویِ ۱۹ جایِ
    مختلفِ کد به‌صورتِ ثابت («🏠 منوی اصلی:») نوشته شده بود؛ حالا مالکِ ربات
    می‌تونه از پنلِ مدیریت → «🎛 دکمه‌ها و تنظیمات» عوضش کنه — یا کلاً
    مخفی‌اش کنه (PATCH_CUSTOM_HOME_MENU_TEXT_HIDE_V1)."""
    if await home_menu_text_hidden(bot_id):
        return HOME_MENU_TEXT_HIDDEN_MARK
    return await get_setting(bot_id, "home_menu_text", HOME_MENU_TEXT_DEFAULT)


# === PATCH_CUSTOM_HOME_MENU_TEXT_HIDE_V2 ===
# === PATCH_CUSTOM_HOME_MENU_TEXT_HIDE_V8 ===
# آخرین «بابلِ خالیِ» منوی اصلی برای هر (bot_id, chat_id) — تا بابلِ قبلی
# پاک شود و در چت روی هم تلنبار نشوند. حافظه‌ای است و با ری‌استارت خالی
# می‌شود؛ بدترین حالتش یک بابلِ جامانده است.
# === PATCH_BTN_STICKER_CLEANUP_V1 ===
# استیکرِ دکمه‌ها روی صفحه تلنبار می‌شد. شناسهٔ آخرین استیکرِ هر کاربر
# این‌جا می‌ماند تا با ارسالِ استیکرِ بعدی یا بازگشت به خانه پاک شود.
_LAST_BTN_STICKER: dict[tuple, int] = {}


async def _drop_btn_sticker(bot, bot_id, chat_id) -> None:
    mid = _LAST_BTN_STICKER.pop((bot_id, chat_id), None)
    if not mid:
        return
    try:
        await bot.delete_message(chat_id, mid)
    except Exception:
        logger.info("پاک‌کردنِ استیکرِ دکمه ممکن نشد (bot_id=%s)", bot_id)


_HIDDEN_HOME_BUBBLES: dict = {}

# === PATCH_CUSTOM_HOME_MENU_TEXT_HIDE_V11 ===
# نتیجهٔ قطعیِ تست‌ها: پاک‌کردنِ پیامِ حاملِ کیبورد — چه فوری، چه چند ثانیه
# بعد، چه با is_persistent — کیبوردِ پایین را هم می‌اندازد. پس این بابل
# باید بماند و فقط بابلِ *قبلی* پاک می‌شود تا تلنبار نشوند.


async def send_home_menu(target, bot_id: int, reply_markup=None, *,
                         prefix: str = "", attach=None, prefer_edit: bool = False):
    """ارسالِ پیامِ «منوی اصلی» با رعایتِ تنظیمِ «مخفی‌کردنِ این پیام».

    وقتی مالکِ ربات این پیام را مخفی کرده باشد، دیگر هیچ بابلِ اضافه‌ای
    فرستاده نمی‌شود:
      • کیبوردِ پایین (Reply): پیامی با متنِ نامرئی می‌رود تا کیبورد عوض
        شود و بلافاصله پاک می‌شود — کاربر بابلی نمی‌بیند ولی منو عوض می‌شود.
      • منوی اینلاین: دکمه‌ها روی پیامِ `attach` (مثلاً همان پیامِ
        خوش‌آمدگویی) یا روی همان پیامی که کاربر رویش دکمه زده سوار می‌شوند.
    `target` می‌تواند Message یا CallbackQuery باشد.
    """
    msg_obj = getattr(target, "message", None) or target
    # === PATCH_BTN_STICKER_CLEANUP_V1_HOME ===
    # هر بازگشت به خانه (کیبوردی، اینلاین یا لغو) استیکر دکمهٔ قبلی را
    # از روی صفحه برمیدارد تا چت تمیز بماند.
    try:
        await _drop_btn_sticker(msg_obj.bot, bot_id, msg_obj.chat.id)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    if msg_obj is None:
        return None
    # === PATCH_BOT_LANG_TOGGLE_V1 ===
    # اگه کاربر زبانِ انگلیسی رو انتخاب کرده، برچسبِ دکمه‌ها رو زنده ترجمه
    # می‌کنیم — قبل از هر دو مسیر (مخفی/عادی)، چون هردوشون از همین
    # reply_markup استفاده می‌کنن.
    try:
        _tg_user = getattr(target, "from_user", None)
        if _tg_user is not None and reply_markup is not None:
            from tenant.shared.translate import user_lang, translate_kb_labels
            _lang = await user_lang(bot_id, _tg_user.id)
            if _lang == "en":
                reply_markup = await translate_kb_labels(bot_id, reply_markup, "en")
    except Exception:
        logger.exception("ترجمهٔ دکمه‌هایِ منویِ اصلی ناموفق بود؛ نسخهٔ فارسی نمایش داده می‌شود")
    _flow_kb_clear(bot_id, getattr(getattr(target, "from_user", None), "id", None))   # PATCH_FLOW_BACK_KB_V1
    hidden = (not prefix) and await home_menu_text_hidden(bot_id)
    if hidden:
        # === PATCH_CUSTOM_HOME_MENU_TEXT_HIDE_V3 ===
        # کیبوردِ پایین (Reply) فقط با ارسالِ یک پیام عوض می‌شود؛ اگر چیزی
        # نفرستیم، کاربر دکمهٔ «بازگشت به منوی اصلی» را می‌زند و هیچ اتفاقی
        # نمی‌افتد — کیبوردِ زیرمنو هم سرِ جایش می‌ماند (باگِ نسخهٔ V2).
        # پس پیامی با متنِ نامرئی می‌فرستیم و بلافاصله پاکش می‌کنیم؛ تلگرام
        # کیبوردِ تنظیم‌شده را بعد از حذفِ پیام هم نگه می‌دارد، ولی هیچ
        # بابلی در چت باقی نمی‌ماند.
        # === PATCH_CUSTOM_HOME_MENU_TEXT_HIDE_V5 ===
        # نسخهٔ V3 پیامِ نامرئی را بلافاصله پاک می‌کرد؛ ولی کلاینت‌های تلگرام
        # با حذفِ آن پیام، کیبوردِ پایین را هم برمی‌گردانند/می‌اندازند و نتیجه
        # این می‌شد که کاربر «برگشت» می‌زد و منو اصلاً نمی‌آمد. رسیدنِ کاربر
        # به منو مهم‌تر از پنهان‌کردنِ پیام است، پس دیگر پاکش نمی‌کنیم:
        # پیام بدونِ هیچ متنِ دیدنی می‌ماند و فقط کیبورد را عوض می‌کند.
        if not isinstance(reply_markup, InlineKeyboardMarkup):
            if reply_markup is None:
                return None
            # === PATCH_CUSTOM_HOME_MENU_TEXT_HIDE_V8 ===
            # آزمودیم: حذفِ پیامِ حاملِ کیبورد (حتی با is_persistent) باعث
            # می‌شود کلاینت کیبوردِ پایین را هم بیندازد و منو پاک شود. پس
            # پیام باید بماند. کاری که می‌شود کرد این است که بابلِ قبلی را
            # پاک کنیم تا در چت روی هم تلنبار نشوند و همیشه فقط یکی باشد.
            _chat_id = getattr(getattr(msg_obj, "chat", None), "id", None)
            _key = (bot_id, _chat_id)
            _prev = _HIDDEN_HOME_BUBBLES.pop(_key, None)
            try:
                sent = await msg_obj.answer(HOME_MENU_TEXT_HIDDEN_MARK, reply_markup=reply_markup)
            except Exception:
                # اگر تلگرام متنِ نامرئی را «پیامِ خالی» بداند و رد کند،
                # نباید کاربر بدونِ منو بماند؛ متنِ عادی فرستاده می‌شود.
                logger.warning("متنِ نامرئیِ منوی اصلی رد شد؛ متنِ عادی فرستاده "
                               "می‌شود (bot_id=%s)", bot_id)
                return await msg_obj.answer(
                    await get_setting(bot_id, "home_menu_text", HOME_MENU_TEXT_DEFAULT),
                    reply_markup=reply_markup)
            if _chat_id is not None:
                _HIDDEN_HOME_BUBBLES[_key] = sent.message_id
                if _prev and _prev != sent.message_id:
                    try:
                        await sent.bot.delete_message(_chat_id, _prev)
                    except Exception:
                        logger.info("پاک‌کردنِ بابلِ خالیِ قبلیِ منو ممکن نشد "
                                    "(bot_id=%s)", bot_id)
            # === PATCH_CUSTOM_HOME_MENU_TEXT_HIDE_V9 ===
            # خودِ پیامِ «🏠 بازگشت به خانه»‌ای که کاربر زده هم پاک می‌شود تا
            # چت تمیز بماند (فقط وقتی target همان پیامِ کاربر است، یعنی
            # دکمهٔ کیبوردی؛ نه پیامِ ربات).
            if getattr(target, "message", None) is None:
                try:
                    await target.delete()
                except Exception:
                    logger.info("پاک‌کردنِ پیامِ «بازگشت»ِ کاربر ممکن نشد "
                                "(bot_id=%s)", bot_id)
            return sent
        _tried = []
        # پیامِ خودِ کاربر را ربات نمی‌تواند ویرایش کند؛ فقط پیامی که کاربر
        # رویش دکمه زده (msg_obj در حالتِ CallbackQuery) یا پیامِ صریحِ attach.
        _cands = [attach]
        if getattr(target, "message", None) is not None:
            _cands.append(msg_obj)
        for _m in _cands:
            if _m is None or any(_m is t for t in _tried):
                continue
            _tried.append(_m)
            try:
                await _m.edit_reply_markup(reply_markup=reply_markup)
                return _m
            except Exception as e:
                # === PATCH_CUSTOM_HOME_MENU_TEXT_HIDE_V4 ===
                # اگر همین منو از قبل رویِ پیام بوده، تلگرام
                # «message is not modified» می‌دهد؛ یعنی کاربر همین حالا
                # منو را جلوی چشمش دارد و کار تمام است — نباید بابلِ
                # اضافه بفرستیم.
                if "not modified" in str(e):
                    return _m
                logger.info("سوارکردنِ منوی اینلاین رویِ پیامِ موجود ممکن نشد؛ "
                            "مسیرِ بعدی امتحان می‌شود (bot_id=%s)", bot_id)
        # آخرین راه: پیامی بدونِ متنِ دیدنی، تا منو کلاً گم نشود
        return await msg_obj.answer(HOME_MENU_TEXT_HIDDEN_MARK, reply_markup=reply_markup)

    text = prefix + await get_setting(bot_id, "home_menu_text", HOME_MENU_TEXT_DEFAULT)
    # === PATCH_HOME_BACK_WELCOME_V1 ===
    # درخواستِ ادمین: در منوی شیشه‌ای، وقتی کاربر به صفحهٔ اصلی برمی‌گردد هم همان متنِ
    # استارت (خوش‌آمد) رویِ منو باشد، نه «به منوی اصلی بازگشتید». با دکمهٔ
    # «متنِ بازگشت به صفحهٔ اصلی» قابلِ خاموش‌شدن است (home_back_welcome=0).
    if (not prefix and isinstance(reply_markup, InlineKeyboardMarkup)
            and await get_setting(bot_id, "menu_mode", "reply") == "inline"
            and await get_setting(bot_id, "home_back_welcome", "1") != "0"):
        try:
            from types import SimpleNamespace as _NS
            _ch = getattr(msg_obj, "chat", None)
            _cbu = getattr(target, "from_user", None) if getattr(target, "message", None) is not None else None
            _u = _cbu or _NS(id=getattr(_ch, "id", 0), full_name=getattr(_ch, "full_name", "") or "",
                             first_name=getattr(_ch, "first_name", "") or "",
                             last_name=getattr(_ch, "last_name", "") or "",
                             username=getattr(_ch, "username", None))
            _w = await _resolve_welcome_text(bot_id, _u)
            if _w and len(_w) <= 4000:
                text = _w
        except Exception:
            logger.exception("ساختِ متنِ خوش‌آمد برایِ بازگشت به خانه ناموفق بود؛ متنِ عادی")
    # === PATCH_BOT_LANG_TOGGLE_V1 ===
    try:
        _tg_user = getattr(target, "from_user", None)
        if _tg_user is not None:
            from tenant.shared.translate import user_lang, translate_text
            if await user_lang(bot_id, _tg_user.id) == "en":
                text = await translate_text(bot_id, text, "en")
    except Exception:
        logger.exception("ترجمهٔ متنِ منویِ اصلی ناموفق بود؛ نسخهٔ فارسی نمایش داده می‌شود")
    if prefer_edit:
        try:
            return await msg_obj.edit_text(text, reply_markup=reply_markup)
        except Exception:
            logger.info("ویرایشِ پیام برایِ نمایشِ منوی اصلی ممکن نشد؛ پیامِ تازه "
                        "فرستاده می‌شود (bot_id=%s)", bot_id)
    return await msg_obj.answer(text, reply_markup=reply_markup)


async def set_setting(bot_id: int, key: str, value: str):
    import time as _time
    from sqlalchemy.exc import IntegrityError as _IE
    # === PATCH_SETTING_UPSERT_RACE_V1 ===
    # لاگ: «duplicate key value violates unique constraint settings_bot_id_key_key». دو پروسه (ورکر/وب) هم‌زمان
    # همان کلید را برایِ اولین‌بار می‌نوشتند؛ هر دو «نبود» می‌دیدند و دومی IntegrityError می‌خورد. حالا برنده‌نشده
    # ردیفِ موجود را به‌روز می‌کند (آخرین مقدار می‌ماند) و خطا بالا نمی‌رود.
    for _attempt in (1, 2):
        try:
            async with Session() as s:
                row = await s.scalar(select(Setting).where(Setting.bot_id == bot_id, Setting.key == key))
                if row:
                    row.value = value
                else:
                    s.add(Setting(bot_id=bot_id, key=key, value=value))
                await s.commit()
            break
        except _IE:
            if _attempt == 2:
                raise
    _SETTING_CACHE[(bot_id, key)] = (value, _time.monotonic() + _SETTING_CACHE_TTL)


# === PATCH_PURCHASE_IDEMPOTENCY_V1 ===
# «یک خرید = یک تحویل»، حتی اگر ربات روی چند ورکر اجرا شود.
#
# قفلِ درون‌حافظه‌ای (ست‌هایِ _inflight) فقط داخلِ همان پروسه کار می‌کند؛
# اگر همان ربات با چند ورکر بالا بیاید، دو تپِ کاربر می‌توانند به دو پروسهٔ
# مختلف بروند و هر دو یک کانفیگ بسازند. این قفل رویِ دیتابیس است: یک ردیف
# در جدولِ settings با کلیدِ یکتا (UniqueConstraint روی bot_id+key) درج
# می‌شود؛ درجِ دوم قطعاً IntegrityError می‌دهد، پس فقط یکی برنده است.
#
# کلید شاملِ شناسهٔ همان پیامِ پیش‌فاکتور است، نه فقط مشخصاتِ پلن — وگرنه
# خریدِ دومِ *واقعیِ* کاربر از همان پلن هم مسدود می‌شد.
# چرا ۳ دقیقه و نه بیشتر: اگر خرید به هر دلیلی *انجام نشود* (موجودی کم،
# پلنِ حذف‌شده، خطای پنل) قفل باید خودش آزاد شود، وگرنه کاربر بعد از شارژِ
# کیف پول با همان دکمه پیامِ «قبلاً ثبت شده» می‌گیرد و گیر می‌کند. تپ‌هایِ
# تکراری در فاصلهٔ چند ثانیه رخ می‌دهند، پس ۳ دقیقه برایِ گرفتنشان کافی است
# و تحویلِ موفق هم خیلی زودتر از این تمام می‌شود.
_PURCHASE_CLAIM_TTL = 180
_PURCHASE_CLAIM_KEEP = 7 * 86400  # ردیف‌های قدیمی‌تر از یک هفته پاک می‌شوند


def _purchase_claim_key(raw: str) -> str:
    import hashlib
    return "buyclaim:" + hashlib.sha1(raw.encode("utf-8")).hexdigest()[:40]


async def claim_purchase_once(bot_id: int, raw: str) -> bool:
    """اگر True برگرداند، این اجرا حقِ تحویل دارد؛ False یعنی تکراری است."""
    from sqlalchemy.exc import IntegrityError
    key = _purchase_claim_key(raw)
    now = time.time()
    async with Session() as s:
        s.add(Setting(bot_id=bot_id, key=key, value=str(now)))
        try:
            await s.commit()
            return True
        except IntegrityError:
            await s.rollback()
    # ردیف از قبل هست: یا اجرای هم‌زمان است، یا اجرایی که وسطِ راه مرده.
    async with Session() as s:
        row = await s.scalar(select(Setting).where(
            Setting.bot_id == bot_id, Setting.key == key).with_for_update())
        if not row:
            return False
        try:
            started = float(row.value or 0)
        except ValueError:
            started = 0.0
        if now - started > _PURCHASE_CLAIM_TTL:
            # تحویلِ قبلی خیلی وقت پیش گیر کرده؛ اجازهٔ تلاشِ دوباره
            row.value = str(now)
            await s.commit()
            logger.warning("قفلِ خریدِ کهنه آزاد شد (bot_id=%s)", bot_id)
            return True
        return False


async def release_purchase_claim(bot_id: int, raw: str) -> None:
    """فقط وقتی صدا زده می‌شود که تحویل *انجام نشده* — تا کاربر بتواند دوباره
    تلاش کند. اگر تحویل موفق بود، ردیف عمداً می‌ماند."""
    key = _purchase_claim_key(raw)
    try:
        async with Session() as s:
            row = await s.scalar(select(Setting).where(
                Setting.bot_id == bot_id, Setting.key == key))
            if row:
                await s.delete(row)
                await s.commit()
    except Exception:
        logger.exception("آزادکردنِ قفلِ خرید ناموفق بود (نادیده گرفته شد)")


async def purge_old_purchase_claims(bot_id: int) -> None:
    """ردیف‌هایِ قفلِ قدیمی را پاک می‌کند تا جدولِ settings باد نکند."""
    try:
        cutoff = time.time() - _PURCHASE_CLAIM_KEEP
        async with Session() as s:
            rows = (await s.scalars(select(Setting).where(
                Setting.bot_id == bot_id,
                Setting.key.like("buyclaim:%")))).all()
            removed = 0
            for r in rows:
                try:
                    if float(r.value or 0) < cutoff:
                        await s.delete(r)
                        removed += 1
                except ValueError:
                    continue
            if removed:
                await s.commit()
    except Exception:
        logger.exception("پاک‌سازیِ قفل‌هایِ قدیمیِ خرید ناموفق بود")


# === PATCH_PAYER_IDENTITY_V1 ===
# آیدیِ عددیِ تلگرامِ خودِ هر ربات (بخشِ قبل از «:» در توکن) — برایِ نگهبانِ زیر. کشِ کوتاه‌مدت: توکن
# فقط در «تعویضِ توکن» عوض می‌شود.
_OWN_TG_ID_CACHE: dict[int, tuple[float, int | None]] = {}
_OWN_TG_ID_TTL_S = 600.0


async def _bot_own_tg_id(bot_id: int) -> int | None:
    import time as _t
    hit = _OWN_TG_ID_CACHE.get(bot_id)
    now = _t.monotonic()
    if hit is not None and (now - hit[0]) < _OWN_TG_ID_TTL_S:
        return hit[1]
    own = None
    try:
        async with Session() as s:
            b = await s.get(BotRow, bot_id)
        tok = getattr(b, "token", None) or ""
        head = tok.split(":", 1)[0]
        own = int(head) if head.isdigit() else None
    except Exception:
        logger.exception("خواندنِ آیدیِ خودِ ربات ناموفق بود (نگهبانِ هویت غیرفعال ماند)")
    _OWN_TG_ID_CACHE[bot_id] = (now, own)
    return own


async def get_or_create_user(bot_id: int, tg_id: int, full_name: str = "", username: str = "",
                              return_created: bool = False):
    from sqlalchemy.exc import IntegrityError
    # === PATCH_PAYER_IDENTITY_V1 ===
    # هیچ آپدیتِ واقعی‌ای از طرفِ خودِ ربات نمی‌آید؛ اگر tg_id برابرِ آیدیِ خودِ ربات است یعنی جایی به‌جایِ
    # کاربر، پیامِ خودِ ربات (cb.message.from_user) را داده‌اند. قبلاً این‌جا بی‌صدا یک «کاربرِ ساختگیِ ربات»
    # ساخته می‌شد و شارژ/سفارش به نامِ آن ثبت می‌شد؛ حالا خطای صریح می‌دهد تا پولِ مشتری به حسابِ اشتباه نرود.
    if tg_id and tg_id == await _bot_own_tg_id(bot_id):
        from tenant.gateways.payer_identity import PayerIdentityError
        logger.error("get_or_create_user: تلاش برایِ ساختِ کاربر با آیدیِ خودِ ربات (bot_id=%s tg=%s) — "
                     "احتمالاً cb.message به‌جایِ cb.from_user", bot_id, tg_id, stack_info=True)
        raise PayerIdentityError("کاربرِ نامعتبر (خودِ ربات)")
    async with Session() as s:
        u = await s.scalar(select(BotUser).where(BotUser.bot_id == bot_id, BotUser.telegram_id == tg_id))
        was_created = u is None
        if u is None:
            u = BotUser(bot_id=bot_id, telegram_id=tg_id, full_name=full_name, username=username)
            s.add(u)
            try:
                await s.commit()
            except IntegrityError:
                # === PATCH_RACE_SAFE_USER_V1 ===
                # وبهوکِ تلگرام گاهی همان آپدیت را دوباره می‌فرستد (بعد از تایم‌اوت)؛
                # اگر دو درخواستِ هم‌زمان هر دو تلاش کنند این کاربر را بسازند، یکی با
                # خطای UNIQUE مواجه می‌شود. در این حالت فقط ردیفِ ساخته‌شده توسط
                # درخواستِ دیگر را می‌خوانیم، بدون کرش کردنِ کل هندلر.
                await s.rollback()
                was_created = False
            async with Session() as s2:
                u = await s2.scalar(select(BotUser).where(BotUser.bot_id == bot_id, BotUser.telegram_id == tg_id))
    # === PATCH_BLOCKED_USERS_V1 ===
    # اگر کاربری که قبلاً «بلاک‌کننده» علامت خورده بود دوباره با ربات تعامل
    # کرد، یعنی آنبلاک کرده — پس علامت را برمی‌داریم تا لیستِ بلاک‌کننده‌ها
    # کهنه و گمراه‌کننده نماند.
    if u is not None and getattr(u, "is_blocked", False):
        await mark_blocked(bot_id, tg_id, False)
    # === PATCH_USER_PROFILE_REFRESH_V1 ===
    # اگر کاربر نام یا یوزرنیمش را عوض کرده، با اولین تعاملِ بعدی در ربات هم به‌روز می‌شود
    # (قبلاً فقط موقعِ ساختِ اولیه ذخیره می‌شد؛ یوزرنیمِ کهنه جستجو/مدیریتِ کاربر را خراب می‌کرد).
    # فقط وقتی نامِ واقعی آمده باشد (full_name خالی = فراخوانی بدونِ اطلاعاتِ پروفایل).
    if u is not None and not was_created and full_name:
        _new_un = (username or "").lstrip("@") or None
        if (u.full_name or "") != full_name or (u.username or None) != _new_un:
            try:
                async with Session() as s_up:
                    _bu = await s_up.get(BotUser, u.id)
                    if _bu is not None:
                        _bu.full_name = full_name[:120]
                        _bu.username = _new_un
                        await s_up.commit()
                        u = _bu
            except Exception:
                logger.exception("به‌روزرسانیِ نام/یوزرنیمِ کاربر ناموفق بود (bot=%s tg=%s)", bot_id, tg_id)
    if return_created:
        return u, was_created
    return u


# === PATCH_BAN_ONLY_MAIN_ADMIN_EXEMPT_V1 ===
# فقط «ادمینِ اصلیِ پلتفرم» بن‌ناپذیر است؛ مالک، ادمین‌هایِ ربات و ادمین‌هایِ رباتِ همکار
# مثلِ هر کاربرِ دیگری بن می‌شوند.
def _is_platform_admin(tg_id: int) -> bool:
    from config import PLATFORM_ADMIN_ID as _PA
    return bool(_PA) and int(tg_id) == int(_PA)


async def is_owner_or_admin(bot_id: int, tg_id: int, owner_id: int) -> bool:
    if tg_id == owner_id:
        return True
    async with Session() as s:
        adm = await s.scalar(select(AdminSupport).where(
            AdminSupport.bot_id == bot_id, AdminSupport.telegram_id == tg_id))
    if adm is None:
        return False
    # === PATCH_ADMIN_PANEL_ADD_ONLY_V1 ===
    # ادمینِ «فقط اتصالِ پنلِ جدید» فقط در همان مراحلِ مجازِ ثبتِ پنل ادمین
    # حساب می‌شود (میان‌افزارِ _addonly_mw این را برایِ همان آپدیت علامت
    # می‌زند)؛ در هر جایِ دیگر — هر دکمه، هر متن، هر کال‌بکِ دست‌ساز — مثلِ
    # کاربرِ عادی است. این‌طوری بدونِ فهرست‌کردنِ تک‌تکِ بخش‌ها، هیچ مسیرِ
    # مدیریتیِ دیگری (پلن‌ها، قیمت‌ها، پنل‌هایِ قبلی، مالی) برایش باز نیست.
    if _perms_is_addonly(adm.permissions):
        return _ADDONLY_ALLOW.get() == (bot_id, tg_id)
    return True


async def is_staff_member(bot_id: int, tg_id: int, owner_id: int) -> bool:
    """فقط «آیا جزوِ کادرِ این ربات است» (برایِ نمایشِ دکمهٔ پنل مدیریت)؛
    برخلافِ is_owner_or_admin دسترسی نمی‌دهد."""
    if tg_id == owner_id:
        return True
    async with Session() as s:
        adm = await s.scalar(select(AdminSupport.id).where(
            AdminSupport.bot_id == bot_id, AdminSupport.telegram_id == tg_id))
    return adm is not None


# === PATCH_ADMIN_PANEL_ADD_ONLY_V1 ===
import contextvars as _contextvars

ADDONLY_PERM = "panel_add"
_ADDONLY_ALLOW: "_contextvars.ContextVar[tuple[int, int] | None]" = _contextvars.ContextVar(
    "addonly_allow", default=None)
# bot_id -> (زمان, {telegram_id: مجموعهٔ دسترسی‌ها یا None=کامل})
_STAFF_PERMS_CACHE: dict[int, tuple[float, dict]] = {}
_STAFF_PERMS_TTL = 20.0


def _parse_perms(raw: str | None) -> set | None:
    raw = (raw or "").strip()
    if not raw:
        return None
    try:
        return set(json.loads(raw) or [])
    except Exception:
        return None


def _perms_is_addonly(raw: str | None) -> bool:
    return _parse_perms(raw) == {ADDONLY_PERM}


async def _staff_perms_map(bot_id: int) -> dict:
    now = time.monotonic()
    c = _STAFF_PERMS_CACHE.get(bot_id)
    if c and now - c[0] < _STAFF_PERMS_TTL:
        return c[1]
    async with Session() as s:
        adms = (await s.scalars(select(AdminSupport).where(AdminSupport.bot_id == bot_id))).all()
    m = {a.telegram_id: _parse_perms(a.permissions) for a in adms}
    _STAFF_PERMS_CACHE[bot_id] = (now, m)
    return m


def _invalidate_staff_perms(bot_id: int) -> None:
    _STAFF_PERMS_CACHE.pop(bot_id, None)


# === PATCH_ADMIN_GRANULAR_PERMS_V1 ===
# دسترسیِ تک‌تکِ بخش‌هایِ پنلِ ادمین برایِ ادمین‌هایِ فرعیِ ربات‌هایِ
# مستأجر. اونر همیشه دسترسیِ کامل داره؛ ادمینِ فرعی با permissions
# خالی هم (سازگاریِ قدیمی) دسترسیِ کامل داره؛ وگرنه فقط بخش‌هایِ
# ذخیره‌شده در permissions مجازه.
_ADMIN_SECTIONS = {
    "products": "📦 سرویس‌ها و محصولات",
    "settings": "🎛 دکمه‌ها و تنظیمات",
    "admins": "👮 ادمین‌ها و پشتیبانی",
    "finance": "💰 مالی و کیف پول",
    "stats": "📊 آمار و گزارشات",
}


async def _admin_permission_set(bot_id: int, tg_id: int, owner_id: int) -> set | None:
    """None یعنی «دسترسیِ کامل» (اونر، یا ادمینِ فرعیِ بدونِ محدودیت).
    وگرنه مجموعه‌ای از کلیدهایِ _ADMIN_SECTIONS که این کاربر بهشون
    دسترسی داره برمی‌گرده (ممکنه خالی باشه = هیچ بخشی)."""
    if tg_id == owner_id:
        return None
    async with Session() as s:
        adm = await s.scalar(select(AdminSupport).where(
            AdminSupport.bot_id == bot_id, AdminSupport.telegram_id == tg_id))
    if not adm:
        return set()  # اصلاً ادمین نیست
    raw = (adm.permissions or "").strip()
    if not raw:
        return None  # سازگاریِ قدیمی: بدونِ محدودیتِ ثبت‌شده = دسترسیِ کامل
    try:
        return set(json.loads(raw))
    except Exception:
        return None


async def _has_section_access(bot_id: int, tg_id: int, owner_id: int, section: str) -> bool:
    perms = await _admin_permission_set(bot_id, tg_id, owner_id)
    if perms is None:
        return True
    return section in perms


async def _section_ok(cb: CallbackQuery, bot: Bot, section: str) -> "BotRow | None":
    """مثلِ _owner_ok، بعلاوهٔ چک‌کردنِ دسترسیِ ادمینِ فرعی به این بخشِ خاص."""
    row = await get_bot_row(bot)
    if not row:
        await cb.answer()
        return None
    if not await is_owner_or_admin(row.id, cb.from_user.id, row.owner_id):
        await cb.answer()
        return None
    if not await _has_section_access(row.id, cb.from_user.id, row.owner_id, section):
        await cb.answer("⛔️ دسترسی به این بخش برای شما محدود شده.", show_alert=True)
        return None
    return row


def _fj_broken_reason(e: Exception) -> str:
    """=== PATCH_FJ_REAL_ERROR_V1 === دلیلِ ⚠️ را از خطای واقعیِ تلگرام می‌سازد؛ قبلاً هر خطا «ربات ادمین نیست» نوشته می‌شد
    (حتی «chat not found» برایِ یوزرنیمِ عوض‌شده یا «user not found»)."""
    m = str(e).lower()
    if "chat not found" in m:
        return "کانال/گروه پیدا نشد (یوزرنیم عوض شده یا ربات از آن حذف شده؛ کانال را حذف و دوباره اضافه کن)"
    if "member list is inaccessible" in m or "chat_admin_required" in m or "not enough rights" in m:
        return "ربات ادمینِ این کانال/گروه نیست یا دسترسیِ دیدنِ اعضا ندارد"
    if "user not found" in m or "participant_id_invalid" in m or "user_id_invalid" in m:
        return "تلگرام این کاربر را پیدا نکرد (مشکلِ همین کاربر است، نه کانال)"
    if "forbidden" in m or "kicked" in m:
        return "ربات از این کانال/گروه بیرون انداخته شده یا مسدود است"
    return "خطای تلگرام: " + str(e).replace("Bad Request: ", "")[:90]


async def check_force_join(bot: Bot, bot_id: int, user_id: int, bypass_cache: bool = False) -> list[dict]:
    """لیست کانال‌هایی که کاربر هنوز عضو نشده.

    bypass_cache: PATCH_FORCEJOIN_START_FRESH_CHECK_V1 — اگه True باشه، کشِ
    ۹۰ثانیه‌ای نادیده گرفته می‌شود و همهٔ کانال‌ها زنده چک می‌شوند. برایِ
    /start استفاده می‌شود (کمیاب است، نه پرتکرار مثلِ تپ‌زدنِ دکمه) تا
    کاربری که همین الان از کانال خارج شده، بلافاصله با /start دوباره درست
    تشخیص داده شود — قبلاً اگه ظرفِ همون ۹۰ ثانیه دوباره /start می‌زد، هنوز
    از رویِ نتیجهٔ کش‌شدهٔ قدیمی «عضو است» رد می‌شد.
    """
    async with Session() as s:
        fjs = (await s.scalars(
            select(ForceJoin).where(ForceJoin.bot_id == bot_id, ForceJoin.is_active == True)
        )).all()
        bot_row = await s.scalar(select(BotRow).where(BotRow.id == bot_id))
    # ادمین و اونر از بررسی عضویت معاف هستند
    # === PATCH_FJ_TEST_MODE_V1 === (محمد، رباتِ قرعه‌کشی: «اصلاً کار نمی‌کند») مالک با حسابِ خودش تست می‌کرد و چون معاف است
    # هیچ‌وقت صفحهٔ عضویت را نمی‌دید؛ «حالتِ تست» این معافیت را برایِ خودِ مالک/ادمین برمی‌دارد.
    if bot_row and await is_owner_or_admin(bot_id, user_id, bot_row.owner_id):
        if (await get_setting(bot_id, "fj_test_mode", "0")) != "1":
            return []
    if not fjs:
        return []
    # === PATCH_FORCEJOIN_PARALLEL_CACHE_V1 ===
    # قبلاً این چک روی *هر* تکِ تپِ دکمه (mbtn_tap) اجرا می‌شد و برای هر کانال
    # یک درخواستِ get_chat_member جداگانه و پشتِ‌سرهم به تلگرام می‌زد — با
    # چند کانال، این خودش می‌تونست ۱-۲ ثانیه طول بکشه، قبل از اینکه اصلاً به
    # cb.answer() برسیم (علتِ اصلیِ خطای «query is too old»). حالا: (۱) نتیجهٔ
    # هر (bot_id, user_id, chat_id) به مدت ۹۰ ثانیه کش می‌شود — کاربری که همین
    # الان عضویتش تایید شده لازم نیست با هر کلیک دوباره چک شود؛ (۲) کانال‌هایی
    # که کش ندارند، همزمان (نه پشتِ‌سرهم) چک می‌شوند.
    import time as _time
    now = _time.monotonic()
    to_check: list = []
    not_joined: list[dict] = []
    for fj in fjs:
        ck = (bot_id, user_id, fj.chat_id)
        cached = None if bypass_cache else _FORCEJOIN_CACHE.get(ck)
        if cached is not None and cached[1] > now:
            if not cached[0]:
                not_joined.append({"chat_id": fj.chat_id, "title": fj.title or fj.chat_id,
                                   "btn_color": fj.btn_color,  # PATCH_FORCEJOIN_BTN_COLOR_V1
                                   "invite_link": getattr(fj, "invite_link", None)})
        else:
            to_check.append(fj)

    async def _check_one(fj):
        # === PATCH_FORCEJOIN_UNCHECKABLE_V1 ===
        # باگِ گزارش‌شده: قبلاً *هر* خطایی به‌معنیِ «کاربر عضو نیست» گرفته
        # می‌شد. یعنی اگه ربات تویِ یکی از کانال‌هایِ عضویتِ اجباری ادمین
        # نباشه (یا کانال حذف/خصوصی شده باشه)، تلگرام خطا می‌ده و ربات
        # نتیجه می‌گیره «هیچ‌کس عضو نیست» — در نتیجه *همهٔ* کاربرها پشتِ یه
        # دیوارِ غیرقابلِ‌عبور گیر می‌کنن، چون هرچقدر هم عضو بشن باز رد نمی‌شن.
        # حالا فرق می‌ذاریم: «کاربر عضو نیست» (پاسخِ معتبرِ تلگرام) با
        # «اصلاً نمی‌تونیم چک کنیم» (خطایِ دسترسی). حالتِ دوم نادیده گرفته
        # می‌شه تا کاربرِ بی‌گناه قفل نشه، و برایِ ادمین لاگ می‌شه.
        #
        # === PATCH_FORCEJOIN_TIMEOUT_DEADLINE_V1 ===
        # باگِ عملکردی: وقتی تلگرام برایِ یک کانالِ خاص (مثلاً چون ربات
        # دیگر ادمینِ آن نیست، یا کانال مشکل دارد) تایم‌اوت می‌داد،
        # get_chat_member از مکانیزمِ سراسریِ retry رد می‌شد — ۳ تلاش، هر
        # کدام تا ۱۲ ثانیه — و کاربر تا ۵۰+ ثانیه معطلِ همین یک چکِ
        # کم‌اهمیت می‌ماند، قبل از اینکه اصلاً ربات جوابش را بدهد. برایِ
        # همینِ نوع چک («فقط عضویت را ببین»، نه یک تراکنشِ حیاتی)، منتظرِ
        # کاملِ آن retry ماندن اصلاً لازم نیست — نتیجه‌اش هرجور باشد
        # («نمی‌تونیم چک کنیم») همان است. با یک سقفِ کوتاه، همان تصمیمِ
        # درستِ بالا خیلی زودتر گرفته می‌شود.
        # === PATCH_FORCEJOIN_UNCHECKABLE_CACHE_V1 ===
        uck = (bot_id, fj.chat_id)
        _uc_until = None if bypass_cache else _FORCEJOIN_UNCHECKABLE_CACHE.get(uck)  # PATCH_FORCEJOIN_CHECK_FRESH_V1
        if _uc_until is not None and _uc_until > now:
            return  # این کانال به‌تازگی «غیرقابلِ‌بررسی» تشخیص داده شده — دوباره از تلگرام نمی‌پرسیم
        try:
            member = await asyncio.wait_for(
                bot.get_chat_member(fj.chat_id, user_id), timeout=5.0)
            joined = member.status not in ("left", "kicked")
            _FORCEJOIN_BROKEN.pop(uck, None)  # PATCH_FORCEJOIN_HEALTH_V1 — دوباره سالم شد
        except asyncio.TimeoutError:
            logger.warning(
                "force-join: کانال %s ظرفِ ۵ ثانیه پاسخ نداد (بدونِ صبر برایِ "
                "تلاشِ مجددِ کامل) — نادیده گرفته شد تا کاربر قفل نشه.", fj.chat_id)
            _FORCEJOIN_UNCHECKABLE_CACHE[uck] = _time.monotonic() + _FORCEJOIN_UNCHECKABLE_TTL  # PATCH_FORCEJOIN_UNCHECKABLE_CACHE_V1
            _FORCEJOIN_BROKEN[uck] = "پاسخ نداد (تایم‌اوت)"  # PATCH_FORCEJOIN_HEALTH_V1
            return
        except (TelegramBadRequest, TelegramForbiddenError) as e:
            logger.warning(
                "force-join: کانال %s قابلِ بررسی نیست (ربات ادمین نیست؟) — "
                "نادیده گرفته شد تا کاربر قفل نشه. جزئیات: %s", fj.chat_id, e)
            _FORCEJOIN_UNCHECKABLE_CACHE[uck] = _time.monotonic() + _FORCEJOIN_UNCHECKABLE_TTL  # PATCH_FORCEJOIN_UNCHECKABLE_CACHE_V1
            _FORCEJOIN_BROKEN[uck] = _fj_broken_reason(e)  # PATCH_FORCEJOIN_HEALTH_V1 (+ خطای واقعیِ تلگرام)
            return
        except Exception:
            logger.exception("force-join: خطای غیرمنتظره در بررسیِ کانال %s", fj.chat_id)
            _FORCEJOIN_UNCHECKABLE_CACHE[uck] = _time.monotonic() + _FORCEJOIN_UNCHECKABLE_TTL  # PATCH_FORCEJOIN_UNCHECKABLE_CACHE_V1
            _FORCEJOIN_BROKEN[uck] = "خطای نامشخص در بررسی"  # PATCH_FORCEJOIN_HEALTH_V1
            return
        if joined:
            # فقط نتیجهٔ «عضو است» کش می‌شود — نتیجهٔ «عضو نیست» هرگز کش
            # نمی‌شود، چون دکمهٔ «fj:check» (بررسیِ مجدد بعدِ عضویت) باید
            # همیشه نتیجهٔ تازه بگیرد؛ وگرنه کاربری که تازه عضو شده ممکن است
            # با نتیجهٔ کهنهٔ «هنوز عضو نشدی» مواجه شود.
            _FORCEJOIN_CACHE[(bot_id, user_id, fj.chat_id)] = (True, _time.monotonic() + _FORCEJOIN_CACHE_TTL)
        else:
            not_joined.append({"chat_id": fj.chat_id, "title": fj.title or fj.chat_id,
                               "btn_color": fj.btn_color,  # PATCH_FORCEJOIN_COLOR_LIVE_V1
                               "invite_link": getattr(fj, "invite_link", None)})

    if to_check:
        await asyncio.gather(*(_check_one(fj) for fj in to_check))
    return not_joined


_FORCEJOIN_CACHE: dict[tuple[int, int, object], tuple[bool, float]] = {}
_FORCEJOIN_CACHE_TTL = 30.0  # ثانیه — PATCH_FORCEJOIN_FASTER_RECHECK_V1 (بود ۹۰): خروج از کانال زودتر تشخیص داده شود

# === PATCH_FORCEJOIN_UNCHECKABLE_CACHE_V1 ===
# کشِ کانال‌هایی که بررسیِ عضویت‌شان شکست می‌خورد (ربات ادمین نیست، کانال
# حذف/خصوصی شده، یا تایم‌اوت). بر اساسِ (bot_id, chat_id) است، نه کاربر —
# چون این یک مشکلِ ساختاریِ کانال است و برایِ همهٔ کاربرها یکسان است.
_FORCEJOIN_UNCHECKABLE_CACHE: dict[tuple[int, object], float] = {}
_FORCEJOIN_UNCHECKABLE_TTL = 300.0  # ثانیه — ۵ دقیقه

# === PATCH_FORCEJOIN_HEALTH_V1 ===
# دلیلِ خرابیِ هر کانال، برایِ نمایش در پنلِ مالک. باگِ اصلیِ گزارش‌شده این
# بود که وقتی ربات ادمینِ کانال نیست، عضویتِ اجباری «بی‌صدا» از کار می‌افتد
# (fail-open، تا کاربرِ بی‌گناه قفل نشود) و مالک هیچ‌وقت نمی‌فهمد چرا گیتش
# کار نمی‌کند — فقط می‌بیند همه بدونِ عضویت رد می‌شوند. حالا در همان صفحهٔ
# «عضویت اجباری» با ⚠️ و دلیلش نشان داده می‌شود.
_FORCEJOIN_BROKEN: dict[tuple[int, object], str] = {}


# ======================= آنتی‌اسپم (فلود پیام) — ربات‌های مستأجر =======================
# اگر کاربری در یک ربات مستأجر ۱۰ پیام پشت‌سرهم (در بازهٔ کوتاه) بفرستد،
# یک «فلود» شمرده می‌شود: بار اول و دوم فقط اخطار می‌گیرد، بار سوم به‌طور
# خودکار از همان ربات بن می‌شود. این تنظیم و لیستِ بن‌شده‌ها per-bot است.
_TN_ANTISPAM_WINDOW_SECONDS = 8
_TN_ANTISPAM_MSG_THRESHOLD = 15      # PATCH_ANTISPAM_TEMP_LOCK_V1: پیش‌فرض ۱۰ → ۱۵ (پیشنهاد #147)
_TN_ANTISPAM_MAX_WARNINGS = 2
# === PATCH_ANTISPAM_TEMP_LOCK_V1 ===
# پیشنهاد #147 (Sajad): آنتی‌اسپم کاربر را «بن» نکند؛ به‌جایِ آن ۱۰ تا ۲۰ دقیقه دسترسی‌اش را بگیرد و بعد
# خودکار پس بدهد، و آستانه ۱۵ پیام باشد. حالتِ پیش‌فرض حالا «قفلِ موقت» است؛ مالک می‌تواند به «بنِ دائمی»
# (رفتارِ قبلی) برگردد. آستانه (۱۰/۱۵/۲۰) و مدتِ قفل (۱۰/۱۵/۲۰ دقیقه) هم قابلِ تنظیم است.
_tn_antispam_locks: dict[tuple[int, int], float] = {}   # (bot_id, telegram_id) -> زمانِ پایانِ قفل (monotonic)
_tn_antispam_lockmsg: dict[tuple[int, int], float] = {}  # آخرین باری که پیامِ «هنوز قفل است» فرستادیم
_ANTISPAM_THRESHOLDS = (10, 15, 20)
_ANTISPAM_LOCK_MINUTES = (10, 15, 20)


async def _antispam_cfg(bot_id: int) -> tuple[int, str, int]:
    """(آستانهٔ پیام، حالت temp|ban، مدتِ قفل به دقیقه)"""
    try:
        thr = int(await get_setting(bot_id, "antispam_threshold", str(_TN_ANTISPAM_MSG_THRESHOLD)))
    except ValueError:
        thr = _TN_ANTISPAM_MSG_THRESHOLD
    mode = (await get_setting(bot_id, "antispam_mode", "temp")) or "temp"
    try:
        mins = int(await get_setting(bot_id, "antispam_lock_min", "15"))
    except ValueError:
        mins = 15
    return max(3, min(thr, 100)), ("ban" if mode == "ban" else "temp"), max(1, min(mins, 120))


def _antispam_lock_left(bot_id: int, uid: int) -> int:
    """ثانیه‌هایِ باقی‌ماندهٔ قفل؛ ۰ یعنی قفل نیست."""
    key = (bot_id, uid)
    until = _tn_antispam_locks.get(key)
    if until is None:
        return 0
    left = until - time.monotonic()
    if left <= 0:
        _tn_antispam_locks.pop(key, None)
        _tn_antispam_lockmsg.pop(key, None)
        return 0
    return int(left) + 1

_tn_antispam_times: dict[tuple[int, int], deque] = {}      # (bot_id, telegram_id) -> زمانِ پیام‌ها
_tn_antispam_cooldown: dict[tuple[int, int], float] = {}   # جلوگیری از شمارشِ یک فلودِ واحد به چند incident


@tenant_router.message.outer_middleware
async def tenant_antispam_mw(handler, event, data):
    u = getattr(event, "from_user", None)
    if not u:
        return await handler(event, data)
    # === PATCH_COMMUNITY_GROUP_ANTISPAM_EXEMPT_V1 ===
    # باگِ گزارش‌شده: ادمینی که داشت رویِ گروهِ متصل‌شده به رباتِ «مدیریتِ
    # گروه و کانال» چندین دستورِ متوالیِ بن/اخطار/سکوت را تست می‌کرد
    # (که برایِ این نوع ربات کاملاً طبیعی و مورداستفاده‌ی اصلی است، نه
    # اسپم)، توسطِ همین میان‌افزار — که برایِ محافظت از پیام‌خصوصیِ ربات
    # در برابرِ مشتریِ اسپم‌کننده طراحی شده بود — به‌اشتباه به‌عنوانِ اسپمر
    # شناسایی و خودکار بن شد (BotUser.is_banned=True). از آن لحظه، هر
    # پیامی که به این ربات می‌فرستاد — از جمله دستورهایِ مدیریتیِ گروه —
    # بی‌صدا نادیده گرفته می‌شد (پایین‌تر: «if bu and bu.is_banned: return»).
    # این میان‌افزار برایِ پیام‌هایِ خصوصی به ربات ساخته شده، نه برایِ
    # فعالیتِ طبیعیِ ادمینِ گروه؛ community.py خودش یک لایهٔ ضداسپمِ
    # مخصوصِ گروه دارد (_antispam_check) که مکانیزمِ درستِ همین کار است.
    chat_type = getattr(getattr(event, "chat", None), "type", None)
    if chat_type in ("group", "supergroup"):
        bot_for_field = data.get("bot") or event.bot
        row_for_field = await get_bot_row(bot_for_field)
        if row_for_field and row_for_field.field == "community_mgmt":
            return await handler(event, data)
    # کاربری که وسطِ یک فرمِ چندمرحله‌ای (مثل افزودن کانفیگ) است هرگز آنتی‌اسپم
    # نخورد؛ فرستادنِ چند پیامِ سریع پشتِ‌هم در یک ویزارد کاملاً طبیعی است.
    fsm_state = data.get("state")
    if fsm_state is not None:
        try:
            if await fsm_state.get_state() is not None:
                # === PATCH_ANTISPAM_TEMP_LOCK_V1 === کاربرِ قفل‌شده با ویزارد هم دورِ قفل را نزند
                _lk = False
                if _tn_antispam_locks:
                    _rw = await get_bot_row(data.get("bot") or event.bot)
                    _lk = bool(_rw and _antispam_lock_left(_rw.id, u.id))
                if not _lk:
                    return await handler(event, data)
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    bot = data.get("bot") or event.bot
    row = await get_bot_row(bot)
    if not row:
        return await handler(event, data)
    # اونر و ادمین‌های همین ربات از آنتی‌اسپم معافند
    if await is_owner_or_admin(row.id, u.id, row.owner_id) or _is_platform_admin(u.id):
        return await handler(event, data)

    # === PATCH_ANTISPAM_TEMP_LOCK_V1 === قفلِ موقت: پیام‌ها نادیده؛ حداکثر دقیقه‌ای یک‌بار زمانِ باقی‌مانده را بگو
    _left = _antispam_lock_left(row.id, u.id)
    if _left:
        _k = (row.id, u.id)
        _now = time.monotonic()
        if _now - _tn_antispam_lockmsg.get(_k, float("-inf")) > 60:
            _tn_antispam_lockmsg[_k] = _now
            try:
                await event.answer(f"⏳ دسترسی‌ات به این ربات موقتاً محدود است؛ حدود {max(1, _left // 60)} دقیقهٔ دیگر "
                                   "خودکار فعال می‌شود.")
            except Exception:
                logger.debug("پیامِ قفلِ موقت ارسال نشد (بی‌اهمیت)")
        return

    async with Session() as s:
        bu = await s.scalar(select(BotUser).where(BotUser.bot_id == row.id, BotUser.telegram_id == u.id))
    if bu and bu.is_banned:
        return  # کاربرِ بن‌شده در همین ربات؛ کاملاً نادیده گرفته می‌شود

    if (await get_setting(row.id, "antispam_enabled", "on")) == "on":
        key = (row.id, u.id)
        now = time.monotonic()
        _thr, _mode, _lock_min = await _antispam_cfg(row.id)
        dq = _tn_antispam_times.setdefault(key, deque())
        dq.append(now)
        while dq and now - dq[0] > _TN_ANTISPAM_WINDOW_SECONDS:
            dq.popleft()

        if len(dq) >= _thr:
            last_trigger = _tn_antispam_cooldown.get(key, float("-inf"))
            if now - last_trigger > _TN_ANTISPAM_WINDOW_SECONDS:
                _tn_antispam_cooldown[key] = now
                dq.clear()
                will_ban = False
                new_warnings = 0
                async with Session() as s:
                    bu2 = await s.scalar(
                        select(BotUser).where(BotUser.bot_id == row.id, BotUser.telegram_id == u.id))
                    if not bu2:
                        bu2 = BotUser(bot_id=row.id, telegram_id=u.id,
                                     full_name=u.full_name or "", username=u.username or "")
                        s.add(bu2)
                        await s.flush()
                    new_warnings = (bu2.spam_warnings or 0) + 1
                    bu2.spam_warnings = new_warnings
                    will_ban = new_warnings > _TN_ANTISPAM_MAX_WARNINGS
                    if will_ban and _mode == "ban":
                        bu2.is_banned = True
                    elif will_ban:
                        bu2.spam_warnings = 0   # بعد از قفلِ موقت از اخطارِ اول شروع می‌شود
                    await s.commit()
                if will_ban and _mode == "temp":
                    _tn_antispam_locks[key] = time.monotonic() + _lock_min * 60
                    _tn_antispam_lockmsg[key] = time.monotonic()
                    await event.answer(
                        f"⏳ به‌دلیل ارسالِ بیش‌ازحدِ پیام، دسترسی‌ات به این ربات {_lock_min} دقیقه محدود شد.\n"
                        "بعد از آن خودکار فعال می‌شود؛ بدونِ مسدودی.")
                elif will_ban:
                    await event.answer(
                        "🚫 به‌دلیل ارسال بیش‌ازحدِ پیام (اسپم)، دسترسی‌ات به این ربات مسدود شد.\n"
                        "برای رفعِ مسدودی با پشتیبانیِ ربات تماس بگیر.")
                else:
                    await event.answer(
                        f"⚠️ اخطار {new_warnings}/{_TN_ANTISPAM_MAX_WARNINGS}: لطفاً پیام‌های پشت‌سرهم و زیاد نفرست.\n"
                        + ("در صورت تکرار، دسترسی‌ات چند دقیقه محدود می‌شود." if _mode == "temp"
                           else "در صورت تکرار، دسترسی‌ات به این ربات مسدود خواهد شد."))
                return
    return await handler(event, data)


# === PATCH_ANTISPAM_TEMP_LOCK_V1 === کاربرِ قفل‌شده با دکمه‌ها هم نباید کاری بکند
@tenant_router.callback_query.outer_middleware
async def tenant_antispam_lock_cb_mw(handler, event, data):
    u = getattr(event, "from_user", None)
    if u and _tn_antispam_locks:
        bot = data.get("bot") or event.bot
        row = await get_bot_row(bot)
        if row:
            left = _antispam_lock_left(row.id, u.id)
            if left and not (await is_owner_or_admin(row.id, u.id, row.owner_id) or _is_platform_admin(u.id)):
                try:
                    await event.answer(f"⏳ دسترسی‌ات موقتاً محدود است؛ حدود {max(1, left // 60)} دقیقهٔ دیگر فعال می‌شود.",
                                       show_alert=True)
                except Exception:
                    logger.debug("پاسخِ قفلِ موقت به دکمه ممکن نشد (بی‌اهمیت)")
                return
    return await handler(event, data)


# === PATCH_KYC_LOCK_V1 === کاربرِ «محدودشده» (kyc_blocked) در کلِ ربات — نه فقط شارژ — بسته است
@tenant_router.message.outer_middleware
async def tenant_kyc_lock_msg_mw(handler, event, data):
    u = getattr(event, "from_user", None)
    if not u or u.is_bot:
        return await handler(event, data)
    from tenant.shared import kyc_lock as _kl
    bot = data.get("bot") or event.bot
    row = await get_bot_row(bot)
    if not row or not await _kl.is_locked(row.id, u.id):
        return await handler(event, data)
    if await is_owner_or_admin(row.id, u.id, row.owner_id) or _is_platform_admin(u.id):
        return await handler(event, data)
    fsm = data.get("state")
    st = await fsm.get_state() if fsm is not None else None
    if not await _kl.message_gate(event, row.id, st):
        return
    return await handler(event, data)


@tenant_router.callback_query.outer_middleware
async def tenant_kyc_lock_cb_mw(handler, event, data):
    u = getattr(event, "from_user", None)
    if not u:
        return await handler(event, data)
    from tenant.shared import kyc_lock as _kl
    bot = data.get("bot") or event.bot
    row = await get_bot_row(bot)
    if not row or not await _kl.is_locked(row.id, u.id):
        return await handler(event, data)
    if await is_owner_or_admin(row.id, u.id, row.owner_id) or _is_platform_admin(u.id):
        return await handler(event, data)
    if not await _kl.callback_gate(event, row.id):
        return
    return await handler(event, data)


async def force_join_msg(bot: Bot, msg: Message, not_joined: list[dict]):
    # === PATCH_FORCEJOIN_BTN_COLOR_V1 ===
    row_pre = await get_bot_row(bot)
    _fj_colored = bool(row_pre) and has_feature(row_pre.plan, Feature.FORCE_JOIN_COLOR)
    rows = []
    for ch in not_joined:
        cid = ch["chat_id"]
        title = ch["title"]
        invite = ch.get("invite_link")
        # === PATCH_FORCEJOIN_LINK_FIX_V1 ===
        # باگ: قبلاً برایِ کانالِ خصوصی از `str(cid).lstrip('-100')` استفاده
        # می‌شد. `lstrip` یک *مجموعه کاراکتر* حذف می‌کند نه یک پیشوند — پس
        # برایِ -1001234567890 علاوه بر «-100»، رقمِ «1»ِ بعدی را هم می‌خورد و
        # لینکِ خراب t.me/c/234567890 ساخته می‌شد. کاربر روی دکمه می‌زد و به
        # هیچ‌جا نمی‌رسید، ولی همچنان پشتِ عضویتِ اجباری گیر بود. حالا پیشوند
        # دقیق برداشته می‌شود، و اگر هیچ لینکِ قابلِ‌استفاده‌ای نداریم (کانالِ
        # خصوصی بدونِ لینکِ دعوت) به‌جایِ فرستادنِ کاربر به یک آدرسِ اشتباه،
        # دکمه بدونِ لینک نشان داده می‌شود.
        cid_s = str(cid)
        if invite:
            link = invite
        elif cid_s.startswith("@"):
            link = f"https://t.me/{cid_s[1:]}"
        elif cid_s.startswith("-100"):
            link = f"https://t.me/c/{cid_s[4:]}"
        else:
            link = None
        # === PATCH_FORCEJOIN_BTN_COLOR_V1 ===
        # رنگِ اختصاصیِ همین کانال (فقط پلنِ حرفه‌ای). اگر مالک رنگی انتخاب
        # نکرده باشد، دکمه مثلِ قبل بی‌رنگ می‌ماند.
        _st = _IBTN_COLOR_STYLE.get(ch.get("btn_color") or "") if _fj_colored else None
        _kw = {"text": f"📢 {title}"}
        if _st:
            _kw["style"] = _st
        if link:
            _kw["url"] = link
        else:
            _kw["callback_data"] = "noop"
        rows.append([InlineKeyboardButton(**_kw)])
    _joined_st = (_IBTN_COLOR_STYLE.get(
        await get_setting(row_pre.id, "fj_joined_color", "success") or "") if _fj_colored else None)
    _jkw = {"text": "✅ عضو شدم", "callback_data": "fj:check"}
    if _joined_st:
        _jkw["style"] = _joined_st
    rows.append([InlineKeyboardButton(**_jkw)])
    row = row_pre
    custom_text = await get_setting(row.id, "force_join_text", "") if row else ""
    await msg.answer(
        custom_text or "⚠️ برای استفاده از ربات باید در کانال‌های زیر عضو باشید:",
        reply_markup=InlineKeyboardMarkup(inline_keyboard=rows), parse_mode="HTML"
    )


# ═══════════════════ PATCH_PHONE_VERIFY_V1 ═══════════════════
# تاییدِ شماره‌همراه — ضدِ رفرالِ فیک. اگه ادمین فعالش کرده باشه، هر
# کاربرِ جدید (غیر از اونر/ادمینِ خودِ ربات) بعدِ عضویتِ اجباری، مجبوره
# شماره‌شو با دکمهٔ اشتراک‌گذاریِ مخاطبِ خودِ تلگرام (نه تایپِ دستی — که
# قابلِ‌جعله) تایید کنه. فقط شماره‌هایِ ایران (+98) قبول می‌شه.

BTN_PHONE_VERIFY = "☎️ تایید می‌کنم شماره"


# === PATCH_FJ_PHONE_GATE_V1 ===
async def _fj_needs_phone_verify(row, user_id: int) -> bool:
    """آیا این کاربر هنوز باید شماره‌اش را تایید کند؟

    همان شرط‌هایِ tenant_phoneverify_mw، ولی قابلِ فراخوانی از داخلِ
    هندلرهایِ callback (که میدل‌ویرِ پیام به آن‌ها نمی‌رسد).
    """
    if (await get_setting(row.id, "phone_verify_enabled", "off")) != "on":
        return False
    if await is_owner_or_admin(row.id, user_id, row.owner_id):
        return False
    try:
        async with Session() as s:
            bu = await s.scalar(select(BotUser).where(
                BotUser.bot_id == row.id, BotUser.telegram_id == user_id))
    except Exception:
        # اگر خواندنِ کاربر خطا داد، *سخت‌گیرانه* عمل کن: تاییدِ شماره
        # یک گیتِ امنیتی است و در شک نباید بازش کرد.
        logger.exception("بررسیِ وضعیتِ تاییدِ شماره ناموفق بود")
        return True
    return not (bu and bu.phone_verified)


# === PATCH_PAY_PHONE_VERIFY_V1 ===
async def _pay_needs_phone(row, user_id: int) -> bool:
    """آیا قبل از پرداخت باید شماره تایید شود؟

    جدا از گیتِ سراسریِ `phone_verify_enabled` است: خیلی از مالک‌ها
    نمی‌خواهند ورودِ کاربر را سخت کنند، ولی می‌خواهند *قبل از پرداخت*
    شماره داشته باشند. پیش‌فرض خاموش.
    """
    if (await get_setting(row.id, "phone_verify_pay", "off")) != "on":
        return False
    if await is_owner_or_admin(row.id, user_id, row.owner_id):
        return False
    try:
        async with Session() as s:
            bu = await s.scalar(select(BotUser).where(
                BotUser.bot_id == row.id, BotUser.telegram_id == user_id))
    except Exception:
        logger.exception("بررسیِ شمارهٔ کاربر پیش از پرداخت ناموفق بود")
        return True
    return not (bu and bu.phone_verified)


async def pay_phone_gate(message: Message, row, user_id: int) -> bool:
    """اگر لازم بود، از کاربر شماره می‌گیرد. True یعنی جلوی پرداخت گرفته شد."""
    if not await _pay_needs_phone(row, user_id):
        return False
    kb = ReplyKeyboardMarkup(keyboard=[
        [KeyboardButton(text=BTN_PHONE_VERIFY, request_contact=True)]
    ], resize_keyboard=True)
    await message.answer(
        "📱 <b>تاییدِ شماره‌همراه پیش از پرداخت</b>\n\n"
        "برایِ ثبتِ امنِ پرداخت و اینکه در صورتِ هر مشکلی بتوانیم باهات "
        "تماس بگیریم، لازم است یک‌بار شماره‌ات را تایید کنی.\n\n"
        "روی دکمهٔ پایین بزن — خودِ تلگرام شماره را می‌فرستد، نیازی به "
        "تایپِ دستی نیست.\n\n"
        "⚠️ فقط شماره‌هایِ ایران (+۹۸) پذیرفته می‌شود.",
        reply_markup=kb)
    return True


async def _phone_verify_prompt(msg: Message) -> None:
    kb = ReplyKeyboardMarkup(keyboard=[
        [KeyboardButton(text=BTN_PHONE_VERIFY, request_contact=True)]
    ], resize_keyboard=True)
    await msg.answer(
        "📱 <b>تاییدِ شماره‌همراه</b>\n\n"
        "برایِ جلوگیری از ثبت‌نامِ تقلبی/رفرالِ فیک، لازمه شماره‌ی همراهت رو "
        "تایید کنی. روی دکمهٔ پایین بزن — خودِ تلگرام شماره‌ی ثبت‌شده رو "
        "برام می‌فرسته (نیازی به تایپِ دستی نیست).\n\n"
        "⚠️ فقط شماره‌هایِ ایران (+۹۸) قبول می‌شه.",
        reply_markup=kb)


async def _phone_verify_resume_pending(bot: Bot, row, u, state: FSMContext, telegram_id: int) -> None:
    """بعدِ تاییدِ موفقِ شماره، دقیقاً مثلِ fj:check دعوت‌هایِ نگه‌داشته‌شده
    (رفرالِ عمومی/گیتِ دسترسی) رو که به‌خاطرِ این مرحله معطل مونده بودن، ثبت می‌کنه."""
    data = await state.get_data()
    pending_ref = data.get("pending_ref_code")
    if pending_ref:
        await state.update_data(pending_ref_code=None)
        from tenant.shared.extras import handle_referral_join
        await handle_referral_join(row.id, u, pending_ref, bot)
    pending_gate = data.get("pending_gate_code")
    if pending_gate:
        await state.update_data(pending_gate_code=None)
        from tenant.shared.referral_gate import handle_gate_referral_join
        await handle_gate_referral_join(pending_gate, telegram_id)


# === PATCH_PHONE_LOG_CHANNEL_V1 ===
# مالکِ ربات می‌خواهد بداند چه کسی، کِی و با چه شماره‌ای قصدِ خرید کرده.
# آیدیِ کانالِ خصوصی در تنظیماتِ «مالی و کیف پول» ذخیره می‌شود و ربات
# باید در آن کانال ادمین باشد.
async def send_phone_log(bot: Bot, row, user, phone: str, reason: str = "") -> None:
    """ثبتِ شمارهٔ تاییدشده در کانالِ خصوصیِ مالکِ ربات (اگر تنظیم شده باشد)."""
    from partner_rules import jalali as _jalali
    chat = (await get_setting(row.id, "phone_log_chat", "")).strip()
    if not chat:
        return
    try:
        uname = f"@{user.username}" if getattr(user, "username", None) else "—"
        name = _html.escape(getattr(user, "full_name", "") or "بدون نام")
        txt = (
            "📱 <b>ثبتِ شمارهٔ کاربر</b>\n\n"
            f"👤 نام: {name}\n"
            f"🔗 یوزرنیم: {uname}\n"
            f"🆔 آیدی: <code>{user.telegram_id}</code>\n"
            f"☎️ شماره: <code>+{phone}</code>\n"
            f"🗓 تاریخ: {_jalali(_dt.datetime.now(), with_time=True)}\n"
            + (f"📌 مرحله: {reason}\n" if reason else "")
            + f"\n💰 موجودی کیف پول: {int(getattr(user, 'balance', 0) or 0):,} تومان"
        )
        await bot.send_message(chat, txt)
    except Exception:
        # نبودنِ ربات در کانال یا آیدیِ غلط نباید جلویِ خریدِ کاربر را بگیرد
        logger.exception("ارسالِ گزارشِ شماره به کانالِ خصوصی ناموفق بود (bot_id=%s)",
                         row.id)


@tenant_router.message(F.contact)
async def tenant_phone_verify_receive(msg: Message, bot: Bot, state: FSMContext):
    row = await get_bot_row(bot)
    if not row:
        return
    contact = msg.contact
    # امنیت: باید شمارهٔ خودِ همون کاربر باشه (نه یه مخاطبِ دیگه که فوروارد/ارسال کرده)
    if contact.user_id and contact.user_id != msg.from_user.id:
        await msg.answer("❗️ باید شماره‌ی خودت رو با همون دکمهٔ پایین بفرستی، نه یه مخاطبِ دیگه.")
        return
    phone = (contact.phone_number or "").strip().lstrip("+")
    if not phone.startswith("98"):
        await msg.answer(
            "❌ فقط شماره‌هایِ ایران (+۹۸) قبول می‌شه. با شماره‌ای که تو تلگرامِ خودت "
            "ثبته و ایرانیه، دوباره روی دکمه بزن:")
        return
    u = await get_or_create_user(row.id, msg.from_user.id, msg.from_user.full_name,
                                 msg.from_user.username or "")
    # === PATCH_PHONE_VERIFY_FRESH_READ_V1 ===
    # با UPDATEِ مستقیم ذخیره می‌کنیم (نه از طریقِ آبجکتِ ORM) تا مطمئن باشیم
    # حتماً رویِ همون ردیفِ درست نوشته می‌شه، و بعدش تایید می‌کنیم که واقعاً
    # ثبت شده — اگه نشده باشه، به کاربر «تایید شد» نمی‌گیم.
    from sqlalchemy import update as _sa_update
    saved = False
    async with Session() as s:
        await s.execute(
            _sa_update(BotUser)
            .where(BotUser.bot_id == row.id, BotUser.telegram_id == msg.from_user.id)
            .values(phone_verified=True, phone_number=phone))
        await s.commit()
        chk = await s.scalar(select(BotUser.phone_verified).where(
            BotUser.bot_id == row.id, BotUser.telegram_id == msg.from_user.id))
        saved = bool(chk)
    if not saved:
        logger.error("phone verify: ذخیره‌سازی تایید نشد (bot_id=%s tg=%s)",
                     row.id, msg.from_user.id)
        await msg.answer("⚠️ ثبتِ شماره با مشکل مواجه شد. لطفاً دوباره امتحان کن "
                         "یا به پشتیبانی اطلاع بده.")
        return
    # === PATCH_PHONE_LOG_CHANNEL_V1 ===
    _pay_gate_now = (await get_setting(row.id, "phone_verify_pay", "off")) == "on"
    await send_phone_log(bot, row, u, phone,
                         "پیش از پرداخت/خرید" if _pay_gate_now else "ثبت‌نام")
    await _phone_verify_resume_pending(bot, row, u, state, msg.from_user.id)
    kb = await main_kb_or_remove(row.id, row.owner_id, msg.from_user.id) \
        if (await get_setting(row.id, "menu_mode", "reply")) != "inline" else ReplyKeyboardRemove()
    # === PATCH_PAY_PHONE_VERIFY_V1 ===
    # اگر گیتِ «پیش از پرداخت» روشن است، کاربر را به همان مسیر برگردان
    # وگرنه نمی‌داند باید دوباره روی شارژ بزند.
    _pay_gate_on = (await get_setting(row.id, "phone_verify_pay", "off")) == "on"
    _ok_msg = await msg.answer(
        "✅ شماره‌ت با موفقیت تایید شد!"
        + ("\n\n💳 حالا می‌تونی دوباره روی «شارژ کیف پول» بزنی و پرداخت رو "
           "ادامه بدی." if _pay_gate_on else ""),
        reply_markup=kb)
    if (await get_setting(row.id, "menu_mode", "reply")) == "inline":
        ikb = await main_inline_kb(row.id, row.owner_id, msg.from_user.id)
        if ikb:
            # === PATCH_CUSTOM_HOME_MENU_TEXT_HIDE_V4 ===
            await send_home_menu(msg, row.id, ikb, attach=_ok_msg)


# === PATCH_PHONE_GATE_CB_V1 ===
# callbackهایی که حتی کاربرِ تاییدنشده باید بتواند بزند — وگرنه در
# حلقه گیر می‌کند (دکمه‌هایِ خودِ فرایندِ عضویت و تایید).
_PHONE_GATE_EXEMPT = ("fj:", "noop", "phv:")


@tenant_router.callback_query.outer_middleware
async def tenant_phoneverify_cb_mw(handler, event, data):
    """همان گیتِ tenant_phoneverify_mw، ولی رویِ دکمه‌هایِ اینلاین.

    چرا لازم است: میدل‌ویرِ پیام‌ها به callback نمی‌رسد. اگر ادمین
    تاییدِ شماره را بعد از شروعِ کارِ ربات فعال کند، کاربرانی که از قبل
    منو گرفته‌اند دکمه‌هایِ اینلاین در چتشان دارند و کلِ گیت را دور
    می‌زنند.
    """
    u = getattr(event, "from_user", None)
    if not u:
        return await handler(event, data)

    cbdata = getattr(event, "data", "") or ""
    if cbdata.startswith(_PHONE_GATE_EXEMPT):
        return await handler(event, data)

    # اگر کاربر وسطِ یک فرایندِ FSM است، وسطش را قطع نکن.
    fsm_state = data.get("state")
    if fsm_state is not None:
        try:
            if await fsm_state.get_state() is not None:
                return await handler(event, data)
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (خواندنِ stateِ FSM)")

    msg = getattr(event, "message", None)
    if msg is not None and getattr(msg, "chat", None) is not None:
        if msg.chat.type != "private":
            return await handler(event, data)

    bot = data.get("bot") or getattr(event, "bot", None)
    if bot is None:
        return await handler(event, data)
    row = await get_bot_row(bot)
    if not row:
        return await handler(event, data)

    if not await _fj_needs_phone_verify(row, u.id):
        return await handler(event, data)

    await event.answer(
        "📱 اول باید شماره‌ات را تایید کنی. /start را بزن.",
        show_alert=True)


@tenant_router.message.outer_middleware
async def tenant_phoneverify_mw(handler, event, data):
    """قبل از رسیدنِ هر پیام به هندلرش، اگه تاییدِ شماره فعال باشه و کاربر
    هنوز تاییدش نکرده باشه، به‌جایِ اجرایِ هندلرِ اصلی، دوباره پرامپتِ
    تاییدِ شماره رو نشون می‌ده — دقیقاً مثلِ میدل‌ویرِ آنتی‌اسپمِ بالا."""
    u = getattr(event, "from_user", None)
    if not u:
        return await handler(event, data)
    # پیامِ حاویِ مخاطب (خودِ تاییدِ شماره) همیشه باید برسه به هندلرِ خودش
    if getattr(event, "contact", None):
        return await handler(event, data)
    fsm_state = data.get("state")
    if fsm_state is not None:
        try:
            if await fsm_state.get_state() is not None:
                return await handler(event, data)
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    bot = data.get("bot") or event.bot
    row = await get_bot_row(bot)
    if not row:
        return await handler(event, data)
    # === PATCH_PHONE_VERIFY_PRIVATE_ONLY_V1 ===
    # فقط تویِ چتِ خصوصی؛ تویِ گروه/سوپرگروه دکمهٔ اشتراک‌گذاریِ مخاطب
    # (request_contact) کار نمی‌کنه و کاربر رو بی‌دلیل گیر می‌انداخت.
    if getattr(event, "chat", None) is not None and event.chat.type != "private":
        return await handler(event, data)
    if (await get_setting(row.id, "phone_verify_enabled", "off")) != "on":
        return await handler(event, data)
    if await is_owner_or_admin(row.id, u.id, row.owner_id):
        return await handler(event, data)
    async with Session() as s:
        bu = await s.scalar(select(BotUser).where(BotUser.bot_id == row.id, BotUser.telegram_id == u.id))
    if bu and bu.phone_verified:
        return await handler(event, data)
    # کاربرِ تازه (هنوز حتی BotUser نداره) با /start می‌رسه اینجا — بذار
    # tenant_start خودش با ثبت/معرفیِ کاربر و دعوت‌هایِ در انتظار مدیریتش کنه؛
    # این‌جا فقط برایِ همون /start اول جلوش رو نمی‌گیریم، ولی بلافاصله بعدش
    # (تویِ خودِ tenant_start) پرامپتِ تاییدِ شماره نشون داده می‌شه.
    if getattr(event, "text", None) and event.text.startswith("/start"):
        return await handler(event, data)
    await _phone_verify_prompt(event)


# === PATCH_VSO_NO_MENU_NO_PIN_V1 ===
# تا وقتی قوانینِ اجباری تایید نشده، هیچ پیام/دکمه‌ای (حتی دکمه‌هایِ منویِ قبلی که در
# چتِ کاربر مانده) کار نمی‌کند؛ فقط /start و دکمهٔ «تایید قوانین». مالک/ادمین معاف‌اند.
async def _vso_rules_blocked(bot, uid: int) -> int | None:
    """اگر کاربر باید اول قوانین را تایید کند، bot_id را برمی‌گرداند؛ وگرنه None."""
    row = await get_bot_row(bot)
    if not row:
        return None
    if (await get_setting(row.id, "vs_rules_required", "0")) != "1":
        return None
    if not (await get_setting(row.id, "vs_rules_text", "")):
        return None
    if await is_owner_or_admin(row.id, uid, row.owner_id) or _is_platform_admin(uid):
        return None
    async with Session() as s:
        bu = await s.scalar(select(BotUser).where(BotUser.bot_id == row.id, BotUser.telegram_id == uid))
    if bu is None:
        return None
    if bu.rules_accepted:
        # === PATCH_RULES_VERSION_V1 === تأییدِ قدیمی (بدونِ نسخه) یک‌بار به نسخهٔ فعلی ارتقا پیدا می‌کند؛
        # بعد از آن، تغییرِ متنِ قوانین ⇒ دوباره پرسیده می‌شود.
        cur = _rules_ver(await get_setting(row.id, "vs_rules_text", ""))
        if bu.rules_version is None:
            from sqlalchemy import update as _upd
            async with Session() as s:
                await s.execute(_upd(BotUser).where(BotUser.id == bu.id).values(rules_version=cur))
                await s.commit()
            return None
        if bu.rules_version == cur:
            return None
    return row.id


@tenant_router.message.outer_middleware
async def tenant_rules_gate_mw(handler, event, data):
    u = getattr(event, "from_user", None)
    if not u or getattr(getattr(event, "chat", None), "type", "private") != "private":
        return await handler(event, data)
    if (getattr(event, "text", None) or "").startswith("/start"):
        return await handler(event, data)
    bot = data.get("bot") or event.bot
    bid = await _vso_rules_blocked(bot, u.id)
    if bid is None:
        return await handler(event, data)
    from tenant.bots.virtual_service.smm import _vs_show_rules_gate
    await _vs_show_rules_gate(event, bot, bid)


@tenant_router.callback_query.outer_middleware
async def tenant_rules_gate_cb_mw(handler, event, data):
    u = getattr(event, "from_user", None)
    if not u:
        return await handler(event, data)
    msg = getattr(event, "message", None)
    if msg is not None and getattr(getattr(msg, "chat", None), "type", "private") != "private":
        return await handler(event, data)
    if (getattr(event, "data", "") or "").startswith("vso:"):
        return await handler(event, data)
    bot = data.get("bot") or event.bot
    bid = await _vso_rules_blocked(bot, u.id)
    if bid is None:
        return await handler(event, data)
    try:
        await event.answer("📖 اول قوانین را تایید کن.", show_alert=True)
    except Exception:
        logger.exception("[vso] پاسخ به callback ممکن نشد")
    if msg is not None:
        from tenant.bots.virtual_service.smm import _vs_show_rules_gate
        await _vs_show_rules_gate(msg, bot, bid)


def parse_opts(text: str, fallback: list[int]) -> list[int]:
    """متن گزینه را به فهرست عددی تبدیل می‌کند.
    پشتیبانی از: «a-b» یا «a تا b» (بازه)، «a,b,c» (لیست)، یا «n» (مقدار ثابت)."""
    if not text:
        return list(fallback)
    t = text.replace("،", ",").replace(" ", "").strip()
    # بازه: a-b یا a تا b
    m = re.split(r"-|تا", t)
    if len(m) == 2 and m[0].isdigit() and m[1].isdigit():
        a, b = int(m[0]), int(m[1])
        if a > b:
            a, b = b, a
        if b - a > 500:  # جلوگیری از بازهٔ بیش از حد بزرگ
            b = a + 500
        return list(range(a, b + 1)) or list(fallback)
    # لیست: a,b,c
    if "," in t:
        nums = [int(x) for x in t.split(",") if x.isdigit()]
        return nums or list(fallback)
    # مقدار ثابت
    if t.isdigit():
        return [int(t)]
    return list(fallback)


async def get_options(bot_id: int):
    v = await get_setting(bot_id, "volume_options", "10,30,50,100")
    d = await get_setting(bot_id, "day_options", "30,60,90")
    c = await get_setting(bot_id, "count_options", "1-5")
    vols = parse_opts(v, [10, 30, 50])
    days = parse_opts(d, [30, 60, 90])
    counts = parse_opts(c, [1, 2, 3, 4, 5])
    return vols, days, counts


_BTN_CFG_CACHE: dict[int, tuple[dict, int, float]] = {}
_BTN_CFG_CACHE_TTL = 15.0  # ثانیه


async def get_btn_cfg(mbid: int):
    # === PATCH_BTNCFG_TTL_CACHE_V1 ===
    # این تابع پشتِ دکمه‌های استپرِ ➕➖ (buy_adjust) هم صدا زده می‌شود که
    # کاربر معمولاً چندبار پشتِ‌سرهم و سریع می‌زند. کشِ کوتاه‌مدت (۱۵ثانیه)
    # از تکرارِ کوئریِ MainButton/گزینه‌ها/قیمت‌ها روی هر تک‌کلیک جلوگیری
    # می‌کند. چون این مقادیر معمولاً فقط توسطِ خودِ ادمین هنگامِ تنظیمِ
    # قیمت‌ها تغییر می‌کنند (نه در هر ثانیه)، تاخیرِ حداکثر ۱۵ثانیه‌ای در
    # دیدنِ تغییرات قابلِ قبول است.
    import time as _time
    cached = _BTN_CFG_CACHE.get(mbid)
    if cached is not None and cached[2] > _time.monotonic():
        return dict(cached[0]), cached[1]  # کپیِ سطحی تا مصرف‌کننده cfg را دستکاری نکند
    async with Session() as s:
        mb = await s.get(MainButton, mbid)
        if not mb:
            return None
        bot_id = mb.bot_id
        cfg = None
        if mb.config:
            try:
                cfg = json.loads(mb.config)
            except Exception:
                cfg = None
    vols, days, counts = await get_options(bot_id)
    if not cfg:
        cfg = {"vols": vols, "days": days, "price_gb": 0, "price_day": 0}
    cfg.setdefault("vols", vols)
    cfg.setdefault("days", days)
    cfg.setdefault("counts", counts)  # اگر دکمه بازهٔ تعداد اختصاصی نداشت، از تنظیمات سراسری
    # قیمت‌ها در سطح ربات (در بخش مدیریت کانفیگ‌ها) تنظیم می‌شوند
    pg = await get_setting(bot_id, "price_gb", "")
    pd = await get_setting(bot_id, "price_day", "")
    cfg["price_gb"] = int(pg) if str(pg).strip().isdigit() else cfg.get("price_gb", 0) or 0
    cfg["price_day"] = int(pd) if str(pd).strip().isdigit() else cfg.get("price_day", 0) or 0
    pu = await get_setting(bot_id, "price_unlimited", "")
    pud = await get_setting(bot_id, "price_unlimited_day", "")
    cfg["price_unlimited"] = int(pu) if str(pu).strip().isdigit() else cfg.get("price_unlimited", 0) or 0
    cfg["price_unlimited_day"] = int(pud) if str(pud).strip().isdigit() else cfg.get("price_unlimited_day", 0) or 0
    if not cfg["vols"]:
        cfg["vols"] = [10]
    if not cfg["days"]:
        cfg["days"] = [30]
    if not cfg["counts"]:
        cfg["counts"] = [1]
    _BTN_CFG_CACHE[mbid] = (cfg, bot_id, _time.monotonic() + _BTN_CFG_CACHE_TTL)
    return dict(cfg), bot_id


async def _bot_has_range_stock(bot_id: int, unlimited: bool = False) -> bool:
    """آیا حداقل یک کانفیگِ «بازه‌ای» (قیمت سراسری هر گیگ/روز، price=0) در انبار این ربات موجود است؟

    اگر هیچ کانفیگی از این نوع در انبار نباشد، نمایشِ کیبوردِ بازه‌ای (➕➖ حجم/روز/تعداد)
    بی‌فایده است — هر انتخابی که کاربر بزند در لحظهٔ «ثبت سفارش» با «ناموجود» رد می‌شود.
    unlimited=True یعنی فقط کانفیگ‌های نامحدود (volume_gb=0) را بشمار.
    """
    async with Session() as s:
        q = select(func.count()).select_from(Config).where(
            Config.bot_id == bot_id, Config.status == "in_stock", Config.price == 0)
        q = q.where(Config.volume_gb == 0) if unlimited else q.where(Config.volume_gb != 0)
        cnt = await s.scalar(q)
    return bool(cnt)


async def get_unlimited_cfg(bot_id: int) -> dict:
    """تنظیمات مستقلِ فروش کانفیگ نامحدود: قیمت ثابت + قیمت هر روز + بازهٔ روز."""
    ud = await get_setting(bot_id, "unlimited_day_options", "30,60,90")
    days = parse_opts(ud, [30, 60, 90])
    if not days:
        days = [30, 60, 90]
    pu = await get_setting(bot_id, "price_unlimited", "")
    pud = await get_setting(bot_id, "price_unlimited_day", "")
    price_unlimited = int(pu) if str(pu).strip().isdigit() else 0
    price_unlimited_day = int(pud) if str(pud).strip().isdigit() else 0
    return {"days": days, "price_unlimited": price_unlimited,
            "price_unlimited_day": price_unlimited_day}


def price_of_unlimited(cfg: dict, di: int) -> int:
    day = cfg["days"][di]
    return cfg.get("price_unlimited", 0) + day * cfg.get("price_unlimited_day", 0)


def price_of(cfg, vi, di, c) -> int:
    vol = cfg["vols"][vi]
    day = cfg["days"][di]
    if vol == 0:
        # کانفیگ نامحدود: قیمت ثابت + قیمت روز
        p_unl = cfg.get("price_unlimited", 0) or 0
        p_unl_day = cfg.get("price_unlimited_day", 0) or 0
        return c * (p_unl + day * p_unl_day)
    return c * (vol * cfg["price_gb"] + day * cfg["price_day"])


def apply_discount(price: int, percent: int) -> int:
    return max(0, price * (100 - percent) // 100)


