BTN_CFG_GUIDE = "📖 دکمه آموزش اتصال چسبیده به کانفیگ خریداری‌شده"
BTN_BACK_MENU = "⬅️ بازگشت به منو"
BTN_BACK_LEVEL = "◀️ بازگشت"
BTN_SUPPORT_ROW = "💬 پشتیبانی این بخش"


_COLOR_TO_STYLE = {
    "danger":  ButtonStyle.DANGER,
    "success": ButtonStyle.SUCCESS,
    "primary": ButtonStyle.PRIMARY,
}


_BTN_CMD_RE = re.compile(r"^[a-z0-9_]{1,32}$")
# کامندهای رزروشدهٔ خود ربات که دکمه‌ها نمی‌توانند بگیرند
_BTN_CMD_RESERVED = {"start", "skip", "cancel", "panel", "admin", "help"}


def _btn_command_of(b) -> str | None:
    """کامند سفارشی ذخیره‌شده روی دکمه (بدون /) — از config JSON."""
    if not getattr(b, "config", None):
        return None
    try:
        c = ((json.loads(b.config) or {}).get("command") or "").strip()
    except Exception:
        return None
    return c if _BTN_CMD_RE.match(c) else None


async def _find_btn_by_command(bot_id: int, cmd: str):
    """پیدا کردن دکمه‌ای که کامند سفارشی‌اش cmd است."""
    async with Session() as s:
        cands = (await s.scalars(select(MainButton).where(
            MainButton.bot_id == bot_id,
            MainButton.config.is_not(None),
            MainButton.config.contains('"command"'),
        ))).all()
    for b in cands:
        if _btn_command_of(b) == cmd:
            return b
    return None


def _is_valid_webapp_url(url: str) -> bool:
    """اعتبارسنجیِ سخت‌گیرانهٔ آدرسِ مینی‌اپ — تنها جایی که این قوانین تعریف می‌شوند
    (هم موقعِ ذخیره‌سازی و هم موقعِ ساختِ دکمه از همین تابع استفاده می‌شود تا هرگز
    این دو جا از هم عقب نیفتند).

    === PATCH_BUTTON_URL_GUARD_V2 ===
    نسخهٔ قبلی فقط دنبالِ کاراکترِ فاصلهٔ معمولی (" ") می‌گشت؛ فاصله‌های نامرئیِ
    دیگر (نیم‌فاصله/nbsp، تب، اینتر، فاصلهٔ عریض و...) که معمولاً از کیبوردِ
    موبایل یا کپی از یک پیامِ دیگر می‌آیند رد نمی‌شدند و باعث می‌شد لینک ذخیره
    شود ولی تلگرام موقعِ ارسالِ دکمه با BUTTON_URL_INVALID رد کند و کلِ /start
    برای همهٔ کاربرها بشکند. حالا هر جور whitespace و همچنین دامنهٔ غیرASCII
    (که تلگرام بدونِ punycode قبول نمی‌کند) رد می‌شود.
    """
    if not url or not url.startswith("https://"):
        return False
    if len(url) > 500:
        return False
    if any(ch.isspace() for ch in url):
        return False
    try:
        from urllib.parse import urlparse
        p = urlparse(url)
    except Exception:
        return False
    if p.scheme != "https" or not p.netloc:
        return False
    if "." not in p.netloc or p.netloc.startswith(".") or p.netloc.endswith("."):
        return False
    if not p.netloc.isascii():
        return False
    return True


def _strip_broken_webapp_buttons(kb: "InlineKeyboardMarkup | None") -> "InlineKeyboardMarkup | None":
    """کیبورد را دوباره می‌سازد ولی هر دکمهٔ web_app را حذف می‌کند (تبدیل به
    دکمهٔ بدونِ اکشن نمی‌شود، کلاً از ردیفش برداشته می‌شود). این تابع فقط در
    مسیرِ محافظِ ارسال (send-guard) استفاده می‌شود، وقتی تلگرام کل کیبورد را
    به‌خاطرِ یک لینکِ خراب رد کرده — تا حداقل بقیهٔ دکمه‌های منو کار کنند.
    """
    if not kb or not kb.inline_keyboard:
        return kb
    new_rows = []
    for row in kb.inline_keyboard:
        new_row = [b for b in row if b.web_app is None]
        if new_row:
            new_rows.append(new_row)
    if not new_rows:
        return None
    return InlineKeyboardMarkup(inline_keyboard=new_rows)


# === PATCH_REPLY_KB_SEND_GUARD_V1 ===
def _strip_broken_webapp_buttons_reply(
        kb: "ReplyKeyboardMarkup | None") -> "ReplyKeyboardMarkup | None":
    """معادلِ _strip_broken_webapp_buttons بالا، ولی برایِ کیبوردِ پایینِ صفحه
    (حالتِ «⌨️ کیبورد» منو). قبلاً فقط مسیرِ منویِ شیشه‌ای این محافظ را
    داشت؛ در حالتِ کیبوردی، همان دکمهٔ مینی‌اپِ خراب کلِ /start را برایِ
    همهٔ کاربرانِ ربات کرش می‌داد (BUTTON_URL_INVALID)."""
    if not kb or not kb.keyboard:
        return kb
    new_rows = []
    for row in kb.keyboard:
        new_row = [b for b in row if b.web_app is None]
        if new_row:
            new_rows.append(new_row)
    if not new_rows:
        return None
    return ReplyKeyboardMarkup(keyboard=new_rows, resize_keyboard=True)


def _webapp_url(b) -> str | None:
    """آدرس مینی‌اپ (Web App) ذخیره‌شده در config دکمه — اگر action دکمه web_app باشد."""
    if getattr(b, "action", None) != "web_app" or not getattr(b, "config", None):
        return None
    try:
        url = ((json.loads(b.config) or {}).get("webapp_url") or "").strip()
    except Exception:
        return None
    if not _is_valid_webapp_url(url):
        return None
    return url


# === PATCH_BUTTON_CHANNEL_LINK_V1 === (پشتیبانِ بات‌ساز) عملکردِ «لینک مستقیم به کانال/گروه/سایت»
def normalize_link_url(raw: str) -> str | None:
    """«@name» / «t.me/name» / «https://…» را به یک لینکِ https معتبر تبدیل می‌کند؛ نامعتبر ⇒ None."""
    t = (raw or "").strip()
    if t.startswith("@") and len(t) > 1 and re.fullmatch(r"@[A-Za-z0-9_]{4,64}", t):
        t = "https://t.me/" + t[1:]
    elif re.match(r"^(?:t\.me|telegram\.me)/", t, re.I):
        t = "https://" + t
    elif t.lower().startswith("http://"):
        t = "https://" + t[len("http://"):]
    return t if _is_valid_webapp_url(t) else None


def _link_url(b) -> str | None:
    if getattr(b, "action", None) != "channel_link" or not getattr(b, "config", None):
        return None
    try:
        url = ((json.loads(b.config) or {}).get("link_url") or "").strip()
    except Exception:
        return None
    return url if _is_valid_webapp_url(url) else None


# === PATCH_REPLY_KEYBOARD_RESPECT_LAYOUT_V2 ===
# نسخهٔ V1 هنوز یک ویتویِ عرض داشت و همان شکایت را کامل حل نمی‌کرد: ادمین
# با «🔀 چیدمانِ سریع» سه دکمه را کنارِ هم می‌گذاشت، ابزار قبولش می‌کرد و در
# دیتابیس هم درست ذخیره می‌شد، ولی موقعِ ساختِ کیبورد همین تابع دوباره
# می‌شکاندش — پس ادمین فکر می‌کرد «سه‌تایی اصلاً کار نمی‌کند».
#
# قاعده: چیدمانی که مالک ذخیره کرده قانون است و بازنویسی نمی‌شود. ابزارِ
# چیدمان خودش سقفِ سه دکمه را اعمال می‌کند، پس اینجا فقط یک محافظِ نهایی
# برایِ ردیف‌هایِ غیرعادی (بیش از چهار دکمه، که فقط از دادهٔ قدیمی/دستی
# می‌آید) لازم است. اگر متنی بلند باشد تلگرام خودش دو خطی نشانش می‌دهد —
# این تصمیمِ مالک است، نه بایِ ما.
_REPLY_ROW_MAX_WIDTH = 38          # فقط برایِ سازگاری؛ دیگر استفاده نمی‌شود
_REPLY_ROW_MAX_BUTTONS = 4


def _reply_text_width(text: str) -> int:
    return sum(2 if unicodedata.east_asian_width(ch) in ("W", "F") else 1
               for ch in (text or ""))


def _fit_reply_rows(rows: list[list[KeyboardButton]]) -> list[list[KeyboardButton]]:
    """ردیف‌های کیبورد متنی را همان‌طور که مالکِ ربات چیده برمی‌گرداند.

    تنها دخالت: ردیفی با بیش از `_REPLY_ROW_MAX_BUTTONS` دکمه به ردیف‌هایِ
    متوازن تقسیم می‌شود. ترتیب، عملکرد و action دکمه‌ها هیچ‌وقت عوض نمی‌شود.
    """
    fitted: list[list[KeyboardButton]] = []
    for row in rows:
        if not row:
            continue
        if len(row) <= _REPLY_ROW_MAX_BUTTONS:
            fitted.append(list(row))       # چیدمانِ مالک دست‌نخورده
            continue
        parts = -(-len(row) // _REPLY_ROW_MAX_BUTTONS)   # کمترین تعدادِ ردیف
        size = -(-len(row) // parts)                     # اندازهٔ متوازن
        fitted.extend([row[i:i + size] for i in range(0, len(row), size)])
    return fitted


def _kbtn_for(b, style):
    """KeyboardButton هر دکمهٔ منو — با اعمال استایل و ایموجی پرمیوم در صورت وجود."""
    kw = {"text": b.label}
    _wa = _webapp_url(b)
    if _wa:
        # دکمهٔ مینی‌اپ: با لمس دکمه، وب‌اپ مستقیماً داخل تلگرام باز می‌شود
        kw["web_app"] = WebAppInfo(url=_wa)
    if style:
        kw["style"] = style
    if getattr(b, "icon_emoji_id", None):
        kw["icon_custom_emoji_id"] = b.icon_emoji_id
    return KeyboardButton(**kw)


def _ibtn_for(b, style):
    """InlineKeyboardButton هر دکمهٔ منو — با اعمال استایل و ایموجی پرمیوم در صورت وجود."""
    kw = {"text": b.label, "callback_data": f"mbtn:{b.id}"}
    _wa = _webapp_url(b)
    if _wa:
        # دکمهٔ مینی‌اپ: به‌جای callback مستقیماً وب‌اپ باز می‌شود
        kw.pop("callback_data", None)
        kw["web_app"] = WebAppInfo(url=_wa)
    _lu = _link_url(b)           # PATCH_BUTTON_CHANNEL_LINK_V1: در منویِ شیشه‌ای مستقیم به کانال/لینک می‌رود
    if _lu:
        kw.pop("callback_data", None)
        kw["url"] = _lu
    if style:
        kw["style"] = style
    if getattr(b, "icon_emoji_id", None):
        kw["icon_custom_emoji_id"] = b.icon_emoji_id
    return InlineKeyboardButton(**kw)


# === PATCH_RESELLER_MENU_BUTTON_V1 ===
# نماینده تا حالا هیچ ردی از نمایندگی‌اش در منویِ ربات نمی‌دید؛ آدرسِ پنل
# را ادمین دستی برایش می‌فرستاد. حالا اگر کاربری نمایندهٔ فعالِ همین ربات
# باشد، یک دکمهٔ اختصاصی در منویِ اصلیِ *خودش* می‌بیند. برایِ بقیهٔ کاربرها
# هیچ تغییری نیست.
BTN_RESELLER = "🏷 پنل نمایندگی من"


async def _is_reseller(bot_id: int, viewer_id: int | None) -> bool:
    if not viewer_id or viewer_id <= 0:
        return False
    try:
        from models import VpnPartner
        async with Session() as s:
            p = await s.scalar(select(VpnPartner).where(
                VpnPartner.bot_id == bot_id, VpnPartner.telegram_id == viewer_id))
        return bool(p and p.active)
    except Exception:
        logger.exception("بررسیِ نمایندگی ناموفق بود (دکمه نمایش داده نمی‌شود)")
        return False


async def main_kb_or_remove(bot_id: int, owner_id: int | None = None,
                            viewer_id: int | None = None):
    """نسخهٔ هماهنگ‌شده با نوعِ منو: در حالتِ «شیشه‌ای» هرگز کیبوردِ پایینِ صفحه
    نشان داده نمی‌شود (چون منو به‌صورت اینلاین است)؛ در حالتِ «کیبورد» همان
    کیبوردِ معمولیِ دکمه‌های اصلی برمی‌گردد. جایگزینِ امنِ همه‌جای
    `kb = await main_kb(...)` که قبلاً بدون توجه به نوع منو صدا زده می‌شد."""
    if await get_setting(bot_id, "menu_mode", "reply") == "inline":
        return ReplyKeyboardRemove()
    kb = await main_kb(bot_id, owner_id, viewer_id)
    return kb or ReplyKeyboardRemove()


async def main_kb(bot_id: int, owner_id: int | None = None,
                  viewer_id: int | None = None) -> ReplyKeyboardMarkup | None:
    async with Session() as s:
        btns = (await s.scalars(
            select(MainButton).where(MainButton.bot_id == bot_id,
                                     MainButton.parent_id.is_(None))
            .order_by(MainButton.row, MainButton.col)
        )).all()
        bot_row = await s.get(BotRow, bot_id)
        _dis_rows = (await s.scalars(
            select(Setting).where(Setting.bot_id == bot_id, Setting.key.like("hbtn_off:%"))
        )).all()
    _disabled = {int(r.key.split(":")[1]) for r in _dis_rows
                 if r.value == "1" and r.key.split(":")[1].isdigit()}
    # === PATCH_ADMIN_SUPPORT_KB_FIX_V1 ===
    # قبلاً فقط برابریِ مستقیمِ viewer_id == owner_id چک می‌شد؛ ادمین‌های
    # پشتیبانیِ ثبت‌شده در جدولِ AdminSupport (مثلاً از طریقِ «دسترسیِ
    # پشتیبانی» در پنلِ ادمینِ پلتفرم) دکمهٔ پنل مدیریت را در کیبورد
    # نمی‌دیدند — هرچند خودِ محتوایِ پنل (با /admin) برایشان باز می‌شد.
    # هماهنگ با main_inline_kb که از قبل درست بود.
    is_staff = (owner_id is not None and viewer_id is not None and
                await is_staff_member(bot_id, viewer_id, owner_id))
    if not btns and not is_staff:
        return None
    colored = bot_row is not None and has_feature(bot_row.plan, Feature.COLORED_BUTTONS)
    rows_map: dict[int, list[KeyboardButton]] = {}
    for b in btns:
        if b.id in _disabled:
            continue
        style = _COLOR_TO_STYLE.get(b.color or "") if colored else None
        rows_map.setdefault(b.row, []).append(_kbtn_for(b, style))
    kb_rows = _fit_reply_rows([rows_map[r] for r in sorted(rows_map)])
    # === PATCH_MINIAPP_PLACEMENT_V1 ===
    # اگر مالک «محلِ نمایش» را روی «کیبورد» گذاشته باشد، مینی‌اپ به‌جای
    # اشغالِ دکمهٔ Menu (که فقط یکی است و منویِ دستورات را پاک می‌کند)،
    # به‌صورتِ یک دکمهٔ وب‌اپ داخلِ همین کیبورد نمایش داده می‌شود.
    # === PATCH_WEBAPP_GROUP_FIX_V1 ===
    # viewer_id مثبت یعنی چتِ خصوصیِ همان کاربر؛ در گروه/سوپرگروه (آی‌دیِ
    # منفی) دکمهٔ وب‌اپ ساخته نمی‌شود، چون تلگرام آن را فقط در چتِ خصوصی
    # می‌پذیرد و در غیرِ این صورت کلِ پیام با خطا رد می‌شود.
    _ma_row = (await _miniapp_kb_row(bot_id, bot_row, viewer_id=viewer_id)
               if (viewer_id or 0) > 0 else None)
    if _ma_row:
        # === PATCH_MINIAPP_KB_POS_V1 === جایگاهِ دکمه: بالا (اولین ردیف) یا پایین (پیش‌فرض)
        if (await get_setting(bot_id, "miniapp_kb_pos", "bottom")) == "top":
            kb_rows.insert(0, _ma_row)
        else:
            kb_rows.append(_ma_row)
    # === PATCH_RESELLER_MENU_BUTTON_V1 ===
    if await _is_reseller(bot_id, viewer_id):
        kb_rows.append([KeyboardButton(text=BTN_RESELLER)])
    if is_staff:
        # دکمهٔ پنل مدیریت فقط برای مالک ربات
        kb_rows.append([KeyboardButton(text=BTN_TADMIN)])
    return ReplyKeyboardMarkup(keyboard=kb_rows, resize_keyboard=True)


# === PATCH_MINIAPP_PLACEMENT_V1 ===
async def _miniapp_kb_row(bot_id: int, bot_row=None,
                          viewer_id: int | None = None) -> list[KeyboardButton] | None:
    """ردیفِ دکمهٔ وب‌اپِ مینی‌اپ برایِ کیبوردِ اصلی — فقط وقتی مینی‌اپ روشن
    است و مالک «محلِ نمایش» را روی «کیبورد» گذاشته. None یعنی چیزی اضافه نشود."""
    try:
        if bot_row is None:
            async with Session() as s:
                bot_row = await s.get(BotRow, bot_id)
        if not bot_row or not getattr(bot_row, "miniapp_enabled", False):
            return None
        if (await get_setting(bot_id, "miniapp_place", "menu")) != "keyboard":
            return None
        # === PATCH_MINIAPP_NO_DUP_BTN_V1 === اگر مالک مینی‌اپ را به یک دکمهٔ دلخواهِ صفحهٔ اصلی
        # وصل کرده («🛍 تبدیل به مینی‌اپ»)، دکمهٔ خودکارِ مینی‌اپ در کیبورد تکراری است و نمی‌آید.
        try:
            async with Session() as _s_dup:
                _dup_ids = (await _s_dup.scalars(select(MainButton.id).where(
                    MainButton.bot_id == bot_id, MainButton.action == "store_miniapp"))).all()
            if _dup_ids:
                _dis = await _disabled_btn_ids(bot_id)
                if any(i not in _dis for i in _dup_ids):
                    return None
        except Exception:
            logger.exception("بررسیِ دکمهٔ تکراریِ مینی‌اپ ناموفق بود")
        from config import WEBHOOK_BASE as _WB
        if not _WB.startswith("https://"):
            return None
        from tenant.shared.miniapp_admin import miniapp_btn_text
        label = await miniapp_btn_text(bot_id)
        # === PATCH_MINIAPP_KB_DIRECT_V1 ===
        # وب‌اپی که از دکمهٔ کیبورد باز شود طبقِ مستنداتِ تلگرام initData
        # نمی‌گیرد، پس نمی‌شود کاربر را از رویِ آن احراز کرد. چون کیبورد
        # برایِ هر کاربر جداگانه ساخته می‌شود، یک توکنِ امضاشدهٔ مخصوصِ
        # همان کاربر داخلِ آدرس می‌گذاریم تا با یک ضربه مستقیم باز شود.
        # اگر viewer_id نداشته باشیم (نباید پیش بیاید) دکمه ساخته نمی‌شود،
        # چون بدونِ توکن کاربر فقط خطا می‌بیند.
        if not viewer_id:
            return None
        from tenant.shared.miniapp import make_kb_token
        tok = make_kb_token(bot_row.token or "", int(viewer_id), bot_id=bot_id)
        url = f"{_WB.rstrip('/')}/miniapp/{bot_id}?t={tok}"
        return [KeyboardButton(text=label, web_app=WebAppInfo(url=url))]
    except Exception:
        logger.exception("خطا در ساختِ دکمهٔ وب‌اپِ مینی‌اپ در کیبورد")
        return None


async def submenu_kb(bot_id: int, parent_id: int, support_row: bool = False,
                     show_up_row: bool = False) -> ReplyKeyboardMarkup | None:
    """کیبوردِ زیرمنو: دکمه‌های فرزندِ یک دکمهٔ والد + دکمهٔ بازگشت. از چند سطح پشتیبانی می‌کند.
    اگر support_row=True باشد، یک ردیفِ «💬 پشتیبانی این بخش» هم به همین کیبورد
    (همان پیام) اضافه می‌شود؛ چون تلگرام نمی‌گذارد یک پیام هم‌زمان کیبوردِ
    شیشه‌ای و کیبوردِ فیزیکی داشته باشد، تنها راهِ واقعاً «چسباندنِ» دکمهٔ
    پشتیبانی به همین پیام (به‌جای پیامِ جداگانه) همین است.
    اگر show_up_row=True باشد (یعنی این زیرمنو خودش داخلِ یک زیرمنوی دیگر است)،
    یک ردیفِ «◀️ بازگشت» هم اضافه می‌شود که واقعاً یک سطح بالا می‌رود (نه خانه)."""
    async with Session() as s:
        btns = (await s.scalars(
            select(MainButton).where(MainButton.bot_id == bot_id,
                                     MainButton.parent_id == parent_id)
            .order_by(MainButton.row, MainButton.col)
        )).all()
        bot_row = await s.get(BotRow, bot_id)
    disabled = await _disabled_btn_ids(bot_id)
    btns = [b for b in btns if b.id not in disabled]
    if not btns:
        rows = []
        if support_row:
            rows.append([KeyboardButton(text=BTN_SUPPORT_ROW)])
        if show_up_row:
            rows.append([KeyboardButton(text=BTN_BACK_LEVEL)])
        rows.append(await _back_kb_row(bot_id))
        return ReplyKeyboardMarkup(keyboard=rows, resize_keyboard=True)
    colored = bot_row is not None and has_feature(bot_row.plan, Feature.COLORED_BUTTONS)
    rows_map: dict[int, list[KeyboardButton]] = {}
    for b in btns:
        style = _COLOR_TO_STYLE.get(b.color or "") if colored else None
        rows_map.setdefault(b.row, []).append(_kbtn_for(b, style))
    kb_rows = _fit_reply_rows([rows_map[r] for r in sorted(rows_map)])
    if support_row:
        kb_rows.append([KeyboardButton(text=BTN_SUPPORT_ROW)])
    if show_up_row:
        kb_rows.append([KeyboardButton(text=BTN_BACK_LEVEL)])
    kb_rows.append(await _back_kb_row(bot_id))
    return ReplyKeyboardMarkup(keyboard=kb_rows, resize_keyboard=True)


async def _back_kb_row(bot_id: int) -> list:
    """ردیفِ پایینِ کیبوردِ زیرمنو: «بازگشت به منو» (+ «بازگشت به خانه» وقتی «بازگشت فقط در کیبورد» روشن است)."""
    row = [KeyboardButton(text=BTN_BACK_MENU)]
    if await nav_kb_only(bot_id):
        row.append(KeyboardButton(text=BTN_HOME_FLOW))
    return row


def _inline_back_btn() -> InlineKeyboardButton:
    return InlineKeyboardButton(text=BTN_BACK_MENU, callback_data="mbtn:home",
                                style=ButtonStyle.DANGER)


# === PATCH_BACK_PREV_AND_HOME_V1 ===
# درخواستِ Fadayi: در هر منو هم «بازگشت به منوی قبل» باشد هم «منوی اصلی». منویِ قبلِ هر کاربر
# (زیرمنویی که صفحه از آن باز شده) در حافظه نگه داشته می‌شود و inline_back_row آن را می‌خواند.
import time as _time_bm
_LAST_MENU: dict = {}
_LAST_MENU_TTL = 1800
_CUR_UID = _ContextVar("botsaz_cur_uid", default=None)


def _set_last_menu(bot_id: int, uid: int, parent_id) -> None:
    try:
        if parent_id:
            _LAST_MENU[(int(bot_id), int(uid))] = (int(parent_id), _time_bm.monotonic())
        else:
            _LAST_MENU.pop((int(bot_id), int(uid)), None)
    except Exception:
        logger.exception("set_last_menu")


def _last_menu_for(bot_id: int):
    uid = _CUR_UID.get()
    if not uid:
        return None
    hit = _LAST_MENU.get((int(bot_id), int(uid)))
    if not hit or _time_bm.monotonic() - hit[1] > _LAST_MENU_TTL:
        return None
    return hit[0]


# === PATCH_FLOW_BACK_KB_V1 ===
# گزارش ایلیا: در منوی کیبوردی، با انتخاب سرویس کل کیبورد بسته می‌شد و «بازگشت به منو» هم از دست می‌رفت.
# حالا کیبورد قبلی با یک کیبورد تک‌دکمه‌ای «⬅️ بازگشت به منو» عوض می‌شود: شلوغ نمی‌شود ولی راه برگشت داخل
# منو می‌ماند. دکمه کاربر را به همان زیرمنویی که از آن آمده برمی‌گرداند (وگرنه صفحهٔ اصلی). حافظه‌ای است؛ اگر
# ری‌استارت شود دکمه همچنان کار می‌کند ولی می‌رود صفحهٔ اصلی.
_FLOW_KB: dict = {}
_FLOW_KB_TTL = 6 * 3600


def _flow_kb_mark(bot_id: int, uid: int, sub_id) -> None:
    now = _time_bm.monotonic()
    if len(_FLOW_KB) > 5000:
        for k in [k for k, v in _FLOW_KB.items() if now - v[1] > _FLOW_KB_TTL]:
            _FLOW_KB.pop(k, None)
    _FLOW_KB[(int(bot_id), int(uid))] = (int(sub_id) if sub_id else None, now)


def _flow_kb_peek(bot_id: int, uid: int):
    """(فعال؟، شناسهٔ زیرمنوی مبدأ یا None)."""
    hit = _FLOW_KB.get((int(bot_id), int(uid)))
    if not hit or _time_bm.monotonic() - hit[1] > _FLOW_KB_TTL:
        return False, None
    return True, hit[0]


def _flow_kb_clear(bot_id: int, uid: int | None) -> None:
    if uid:
        _FLOW_KB.pop((int(bot_id), int(uid)), None)


async def _send_kb_bubble(msg_obj, bot_id: int, kb):
    """کیبورد پایین فقط با ارسال یک پیام عوض می‌شود و پاک‌کردن همان پیام کیبورد را هم می‌اندازد (آزموده‌شده، بالاتر ببین)؛
    پس پیام حامل با متن نامرئی می‌ماند و فقط بابل نامرئی *قبلی* پاک می‌شود تا تلنبار نشوند."""
    chat_id = getattr(getattr(msg_obj, "chat", None), "id", None)
    key = (bot_id, chat_id)
    prev = _HIDDEN_HOME_BUBBLES.pop(key, None)
    try:
        sent = await msg_obj.answer(HOME_MENU_TEXT_HIDDEN_MARK, reply_markup=kb)
    except Exception:
        logger.warning("متن نامرئی کیبورد بازگشت رد شد؛ متن عادی فرستاده می‌شود (bot_id=%s)", bot_id)
        return await msg_obj.answer("⬇️", reply_markup=kb)
    if chat_id is not None:
        _HIDDEN_HOME_BUBBLES[key] = sent.message_id
        if prev and prev != sent.message_id:
            try:
                await sent.bot.delete_message(chat_id, prev)
            except Exception:
                logger.info("پاک‌کردن بابل نامرئی قبلی ممکن نشد (bot_id=%s)", bot_id)
    return sent


# === PATCH_NAV_KB_ONLY_V1 ===
# درخواستِ ایلیا: «بازگشت به خانه / منوی اصلی / بازگشت به منو» از منوی شیشه‌ای حذف شود و فقط «بازگشت به منو» و
# «بازگشت به خانه» در کیبوردِ پایینِ چت باشد (در همهٔ بخش‌ها). گزینهٔ اختیاریِ مالک (پیش‌فرض خاموش) و فقط در منوی کیبوردی.
BTN_HOME_FLOW = "🏠 بازگشت به خانه"


async def nav_kb_only(bot_id: int) -> bool:
    try:
        return (await get_setting(bot_id, "menu_mode", "reply") != "inline"
                and await get_setting(bot_id, "nav_kb_only", "0") == "1")
    except Exception:
        logger.debug("nav_kb_only: خواندنِ تنظیم ممکن نشد")
        return False


_NAV_INLINE_BACK_TEXTS = frozenset({
    "بازگشت", "بازگشتبهمنو", "بازگشتبهخانه", "بازگشتبهمنویاصلی", "بازگشتبهمنویقبل", "منویاصلی",
    "خانه", "برگشتبهمنو", "برگشتبهمنویقبل", "برگشتبهخانه", "بازگشتبهصفحهیاصلی", "بازگشتبهصفحهاصلی",
})
_NAV_INLINE_BACK_CBS = frozenset({"mbtn:home", "nav:back", "vsvc:home", "vsvcback"})


def _nav_norm_label(t: str) -> str:
    return "".join(ch for ch in (t or "") if ch.isalpha()).replace("ٔ", "").replace("ي", "ی")


def _is_inline_nav_button(b) -> bool:
    cb = str(getattr(b, "callback_data", "") or "")
    return cb in _NAV_INLINE_BACK_CBS or _nav_norm_label(getattr(b, "text", "")) in _NAV_INLINE_BACK_TEXTS


_STAFF_PAGE_CB_PREFIXES = ("tadm:", "tvpn:", "sadm:", "smm:", "cfg:", "cfgf:", "set:", "usr:", "bc:", "vcadm:", "kyc:")
_CUSTOMER_NAV_CBS = ("mbtn:home", "nav:back", "vsvc:home", "vsvcback", "vc:home")


def _is_customer_nav_page(mk) -> bool:
    """PATCH_NAV_KB_ONLY_STAFF_V1 — صفحه‌ایِ از منویِ مشتری (دکمهٔ خانه/بازگشتِ مشتری دارد و دکمهٔ مدیریتی ندارد).
    مالک وقتی رباتِ خودش را تست می‌کند همین صفحه‌ها را می‌بیند؛ پس «بازگشت فقط در کیبورد» رویشان هم اعمال می‌شود.
    صفحه‌هایِ پنلِ مدیریت (tadm:/tvpn:/…) هرگز دست نمی‌خورند."""
    if not isinstance(mk, InlineKeyboardMarkup):
        return False
    cbs = [str(getattr(b, "callback_data", "") or "") for r in mk.inline_keyboard for b in r]
    if any(c.startswith(_STAFF_PAGE_CB_PREFIXES) for c in cbs):
        return False
    return any(c in _CUSTOMER_NAV_CBS or c.startswith("smopen:") for c in cbs)


def strip_inline_nav(mk):
    """دکمه‌هایِ بازگشت/خانهٔ شیشه‌ای را برمی‌دارد؛ ردیف‌هایِ خالی‌شده حذف می‌شوند. اگر چیزی نماند None."""
    if not isinstance(mk, InlineKeyboardMarkup):
        return mk
    rows = [[b for b in r if not _is_inline_nav_button(b)] for r in mk.inline_keyboard]
    rows = [r for r in rows if r]
    return InlineKeyboardMarkup(inline_keyboard=rows) if rows else None


async def flow_back_kb(msg: Message, bot_id: int):
    """جایگزین کیبورد منو در صفحه‌های مرحله‌ای خرید: فقط «⬅️ بازگشت به منو» (همیشه دیده می‌شود).
    اگر مالک «بازگشت فقط در کیبورد» را روشن کرده باشد، «🏠 بازگشت به خانه» هم کنارش می‌آید."""
    uid = msg.from_user.id
    _flow_kb_mark(bot_id, uid, _last_menu_for(bot_id))
    _row = [KeyboardButton(text=BTN_BACK_MENU)]
    if await nav_kb_only(bot_id):
        _row.append(KeyboardButton(text=BTN_HOME_FLOW))
    kb = ReplyKeyboardMarkup(keyboard=[_row], resize_keyboard=True, is_persistent=True)
    return await _send_kb_bubble(msg, bot_id, kb)


async def _cur_uid_mw(handler, event, data):
    u = getattr(event, "from_user", None)
    tok = _CUR_UID.set(u.id if u else None)
    try:
        _nav_install(data.get("bot"))
        _nav_seed(event)
        txt = getattr(event, "text", None)
        if u and isinstance(txt, str) and txt.startswith("/start"):
            for k in [k for k in _LAST_MENU if k[1] == u.id]:
                _LAST_MENU.pop(k, None)
        return await handler(event, data)
    finally:
        _CUR_UID.reset(tok)


tenant_router.callback_query.outer_middleware(_cur_uid_mw)
tenant_router.message.outer_middleware(_cur_uid_mw)


# === PATCH_ADMIN_CB_GUARD_V1 ===
# callback_data را تلگرام اعتبارسنجی نمی‌کند: با یک کلاینتِ MTProto هر کاربری
# می‌تواند هر رشته‌ای بفرستد، نه فقط دکمه‌هایی که دیده. بخشی از هندلرهایِ
# مدیریتی (حذف/ویرایشِ محصول در فروشگاه، اسلایدها، نوبت‌دهی، نظرسنجی، تأییدِ
# نظر، …) خودشان مالک/ادمین بودن را چک نمی‌کردند و چون رکورد را فقط با id
# می‌خواندند، حتی دادهٔ ربات‌هایِ دیگر را هم تغییر می‌دادند. این گارد برایِ
# پیشوندهایی که *فقط* در پنلِ مدیریت ساخته می‌شوند، قبل از هر هندلری مالک یا
# ادمینِ همین ربات بودن را الزامی می‌کند (چکِ سخت‌گیرانه‌ترِ خودِ هندلرها سرِ جایش می‌ماند).
_ADMIN_ONLY_CB_PREFIXES = (
    "tadm:", "sadm:", "shopadd:", "badm:", "sla:",
    "poll:adm:", "poll:toggle:", "poll:del:", "poll:new", "poll:send:", "poll:setgroup",
    "review:approve:",
    "cfg:", "cfgf:", "bc:", "adjdeduct:",
    # تأیید/ردِ سفارش و نوبت توسطِ ادمین — قبلاً هیچ چکی نداشتند: مشتری می‌توانست
    # سفارشِ کارت‌به‌کارتِ خودش را با callbackِ دست‌ساز «تأیید» کند و محصول را
    # بدونِ پرداخت بگیرد.
    "shop:confirm:", "shop:reject", "shop:giftdone:",
    "book:confirm:", "book:reject:",
    "set:", "usr:", "cfef:", "chp:",
)


async def _admin_cb_guard_mw(handler, event, data):
    cb_data = getattr(event, "data", None) or ""
    if not cb_data.startswith(_ADMIN_ONLY_CB_PREFIXES):
        return await handler(event, data)
    bot = data.get("bot")
    row = await get_bot_row(bot) if bot is not None else None
    if row and event.from_user and await is_owner_or_admin(row.id, event.from_user.id, row.owner_id):
        return await handler(event, data)
    logger.warning("admin_cb_guard: callbackِ مدیریتی از کاربرِ غیرمجاز رد شد "
                   "(bot_id=%s user=%s data=%r)", getattr(row, "id", None),
                   getattr(event.from_user, "id", None), cb_data[:64])
    try:
        await event.answer()
    except Exception:
        logger.debug("admin_cb_guard: پاسخ به callback ممکن نشد", exc_info=True)
    return None


tenant_router.callback_query.outer_middleware(_admin_cb_guard_mw)
