async def pay_method_kb_full(bot_id: int, oid: int) -> InlineKeyboardMarkup:
    """کیبورد انتخابِ روش پرداختِ سفارش، شاملِ روش‌های مستقیمِ پرداختِ همان سفارش:
    کیف پول (کسر از موجودی) و کارت‌به‌کارت (اگر فعال باشد). گزینه‌های «شارژ
    کیف‌پول» (ارز دیجیتال/سواپ‌ولت) فقط وقتی نشان داده می‌شوند که مالک از
    تنظیماتِ مالی صراحتاً روشنش کرده باشد (پیش‌فرض خاموش).
    """
    # === PATCH_WALLET_PAY_TOGGLE_V1 ===
    rows = ([[InlineKeyboardButton(text="💰 پرداخت از کیف پول",
                                   callback_data=f"pay:wallet:{oid}")]]
            if await wallet_pay_on(bot_id) else [])

    # کارت‌به‌کارت فقط وقتی نشان داده می‌شود که هم کلاً فعال باشد و هم در بخشِ
    # «خرید» غیرفعال نشده باشد (card_purchase_enabled). قبلاً فقط card_enabled
    # چک می‌شد و دکمه با وجودِ غیرفعال‌بودن در خرید نمایش داده می‌شد.
    card_enabled = await get_setting(bot_id, "card_enabled", "1")
    card_purchase_enabled = await get_setting(bot_id, "card_purchase_enabled", "1")
    _ab_repl_o = await _ab_replaces_card(bot_id)   # === PATCH_ABANGATEWAY_REPLACE_CARD_V1 ===
    if card_enabled == "1" and card_purchase_enabled == "1" and not _ab_repl_o:
        rows.append([InlineKeyboardButton(text="💳 کارت‌به‌کارت",
                                          callback_data=f"pay:card:{oid}")])

    # === PATCH_TONPAYS_VISIBILITY_V1 ===
    # تون‌پیز تیکِ نمایشِ مستقلِ خودش را دارد و به تیکِ عمومیِ «شارژ کیف‌پول در
    # صفحهٔ خرید» گره نخورده، چون یک روشِ پرداختِ ریالیِ مستقیم است نه صرفاً
    # شارژِ کیف‌پول.
    # === PATCH_TONPAYS_DISPLAY_NAME_V1 ===
    from tenant.gateways.tonpays import (is_available as _tonp_ok2,
                                get_display_name as _tonp_name2)
    if await _tonp_ok2(bot_id) and \
            await get_setting(bot_id, "tonpays_show_purchase", "1") == "1":
        rows.append([InlineKeyboardButton(
            text=await gw_btn(bot_id, 'tonpays', 'پرداخت با', '💠'), callback_data="w:tonpays")])

    try:
        from tenant.gateways.hesabpay import is_available as _hb_product_ok
        if await get_setting(bot_id, "hesabpay_show_purchase", "0") == "1" and \
                await _hb_product_ok(bot_id):
            rows.append([InlineKeyboardButton(
                text=await gw_btn(bot_id, 'hesabpay', 'پرداخت با', '🇦🇫'), callback_data="w:hesabpay")])
    except Exception:
        logger.exception("بررسیِ حساب‌پی در روش‌های پرداخت محصول ناموفق بود")

    if await get_setting(bot_id, "wallet_charge_in_purchase_enabled", "0") == "1":
        # ارز دیجیتال (نوپیمنت) — فقط اگر درگاه تنظیم و فعال است
        nowpay_key = await get_setting(bot_id, "nowpay_api_key", "")
        nowpay_enabled = await get_setting(bot_id, "nowpay_enabled", "1")
        if bool(nowpay_key) and nowpay_enabled == "1":
            rows.append([InlineKeyboardButton(
                text="🪙 شارژ کیف پول با ارز دیجیتال", callback_data="w:crypto")])

        # سواپ‌ولت — فقط اگر تنظیم شده است
        swap_on = bool(await get_setting(bot_id, "swap_api_key", "")) and \
            bool(await get_setting(bot_id, "swap_addr_usdt", "") or
                 await get_setting(bot_id, "swap_addr_ton", "") or
                 await get_setting(bot_id, "swap_addr_trx", ""))
        if swap_on:
            rows.append([InlineKeyboardButton(
                text="🟦 شارژ کیف پول با سواپ‌ولت", callback_data="w:swap")])

    # === PATCH_UNIQUEPAY_PURCHASE_VISIBILITY_V1 ===
    # تیکِ مستقلِ «نمایش موقعِ پرداختِ محصول» — به تیکِ عمومیِ
    # wallet_charge_in_purchase_enabled گره نخورده، دقیقاً مثلِ تون‌پیز.
    try:
        from tenant.gateways.uniquepay import is_available as _up_ok2
        if await get_setting(bot_id, "uniquepay_show_purchase", "1") == "1" and \
                await _up_ok2(bot_id):
            rows.append([InlineKeyboardButton(
                text=await gw_btn(bot_id, 'uniquepay', 'پرداخت با', '💳'), callback_data="w:uniquepay")])
    except Exception:
        logger.exception("بررسیِ دسترسیِ یونیک‌پی ناموفق بود")

    # === PATCH_APAY_GATEWAY_V1 ===
    try:
        from tenant.gateways.apay import is_available as _ap_ok2
        if await get_setting(bot_id, "apay_show_purchase", "1") == "1" and \
                await _ap_ok2(bot_id):
            rows.append([InlineKeyboardButton(
                text=await gw_btn(bot_id, 'apay', 'پرداخت با', '💳'),
                callback_data=f"w:apay:{oid}")])     # === PATCH_APAY_DIRECT_PURCHASE_V1 === پرداختِ مستقیمِ همین سفارش
    except Exception:
        logger.exception("بررسیِ دسترسیِ آپی ناموفق بود")

    # === PATCH_ABANGATEWAY_V1 ===
    # === PATCH_GATEWAY_PAY_FOR_ORDER_V1 ===
    # شمارهٔ سفارش داخلِ callback حمل می‌شود تا درگاه بداند این پرداخت برایِ
    # کدام سفارش است. قبلاً همان دکمهٔ عمومیِ «شارژِ کیف‌پول» بود: کاربر باید
    # مبلغ را خودش حدس می‌زد، پول می‌رفت تو کیف‌پول، و بعد باید دستی
    # برمی‌گشت رویِ سفارش — سه قدمِ اضافه و جایِ اشتباهِ زیاد.
    try:
        from tenant.gateways.abangateway import is_available as _ab_ok2, get_display_name as _ab_name2
        if (_ab_repl_o or
                await get_setting(bot_id, "abangateway_show_purchase", "1") == "1") and \
                await _ab_ok2(bot_id):
            rows.append([InlineKeyboardButton(
                text=await gw_btn(bot_id, 'abangateway', 'پرداخت با', '💳'),
                callback_data=f"w:abangateway:{oid}")])
    except Exception:
        logger.exception("بررسیِ دسترسیِ آبان گیت‌وی ناموفق بود")

    if not _has_wallet_charge_btn(rows):
        rows.extend(await wallet_charge_btn_rows(bot_id))   # PATCH_WALLET_CHARGE_BTN_V1
    rows.append([InlineKeyboardButton(text="❌ لغو سفارش",
                                      callback_data=f"pay:cancel:{oid}")])
    return InlineKeyboardMarkup(inline_keyboard=rows)


# === PATCH_PAYLOAD_MULTILINK_V1 ===
_PAYLOAD_URL_RE = re.compile(r'[A-Za-z][A-Za-z0-9+.\-]*://[^\s<>"]+')


def _fmt_payload_html(payload: str) -> tuple[str, bool]:
    """متنِ تحویلِ کانفیگ را برایِ HTMLِ تلگرام آماده می‌کند.

    کانفیگِ دستی گاهی «توضیح + چند لینک» است (مثلاً SSH با یک لینک برایِ اندروید و
    یکی برایِ آیفون). قبلاً کلِ متن داخلِ یک <code> می‌رفت، پس لمس‌کردن *همه‌چیز* را
    کپی می‌کرد. اگر متن هم توضیحِ عادی دارد هم لینک، هر لینک جدا داخلِ <code> می‌رود
    (لمسش فقط همان لینک را کپی می‌کند) و توضیح‌ها متنِ ساده می‌مانند.
    خروجی: (html, mixed). اگر فقط لینک(ها) یا فقط متن باشد، رفتارِ قبلی بدونِ تغییر
    (mixed=False)."""
    p = (payload or "").strip()
    urls = list(_PAYLOAD_URL_RE.finditer(p))
    if not urls or not _PAYLOAD_URL_RE.sub("", p).strip():
        return f"<code>{p}</code>", False
    out, pos = [], 0
    for m in urls:
        url = m.group(0)
        tail = ""
        while url and url[-1] in ".,;:!?)،؛":
            tail = url[-1] + tail
            url = url[:-1]
        out.append(_html.escape(p[pos:m.start()]))
        out.append(f"<code>{_html.escape(url)}</code>" + _html.escape(tail))
        pos = m.end()
    out.append(_html.escape(p[pos:]))
    return "".join(out), True


def _is_sub_link(payload: str) -> bool:
    """بررسی می‌کند که payload یک ساب‌لینک HTTP است یا کانفیگ تکی."""
    p = payload.strip()
    return p.startswith("http://") or p.startswith("https://")


async def _fetch_single_configs(sub_url: str) -> list[str]:
    """ساب‌لینک را fetch کرده، base64 decode می‌کند و لیست کانفیگ‌های تکی برمی‌گرداند."""
    import base64
    try:
        import aiohttp
        async with aiohttp.ClientSession() as session:
            async with session.get(sub_url, timeout=aiohttp.ClientTimeout(total=10)) as resp:
                body = await resp.read()
        # decode base64 اگر لازم باشد
        try:
            decoded = base64.b64decode(body).decode("utf-8", errors="ignore")
        except Exception:
            decoded = body.decode("utf-8", errors="ignore")
        lines = [ln.strip() for ln in decoded.splitlines() if ln.strip()]
        # فقط لینک‌های معتبر کانفیگ
        valid_prefixes = ("vless://", "vmess://", "trojan://", "ss://", "hysteria2://",
                          "hy2://", "tuic://", "wireguard://")
        return [ln for ln in lines if any(ln.startswith(p) for p in valid_prefixes)]
    except Exception:
        return []


