# === PATCH_WIREGUARD_SUBLINK_V1 ===
def _wg_payload_is_link(payload: str) -> bool:
    """آیدیِ فایلِ تلگرامی هیچ‌وقت با http شروع نمی‌شه؛ اگه payload یه
    لینکِ ساب باشه (نه فایلِ آپلودشده)، این تشخیصش می‌ده."""
    return (payload or "").strip().lower().startswith(("http://", "https://"))


# === PATCH_OPENVPN_CONFIG_V1 ===
# OpenVPN دقیقاً همان ساختارِ وایرگارد را دارد (فایل به‌جایِ لینک)، پس
# به‌جایِ یک فلوی موازی، همان مسیر با kind="openvpn" استفاده می‌شود و
# فقط برچسب/پسوند/نامِ اپ فرق می‌کند.
FILE_KINDS = ("wireguard", "openvpn")

_KIND_META = {
    "wireguard": {"label": "وایرگارد", "app": "WireGuard", "ext": ".conf",
                  "icon": "🛡️"},
    "openvpn":   {"label": "اوپن‌وی‌پی‌ان", "app": "OpenVPN", "ext": ".ovpn",
                  "icon": "🔐"},
}


def _kind_meta(kind: str) -> dict:
    return _KIND_META.get(kind or "", _KIND_META["wireguard"])


async def _send_wg_config_to_user(bot: Bot, tg_id: int, cfg: Config):
    """تحویلِ کانفیگِ وایرگارد: یا فایلِ .conf رو می‌فرسته (+ QR از رویِ
    محتواش)، یا اگه ادمین به‌جایِ فایل یه لینکِ ساب ثبت کرده باشه، همون
    لینک رو به‌شکلِ متنی/کلیک‌پذیر می‌فرسته."""
    vol = "نامحدود" if cfg.volume_gb == 0 else f"{cfg.volume_gb} گیگ"
    dur = "بی‌انقضا" if cfg.days == 0 else f"{cfg.days} روز"
    _clabel = getattr(cfg, "custom_label", None)
    _label_line = f"✏️ نام: <b>{_clabel}</b>\n" if _clabel else ""
    _mcfg_delivery_note = ""
    row = None
    try:
        row = await get_bot_row(bot)
        if row:
            # === PATCH_MCFG_NOTE_CATMAP_V1 ===
            _dn = await get_mcfg_note_cat(
                row.id, "delivery", "unlimited" if (cfg.volume_gb or 0) == 0 else "manual",
                getattr(cfg, "category", None))
            if _dn:
                _mcfg_delivery_note = f"📝 {_dn}\n\n"
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")

    # === PATCH_WIREGUARD_SUBLINK_V1 ===
    if _wg_payload_is_link(cfg.payload):
        _m = _kind_meta(cfg.kind)  # === PATCH_OPENVPN_CONFIG_V1 ===
        # === PATCH_MCFG_LINK_NO_APP_INSTRUCTION_V1 ===
        # قبلاً همیشه زیرِ لینک این‌جوری نوشته می‌شد: «این لینک رو تو اپِ
        # WireGuard از Add from URL وارد کن» — ولی وقتی ادمین یه کانفیگِ
        # وایرگارد/اوپن‌وی‌پی‌انِ *دستی* رو به‌شکلِ لینک (نه فایل) ثبت می‌کنه،
        # این لینک لزوماً یه ساب‌لینکِ قابلِ ایمپورتِ مستقیم تو اپِ رسمی
        # نیست (مثلاً یه فرمتِ دیگه یا راهنمای متفاوتی داره) و این دستورالعملِ
        # ثابت گمراه‌کننده بود. حالا حذف شد؛ اگه ادمین راهنمای اتصال دلخواه
        # داشته باشه، همون از طریقِ دکمهٔ راهنما (_cfg_guide_row) پایین
        # همین پیام نشون داده می‌شه.
        header = (
            f"✅ کانفیگِ {_m['label']} شما آماده است\n\n"
            f"📦 کد اختصاصی: <b>{cfg.code}</b>\n"
            f"🗂 حجم: {vol} | مدت: {dur}\n"
            f"{_label_line}"
            f"{_mcfg_delivery_note}"
            f"🔗 لینکِ ساب:\n<code>{cfg.payload.strip()}</code>"
        )
        kb_rows = []
        try:
            if row:
                _gr = await _cfg_guide_row(row.id, "unlimited" if (cfg.volume_gb or 0) == 0 else "manual",
                                           category=getattr(cfg, "category", None))
                if _gr:
                    kb_rows.append(_gr)
                _br = await inline_back_row(row.id)
                if _br:
                    kb_rows.append(_br)
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        try:
            await bot.send_message(tg_id, header,
                                   reply_markup=InlineKeyboardMarkup(inline_keyboard=kb_rows) if kb_rows else None)
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (ارسالِ لینکِ سابِ وایرگارد)")
        return

    _m = _kind_meta(cfg.kind)  # === PATCH_OPENVPN_CONFIG_V1 ===
    header = (
        f"✅ کانفیگِ {_m['label']} شما آماده است\n\n"
        f"📦 کد اختصاصی: <b>{cfg.code}</b>\n"
        f"🗂 حجم: {vol} | مدت: {dur}\n"
        f"{_label_line}"
        f"{_mcfg_delivery_note}"
        f"📎 فایلِ کانفیگ رو باز کن یا مستقیم تو اپِ {_m['app']} اسکنش کن."
    )
    kb_rows = [[InlineKeyboardButton(text=f"📄 ارسال کانفیگ {_m['label']}", callback_data=f"cfgdl:wg:{cfg.id}", style=ButtonStyle.PRIMARY)]]
    try:
        if row:
            _gr = await _cfg_guide_row(row.id, "unlimited" if (cfg.volume_gb or 0) == 0 else "manual",
                                       category=getattr(cfg, "category", None))
            if _gr:
                kb_rows.append(_gr)
            _br = await inline_back_row(row.id)
            if _br:
                kb_rows.append(_br)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    kb = InlineKeyboardMarkup(inline_keyboard=kb_rows)

    # === PATCH_WG_QR_ABOVE_FILE_V1 ===
    # قبلاً اول خودِ فایل فرستاده می‌شد، بعد QR زیرش (به‌عنوانِ یه پیامِ
    # جدا) — کاربر می‌خواست QR بالای فایل باشه. الان اول QR رو (از روی
    # محتوای متنیِ فایل) می‌سازیم و با کپشنِ اصلی + دکمه‌ها می‌فرستیم، بعد
    # خودِ فایل رو زیرش.
    qr_png = None
    try:
        buf = io.BytesIO()
        await bot.download(cfg.payload, destination=buf)
        conf_text = buf.getvalue().decode("utf-8", errors="ignore")
        if conf_text.strip():
            qr_png = await _qr_png_cfg(cfg.bot_id, conf_text)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (ساختِ QR فایلِ وایرگارد)")

    try:
        if qr_png:
            await bot.send_photo(
                tg_id, BufferedInputFile(qr_png, filename="wg_qr.png"),
                caption=header, reply_markup=kb)
        else:
            await bot.send_message(tg_id, header, reply_markup=kb)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (ارسالِ QR/پیامِ اصلیِ تحویلِ وایرگارد)")

    try:
        await bot.send_document(tg_id, cfg.payload,
                                caption="📎 فایلِ کانفیگ — این رو مستقیم تو اپِ WireGuard ایمپورت کن.")
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (ارسالِ فایلِ وایرگارد در تحویلِ اولیه)")


async def _send_panel_to_user(bot: Bot, tg_id: int, cfg: Config):
    """PATCH_VPN_PANEL_MARKET_V1 — تحویلِ یه پنلِ فروخته‌شده: بجایِ کانفیگِ
    VPN، آدرس/یوزرنیم/پسوردِ پنل رو با متنِ شیک + دکمه‌هایِ کپیِ جدا برایِ
    هرکدوم می‌فرسته."""
    try:
        data = json.loads(cfg.payload) or {}
    except Exception:
        data = {}
    name = data.get("name") or (getattr(cfg, "custom_label", None) or f"پنل #{cfg.code}")
    address = data.get("address") or "—"
    username = data.get("username") or "—"
    password = data.get("password") or "—"
    _mcfg_delivery_note = ""
    try:
        row = await get_bot_row(bot)
        if row:
            _dn = await get_mcfg_note(row.id, "delivery")
            if _dn:
                _mcfg_delivery_note = f"📝 {_dn}\n\n"
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    # === PATCH_PANEL_MARKET_FIX_V2 === رمز/آدرس ممکن است < یا & داشته باشد → بدونِ escape تلگرام پیام را رد می‌کرد
    # و خریدار هیچ‌چیز دریافت نمی‌کرد.
    _raw_name, _raw_addr, _raw_user, _raw_pass = name, address, username, password
    _extra_info = ""   # PATCH_PANEL_SHOP_OPTIONAL_V1
    for _k, _ic, _lb in (("traffic", "📦", "حجم"), ("duration", "📅", "مدت"),
                         ("inbounds", "🔌", "اینباندها"), ("features", "✨", "قابلیت‌ها")):
        if data.get(_k):
            _extra_info += f"{_ic} {_lb}: {_html.escape(str(data[_k]))}\n"
    if _extra_info:
        _extra_info += "\n"
    name, address, username, password = (_html.escape(str(x)) for x in (name, address, username, password))
    header = (
        f"✅ <b>پنلِ شما آماده است!</b>\n\n"
        f"🏷 نام: <b>{name}</b>\n"
        f"📦 کد اختصاصی: <b>{cfg.code}</b>\n\n"
        f"{_mcfg_delivery_note}"
        f"🌐 آدرس:\n<code>{address}</code>\n\n"
        f"👤 یوزرنیم:\n<code>{username}</code>\n\n"
        f"🔑 پسورد:\n<code>{password}</code>\n\n"
        + _extra_info +
        f"از دکمه‌های زیر می‌تونی هرکدوم رو جدا کپی کنی 👇"
    )
    kb_rows = [
        [InlineKeyboardButton(text="📋 کپیِ آدرس", copy_text=CopyTextButton(text=str(_raw_addr)[:256] or "—"))],
        [InlineKeyboardButton(text="📋 کپیِ یوزرنیم", copy_text=CopyTextButton(text=str(_raw_user)[:256] or "—"))],
        [InlineKeyboardButton(text="📋 کپیِ پسورد", copy_text=CopyTextButton(text=str(_raw_pass)[:256] or "—"))],
    ]
    try:
        _br = await inline_back_row(cfg.bot_id)
        if _br:
            kb_rows.append(_br)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    try:
        await bot.send_message(tg_id, header, reply_markup=InlineKeyboardMarkup(inline_keyboard=kb_rows))
    except Exception:
        logger.exception("ارسالِ پنلِ فروخته‌شده ناموفق بود؛ تلاش بدونِ فرمت")
        try:
            _plain = (f"✅ پنلِ شما آماده است!\n\nنام: {_raw_name}\nکد: {cfg.code}\n\n"
                      f"آدرس: {_raw_addr}\nیوزرنیم: {_raw_user}\nپسورد: {_raw_pass}")
            await bot.send_message(tg_id, _plain, parse_mode=None,
                                   reply_markup=InlineKeyboardMarkup(inline_keyboard=kb_rows))
        except Exception:
            logger.exception("ارسالِ ساده‌یِ پنلِ فروخته‌شده هم ناموفق بود")


async def send_config_to_user(bot: Bot, tg_id: int, cfg: Config):
    """ارسال کانفیگ با QR کد + دکمه‌های اینلاین ارسال تکی / ساب‌لینک."""
    # === PATCH_VPN_PANEL_MARKET_V1 ===
    # فروشِ پنل (نه کانفیگِ VPN) یه فرمتِ تحویلِ کاملاً جدا داره: به‌جایِ
    # QR/فایل/لینک، آدرس+یوزرنیم+پسورد با دکمه‌هایِ کپیِ جدا.
    if cfg.kind == "panel":
        await _send_panel_to_user(bot, tg_id, cfg)
        return
    # === PATCH_WIREGUARD_CONFIG_V1 ===
    # کانفیگِ وایرگارد یه مسیرِ کاملاً جدا داره چون payload اینجا یه متنِ
    # لینک نیست، بلکه آیدیِ فایلِ تلگرامیِ یه فایلِ .conf واقعیه.
    # === PATCH_OPENVPN_CONFIG_V1 ===
    if cfg.kind in FILE_KINDS:
        await _send_wg_config_to_user(bot, tg_id, cfg)
        return
    payload = cfg.payload.strip()
    vol  = "نامحدود" if cfg.volume_gb == 0 else f"{cfg.volume_gb} گیگ"
    dur  = "بی‌انقضا" if cfg.days == 0 else f"{cfg.days} روز"
    _clabel = getattr(cfg, "custom_label", None)
    _label_line = f"✏️ نام: <b>{_clabel}</b>\n" if _clabel else ""
    _mcfg_delivery_note = ""
    try:
        row_for_note = await get_bot_row(bot)
        if row_for_note:
            # === PATCH_MCFG_NOTE_CATMAP_V1 ===
            _dn = await get_mcfg_note_cat(
                row_for_note.id, "delivery", "unlimited" if (cfg.volume_gb or 0) == 0 else "manual",
                getattr(cfg, "category", None))
            if _dn:
                _mcfg_delivery_note = f"📝 {_dn}\n\n"
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    header = (
        f"✅ کانفیگ شما آماده است\n\n"
        f"📦 کد اختصاصی: <b>{cfg.code}</b>\n"
        f"🗂 حجم: {vol} | مدت: {dur}\n"
        f"{_label_line}"
        f"{_mcfg_delivery_note}"
    )

    is_sub = _is_sub_link(payload)

    # کیبورد زیر پیام
    kb_rows = [[
        InlineKeyboardButton(
            text="📦 ارسال سرورهای تکی",
            callback_data=f"cfgdl:single:{cfg.id}", style=ButtonStyle.PRIMARY),
        InlineKeyboardButton(
            text="🔗 ارسال ساب‌لینک",
            callback_data=f"cfgdl:sub:{cfg.id}", style=ButtonStyle.PRIMARY),
    ]]
    try:
        row = await get_bot_row(bot)
        if row:
            _cfgsrc = "unlimited" if (cfg.volume_gb or 0) == 0 else "manual"
            _gr = await _cfg_guide_row(row.id, _cfgsrc, category=getattr(cfg, "category", None))
            if _gr:
                kb_rows.append(_gr)
            _br = await inline_back_row(row.id)
            if _br:
                kb_rows.append(_br)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    kb = InlineKeyboardMarkup(inline_keyboard=kb_rows)

    _pl_html, _pl_mixed = _fmt_payload_html(payload)
    if is_sub:
        # payload یک ساب‌لینک است — QR از روی آن
        caption = header + f"🔗 ساب‌لینک:\n<code>{payload}</code>"
        png = await _qr_png_cfg(cfg.bot_id, payload)
    elif _pl_mixed:
        # توضیح + چند لینک: هر لینک جدا قابلِ کپی؛ QRِ کلِ متن بی‌معنی است و
        # کپشنِ عکس هم سقفِ ۱۰۲۴ کاراکتر دارد (لینک‌هایِ SSH/NPV بلندند).
        caption = header + _pl_html
        png = None
    else:
        # payload یک کانفیگ تکی است
        caption = header + f"<code>{payload}</code>"
        png = await _qr_png_cfg(cfg.bot_id, payload)

    try:
        if png:
            await bot.send_photo(
                tg_id,
                BufferedInputFile(png, filename="config_qr.png"),
                caption=caption,
                reply_markup=kb,
            )
        else:
            await bot.send_message(tg_id, caption, reply_markup=kb)
    except Exception:
        # === PATCH_CONFIG_DELIVERY_RESILIENCE_V1 ===
        # قبلاً اگه این تلاشِ دومِ send_message هم شکست می‌خورد (مثلاً تایم‌اوتِ
        # شبکه — دقیقاً همون خطایی که تلاشِ اول رو fail کرده بود، احتمالاً
        # بازم fail می‌شد)، استثنا بدونِ گرفته‌شدن تا صدازننده بالا می‌رفت و
        # کلِ هندلرِ خرید (که این تابع رو بعدِ کسرِ موجودی/کامیتِ سفارش صدا
        # می‌زد) کرش می‌کرد — نتیجه: پول کسر شده، سفارش paid شده، ولی نه
        # پیامی به کاربر می‌رسید، نه اعلانِ خرید به ادمین اجرا می‌شد. کانفیگ
        # خودش تو دیتابیس assign شده و از «سرویس‌های من» قابلِ بازیابی بود،
        # ولی کاربر هیچ نشونه‌ای نمی‌دید و فکر می‌کرد پولش رفته هوا.
        try:
            await bot.send_message(
                tg_id,
                f"✅ کانفیگ شما:\n\n{_pl_html}\n\nکد: {cfg.code}",
                reply_markup=kb,
            )
        except Exception:
            logger.exception(
                "ارسالِ کانفیگ به کاربر ناموفق بود (هر دو تلاش)؛ کانفیگ "
                f"tg_id={tg_id} cfg_id={cfg.id} همچنان در «سرویس‌های من» موجود است."
            )
            raise


# ─────────── دکمه‌های «ارسال سرورهای تکی» و «ارسال ساب‌لینک» ───────────

@tenant_router.callback_query(F.data.startswith("cfgdl:"))
async def cfgdl_handler(cb: CallbackQuery, bot: Bot):
    """ارسال سرورهای تکی یا ساب‌لینک برای کانفیگ خریداری‌شده."""
    parts = cb.data.split(":")
    action  = parts[1]          # "single" | "sub" | "wg"
    cfg_id  = int(parts[2])

    row = await get_bot_row(bot)
    if not row:
        await cb.answer()
        return

    async with Session() as s:
        cfg = await s.get(Config, cfg_id)

    if not cfg or cfg.bot_id != row.id:
        await cb.answer("کانفیگ یافت نشد.", show_alert=True)
        return

    await cb.answer()

    # === PATCH_WIREGUARD_CONFIG_V1 / PATCH_WIREGUARD_SUBLINK_V1 ===
    if action == "wg":
        # === PATCH_OPENVPN_CONFIG_V1 ===
        if cfg.kind not in FILE_KINDS:
            await cb.message.answer("⚠️ این کانفیگ فایلی نیست.")
            return
        if _wg_payload_is_link(cfg.payload):
            await cb.message.answer(
                f"🔗 لینکِ ساب — کد {cfg.code}:\n<code>{cfg.payload.strip()}</code>")
            return
        try:
            await bot.send_document(cb.from_user.id, cfg.payload,
                                    caption=f"📄 کانفیگِ وایرگارد — کد {cfg.code}")
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (ارسالِ مجددِ فایلِ وایرگارد)")
            await cb.message.answer("⚠️ ارسالِ فایل با خطا مواجه شد؛ دوباره امتحان کن.")
        return

    payload = cfg.payload.strip()
    is_sub  = _is_sub_link(payload)

    if action == "sub":
        # ─── ارسال ساب‌لینک ───
        if is_sub:
            sub_url = payload
        else:
            # کانفیگ تکی است؛ ساب‌لینکی نداریم
            await cb.message.answer(
                "⚠️ این کانفیگ به‌صورت سرور تکی ذخیره شده و ساب‌لینک ندارد."
            )
            return

        png = await _qr_png_cfg(row.id, sub_url)
        text = f"🔗 <b>ساب‌لینک شما:</b>\n<code>{sub_url}</code>"
        try:
            if png:
                await cb.message.answer_photo(
                    BufferedInputFile(png, filename="sub_qr.png"),
                    caption=text,
                )
            else:
                await cb.message.answer(text)
        except Exception:
            await cb.message.answer(text)

    elif action == "single":
        # ─── ارسال سرورهای تکی ───
        if is_sub:
            # payload ساب‌لینک است؛ fetch و parse کن
            configs = await _fetch_single_configs(payload)
            if not configs:
                await cb.message.answer(
                    "⚠️ نتوانستیم سرورهای تکی را از ساب‌لینک دریافت کنیم.\n"
                    "ممکن است ساب‌لینک موقتاً در دسترس نباشد."
                )
                return
        else:
            # خودش یک کانفیگ تکی است
            configs = [payload]

        if len(configs) == 1:
            # یک سرور: با QR بفرست
            _one_html, _one_mixed = _fmt_payload_html(configs[0])
            png = None if _one_mixed else await _qr_png_cfg(row.id, configs[0])
            text = f"📦 <b>کانفیگ تکی:</b>\n{_one_html}"
            try:
                if png:
                    await cb.message.answer_photo(
                        BufferedInputFile(png, filename="cfg_qr.png"),
                        caption=text,
                    )
                else:
                    await cb.message.answer(text)
            except Exception:
                await cb.message.answer(text)
        else:
            # چند سرور: هر کدام جداگانه
            await cb.message.answer(
                f"📦 <b>سرورهای تکی ({len(configs)} عدد):</b>\n"
                "هر سرور را جداگانه دریافت می‌کنی:"
            )
            for i, cfg_line in enumerate(configs, 1):
                png = await _qr_png_cfg(row.id, cfg_line)
                text = f"🌐 سرور {i}:\n<code>{cfg_line}</code>"
                try:
                    if png:
                        await cb.message.answer_photo(
                            BufferedInputFile(png, filename=f"server_{i}_qr.png"),
                            caption=text,
                        )
                    else:
                        await cb.message.answer(text)
                except Exception:
                    await cb.message.answer(text)


