class ChannelPostFSM(StatesGroup):
    """ویزارد اتصال کانال + ساخت و ارسال پست (با دکمهٔ اینلاینِ لینک) — فقط پلن حرفه‌ای."""
    wait_channel = State()    # دریافت فوروارد یا یوزرنیمِ کانالِ مقصد
    wait_content = State()    # دریافت متن یا عکسِ پست
    wait_btn_label = State()  # دریافت متنِ دکمه
    wait_btn_url = State()    # دریافت لینکِ دکمه
    # === PATCH_CHPOST_ATTACH_EXISTING_V1 ===
    wait_target_msg = State()  # دریافت فوروارد/لینکِ پستی که خودِ ادمین مستقیم در کانال گذاشته
    wait_attach_idle = State()  # حالتِ «در حالِ چیدنِ دکمه برای پستِ موجود» (معادلِ wait_content ولی بدونِ محتوای جدید)
    # === PATCH_CHPOST_DETACH_EXISTING_V1 ===
    wait_detach_target = State()  # دریافت فوروارد/لینکِ پستی که می‌خواهیم دکمه(ها) را از زیرش برداریم


class HomeBtnFSM(StatesGroup):
    rename = State()
    rule = State()
    new_label = State()   # افزودن دکمهٔ دلخواه: دریافت نام
    edit_msg = State()     # تنظیم متنِ دکمه
    btn_range = State()    # بازهٔ اختصاصی دکمهٔ فروش کانفیگ (vols/days/counts)
    set_emoji = State()    # دریافت ایموجی پرمیوم برای دکمه
    set_btn_support = State()  # دریافت آدرس پشتیبانِ اختصاصیِ یک دکمه
    move_row = State()     # جابه‌جایی دکمه: انتخاب ردیف مقصد
    move_pos = State()     # جابه‌جایی دکمه: انتخاب موقعیت
    set_webapp_url = State()  # دریافت لینک مینی‌اپ (Web App) برای دکمه
    set_link_url = State()    # PATCH_BUTTON_CHANNEL_LINK_V1 — لینکِ مستقیمِ کانال/گروه/سایت
    set_command = State()     # دریافت کامند سفارشی دکمه (مثلاً /wallet)
    exdisc_code = State()     # دریافت متنِ کد تخفیف اختصاصیِ دکمه
    exdisc_percent = State()  # دریافت درصدِ کد تخفیف اختصاصیِ دکمه
    exdisc_amount = State()   # دریافت مبلغِ ثابتِ تخفیف (تومان) کد تخفیف اختصاصیِ دکمه
