# === PATCH_SLIDESHOW_ENHANCEMENTS_V1 ===
async def _maybe_show_slideshow(msg: Message, bot: Bot, bot_id: int,
                                 slide_target: tuple[int, int] | None, field: str | None = None):
    """بعدِ خوش‌آمدِ عادیِ /start، اگه لازم بود یه اسلایدشو هم نشون می‌ده:
    اول اولویت با دیپ‌لینکِ اشتراک‌گذاری (slide_target)ه؛ اگه نبود، اگه
    ادمین یه اسلایدشو رو «نمایشِ خودکار موقعِ /start» پین کرده باشه،
    همون نشون داده می‌شه.

    === PATCH_SLIDESHOW_FIELD_RESTRICT_V1 ===
    نمایشِ خودکارِ اسلایدشو موقعِ /start (حالتِ «پین») مختصِ ربات‌هایِ
    تبلیغاتی/فروشگاهیه (ad_bot / digital_shop) — برایِ بقیهٔ زمینه‌ها
    (مثلاً vpn_sales) عمداً نشون داده نمی‌شه، حتی اگه قبلاً یه اسلایدشو
    پین شده باشه؛ فقط لینکِ اشتراک‌گذاریِ مستقیم (slide_target) که کاربر
    خودش صریح روش کلیک کرده، دست‌نخورده می‌مونه."""
    try:
        from tenant.shared.slideshow import show_slideshow_to_user, _get_setting_local, _pin_start_key
        if slide_target:
            button_id, step_num = slide_target
            await show_slideshow_to_user(msg, button_id, bot, start_step=step_num)
            return
        if field not in ("ad_bot", "digital_shop"):
            return
        pinned = await _get_setting_local(bot_id, _pin_start_key(bot_id), "")
        if pinned:
            await show_slideshow_to_user(msg, int(pinned), bot)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (نمایشِ اسلایدشو موقعِ /start)")


# === PATCH_MINIAPP_VSERVICES_V1 ===
async def _open_vservice_shop(msg, bot, bot_id: int, action: str, state) -> bool:
    """بازکردنِ فروشگاهِ یک محصولِ خدماتِ مجازی از دیپ‌لینکِ مینی‌اپ.

    هیچ منطقِ خریدی اینجا بازسازی نمی‌شود؛ فقط همان توابعِ کاربریِ موجود
    (که دکمه‌هایِ صفحهٔ اصلی هم از آنها استفاده می‌کنند) صدا زده می‌شوند.
    """
    try:
        if action == "gift_shop":
            from tenant.bots.virtual_service.smm import show_gift_shop_to_user
            await show_gift_shop_to_user(bot, msg, bot_id)
        elif action == "premium_shop":
            from tenant.bots.virtual_service.smm import show_premium_shop_to_user
            await show_premium_shop_to_user(bot, msg, bot_id)
        elif action == "stars_shop":
            from tenant.bots.virtual_service.smm import show_stars_shop_to_user
            await show_stars_shop_to_user(bot, msg, bot_id, state)
        elif action == "ton_shop":
            from tenant.bots.virtual_service.smm import show_ton_shop_to_user
            await show_ton_shop_to_user(bot, msg, bot_id, state)
        elif action == "star_reaction_shop":
            from tenant.bots.virtual_service.smm import srx_show_shop
            await srx_show_shop(bot, msg, bot_id, state)
        elif action == "vnum_shop":
            from tenant.bots.virtual_service.smm import show_vnum_shop_to_user
            await show_vnum_shop_to_user(bot, msg, bot_id)
        elif action == "vnum_shop_manual":  # === PATCH_VNUM_SHOP_SPLIT_V1 ===
            from tenant.bots.virtual_service.smm import show_vnum_shop_to_user
            await show_vnum_shop_to_user(bot, msg, bot_id, only="manual")
        elif action == "vnum_shop_auto":  # === PATCH_VNUM_SHOP_SPLIT_V1 ===
            from tenant.bots.virtual_service.smm import show_vnum_shop_to_user
            await show_vnum_shop_to_user(bot, msg, bot_id, only="auto")
        elif action == "smm_shop":
            from tenant.bots.virtual_service.smm import show_smm_services_to_user
            await show_smm_services_to_user(bot, msg, bot_id)
        elif action == "smm_myorders":
            from tenant.bots.virtual_service.smm import show_smm_myorders_to_user
            await show_smm_myorders_to_user(bot, msg, bot_id)
        else:
            return False
        return True
    except Exception:
        logger.exception("بازکردنِ فروشگاهِ %s از دیپ‌لینکِ مینی‌اپ ناموفق بود", action)
        return False


async def _is_home_kb_press(msg: Message, bot: Bot) -> bool:
    t = (msg.text or "").strip()
    if not t or t.startswith("/") or msg.chat.type != "private":
        return False
    row = await get_bot_row(bot)
    if not row or not await home_kb_enabled(row.id):
        return False
    old = ((await get_setting(row.id, "home_kb_label_old", "")) or "").strip()
    return t == await home_kb_label(row.id) or (bool(old) and t == old)


@tenant_router.message(_is_home_kb_press)
async def home_kb_pressed(msg: Message, bot: Bot, state: FSMContext):
    """دکمهٔ ثابتِ پایینِ چت = همان /start (هر مرحلهٔ نیمه‌کاره هم لغو می‌شود)."""
    await state.clear()
    await tenant_start(msg, CommandObject(prefix="/", command="start", args=None), bot, state)


async def _is_flow_back_press(msg: Message, bot: Bot) -> bool:
    """=== PATCH_FLOW_BACK_KB_V1 === «⬅️ بازگشت به منو» از کیبورد تک‌دکمه‌ای صفحه‌های خرید؛ فقط وقتی آن کیبورد را ما
    برای همین کاربر گذاشته‌ایم. در هر وضعیت FSM کار می‌کند (وگرنه وسط مرحله‌ای متنی به‌جای برگشت، ورودی کاربر حساب می‌شد)."""
    if msg.text != BTN_BACK_MENU or msg.chat.type != "private" or not msg.from_user:
        return False
    row = await get_bot_row(bot)
    return bool(row) and _flow_kb_peek(row.id, msg.from_user.id)[0]


@tenant_router.message(_is_flow_back_press)
async def flow_back_pressed(msg: Message, bot: Bot, state: FSMContext):
    row = await get_bot_row(bot)
    if not row:
        return
    uid = msg.from_user.id
    if row.status == "paused" and not await is_owner_or_admin(row.id, uid, row.owner_id):
        raise SkipHandler                      # پیام «در حال به‌روزرسانی» را هندلر عمومی می‌دهد
    u = await get_or_create_user(row.id, uid, msg.from_user.full_name, msg.from_user.username or "")
    if u.is_banned and not _is_platform_admin(uid):
        return
    _, sub_id = _flow_kb_peek(row.id, uid)
    _flow_kb_clear(row.id, uid)
    await state.clear()                        # مرحلهٔ نیمه‌کارهٔ خرید رها می‌شود
    btn = None
    if sub_id:
        async with Session() as s:
            btn = await s.get(MainButton, sub_id)
        if (not btn or btn.bot_id != row.id or btn.action != "submenu"
                or btn.id in await _disabled_btn_ids(row.id)):
            btn = None                         # زیرمنو دیگر نیست/غیرفعال شده ⇒ صفحهٔ اصلی
    if btn:
        await _render_reply_submenu(msg, row.id, btn, state)
        return
    _set_last_menu(row.id, uid, None)
    kb = await main_kb_or_remove(row.id, row.owner_id, uid)
    await send_home_menu(msg, row.id, kb or ReplyKeyboardRemove())


async def _is_flow_home_press(msg: Message, bot: Bot) -> bool:
    """PATCH_NAV_KB_ONLY_V1 — «🏠 بازگشت به خانه» از کیبوردِ دکمه‌ایِ صفحه‌هایِ خرید."""
    if msg.text != BTN_HOME_FLOW or msg.chat.type != "private" or not msg.from_user:
        return False
