@tenant_router.message(CommandStart())
async def tenant_start(msg: Message, command: CommandObject, bot: Bot, state: FSMContext):
    await state.clear()
    row = await get_bot_row(bot)
    if not row:
        await msg.answer("این ربات فعال نیست.")
        return
    # === PATCH_SMM_AI_GROUP_V1 ===
    # وقتی دکمه‌ی «🔗 اتصالِ گروه با دکمه» زده بشه، تلگرام یه انتخاب‌گرِ
    # «به کدوم گروه اضافه بشه» نشون می‌ده؛ بعدِ انتخاب، همین /start با
    # همین payload به همون گروه فرستاده می‌شه — این تنها لحظه‌ایه که
    # chat_id اون گروه رو می‌فهمیم.
    if command.args == "connectai" and msg.chat.type in ("group", "supergroup"):
        from tenant.bots.virtual_service.smm import _set_setting as _smm_set_setting
        if not await is_owner_or_admin(row.id, msg.from_user.id, row.owner_id):
            await msg.reply("❌ فقط ادمینِ ربات می‌تونه دستیار رو به گروه وصل کنه.")
            return
        await _smm_set_setting(row.id, "smm_ai_group_chat_id", str(msg.chat.id))
        await _smm_set_setting(row.id, "smm_ai_group_chat_title", msg.chat.title or "این گروه")
        _ai_name = (await get_setting(row.id, "smm_ai_group_name", "")).strip()
        _ai_test = (f"برای آزمایش، ابتدا فقط «{_ai_name}» را بفرست و بعد سؤالت را ارسال کن."
                    if _ai_name else "برای استفاده، ابتدا از تنظیمات گروه یک اسم برای دستیار تعیین کن.")
        await msg.reply(
            "✅ دستیار هوش مصنوعی با موفقیت به همین گروه متصل شد.\n\n"
            f"{_ai_test}")
        return
    # === PATCH_GROUP_START_PRIVATE_ONLY_V2 ===
    # /start عادی فقط برای گفت‌وگوی خصوصی است؛ در گروه نباید منوی فروشگاه،
    # خوش‌آمد یا کیبورد کاربری ارسال کند. تنها استثنای مجاز، payload اتصال
    # دستیار به گروه است که چند خط بالاتر به‌صورت جداگانه return شده.
    if msg.chat.type in ("group", "supergroup"):
        return
    if row.status == "paused" and not await is_owner_or_admin(row.id, msg.from_user.id, row.owner_id):
        # === PATCH_PAUSED_NOTICE_THROTTLE_V1 === گزارش فدایی: «وقتی ربات را خاموش می‌کنیم، در گروه برای هر پیام می‌گوید
        # ربات خاموش است و اسپم می‌کند». در گروه هیچ پاسخی نمی‌دهیم؛ در چت خصوصی هم هر ۱۵ دقیقه یک‌بار.
        if msg.chat.type == "private" and _paused_notice_due(row.id, msg.chat.id):
            await msg.answer("🛠 ربات در حال به‌روزرسانی می‌باشد. لطفا چند دقیقهٔ دیگر دوباره امتحان کنید.")
        return
    u, was_created = await get_or_create_user(
        row.id, msg.from_user.id, msg.from_user.full_name,
        msg.from_user.username or "", return_created=True)
    if was_created:
        try:
            await _new_user_alert(bot, row, u)
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    # === PATCH_BAN_ONLY_MAIN_ADMIN_EXEMPT_V1 === فقط ادمینِ اصلیِ پلتفرم بن‌ناپذیر است.
    if u.is_banned and not _is_platform_admin(msg.from_user.id):
        await msg.answer("شما از این ربات مسدود شده‌اید.")
        return
    # === PATCH_VS_ONBOARDING_V1 ===
    # === PATCH_ONBOARDING_ALL_FIELDS_V1 ===
    # قبلاً این تجربه فقط برایِ ربات‌هایِ «خدمات مجازی» فعال می‌شد، چون
    # اولین‌بار همان‌جا ساخته شد. طبقِ درخواستِ ادمین، حالا برایِ همهٔ
    # نوع‌هایِ ربات در دسترس است (از «دکمه‌ها و تنظیمات» عمومی هم قابلِ
    # روشن/خاموش کردن است، نه فقط از پنلِ SMM) — منطقِ خودِ گیت
    # (_vs_show_rules_gate) از قبل عمومی بود و فقط اگر ادمین صراحتاً
    # قوانین را اجباری کرده باشد کاری می‌کند، پس برایِ ربات‌هایی که این
    # قابلیت را روشن نکرده‌اند هیچ تغییرِ رفتاری‌ای ایجاد نمی‌شود.
    # عمداً همین‌جا، قبل از هرچیزِ دیگر (حتی دیپ‌لینک‌ها) چک می‌شود — چون
    # منطقی نیست کسی که هنوز قوانین را نخوانده، مستقیم به یک محصولِ خاص
    # یا گیتِ اختصاصی برسد.
    if (not u.rules_accepted) or await _vso_rules_blocked(bot, msg.from_user.id) is not None:   # PATCH_RULES_VERSION_V1
        from tenant.bots.virtual_service.smm import _vs_show_rules_gate, _svc_id_from_start_payload
        if await _vs_show_rules_gate(msg, bot, row.id):
            # === PATCH_SMM_DEEPLINK_RESUME_V1 === لینکِ محصول را تا بعدِ تأییدِ قوانین نگه دار
            _psid = _svc_id_from_start_payload(command.args if command else None)
            if _psid:
                await state.update_data(pending_svc_id=_psid)
            return
    # استخراج کد دعوت از پارامتر /start (پیش از بررسی عضویت اجباری، چون اگر
    # کاربر هنوز عضو کانال نشده و این‌جا خروج بزنیم، در دفعهٔ بعدی که از منوی
    # تلگرام دوباره /start می‌زند پارامتر را نخواهد داشت و دعوت برای همیشه از
    # دست می‌رود). ثبتِ خودِ دعوت (handle_referral_join) چند سطر پایین‌تر و فقط
    # برای کاربرِ واقعاً تازه‌ساخته‌شده انجام می‌شود.
    ref_code = None
    # === PATCH_GATE_DEDICATED_LINK_V1 ===
    # دیپ‌لینکِ t.me/<bot>?start=gate_<code> — لینکِ اختصاصیِ یه دکمهٔ
    # «گیتِ دسترسی» (نگاه کن به tenant/referral_gate.py)؛ کاملاً مستقل از
    # ref_code (رفرالِ عمومی) است — یه کاربر می‌تونه هم‌زمان با هردو نوع
    # لینک وارد بشه ولی این‌جا چون start فقط یک پارامتر داره، هر بار یکی.
    gate_code = None
    # === PATCH_PRODUCT_DEEPLINK_V1 ===
    # دیپ‌لینکِ t.me/<bot>?start=prod_<id> — از دکمهٔ آبیِ زیرِ پستِ تبلیغِ
    # کانال میاد (نگاه کن به tenant/ad_broadcast.py). بعد از خوش‌آمد/منوی
    # عادی، صفحهٔ همون محصول رو هم نشون می‌دیم.
    prod_id = None
    # === PATCH_SMM_PRODUCT_DEEPLINK_V1 ===
    # گزارشِ ادمین (فدایی): «هر محصول شماره‌ محصولِ دستوری داشته باشه و
    # لینکِ سریع برایِ ثبتِ سفارشش». prod_ بالا فقط مالِ محصولاتِ فروشگاهِ
    # دیجیتال (Config/Order) است؛ سرویس‌هایِ SMM جدولِ جدا (SmmService)
    # دارند، پس یک پیشوندِ جدا لازم بود: t.me/<bot>?start=svc_<id>
    smm_svc_id = None
    # === PATCH_SLIDESHOW_ENHANCEMENTS_V1 ===
    # دیپ‌لینکِ t.me/<bot>?start=slide_<button_id>_<step_num> — از دکمهٔ
    # «📤 اشتراک‌گذاری» روی یه اسلاید میاد؛ باید همون اسلایدِ خاص رو نشون بدیم.
    slide_target = None  # (button_id, step_num) یا None
    # === PATCH_CHPOST_CHANNEL_BTN_DEEPLINK_FIX_V1 ===
    # دیپ‌لینکِ t.me/<bot>?start=mbtn_<id> — از دکمه‌ای می‌آید که ادمین به یک
    # پستِ کانال/گروه چسبانده (نگاه کن به _chpost_full_kb)؛ باید بلافاصله
    # بعدِ خوش‌آمد، همون عملِ دکمهٔ مربوطه را اجرا کنیم — نه اینکه کاربر را
    # فقط با پیامِ خوش‌آمد رها کنیم.
    mbtn_deeplink_id = None
    vhelp_deeplink_key = None  # PATCH_CHPOST_PICK_GUIDE_CHILDREN_V1
    # === PATCH_MINIAPP_V1 ===
    # دیپ‌لینکِ t.me/<bot>?start=vpay_<plan_id> — از دکمهٔ «خرید این پلن»
    # داخلِ مینی‌اپ می‌آید (نگاه کن به tenant/miniapp.py). همان خلاصهٔ خرید و
    # دکمه‌های پرداختِ همیشگی (vpay:<id> در tenant/vpn_user.py) را نشان
    # می‌دهیم؛ منطقِ پرداخت اینجا بازسازی نمی‌شود، فقط صدا زده می‌شود.
    miniapp_plan_id = None
    # === PATCH_MINIAPP_STOCK_CATS_V1 ===
    # t.me/<bot>?start=mbuy_<vol>_<days>_<users>_<price> — دکمهٔ «خرید این
    # بسته» رویِ بسته‌های آمادهٔ انبار در مینی‌اپ. همان هندلرِ همیشگیِ
    # mcfg:buy صدا زده می‌شود؛ منطقِ خرید بازسازی نمی‌شود.
    miniapp_pack = None
    # === PATCH_MINIAPP_VC_TRIAL_V1 ===
    # t.me/<bot>?start=vcbuy_<panel_key>_<gb>_<days>_<count> — از رابطِ +/−
    # حجم/روز دلخواهِ مینی‌اپ. t.me/<bot>?start=trial_<mb_id> — از کارتِ
    # «تست رایگان» مینی‌اپ. هردو همان توابعِ همیشگیِ ربات را صدا می‌زنند.
    miniapp_vc = None
    miniapp_trial_mb_id = None
    # === PATCH_MINIAPP_VSERVICES_V1 ===
    vsvc_action = None
    pubot_target_id = None  # === PATCH_PARTNER_REACTIVATION_LINK_V1 ===
    gw_payload = None       # === PATCH_GIVEAWAY_BOT_V1 ===
    if command.args:
        param = command.args.strip()
        if param.startswith("mbuy_"):
            _p = param[5:].split("_")
            if len(_p) == 4 and all(x.isdigit() for x in _p):
                miniapp_pack = tuple(int(x) for x in _p)
        # === PATCH_MINIAPP_VC_TRIAL_V1 ===
        elif param.startswith("vcbuy_"):
            # panel_key خودش می‌تواند زیرخط داشته باشد (مثل upanel_mizban)،
            # پس فقط سه بخشِ عددیِ انتهایی را جدا می‌کنیم.
            _vp = param[6:].split("_")
            if len(_vp) >= 4 and all(x.isdigit() for x in _vp[-3:]):
                _panel_key = "_".join(_vp[:-3])
                try:
                    miniapp_vc = (_panel_key, int(_vp[-3]), int(_vp[-2]), int(_vp[-1]))
                except ValueError:
                    miniapp_vc = None
        elif param.startswith("trial_"):
            try:
                miniapp_trial_mb_id = int(param[6:])
            except ValueError:
                miniapp_trial_mb_id = None
        elif param.startswith("vsvc_"):
            # === PATCH_MINIAPP_VSERVICES_V1 ===
            # t.me/<bot>?start=vsvc_<action> — از کاتالوگِ مینی‌اپِ خدماتِ
            # مجازی. همان هندلرهایِ کاربریِ موجود صدا زده می‌شوند.
            vsvc_action = param[5:]
        elif param.startswith("vpay_"):
            try:
                miniapp_plan_id = int(param[5:])
            except ValueError:
                miniapp_plan_id = None
        elif param.startswith("ref_"):
            ref_code = param[4:]
        elif param.startswith("gate_"):
            gate_code = param[5:]
        elif param.startswith("gw_"):
            gw_payload = param      # === PATCH_GIVEAWAY_BOT_V1 === t.me/<bot>?start=gw_<id>[_<inviter>]
        elif param.startswith("prod_"):
            try:
                prod_id = int(param[5:])
            except ValueError:
                prod_id = None
        # === PATCH_SMM_PRODUCT_DEEPLINK_V1 ===
        elif param.startswith("svc_"):
            try:
                smm_svc_id = int(param[4:])
            except ValueError:
                smm_svc_id = None
        elif param.startswith("slide_"):
            try:
                _parts = param[6:].split("_")
                slide_target = (int(_parts[0]), int(_parts[1]))
            except (ValueError, IndexError):
                slide_target = None
        elif param.startswith("mbtn_"):
            try:
                mbtn_deeplink_id = int(param[5:])
            except ValueError:
                mbtn_deeplink_id = None
        # === PATCH_CHPOST_PICK_GUIDE_CHILDREN_V1 ===
        # دکمهٔ یکی از گزینه‌هایِ «آموزش اتصال» که ادمین زیرِ پستِ کانال
        # چسبانده. مثلِ mbtn_ باید بعد از /start و در چتِ خصوصی اجرا شود.
        elif param.startswith("vhelp_"):
            vhelp_deeplink_key = param[6:] or None
        elif param.startswith("pubot_"):
            # === PATCH_PARTNER_REACTIVATION_LINK_V1 ===
            # کاربر از دکمهٔ «فعال‌سازیِ ربات» (وقتی رباتش که با این همکار ساخته
            # شده بایگانی/منقضی شده) به این ربات همکار آمده؛ مستقیم صفحهٔ همان
            # ربات را در «ربات‌های من» باز می‌کنیم تا تمدید/فعال کند.
            try:
                pubot_target_id = int(param[6:])
            except ValueError:
                pubot_target_id = None
    # بررسی عضویت اجباری
    # === PATCH_TENANT_FORCEJOIN_PRIVATE_ONLY_V1 ===
    # /start هم می‌تونه به‌صورتِ /start@botusername داخلِ گروه زده بشه؛ عضویتِ
    # اجباری فقط برایِ تعاملِ خصوصیِ کاربر با رباته، پس فقط تو چتِ خصوصی چک می‌شه.
    if msg.chat.type == "private":
        # === PATCH_TENANT_START_FORCEJOIN_USE_CACHE_V1 ===
        # قبلاً bypass_cache=True بود: یعنی هر /start، حتی برایِ کاربرِ
        # تازه‌تاییدشده، مجبور بود منتظرِ یک درخواستِ زندهٔ تلگرام برایِ هر
        # کانالِ عضویتِ اجباری بماند (۲-۳ ثانیه یا بیشتر با چند کانال).
        # حالا مثلِ بقیهٔ جاها از همان کشِ ۹۰ثانیه‌ای استفاده می‌شود.
        nj = await check_force_join(bot, row.id, msg.from_user.id)
        if nj:
            # اگر کاربر تازه از لینک دعوت آمده ولی هنوز عضو کانال نشده، کد دعوت را
            # در FSM نگه می‌داریم تا بعد از تایید عضویت (fj_check) از دست نرود.
            if ref_code and was_created:
                await state.update_data(pending_ref_code=ref_code)
            if gate_code and was_created:  # === PATCH_GATE_DEDICATED_LINK_V1 ===
                await state.update_data(pending_gate_code=gate_code)
            if smm_svc_id:  # === PATCH_SMM_DEEPLINK_RESUME_V1 === (برایِ همهٔ کاربران، نه فقط تازه‌ها)
                await state.update_data(pending_svc_id=smm_svc_id)
            if gw_payload:  # === PATCH_GIVEAWAY_FJ_RESUME_V1 === بعد از «عضو شدم» به همان قرعه‌کشی برگرد
                await state.update_data(pending_gw=gw_payload)
            await force_join_msg(bot, msg, nj)
            return
    # === PATCH_PHONE_VERIFY_V1 ===
    # درست مثلِ عضویتِ اجباری، اگه تاییدِ شماره لازمه و هنوز انجام نشده،
    # قبل از ثبتِ رفرال (که خودِ هدفِ این قابلیته: جلوگیری از رفرالِ فیک)
    # جلوش رو می‌گیریم و کدهایِ دعوتِ در انتظار رو نگه می‌داریم.
    # === PATCH_PHONE_VERIFY_FRESH_READ_V1 ===
    # وضعیتِ تایید رو مستقیم و تازه از دیتابیس می‌خونیم (نه از رویِ آبجکتِ u
    # که ممکنه از یه Sessionِ بسته‌شده مونده باشه). باگِ گزارش‌شده این بود که
    # کاربر شماره‌شو تایید می‌کرد ولی با /startِ بعدی دوباره ازش شماره خواسته
    # می‌شد. مقدارِ NULL (کاربرانِ قدیمی که قبل از اضافه‌شدنِ این ستون ساخته
    # شدن) هم مثلِ «تاییدنشده» حساب می‌شه.
    _phone_ok = False
    try:
        async with Session() as _s:
            _bu = await _s.scalar(select(BotUser).where(
                BotUser.bot_id == row.id, BotUser.telegram_id == msg.from_user.id))
            _phone_ok = bool(_bu and _bu.phone_verified)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (خواندنِ وضعیتِ تاییدِ شماره)")
    # === PATCH_PHONE_VERIFY_PRIVATE_ONLY_V1 ===
    # درست مثلِ عضویتِ اجباری (بالاتر)، تاییدِ شماره فقط تویِ چتِ خصوصی معنا
    # داره — دکمهٔ اشتراک‌گذاریِ مخاطب (request_contact) تویِ گروه/سوپرگروه
    # اصلاً درست کار نمی‌کنه و کاربر رو بی‌دلیل گیر می‌انداخت.
    if msg.chat.type == "private" \
            and (await get_setting(row.id, "phone_verify_enabled", "off")) == "on" and not _phone_ok \
            and not await is_owner_or_admin(row.id, msg.from_user.id, row.owner_id):
        if ref_code and was_created:
            await state.update_data(pending_ref_code=ref_code)
        if gate_code and was_created:
            await state.update_data(pending_gate_code=gate_code)
        await _phone_verify_prompt(msg)
        return
    # ثبت دعوت — فقط وقتی این کاربر همین الان (نه قبلاً) برای این ربات ساخته شده،
    # تا کاربرانِ قدیمیِ ربات با کلیک بعدی روی یک لینک دعوت اشتباهاً به‌عنوان
    # زیرمجموعهٔ جدید شمارش/پاداش‌دهی نشوند.
    if ref_code and was_created:
        from tenant.shared.extras import handle_referral_join
        await handle_referral_join(row.id, u, ref_code, bot)
    if gate_code and was_created:  # === PATCH_GATE_DEDICATED_LINK_V1 ===
        from tenant.shared.referral_gate import handle_gate_referral_join
        await handle_gate_referral_join(gate_code, msg.from_user.id)
    # === PATCH_WELCOME_BONUS_V1 ===
    # درست مثلِ پاداشِ دعوت، عمداً بعدِ گیت‌هایِ عضویتِ اجباری/تاییدِ شماره
    # قرار داره (نه بالاتر، نزدیکِ was_created خام) — وگرنه کسی که این
    # گیت‌ها رو رد نکرده هم می‌تونست با /start زدنِ ساده هدیه بگیره.
    if was_created:
        await grant_welcome_bonus(bot, row, u)

    # === PATCH_START_REACTION_V1 ===
    # اگر ادمین از «😀 ری‌اکشن روی پیامِ استارت» چیزی تنظیم کرده باشد، همین
    # لحظه رویِ خودِ پیامِ /start کاربر یک ری‌اکشن می‌گذاریم — قبل از پیامِ
    # خوش‌آمد، تا حتی اگر ارسالِ خوشامد به هر دلیلی به مشکل خورد، این
    # واکنشِ کوچک همچنان انجام شده باشد.
    # === PATCH_START_REACTION_BIG_V1 ===
    # is_big=True یعنی همان جلوهٔ پُرزرق‌وبرقی که با نگه‌داشتنِ انگشت رویِ
    # یک ری‌اکشن در تلگرام می‌بینی — چند نسخه از ایموجی روی صفحه پخش
    # می‌شوند و بعد جمع می‌شوند رویِ پیام؛ همان چیزی که کاربر خواسته بود،
    # نه فقط یک نشانِ ساکنِ کوچک زیرِ پیام.
    _start_react = await get_setting(row.id, "start_reaction_emoji", "")
    if _start_react:
        try:
            await msg.react([ReactionTypeEmoji(emoji=_start_react)], is_big=True)
        except Exception as e:
            # بعضی ایموجی‌ها یا حساب‌ها در Telegram قابل‌استفاده به‌عنوان
            # message reaction نیستند؛ این خطای غیرعملیاتی نباید traceback
            # تولید کند یا مسیر /start را شلوغ کند.
            if 'REACTION_INVALID' in str(e):
                logger.info('ری‌اکشن شروع نامعتبر بود و نادیده گرفته شد')
            else:
                logger.exception('ری‌اکشن‌زدن رویِ پیامِ /start ناموفق بود')

    # === PATCH_CHPOST_DEEPLINK_ONLY_BTN_V1 ===
    # گزارشِ ادمین: وقتی کاربر زیرِ پستِ کانال روی دکمهٔ ربات می‌زد، اول پیامِ /start
    # (استیکر + خوش‌آمد + منوی اصلی + محصولاتِ پین‌شده) می‌آمد و بعد پیامِ همان دکمه.
    # کاربر فقط پیامِ خودِ دکمه را می‌خواهد. پس برایِ دیپ‌لینکِ دکمهٔ کانال (mbtn_/vhelp_)
    # همهٔ این‌ها رد می‌شود و مستقیم همان دکمه اجرا می‌شود.
    # استثنا: حالتِ «کیبورد» برایِ کاربرِ تازه — کیبوردِ منو فقط با پیامِ خوش‌آمد روی صفحه
    # می‌نشیند؛ آنجا خوش‌آمد حفظ می‌شود تا کاربر بدونِ منو نماند.
    if mbtn_deeplink_id is not None or vhelp_deeplink_key:
        _dl_mode = await get_setting(row.id, "menu_mode", "reply")
        if _dl_mode == "inline" or not was_created:
            if mbtn_deeplink_id is not None:
                await mbtn_tap(_FakeCb(msg, f"mbtn:{mbtn_deeplink_id}"), bot, state)
            if vhelp_deeplink_key:
                from tenant.bots.vpn.vpn_user import vpn_help_show as _vhs
                await _vhs(_FakeCb(msg, f"vhelp:{vhelp_deeplink_key}"), bot)
            return

    # === PATCH_TENANT_HOME_STICKER_V1 ===
    # استیکرِ استارت (اگر تنظیم شده و ربات پلنِ حرفه‌ای است) پیش از پیامِ
    # خوش‌آمد ارسال می‌شود؛ دقیقاً همان رفتاری که در ربات اصلیِ بات‌ساز هست.
    if has_feature(row.plan, Feature.HOME_STICKERS):
        try:
            from tenant.shared.home_sticker_admin import get_start_sticker
            _start_sticker = await get_start_sticker(row.id)
            if _start_sticker:
                await msg.answer_sticker(_start_sticker)
        except Exception:
            logger.exception("ارسال استیکرِ استارت ناموفق بود")

    welcome = await get_setting(row.id, "welcome_text", "")
    txt = welcome if welcome else "به ربات خوش اومدی 👋"
    # === PATCH_WELCOME_MEDIA_V1 ===
    welcome_media_id = await get_setting(row.id, "welcome_media_id", "")
    welcome_media_type = await get_setting(row.id, "welcome_media_type", "")
    # جایگزینی متغیرها
    # === PATCH_TEXT_VARS_V1 === موتورِ مشترک (رفتارِ {name}/{fullname}/{id} عیناً حفظ شده
    # و حالا کلِ لیستِ متغیرها هم کار می‌کند؛ رجوع کنید به tenant/shared/text_vars.py)
    from tenant.shared.text_vars import render_text as _render_vars
    txt = await _render_vars(txt, bot_id=row.id, tg_user=msg.from_user)
    mode = await get_setting(row.id, "menu_mode", "reply")
    # === PATCH_PARTNER_MENU_MODE_HOME_FIX_V1 ===
    # قبلاً این‌جا صفحهٔ خانهٔ ربات‌هایِ پلنِ همکار همیشه اجباراً اینلاین
    # می‌شد (PATCH_PARTNER_INLINE_ONLY_V1)، حتی اگه مالک از تنظیماتِ پنلِ
    # همکار (دکمهٔ «🎛 نوع منو» → pp:menumode در tenant/partner_menu.py)
    # نوعِ منو رو رویِ «⌨️ کیبورد» گذاشته بود. یعنی اون سوییچ برایِ صفحهٔ
    # خانه اصلاً اثر نداشت، با اینکه پیامِ تاییدش می‌گفت «کاربران با
    # /start منوی جدید را می‌بینند». پنلِ مدیریتِ خودِ همکار (partner_home_kb)
    # جدا از این‌جاست و همیشه اینلاین می‌مونه؛ فقط صفحهٔ خانه/استارت باید
    # از رویِ همون menu_mode ذخیره‌شده تصمیم بگیره، دقیقاً مثلِ بقیهٔ پلن‌ها.
    if mode == "inline":
        if msg.from_user.id == row.owner_id:
            txt += "\n\n(شما مالک هستید؛ دکمهٔ «🛠 پنل مدیریت» در منوی زیر است.)"
        ikb = await main_inline_kb(row.id, row.owner_id, msg.from_user.id)
        # === PATCH_START_MERGED_GLASS_V1 ===
        # درخواستِ ادمین: در منوی شیشه‌ای، متنِ خوش‌آمد و دکمه‌ها یک پیام باشند (نه دو پیامِ
        # جدا با «🏠 به منوی اصلی بازگشتید»). کیبوردِ پایینِ احتمالیِ قبلی با یک پیامِ
        # نامرئیِ آنی پاک می‌شود. اگر هر چیزی خطا داد (لینکِ خرابِ دکمه، کپشنِ طولانی)،
        # همان مسیرِ قبلیِ دو‌پیامی اجرا می‌شود.
        _welcome_msg = await _try_merged_welcome(msg, row, txt, welcome_media_id, welcome_media_type,
                                                 ikb, msg.from_user.id)
        _merged = _welcome_msg is not None
        if not _merged:
            # حذف کیبوردِ پایینِ احتمالی از قبل + منوی شیشه‌ای
            _welcome_msg = await _send_welcome_media(msg, txt, welcome_media_id, welcome_media_type,
                                                     reply_markup=ReplyKeyboardRemove())
        if ikb and not _merged:
            # === PATCH_HOME_KB_SEND_GUARD_V1 ===
            # اگه یکی از دکمه‌های منو (مثلاً لینکِ مینی‌اپِ ذخیره‌شده‌ی قبلی که با
            # اعتبارسنجیِ سخت‌گیرانه‌ترِ فعلی مطابقت ندارد) باعثِ BUTTON_URL_INVALID
            # از سمتِ تلگرام بشه، دیگه کلِ /start برای همهٔ کاربرهای این ربات
            # کرش نکنه؛ پیام بدونِ کیبورد ارسال می‌شه و خطا لاگ می‌شه تا ادمین
            # بفهمه باید لینکِ دکمه را دوباره تنظیم کند.
            try:
                await send_home_menu(msg, row.id, ikb, attach=_welcome_msg)
            except TelegramBadRequest as e:
                logger.error("[home_kb_send_guard] bot_id=%s BUTTON_URL_INVALID احتمالاً به‌خاطر "
                             "لینکِ خرابِ یکی از دکمه‌ها — پیام بدونِ کیبورد ارسال شد: %s",
                             row.id, e)
                # === PATCH_HOME_KB_SEND_GUARD_V2 ===
                # به‌جای اینکه کلِ منو برای کاربر ناپدید شود، اول تلاش می‌کنیم
                # فقط دکمهٔ خرابِ مینی‌اپ را حذف کنیم و بقیهٔ منو را سالم
                # بفرستیم؛ و در هر صورت به مالکِ ربات یک پیامِ خصوصیِ هشدار
                # می‌فرستیم تا از مشکل باخبر شود (نه فقط در لاگِ سرور).
                _fixed_kb = _strip_broken_webapp_buttons(ikb)
                try:
                    if _fixed_kb and _fixed_kb.inline_keyboard:
                        await send_home_menu(msg, row.id, _fixed_kb, attach=_welcome_msg)
                    else:
                        await send_home_menu(msg, row.id)
                except TelegramBadRequest:
                    await send_home_menu(msg, row.id)
                try:
                    await bot.send_message(
                        row.owner_id,
                        "⚠️ یکی از دکمه‌های منوی اصلیِ ربات شما یک لینکِ خراب دارد و "
                        "تلگرام آن را رد می‌کند؛ آن دکمه موقتاً برای کاربران حذف شده تا "
                        "بقیهٔ منو کار کند. لطفاً با /admin وارد پنل مدیریت شوید، بخشِ "
                        "دکمه‌های منو را باز کنید و آدرسِ مینی‌اپ/لینکِ دکمهٔ مشکل‌دار را "
                        "دوباره تنظیم کنید.\n\n"
                        f"جزئیاتِ فنی: {e}")
                except Exception:
                    logger.exception("خطای نادیده‌گرفته‌شده (اطلاع‌رسانیِ لینکِ خرابِ منو به مالک)")
        if prod_id:
            from tenant.bots.digital_shop.handlers import send_product_page  # === PATCH_TENANT_SPLIT_PHASE3_DIGITAL_SHOP_V1 === (قبلاً tenant/shop.py)
            await send_product_page(msg, bot, prod_id, state)
        # === PATCH_SMM_PRODUCT_DEEPLINK_V1 ===
        if smm_svc_id:
            from tenant.bots.virtual_service.smm import send_smm_product_page
            await send_smm_product_page(msg, bot, smm_svc_id, state)
        # === PATCH_PRODUCT_PIN_ON_START_V1 ===
        await _send_start_pinned_products(msg, bot, row.id, state, skip_pid=prod_id)
        # === PATCH_SLIDESHOW_ENHANCEMENTS_V1 ===
        await _maybe_show_slideshow(msg, bot, row.id, slide_target, field=row.field)
        # === PATCH_CHPOST_CHANNEL_BTN_DEEPLINK_FIX_V1 ===
        if mbtn_deeplink_id is not None:
            await mbtn_tap(_FakeCb(msg, f"mbtn:{mbtn_deeplink_id}"), bot, state)
        if vhelp_deeplink_key:
            from tenant.bots.vpn.vpn_user import vpn_help_show as _vhs
            await _vhs(_FakeCb(msg, f"vhelp:{vhelp_deeplink_key}"), bot)
        # === PATCH_MINIAPP_V1 ===
        if miniapp_plan_id is not None:
            await _send_miniapp_buy_summary(msg, bot, row.id, miniapp_plan_id, state)
        # === PATCH_MINIAPP_STOCK_CATS_V1 ===
        if miniapp_pack is not None:
            await _start_miniapp_pack_buy(msg, bot, state, miniapp_pack)
        # === PATCH_MINIAPP_VC_TRIAL_V1 ===
        if miniapp_vc is not None:
            await _start_miniapp_vc_buy(msg, bot, state, row.id, miniapp_vc)
        if miniapp_trial_mb_id is not None:
            await _start_miniapp_trial(msg, bot, row.id, miniapp_trial_mb_id)
        # === PATCH_MINIAPP_VSERVICES_V1 ===
        if vsvc_action:
            await _open_vservice_shop(msg, bot, row.id, vsvc_action, state)
        # === PATCH_PARTNER_REACTIVATION_LINK_V1 ===
        if pubot_target_id is not None:
            try:
                from tenant.partner_bot.partner_user import pu_bot_detail
                await pu_bot_detail(_FakeCb(msg, f"pu:bot:{pubot_target_id}"), bot)
            except Exception:
                logger.exception("بازکردنِ صفحهٔ ربات همکار از دیپ‌لینک ناموفق بود")
        await _giveaway_start_hook(msg, bot, row, gw_payload, state)   # === PATCH_GIVEAWAY_BOT_V1 ===
        return
    kb = await main_kb_or_remove(row.id, row.owner_id, msg.from_user.id)
    if msg.from_user.id == row.owner_id:
        txt += "\n\n(شما مالک هستید؛ از دکمهٔ «🛠 پنل مدیریت» پایین صفحه استفاده کنید.)"
    # === PATCH_REPLY_KB_SEND_GUARD_V1 ===
    # باگ: در حالتِ «⌨️ کیبورد»، اگر یکی از دکمه‌هایِ منو (مینی‌اپ) لینکِ
    # خرابی داشت، تلگرام همین ارسال را با BUTTON_URL_INVALID رد می‌کرد و
    # چون هیچ try/except ای دورش نبود، /start برایِ *همهٔ* کاربرانِ همین
    # ربات کرش می‌کرد — همان ERR-220745. مسیرِ منویِ شیشه‌ای از قبل چنین
    # محافظی داشت (PATCH_HOME_KB_SEND_GUARD_V1)؛ این پچ همان الگو را برایِ
    # حالتِ کیبوردی هم تکرار می‌کند.
    try:
        await _send_welcome_media(msg, txt, welcome_media_id, welcome_media_type,
                                  reply_markup=kb or ReplyKeyboardRemove())
    except TelegramBadRequest as e:
        logger.error("[reply_kb_send_guard] bot_id=%s BUTTON_URL_INVALID احتمالاً به‌خاطر "
                    "لینکِ خرابِ یکی از دکمه‌ها — پیام بدونِ کیبورد ارسال شد: %s",
                    row.id, e)
        _fixed_kb = _strip_broken_webapp_buttons_reply(kb) if kb else None
        try:
            await _send_welcome_media(msg, txt, welcome_media_id, welcome_media_type,
                                      reply_markup=_fixed_kb or ReplyKeyboardRemove())
        except TelegramBadRequest:
            await _send_welcome_media(msg, txt, welcome_media_id, welcome_media_type,
                                      reply_markup=ReplyKeyboardRemove())
        try:
            await bot.send_message(
                row.owner_id,
                "⚠️ یکی از دکمه‌های منوی اصلیِ ربات شما یک لینکِ خراب دارد و "
                "تلگرام آن را رد می‌کند؛ آن دکمه موقتاً برای کاربران حذف شده تا "
                "بقیهٔ منو کار کند. لطفاً با /admin وارد پنل مدیریت شوید، بخشِ "
                "دکمه‌های منو را باز کنید و آدرسِ مینی‌اپ/لینکِ دکمهٔ مشکل‌دار را "
                "دوباره تنظیم کنید.\n\n"
                f"جزئیاتِ فنی: {e}")
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (اطلاع‌رسانیِ لینکِ خرابِ منو به مالک)")
    if prod_id:
        from tenant.bots.digital_shop.handlers import send_product_page  # === PATCH_TENANT_SPLIT_PHASE3_DIGITAL_SHOP_V1 === (قبلاً tenant/shop.py)
        await send_product_page(msg, bot, prod_id, state)
    # === PATCH_SMM_PRODUCT_DEEPLINK_V1 ===
    if smm_svc_id:
        from tenant.bots.virtual_service.smm import send_smm_product_page
        await send_smm_product_page(msg, bot, smm_svc_id, state)
    # === PATCH_PRODUCT_PIN_ON_START_V1 ===
    await _send_start_pinned_products(msg, bot, row.id, state, skip_pid=prod_id)
    # === PATCH_SLIDESHOW_ENHANCEMENTS_V1 ===
    await _maybe_show_slideshow(msg, bot, row.id, slide_target, field=row.field)
    # === PATCH_CHPOST_CHANNEL_BTN_DEEPLINK_FIX_V1 ===
    if mbtn_deeplink_id is not None:
        await mbtn_tap(_FakeCb(msg, f"mbtn:{mbtn_deeplink_id}"), bot, state)
    if vhelp_deeplink_key:
        from tenant.bots.vpn.vpn_user import vpn_help_show as _vhs
        await _vhs(_FakeCb(msg, f"vhelp:{vhelp_deeplink_key}"), bot)
    # === PATCH_MINIAPP_V1 ===
    if miniapp_plan_id is not None:
        await _send_miniapp_buy_summary(msg, bot, row.id, miniapp_plan_id, state)
    # === PATCH_MINIAPP_STOCK_CATS_V1 ===
    if miniapp_pack is not None:
        await _start_miniapp_pack_buy(msg, bot, state, miniapp_pack)
    # === PATCH_MINIAPP_VC_TRIAL_V1 ===
    if miniapp_vc is not None:
        await _start_miniapp_vc_buy(msg, bot, state, row.id, miniapp_vc)
    if miniapp_trial_mb_id is not None:
        await _start_miniapp_trial(msg, bot, row.id, miniapp_trial_mb_id)
    # === PATCH_MINIAPP_VSERVICES_V1 ===
    if vsvc_action:
        await _open_vservice_shop(msg, bot, row.id, vsvc_action, state)
    # === PATCH_PARTNER_REACTIVATION_LINK_V1 ===
    if pubot_target_id is not None:
        try:
            from tenant.partner_bot.partner_user import pu_bot_detail
            await pu_bot_detail(_FakeCb(msg, f"pu:bot:{pubot_target_id}"), bot)
        except Exception:
            logger.exception("بازکردنِ صفحهٔ ربات همکار از دیپ‌لینک ناموفق بود")
    await _giveaway_start_hook(msg, bot, row, gw_payload, state)   # === PATCH_GIVEAWAY_BOT_V1 ===


# === PATCH_FIX_MISSING_PACK_BUY_HEADER_V1 ===
async def _start_miniapp_pack_buy(msg: Message, bot: Bot, state: FSMContext, pack) -> None:
    """خریدِ یک بستهٔ آمادهٔ انبار که از مینی‌اپ شروع شده — دقیقاً همان
    هندلرِ mcfg:buy را صدا می‌زند تا جریانِ پرداخت یکی بماند."""
    vol, days, users, price = pack
    fake = _FakeCb(msg, data=f"mcfg:buy:{vol}:{days}:{users}:{price}:-:0")
    try:
        await manual_cfg_buy(fake, bot, state)
    except Exception:
        logger.exception("خطا در شروعِ خریدِ بستهٔ آماده از مینی‌اپ")
        await msg.answer("⚠️ این بسته الان در دسترس نیست. از منویِ خودِ ربات امتحان کن.")


# === PATCH_MINIAPP_VC_TRIAL_V1 ===
async def _start_miniapp_vc_buy(msg: Message, bot: Bot, state: FSMContext, bot_id: int, vc) -> None:
    """کاربر با رابطِ +/− حجم/روزِ دلخواهِ مینی‌اپ (tenant/miniapp.py) گیگ/
    روز/تعداد را انتخاب کرده و از آنجا با دیپ‌لینک به اینجا آمده؛ همان
    صفحه‌ای که با دکمهٔ vc:open در خودِ ربات باز می‌شود را با همان مقادیر
    می‌سازیم. هیچ منطقِ قیمتی/تخفیفی اینجا بازسازی نمی‌شود — نگاه کن به
    tenant/vpn_user.py::_vc_render."""
    panel_key, gb, days, count = vc
    try:
        from tenant.bots.vpn.vpn_user import _vc_all_for_user, _vc_render, VpnConfiguratorFSM
        cfg = await _vc_all_for_user(bot_id, msg.from_user.id, panel_key, days=days, gb=gb)
        if cfg.get("vc_enabled") != "1":
            await msg.answer("⚠️ این بخش دیگر در دسترس نیست. از منویِ خودِ ربات امتحان کن.")
            return
        mn_gb, mx_gb = int(cfg["vc_min_gb"]), int(cfg["vc_max_gb"])
        mn_d, mx_d = int(cfg["vc_min_days"]), int(cfg["vc_max_days"])
        mx_c = max(1, int(cfg["vc_max_count"]))
        gb = max(mn_gb, min(gb, mx_gb))
        days = max(mn_d, min(days, mx_d))
        count = max(1, min(count, mx_c))
        await state.set_state(VpnConfiguratorFSM.selecting)
        await state.update_data(vc_gb=gb, vc_days=days, vc_count=count,
                                vc_bot_id=bot_id, vc_panel_key=panel_key,
                                vc_disc_code=None, vc_stage=None)
        text, kb = await _vc_render(bot, bot_id, msg.from_user.id, gb, days, count, panel_key, state)
        await msg.answer(text, reply_markup=kb)
    except Exception:
        logger.exception("خطا در بازسازیِ صفحهٔ حجم دلخواه از مینی‌اپ")
        await msg.answer("⚠️ مشکلی پیش اومد. از منویِ خودِ ربات امتحان کن.")


async def _start_miniapp_trial(msg: Message, bot: Bot, bot_id: int, mb_id: int) -> None:
    """کاربر از کارتِ «تست رایگان» در مینی‌اپ آمده؛ دقیقاً همان do_free_trial
    که دکمهٔ متنیِ «🎁 تست رایگان VPN» صدا می‌زند را اجرا می‌کند."""
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
        u = await s.scalar(select(BotUser).where(
            BotUser.bot_id == bot_id, BotUser.telegram_id == msg.from_user.id))
    if not mb or mb.bot_id != bot_id or mb.action != "free_trial" or not u:
        await msg.answer("⚠️ تست رایگان دیگر در دسترس نیست.")
        return
    btn_cfg = {}
    if mb.config:
        try:
            btn_cfg = json.loads(mb.config) or {}
        except Exception:
            btn_cfg = {}
    await do_free_trial(msg, bot, bot_id, u, btn_cfg=btn_cfg, mb_id=mb.id)


# === PATCH_MINIAPP_V1 ===
async def _send_miniapp_buy_summary(msg: Message, bot: Bot, bot_id: int,
                                    plan_id: int, state: FSMContext) -> None:
    """کاربر از دکمهٔ «خرید این پلن» در مینی‌اپ با دیپ‌لینک به این‌جا آمده؛
    دقیقاً همان خلاصهٔ پیش‌فاکتور/دکمه‌های پرداختی که در جریانِ عادیِ خریدِ
    داخلِ ربات نمایش داده می‌شود را می‌سازیم و می‌فرستیم (نگاه کن به
    tenant/vpn_user.py::_build_buy_summary) — هیچ منطقِ پرداختی این‌جا
    تکرار نمی‌شود."""
    from tenant.bots.vpn.vpn_user import _build_buy_summary, plan_sale_full_message
    _full_msg = await plan_sale_full_message(bot_id, plan_id)      # PATCH_CATEGORY_SALE_FULL_V1
    if _full_msg:
        await msg.answer(_full_msg)
        return
    text, kb = await _build_buy_summary(bot, bot_id, plan_id, msg.from_user.id, state)
    if not text:
        await msg.answer("این پلن دیگر در دسترس نیست.")
        return
    await msg.answer(text, reply_markup=kb)


# === PATCH_PRODUCT_PIN_ON_START_V1 ===
async def _send_start_pinned_products(msg: Message, bot: Bot, bot_id: int,
                                      state: FSMContext,
                                      skip_pid: int | None = None) -> None:
    """محصولاتی که ادمین «📌 چسباندن به /start» رو براشون روشن کرده، بلافاصله
    بعد از پیامِ خوش‌آمد برای کاربر ارسال می‌کنه. اگه هیچ محصولی پین نشده
    باشه، هیچی نمی‌فرسته (رفتارِ قبلی: فقط خوش‌آمد و دکمه‌ها).
    skip_pid: اگه کاربر با دیپ‌لینکِ prod_<id> اومده و همون محصول جداگانه
    نشون داده شده، دوباره تکراری فرستاده نشه."""
    try:
        from models import Product
        async with Session() as s:
            pins = (await s.scalars(select(Product).where(
                Product.bot_id == bot_id,
                Product.is_active == True,
                Product.pin_on_start == True,
            ).order_by(Product.sort_order, Product.id))).all()
            pin_ids = [p.id for p in pins]
        if not pin_ids:
            return
        from tenant.bots.digital_shop.handlers import send_product_page  # === PATCH_TENANT_SPLIT_PHASE3_DIGITAL_SHOP_V1 === (قبلاً tenant/shop.py)
        for pid in pin_ids:
            if skip_pid and pid == skip_pid:
                continue
            try:
                await send_product_page(msg, bot, pid, state)
            except Exception:
                logger.exception("خطای نادیده‌گرفته‌شده (ارسالِ محصولِ پین‌شده رو /start)")
    except Exception:
        # ستون هنوز ساخته نشده / هر خطای دیگه — /start نباید کرش کنه
        logger.exception("خطای نادیده‌گرفته‌شده (محصولاتِ پین‌شدهٔ /start)")


# === PATCH_NO_DOT_MSG_V1 ===
# گزارش: «بعضی جاها رباتو استارت می‌کنی یه نقطه می‌فرسته و پاک می‌کنه». برایِ برداشتنِ
# کیبوردِ پایینیِ قدیمی باید یک پیام با ReplyKeyboardRemove فرستاد (تلگرام راهِ دیگری ندارد)؛
# فقط یک‌بار برایِ هر کاربر انجام می‌شود (kb_cleared) تا دیگر هر /start «نقطه» نپرد.
# با عوض‌شدنِ حالتِ منو (کیبورد↔شیشه‌ای) پرچم برایِ همه ریست می‌شود.
# === PATCH_HOME_KB_BUTTON_V1 ===
# درخواستِ Rocket: در منوی شیشه‌ای یک دکمهٔ ثابتِ پایینِ چت («🏠 منوی اصلی»، با اسمِ دلخواه) باشد که
# مثلِ /start منوی شیشه‌ای را دوباره بیاورد. پیش‌فرض خاموش؛ مالک از «🏠 متنِ بازگشت به صفحهٔ اصلی» روشنش می‌کند.
HOME_KB_LABEL_DEFAULT = "🏠 منوی اصلی"


async def home_kb_enabled(bot_id: int) -> bool:
    return (await get_setting(bot_id, "menu_mode", "reply") == "inline"
            and await get_setting(bot_id, "home_kb_btn", "0") == "1")


async def home_kb_label(bot_id: int) -> str:
    return ((await get_setting(bot_id, "home_kb_label", "")) or "").strip() or HOME_KB_LABEL_DEFAULT


async def home_kb_markup(bot_id: int):
    if not await home_kb_enabled(bot_id):
        return None
    from aiogram.types import KeyboardButton, ReplyKeyboardMarkup
    return ReplyKeyboardMarkup(keyboard=[[KeyboardButton(text=await home_kb_label(bot_id))]],
                               resize_keyboard=True, is_persistent=True)


async def clear_reply_kb_once(msg, bot_id: int, tg_id: int) -> None:
    try:
        async with Session() as s:
            bu = await s.scalar(select(BotUser).where(
                BotUser.bot_id == bot_id, BotUser.telegram_id == tg_id))
            if bu is None or bu.kb_cleared:
                return
        _hk = await home_kb_markup(bot_id)
        if _hk is not None:
            # دکمهٔ ثابتِ «منوی اصلی»: پیامِ حاملِ کیبورد نباید پاک شود وگرنه کلاینت کیبورد را هم می‌اندازد
            await msg.answer(HOME_MENU_TEXT_HIDDEN_MARK, reply_markup=_hk)
        else:
            _rm = await msg.answer(HOME_MENU_TEXT_HIDDEN_MARK, reply_markup=ReplyKeyboardRemove())
            await _rm.delete()
        async with Session() as s:
            bu = await s.scalar(select(BotUser).where(
                BotUser.bot_id == bot_id, BotUser.telegram_id == tg_id))
            if bu:
                bu.kb_cleared = True
                await s.commit()
    except Exception:
        logger.info("پاک‌کردنِ کیبوردِ پایین ممکن نشد (بی‌اهمیت)")


async def reset_kb_cleared(bot_id: int) -> None:
    from sqlalchemy import update as _upd
    try:
        async with Session() as s:
            await s.execute(_upd(BotUser).where(BotUser.bot_id == bot_id).values(kb_cleared=False))
            await s.commit()
    except Exception:
        logger.exception("reset_kb_cleared failed")


# === PATCH_WELCOME_MEDIA_V1 ===
# === PATCH_START_MERGED_GLASS_V2 ===
async def _try_merged_welcome(msg: Message, row, txt: str, media_id: str, media_type: str,
                              ikb, tg_user_id: int):
    """متنِ خوش‌آمد + دکمه‌هایِ شیشه‌ایِ منو در *یک* پیام. اگر نشد، None برمی‌گرداند تا فراخوان
    مسیرِ قبلیِ دو‌پیامی را اجرا کند."""
    # === PATCH_START_MERGED_GLASS_V3 ===
    # حتی وقتی «مخفی‌کردنِ متنِ بازگشت به خانه» روشن است، /start باید متنِ خوش‌آمد را با دکمه‌ها
    # در *یک* پیام بدهد (قبلاً دکمه‌ها رویِ یک بابلِ خالیِ جدا می‌نشست و متنِ خوش‌آمد بی‌منو می‌ماند).
    if not ikb:
        return None
    try:
        await clear_reply_kb_once(msg, row.id, tg_user_id)   # PATCH_NO_DOT_MSG_V1
        _ikb_send = ikb
        try:
            from tenant.shared.translate import user_lang as _ul, translate_kb_labels as _tkl
            if await _ul(row.id, tg_user_id) == "en":
                _ikb_send = await _tkl(row.id, ikb, "en")
        except Exception:
            logger.exception("ترجمهٔ دکمه‌هایِ منویِ ادغام‌شده ناموفق بود")
        return await _send_welcome_media(msg, txt, media_id, media_type, reply_markup=_ikb_send)
    except TelegramBadRequest as e:
        logger.warning("منوی ادغام‌شده رد شد؛ مسیرِ دو‌پیامی (bot_id=%s): %s", row.id, e)
        return None


async def _send_welcome_media(msg: Message, txt: str, media_id: str, media_type: str,
                              reply_markup=None):
    """پیامِ خوش‌آمدگویی رو می‌فرسته — اگه ادمین عکس/ویدیو تنظیم کرده باشه،
    به‌صورتِ عکس/ویدیو با کپشنِ متنِ خوش‌آمد؛ وگرنه فقط متن."""
    try:
        if media_id and media_type == "photo":
            # === PATCH_CUSTOM_HOME_MENU_TEXT_HIDE_V2 === پیامِ ارسالی برگردانده
            # می‌شود تا در حالتِ «مخفی» بتوان منوی اینلاین را رویش سوار کرد.
            return await msg.answer_photo(media_id, caption=txt, reply_markup=reply_markup)
        if media_id and media_type == "video":
            return await msg.answer_video(media_id, caption=txt, reply_markup=reply_markup)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (ارسالِ مدیای خوش‌آمدگویی)")
    return await msg.answer(txt, reply_markup=reply_markup)


# === PATCH_FJ_CUSTOM_WELCOME_V1 ===
# متنِ خوش‌آمدگویی (با جایگزینیِ {name}/{fullname}/{id}) را دقیقاً مثلِ
# مسیرِ /start می‌سازد تا بعد از تاییدِ عضویتِ اجباری هم همان پیامِ سفارشیِ
# ادمین نمایش داده شود، نه پیامِ پیش‌فرضِ «به ربات خوش اومدی».
async def _resolve_welcome_text(row_id: int, tg_user) -> str:
    welcome = await get_setting(row_id, "welcome_text", "")
    txt = welcome if welcome else "به ربات خوش اومدی 👋"
    # === PATCH_TEXT_VARS_V1 === همان موتورِ مشترکِ مسیرِ /start
    from tenant.shared.text_vars import render_text as _render_vars
    return await _render_vars(txt, bot_id=row_id, tg_user=tg_user)


# === PATCH_SMM_DEEPLINK_RESUME_V1 ===
async def _resume_pending_svc_after_gate(target, bot: Bot, state: FSMContext) -> None:
    """بعدِ عبور از عضویتِ اجباری، اگر کاربر با لینکِ یک محصولِ SMM آمده بود، آن صفحه را نشان
    بده. فقط وقتی pending_svc_id ذخیره شده باشد کاری می‌کند (برایِ بقیهٔ انواعِ ربات بی‌اثر)."""
    try:
        if not (await state.get_data()).get("pending_svc_id"):
            return
        from tenant.bots.virtual_service.smm import _resume_pending_svc
        await _resume_pending_svc(target, bot, state)
    except Exception:
        logger.exception("ادامهٔ لینکِ محصول بعد از عضویتِ اجباری ناموفق بود")


async def _resume_giveaway_after_gate(cb, bot, row, state, data: dict) -> None:
    """PATCH_GIVEAWAY_FJ_RESUME_V1 — بعد از تأییدِ عضویتِ اجباری، کارتِ قرعه‌کشی (یا فهرستِ قرعه‌کشی‌هایِ رباتِ
    قرعه‌کشی) را نشان بده؛ قبلاً کاربر فقط خوش‌آمد می‌دید و لینکِ قرعه‌کشی گم می‌شد. هرگز fj:check را خراب نمی‌کند."""
    try:
        gw = (data or {}).get("pending_gw")
        if gw:
            await state.update_data(pending_gw=None)
        if not gw and row.field != "giveaway":
            return
        fake = cb.message.model_copy(update={"from_user": cb.from_user}).as_(bot)
        await _giveaway_start_hook(fake, bot, row, gw, state)
    except Exception:
        logger.exception("ادامهٔ قرعه‌کشی بعد از عضویتِ اجباری ناموفق بود")


@tenant_router.callback_query(F.data == "fj:check")
async def fj_check(cb: CallbackQuery, bot: Bot, state: FSMContext):
    row = await get_bot_row(bot)
    if not row:
        await cb.answer()
        return
    # === PATCH_FORCEJOIN_CHECK_FRESH_V1 ===
    # دکمهٔ «✅ عضو شدم» باید *همیشه* نتیجهٔ زنده بگیرد. نتیجهٔ منفی کش
    # نمی‌شد، ولی کشِ «غیرقابلِ‌بررسی» (۵ دقیقه‌ای) هنوز اثر داشت — یعنی اگر
    # مالک همین الان ربات را ادمینِ کانال کرده بود، تا ۵ دقیقه هیچ‌کس واقعاً
    # چک نمی‌شد. با bypass_cache هر دو کش کنار گذاشته می‌شوند.
    nj = await check_force_join(bot, row.id, cb.from_user.id, bypass_cache=True)
    if nj:
        await cb.answer("هنوز عضو نشدی!", show_alert=True)
        return
    await cb.answer("✅ عضویت تایید شد!", show_alert=True)
    # اگر این کاربر قبل از تایید عضویت از یک لینک دعوت آمده بود، حالا که عضو
    # کانال شد دعوتش را ثبت کن (تا دعوت‌های معتبر به‌خاطر عضویت اجباری از دست نروند).
    data = await state.get_data()
    pending_ref = data.get("pending_ref_code")
    if pending_ref:
        await state.update_data(pending_ref_code=None)
        u = await get_or_create_user(row.id, cb.from_user.id, cb.from_user.full_name,
                                     cb.from_user.username or "")
        from tenant.shared.extras import handle_referral_join
        await handle_referral_join(row.id, u, pending_ref, bot)
    # === PATCH_GATE_DEDICATED_LINK_V1 ===
    pending_gate = data.get("pending_gate_code")
    if pending_gate:
        await state.update_data(pending_gate_code=None)
        from tenant.shared.referral_gate import handle_gate_referral_join
        await handle_gate_referral_join(pending_gate, cb.from_user.id)
    try:
        await cb.message.delete()
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")

    # === PATCH_FJ_PHONE_GATE_V1 ===
    # میدل‌ویرِ تاییدِ شماره فقط رویِ *پیام‌ها* است، و این یک
    # callback_query است — پس بدونِ این بررسی، کاربر با «عضو شدم» کلِ
    # منو را می‌گرفت و تاییدِ شماره را کامل دور می‌زد.
    if await _fj_needs_phone_verify(row, cb.from_user.id):
        await _phone_verify_prompt(cb.message)
        return

    # === PATCH_FJ_CUSTOM_WELCOME_V1 ===
    # به‌جای متنِ ثابتِ «به ربات خوش اومدی»، همان پیامِ خوش‌آمدگوییِ سفارشیِ
    # ادمین (welcome_text + مدیای احتمالی) را می‌سازیم و می‌فرستیم — دقیقاً
    # مثلِ مسیرِ /start. ارسال روی cb.message انجام می‌شود (چتِ خصوصیِ کاربر)
    # ولی متغیرها از cb.from_user (خودِ کاربر) گرفته می‌شوند، نه از فرستندهٔ
    # پیام که ربات است.
    txt = await _resolve_welcome_text(row.id, cb.from_user)
    welcome_media_id = await get_setting(row.id, "welcome_media_id", "")
    welcome_media_type = await get_setting(row.id, "welcome_media_type", "")
    if await get_setting(row.id, "menu_mode", "reply") == "inline":
        ikb = await main_inline_kb(row.id, row.owner_id, cb.from_user.id)
        # === PATCH_START_MERGED_GLASS_V2 === بعد از «عضو شدم» هم متن و منو یک پیام
        _welcome_msg = await _try_merged_welcome(cb.message, row, txt, welcome_media_id,
                                                 welcome_media_type, ikb, cb.from_user.id)
        if _welcome_msg is None:
            _welcome_msg = await _send_welcome_media(cb.message, txt, welcome_media_id, welcome_media_type,
                                                     reply_markup=ReplyKeyboardRemove())
            if ikb:
                await send_home_menu(cb.message, row.id, ikb, attach=_welcome_msg)
        await _resume_pending_svc_after_gate(cb.message, bot, state)   # === PATCH_SMM_DEEPLINK_RESUME_V1 ===
        await _resume_giveaway_after_gate(cb, bot, row, state, data)
        return
    kb = await main_kb_or_remove(row.id, row.owner_id, cb.from_user.id)
    await _send_welcome_media(cb.message, txt, welcome_media_id, welcome_media_type,
                              reply_markup=kb or ReplyKeyboardRemove())
    await _resume_pending_svc_after_gate(cb.message, bot, state)   # === PATCH_SMM_DEEPLINK_RESUME_V1 ===
    await _resume_giveaway_after_gate(cb, bot, row, state, data)


# ─────────────────────── لغو کلی ───────────────────────

@tenant_router.message(F.text.in_({"❌ لغو", "❌ لغو / بازگشت"}))
async def tenant_cancel(msg: Message, bot: Bot, state: FSMContext):
    # === PATCH_DISCOUNT_CANCEL_BACK_V1 ===
    # نگاه کن به توضیحِ کاملِ fsm_cancel_inline (نسخهٔ شیشه‌ای‌اش) — همین
    # منطق اینجا هم برای حالتِ کیبوردی تکرار شده: قبلاً لغوِ کدِ تخفیف
    # حینِ خرید مستقیم می‌رفت منوی اصلی (نه صفحهٔ خریدی که توش بود).
    cur_state = await state.get_state()
    # === PATCH_ADMIN_USER_CANCEL_BACK_V1 ===
    # همینِ الگو برایِ فرآیندهایِ مدیریتِ کاربر (کیف‌پول/روز/حجم) — نسخهٔ
    # کیبوردیِ همان تغییری که در fsm_cancel_inline اضافه شد.
    if cur_state in (AdminFSM.adjust_days.state, AdminFSM.adjust_gb.state,
                    AdminFSM.adjust_amount.state):
        data = await state.get_data()
        target_uid = data.get("target_uid")
        await state.clear()
        if target_uid:
            await _render_user_detail(msg, bot, int(target_uid))
            return
    # === PATCH_VPN_PLAN_CATEGORY_RENAME_V1 ===
    from tenant.bots.vpn.vpn_admin import VpnCatRenameFSM, vpn_plans
    if cur_state == VpnCatRenameFSM.name.state:
        data = await state.get_data()
        key = data.get("cat_panel_key")
        await state.clear()
        if key:
            row = await get_bot_row(bot)
            kb = await main_kb_or_remove(row.id, row.owner_id, msg.from_user.id) if row else None
            await msg.answer("❌ لغو شد.", reply_markup=kb or ReplyKeyboardRemove())
            fake_cb = type("CB", (), {
                "data": f"tvpn:plans:{key}",
                "answer": (lambda *a, **k: _fsm_cancel_noop()),
                "message": msg, "from_user": msg.from_user,
            })()
            await vpn_plans(fake_cb, bot)
            return
    if cur_state == _ManualCfgDiscountFSM.entering.state:
        await state.set_state(None)
        try:
            await _show_manual_preinvoice(msg, bot, msg.from_user, state)
            return
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (بازگشت به پیش‌فاکتور بعد از لغوِ کدِ تخفیف)")
    if cur_state in (BuyFSM.discount.state, BuyFSM.discount_unlimited.state):
        data = await state.get_data()
        await state.clear()
        row = await get_bot_row(bot)
        try:
            kb = await main_kb_or_remove(row.id, row.owner_id, msg.from_user.id) if row else None
            if cur_state == BuyFSM.discount.state:
                mbid, vi, di, c = data.get("disc_mbid"), data.get("disc_vi"), \
                    data.get("disc_di"), data.get("disc_c")
                res = await get_btn_cfg(mbid) if mbid is not None else None
                if row and res:
                    cfg, _ = res
                    is_owner = (msg.from_user.id == row.owner_id)
                    await msg.answer("❌ لغو شد.", reply_markup=kb or ReplyKeyboardRemove())
                    await msg.answer(
                        "🛒 سفارش:",
                        reply_markup=await buy_kb(mbid, vi, di, c, cfg, 0, plan=row.plan, is_owner=is_owner, bot_id=row.id))
                    return
            else:
                mbid, di, c = data.get("discu_mbid"), data.get("discu_di"), data.get("discu_c")
                if row and mbid is not None:
                    cfg = await get_unlimited_cfg(row.id)
                    is_owner = (msg.from_user.id == row.owner_id)
                    await msg.answer("❌ لغو شد.", reply_markup=kb or ReplyKeyboardRemove())
                    await msg.answer(
                        "♾️ سفارش:",
                        reply_markup=await buy_unlimited_kb(mbid, di, c, cfg, 0, plan=row.plan, is_owner=is_owner, bot_id=row.id))
                    return
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (بازگشت به صفحهٔ خرید بعد از لغوِ کدِ تخفیف)")
        # اگه نشد برگردونیمش به صفحهٔ خرید، رفتارِ قبلی (برگشت به منوی اصلی) ادامه پیدا می‌کنه
    else:
        await state.clear()
    row = await get_bot_row(bot)
    if not row:
        return
    if await get_setting(row.id, "menu_mode", "reply") == "inline":
        ikb = await main_inline_kb(row.id, row.owner_id, msg.from_user.id)
        _note_msg = await msg.answer("به منوی اصلی برگشتی.", reply_markup=ReplyKeyboardRemove())
        if ikb:
            await send_home_menu(msg, row.id, ikb, attach=_note_msg)
        return
    kb = await main_kb_or_remove(row.id, row.owner_id, msg.from_user.id)
    await msg.answer("به منوی اصلی برگشتی.", reply_markup=kb or ReplyKeyboardRemove())


@tenant_router.callback_query(F.data == "cfg:add:cancel")
async def cfg_add_cancel(cb: CallbackQuery, bot: Bot, state: FSMContext):
    """لغو هر مرحله از افزودن/ویرایش کانفیگ و بازگشت به منوی مدیریت کانفیگ‌ها."""
    await state.clear()
    try:
        await cb.message.edit_reply_markup(reply_markup=None)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.message.answer("❌ لغو شد. به مدیریت کانفیگ‌ها برگشتی.",
                            reply_markup=cfg_manage_kb())
    await cb.answer("لغو شد")


@tenant_router.callback_query(F.data == "buy:cancel")
async def buy_cancel(cb: CallbackQuery, bot: Bot):
    await cb.answer("لغو شد")
    row = await get_bot_row(bot)
    if not row:
        try:
            await cb.message.delete()
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        return
    _inline = await get_setting(row.id, "menu_mode", "reply") == "inline"
    # === PATCH_CUSTOM_HOME_MENU_TEXT_HIDE_V4 ===
    # در حالتِ «مخفی» + منوی شیشه‌ای، همین پیام میزبانِ دکمه‌های منو می‌شود،
    # پس نباید قبلش پاکش کنیم؛ وگرنه مجبور می‌شویم بابلِ خالی بفرستیم.
    _keep = _inline and await home_menu_text_hidden(row.id)
    if not _keep:
        try:
            await cb.message.delete()
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    if _inline:
        ikb = await main_inline_kb(row.id, row.owner_id, cb.from_user.id)
        if ikb:
            await send_home_menu(cb, row.id, ikb)
    else:
        kb = await main_kb_or_remove(row.id, row.owner_id, cb.from_user.id)
        await send_home_menu(cb, row.id, kb)


# ─────────────────────── دکمه‌های صفحه اصلی ───────────────────────

async def _disabled_btn_ids(bot_id: int) -> set:
    async with Session() as s:
        rows = (await s.scalars(
            select(Setting).where(Setting.bot_id == bot_id, Setting.key.like("hbtn_off:%"))
        )).all()
    out = set()
    for r in rows:
        if r.value == "1":
            part = r.key.split(":")[1] if ":" in r.key else ""
            if part.isdigit():
                out.add(int(part))
    return out


# === PATCH_BTN_EXEC_SAFETY_NET_V1 ===
async def _exec_main_button(btn, msg, bot, state, row, u, bot_id, cb=None):
    # === PATCH_TENANT_HOME_STICKER_V1 ===
    # استیکرِ همین دکمه (اگر تنظیم شده و ربات پلنِ حرفه‌ای است) پیش از
    # محتوایِ خودِ دکمه ارسال می‌شود.
    if has_feature(row.plan, Feature.HOME_STICKERS):
        try:
            from tenant.shared.home_sticker_admin import get_button_sticker
            _btn_sticker = await get_button_sticker(bot_id, btn.id)
            if _btn_sticker:
                await _drop_btn_sticker(bot, bot_id, msg.chat.id)
                _sent_st = await msg.answer_sticker(_btn_sticker)
                _LAST_BTN_STICKER[(bot_id, msg.chat.id)] = _sent_st.message_id
        except Exception:
            logger.exception("ارسال استیکرِ دکمه ناموفق بود")
    # دکمهٔ شرطی‌شده با زیرمجموعه: منطق اختصاصی خودش را دارد (متن پیش‌فرض را نشان نده)
    try:
        if btn.action == "referral_gate":
            from tenant.shared.referral_gate import deliver_gate
            await deliver_gate(btn, msg, bot, row, u, bot_id, state=state, cb=cb)
            return

        await _run_button_action(btn.action, btn, msg, bot, state, row, u, bot_id, cb=cb)
    except Exception:
        import logging
        logging.getLogger("botsaz").exception(
            "button exec failed: bot_id=%s btn_id=%s action=%s",
            bot_id, getattr(btn, "id", None), getattr(btn, "action", None))
        try:
            await msg.answer(
                "⚠️ در اجرای این دکمه خطایی رخ داد. لطفاً دوباره امتحان کن یا به پشتیبانی اطلاع بده.")
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")


# === PATCH_CUSTOM_SUBMENU_HEADER_V1 ===
def submenu_header(btn) -> str:
    """متنِ بالایِ صفحهٔ زیرمنو (همون‌جایی که دکمه‌هایِ داخلش نشون داده می‌شن).

    اگه مالکِ ربات برایِ این دکمه «متن دکمه» تنظیم کرده باشه، *دقیقاً* همون
    نشون داده می‌شه — بدونِ اضافه‌شدنِ عنوانِ خودکار («🗂 اسمِ دکمه») و بدونِ
    «یکی را انتخاب کن:» — یعنی کنترلِ کاملِ متن دستِ خودشه و می‌تونه هرچی
    مناسبِ موضوعِ اون دکمه‌ست بنویسه. اگه چیزی تنظیم نکرده باشه، همون
    قالبِ پیش‌فرضِ قبلی دست‌نخورده باقی می‌مونه.
    """
    desc = (getattr(btn, "message", None) or "").strip()
    if desc:
        return _rtl_lines(desc)  # === PATCH_RTL_PAGE_TEXT_V1 ===
    return _rtl_lines(f"🗂 <b>{btn.label}</b>\nیکی را انتخاب کن:")


async def _render_reply_submenu(msg: Message, bot_id: int, btn: "MainButton", state: FSMContext) -> None:
    """رندرِ زیرمنوی کیبوردی برای دکمهٔ btn — هم موقعِ ورود اولیه به زیرمنو
    استفاده می‌شود، هم موقعِ زدنِ «◀️ بازگشت» (رفتن یک سطح بالا)."""
    support_enabled = getattr(btn, "support_btn", False)
    _sm_head = submenu_header(btn)
    kb = await submenu_kb(bot_id, btn.id, support_row=support_enabled,
                          show_up_row=btn.parent_id is not None)
    # === PATCH_BOT_LANG_TOGGLE_V1 ===
    try:
        from tenant.shared.translate import user_lang, translate_text, translate_kb_labels
        if await user_lang(bot_id, msg.from_user.id) == "en":
            _sm_head = await translate_text(bot_id, _sm_head, "en")
            kb = await translate_kb_labels(bot_id, kb, "en")
    except Exception:
        logger.exception("ترجمهٔ زیرمنویِ کیبوردی ناموفق بود؛ نسخهٔ فارسی نمایش داده می‌شود")
    if kb:
        if support_enabled:
            await state.update_data(support_mb_id=btn.id)
        await state.update_data(cur_submenu_id=btn.id)
        # === PATCH_FLOW_BACK_TO_SUBMENU_V1 === (ایلیا) صفحه‌هایِ خرید «بازگشت به منو» را به همین زیرمنو برمی‌گردانند، نه صفحهٔ اصلی
        _set_last_menu(bot_id, msg.from_user.id, btn.id)
        _flow_kb_clear(bot_id, msg.from_user.id)        # PATCH_FLOW_BACK_KB_V1 — کیبورد زیرمنو جایگزین کیبورد تک‌دکمه‌ای شد
        await msg.answer(_sm_head, reply_markup=kb)
        _stale = _HIDDEN_HOME_BUBBLES.pop((bot_id, getattr(getattr(msg, "chat", None), "id", None)), None)
        if _stale:                                      # بابل نامرئی کیبورد تک‌دکمه‌ای دیگر لازم نیست (کیبورد تازه‌تر آمد)
            try:
                await msg.bot.delete_message(msg.chat.id, _stale)
            except Exception:
                logger.info("پاک‌کردن بابل نامرئی قبلی ممکن نشد (bot_id=%s)", bot_id)
    elif not btn.message:
        await msg.answer("🗂 این زیرمنو هنوز دکمه‌ای ندارد.")


async def _run_button_action(action, btn, msg, bot, state, row, u, bot_id, cb=None):
    """اجرای عملکردِ یک دکمه بر اساس action داده‌شده.

    این تابع از _exec_main_button جدا شده تا «گیتِ دسترسی» بتواند پس از احراز
    شرطِ زیرمجموعه، همان عملکرد اصلیِ دکمه (keep_action) را اجرا کند. `action`
    صراحتاً پاس داده می‌شود (ممکن است با btn.action فرق کند).
    """
    support_enabled = getattr(btn, "support_btn", False)
    support_contact = (getattr(btn, "support_contact", None) or "").strip() or None
    effective_has_action = bool(action)
    # === PATCH_BTN_DESC_FIX_MARKER ===
    # اکشن‌هایی که خودشان action_header را به‌صورت سرتیتر بالای صفحهٔ اکشن
    # نمایش می‌دهند؛ برای بقیهٔ اکشن‌ها باید متنِ دکمه جداگانه ارسال شود
    # وگرنه (مثل قبل از این پچ) هیچ‌وقت به کاربر نشان داده نمی‌شود.
    # === PATCH_SUBMENU_DESC_INLINE_V1 ===
    _HEADER_AWARE_ACTIONS = {
        "buy_config", "buy_unlimited", "buy_vpn",
        "buy_vpn_sanai", "buy_vpn_pasargad", "buy_vpn_pasarguard", "buy_vpn_marzban",
        "buy_vpn_marzneshin", "buy_vpn_hiddify", "buy_vpn_rebecca", "buy_vpn_alireza", "buy_vpn_upanel_mizban", "buy_vpn_nodex", "buy_vpn_degeris", "buy_vpn_eylan", "buy_vpn_heimdall", "buy_vpn_rickpanel",
        "buy_vpn_shahan",   # === PATCH_SHAHAN_BUY_BUTTON_V1 ===
        "buy_bundle",   # === PATCH_BUNDLE_BUTTON_V1 ===
        "buy_panel_market",   # === PATCH_PANEL_SHOP_ACTION_V1 ===
        "buy_metered",   # === PATCH_METERED_BTN_ACTION_V1 ===
        "submenu", "web_app", "channel_link",
        "wallet",
    }
    # اگر دکمه «اکشن» دارد، متنِ دکمه به‌صورت پیام جدا ارسال نمی‌شود؛ بلکه به‌عنوان
    # سرتیتر (توضیح) بالای صفحهٔ همان اکشن (مثل صفحهٔ خرید) نشان داده می‌شود.
    action_header = ""
    if btn.message and effective_has_action:
        action_header = btn.message.strip() + "\n\n"
        if action not in _HEADER_AWARE_ACTIONS and not str(action or "").startswith("buy_vpn_"):
            extra = await inline_back_kb(bot_id)
            extra = await _attach_support(bot_id, extra, support_enabled, contact=support_contact, mb=btn)
            await msg.answer(btn.message, reply_markup=extra)
    # === PATCH_NO_ACTION_BTN_CRASH_V1 ===
    # باگ: دکمه‌ای که هنوز هیچ عملکردی برایش تنظیم نشده (action=None) پس از
    # نمایشِ متن/پشتیبانی، به‌جایِ بازگشتن از تابع، به زنجیرهٔ عظیمِ
    # if/elifِ اکشن‌ها می‌افتاد. آنجا یک شرط بدونِ محافظت
    # (`action.startswith("buy_vpn_")`) رویِ None صدا زده می‌شد و
    # AttributeError می‌داد — که به‌عنوانِ «⚠️ خطای غیرمنتظره» به مشتری
    # نشان داده می‌شد، درست بعدِ پیامِ درستِ پشتیبانی/توضیح. حالا این حالت
    # را کامل و زودتر مدیریت می‌کنیم و return می‌زنیم.
    if not effective_has_action:
        if btn.message:
            extra = await inline_back_kb(bot_id)
            extra = await _attach_support(bot_id, extra, support_enabled, contact=support_contact, mb=btn)
            await msg.answer(btn.message, reply_markup=extra)
        elif support_enabled:
            # دکمهٔ بدون متن ولی با پشتیبانیِ روشن: فقط دکمهٔ پشتیبانی را نشان بده
            sb = await _support_btn_for(bot_id, btn)
            if sb:
                rows = [[sb]]
                br = await inline_back_row(bot_id)
                if br:
                    rows.append(br)
                await msg.answer("برای ارتباط با پشتیبانی روی دکمهٔ زیر بزنید 👇",
                                 reply_markup=InlineKeyboardMarkup(inline_keyboard=rows))
            else:
                # پشتیبانی روشن است ولی آدرسش تنظیم نشده
                await msg.answer("ℹ️ آدرس پشتیبانی هنوز تنظیم نشده است.",
                                 reply_markup=await inline_back_kb(bot_id))
        else:
            # نه متنی هست، نه پشتیبانی‌ای روشن — یعنی ادمین هنوز این دکمه
            # را تنظیم نکرده؛ به مشتری پیامِ روشن بده، نه سکوت و نه کرش.
            await msg.answer("ℹ️ این دکمه هنوز توسط مدیر ربات تنظیم نشده است.",
                             reply_markup=await inline_back_kb(bot_id))
        return

    if action == "buy_config":
        # حالتِ نمایش این دکمه: «range» = بازه‌ای با ➕➖ | «packages» = فقط بسته‌های
        # آمادهٔ قیمت ثابت | «both» = هر دو (حالت قدیمی، برای سازگاری با دکمه‌های قبلی)
        cfg_mode = "both"
        cfg_category = None
        # === PATCH_BUY_CONFIG_CFG_KIND_UNBOUND_V1 ===
        # باگ: cfg_kind فقط داخلِ «if btn.config:» مقداردهی می‌شد؛ برایِ
        # دکمه‌هایی که هنوز config (JSON) ندارن (btn.config خالی/None —
        # یعنی دکمهٔ ساده/پیش‌فرض، حالتِ خیلی رایج)، این بلوک اصلاً اجرا
        # نمی‌شد و چند خط پایین‌تر (ارسال به _show_manual_packages) با
        # UnboundLocalError کرش می‌کرد — یعنی زدنِ دکمهٔ «خرید کانفیگ» برای
        # همچین دکمه‌ای اصلاً جواب نمی‌داد. الان پیش‌فرضش همین‌جا None است.
        cfg_kind = None
        cfg_incl_unl = False  # === PATCH_MANUAL_BTN_DISPLAY_CATS_V1 ===
        if btn.config:
            try:
                _btn_cfg_json = json.loads(btn.config) or {}
            except Exception:
                _btn_cfg_json = {}
            cfg_mode = _btn_cfg_json.get("config_mode", "both")
            cfg_category = _norm_cat_list(_btn_cfg_json.get("config_category"))
            cfg_kind = _btn_cfg_json.get("config_kind") or None
            cfg_incl_unl = bool(_btn_cfg_json.get("config_include_unlimited"))  # === PATCH_MANUAL_BTN_DISPLAY_CATS_V1 ===
        # === PATCH_PANEL_SHOP_ACTION_V1 === دکمه‌هایِ قدیمیِ «خرید کانفیگ ← فقط پنل‌ها» هم به فروشگاهِ پنل می‌روند
        if cfg_kind == "panel":
            if not has_feature(row.plan, Feature.VPN_PANEL_MARKET):
                await msg.answer("⛔️ این دکمه در پلنِ فعلیِ ربات در دسترس نیست.",
                                 reply_markup=await inline_back_kb(bot_id))
            else:
                from tenant.bots.vpn.panel_shop import show_panel_shop
                await show_panel_shop(msg, bot_id, header=action_header, support_enabled=support_enabled,
                                      support_contact=support_contact, mb=btn)
            return
        if cfg_mode != "packages":
            res = await get_btn_cfg(btn.id)
            if res:
                cfg, _ = res
                has_range_stock = await _bot_has_range_stock(bot_id)
                if has_range_stock:
                    c0 = min(cfg.get("counts", [1]) or [1])
                    kb = await buy_kb(btn.id, 0, 0, c0, cfg, plan=row.plan,
                               is_owner=(msg.from_user.id == row.owner_id), bot_id=bot_id)
                    # === PATCH_SUPNOTIFY_MB_FIX_V1 ===
                    kb = await _attach_support(bot_id, kb, support_enabled, contact=support_contact, mb=btn)
                    await msg.answer(
                        _with_btn_header(buy_info_text(cfg), btn.message if effective_has_action else ""),
                        reply_markup=kb,
                        parse_mode="HTML",
                    )
                elif cfg_mode == "range":
                    # فقط حالتِ بازه‌ای انتخاب شده و هیچ کانفیگی در انبار نیست: به‌جای نمایشِ
                    # دکمه‌های خرید که قطعاً با «ناموجود» رد می‌شوند، پیامِ ناموجودی نشان بده.
                    rows = []
                    _br = await inline_back_row(bot_id)
                    if _br:
                        rows.append(_br)
                    kb = InlineKeyboardMarkup(inline_keyboard=rows) if rows else None
                    await msg.answer(
                        _with_btn_header(
                            "📦 فعلاً هیچ کانفیگی موجود نیست.\nبعداً دوباره سر بزن.",
                            btn.message if effective_has_action else ""),
                        reply_markup=kb,
                    )
        if cfg_mode != "range":
            # وقتی فقط «بسته‌های آماده» انتخاب شده، دکمهٔ پشتیبانی باید همینجا بچسبد
            await _show_manual_packages(
                msg, bot_id, unlimited=False,
                support_enabled=(support_enabled if cfg_mode == "packages" else False),
                support_contact=support_contact,
                header=(btn.message if (effective_has_action and cfg_mode == "packages") else ""), mb=btn,
                category=cfg_category, kind=cfg_kind, include_unlimited=cfg_incl_unl)
    elif action == "buy_unlimited":
        # حالتِ نمایش این دکمه: «range» = بازهٔ روز با ➕➖ | «packages» = فقط بسته‌های
        # آمادهٔ قیمت ثابت | «both» = هر دو (حالت قدیمی، برای سازگاری با دکمه‌های قبلی)
        unl_mode = "both"
        unl_category = None
        # === PATCH_BUY_CONFIG_CFG_KIND_UNBOUND_V1 ===
        # همون باگِ عیناً در buy_config: unl_kind فقط داخلِ «if btn.config:»
        # مقداردهی می‌شد و برایِ دکمه‌های بدونِ config، پایین‌تر با
        # UnboundLocalError کرش می‌کرد.
        unl_kind = None
        if btn.config:
            try:
                _btn_cfg_json2 = json.loads(btn.config) or {}
            except Exception:
                _btn_cfg_json2 = {}
            unl_mode = _btn_cfg_json2.get("unlimited_mode", "both")
            unl_category = _norm_cat_list(_btn_cfg_json2.get("unlimited_category"))
            unl_kind = _btn_cfg_json2.get("unlimited_kind") or None
        if unl_mode != "packages":
            cfg = await get_unlimited_cfg(bot_id)
            has_unl_stock = await _bot_has_range_stock(bot_id, unlimited=True)
            if has_unl_stock:
                kb = await buy_unlimited_kb(btn.id, 0, 1, cfg, plan=row.plan,
                                      is_owner=(msg.from_user.id == row.owner_id), bot_id=bot_id)
                kb = await _attach_support(bot_id, kb, support_enabled, contact=support_contact, mb=btn)
                await msg.answer(
                    _with_btn_header(buy_unlimited_info_text(cfg), btn.message if effective_has_action else ""),
                    reply_markup=kb,
                    parse_mode="HTML",
                )
            elif unl_mode == "range":
                rows = []
                _br = await inline_back_row(bot_id)
                if _br:
                    rows.append(_br)
                kb = InlineKeyboardMarkup(inline_keyboard=rows) if rows else None
                await msg.answer(
                    _with_btn_header(
                        "♾️ فعلاً هیچ کانفیگ نامحدودی موجود نیست.\nبعداً دوباره سر بزن.",
                        btn.message if effective_has_action else ""),
                    reply_markup=kb,
                )
        if unl_mode != "range":
            # وقتی فقط «بسته‌های آماده» انتخاب شده، دکمهٔ پشتیبانی باید همینجا بچسبد
            await _show_manual_packages(
                msg, bot_id, unlimited=True,
                support_enabled=(support_enabled if unl_mode == "packages" else False),
                support_contact=support_contact,
                header=(btn.message if (effective_has_action and unl_mode == "packages") else ""), mb=btn,
                category=unl_category, kind=unl_kind)
    # === PATCH_PARTNER_V5 ===
    # از _FakeCb خودِ پروژه استفاده می‌شود — همان الگویی که booking دارد.
    elif action == "pnr_build":
        from tenant.partner_bot.partner_sales import ps_menu
        await ps_menu(_FakeCb(msg), bot)
    elif action == "pnr_mybots":
        from tenant.partner_bot.partner_user import pu_bots
        await pu_bots(_FakeCb(msg), bot)
    elif action == "wallet":
        await show_wallet(msg, bot_id, u, header=action_header)
    elif action == "api_panel":
        # === PATCH_API_PAID_ACCESS_V1 ===
        await show_api_panel(msg, bot_id, u)
    elif action == "book_show":
        from tenant.bots.booking.handlers import book_show_slots  # === PATCH_TENANT_SPLIT_PHASE2_BOOKING_V1 ===
        await book_show_slots(_FakeCb(msg), bot)
    elif action == "book_my":
        from tenant.bots.booking.handlers import book_my_appointments  # === PATCH_TENANT_SPLIT_PHASE2_BOOKING_V1 ===
        await book_my_appointments(_FakeCb(msg), bot)
    elif action == "do_start":
        # === PATCH_BTN_ACTION_RESTART_V1 ===
        # همان مسیرِ /start صدا زده می‌شود تا رفتار دقیقاً یکی باشد
        # (خوش‌آمد، عضویتِ اجباری، منویِ اصلی) و دو نسخه از یک منطق نداشته
        # باشیم. خودِ tenant_start اولین کارش state.clear است، پس اگر کاربر
        # وسطِ یک مرحله گیر کرده باشد هم واقعاً از نو شروع می‌کند.
        # tenant_start فقط command.args را می‌خواند؛ بقیهٔ فیلدها پیش‌فرض دارند.
        await tenant_start(msg, CommandObject(command="start"), bot, state)
        return
    elif action == "nft_market":
        # === PATCH_NFT_MARKET_BTN_ACTION_V1 ===
        await _open_nft_market(msg, bot_id, header=action_header)
    elif action == "escrow":
        # === PATCH_ESCROW_V1 ===
        from tenant.shared.escrow import show_menu as _escrow_menu
        await _escrow_menu(msg, bot, bot_id, header=action_header)
    elif action == "store_miniapp":
        # === PATCH_STORE_MINIAPP_BTN_ACTION_V1 ===
        await _open_store_miniapp(msg, bot_id, header=action_header)
    elif action == "buy_metered":
        # === PATCH_METERED_BTN_ACTION_V1 === بازبینیِ لحظه‌ایِ پلن (مثلِ بقیهٔ اکشن‌هایِ پلنی)
        from tenant.bots.vpn.vpn_metered import show_for_message as _mtr_show
        await _mtr_show(msg, bot, row, header=action_header)
    elif action == "buy_panel_market":
        # === PATCH_PANEL_SHOP_ACTION_V1 ===
        if not has_feature(row.plan, Feature.VPN_PANEL_MARKET):
            await msg.answer("⛔️ این دکمه در پلنِ فعلیِ ربات در دسترس نیست.",
                             reply_markup=await inline_back_kb(bot_id))
        else:
            from tenant.bots.vpn.panel_shop import show_panel_shop
            await show_panel_shop(msg, bot_id, header=action_header, support_enabled=support_enabled,
                                  support_contact=support_contact, mb=btn)
    elif action == "review_show":
        from tenant.shared.extras import review_show_form
        await review_show_form(_FakeCb(msg), bot)
    elif action == "review_list":
        from tenant.shared.extras import review_list
        await review_list(_FakeCb(msg), bot)
    elif action == "toggle_lang":
        # قابلیتِ تغییر زبان حذف شده؛ دکمهٔ قدیمی فقط منوی اصلی را نشان می‌دهد.
        if await get_setting(bot_id, "menu_mode", "reply") == "inline":
            ikb = await main_inline_kb(bot_id, row.owner_id, msg.from_user.id)
            await send_home_menu(msg, bot_id, ikb, prefer_edit=False)
        else:
            kb = await main_kb_or_remove(bot_id, row.owner_id, msg.from_user.id)
            await send_home_menu(msg, bot_id, kb or ReplyKeyboardRemove())
    elif action == "buy_vpn":
        await show_vpn_plans(bot, msg, bot_id, state=state, header=action_header, mb_id=btn.id)
    elif action and action.startswith("buy_vpn_"):
        # === PATCH_NO_ACTION_BTN_CRASH_V1 ===
        # محافظِ اضافه: با اینکه حالا مسیرِ اصلی (action=None) زودتر return
        # می‌زند، این شرط هم دیگر بدونِ محافظت رویِ None صدا زده نمی‌شود —
        # چون همینجا بود که AttributeError می‌داد.
        # === PATCH_MULTI_PANEL_INSTANCES_V1 ===
        # قبلاً فهرستِ ثابتی از اکشن‌ها بود، پس دکمه‌ای که رویِ پنلِ دومِ
        # هم‌نوع (buy_vpn_pasargad#2) ست شده بود اصلاً اجرا نمی‌شد.
        # خرید کانفیگ از پنل خاص
        panel_key = action.replace("buy_vpn_", "")
        from tenant.bots.vpn.vpn_admin import get_panel
        panel = await get_panel(bot_id, panel_key)
        if not panel or not panel.enabled:
            # === PATCH_VPN_SALE_OFF_TEXT_V1 === (باگ #155) فروشِ خاموش ≠ «پنل وصل نشده»؛ و راهنمایِ ادمین به مشتری نشان داده نشود
            await msg.answer(
                await _vpn_panel_off_text(bot_id, panel_key, panel, staff=(msg.from_user.id == row.owner_id)),
                reply_markup=await _attach_support(
                    bot_id, await inline_back_kb(bot_id), support_enabled, contact=support_contact, mb=btn))
