async def _wallet_history_content(bot_id: int, telegram_id: int) -> tuple[str, InlineKeyboardMarkup]:
    """متن و کیبوردِ تاریخچهٔ کیف پول — مشترک بینِ نسخهٔ شیشه‌ای و کیبوردی."""
    async with Session() as s:
        u = await s.scalar(select(BotUser).where(
            BotUser.bot_id == bot_id, BotUser.telegram_id == telegram_id))
        if not u:
            return "یافت نشد.", InlineKeyboardMarkup(inline_keyboard=[])
        txns = (await s.scalars(
            select(WalletTxn).where(WalletTxn.user_id == u.id)
            .order_by(WalletTxn.id.desc()).limit(10)
        )).all()
        total_spent = await s.scalar(select(func.coalesce(func.sum(WalletTxn.amount), 0)).where(
            WalletTxn.user_id == u.id, WalletTxn.kind.in_(["purchase", "renew"])))
        bal = float(u.balance)
    back_kb = InlineKeyboardMarkup(inline_keyboard=[[
        InlineKeyboardButton(text="⬅️ بازگشت به کیف پول", callback_data="w:back",
                             style=ButtonStyle.DANGER)]])
    if not txns:
        return (
            "📋 <b>تاریخچهٔ کیف پول</b>\n"
            "➖➖➖➖➖➖➖➖➖➖\n"
            f"👛 موجودی فعلی: <b>{rial(bal)}</b>\n\n"
            "هنوز تراکنشی ثبت نشده است. 🤍"
        ), back_kb
    spent = abs(float(total_spent or 0))
    header = (
        "📋 <b>تاریخچهٔ کیف پول</b>\n"
        "➖➖➖➖➖➖➖➖➖➖\n"
        f"👛 موجودی فعلی: <b>{rial(bal)}</b>\n"
        f"🧮 مجموع خریدها: <b>{rial(spent)}</b>\n"
        "➖➖➖➖➖➖➖➖➖➖\n"
        "🧾 <b>۱۰ تراکنش اخیر</b>"
    )
    blocks = []
    for t in txns:
        amt = float(t.amount)
        emj = _TXN_EMOJI.get(t.kind, "•")
        label = _TXN_LABELS.get(t.kind, t.kind)
        if amt > 0:
            money = f"🟢 +{rial(abs(amt))} تومان"
        else:
            money = f"🔴 −{rial(abs(amt))} تومان"
        d, tm = _jalali_date_time(t.created_at)
        block = f"\n{emj} <b>{label}</b>\n   {money}\n   🗓 {d}   🕒 {tm}"
        if t.note:
            block += f"\n   📝 {t.note}"
        blocks.append(block)
    return header + "\n" + "\n".join(blocks), back_kb


async def _wallet_history_text(msg: Message, bot: Bot):
    row = await get_bot_row(bot)
    if not row:
        return
    text, _ = await _wallet_history_content(row.id, msg.from_user.id)
    await msg.answer(text, reply_markup=InlineKeyboardMarkup(inline_keyboard=[[
        InlineKeyboardButton(text="⬅️ بازگشت به کیف پول", callback_data="w:back")]]))



