@tenant_router.pre_checkout_query()
async def stars_pre_checkout(pcq: PreCheckoutQuery):
    payload = pcq.invoice_payload or ""
    if payload.startswith("wallet_stars:"):
        await pcq.answer(ok=True)
    elif payload.startswith("p2pfee:"):   # === PATCH_P2P_MARKET_V1 ===
        from tenant.bots.virtual_service.nft_p2p import fee_precheck
        _ok, _why = await fee_precheck(pcq)
        await pcq.answer(ok=_ok, error_message=(None if _ok else _why))
    else:
        await pcq.answer(ok=True)


@tenant_router.message(F.successful_payment)
async def stars_successful_payment(msg: Message, bot: Bot):
    sp = msg.successful_payment
    payload = sp.invoice_payload or ""
    # === PATCH_STARS_PAYMENT_DEDUPE_V1 ===
    # اگر تلگرام همان آپدیتِ پرداخت را دوباره بفرستد (retryِ وبهوک)، قبلاً شارژ/سفارش
    # دوبار ثبت می‌شد. شناسهٔ یکتایِ پرداخت فقط یک‌بار پذیرفته می‌شود.
    _charge_id = str(getattr(sp, "telegram_payment_charge_id", "") or "")
    if _charge_id:
        from tenant.gateways.auto_receipt import claim_receipts
        if not await claim_receipts("tg_stars", [_charge_id[:120]],
                                    amount=int(sp.total_amount or 0),
                                    user_telegram_id=msg.from_user.id):
            logger.warning("پرداختِ استارزِ تکراری نادیده گرفته شد: %s", _charge_id)
            return
    if payload.startswith("wallet_stars:"):
        from tenant.gateways.stars_admin import handle_wallet_stars_payment
        await handle_wallet_stars_payment(msg, bot, sp, payload)
    elif payload.startswith("shop_stars:") or payload.startswith("shop_stars2:"):
        await _handle_shop_stars_payment(msg, bot, sp, payload)
    elif payload.startswith("bot_stars:"):   # === PATCH_BOT_STARS_TOPUP_V1 ===
        from tenant.gateways.stars_admin import handle_bot_stars_payment
        await handle_bot_stars_payment(msg, bot, sp, payload)
    elif payload.startswith("p2pfee:"):   # === PATCH_P2P_MARKET_V1 ===
        from tenant.bots.virtual_service.nft_p2p import handle_p2p_fee_payment
        await handle_p2p_fee_payment(msg, bot, sp, payload)


async def _handle_shop_stars_payment(msg: Message, bot: Bot, sp, payload: str):
    """پرداختِ موفقِ خریدِ یک محصولِ فروشگاه با استارزِ تلگرام.
    توجه: پول همین الان توسط تلگرام گرفته شده، پس تحویل همیشه انجام می‌شود
    (حتی اگر موجودی هم‌زمان به صفر رسیده باشد) — لغو/بازپرداخت اینجا معنی ندارد."""
    parts = payload.split(":", 5)
    if len(parts) < 5:
        return
    # === PATCH_GIFT_TO_FRIEND_V1 ===
    # فرمتِ جدید shop_stars2 یه فیلدِ «گیرندهٔ هدیه» هم داره؛ فرمتِ قدیمی
    # (فاکتورهای درجریان موقعِ آپدیت) همچنان پشتیبانی می‌شه.
    gift_recipient = None
    if payload.startswith("shop_stars2:"):
        parts = payload.split(":", 6)
        if len(parts) < 6:
            return
        _, bot_id_str, pid_str, price_str, code_id_str, giftto_str = parts[:6]
        try:
            gift_recipient = int(giftto_str) or None
        except Exception:
            gift_recipient = None
    else:
        _, bot_id_str, pid_str, price_str, code_id_str = parts[:5]
    try:
        bot_id = int(bot_id_str)
        pid = int(pid_str)
        final_price = float(price_str)
        code_id = int(code_id_str) or None
    except Exception:
        return
    row = await get_bot_row(bot)
    if not row or row.id != bot_id:
        return
    from tenant.bots.digital_shop.handlers import Product, ProductOrder, _gen_tracking  # === PATCH_TENANT_SPLIT_PHASE3_DIGITAL_SHOP_V1 === (قبلاً tenant/shop.py)
    async with Session() as s:
        u = await s.scalar(select(BotUser).where(
            BotUser.bot_id == row.id, BotUser.telegram_id == msg.from_user.id))
        p = await s.get(Product, pid, with_for_update=True)
        if not u or not p:
            return
        if p.stock > 0:
            p.stock -= 1
        from models import alloc_tracking_in as _alloc_in  # PATCH_SEQ_TRACKING_V1
        tracking = await _alloc_in(s, row.id)
        order = ProductOrder(
            bot_id=row.id, user_id=u.id, product_id=pid,
            amount=final_price, pay_method="stars", status="paid",
            tracking_code=tracking, discount_code_id=code_id,
            gift_recipient_tg_id=gift_recipient,  # PATCH_GIFT_TO_FRIEND_V1
        )
        s.add(order)
        if code_id:
            from tenant.gateways.discount_engine import record_usage
            await record_usage(s, code_id=code_id, bot_id=row.id, telegram_id=msg.from_user.id)
        await s.flush()          # قبلاً order.id قبل از flush خوانده می‌شد و همیشه None بود
        order_id = order.id
        await s.commit()
    kb = await main_kb_or_remove(row.id, row.owner_id, msg.from_user.id)
    await msg.answer(
        f"✅ <b>خرید موفق!</b>\n"
        f"🛍 محصول: <b>{p.title}</b>\n"
        f"💰 مبلغ: {rial(final_price)} (پرداخت با {sp.total_amount} ⭐)\n"
        f"🔖 کد پیگیری: <code>{tracking}</code>",
        reply_markup=kb)
    if p.file_id:
        await bot.send_document(msg.from_user.id, p.file_id, caption=f"📦 {p.title}")
    if p.is_gift:
        from tenant.bots.digital_shop.handlers import _notify_admin_gift_manual  # === PATCH_TENANT_SPLIT_PHASE3_DIGITAL_SHOP_V1 === (قبلاً tenant/shop.py)
        # === PATCH_GIFT_MANUAL_CONFIRM_V1 ===
        await msg.answer(
            "🎁 سفارشِ گیفتِ شما ثبت شد؛ به‌محضِ ارسال توسط مدیر، بهت اطلاع می‌دیم.")
        await _notify_admin_gift_manual(bot, row, order_id, p, gift_recipient or msg.from_user.id)
    from tenant.bots.digital_shop.handlers import _check_low_stock  # === PATCH_TENANT_SPLIT_PHASE3_DIGITAL_SHOP_V1 === (قبلاً tenant/shop.py)
    await _check_low_stock(bot, row, p)


