_TXN_LABELS = {
    "charge": "شارژ", "purchase": "خرید", "renew": "تمدید", "refund": "عودت",
    "referral": "پاداش دعوت", "deduct": "کسر", "card_charge": "شارژ کارت‌به‌کارت",
    "crypto_charge": "شارژ ارز دیجیتال", "swap_charge": "شارژ سواپ‌ولت",
}

# شکلک متناسب با نوع هر تراکنش (برای نمایش زیباتر تاریخچه)
_TXN_EMOJI = {
    "charge": "💳", "card_charge": "💳", "crypto_charge": "🪙", "swap_charge": "🟦",
    "purchase": "🛒", "renew": "🔄", "refund": "↩️", "referral": "🎁",
    "deduct": "➖", "admin": "🛠️",
}


def _jalali_date_time(dt) -> tuple[str, str]:
    """تاریخ و ساعتِ شمسی به وقت ایران (تهران) را جدا برمی‌گرداند: (تاریخ, ساعت)."""
    if dt is None:
        return "—", "—"
    try:
        local = dt + _dt.timedelta(hours=3, minutes=30)  # UTC → وقت ایران
        time_str = local.strftime("%H:%M:%S")
        if _jdt:
            date_str = _jdt.datetime.fromgregorian(datetime=local).strftime("%Y/%m/%d")
        else:
            date_str = local.strftime("%Y/%m/%d")
        return date_str, time_str
    except Exception:
        return "—", "—"


async def show_profile(msg, bot_id: int, u: BotUser):
    """نمایش «مشخصات کاربری» (مثل ربات سوپرا): اطلاعات کاربر، تراکنشها و تاریخ عضویت شمسی.

    === PATCH_PROFILE_TEMPLATE_V1 ===
    درخواستِ ادمین (فدایی): «متنِ مشخصات رو نمیشه کامل عوض کرد، فقط زیرش چیزی اضافه میشه».
    حالا اگر ادمین «قالبِ کاملِ مشخصات» (profile_template_text) گذاشته باشد، همان (با متغیرها) به‌جایِ
    متنِ پیش‌فرض نشان داده می‌شود؛ متنِ پایینی (profile_footer_text) مثلِ قبل بعدش می‌آید. اگر قالب یا
    متنِ پایین به‌خاطرِ HTMLِ ناقص/طولِ زیاد ارسال نشد، کاربر هرگز صفحهٔ خالی/خطا نمی‌بیند: نسخهٔ بدونِ
    قالب و در نهایت متنِ پیش‌فرض فرستاده می‌شود.
    """
    from tenant.shared import profile_stats as _ps
    tg_id = u.telegram_id
    async with Session() as _s_pf:
        _pf_brow = await _s_pf.get(BotRow, bot_id)
    st = await _ps.compute(bot_id, u, is_virtual_service=bool(_pf_brow and _pf_brow.field == "virtual_service"))
    account_status = _ps.account_status_text(st.account_active)
    uname = ("@" + u.username) if u.username else "—"
    full_name = _html.escape(u.full_name or "—")
    jdate, jtime = _jalali_date_time(u.joined_at)
    ref_lines = _ps.ref_summary(st)

    default_text = (
        "👤 <b>مشخصات شما</b>\n\n"
        f"🛡 شناسه کاربری : <code>{tg_id}</code>\n"
        f"🏖 نام کاربری : {uname}\n"
        f"🧑‍💼 نام : {full_name}\n"
        f"☑️ وضعیت اکانت : {account_status}\n"
        "┈┅━━⊷⊰✨⊱⊶━━┅┈\n"
        "🛍 <b>تراکنش‌ها</b>\n\n"
        f"📑 تعداد سفارشات : {st.orders_count}\n"
        f"🟢 سرویس‌های فعال : {st.active_services}\n"
        f"💵 تراکنش کل : {st.total_spent:,} تومان\n"
        f"💰 موجودی : {int(u.balance):,} تومان\n"
        "┈┅━━⊷⊰✨⊱⊶━━┅┈\n"
        "👥 <b>زیرمجموعه‌گیری</b>\n\n"
        + ref_lines +
        "\n┈┅━━⊷⊰✨⊱⊶━━┅┈\n"
        "📅 <b>تاریخ عضویت</b>\n\n"
        f"🗓 تاریخ : {jdate}\n"
        f"🕐 ساعت : {jtime}\n"
        "┈┅━━⊷⊰✨⊱⊶━━┅┈"
    )
    from tenant.shared.text_vars import render_text as _render_vars
    body = default_text
    used_template = False
    _tpl = (await get_setting(bot_id, "profile_template_text", "") or "")
    if _tpl.strip():
        try:
            body = await _render_vars(_tpl, bot_id=bot_id, user=u)
            used_template = True
        except Exception:
            logger.exception("[profile] رندرِ قالبِ مشخصات ناموفق بود؛ متنِ پیش‌فرض نشان داده شد")
    # === PATCH_PROFILE_CUSTOM_FOOTER_V1 ===
    footer = await get_setting(bot_id, "profile_footer_text", "")
    if footer:
        # === PATCH_TEXT_VARS_V1 === متغیرهایِ کاربر/ربات/زمان در این متن هم کار می‌کنند
        footer = await _render_vars(footer, bot_id=bot_id, user=u)
    text = body + (("\n\n" + footer) if footer else "")
    # === PATCH_PUBLIC_API_PER_USER_V1 ===
    kb_rows = []
    back_row = await inline_back_row(bot_id)
    # === PATCH_API_OPEN_TO_ALL_V1 === (سوئیچِ «API برایِ همه» در custom_domain.py؛ این سمتِ کاربر جا مانده بود)
    # === PATCH_API_PAID_ACCESS_V1 === دسترسی/پولی‌بودن از یک نقطه تصمیم گرفته می‌شود
    try:
        from tenant.shared.public_api import user_api_allowed as _uaa, api_price as _apr
        _prow = await get_bot_row_by_id(bot_id)
        if await _uaa(u):
            kb_rows.append([InlineKeyboardButton(text="🔑 دریافتِ API Key", callback_data="pubapi:key")])
        elif _prow and _prow.field in ("virtual_service", "vpn_sales") and await _apr(bot_id) > 0:   # PATCH_VPN_API_V1
            kb_rows.append([InlineKeyboardButton(text="🔑 خرید دسترسیِ API", callback_data="pubapi:key")])
    except Exception:
        logger.exception("[profile] نمایشِ دکمهٔ API ناموفق بود")
    if back_row:
        kb_rows.append(back_row)
    _kb = InlineKeyboardMarkup(inline_keyboard=kb_rows) if kb_rows else None
    # نسخه‌هایِ جایگزین به ترتیب: (قالب/پیش‌فرض + متنِ پایین) → (پیش‌فرض + متنِ پایین) → (فقط پیش‌فرض)
    candidates = [text]
    if used_template:
        candidates.append(default_text + (("\n\n" + footer) if footer else ""))
    if footer:
        candidates.append(default_text)
    last_exc = None
    for cand in candidates:
        try:
            await msg.answer(cand, reply_markup=_kb)
            return
        except TelegramBadRequest as e:
            last_exc = e
            logger.warning("[profile] ارسالِ صفحهٔ مشخصات رد شد (%s)؛ نسخهٔ سادهٔ بعدی امتحان می‌شود", e)
    if last_exc is not None:
        raise last_exc


# === PATCH_PUBLIC_API_PER_USER_V1 ===
# === PATCH_API_PAID_ACCESS_V1 ===
# صفحهٔ «API ربات»: هم از دکمهٔ مستقیمِ منو (action=api_panel) و هم از پروفایل
# باز می‌شود. اگر کاربر دسترسی دارد کلید را نشان می‌دهد؛ اگر API پولی است و
# دسترسی ندارد (یا منقضی شده) پیشنهادِ خرید با موجودیِ کیف پول.
def _api_period_label(days: int) -> str:
    return "دائمی" if not days else ("ماهانه (۳۰ روز)" if days == 30 else f"{days} روزه")


def _api_fmt_exp(dt) -> str:
    try:
        jd, _jt = _jalali_date_time(dt)
        return jd
    except Exception:
        return dt.strftime("%Y-%m-%d")


async def _pubapi_render(row, u, tg_id: int):
    """(text, kb) صفحهٔ API برایِ این کاربر؛ None اگر این ربات API ندارد."""
    from tenant.shared.public_api import user_api_allowed, api_price, api_period_days, api_expired
    if row.field not in ("virtual_service", "vpn_sales"):   # PATCH_VPN_API_V1
        return None
    _is_vpn_api = row.field == "vpn_sales"
    price = await api_price(row.id)
    days = await api_period_days(row.id)
    back = [InlineKeyboardButton(text="⬅️ بازگشت", callback_data="mbtn:home", style=ButtonStyle.DANGER)]
    if not await user_api_allowed(u):
        if price <= 0:
            return ("🔑 <b>API ربات</b>\n\nاین قابلیت برایِ حسابِ شما فعال نیست. "
                    "برایِ فعال‌سازی با پشتیبانی در تماس باش.",
                    InlineKeyboardMarkup(inline_keyboard=[back]))
        expired_line = "⏰ دسترسیِ قبلیِ شما منقضی شده است.\n\n" if (u.api_access and api_expired(u)) else ""
        text = (
            "🔑 <b>API ربات</b>\n\n" + expired_line +
            "با API می‌تونی سفارش‌هایِ ربات رو از پنل/سایت/ابزارِ خودت ثبت کنی.\n\n"
            f"💵 هزینه: <b>{price:,}</b> تومان\n"
            f"⏳ مدت: <b>{_api_period_label(days)}</b>\n"
            f"💰 موجودیِ شما: {int(u.balance):,} تومان")
        rows = [[InlineKeyboardButton(text=f"🛒 خرید دسترسیِ API ({price:,} تومان)",
                                      callback_data="pubapi:buy", style=ButtonStyle.SUCCESS)]]
        if float(u.balance) < price:
            rows.append([InlineKeyboardButton(text="💳 شارژ کیف پول", callback_data="w:charge")])
        rows.append(back)
        return text, InlineKeyboardMarkup(inline_keyboard=rows)

    if not u.api_key:
        import secrets as _secrets
        async with Session() as s:
            uu = await s.scalar(select(BotUser).where(
                BotUser.bot_id == row.id, BotUser.telegram_id == tg_id).with_for_update())
            if not uu.api_key:
                uu.api_key = _secrets.token_hex(24)
            await s.commit()
            key = uu.api_key
    else:
        key = u.api_key
    # === PATCH_API_PAGE_CLEAN_V1 ===
    # درخواستِ ادمین (فدایی): «این خیلی شلوغ و نامعلومه؛ آدرسِ استاندارد باید باشه با کلید، بقیه چیه این همه؟»
    # حالا: آدرسِ استانداردِ v2 + موجودی + کلید + وضعیت + شمارندهٔ سفارش‌هایِ API + لینکِ مستندات، و چهار دکمه.
    # (آدرسِ v1، هدرِ X-API-Key و توضیحاتِ طولانی به صفحهٔ مستندات رفت؛ خودِ v1 هم هنوز کار می‌کند.)
    from tenant.gateways.custom_domain import get_bot_webhook_base
    base = (await get_bot_webhook_base(row.id) or "").rstrip("/")
    async with Session() as s_cnt:
        n_api = int(await s_cnt.scalar(select(func.count(SmmOrder.id)).where(
            SmmOrder.bot_id == row.id, SmmOrder.user_telegram_id == tg_id,
            SmmOrder.source == "api")) or 0)
    lines = [
        "🔑 <b>API</b>", "",
        "🔗 آدرس API:", f"<code>{base}/api/vpn</code>" if _is_vpn_api else f"<code>{base}/api/v2</code>", "",
        f"💰 موجودی شما: <b>{int(u.balance):,}</b> تومان",
    ]
    if u.api_discount_pct:
        lines.append(f"🎁 تخفیفِ شما رویِ خریدهایِ API: {float(u.api_discount_pct):g}٪")
    if u.api_expires_at:
        lines.append(f"⏳ اعتبارِ دسترسی تا: <b>{_api_fmt_exp(u.api_expires_at)}</b>")
    elif u.api_access:
        lines.append("♾ دسترسیِ دائمی")
    lines += ["", "🛡 کلید API شما:", f"<code>{key}</code>", "",
              "✅ وضعیت کلید: فعال"]
    if not _is_vpn_api:
        lines.append(f"🛒 سفارش‌هایِ API: <b>{n_api}</b>")
    else:
        lines += ["", "اکشن‌ها: <code>plans</code> · <code>balance</code> · <code>buy</code> · "
                      "<code>services</code> · <code>status</code>"]
    docs_url = f"{base}/api/docs/vpn" if _is_vpn_api else f"{base}/api/docs"   # PATCH_VPN_API_V1
    lines += ["", f"📘 مستندات: {docs_url}"]
    text = "\n".join(lines)
    rows = [[InlineKeyboardButton(text="🔄 تغییر کلید", callback_data="pubapi:regen", style=ButtonStyle.DANGER)]
            + ([] if _is_vpn_api else
               [InlineKeyboardButton(text="📋 سفارش‌هایِ API", callback_data="pubapi:orders", style=ButtonStyle.PRIMARY)])]
    if not _is_vpn_api:
        # === PATCH_API_ORDER_NOTIFY_V1 === روشن/خاموشِ پیامِ وضعیتِ سفارش‌هایِ وب‌سرویس (با برچسبِ #وبسرویس)
        from tenant.bots.virtual_service.smm import api_notify_enabled
        _non = await api_notify_enabled(row.id, tg_id)
        rows.append([InlineKeyboardButton(
            text=("🟢 اعلان سفارشات وبسرویس 🟢" if _non else "🔴 اعلان سفارشات وبسرویس 🔴"),
            callback_data="pubapi:notif",
            style=(ButtonStyle.SUCCESS if _non else ButtonStyle.DANGER))])
    if docs_url.startswith(("http://", "https://")) and "YOUR" not in docs_url:
        rows.append([InlineKeyboardButton(text="📘 مستندات API", url=docs_url, style=ButtonStyle.PRIMARY)])
    if price > 0 and u.api_expires_at:
        rows.append([InlineKeyboardButton(text=f"♻️ تمدید ({price:,} تومان)",
                                          callback_data="pubapi:buy", style=ButtonStyle.SUCCESS)])
    rows.append(back)
    return text, InlineKeyboardMarkup(inline_keyboard=rows)


async def show_api_panel(msg, bot_id: int, u: BotUser):
    """اکشنِ دکمهٔ مستقیمِ «🔑 API ربات»."""
    row = await get_bot_row_by_id(bot_id)
    if not row:
        return
    async with Session() as s:
        fresh = await s.scalar(select(BotUser).where(
            BotUser.bot_id == bot_id, BotUser.telegram_id == u.telegram_id))
    res = await _pubapi_render(row, fresh or u, u.telegram_id)
    if res is None:
        await msg.answer("این بخش در حالِ حاضر در دسترس نیست.")
        return
    text, kb = res
    await msg.answer(text, reply_markup=kb)


@tenant_router.callback_query(F.data == "pubapi:key")
async def pubapi_key_show(cb: CallbackQuery, bot: Bot):
    row = await get_bot_row(bot)
    if not row:
        await cb.answer()
        return
    async with Session() as s:
        u = await s.scalar(select(BotUser).where(
            BotUser.bot_id == row.id, BotUser.telegram_id == cb.from_user.id))
    if not u:
        await cb.answer("این قابلیت برایِ شما فعال نیست.", show_alert=True)
        return
    res = await _pubapi_render(row, u, cb.from_user.id)
    if res is None:
        await cb.answer("این قابلیت برایِ شما فعال نیست.", show_alert=True)
        return
    text, kb = res
    await edit_or_replace(cb.message, text, reply_markup=kb)
    await cb.answer()


# === PATCH_API_PAGE_CLEAN_V1 === «📋 سفارش‌هایِ API»: آخرین سفارش‌هایی که خودِ کاربر از راهِ API ثبت کرده
_API_ORDERS_PAGE = 15


async def _pubapi_orders_content(bot_id: int, tg_id: int):
    from tenant.bots.virtual_service.smm import _SMM_STATUS_LABEL
    async with Session() as s:
        total = int(await s.scalar(select(func.count(SmmOrder.id)).where(
            SmmOrder.bot_id == bot_id, SmmOrder.user_telegram_id == tg_id, SmmOrder.source == "api")) or 0)
        orders = (await s.scalars(select(SmmOrder).where(
            SmmOrder.bot_id == bot_id, SmmOrder.user_telegram_id == tg_id, SmmOrder.source == "api"
        ).order_by(SmmOrder.id.desc()).limit(_API_ORDERS_PAGE))).all()
    kb = InlineKeyboardMarkup(inline_keyboard=[[
        InlineKeyboardButton(text="⬅️ بازگشت", callback_data="pubapi:key", style=ButtonStyle.DANGER)]])
    if not orders:
        return ("📋 <b>سفارش‌هایِ API</b>\n\nهنوز سفارشی از راهِ API ثبت نکرده‌ای.\n"
                "(سفارش‌هایی که از داخلِ ربات می‌دهی در «📦 سفارش‌هایِ من» است.)"), kb
    lines = [f"📋 <b>سفارش‌هایِ API</b> ({total:,} سفارش" + (f"؛ آخرین {len(orders)}" if total > len(orders) else "") + ")", ""]
    for o in orders:
        label = _SMM_STATUS_LABEL.get((o.status or "").lower(), o.status or "—")
        name = (o.service_name or "—")[:28]
        lines.append(f"<code>{o.tracking_code or o.id}</code> · {label.split()[0]} · {name} × {int(o.quantity or 0):,} · {int(o.price_toman or 0):,}ت")
    return "\n".join(lines), kb


@tenant_router.callback_query(F.data == "pubapi:orders")
async def pubapi_orders(cb: CallbackQuery, bot: Bot):
    row = await get_bot_row(bot)
    if not row or row.field != "virtual_service":   # PATCH_VPN_API_V1
        await cb.answer()
        return
    from tenant.shared.public_api import user_api_allowed
    async with Session() as s:
        u = await s.scalar(select(BotUser).where(
            BotUser.bot_id == row.id, BotUser.telegram_id == cb.from_user.id))
    if not u or not await user_api_allowed(u):
        await cb.answer("این قابلیت برایِ شما فعال نیست.", show_alert=True)
        return
    text, kb = await _pubapi_orders_content(row.id, cb.from_user.id)
    await edit_or_replace(cb.message, text, reply_markup=kb)
    await cb.answer()


@tenant_router.callback_query(F.data == "pubapi:notif")
async def pubapi_notify_toggle(cb: CallbackQuery, bot: Bot):
    """PATCH_API_ORDER_NOTIFY_V1"""
    row = await get_bot_row(bot)
    if not row or row.field != "virtual_service":
        await cb.answer()
        return
    from tenant.shared.public_api import user_api_allowed
    from tenant.bots.virtual_service.smm import api_notify_enabled, set_api_notify
    async with Session() as s:
        u = await s.scalar(select(BotUser).where(
            BotUser.bot_id == row.id, BotUser.telegram_id == cb.from_user.id))
    if not u or not await user_api_allowed(u):
        await cb.answer("این قابلیت برایِ شما فعال نیست.", show_alert=True)
        return
    on = not await api_notify_enabled(row.id, cb.from_user.id)
    await set_api_notify(row.id, cb.from_user.id, on)
    res = await _pubapi_render(row, u, cb.from_user.id)
    if res:
        await edit_or_replace(cb.message, res[0], reply_markup=res[1])
    await cb.answer("🟢 از این به بعد وضعیتِ سفارش‌هایِ وب‌سرویس (با #وبسرویس) برات میاد." if on
                    else "🔴 اعلانِ سفارش‌هایِ وب‌سرویس خاموش شد.", show_alert=True)


@tenant_router.callback_query(F.data == "pubapi:regen")
async def pubapi_key_regen(cb: CallbackQuery, bot: Bot):
    row = await get_bot_row(bot)
    if not row:
        await cb.answer()
        return
    import secrets as _secrets
    from tenant.shared.public_api import user_api_allowed
