def _fmt_txn_time(dt) -> str:
    if dt is None:
        return ""
    try:
        local = dt + _dt.timedelta(hours=3, minutes=30)  # وقت ایران
        if _jdt:
            return _jdt.datetime.fromgregorian(datetime=local).strftime("%Y/%m/%d %H:%M")
        return local.strftime("%Y/%m/%d %H:%M")
    except Exception:
        return ""


def _fmt_exp_jalali(dt, with_time: bool = True) -> str:
    """تاریخ انقضای یک کد تخفیف (که به‌صورت UTC ذخیره شده) را به شمسی و به وقت
    ایران نمایش می‌دهد. اگر jdatetime نصب نباشد، به میلادی برمی‌گردد."""
    if dt is None:
        return "ندارد"
    try:
        local = dt + _dt.timedelta(hours=3, minutes=30)  # وقت ایران
        fmt = "%Y/%m/%d %H:%M" if with_time else "%Y/%m/%d"
        if _jdt:
            return _jdt.datetime.fromgregorian(datetime=local).strftime(fmt)
        return local.strftime(fmt)
    except Exception:
        return "نامعتبر"


def _parse_exp_jalali(raw: str):
    """تاریخِ انقضای وارد شده به شمسی (YYYY-MM-DD یا YYYY/MM/DD، به وقت ایران) را
    می‌گیرد و datetime میلادیِ UTC (برای ذخیره در DiscountCode.expires_at) برمی‌گرداند.
    اگر فرمت نامعتبر بود، None برمی‌گرداند."""
    raw = (raw or "").strip().replace("/", "-")
    if not _jdt:
        try:
            return _dt.datetime.strptime(raw, "%Y-%m-%d")
        except Exception:
            return None
    try:
        y, m, d = (int(p) for p in raw.split("-"))
        j = _jdt.date(y, m, d)
        g = j.togregorian()  # تاریخ میلادی معادل، به وقت ایران (نیمه‌شب محلی)
        local_midnight = _dt.datetime(g.year, g.month, g.day)
        return local_midnight - _dt.timedelta(hours=3, minutes=30)  # تبدیل به UTC
    except Exception:
        return None


