async def _admin_referral_summary(bot_id: int, user_id: int) -> str | None:
    """خلاصهٔ زیرمجموعه‌گیریِ یک کاربر (تعداد دعوت‌شده‌ها + مجموع پاداش دریافتی)
    برای نمایش در پیام‌های اطلاع‌رسانیِ خریدِ محصول به ادمین. اگر کاربر هیچ
    دعوتی نداشته و پاداشی هم نگرفته، None برمی‌گرداند."""
    async with Session() as s:
        ref_link = await s.scalar(select(ReferralLink).where(
            ReferralLink.bot_id == bot_id, ReferralLink.user_id == user_id))
        ref_count = int(ref_link.join_count) if ref_link else 0
        ref_earned = await s.scalar(select(func.coalesce(func.sum(WalletTxn.amount), 0)).where(
            WalletTxn.bot_id == bot_id, WalletTxn.user_id == user_id,
            WalletTxn.kind == "referral")) or 0
    if ref_count == 0 and not ref_earned:
        return None
    return (
        f"👥 زیرمجموعه‌های دعوت‌شده: {ref_count} نفر\n"
        f"🎁 مجموع پاداش دریافتی: {rial(float(ref_earned))}"
    )


# === PATCH_ORDER_SOURCE_LINE_V1 ===
# در رسیدِ ادمین فقط «۲۰ گیگ / ۳۰ روز» نوشته می‌شد. اگر ربات چند پنل یا چند
# دستهٔ قیمتی داشته باشد (مثلاً «اقتصادی» و «حرفه‌ای» با حجمِ یکسان و قیمتِ
# متفاوت)، ادمین نمی‌فهمد کاربر از کدام دکمه خریده و نمی‌تواند تشخیص دهد
# رسیدِ فرستاده‌شده با قیمتِ همان بسته می‌خواند یا با بستهٔ ارزان‌ترِ هم‌حجم.
# این تابع پنل و پلنِ دقیق را از رویِ سفارش پیدا می‌کند.
async def order_source_lines(order: "Order") -> str:
    """خطّ‌هایِ «منبعِ دقیقِ خرید» برایِ نمایش در رسیدِ ادمین.

    سه حالت پوشش داده می‌شود:
      • خریدِ پلنِ پنل  → پنل + نامِ بسته + دسته‌بندی + قیمتِ مصوب
      • خریدِ کانفیگِ انبارِ دستی → کدِ کانفیگ + دستهٔ انبار + قیمتِ مصوب
      • خریدِ سفارشیِ حجم/روز → فقط پنل (بسته‌ای در کار نیست)

    هیچ‌وقت خطا نمی‌دهد؛ این فقط اطلاعاتِ نمایشی است و نباید جلوی ثبتِ
    رسید را بگیرد.
    """
    try:
        from tenant.bots.vpn.vpn_admin import PANEL_LABELS
        from models import Config, VpnPlan

        lines: list[str] = []

        # ── کانفیگِ انبارِ دستی ──
        cfg_id = getattr(order, "reserved_config_id", None)
        if cfg_id:
            async with Session() as s:
                cfg = await s.get(Config, cfg_id)
            if cfg:
                lines.append("🗃 منبع: انبارِ کانفیگ‌هایِ دستی")
                lines.append(f"🔢 کدِ کانفیگ: <code>{cfg.code}</code>")
                if cfg.category:
                    lines.append(f"🗂 دستهٔ انبار: {_html.escape(cfg.category)}")
                if cfg.user_count:
                    lines.append(f"👥 تعدادِ کاربرِ مجاز: {cfg.user_count}")
                if cfg.price:
                    lines.append(f"💵 قیمتِ مصوبِ کانفیگ: {rial(float(cfg.price))}")
            return "\n".join(lines)

        pkey = getattr(order, "panel_key", None)
        plan_id = getattr(order, "plan_id", None)
        if not pkey and not plan_id:
            return ""

        plan = None
        async with Session() as s:
            if plan_id:
                # مسیرِ دقیق: پلنی که کاربر رویش کلیک کرده، ذخیره شده است.
                plan = await s.get(VpnPlan, plan_id)
                if plan and plan.bot_id != order.bot_id:
                    plan = None
            if plan is None and pkey:
                # سفارش‌هایِ قدیمی (پیش از PATCH_ORDER_PLAN_ID_V1): حدسِ
                # پلن از رویِ حجم/مدت و در صورتِ ابهام، قیمتِ واحد.
                plans = (await s.scalars(select(VpnPlan).where(
                    VpnPlan.bot_id == order.bot_id,
                    VpnPlan.panel_key == pkey,
                    VpnPlan.volume_gb == order.volume_gb,
                    VpnPlan.days == order.days))).all()
                if len(plans) == 1:
                    plan = plans[0]
                elif plans:
                    unit = float(order.amount) / max(int(order.count or 1), 1)
                    plan = min(plans, key=lambda p: abs(float(p.price) - unit))

        panel_key = (plan.panel_key if plan else pkey)
        if panel_key:
            lines.append(f"🖥 پنل: {PANEL_LABELS.get(panel_key, panel_key)}")
        if plan:
            lines.append(f"🏷 بسته: {_html.escape(plan.title)}")
            if plan.category:
                lines.append(f"🗂 دسته‌بندی: {_html.escape(plan.category)}")
            lines.append(f"💵 قیمتِ مصوبِ بسته: {rial(float(plan.price))}")
            if not plan_id:
                lines.append("<i>(بستهٔ حدس‌زده‌شده — سفارشِ قدیمی)</i>")
        else:
            lines.append("🏷 بسته: سفارشی (حجم/مدتِ انتخابیِ کاربر)")
        return "\n".join(lines)
    except Exception:
        logger.exception("order_source_lines: پیداکردنِ منبعِ سفارش ناموفق")
        return ""


async def _admin_user_block(u: "BotUser", tg_id: int, tracking_code: str | None = None,
                             bot_id: int | None = None) -> str:
    """بلوک استاندارد اطلاعات کاربر برای پیام‌های رسید/تایید ادمین.
    یوزرنیم به‌صورت لینک است: با زدنش مستقیم پروفایل تلگرام شخص باز می‌شود.
    اگر bot_id داده شود و کاربر از طریق لینک دعوت وارد شده باشد، اطلاعات
    دعوت‌کننده (رفرال) هم اضافه می‌شود."""
    name = _html.escape(u.full_name or "—") if u else "—"
    if u and u.username:
        safe_uname = _html.escape(u.username)
        uname = f'<a href="https://t.me/{safe_uname}">@{safe_uname}</a>'
    elif u:
        # بدون یوزرنیم: با آیدی عددی به پروفایل لینک می‌شود (اگر حریم‌خصوصی کاربر اجازه دهد)
        uname = f'<a href="tg://user?id={tg_id}">🔗 مشاهده پروفایل</a>'
    else:
        uname = "—"
    bal = rial(float(u.balance)) if u else "—"
    lines = [
        f"👤 نام: {name}",
        f"📇 یوزرنیم: {uname}",
        # === PATCH_ADMIN_ID_LINK_V1 === آیدی عددی لینکِ مستقیمِ چت (tg://openmessage) است، نه عددِ خام
        f'📱 آیدی تلگرام: <a href="tg://openmessage?user_id={tg_id}">{tg_id}</a>',
        f"💰 موجودی فعلی: {bal}",
    ]
    # === PATCH_PAY_PHONE_VERIFY_V1 ===
    # شمارهٔ تاییدشده در همهٔ پیام‌هایِ رسید/تاییدِ ادمین دیده می‌شود تا اگر
    # کاربر از تاییدِ پرداخت خبردار نشد، بشود مستقیم باهاش تماس گرفت.
    if u and getattr(u, "phone_number", None):
        _ph = _html.escape(str(u.phone_number))
        lines.append(f"☎️ شمارهٔ تاییدشده: <code>{_ph}</code>")
    if tracking_code:
        lines.append(f"🔖 کد پیگیری: <code>{tracking_code}</code>")
    if bot_id and u:
        async with Session() as s:
            rj = await s.scalar(select(ReferralJoin).where(
                ReferralJoin.bot_id == bot_id,
                ReferralJoin.referred_telegram_id == tg_id))
            inviter = await s.get(BotUser, rj.inviter_user_id) if rj else None
        if inviter:
            inv_name = _html.escape(inviter.full_name or "—")
            if inviter.username:
                safe_inv_uname = _html.escape(inviter.username)
                inv_uname = f'<a href="https://t.me/{safe_inv_uname}">@{safe_inv_uname}</a>'
            else:
                inv_uname = f'<a href="tg://user?id={inviter.telegram_id}">🔗 مشاهده پروفایل</a>'
            lines.append(
                f"🔗 دعوت‌شده توسط: {inv_name} ({inv_uname}) — <code>{inviter.telegram_id}</code>"
            )
    return "\n".join(lines)


async def _admin_user_configs_block(bot_id: int, u: "BotUser | None", max_show: int = 5,
                                    bot_field: str | None = None) -> str:
    """خلاصهٔ کانفیگ‌های کاربر (خودکارِ روی پنل + دستیِ انبار) برای پیام‌های ادمین
    (مثلاً وقتی کاربر روی دکمهٔ پشتیبانی می‌زند، تا ادمین بدون پرس‌وجو ببیند این
    شخص چه سرویس‌هایی خریده).

    === PATCH_SUPPORT_NOTIF_FIELD_AWARE_V1 ===
    باگ: این بخش همیشه، حتی برایِ ربات‌هایی که اصلاً VPN نمی‌فروشند (مثلِ
    «مدیریتِ گروه و کانال»)، در پیامِ درخواستِ پشتیبانی می‌نشست — با متنِ
    گیج‌کننده‌ای مثلِ «کاربر هنوز هیچ کانفیگی خریداری نکرده»، درحالی‌که آن
    ربات اصلاً مفهومِ «کانفیگ» ندارد. حالا فقط برایِ ربات‌هایِ vpn_sales
    نمایش داده می‌شود؛ برایِ بقیه، این خط اصلاً به پیام اضافه نمی‌شود.
    """
    if bot_field is None:
        async with Session() as s:
            _row = await s.scalar(select(BotRow).where(BotRow.id == bot_id))
        bot_field = _row.field if _row else "vpn_sales"
    if bot_field != "vpn_sales":
        return ""
    if not u:
        return "📦 کانفیگ‌ها: —"
    async with Session() as s:
        panel_accs = (await s.scalars(select(PanelAccount).where(
            PanelAccount.bot_id == bot_id, PanelAccount.user_telegram_id == u.telegram_id,
        ).order_by(PanelAccount.created_at.desc()))).all()
        manual_cfgs = (await s.scalars(select(Config).where(
            Config.bot_id == bot_id, Config.owner_user_id == u.id,
            Config.status.in_(["sold", "stopped"])
        ).order_by(Config.code.desc()))).all()

    total = len(panel_accs) + len(manual_cfgs)
    if total == 0:
        return "📦 <b>کانفیگ‌ها:</b> کاربر هنوز هیچ کانفیگی خریداری نکرده."

    _st_icon = {"active": "✅", "sold": "✅", "stopped": "⛔️", "disabled": "⛔️"}
    lines = [f"📦 <b>کانفیگ‌های کاربر</b> ({total} مورد):"]
    shown = 0
    for a in panel_accs:
        if shown >= max_show:
            break
        if getattr(a, "volume_mb", None) and int(a.volume_gb or 0) == 0:
            vol = f"{a.volume_mb} مگابایت"
        else:
            vol = "نامحدود" if int(a.volume_gb or 0) == 0 else f"{a.volume_gb} گیگ"
        icon = _st_icon.get(a.status or "active", "•")
        title = _html.escape(a.plan_title or "کانفیگ خودکار")
        lines.append(f"  {icon} {title} — {vol}/{a.days}روز")
        shown += 1
    for c in manual_cfgs:
        if shown >= max_show:
            break
        vol = "نامحدود" if int(c.volume_gb or 0) == 0 else f"{c.volume_gb} گیگ"
        icon = _st_icon.get(c.status, "•")
        lines.append(f"  {icon} کانفیگ #{c.code} — {vol}/{fmt_days(c.days)}")
        shown += 1
    remaining = total - shown
    if remaining > 0:
        lines.append(f"  … و {remaining} مورد دیگر")
    return "\n".join(lines)


# === PATCH_USER_ERRORS_GENERIC_V1 ===
# گزارش (ساجد): خطایِ فنیِ ساخت/تمدید (با آدرسِ پنل و …) به مشتری نشان داده می‌شد. حالا مشتری فقط یک پیامِ
# کوتاهِ «دوباره امتحان کن» می‌بیند؛ جزئیاتِ فنی برایِ مالک/ادمین‌ها می‌رود (حداکثر هر ۲ دقیقه یک‌بار برایِ
# هر نقطه تا اسپم نشود) و در لاگ هم هست.
USER_FAIL_TEXT = "🙏 مشکلی پیش اومد؛ لطفاً دوباره امتحان کن."
_ERR_REPORT_LAST: dict = {}


async def report_user_error(bot: Bot, bot_id: int, where: str, err, tg_id: int | None = None) -> None:
    try:
        import time as _tm
        key = (bot_id, where)
        now = _tm.monotonic()
        if now - _ERR_REPORT_LAST.get(key, 0) < 120:
            return
        _ERR_REPORT_LAST[key] = now
        row = await get_bot_row_by_id(bot_id)
        if not row:
            return
        txt = (f"⚠️ خطا برایِ مشتری — {where}\n"
               + (f"🆔 کاربر: <code>{tg_id}</code>\n" if tg_id else "")
               + f"<code>{_html.escape(str(err)[:400])}</code>\n\n"
               "مشتری فقط پیامِ «دوباره امتحان کن» را دید. اگر تکرار شد پنل/تنظیمات را بررسی کن.")
        await _notify_admins(bot, row, txt)
    except Exception:
        logger.exception("report_user_error ناموفق بود")


async def _notify_admins(bot: Bot, row: BotRow, text: str,
                          kb: InlineKeyboardMarkup | None = None,
                          photo_file_id: str | None = None):
    targets = [row.owner_id]
    async with Session() as s:
        adms = (await s.scalars(select(AdminSupport).where(AdminSupport.bot_id == row.id))).all()
        # PATCH_ADMIN_PANEL_ADD_ONLY_V1 — ادمینِ «فقط اتصالِ پنل» سفارش/رسید/قیمت نمی‌بیند
        targets += [a.telegram_id for a in adms if not _perms_is_addonly(a.permissions)]
    for tid in set(targets):
        try:
            if photo_file_id:
                await bot.send_photo(tid, photo_file_id, caption=text, reply_markup=kb, parse_mode="HTML")  # === PATCH_RECEIPT_HTML_PARSEMODE ===
            else:
                await bot.send_message(tid, text, reply_markup=kb, parse_mode="HTML")  # === PATCH_RECEIPT_HTML_PARSEMODE ===
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")


# === PATCH_MANUAL_ORDER_CHANNEL_V1 ===
async def manual_order_channel_active(bot_id: int) -> bool:
    chat = (await get_setting(bot_id, "smm_manual_channel_id", "") or "").strip()
    return bool(chat) and await get_setting(bot_id, "smm_manual_channel_enabled", "0") == "1"


async def _notify_manual_order(bot: Bot, row: BotRow, text: str,
                               kb: InlineKeyboardMarkup | None = None,
                               photo_file_id: str | None = None) -> None:
    """سفارشِ دستی‌ای که ادمین باید انجام/تأیید کند (گیفت، استارز، پرمیوم، تون،
    ری‌اکشن — چه کیف‌پول چه کارت‌به‌کارت): اگر «کانالِ سفارشاتِ دستی» وصل و فعال
    باشد همان‌جا پست می‌شود تا تیم همان‌جا تأیید کند؛ وگرنه (یا اگر ارسال خطا داد)
    همان رفتارِ قبلی — پیامِ خصوصی به مالک و ادمین‌ها. دکمه‌ها در کانال هم با
    is_owner_or_admin کنترل می‌شوند."""
    try:
        chat = (await get_setting(row.id, "smm_manual_channel_id", "") or "").strip()
        if chat and await get_setting(row.id, "smm_manual_channel_enabled", "0") == "1":
            if photo_file_id:
                await bot.send_photo(chat, photo_file_id, caption=text, reply_markup=kb, parse_mode="HTML")
            else:
                await bot.send_message(chat, text, reply_markup=kb, parse_mode="HTML")
            return
    except Exception:
        logger.exception("ارسالِ سفارشِ دستی به کانالِ سفارشات ناموفق بود (bot_id=%s)؛ "
                         "به پیامِ خصوصیِ ادمین برمی‌گردیم", row.id)
    await _notify_admins(bot, row, text, kb, photo_file_id=photo_file_id)


# === PATCH_RECEIPT_CHANNEL_V1 ===
async def _notify_receipt_admins(bot: Bot, row: BotRow, text: str,
                                  kb: InlineKeyboardMarkup | None = None,
                                  photo_file_id: str | None = None):
    """مثلِ `_notify_admins`، مخصوصِ اطلاع‌رسانیِ رسیدِ پرداخت: اگه «کانالِ
    تاییدِ رسید» وصل و فعال باشه، به‌جایِ پیامِ خصوصیِ جداگانه به تک‌تکِ
    ادمین‌ها، فقط یک پیام به همون کانال پست می‌شه. اگه کانال وصل نبود، فعال
    نبود، یا ارسال بهش به هر دلیلی خطا داد، بی‌صدا به رفتارِ قبلی (DM به
    مالک + ادمین‌هایِ پشتیبانی) برمی‌گردیم — این قابلیت هیچ‌وقت نباید خودِ
    رسیدنِ اطلاعِ رسید رو مختل کنه.

    توجه: زدنِ دکمه‌هایِ تایید/رد همچنان از `is_owner_or_admin` رد می‌شود؛
    وصل‌بودنِ کانال فقط مسیرِ رسیدنِ پیام را عوض می‌کند، نه اینکه چه کسی
    مجاز به تصمیم‌گیری است."""
    channel_id = await get_setting(row.id, "receipt_channel_id", "")
    channel_enabled = await get_setting(row.id, "receipt_channel_enabled", "0") == "1"
    if channel_enabled and channel_id:
        try:
            if photo_file_id:
                await bot.send_photo(int(channel_id), photo_file_id, caption=text, reply_markup=kb, parse_mode="HTML")  # === PATCH_RECEIPT_HTML_PARSEMODE ===
            else:
                await bot.send_message(int(channel_id), text, reply_markup=kb, parse_mode="HTML")  # === PATCH_RECEIPT_HTML_PARSEMODE ===
            return
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود) — "
                             "ارسال به کانالِ تاییدِ رسید شکست خورد؛ برمی‌گردیم به DM ادمین‌ها")
    await _notify_admins(bot, row, text, kb, photo_file_id)


