@tenant_router.callback_query(F.data == "noop")
async def tenant_noop(cb: CallbackQuery):
    await cb.answer()


@tenant_router.callback_query(F.data.startswith("bs:"))
async def buy_adjust(cb: CallbackQuery, state: FSMContext, bot: Bot):
    _, field, sign, mbid, vi, di, c = cb.data.split(":")
    mbid, vi, di, c = int(mbid), int(vi), int(di), int(c)
    res = await get_btn_cfg(mbid)
    if not res:
        await cb.answer()
        return
    cfg, _ = res
    row = await get_bot_row(bot)
    step = 1 if sign == "p" else -1
    if field == "v":
        vi = max(0, min(len(cfg["vols"]) - 1, vi + step))
    elif field == "d":
        di = max(0, min(len(cfg["days"]) - 1, di + step))
    else:
        counts = cfg.get("counts", [1])
        cmin, cmax = (min(counts), max(counts)) if counts else (1, 99)
        c = max(cmin, min(cmax, c + step))
    data = await state.get_data()
    disc = data.get("discount_pct", 0)
    plan = row.plan if row else "free"
    is_owner = bool(row and cb.from_user.id == row.owner_id)
    try:
        await cb.message.edit_reply_markup(reply_markup=await buy_kb(mbid, vi, di, c, cfg, disc, plan=plan, is_owner=is_owner, bot_id=(row.id if row else None)))
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.answer()


@tenant_router.callback_query(F.data == "disc:locked")
async def disc_locked(cb: CallbackQuery):
    await cb.answer("🔒 کد تخفیف فقط در پلن رشد و حرفه‌ای فعال است.", show_alert=True)


@tenant_router.callback_query(F.data.startswith("bdrm:"))
async def buy_disc_remove(cb: CallbackQuery, state: FSMContext, bot: Bot):
    """حذف کد تخفیفِ اعمال‌شده و به‌روزرسانی همان پیام خرید (حجمی یا نامحدود)."""
    parts = cb.data.split(":")
    kind = parts[1]  # "v" = خرید حجمی | "u" = نامحدود
    row = await get_bot_row(bot)
    if not row:
        await cb.answer()
        return
    # پاک‌کردن تخفیف از state
    await state.update_data(discount_pct=0, discount_code=None, discount_code_id=None)
    is_owner = bool(cb.from_user.id == row.owner_id)
    try:
        if kind == "u":
            mbid, di, c = int(parts[2]), int(parts[3]), int(parts[4])
            cfg = await get_unlimited_cfg(row.id)
            await cb.message.edit_reply_markup(
                reply_markup=await buy_unlimited_kb(mbid, di, c, cfg, 0, plan=row.plan, is_owner=is_owner, bot_id=row.id))
        else:  # "v"
            mbid, vi, di, c = int(parts[2]), int(parts[3]), int(parts[4]), int(parts[5])
            res = await get_btn_cfg(mbid)
            if res:
                cfg, _ = res
                await cb.message.edit_reply_markup(
                    reply_markup=await buy_kb(mbid, vi, di, c, cfg, 0, plan=row.plan, is_owner=is_owner, bot_id=row.id))
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.answer("کد تخفیف حذف شد ✅")


