@tenant_router.message(BuyFSM.discount_unlimited, F.text)
async def buy_unlimited_disc_enter(msg: Message, state: FSMContext, bot: Bot):
    code = msg.text.strip()
    row = await get_bot_row(bot)
    if not row:
        await state.clear()
        return
    tg_id = msg.from_user.id
    async with Session() as s:
        dc = await s.scalar(select(DiscountCode).where(
            DiscountCode.bot_id == row.id, DiscountCode.code == code,
            DiscountCode.is_active == True))
        if dc:
            already_used = await s.scalar(select(DiscountUsage).where(
                DiscountUsage.discount_code_id == dc.id,
                DiscountUsage.telegram_id == tg_id))
    if not dc or (dc.max_uses > 0 and dc.used_count >= dc.max_uses):
        await msg.answer("❌ کد تخفیف نامعتبر یا منقضی شده است.")
        await state.clear()
        return
    if already_used:
        await msg.answer("❌ شما قبلاً از این کد تخفیف استفاده کرده‌اید.")
        await state.clear()
        return
    data0 = await state.get_data()
    if dc.button_id is not None and dc.button_id != data0.get("discu_mbid"):
        await msg.answer("❌ این کد مخصوص یک دکمهٔ دیگر است.")
        await state.clear()
        return
    # محدودیت بخش: کدِ مخصوص پنل/پلن فقط در همان بخش VPN کار می‌کند، نه در فروشگاه
    if dc.panel_key or dc.plan_id:
        await msg.answer("❌ این کد مخصوص بخش دیگری است و در فروشگاه قابل استفاده نیست.")
        await state.clear()
        return
    if dc.expires_at is not None and dc.expires_at < _dt.datetime.utcnow():
        await msg.answer("❌ این کد منقضی شده است.")
        await state.clear()
        return
    if (dc.disc_type or "percent") != "percent" or (dc.percent or 0) <= 0:
        await msg.answer("❌ این نوع کد در این بخش پشتیبانی نمی‌شود (مخصوص بخش VPN است).")
        await state.clear()
        return
    data = await state.get_data()
    await state.clear()
    await state.update_data(discount_pct=dc.percent, discount_code=code, discount_code_id=dc.id)
    mbid = data["discu_mbid"]
    di, c = data["discu_di"], data["discu_c"]
    cfg = await get_unlimited_cfg(row.id)
    kb = await main_kb_or_remove(row.id, row.owner_id, msg.from_user.id)
    await msg.answer(f"✅ کد تخفیف {dc.percent}٪ اعمال شد!", reply_markup=kb)
    await msg.answer("♾️ سفارش به‌روز شد:", reply_markup=await buy_unlimited_kb(
        mbid, di, c, cfg, dc.percent, plan=row.plan, is_owner=(msg.from_user.id == row.owner_id), bot_id=row.id))


@tenant_router.callback_query(F.data.startswith("boku:"))
async def buy_unlimited_ok(cb: CallbackQuery, bot: Bot, state: FSMContext):
    _, mbid, di, c = cb.data.split(":")
    mbid, di, c = int(mbid), int(di), int(c)
    row = await get_bot_row(bot)
    if not row:
        await cb.answer()
        return
    bot_id = row.id
    cfg = await get_unlimited_cfg(bot_id)

    fsm_data = await state.get_data()
    disc_pct = fsm_data.get("discount_pct", 0)
    disc_code = fsm_data.get("discount_code", None)
    await state.clear()

    day, count = cfg["days"][di], c
    base_price = price_of_unlimited(cfg, di)
    final_price = apply_discount(base_price, disc_pct)

    async with Session() as s:
        stock = await s.scalar(select(func.count()).select_from(Config).where(
            Config.bot_id == bot_id, Config.status == "in_stock", Config.price == 0,
            Config.volume_gb == 0, Config.days == day))
        # آیا نسخهٔ «دستی» (قیمت‌دار) از همین بسته موجود است؟
        manual_stock = await s.scalar(select(func.count()).select_from(Config).where(
            Config.bot_id == bot_id, Config.status == "in_stock", Config.price > 0,
            Config.volume_gb == 0))

    if stock < count:
        is_new_request = False
        total_waiting = 0
        async with Session() as s:
            existing = await s.scalar(select(StockRequest).where(
                StockRequest.bot_id == bot_id,
                StockRequest.user_telegram_id == cb.from_user.id,
                StockRequest.volume_gb == 0, StockRequest.days == day,
                StockRequest.fulfilled == False))
            is_new_request = existing is None
            if is_new_request:
                s.add(StockRequest(bot_id=bot_id, user_telegram_id=cb.from_user.id,
                                   volume_gb=0, days=day))
                await s.commit()
                total_waiting = await s.scalar(select(func.count()).select_from(StockRequest).where(
                    StockRequest.bot_id == bot_id, StockRequest.volume_gb == 0,
                    StockRequest.days == day, StockRequest.fulfilled == False)) or 0
        await cb.answer()
        try:
            await cb.message.answer(
                "❌ این کانفیگ نامحدود در حال حاضر موجود نیست.\n"
                "به‌زودی شارژ می‌شود و به‌محض موجود شدن به شما اطلاع داده می‌شود. 🔔")
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        # اگر بستهٔ نامحدودِ ویژه (قیمت ثابت) موجود است، همان را پیشنهاد بده
        if manual_stock and manual_stock > 0:
            try:
                await _show_manual_packages(cb.message, bot_id, unlimited=True)
            except Exception:
                logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        if is_new_request:
            try:
                await bot.send_message(
                    row.owner_id,
                    f"🛎 <b>درخواست کانفیگ نامحدود ناموجود</b>\n\n"
                    f"کاربری کانفیگ نامحدود <b>{day} روزه</b> را خواست که موجود نیست.\n"
                    f"کاربر: <code>{cb.from_user.id}</code>\n"
                    f"👥 کل درخواست‌دهندگان این بسته: {total_waiting or 1} نفر\n\n"
                    "وقتی این کانفیگ را به انبار اضافه کنی، به همهٔ درخواست‌دهنده‌ها خودکار اطلاع داده می‌شود.")
            except Exception:
                logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        return

    async with Session() as s:
        # === PATCH_ORDER_DEDUPE_V1 === (نسخهٔ نامحدود — نگاه کن به همون پچ در buy_ok)
        u = await s.scalar(select(BotUser).where(
            BotUser.bot_id == bot_id, BotUser.telegram_id == cb.from_user.id
        ).with_for_update())
        if u is None:
            u = BotUser(bot_id=bot_id, telegram_id=cb.from_user.id, full_name=cb.from_user.full_name)
            s.add(u)
            await s.flush()
        _dedupe_cutoff = _dt.datetime.utcnow() - _dt.timedelta(seconds=120)
        o = await s.scalar(select(Order).where(
            Order.bot_id == bot_id, Order.user_id == u.id, Order.status == "pending",
            Order.volume_gb == 0, Order.days == day, Order.count == count,
            Order.created_at >= _dedupe_cutoff,
        ).order_by(Order.id.desc()))
        if o is None:
            o = Order(bot_id=bot_id, user_id=u.id, volume_gb=0, days=day,
                      count=count, amount=final_price, pay_method="pending",
                      status="pending", discount_code=disc_code)
            s.add(o)
            await s.flush()
        oid = o.id
        final_price = float(o.amount)
        await s.commit()
        user_bal = float(u.balance)

    if disc_code:
        async with Session() as s:
            dc = await s.scalar(select(DiscountCode).where(
                DiscountCode.bot_id == bot_id, DiscountCode.code == disc_code))
            if dc:
                dc.used_count += 1
                s.add(DiscountUsage(
                    discount_code_id=dc.id,
                    bot_id=bot_id,
                    telegram_id=cb.from_user.id,
                ))
                await s.commit()

    disc_txt = f" (تخفیف {disc_pct}٪)" if disc_pct else ""
    try:
        await cb.message.edit_text(
            f"🧾 سفارش #{await order_no(Order, oid)}\n♾️ نامحدود • {day} روز • تعداد {count}{disc_txt}\n"
            f"مبلغ: {rial(final_price)}\n\n"
            f"💰 موجودی کیف پول شما: {rial(user_bal)}\n\n"
            f"روش پرداخت را انتخاب کن:",
            reply_markup=await pay_method_kb_full(bot_id, oid),
        )
    except Exception:
        await cb.message.answer(
            f"🧾 سفارش #{await order_no(Order, oid)}\nمبلغ: {rial(final_price)}\nروش پرداخت:",
            reply_markup=await pay_method_kb_full(bot_id, oid),
        )
    await cb.answer()


@tenant_router.callback_query(F.data.startswith("bdisc:"))
async def buy_disc_start(cb: CallbackQuery, state: FSMContext, bot: Bot):
    _, mbid, vi, di, c = cb.data.split(":")
    await state.update_data(disc_mbid=int(mbid), disc_vi=int(vi), disc_di=int(di), disc_c=int(c))
    await state.set_state(BuyFSM.discount)
    await cb.answer()
    try:
        await cb.message.delete()
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.message.answer("🏷 کد تخفیف خود را وارد کنید:", reply_markup=await smart_cancel_kb(bot))


@tenant_router.message(BuyFSM.discount, F.text)
async def buy_disc_enter(msg: Message, state: FSMContext, bot: Bot):
    code = msg.text.strip()
    row = await get_bot_row(bot)
    if not row:
        await state.clear()
        return
    tg_id = msg.from_user.id
    async with Session() as s:
        dc = await s.scalar(select(DiscountCode).where(
            DiscountCode.bot_id == row.id, DiscountCode.code == code,
            DiscountCode.is_active == True))
        if dc:
            # بررسی استفاده قبلی این کاربر از همین کد
            already_used = await s.scalar(select(DiscountUsage).where(
                DiscountUsage.discount_code_id == dc.id,
                DiscountUsage.telegram_id == tg_id))
    if not dc or (dc.max_uses > 0 and dc.used_count >= dc.max_uses):
        await msg.answer("❌ کد تخفیف نامعتبر یا منقضی شده است.")
        await state.clear()
        return
    if already_used:
        await msg.answer("❌ شما قبلاً از این کد تخفیف استفاده کرده‌اید.")
        await state.clear()
        return
    data0 = await state.get_data()
    if dc.button_id is not None and dc.button_id != data0.get("disc_mbid"):
        await msg.answer("❌ این کد مخصوص یک دکمهٔ دیگر است.")
        await state.clear()
        return
    # محدودیت بخش: کدِ مخصوص پنل/پلن فقط در همان بخش VPN کار می‌کند، نه در فروشگاه
    if dc.panel_key or dc.plan_id:
        await msg.answer("❌ این کد مخصوص بخش دیگری است و در فروشگاه قابل استفاده نیست.")
        await state.clear()
        return
    if dc.expires_at is not None and dc.expires_at < _dt.datetime.utcnow():
        await msg.answer("❌ این کد منقضی شده است.")
        await state.clear()
        return
    if (dc.disc_type or "percent") != "percent" or (dc.percent or 0) <= 0:
        await msg.answer("❌ این نوع کد در این بخش پشتیبانی نمی‌شود (مخصوص بخش VPN است).")
        await state.clear()
        return
    data = await state.get_data()
    await state.clear()
    await state.update_data(discount_pct=dc.percent, discount_code=code, discount_code_id=dc.id)
    mbid = data["disc_mbid"]
    vi, di, c = data["disc_vi"], data["disc_di"], data["disc_c"]
    res = await get_btn_cfg(mbid)
    if not res:
        return
    cfg, _ = res
    kb = await main_kb_or_remove(row.id, row.owner_id, msg.from_user.id)
    await msg.answer(f"✅ کد تخفیف {dc.percent}٪ اعمال شد!", reply_markup=kb)
    await msg.answer("🛒 سفارش به‌روز شد:", reply_markup=await buy_kb(mbid, vi, di, c, cfg, dc.percent, plan=row.plan, is_owner=(msg.from_user.id == row.owner_id), bot_id=row.id))


@tenant_router.callback_query(F.data.startswith("bok:"))
async def buy_ok(cb: CallbackQuery, bot: Bot, state: FSMContext):
    _, mbid, vi, di, c = cb.data.split(":")
    mbid, vi, di, c = int(mbid), int(vi), int(di), int(c)
    res = await get_btn_cfg(mbid)
    if not res:
        await cb.answer()
        return
    cfg, bot_id = res
    row = await get_bot_row(bot)
    if not row:
        await cb.answer()
        return
    # خواندن تخفیف از state
    fsm_data = await state.get_data()
    disc_pct = fsm_data.get("discount_pct", 0)
    disc_code = fsm_data.get("discount_code", None)
    await state.clear()

    vol, day, count = cfg["vols"][vi], cfg["days"][di], c
    base_price = price_of(cfg, vi, di, count)
    final_price = apply_discount(base_price, disc_pct)

    # بررسی موجودی انبار
    async with Session() as s:
        stock = await s.scalar(select(func.count()).select_from(Config).where(
            Config.bot_id == bot_id, Config.status == "in_stock", Config.price == 0,
            Config.volume_gb == vol, Config.days == day))

    if stock < count:
        # ثبت در لیست انتظار (بدون تکرار) + اطلاع به ادمین ربات
        is_new_request = False
        total_waiting = 0
        async with Session() as s:
            existing = await s.scalar(select(StockRequest).where(
                StockRequest.bot_id == bot_id,
                StockRequest.user_telegram_id == cb.from_user.id,
                StockRequest.volume_gb == vol, StockRequest.days == day,
                StockRequest.fulfilled == False))
            is_new_request = existing is None
            if is_new_request:
                s.add(StockRequest(bot_id=bot_id, user_telegram_id=cb.from_user.id,
                                   volume_gb=vol, days=day))
                await s.commit()
                # شمارش کل درخواست‌دهندگان این بسته برای نمایش به ادمین
                total_waiting = await s.scalar(select(func.count()).select_from(StockRequest).where(
                    StockRequest.bot_id == bot_id, StockRequest.volume_gb == vol,
                    StockRequest.days == day, StockRequest.fulfilled == False)) or 0
        await cb.answer()
        try:
            await cb.message.answer(
                "❌ این کانفیگ در حال حاضر موجود نیست.\n"
                "به‌زودی شارژ می‌شود و به‌محض موجود شدن به شما اطلاع داده می‌شود. 🔔")
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        # اطلاع به مالک ربات — فقط اگر درخواست جدید بود (تکراری نبود)
        if is_new_request:
            try:
                await bot.send_message(
                    row.owner_id,
                    f"🛎 <b>درخواست بستهٔ ناموجود</b>\n\n"
                    f"کاربری بستهٔ <b>{vol} گیگ / {day} روز</b> را خواست که موجود نیست.\n"
                    f"کاربر: <code>{cb.from_user.id}</code>\n"
                    f"👥 کل درخواست‌دهندگان این بسته: {total_waiting or 1} نفر\n\n"
                    "وقتی این حجم/مدت را به انبار اضافه کنی، به همهٔ درخواست‌دهنده‌ها خودکار اطلاع داده می‌شود.")
            except Exception:
                logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        return

    async with Session() as s:
        # === PATCH_ORDER_DEDUPE_V1 ===
        # قفلِ ردیفِ کاربر تا پایانِ این تراکنش. دکمهٔ «✅ ثبت سفارش» با تاپ‌های
        # پشتِ‌سرهم (قبل از اینکه پیام ویرایش/ادیت بشه) قبلاً هر بار یک Order
        # کاملاً جدید می‌ساخت — چون هیچ چکِ تکراری‌ای وجود نداشت. نتیجه: چند تا
        # پیامِ سفارشِ جداگانه (هرکدام با دکمهٔ «پرداخت از کیف پول» مستقل) توی
        # چت باقی می‌موند و کاربر با زدنِ هرکدوم، یک خریدِ کاملاً معتبر و جداگانه
        # (به قیمتِ همون یک بسته) انجام می‌داد. الان قبل از ساختِ سفارشِ جدید،
        # زیرِ قفلِ ردیفِ کاربر چک می‌کنیم که آیا همین کاربر همین الان (چند
        # ثانیهٔ اخیر) یک سفارشِ pending با همین حجم/روز/تعداد داره؛ اگه داره
        # همون رو دوباره نشون می‌دیم، سفارشِ تکراری نمی‌سازیم.
        u = await s.scalar(select(BotUser).where(
            BotUser.bot_id == bot_id, BotUser.telegram_id == cb.from_user.id
        ).with_for_update())
        if u is None:
            u = BotUser(bot_id=bot_id, telegram_id=cb.from_user.id, full_name=cb.from_user.full_name)
            s.add(u)
            await s.flush()
        _dedupe_cutoff = _dt.datetime.utcnow() - _dt.timedelta(seconds=120)
        o = await s.scalar(select(Order).where(
            Order.bot_id == bot_id, Order.user_id == u.id, Order.status == "pending",
            Order.volume_gb == vol, Order.days == day, Order.count == count,
            Order.created_at >= _dedupe_cutoff,
        ).order_by(Order.id.desc()))
        if o is None:
            o = Order(bot_id=bot_id, user_id=u.id, volume_gb=vol, days=day,
                      count=count, amount=final_price, pay_method="pending",
                      status="pending", discount_code=disc_code)
            s.add(o)
            await s.flush()
        oid = o.id
        final_price = float(o.amount)
        await s.commit()
        user_bal = float(u.balance)

    # به‌روزرسانی تعداد استفاده از کد تخفیف + ثبت استفاده کاربر
    if disc_code:
        async with Session() as s:
            dc = await s.scalar(select(DiscountCode).where(
                DiscountCode.bot_id == bot_id, DiscountCode.code == disc_code))
            if dc:
                dc.used_count += 1
                # ثبت اینکه این کاربر از این کد استفاده کرد
                s.add(DiscountUsage(
                    discount_code_id=dc.id,
                    bot_id=bot_id,
                    telegram_id=cb.from_user.id,
                ))
                await s.commit()

    disc_txt = f" (تخفیف {disc_pct}٪)" if disc_pct else ""
    try:
        await cb.message.edit_text(
            f"🧾 سفارش #{await order_no(Order, oid)}\n{fmt_vol(vol)} • {day} روز • تعداد {count}{disc_txt}\n"
            f"مبلغ: {rial(final_price)}\n\n"
            f"💰 موجودی کیف پول شما: {rial(user_bal)}\n\n"
            f"روش پرداخت را انتخاب کن:",
            reply_markup=await pay_method_kb_full(bot_id, oid),
        )
    except Exception:
        await cb.message.answer(
            f"🧾 سفارش #{await order_no(Order, oid)}\nمبلغ: {rial(final_price)}\nروش پرداخت:",
            reply_markup=await pay_method_kb_full(bot_id, oid),
        )
    await cb.answer()


@tenant_router.callback_query(F.data.startswith("pay:"))
async def pay_method(cb: CallbackQuery, bot: Bot, state: FSMContext):
    parts = cb.data.split(":")
    method = parts[1]
    oid = int(parts[2])
    row = await get_bot_row(bot)
    if not row:
        await cb.answer()
        return
    bot_id = row.id

    async def _own_order(s, order) -> bool:
        """=== PATCH_PAY_ORDER_OWNERSHIP_V1 ===
        قبلاً هیچ‌کدام از مسیرهایِ pay: مالکیتِ سفارش را چک نمی‌کردند: هر
        کاربری با callbackِ دست‌ساز می‌توانست سفارشِ هر کس (حتی رباتِ دیگر) را
        لغو کند یا با کیف‌پولِ صاحبش پرداخت کند."""
        if not order or order.bot_id != bot_id:
            return False
        owner = await s.get(BotUser, order.user_id)
        return bool(owner and owner.telegram_id == cb.from_user.id)

    if method == "cancel":
        async with Session() as s:
            o = await s.get(Order, oid)
            if o is not None and await _is_foreign(o, bot):   # PATCH_TENANT_SCOPE_V1
                o = None
            if not await _own_order(s, o):
                await cb.answer("یافت نشد.", show_alert=True)
                return
            # فقط سفارشِ هنوز-پرداخت‌نشده؛ سفارشِ در انتظارِ تأییدِ ادمین/پرداخت‌شده دست نمی‌خورد
            if o.status in ("pending", "awaiting_receipt"):
                o.status = "rejected"
                await s.commit()
        try:
            await cb.message.edit_text("❌ سفارش لغو شد.",
                                        reply_markup=await inline_back_kb(bot_id))
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        await cb.answer("لغو شد")
        return

    async with Session() as s:
        o = await s.get(Order, oid)
        if o is not None and await _is_foreign(o, bot):   # PATCH_TENANT_SCOPE_V1
            o = None
        if o is not None and not await _own_order(s, o):
            o = None
        if not o or o.status != "pending":
            # سفارش منقضی/لغو/پرداخت‌شده — پیامِ واضح به‌جای «یافت نشد»
            _st = o.status if o else None
            if _st == "awaiting_receipt":
                msg_txt = ("این سفارش در انتظارِ رسید است. اگر رسید فرستادی صبر کن، "
                           "وگرنه یک خریدِ جدید شروع کن.")
            elif _st in ("paid",):
                msg_txt = "این سفارش قبلاً پرداخت شده است. ✅"
            elif _st in ("rejected", None):
                msg_txt = ("⏳ این سفارش منقضی یا لغو شده. لطفاً از منوی اصلی یک "
                           "خریدِ جدید شروع کن.")
            else:
                msg_txt = "این سفارش دیگر معتبر نیست. لطفاً خریدِ جدیدی شروع کن."
            await cb.answer(msg_txt, show_alert=True)
            return
        u = await s.get(BotUser, o.user_id)
        amount    = float(o.amount)
        volume_gb = o.volume_gb
        days      = o.days
        count     = o.count

    if method == "wallet":
        # === PATCH_PAY_WALLET_INSTANT_BUTTON_CLEAR_V1 ===
        # دکمه‌های صفحهٔ پرداخت رو همین اول پاک می‌کنیم تا کاربر فیزیکاً نتونه
        # دوباره روی همین پیام تپ کنه. قفلِ سفارش (پایین‌تر) از نظرِ دیتابیس
        # قبلاً امن بود؛ این فقط یک لایهٔ محافظتیِ اضافه در سطحِ UI هست.
        try:
            await cb.message.edit_reply_markup(reply_markup=None)
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (پاک‌کردنِ فوریِ دکمه‌ها ناموفق بود)")
        if float(u.balance) < amount:
            await cb.answer(
                f"موجودی کافی نیست.\nلازم: {rial(amount)} — موجودی: {rial(u.balance)}",
                show_alert=True)
            return
        # ── همهٔ چک‌ها و کسر در یک تراکنش انجام می‌شوند تا دابل‌کلیک باعث
        #    کسرِ دوباره یا تخصیص دوبارهٔ کانفیگ نشود (جلوگیری از double-spend) ──
        # cb.answer زودتر زده می‌شود تا callback timeout نشود (Telegram ۱۰ ثانیه فرصت می‌دهد)
        await cb.answer()
        assigned = []
        sd_queued_id = None      # PATCH_STOCK_MANUAL_DELIVERY_V1
        err = None
        async with Session() as s:
            # === PATCH_WALLET_ORDER_ROW_LOCK_V2 ===
            # قفلِ خودِ سفارش (FOR UPDATE) قبل از هر چیز، تا اگه دابل‌کلیک
            # چند ریکوئستِ هم‌زمان برای همون oid بفرسته، همه‌شون پشتِ سرِ هم
            # صف بشن روی همین ردیف. قبلاً وضعیتِ سفارش را قبل از قفل‌شدن
            # می‌خوندیم (بدون with_for_update)، پس درخواستِ دوم یک نسخهٔ کهنه
            # از سفارش (status="pending") را در حافظه نگه می‌داشت و حتی بعد از
            # صف‌کشیدن پشتِ قفلِ کاربر، دوباره چکِ وضعیت انجام نمی‌شد؛ نتیجه‌اش
            # کسرِ چندبارهٔ موجودی و تخصیصِ چندبارهٔ کانفیگ برای یک سفارش بود.
            # حالا با گرفتنِ قفل روی خودِ سفارش، درخواستِ دوم وقتی نوبتش میشه
            # آخرین وضعیتِ commit‌شده (paid) را می‌بیند و متوقف می‌شود.
            o = await s.get(Order, oid, with_for_update=True)
            if o is not None and await _is_foreign(o, bot):   # PATCH_TENANT_SCOPE_V1
                o = None
            # چکِ مجددِ وضعیت: اگر همین سفارش هم‌زمان پرداخت شده باشد، خارج شو
            if not o or o.status != "pending":
                err = "این سفارش قبلاً پردازش شده است."
            else:
                # === PATCH_WALLET_ROW_LOCK_V1 ===
                # قفلِ ردیفِ کاربر تا پایانِ تراکنش، تا اگه دو ریکوئستِ خرید
                # هم‌زمان بیان (مثلاً دابل‌کلیک)، دومی منتظرِ اولی بمونه و
                # موجودیِ کهنه نبینه — جلوگیری از race condition/double-spend.
                u = await s.get(BotUser, o.user_id, with_for_update=True)
                if not u or float(u.balance) < amount:
                    err = "موجودی کافی نیست."
                else:
                    # تخصیص کانفیگ — باید به‌اندازهٔ تعداد سفارش موجود باشد
                    cfgs = (await s.scalars(
                        select(Config).where(
                            Config.bot_id == bot_id, Config.status == "in_stock", Config.price == 0,
                            Config.volume_gb == o.volume_gb, Config.days == o.days
                        ).with_for_update().limit(o.count)
                    )).all()
                    if len(cfgs) < o.count:
                        err = ("موجودی کانفیگ کافی نیست؛ پرداخت انجام نشد. "
                               "لطفاً بعداً دوباره تلاش کن یا به پشتیبانی پیام بده.")
                    else:
                        u.balance = float(u.balance) - amount
                        o.status = "paid"
                        o.pay_method = "wallet"
                        s.add(WalletTxn(bot_id=bot_id, user_id=u.id, amount=-amount,
                                        kind="purchase", note=f"خرید سفارش #{await order_no(Order, oid)}"))
                        # === PATCH_STOCK_MANUAL_DELIVERY_V1 === تحویل دستی: انبار دست نمی‌خورد، سفارش می‌رود در صفِ تحویل
                        from tenant.bots.vpn import stock_delivery as _sd
                        if await _sd.is_on(bot_id):
                            _sd_obj = _sd.queue(s, bot_id=bot_id, user_id=u.id, order_id=o.id, volume_gb=o.volume_gb,
                                                days=o.days, count=o.count, amount=amount, label=o.custom_label)
                            await s.flush()
                            sd_queued_id = _sd_obj.id
                        else:
                            for cfg in cfgs[:o.count]:
                                cfg.status = "sold"
                                cfg.owner_user_id = u.id
                                assigned.append(cfg)
                        await s.commit()
                        # PATCH_DEBUG_USER_CONFIG_REPORT — لاگِ موقتِ تشخیصی، نقطه‌ی مقابلِ
                        # لاگِ admin_user_receipts؛ بعد از پیداشدنِ ریشهٔ باگ حذف کن.
                        print(
                            f"[DEBUG_USER_CFG_REPORT] خریدِ کیف‌پولی ثبت شد: bot_id={bot_id} "
                            f"u.id={u.id} u.telegram_id={u.telegram_id} oid={oid} amount={amount} -> "
                            f"cfgs تخصیص‌یافته: " +
                            ", ".join(f"[id={c.id} owner_user_id={c.owner_user_id} status={c.status!r} "
                                      f"bot_id={c.bot_id}]" for c in assigned)
                        )
                        from tenant.shared.extras import handle_referral_purchase
                        await handle_referral_purchase(bot_id, cb.from_user.id, bot, amount=amount)
        if err:
            try:
                await cb.message.edit_text(f"❌ {err}")
            except Exception:
                await cb.message.answer(f"❌ {err}")
            return
        try:
            await cb.message.edit_text("✅ پرداخت موفق! سفارشت در صفِ تحویل قرار می‌گیرد..." if sd_queued_id
                                       else "✅ پرداخت موفق! کانفیگ‌ها ارسال می‌شوند...")
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        if sd_queued_id:
            from tenant.bots.vpn import stock_delivery as _sd2
            await _sd2.announce(bot, sd_queued_id)
        for cfg in assigned:
            try:
                await send_config_to_user(bot, cb.from_user.id, cfg)
            except Exception:
                # === PATCH_CONFIG_DELIVERY_RESILIENCE_V1 ===
                # اگه ارسال (با هر دو تلاشِ داخلِ send_config_to_user) شکست
                # بخوره، دیگه نباید کلِ هندلر کرش کنه — سفارش از قبل paid
                # شده و کانفیگ assign شده. حداقل یه پیامِ راهنما بفرست و
                # ادامه بده تا اعلانِ ادمین و بقیهٔ کانفیگ‌ها (تو خریدِ
                # چندتایی) هم اجرا بشن.
                logger.exception(
                    f"ارسالِ کانفیگ به کاربر ناموفق بود — cfg_id={cfg.id} "
                    f"tg_id={cb.from_user.id}؛ کانفیگ در «سرویس‌های من» موجود است.")
                try:
                    await bot.send_message(
                        cb.from_user.id,
                        "✅ پرداختت با موفقیت انجام شد، ولی در ارسالِ خودکارِ "
                        "کانفیگ مشکلی پیش اومد. از «📡 سرویس‌های من» می‌تونی "
                        "کانفیگت رو ببینی و دوباره ارسال کنی.",
                    )
                except Exception:
                    logger.debug("پیامِ راهنمای جایگزین هم ارسال نشد (بی‌اهمیت)")
        # اطلاع خودکار خرید به ادمین‌ها (در صورت روشن‌بودن) — قبلاً این شاخه
        # (خرید از انبار با موجودیِ کیف‌پول) برخلافِ مسیرهای مشابه، این اعلان
        # را نمی‌فرستاد.
        if assigned or sd_queued_id:
            try:
                await _purchase_alert(
                    bot, row, buyer=u,
                    section="فروشگاه / انبار",
                    detail=f"{fmt_vol(volume_gb)} · {fmt_days(days)}" + (f" × {count} عدد" if count and count > 1 else ""),   # PATCH_TRUST_DETAIL_DEDUP_V2
                    amount=amount, order_id=oid, count=count)
            except Exception:
                logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")

    elif method == "card":
        from tenant.gateways.card_purchase import handle_card_payment_method
        await handle_card_payment_method(cb, state, bot, bot_id, oid, amount, volume_gb, days, count)


# PATCH_MCFG_NAME_NOTE_PAY_V1
class _ManualCfgNameFSM(StatesGroup):
    naming = State()   # پرسیدن اسم دلخواه قبل از پیش‌فاکتورِ انبار دستی


class _ManualCfgNoteFSM(StatesGroup):
    invoice = State()   # ویرایش یادداشت پیش‌فاکتور انبار دستی
    delivery = State()  # ویرایش یادداشت تحویل انبار دستی


# PATCH_MCFG_DISCOUNT_V1
