async def _show_manual_preinvoice(target_msg: Message, bot: Bot, from_user, state: FSMContext):
    """پیش‌فاکتورِ انبار دستی: اطلاعات خریدار + یادداشت ادمین + کد تخفیف + دو روش پرداخت."""
    data = await state.get_data()
    vol, days, users, price = data.get("mcfg_vol"), data.get("mcfg_days"), data.get("mcfg_users"), data.get("mcfg_price")
    category = data.get("mcfg_category")
    label = data.get("mcfg_custom_label")
    disc_code = data.get("mcfg_disc_code")
    disc_amount = int(data.get("mcfg_disc_amount") or 0)
    row = await get_bot_row(bot)
    if not row or vol is None:
        return
    async with Session() as s:
        u = await s.scalar(select(BotUser).where(
            BotUser.bot_id == row.id, BotUser.telegram_id == from_user.id))
        bal = float(u.balance) if u else 0
        q = select(func.count()).select_from(Config).where(
            Config.bot_id == row.id, Config.status == "in_stock", Config.price == price,
            Config.volume_gb == vol, Config.days == days,
            Config.user_count == users)
        if category:
            q = q.where(Config.category.in_(category.split(",")))
        stock = await s.scalar(q)
    if stock < 1:
        await target_msg.answer("این بسته دیگر موجود نیست.")
        return
    final_price = max(0, price - disc_amount) if disc_code else price
    vol_lbl = "♾️ نامحدود" if vol == 0 else f"{vol} گیگ"
    users_lbl = f"\n👥 کاربر: {users}" if users else ""
    label_line = f"\n✏️ نام دلخواه: <b>{label}</b>" if label else ""
    disc_line = f"\n🏷 کد {disc_code}: −{rial(disc_amount)} تومان" if disc_code else ""
    # === PATCH_MCFG_NOTE_CATMAP_V1 ===
    note = await get_mcfg_note_cat(row.id, "invoice", "unlimited" if (vol or 0) == 0 else "manual", category)
    note_line = f"📝 {note}\n" if note else ""
    buyer_name = from_user.full_name or "—"
    buyer_uname = from_user.username
    buyer_line = f"👤 خریدار: {buyer_name}" + (f" (@{buyer_uname})" if buyer_uname else "")
    buyer_line += f"\n🆔 شناسه: <code>{from_user.id}</code>"
    price_line = (f"💰 قیمت: <b>{rial(price)}</b>" if not disc_code
                  else f"💰 قیمت: <s>{rial(price)}</s> ← <b>{rial(final_price)}</b>")
    enough = "" if bal >= final_price else "\n⚠️ موجودی کیف پول کافی نیست؛ اول شارژ کن."
    text = (
        "🧾 <b>پیش فاکتور</b>\n"
        "┈┅━━⊷⊰✨⊱⊶━━┅┈\n"
        f"{buyer_line}\n"
        "┈┅━━⊷⊰✨⊱⊶━━┅┈\n"
        f"📦 سرویس: <b>{vol_lbl}</b>\n"
        f"📅 مدت: <b>{fmt_days(days)}</b>{users_lbl}{label_line}\n"
        f"{price_line}{disc_line}\n"
        f"{note_line}"
        f"💳 موجودی کیف پول: {rial(bal)}{enough}"
    )
    # === PATCH_WALLET_PAY_TOGGLE_V1 ===
    kb_rows = ([
        [InlineKeyboardButton(text="✅ پرداخت از کیف پول",
                              callback_data=f"mcfg:pay:{vol}:{days}:{users}:{price}", style=ButtonStyle.SUCCESS)],
    ] if await wallet_pay_on(row.id) else [])
    card_purchase_ok = (
        await get_setting(row.id, "card_enabled", "1") == "1"
        and await get_setting(row.id, "card_purchase_enabled", "1") == "1"
    )
    if card_purchase_ok:
        kb_rows.append([InlineKeyboardButton(text="💳 پرداخت کارت‌به‌کارت",
                              callback_data=f"mcfg:paycard:{vol}:{days}:{users}:{price}", style=ButtonStyle.PRIMARY)])
    # === PATCH_MCFG_TOPUP_ROWS_V1 ===
    # گزارشِ ادمین: «آبان گیت‌وی موقعِ پرداختِ محصول نشون داده نمی‌شه».
    # علت: این صفحه (پیش‌فاکتورِ حجم/مدتِ دلخواه) برخلافِ صفحهٔ خریدِ پلن،
    # هیچ‌وقت روش‌هایِ شارژ را اضافه نمی‌کرد — فقط کیف‌پول و کارت‌به‌کارت
    # داشت. پس کاربری که موجودی‌اش کم بود جملهٔ «اول شارژ کن» را می‌دید
    # بدونِ اینکه هیچ راهی جلویش باشد. همان منطقِ صفحهٔ پلن
    # (PATCH_WALLET_TOPUP_ROWS_V1) این‌جا هم اعمال شد.
    if bal < final_price:
        kb_rows.extend(await wallet_topup_rows(row.id, skip_card=card_purchase_ok))
    else:
        # === PATCH_ABAN_ALWAYS_SHOW_PURCHASE_V1 === با موجودیِ کافی هم آبان‌گیت (تیکِ نمایش در خرید)
        kb_rows.extend([r for r in await wallet_topup_rows(row.id, skip_card=True)
                        if any((b.callback_data or "").startswith("w:abangateway") for b in r)])
    if not _has_wallet_charge_btn(kb_rows):
        kb_rows.extend(await wallet_charge_btn_rows(row.id))   # PATCH_WALLET_CHARGE_BTN_V1
    # === PATCH_VPN_DISCOUNT_TOGGLE_V1 ===
    # این دقیقاً همون صفحه‌ایه که تو اسکرین‌شاتِ ادمین دیده شد — تنظیمِ
    # «استفاده از کد تخفیف در خرید» اینجا هیچ‌وقت چک نمی‌شد (برخلافِ
    # فروشگاه که درست چک می‌کرد)، پس این دکمه همیشه نشون داده می‌شد.
    if await get_setting(row.id, "discount_purchase_enabled", "1") == "1":
        if disc_code:
            kb_rows.append([InlineKeyboardButton(text="🗑 حذف کد تخفیف", callback_data="mcfg:disc:remove", style=ButtonStyle.DANGER)])
        else:
            kb_rows.append([InlineKeyboardButton(text="🏷 اعمال کد تخفیف", callback_data="mcfg:disc:start", style=ButtonStyle.PRIMARY)])
    kb_rows.append([InlineKeyboardButton(text="❌ لغو و بازگشت به منو", callback_data="buy:cancel")])
    await target_msg.answer(text, reply_markup=InlineKeyboardMarkup(inline_keyboard=kb_rows))


@tenant_router.callback_query(F.data == "mcfg:disc:start")
async def mcfg_disc_start(cb: CallbackQuery, bot: Bot, state: FSMContext):
    data = await state.get_data()
