    oid = int(cb.data.split(":")[1])
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="⚠️ بله؛ شارژ لغو و از کیف‌پول کسر شود",
                              callback_data=f"chadm_revoke_ok:{oid}", style=ButtonStyle.DANGER)],
        [InlineKeyboardButton(text="↩️ انصراف", callback_data=f"chadm_revoke_no:{oid}", style=ButtonStyle.SUCCESS)],
    ])
