@tenant_router.callback_query(F.data.startswith("chadm_revoke_ok:"))
async def chadm_revoke(cb: CallbackQuery, bot: Bot):
    """لغوِ یک شارژِ کیف‌پول که پیش‌تر به‌صورت خودکار تایید شده بود
    (مثلاً چون بعداً معلوم شد رسید فیک بوده). مبلغ از کیف‌پول کاربر
    کسر می‌شود."""
    row = await get_bot_row(bot)
    if not row:
        await cb.answer()
        return
    if not await is_owner_or_admin(row.id, cb.from_user.id, row.owner_id):
        await cb.answer()
        return
    oid = int(cb.data.split(":")[1])
    async with Session() as s:
        o = await s.get(Order, oid, with_for_update=True)
        if not o or o.bot_id != row.id or o.status != "paid" or o.pay_method != "card_charge":
            await cb.answer("این سفارش قابلِ لغو نیست (شاید قبلاً لغو شده).", show_alert=True)
            return
        u = await s.get(BotUser, o.user_id)
        amount = float(o.amount)
        # === PATCH_REVOKE_DEBT_V1 ===
        # باگ (ایلیا): «رسید رو فیک زدم ولی حسابش بازم شارژ شده بود». کاربر شارژِ خودکار را همان لحظه خرج
        # کرده بود، و کدِ قبلی موجودی را با max(0, …) روی صفر نگه می‌داشت؛ یعنی لغو بی‌صدا هیچ مبلغی کم
        # نمی‌کرد درحالی‌که سرویس‌هایِ خریده‌شده سرِ جایشان بود. حالا کسر کامل انجام می‌شود (موجودی می‌تواند
        # منفی شود = بدهیِ کاربر؛ تا شارژِ جبرانی نتواند خرید کند) و به ادمین گفته می‌شود چه چیزی خرج شده.
        bal_before = float(u.balance or 0)
        u.balance = bal_before - amount
        shortage = max(0.0, amount - max(0.0, bal_before))
        spent_rows = []
        try:
            spent_rows = (await s.execute(select(WalletTxn.amount, WalletTxn.note).where(
                WalletTxn.bot_id == row.id, WalletTxn.user_id == u.id,
                WalletTxn.amount < 0, WalletTxn.kind != "revert",
                WalletTxn.created_at >= o.created_at).order_by(WalletTxn.id.desc()).limit(6))).all()
        except Exception:
            logger.exception("[revoke] خوانِ خرج‌هایِ بعد از شارژ ناموفق")
        s.add(WalletTxn(bot_id=row.id, user_id=u.id, amount=-amount,
                        kind="revert", note=f"لغوِ تاییدِ خودکار (رسید فیک) — سفارش #{await order_no(Order, oid)}"))
        o.status = "fake_reverted"
        new_bal = float(u.balance)
        await s.commit()
        tg_id = u.telegram_id
    admin_name = f"@{cb.from_user.username}" if cb.from_user.username else cb.from_user.full_name
    try:
        original = cb.message.caption or cb.message.text or ""
        done_text = original + f"\n\n🚫 <b>لغو شد (رسید فیک) توسط</b> {admin_name}"
        if shortage > 0:
            done_text += (f"\n⚠️ <b>کاربر {rial(shortage)} از این شارژ را قبلاً خرج کرده بود</b>؛ "
                          f"موجودی الان <b>{rial(new_bal)}</b> است (منفی = بدهیِ کاربر).")
            for _a, _n in spent_rows:
                done_text += f"\n  • {rial(abs(float(_a)))} — {_html.escape(str(_n or ''))[:60]}"
            done_text += "\nسرویس‌هایِ خریده‌شده خودکار حذف نمی‌شوند؛ اگر لازم است دستی غیرفعال کن یا کاربر را مسدود کن."
        if cb.message.caption is not None:
            await cb.message.edit_caption(caption=done_text, reply_markup=None)
        else:
            await cb.message.edit_text(done_text, reply_markup=None)
    except Exception:
        try:
            await cb.message.edit_reply_markup(reply_markup=None)
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.answer(("لغو شد 🚫 — کاربر قبلاً خرج کرده؛ موجودی منفی شد." if shortage > 0 else "لغو شد 🚫"),
                    show_alert=(shortage > 0))
    try:
        _debt = (f"\n⚠️ موجودیِ کیف‌پولت الان {rial(new_bal)} است؛ برایِ ادامهٔ خرید باید شارژ کنی."
                 if new_bal < 0 else "")
        await bot.send_message(
            tg_id,
            f"⚠️ شارژِ کیف‌پولِ شما بابتِ سفارشِ #{await order_no(Order, oid)} به مبلغِ {rial(amount)} به دلیلِ نامعتبر بودنِ "
            f"رسید، لغو شد و از کیف‌پولتان کسر گردید.{_debt}\nدر صورتِ اعتراض با پشتیبانی تماس بگیرید.",
            reply_markup=await inline_back_kb(row.id))
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")


