# ─────────────────────── پنل مدیریت ───────────────────────

async def tadmin_kb(bot_id: int = 0, bot_field: str | None = None, plan: str | None = None,
                   is_beta: bool = False) -> InlineKeyboardMarkup | ReplyKeyboardMarkup:
    _ibs = ibtn_style
    # === PATCH_TADMIN_KB_AUTOFIELD_V1 ===
    if bot_field is None or plan is None:
        async with Session() as _s:
            _row = await _s.get(BotRow, bot_id)
        if _row:
            bot_field = bot_field if bot_field is not None else _row.field
            plan = plan if plan is not None else _row.plan
        else:
            bot_field = bot_field or "vpn_sales"
            plan = plan or "free"
    # === PATCH_PARTNER_V7 ===
    if plan == "partner":
        from tenant.partner_bot.partner_menu import partner_home_kb
        return await partner_home_kb(bot_id)
    def ok(f) -> bool:
        return has_feature(plan, f)
    _main_styles = {
        "products": ButtonStyle.PRIMARY,
        "finance": ButtonStyle.SUCCESS,
        "stats": ButtonStyle.SUCCESS,
        "admins": ButtonStyle.PRIMARY,
        "settings": ButtonStyle.PRIMARY,
        "home": ButtonStyle.DANGER,
    }
    from tenant.settings_registry import visible_items as _rv_home, section_key as _sk_home
    _home_extra = _rv_home(_sk_home("home", bot_field), plan)
    if await get_setting(bot_id, "menu_mode", "reply") != "inline":
        # === PATCH_SETTINGS_REGISTRY_V6_HOME_HUB ===
        # دکمه‌هایِ اختصاصیِ هر نوعِ ربات در خانهٔ پنل (مثلاً «راهنما و دستیار» فقط برایِ
        # خدماتِ مجازی) از tenant/bots/<kind>/settings.py می‌آیند (بخشِ "home").
        rows = [[KeyboardButton(text=_it.label)] for _it in _home_extra]
        rows += [
            [KeyboardButton(text="📦 سرویس‌ها و محصولات", style=_main_styles["products"])],
            [KeyboardButton(text="🎛 دکمه‌ها و تنظیمات", style=_main_styles["settings"])],
            [KeyboardButton(text="👮 ادمین‌ها و پشتیبانی", style=_main_styles["admins"])],
            [
                KeyboardButton(text="💰 مالی و کیف پول", style=_main_styles["finance"]),
                KeyboardButton(text="📊 آمار و گزارشات", style=_main_styles["stats"]),
            ],
            [KeyboardButton(text="🏠 بازگشت به خانه", style=_main_styles["home"])],
        ]
        return ReplyKeyboardMarkup(keyboard=rows, resize_keyboard=True)
    rows = [[InlineKeyboardButton(
                text=_it.label, callback_data=_it.callback,
                style=(getattr(ButtonStyle, _it.style.upper()) if _it.style else None))]
            for _it in _home_extra]
    rows += [
        [InlineKeyboardButton(text="📦 سرویس‌ها و محصولات", callback_data="tadm:sec:products",
                              style=await _ibs(bot_id, "ibtn:adm_sec_products"))],
        [InlineKeyboardButton(text="🎛 دکمه‌ها و تنظیمات", callback_data="tadm:sec:settings",
                              style=await _ibs(bot_id, "ibtn:adm_sec_settings"))],
        [InlineKeyboardButton(text="👮 ادمین‌ها و پشتیبانی", callback_data="tadm:sec:admins",
                              style=await _ibs(bot_id, "ibtn:adm_sec_admins"))],
        [
            InlineKeyboardButton(text="💰 مالی و کیف پول", callback_data="tadm:sec:finance",
                                 style=await _ibs(bot_id, "ibtn:adm_sec_finance")),
            InlineKeyboardButton(text="📊 آمار و گزارشات", callback_data="tadm:sec:stats",
                                 style=await _ibs(bot_id, "ibtn:adm_sec_stats2")),
        ],
        [InlineKeyboardButton(text="🏠 بازگشت به خانه", callback_data="tadm:home",
                              style=await _ibs(bot_id, "ibtn:adm_home"))],
    ]
    return InlineKeyboardMarkup(inline_keyboard=rows)


# === PATCH_PARTNER_ADMINKB_FIX_V1 ===
# باگ: PATCH_PARTNER_CAPTION_FIX_V1 فقط متنِ پیام را برایِ رباتِ همکار
# درست کرده بود (partner_home_text)، ولی کیبوردِ همراهش هنوز همه‌جا
# مستقیم tadmin_kb(...) صدا زده می‌شد — یعنی همانِ پنلِ عمومیِ ربات‌هایِ
# مستأجر (سرویس‌ها و محصولات / مالی و کیف پول / آمار و گزارشات / ...)
# به‌جایِ پنلِ شیشه‌ایِ مخصوصِ همکار نمایش داده می‌شد. این تابع کیبوردِ
# درست را بر اساسِ نوعِ ربات برمی‌گرداند و باید به‌جایِ فراخوانیِ مستقیمِ
# tadmin_kb در تمامِ نقاطی که پنلِ مدیریت را باز می‌کنند استفاده شود.
# === PATCH_PAYGUIDE_MOVE_FINANCE_PRO_V1_HELPER ===
async def get_bot_row_by_id(bot_id: int):
    """مشابهِ get_bot_row ولی از رویِ bot_id، برایِ جاهایی که فقط
    شناسهٔ رباتِ دیتابیس را دارند نه آبجکتِ aiogram.Bot."""
    async with Session() as _s:
        return await _s.get(BotRow, bot_id)


async def _admin_panel_kb(row):
    if row.plan == "partner":
        from tenant.partner_bot.partner_menu import partner_home_kb
        return await partner_home_kb(row.id)
    return await tadmin_kb(row.id, row.field, row.plan, True)


def _products_help_text(bot_field: str) -> str:
    """راهنمای کوتاه و اختصاصیِ اتصال محصول به دکمهٔ صفحهٔ اصلی."""
    if bot_field == "vpn_sales":
        return (
            "📘 <b>راهنمای فروش VPN و اتصال به دکمه</b>\n\n"
            "برای فروش VPN، ابتدا از مسیر زیر وارد بخش مدیریت شوید:\n"
            "<code>پنل مدیریت ← سرویس‌ها و محصولات</code>\n\n"
            "در این بخش یکی از دو روش را انتخاب کنید:\n"
            "• <b>کانفیگ آماده:</b> کانفیگی را که از قبل آماده کرده‌اید به‌عنوان محصول ثبت کنید تا بعد از خرید برای کاربر ارسال شود.\n"
            "• <b>کانفیگ خودکار:</b> مشخصات پلن، حجم، مدت، قیمت و اطلاعات فنی را وارد کنید تا کانفیگ بعد از خرید به‌صورت خودکار ساخته و تحویل شود.\n\n"
            "بعد از ساخت محصول، حتماً آن را ذخیره و فعال کنید. سپس برای ساخت دکمهٔ فروش وارد مسیر زیر شوید:\n"
            "<code>پنل مدیریت ← دکمه‌ها و تنظیمات ← تنظیم و مدیریت دکمه‌های صفحهٔ اصلی</code>\n\n"
            "روی <b>افزودن دکمه</b> بزنید، عنوان واضحی مثل «🌐 خرید VPN» یا «🎁 تست رایگان VPN» بنویسید و در بخش عملکرد، گزینهٔ مربوط به فروش VPN یا تست رایگان را انتخاب کنید. سپس محصول یا پلن موردنظر را انتخاب و ذخیره کنید.\n\n"
            "اگر چند پلن دارید، برای هرکدام دکمهٔ جدا بسازید یا یک دکمهٔ اصلی برای نمایش فهرست پلن‌ها ایجاد کنید. در پایان با /start نتیجه را بررسی کنید و یک خرید یا تست آزمایشی انجام دهید.\n\n"
            "⚠️ دکمهٔ فعال به‌تنهایی کافی نیست؛ محصول، نوع کانفیگ، قیمت، حجم، مدت اعتبار و اطلاعات فنی نیز باید کامل و فعال باشند."
        )
    return (
        "📘 <b>راهنمای اتصال محصولات خدمات مجازی به دکمه</b>\n\n"
        "ابتدا از مسیر زیر محصول موردنظر را بسازید و فعال کنید:\n"
        "<code>پنل مدیریت ← سرویس‌ها و محصولات</code>\n\n"
        "محصول می‌تواند شامل استارز، گیفت، شمارهٔ مجازی، پرمیوم، بوست، ری‌اکشن یا سرویس‌های دستی باشد. هنگام افزودن محصول، عنوان، قیمت، حداقل و حداکثر مقدار، موجودی و تنظیمات فنی سرویس را کامل کنید و سپس ذخیره و فعال‌سازی را بزنید.\n\n"
        "بعد از ساخت محصول، برای اتصال آن به دکمه وارد مسیر زیر شوید:\n"
        "<code>پنل مدیریت ← دکمه‌ها و تنظیمات ← تنظیم و مدیریت دکمه‌های صفحهٔ اصلی</code>\n\n"
        "روی <b>افزودن دکمه</b> بزنید، عنوانی واضح مثل «⭐ خرید استارز»، «🎁 خرید گیفت» یا «📞 شمارهٔ مجازی» انتخاب کنید و در بخش عملکرد، گزینهٔ سرویس‌ها و محصولات یا فروش محصول را بزنید. سپس محصول موردنظر را انتخاب و دکمه را ذخیره کنید.\n\n"
        "اگر محصول به سرویس یا تأمین‌کنندهٔ دیگری وابسته است، اتصال، موجودی و فعال‌بودن آن را نیز بررسی کنید. در پایان با /start وارد صفحهٔ اصلی شوید و دکمه را با یک سفارش آزمایشی تست کنید.\n\n"
        "⚠️ اگر محصول غیرفعال، ناقص یا ناموجود باشد، ممکن است دکمه نمایش داده شود اما خرید ادامه پیدا نکند."
    )


def _sec_products_text(bot_field: str) -> str:
    """توضیحِ بخشِ «سرویس‌ها و محصولات» — متناسب با زمینهٔ ربات، تا مثلاً ربات
    فروشگاهی حرفی از کانفیگ/VPN نبیند.
    === PATCH_SETTINGS_REGISTRY_V3_PRODUCTS === متنِ هر نوع در
    tenant/bots/<kind>/products_menu.py ثبت شده است."""
    from tenant.settings_registry import products_menu_for as _pm_for
    _pm = _pm_for(bot_field)
    desc = _pm.description if (_pm is not None and _pm.description) else "مدیریت سرویس‌ها و محصولات ربات:"
    return "📦 <b>سرویس‌ها و محصولات</b>\n\n" + desc


async def _sec_products_kb(bot_id: int, bot_field: str, plan: str) -> InlineKeyboardMarkup | ReplyKeyboardMarkup:
    """زیرمنوی سرویس‌ها و محصولات."""
    def ok(f): return has_feature(plan, f)
    # === PATCH_SETTINGS_REGISTRY_V3_PRODUCTS ===
    # دکمه‌هایِ هر نوعِ ربات در tenant/bots/<kind>/products_menu.py ثبت شده‌اند
    # (vpn_sales, digital_shop, booking, virtual_service, community_mgmt, ad_bot).
    from tenant.settings_registry import products_menu_for as _pm_for
    _pm = _pm_for(bot_field)
    opts: list[tuple[str, str]] = list(await _pm.opts(bot_id, plan)) if _pm is not None else []
    # === PATCH_EMPTY_PRODUCTS_SECTION_HINT_V1 ===
    # قبلاً وقتی به‌خاطرِ پلنِ فعلی هیچ گزینه‌ای واجدِ شرایط نبود (مثلاً باتِ
    # تبلیغاتی رو پلنِ رایگان/رشد که نه SCHEDULED_BROADCAST داره نه
    # PRODUCT_SHOP)، این بخش کاملاً خالی نشون داده می‌شد — فقط دکمهٔ
    # «بازگشت»، بدونِ هیچ توضیحی که چرا. کاربر فکر می‌کرد باگه. الان یه
    # دکمهٔ توضیحی نشون می‌ده که با زدنش می‌فهمه باید پلن رو ارتقا بده.
    # === PATCH_EMPTY_FIELD_PICKER_V1 ===
    # رباتِ بدونِ زمینه (معمولاً فروخته‌شده از رباتِ همکار) پلن‌اش مشکلی
    # ندارد؛ فقط نوعش تعیین نشده. به‌جایِ پیامِ گمراه‌کنندهٔ «نیاز ارتقای
    # پلن»، انتخاب‌گرِ نوعِ ربات نشان داده می‌شود (tenant/field_pick.py).
    from tenant.shared.field_pick import needs_field, BTN_PICK_FIELD
    if needs_field(bot_field):
        opts.insert(0, (BTN_PICK_FIELD, "tfld:menu"))
    if not opts:
        opts.append(("🔒 این بخش هنوز چیزی نداره (نیازِ ارتقای پلن)", "tadm:sec:products:lockedinfo"))
    # رنگ‌بندی اختصاصیِ بخشِ سرویس‌ها و محصولات؛ callbackها تغییر نمی‌کنند.
    # === PATCH_SMM_PROVIDERS_MENU_LAYOUT_V1 ===
    # ترتیبِ گزینه‌ها برایِ virtual_service عمداً بازچیده شده (سندِ
    # references/smm-menu-redesign.md در اسکیلِ botsaz-dev)؛ حالا در
    # tenant/bots/virtual_service/products_menu.py است، نه این‌جا.
    # رنگِ دکمه‌هایِ اختصاصیِ هر نوع از رجیستری می‌آید؛ این دو، مشترک‌اند.
    service_styles = {
        "tadm:sec:products:lockedinfo": ButtonStyle.DANGER,
        "tfld:menu": ButtonStyle.SUCCESS,  # === PATCH_EMPTY_FIELD_PICKER_V1 ===
    }
    if _pm is not None:
        service_styles.update({cbd: getattr(ButtonStyle, name.upper())
                               for cbd, name in _pm.styles.items()})
    # === PATCH_SMM_PRODUCTS_HUB_V1 ===
    # فقط برایِ virtual_service: «ارائه‌دهندگان» تنهایی زیرِ «مشاهده
    # سفارشات» می‌شینه؛ «مدیریتِ محصولات» با «مدیریتِ دسته‌ها» و «تنظیم
    # قیمت سرویس‌ها» با «سرویس‌های دستی» در یک ردیف (دو دکمه کنارِ هم)
    # نشون داده می‌شن. بقیهٔ bot_field ها دست‌نخورده، یک‌دکمه‌در‌هر‌ردیف می‌مونن.
    _vs_row_pairs = dict(_pm.row_pairs) if _pm is not None else {}

    def _grouped_opt_rows(opts_list, pair_map):
        by_cbd = {cbd: (lbl, cbd) for lbl, cbd in opts_list}
        seen = set()
        grouped = []
        for lbl, cbd in opts_list:
            if cbd in seen:
                continue
            partner_cbd = pair_map.get(cbd)
            if partner_cbd and partner_cbd in by_cbd and partner_cbd not in seen:
                grouped.append([(lbl, cbd), by_cbd[partner_cbd]])
                seen.add(cbd)
                seen.add(partner_cbd)
            else:
                grouped.append([(lbl, cbd)])
                seen.add(cbd)
        return grouped

    opt_rows = _grouped_opt_rows(opts, _vs_row_pairs)
    if await get_setting(bot_id, "menu_mode", "reply") != "inline":
        rows = [[KeyboardButton(text=lbl, style=service_styles.get(cbd, ButtonStyle.PRIMARY))
                 for lbl, cbd in row] for row in opt_rows]
        rows.append([KeyboardButton(text="⬅️ بازگشت", style=ButtonStyle.DANGER)])
        return ReplyKeyboardMarkup(keyboard=rows, resize_keyboard=True)
    rows = [[InlineKeyboardButton(text=lbl, callback_data=cbd,
                                  style=service_styles.get(cbd, _tadm_opt_style(lbl)))
             for lbl, cbd in row] for row in opt_rows]
    rows.append([InlineKeyboardButton(text="⬅️ بازگشت", callback_data="tadm:menu", style=ButtonStyle.DANGER)])
    return InlineKeyboardMarkup(inline_keyboard=rows)


async def _sec_finance_opts(bot_id: int, plan: str) -> list[tuple[str, str]]:
    """PATCH_FINANCE_KEYBOARD_MODE_TEXT_HANDLERS_V1 — لیستِ (برچسب, callback_data)
    زیرمنویِ «مالی و کیف پول» رو جدا بیرون کشیدم (قبلاً فقط داخلِ
    _sec_finance_kb بود) تا هم کیبورد ازش بسازه، هم دیسپچرِ حالتِ کیبوردی
    (پایین‌تر) بتونه دقیقاً همون نگاشتِ زنده رو برایِ مچ‌کردنِ متن استفاده کنه."""
    def ok(f): return has_feature(plan, f)
    auto_approve_v = await get_setting(bot_id, "auto_approve_receipts", "0")  # PATCH_AUTO_APPROVE_STATUS_AND_WARNING
    opts: list[tuple[str, str]] = [
        ("🧾 سفارش‌ها و رسیدها", "tadm:orders"),
        ("📊 گزارش کلی فروش ربات", "tadm:buyinfo:today:0"),
        ("💳 شماره کارت و کارت‌به‌کارت", "set:card"),
    ]
    # === PATCH_FREE_PLAN_SIMPLIFY_V1 ===
    # پلنِ رایگان فقط کارت‌به‌کارت دارد؛ هیچ درگاهی نباید ببیند. قبلاً
    # زرین‌پال و تاییدِ خودکارِ رسید بی‌قید به همه نشان داده می‌شد.
    if ok(Feature.GATEWAY_ZARINPAL):
        opts.append(("🔐 درگاه زرین‌پالِ ربات", "set:zarinpal"))
    # === PATCH_ZIBAL_GATEWAY_V1 ===
    if ok(Feature.GATEWAY_ZIBAL):
        opts.append(("🔐 درگاه زیبالِ ربات", "set:zibal"))
    if ok(Feature.AUTO_APPROVE_RECEIPT):
        opts.append(("🤖 تایید خودکار رسید: " + ("✅ فعال" if auto_approve_v == "1" else "❌ غیرفعال"),
                     "set:auto_approve_toggle"))
    # === PATCH_WALLET_CHARGE_IN_PURCHASE_TOGGLE_V1 ===
    # این تیک کنترل می‌کند که آیا گزینه‌هایِ «شارژ کیف‌پول» (ارز دیجیتال/سواپ‌ولت)
    # در صفحهٔ انتخابِ روشِ پرداختِ سفارش (هنگامِ خرید) نشان داده شوند یا نه.
    # پیش‌فرض خاموش است (نمایش داده نمی‌شود) — فقط کارت‌به‌کارت و کیف‌پول (کسر
    # از موجودی) در آن صفحه دیده می‌شود.
    #
    # === PATCH_FINANCE_TOGGLE_CLARITY_V1 ===
    # گزارشِ ادمین: «این دکمه‌ها با فعال/غیرفعال هیچ عملی انجام نمی‌دن».
    # با تست مستقیم تأیید شد که خودِ تنظیم درست عوض می‌شه — مشکل این بود که
    # دو دکمه‌ی «فعال»/«غیرفعال» همیشه به‌ترتیب سبز/قرمز بودن (رنگ‌شون به
    # وضعیتِ فعلی وابسته نبود)، و تنها نشانه‌ی وضعیت یه نقطه‌ی ایموجیِ ریز
    # (🔘/⚪️) بود که به‌سختی دیده می‌شد — یعنی از نظرِ ادمین، ظاهراً «هیچی
    # عوض نمی‌شد» با اینکه واقعاً عوض می‌شد. الان مثلِ «تایید خودکار رسید»
    # (که این مشکل رو نداشت) یک دکمه با وضعیتِ واضح تویِ متنِ خودش.
    # === PATCH_WALLET_PAY_TOGGLE_V1 ===
    _wpay_v = await get_setting(bot_id, "wallet_pay_purchase_enabled", "1")
    opts.append(("👛 پرداخت از کیف پول در خرید محصولات: " + ("✅ فعال" if _wpay_v != "0" else "❌ غیرفعال"),
                 "set:wallet_pay_toggle"))
    wallet_charge_v = await get_setting(bot_id, "wallet_charge_in_purchase_enabled", "0")
    opts.append((f"🔋 شارژ کیف پول در صفحه خرید: " + ("✅ فعال" if wallet_charge_v == "1" else "❌ غیرفعال"),
                 "set:wallet_charge_toggle"))
    # === PATCH_CARD_PURCHASE_TOGGLE_V1 === (فدایی) خاموش‌کردنِ کارت‌به‌کارت در فاکتورِ خرید، کنارِ دو تیکِ دیگر
    _cpay_v = await get_setting(bot_id, "card_purchase_enabled", "1")
    opts.append(("💳 پرداخت کارت‌به‌کارت در فاکتور خرید: " + ("✅ فعال" if _cpay_v != "0" else "❌ غیرفعال"),
                 "set:card_purchase_toggle"))
    # === PATCH_PAYGUIDE_MOVE_FINANCE_PRO_V1 ===
    # از «دکمه‌ها و تنظیمات» به اینجا منتقل شد؛ فقط پلنِ حرفه‌ای می‌بیند.
    if ok(Feature.PAYMENT_GUIDE):
        _pg_on = await get_setting(bot_id, "payguide_on", "") == "1"
        _pg_has = bool((await get_setting(bot_id, "payguide_text", "")).strip())
        opts.append(("💰 راهنمای پرداخت و افزایش موجودی: "
                     + ("✅ روشن" if (_pg_on and _pg_has) else
                        ("⚠️ متن ندارد" if _pg_on else "❌ خاموش")),
                     "tadm:payguide"))
    discount_purchase_v = await get_setting(bot_id, "discount_purchase_enabled", "1")
    if ok(Feature.DISCOUNT_CODES):   # PATCH_FREE_PLAN_SIMPLIFY_V1
        opts.append((f"🏷 استفاده از کد تخفیف در خرید: " + ("✅ فعال" if discount_purchase_v == "1" else "❌ غیرفعال"),
                     "set:discount_purchase_toggle"))
    # === PATCH_WALLET_LIMITS_V1 ===
    # درخواستِ ادمین (فدایی): حداقل و حداکثرِ واریز برایِ هر درگاه قابلِ تنظیم باشد.
    opts.append(("📏 حداقل و حداکثر واریز هر درگاه", "wlim:menu"))
    opts.append(("🎛 نام و ترتیبِ دکمه‌هایِ پرداخت", "gwl:menu"))   # PATCH_GATEWAY_LAYOUT_V1
    # === PATCH_CHANNEL_BTN_CLEARER_V1 === نامِ واضح‌تر، چون «کانالِ تاییدِ
    # رسید» به‌نظرِ چند ادمین معلوم نمی‌کرد که کارِ دکمه *اتصال* است.
    opts.append(("🧾 متصل‌کردن کانالِ تاییدِ رسیدها", "tadm:receiptchannel"))
    # === PATCH_TX_LOG_CHANNEL_V1 ===
    _txch = await get_setting(bot_id, "tx_log_channel", "")
    if ok(Feature.TX_LOG_CHANNEL):   # PATCH_FREE_PLAN_SIMPLIFY_V1
        opts.append(("📊 کانالِ لاگ تراکنشها: " + ("✅ متصل" if _txch else "❌ خاموش"),
                     "set:txlog"))
    # === PATCH_TRIAL_REPORT_CHANNEL_V1 ===
    # فقط رباتِ فروشِ VPN تستِ رایگانِ VPN دارد (در «خدمات مجازی»/فروشگاه/… بی‌معنی است)
    async with Session() as _sf:
        _bf = await _sf.scalar(select(BotRow.field).where(BotRow.id == bot_id))
    if ok(Feature.TRIAL_REPORT_CHANNEL) and _bf == "vpn_sales":
        _trch = await get_setting(bot_id, "trial_report_channel", "")
        opts.append(("🔑 کانالِ گزارشِ اکانتِ تست: " + ("✅ متصل" if _trch else "❌ خاموش"),
                     "set:trrep"))
    # === PATCH_KYC_V1 ===
    _kyc_on = await get_setting(bot_id, "kyc_enabled", "0") == "1"
    if ok(Feature.KYC_VERIFY):       # PATCH_FREE_PLAN_SIMPLIFY_V1
        opts.append(("🛡 احرازِ هویتِ کاربران: " + ("✅ فعال" if _kyc_on else "❌ خاموش"),
                     "set:kyc"))
    # === PATCH_UNIQUEPAY_V1 ===
    _up_on = await get_setting(bot_id, "uniquepay_enabled", "0") == "1"
    if ok(Feature.GATEWAY_UNIQUEPAY):  # PATCH_FREE_PLAN_SIMPLIFY_V1
        opts.append(("💳 درگاهِ یونیک‌پی: " + ("✅ فعال" if _up_on else "❌ خاموش"),
                     "set:uniquepay"))
    # === PATCH_APAY_GATEWAY_V1 ===
    _ap_on = await get_setting(bot_id, "apay_enabled", "0") == "1"
    if ok(Feature.GATEWAY_APAY):
        opts.append(("💳 درگاهِ آپی (کارت‌به‌کارت آنی): " + ("✅ فعال" if _ap_on else "❌ خاموش"),
                     "set:apay"))
    # === PATCH_ABANGATEWAY_V1 ===
    _ab_on = await get_setting(bot_id, "abangateway_enabled", "0") == "1"
    if ok(Feature.GATEWAY_ABANGATEWAY):
        opts.append(("💳 درگاهِ آبان گیت‌وی: " + ("✅ فعال" if _ab_on else "❌ خاموش"),
                     "set:abangateway"))
    if ok(Feature.WALLET_RECEIPT_BTNS):   # PATCH_FREE_PLAN_SIMPLIFY_V1
        opts.append(("🔘 انتخاب دکمه زیر پیام تأیید واریز", "set:wallet_receipt_buttons"))
    # === PATCH_PHONE_LOG_CHANNEL_V2 === درست بالایِ گزینهٔ تاییدِ شماره
    _plog = (await get_setting(bot_id, "phone_log_chat", "")).strip()
    if ok(Feature.PHONE_VERIFY):     # PATCH_FREE_PLAN_SIMPLIFY_V1
        opts.append((f"📥 کانالِ ثبتِ شماره‌ها {'🟢' if _plog else '⚪️'}",
                     "set:phonelog"))
    # === PATCH_PAY_PHONE_VERIFY_V1 ===
    # === PATCH_FINANCE_TOGGLE_CLARITY_V1 ===
    _payphone_on = (await get_setting(bot_id, "phone_verify_pay", "off")) == "on"
    if ok(Feature.PHONE_VERIFY):     # PATCH_FREE_PLAN_SIMPLIFY_V1
        opts.append((f"📱 تایید شماره پیش از پرداخت: " + ("✅ فعال" if _payphone_on else "❌ غیرفعال"),
                     "set:toggle_payphone"))
    if ok(Feature.GATEWAY_PAYMENT):
        opts.append(("🪙 درگاه ارز دیجیتال (NOWPayments)", "set:crypto"))
    if plan != "free":
        opts.append(("🟦 درگاه سواپ‌ولت (SwapPay)", "set:swap"))
    if ok(Feature.BULK_WALLET):      # PATCH_FREE_PLAN_SIMPLIFY_V1
        opts.append(("💸 شارژ/کسر همگانی کیف پول", "tadm:bulkwallet"))
    if ok(Feature.GATEWAY_STARS):    # PATCH_FREE_PLAN_SIMPLIFY_V1
        opts.append(("⭐ پرداخت با استارز تلگرام", "set:stars"))
    if plan != "free":
        opts.append(("💠 درگاه تون‌پیز (TonPays)", "set:tonpays"))  # === PATCH_TONPAYS_V1 ===
    # === PATCH_TON_DIRECT_V1 === واریزِ مستقیم به ولتِ خودِ مالک (بدونِ درگاه)
    # === PATCH_TON_DIRECT_PRO_ONLY_V1 === طبقِ خواستهٔ مدیر فقط پلنِ حرفه‌ای.
    # عمداً به‌جایِ حذفِ کامل، در پلن‌هایِ پایین‌تر یک گزینهٔ قفل‌شده نشان
    # داده می‌شود تا مالک بداند چنین امکانی هست و برایِ ارتقا انگیزه بگیرد —
    # همان الگویی که برایِ «خرید ترکیبی» هم استفاده شده.
    # === PATCH_COIN_DIRECT_MULTI_ASSET_V1 ===
    # یک ورودی برایِ هر سه ارز (تون/ترون/تتر). callback تازه است چون صفحهٔ
    # مقصد هم تازه است؛ set:ton_direct عمداً زنده مانده تا دکمه‌هایِ شیشه‌ایِ
    # قدیمی که هنوز در چتِ مالک‌ها هست بی‌جواب نماند.
    if ok(Feature.TON_DIRECT):
        opts.append(("💎 پرداخت مستقیم ارز (تون/ترون/تتر)", "set:coin_direct"))
    elif plan != "free":
        opts.append(("🔒 پرداخت مستقیم ارز (ویژهٔ حرفه‌ای)", "set:coin_direct"))
    # دکمهٔ مدیریت کدهای تخفیف در منوی مالی همیشه قابل مشاهده باشد؛
    # بررسی دسترسی همچنان داخل handler قبلی انجام می‌شود.
    if ok(Feature.DISCOUNT_CODES):   # PATCH_FREE_PLAN_SIMPLIFY_V1
        opts.append(("🏷 کدهای تخفیف", "tadm:discounts"))
        # === PATCH_FIRST_PURCHASE_DISCOUNT_V1 ===
        _fb_on = await get_setting(bot_id, "firstbuy_on", "") == "1"
        _fb_v = await get_setting(bot_id, "firstbuy_value", "0")
        _fb_t = await get_setting(bot_id, "firstbuy_type", "percent")
        _fb_lbl = (f"{_fb_v}٪" if _fb_t == "percent" else f"{_fb_v} تومان")
        opts.append(("🎁 تخفیفِ اولین خرید: "
                     + (f"✅ {_fb_lbl}" if _fb_on else "❌ خاموش"),
                     "tadm:firstbuy"))
    # === PATCH_WELCOME_BONUS_V1 ===
    # درخواستِ ادمین: به هر کاربری که برایِ اولین بار /start بزنه، یه مبلغِ
    # ثابت خودکار به کیف‌پولش اضافه بشه — «هدیهٔ ورود»، جدا از تخفیفِ اولین
    # خرید (که فقط رویِ قیمتِ خرید تخفیف می‌ده، پول نمی‌ده) و جدا از پاداشِ
    # دعوت (که فقط برایِ دعوت‌کننده‌ست، نه خودِ کاربرِ تازه‌وارد).
    _wb_on = await get_setting(bot_id, "welcome_bonus_on", "") == "1"
    _wb_amt = await get_setting(bot_id, "welcome_bonus_amount", "0")
    opts.append(("🎁 هدیهٔ ورودِ کاربرانِ جدید: "
                 + (f"✅ {int(_wb_amt):,} ت" if _wb_on else "❌ خاموش"),
                 "tadm:welcomebonus"))
    # === PATCH_CHARGE_BONUS_V1 === بونوسِ درصدیِ شارژِ کیف پول (پله‌ای)
    _cb_on = await get_setting(bot_id, "chg_bonus_on", "") == "1"
    opts.append(("🎁 بونوسِ شارژِ کیف پول: " + ("✅ روشن" if _cb_on else "❌ خاموش"), "tadm:chgbonus"))
    # === PATCH_SETTINGS_REGISTRY_V5_SECTIONS ===
    # گزینه‌هایِ مخصوصِ هر نوعِ ربات در این بخش از tenant/bots/<kind>/settings.py می‌آیند.
    try:
        from tenant.settings_registry import (visible_items as _rv, merge_into as _rm,
                                              resolve_labels as _rr, section_key as _sk)
        async with Session() as _s_sec:
            _row_sec = await _s_sec.get(BotRow, bot_id)
        if _row_sec is not None:
            opts = _rm(opts, await _rr(_rv(_sk("finance", _row_sec.field), plan), bot_id))
    except Exception:
        logger.exception("خطا در افزودنِ آیتم‌هایِ رجیستریِ بخشِ مالی")
    return opts


async def _sec_finance_kb(bot_id: int, plan: str) -> InlineKeyboardMarkup | ReplyKeyboardMarkup:
    """زیرمنوی مالی و کیف پول با چیدمان گروه‌بندی‌شده و رنگ‌بندی ثابت."""
    opts = await _sec_finance_opts(bot_id, plan)
    by_cb = {cb: (lbl, cb) for lbl, cb in opts}

    top_cbs = ("tadm:orders", "tadm:buyinfo:today:0", "set:card")
    gateway_cbs = ("set:zarinpal", "set:zibal", "set:crypto", "set:swap", "set:tonpays",
                   "set:hesabpay", "set:ton_direct", "set:coin_direct", "set:stars")
    # === PATCH_FINANCE_TOGGLE_CLARITY_V1 ===
    # این سه‌تا الان مثلِ auto_approve_toggle یک دکمهٔ تکی‌اند (نه جفتِ
    # فعال/غیرفعالِ همیشه‌هم‌رنگ) — پس دیگه نیازی به گروه‌بندیِ ویژهٔ
    # toggle_pair_specs ندارن؛ همون مکانیزمِ سادهٔ auto_approve_toggle کافیه.
    single_toggle_cbs = ("set:auto_approve_toggle", "set:wallet_pay_toggle", "set:wallet_charge_toggle",
                         "set:card_purchase_toggle",   # PATCH_CARD_PURCHASE_TOGGLE_V1
                         "set:discount_purchase_toggle", "set:toggle_payphone")

    groups: list[list[tuple[str, str]]] = []
    for cb in top_cbs:
        if cb in by_cb:
            groups.append([by_cb[cb]])
    for cb in gateway_cbs:
        if cb in by_cb:
            groups.append([by_cb[cb]])
    used = set(top_cbs) | set(gateway_cbs) | set(single_toggle_cbs)
    for item in opts:
        if item[1] not in used:
            groups.append([item])
    for cb in single_toggle_cbs:
        if cb in by_cb:
            groups.append([by_cb[cb]])

    finance_styles = {
        "tadm:orders": ButtonStyle.PRIMARY,
        "tadm:buyinfo:today:0": ButtonStyle.SUCCESS,
        "set:card": ButtonStyle.PRIMARY,
        "set:zarinpal": ButtonStyle.PRIMARY,
        "set:zibal": ButtonStyle.PRIMARY,
        "set:crypto": ButtonStyle.PRIMARY,
        "set:swap": ButtonStyle.PRIMARY,
        "set:tonpays": ButtonStyle.PRIMARY,
        "set:hesabpay": ButtonStyle.PRIMARY,
        "set:ton_direct": ButtonStyle.PRIMARY,  # PATCH_TON_DIRECT_V1
        "set:coin_direct": ButtonStyle.PRIMARY,  # PATCH_COIN_DIRECT_MULTI_ASSET_V1
        "wlim:menu": ButtonStyle.PRIMARY,              # PATCH_WALLET_LIMITS_V1
        "gwl:menu": ButtonStyle.PRIMARY,               # PATCH_GATEWAY_LAYOUT_V1
        "tadm:receiptchannel": ButtonStyle.SUCCESS,
        "tadm:smmorderchannel": ButtonStyle.SUCCESS,   # PATCH_SMM_ORDER_CHANNEL_V1
        "set:wallet_receipt_buttons": ButtonStyle.PRIMARY,
        "tadm:bulkwallet": ButtonStyle.DANGER,
        "set:stars": ButtonStyle.SUCCESS,
        "tadm:discounts": ButtonStyle.SUCCESS,
        "set:auto_approve_toggle": ButtonStyle.SUCCESS,
        # === PATCH_FINANCE_TOGGLE_CLARITY_V1 ===
        "set:wallet_charge_toggle": ButtonStyle.SUCCESS,
        "set:wallet_pay_toggle": ButtonStyle.SUCCESS,   # PATCH_WALLET_PAY_TOGGLE_V1
        "set:card_purchase_toggle": ButtonStyle.SUCCESS,   # PATCH_CARD_PURCHASE_TOGGLE_V1
        "set:discount_purchase_toggle": ButtonStyle.SUCCESS,
        "set:toggle_payphone": ButtonStyle.SUCCESS,
        # === PATCH_PAYGUIDE_MOVE_FINANCE_PRO_V1 ===
        "tadm:payguide": ButtonStyle.PRIMARY,
        # === PATCH_WELCOME_BONUS_V1 ===
        "tadm:welcomebonus": ButtonStyle.SUCCESS,
        "tadm:chgbonus": ButtonStyle.SUCCESS,   # PATCH_CHARGE_BONUS_V1
    }
    if await get_setting(bot_id, "menu_mode", "reply") != "inline":
        rows = []
        for group in groups:
            row = []
            for lbl, cb in group:
                row.append(KeyboardButton(text=lbl, style=None if cb == "__finance_toggle_header__" else finance_styles.get(cb, ButtonStyle.PRIMARY)))
            rows.append(row)
        rows.append([KeyboardButton(text="⬅️ بازگشت", style=ButtonStyle.DANGER)])
        return ReplyKeyboardMarkup(keyboard=rows, resize_keyboard=True)
    rows = []
    for group in groups:
        row = []
        for lbl, cb in group:
            row.append(InlineKeyboardButton(text=lbl, callback_data="noop" if cb == "__finance_toggle_header__" else cb,
                                            style=None if cb == "__finance_toggle_header__" else finance_styles.get(cb, _tadm_opt_style(lbl))))
        rows.append(row)
    rows.append([InlineKeyboardButton(text="⬅️ بازگشت", callback_data="tadm:menu",
                                      style=ButtonStyle.DANGER)])
    return InlineKeyboardMarkup(inline_keyboard=rows)


async def _sec_stats_kb(bot_id: int, plan: str) -> InlineKeyboardMarkup | ReplyKeyboardMarkup:
    """زیرمنوی آمار و گزارشات با چیدمان یکسان در حالتِ شیشه‌ای و کیبوردی."""
    def ok(f): return has_feature(plan, f)
    purchase_notify_v = await get_setting(bot_id, "purchase_notify", "1")
    new_user_notify_v = await get_setting(bot_id, "new_user_notify", "0")
    # ترتیب درخواستی: آمار/مدیریت کاربران، کانال اعتمادسازی/نفرات برتر،
    # سپس اطلاع خودکار خرید و اطلاع ورود کاربر جدید.
    opts: list[tuple[str, str]] = []
    if ok(Feature.BOT_STATS):
        opts.append(("📊 آمار کلی ربات", "tadm:stats"))
    if ok(Feature.USER_LOOKUP):
        opts.append(("👥 مدیریت کاربران", "tadm:users"))
    opts.append(("🎖 کانال اعتمادسازی", "tadm:trustreport"))
    if ok(Feature.ADVANCED_STATS):
        opts.append(("🏆 نفرات برتر", "tc:settings"))
    opts.append(("🔔 اطلاع خودکار خرید: " + ("✅ فعال" if purchase_notify_v == "1" else "❌ غیرفعال"),
                 "tadm:pnotify_toggle"))
    opts.append(("👤 اطلاع ورود کاربر جدید: " + ("✅ فعال" if new_user_notify_v == "1" else "❌ غیرفعال"),
                 "tadm:newuser_notify_toggle"))
    styles = {
        "tadm:stats": ButtonStyle.PRIMARY,
        "tadm:users": ButtonStyle.PRIMARY,
        "tadm:trustreport": ButtonStyle.SUCCESS,
        "tc:settings": ButtonStyle.SUCCESS,
        "tadm:pnotify_toggle": ButtonStyle.PRIMARY,
        "tadm:newuser_notify_toggle": ButtonStyle.PRIMARY,
    }
    # ردیف‌بندی ثابتِ درخواستی: دو ردیف اول دوتایی، و هر اعلان در ردیف مستقل.
    # === PATCH_PERIOD_STATS_V1 === «آمار زمانی» (سفارش/شارژ/زیرمجموعه) ردیفِ جدایِ خودش را دارد
    _pst = [("📈 آمار زمانی (سفارش/شارژ/زیرمجموعه)", "pst:menu")] if ok(Feature.BOT_STATS) else []
    styles["pst:menu"] = ButtonStyle.SUCCESS
    groups = [opts[0:2], _pst, opts[2:3], opts[3:4], opts[4:5], opts[5:6]]
    if await get_setting(bot_id, "menu_mode", "reply") != "inline":
        rows = [[KeyboardButton(text=lbl, style=styles.get(cbd, _tadm_opt_style(lbl)))
                 for lbl, cbd in group] for group in groups if group]
        rows.append([KeyboardButton(text="⬅️ بازگشت", style=ButtonStyle.DANGER)])
        return ReplyKeyboardMarkup(keyboard=rows, resize_keyboard=True)
    rows = [[InlineKeyboardButton(text=lbl, callback_data=cbd,
                                  style=styles.get(cbd, _tadm_opt_style(lbl)))
             for lbl, cbd in group] for group in groups if group]
    rows.append([InlineKeyboardButton(text="⬅️ بازگشت", callback_data="tadm:menu",
                                      style=ButtonStyle.DANGER)])
    return InlineKeyboardMarkup(inline_keyboard=rows)


async def _sec_admins_kb(bot_id: int, plan: str = "free") -> InlineKeyboardMarkup | ReplyKeyboardMarkup:
    """زیرمنوی ادمین‌ها، پشتیبانی و ارتباط با کاربران."""
    def ok(f): return has_feature(plan, f)
    opts: list[tuple[str, str]] = [
        ("👮 مدیریت ادمین‌های پشتیبان", "tadm:admins"),
        ("🎫 تیکت‌ها و پیام‌های کاربران", "tadm:tickets"),
        # === PATCH_SUPPORT_DIRECT_CONTACT_V1 ===
        ("💬 آیدی/یوزرنیمِ تماسِ مستقیم", "supp:contact"),
        ("📢 عضویت اجباری در کانال", "tadm:forcejoin"),
    ]
    # === PATCH_RESELLER_MOVE_TO_ADMINS_V1 ===
    # عمداً همین‌جا (قبل از broadcast/polls) اضافه می‌شود: منطقِ چیدمانِ
    # پایینِ همین تابع به این بسته است که دو گزینهٔ *آخر* دقیقاً همان دو
    # باشند تا کنار هم بنشینند. append در انتها آن جفت‌شدن را می‌شکست.
    # === PATCH_SETTINGS_REGISTRY_V5_SECTIONS ===
    # گزینه‌هایِ مخصوصِ هر نوعِ ربات در این بخش از tenant/bots/<kind>/settings.py می‌آیند.
    try:
        from tenant.settings_registry import (visible_items as _rv, merge_into as _rm,
                                              resolve_labels as _rr, section_key as _sk)
        async with Session() as _s_sec:
            _row_sec = await _s_sec.get(BotRow, bot_id)
        if _row_sec is not None:
            opts = _rm(opts, await _rr(_rv(_sk("admins", _row_sec.field), plan), bot_id))
    except Exception:
        logger.exception("خطا در افزودنِ آیتم‌هایِ رجیستریِ بخشِ ادمین‌ها")
    if ok(Feature.BROADCAST_PHOTO):
        opts.append(("📣 ارسال پیام همگانی", "tadm:broadcast"))
    if ok(Feature.POLL):
        opts.append(("📋 نظرسنجی‌ها", "tadm:polls"))
    if await get_setting(bot_id, "menu_mode", "reply") != "inline":
        # Reply Keyboard نیز از فیلدِ style پشتیبانی می‌کند؛ همان رنگ‌بندیِ
        # حالتِ Inline را برای دکمه‌های این بخش به‌صورت مستقیم ارسال می‌کنیم.
        _styles = {
            "tadm:admins": ButtonStyle.PRIMARY,
            "tadm:tickets": ButtonStyle.PRIMARY,
            "supp:contact": ButtonStyle.SUCCESS,
            "tadm:forcejoin": ButtonStyle.DANGER,
            "tadm:broadcast": ButtonStyle.PRIMARY,
            "tadm:polls": ButtonStyle.SUCCESS,
            "rsl:menu": ButtonStyle.SUCCESS,  # PATCH_RESELLER_MOVE_TO_ADMINS_V1
        }
        def _reply_btn(lbl: str, cbd: str) -> KeyboardButton:
            return KeyboardButton(text=lbl, style=_styles.get(cbd, _tadm_opt_style(lbl)))
        rows = [[_reply_btn(lbl, cbd)] for lbl, cbd in opts[:-2]]
        if len(opts) >= 2 and opts[-2][1] == "tadm:broadcast" and opts[-1][1] == "tadm:polls":
            rows.append([
                _reply_btn(opts[-2][0], opts[-2][1]),
                _reply_btn(opts[-1][0], opts[-1][1]),
            ])
        else:
            rows.extend([[_reply_btn(lbl, cbd)] for lbl, cbd in opts[-2:]])
        rows.append([KeyboardButton(text="⬅️ بازگشت", style=ButtonStyle.DANGER)])
        return ReplyKeyboardMarkup(keyboard=rows, resize_keyboard=True)
    # همهٔ گزینه‌ها مثل قبل حفظ می‌شوند؛ فقط دو گزینهٔ پایانیِ موجود
    # («ارسال پیام همگانی» و «نظرسنجی‌ها») کنار هم قرار می‌گیرند.
    _styles = {
        "tadm:admins": ButtonStyle.PRIMARY,
        "tadm:tickets": ButtonStyle.PRIMARY,
        "supp:contact": ButtonStyle.SUCCESS,
        "tadm:forcejoin": ButtonStyle.DANGER,
        "tadm:broadcast": ButtonStyle.PRIMARY,
        "tadm:polls": ButtonStyle.SUCCESS,
        "rsl:menu": ButtonStyle.SUCCESS,  # PATCH_RESELLER_MOVE_TO_ADMINS_V1
    }
    rows = []
    for lbl, cbd in opts[:-2]:
        rows.append([InlineKeyboardButton(text=lbl, callback_data=cbd,
                                          style=_styles.get(cbd, _tadm_opt_style(lbl)))])
    if len(opts) >= 2 and opts[-2][1] == "tadm:broadcast" and opts[-1][1] == "tadm:polls":
        rows.append([
            InlineKeyboardButton(text=opts[-2][0], callback_data=opts[-2][1],
                                 style=_styles[opts[-2][1]]),
            InlineKeyboardButton(text=opts[-1][0], callback_data=opts[-1][1],
                                 style=_styles[opts[-1][1]]),
        ])
    else:
        for lbl, cbd in opts[-2:]:
            rows.append([InlineKeyboardButton(text=lbl, callback_data=cbd,
                                              style=_styles.get(cbd, _tadm_opt_style(lbl)))])
    rows.append([InlineKeyboardButton(text="⬅️ بازگشت", callback_data="tadm:menu", style=ButtonStyle.DANGER)])
    return InlineKeyboardMarkup(inline_keyboard=rows)


