@tenant_router.message(ChannelPostFSM.wait_channel)
async def tadm_chpost_setch_recv(msg: Message, state: FSMContext, bot: Bot):
    row = await get_bot_row(bot)
    if not row or not await is_owner_or_admin(row.id, msg.from_user.id, row.owner_id):
        await state.clear()
        return
    if (msg.text or "").strip() == "❌ لغو":
        await state.clear()
        await msg.answer("لغو شد.", reply_markup=await smart_cancel_kb(bot))
        txt, kb = await _chpost_menu(row.id)
        await msg.answer(txt, reply_markup=kb)
        return

    # === PATCH_TENANT_CHPOST_FORWARD_ORIGIN_V1 ===
    # فیلدِ قدیمیِ msg.forward_from_chat طبقِ Bot API 7.0+ منسوخ شده و تلگرام
    # دیگه همیشه پرش نمی‌کنه (به‌خصوص فورواردِ کانال‌ها) — همینه که اتصالِ
    # کانال با فوروارد اکثراً شکست می‌خورد و ادمین به «ارسال پست» نمی‌رسید.
    # حالا اول forward_origin (فیلدِ جدید) چک می‌شه و فقط برای سازگاری با
    # نسخه‌های قدیمی، به‌عنوانِ fallback به forward_from_chat هم سر می‌زنیم.
    target = None
    fwd_origin = getattr(msg, "forward_origin", None)
    if fwd_origin is not None and getattr(fwd_origin, "type", None) == "channel":
        target = fwd_origin.chat.id
    elif msg.forward_from_chat and msg.forward_from_chat.type == "channel":
        target = msg.forward_from_chat.id
    else:
        raw = (msg.text or "").strip()
        if raw.startswith("@") and len(raw) > 1:
            target = raw
        elif raw.lstrip("-").isdigit():
            target = int(raw)

    if target is None:
        await msg.answer(
            "❌ این یک فورواردِ کانال یا یوزرنیمِ معتبر نبود. یک پیام از کانال فوروارد کن یا "
            "یوزرنیمش را با @ بفرست، یا «❌ لغو» را بزن.")
        return

    try:
        chat = await bot.get_chat(target)
        _st = await state.get_data()
        _kind = _st.get("chpost_conn_kind", "channel")
        if _kind == "group":
            if chat.type not in ("group", "supergroup"):
                await msg.answer("❌ این یک گروه نیست. لطفاً گروه را فوروارد/معرفی کن.")
                return
        elif chat.type != "channel":
            await msg.answer("❌ این یک کانال نیست. لطفاً کانال را فوروارد/معرفی کن.")
            return
        member = await bot.get_chat_member(chat.id, bot.id)
        if member.status != "administrator":
            await msg.answer(
                "❌ ربات در این کانال ادمین نیست. اول ربات را با دسترسیِ «ارسال پیام» ادمینِ "
                "کانال کن، بعد دوباره امتحان کن.")
            return
    except (TelegramBadRequest, TelegramForbiddenError):
        await msg.answer(
            "❌ به این کانال دسترسی ندارم. مطمئن شو یوزرنیم/آیدی درست است و ربات آنجا ادمین است.")
        return
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        await msg.answer("❌ خطایی پیش آمد، دوباره امتحان کن.")
        return

    _pref = "chpost_group" if _kind == "group" else "chpost_chat"
    await set_setting(row.id, f"{_pref}_id", str(chat.id))
    await set_setting(row.id, f"{_pref}_title", chat.title or chat.username or str(chat.id))
    await state.clear()
    await msg.answer(f"✅ کانال «{chat.title or chat.username}» وصل شد.",
                     reply_markup=await smart_cancel_kb(bot))
    txt, kb = await _chpost_menu(row.id)
    await msg.answer(txt, reply_markup=kb)


