# ═══════════ PATCH_CHPOST_ATTACH_EXISTING_V1 ═══════════
# افزودنِ دکمه به پستی که ادمین خودش مستقیم (نه از طریقِ ربات) توی کانال
# گذاشته — چون تلگرام ارسالِ ایموجیِ پرمیوم را فقط به بات‌هایی با یوزرنیمِ
# ویژهٔ Fragment اجازه می‌دهد، اگر ادمین خودش با اکانتِ پرمیومش پست را در
# کانال بگذارد (ایموجیِ پرمیومش سالم می‌ماند) و فقط دکمه را از ربات بخواهد،
# دیگر به این محدودیت برنمی‌خوریم — چون edit_message_reply_markup فقط
# کیبورد را عوض می‌کند، نه محتوایِ پیام را.

@tenant_router.callback_query(F.data == "tadm:chpost:attach_start")
async def tadm_chpost_attach_start(cb: CallbackQuery, bot: Bot, state: FSMContext):
    row = await _gate(cb, bot, Feature.CHANNEL_POST)
    if not row:
        return
    if not await get_setting(row.id, "chpost_chat_id", ""):
        await cb.answer("اول یک کانال وصل کن.", show_alert=True)
        return
    await state.set_state(ChannelPostFSM.wait_target_msg)
    await state.update_data(chpost_mode="attach", chpost_buttons=[], chpost_button_ids=[],
                            chpost_guide_keys=[],
                            chpost_target_chat_id=None, chpost_target_msg_id=None)
    try:
        await cb.message.edit_reply_markup(reply_markup=None)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.message.answer(
        "📎 <b>افزودنِ دکمه به پستِ موجود</b>\n\n"
        "همون پستی که خودت مستقیم توی کانال گذاشتی را برایم <b>فوروارد کن</b>، "
        "یا لینکِ پیام را بفرست (مثلاً <code>https://t.me/mychannel/123</code>).\n\n"
        "⚠️ باید همون کانالِ متصل‌شده باشد؛ متنِ پست دست‌نخورده می‌ماند، فقط دکمه زیرش اضافه می‌شود.",
        reply_markup=cancel_kb(),
    )
    await cb.answer()


_TME_MSG_LINK_RE = re.compile(
    r"(?:https?://)?t\.me/(c/(?P<cid>\d+)|(?P<uname>[A-Za-z][\w]{3,31}))/(?P<mid>\d+)(?:[/?]|\b)")


@tenant_router.message(ChannelPostFSM.wait_target_msg)
async def tadm_chpost_target_recv(msg: Message, state: FSMContext, bot: Bot):
    row = await get_bot_row(bot)
    if not row or not await is_owner_or_admin(row.id, msg.from_user.id, row.owner_id):
        await state.clear()
        return
    if (msg.text or "").strip() == "❌ لغو":
        await state.clear()
        await msg.answer("لغو شد.", reply_markup=await smart_cancel_kb(bot))
        txt, kb = await _chpost_menu(row.id)
        await msg.answer(txt, reply_markup=kb)
        return

    saved_chat_id = await get_setting(row.id, "chpost_chat_id", "")
    target_chat_id: int | str | None = None
    target_msg_id: int | None = None

    # ۱) فوروارد از خودِ کانال — دقیق‌ترین و مطمئن‌ترین راه
    fwd_origin = getattr(msg, "forward_origin", None)
    if fwd_origin is not None and getattr(fwd_origin, "type", None) == "channel":
        target_chat_id = fwd_origin.chat.id
        target_msg_id = fwd_origin.message_id
    elif msg.forward_from_chat and msg.forward_from_chat.type == "channel":
        target_chat_id = msg.forward_from_chat.id
        target_msg_id = msg.forward_from_message_id
    else:
        # ۲) لینکِ مستقیمِ پیام (t.me/username/123 یا t.me/c/123456789/123)
        raw = (msg.text or "").strip()
        m = _TME_MSG_LINK_RE.search(raw)
        if m:
            target_msg_id = int(m.group("mid"))
            if m.group("cid"):
                target_chat_id = int(f"-100{m.group('cid')}")
            elif m.group("uname"):
                target_chat_id = f"@{m.group('uname')}"

    if target_chat_id is None or target_msg_id is None:
        await msg.answer(
            "❌ این نه فورواردِ یک پستِ کانال بود، نه لینکِ معتبرِ پیام. یکی از پستِ کانال "
            "برایم فوروارد کن یا لینکش را بفرست (مثلاً https://t.me/mychannel/123)، "
            "یا «❌ لغو» را بزن.")
        return

    # اطمینان از این‌که پیام واقعاً متعلق به همون کانالِ متصل‌شده است — چون
    # بعداً می‌خواهیم edit_message_reply_markup بزنیم و اگه کانالِ اشتباه
    # باشد یا خودِ ربات آنجا ادمین نباشد، اون درخواست شکست می‌خورد.
    try:
        chat = await bot.get_chat(target_chat_id)
    except (TelegramBadRequest, TelegramForbiddenError):
        await msg.answer("❌ به این کانال دسترسی ندارم. مطمئن شو لینک/فوروارد درست است.")
        return
    if saved_chat_id and str(chat.id) != str(saved_chat_id):
        await msg.answer(
            "❌ این پیام مالِ کانالِ دیگری است، نه همون کانالِ متصل‌شده به این بخش.\n"
            "پیام را از همون کانالِ متصل فوروارد کن، یا اول از «✏️ تغییر کانال» کانال را عوض کن.")
        return

    await state.update_data(chpost_target_chat_id=chat.id, chpost_target_msg_id=target_msg_id)
    await state.set_state(ChannelPostFSM.wait_attach_idle)
    await msg.answer("👌 پیام پیدا شد. حالا دکمه(ها) را اضافه کن:", reply_markup=await smart_cancel_kb(bot))
    await _chpost_preview(msg, state, row.id, bot=bot)


@tenant_router.callback_query(F.data == "tadm:chpost:attach_apply")
async def tadm_chpost_attach_apply(cb: CallbackQuery, bot: Bot, state: FSMContext):
    row = await _gate(cb, bot, Feature.CHANNEL_POST)
    if not row:
        return
    data = await state.get_data()
    target_chat_id = data.get("chpost_target_chat_id")
    target_msg_id = data.get("chpost_target_msg_id")
    if not target_chat_id or not target_msg_id:
        await cb.answer("پیامِ هدف مشخص نیست. از اول شروع کن.", show_alert=True)
        return
    buttons = data.get("chpost_buttons") or []
    button_ids = data.get("chpost_button_ids") or []
    guide_keys = list(data.get("chpost_guide_keys") or [])  # PATCH_CHPOST_PICK_GUIDE_CHILDREN_V1
    kb = await _chpost_full_kb(row.id, buttons, button_ids, bot=bot,
                               guide_keys=guide_keys)
    if kb is None:
        await cb.answer("اول حداقل یک دکمه اضافه کن.", show_alert=True)
        return
    try:
        await bot.edit_message_reply_markup(
            chat_id=target_chat_id, message_id=target_msg_id, reply_markup=kb)
    except (TelegramBadRequest, TelegramForbiddenError) as e:
        await cb.message.answer(
            "❌ چسباندنِ دکمه ناموفق بود. احتمالاً ربات دیگر در آن کانال ادمین نیست، "
            "یا پیام حذف شده.\n"
            f"جزئیات: {e}")
        await cb.answer()
        return
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        await cb.message.answer("❌ خطای غیرمنتظره‌ای پیش آمد.")
        await cb.answer()
        return
    await state.clear()
    await cb.message.answer("✅ دکمه(ها) زیرِ همون پست در کانال چسبانده شد؛ متنِ پست دست‌نخورده ماند.",
                            reply_markup=await smart_cancel_kb(bot))
    txt, kbm = await _chpost_menu(row.id)
    await cb.message.answer(txt, reply_markup=kbm)
    await cb.answer()


async def _resolve_chpost_target(msg: Message, bot: Bot, saved_chat_id: str):
    """=== PATCH_CHPOST_DETACH_EXISTING_V1 ===
    فوروارد/لینکِ پستِ کانال را به (chat_id, msg_id) تبدیل می‌کند — همون
    منطقی که تویِ tadm_chpost_target_recv بود، به یک تابعِ مشترک منتقل شد تا
    برایِ ویژگیِ «حذفِ دکمه از پستِ موجود» هم دوباره استفاده شود."""
    target_chat_id: int | str | None = None
    target_msg_id: int | None = None
    fwd_origin = getattr(msg, "forward_origin", None)
    if fwd_origin is not None and getattr(fwd_origin, "type", None) == "channel":
        target_chat_id = fwd_origin.chat.id
        target_msg_id = fwd_origin.message_id
    elif msg.forward_from_chat and msg.forward_from_chat.type == "channel":
        target_chat_id = msg.forward_from_chat.id
        target_msg_id = msg.forward_from_message_id
    else:
        raw = (msg.text or "").strip()
        m = _TME_MSG_LINK_RE.search(raw)
        if m:
            target_msg_id = int(m.group("mid"))
            if m.group("cid"):
                target_chat_id = int(f"-100{m.group('cid')}")
            elif m.group("uname"):
                target_chat_id = f"@{m.group('uname')}"

    if target_chat_id is None or target_msg_id is None:
        return None, None, "❌ این نه فورواردِ یک پستِ کانال بود، نه لینکِ معتبرِ پیام. یکی از پستِ کانال " \
            "برایم فوروارد کن یا لینکش را بفرست (مثلاً https://t.me/mychannel/123)، یا «❌ لغو» را بزن."
    try:
        chat = await bot.get_chat(target_chat_id)
    except (TelegramBadRequest, TelegramForbiddenError):
        return None, None, "❌ به این کانال دسترسی ندارم. مطمئن شو لینک/فوروارد درست است."
    if saved_chat_id and str(chat.id) != str(saved_chat_id):
        return None, None, ("❌ این پیام مالِ کانالِ دیگری است، نه همون کانالِ متصل‌شده به این بخش.\n"
                            "پیام را از همون کانالِ متصل فوروارد کن، یا اول از «✏️ تغییر کانال» کانال را عوض کن.")
    return chat.id, target_msg_id, None


@tenant_router.callback_query(F.data == "tadm:chpost:detach_start")
async def tadm_chpost_detach_start(cb: CallbackQuery, bot: Bot, state: FSMContext):
    """=== PATCH_CHPOST_DETACH_EXISTING_V1 ===
    شروعِ ویزاردِ «حذفِ دکمه از پستِ موجود» — عکسِ ویزاردِ attach: به‌جایِ
    چسباندن، کیبوردِ زیرِ پستِ فوروارد/لینک‌شده کاملاً برداشته می‌شود."""
    row = await _gate(cb, bot, Feature.CHANNEL_POST)
    if not row:
        return
    if not await get_setting(row.id, "chpost_chat_id", ""):
        await cb.answer("اول یک کانال وصل کن.", show_alert=True)
        return
    await state.set_state(ChannelPostFSM.wait_detach_target)
    try:
        await cb.message.edit_reply_markup(reply_markup=None)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.message.answer(
        "🗑 <b>حذفِ دکمه از پستِ موجود</b>\n\n"
        "همون پستی که دکمه زیرش چسبیده را برایم <b>فوروارد کن</b>، یا لینکِ پیام را "
        "بفرست (مثلاً <code>https://t.me/mychannel/123</code>).\n\n"
        "⚠️ باید همون کانالِ متصل‌شده باشد؛ متنِ پست دست‌نخورده می‌ماند، فقط همهٔ دکمه‌های "
        "زیرش برداشته می‌شود.",
        reply_markup=cancel_kb(),
    )
    await cb.answer()


@tenant_router.message(ChannelPostFSM.wait_detach_target)
async def tadm_chpost_detach_target_recv(msg: Message, state: FSMContext, bot: Bot):
    row = await get_bot_row(bot)
    if not row or not await is_owner_or_admin(row.id, msg.from_user.id, row.owner_id):
        await state.clear()
        return
    if (msg.text or "").strip() == "❌ لغو":
        await state.clear()
        await msg.answer("لغو شد.", reply_markup=await smart_cancel_kb(bot))
        txt, kb = await _chpost_menu(row.id)
        await msg.answer(txt, reply_markup=kb)
        return

    saved_chat_id = await get_setting(row.id, "chpost_chat_id", "")
    target_chat_id, target_msg_id, err = await _resolve_chpost_target(msg, bot, saved_chat_id)
    if err:
        await msg.answer(err)
        return

    try:
        await bot.edit_message_reply_markup(
            chat_id=target_chat_id, message_id=target_msg_id, reply_markup=None)
    except (TelegramBadRequest, TelegramForbiddenError) as e:
        await msg.answer(
            "❌ حذفِ دکمه ناموفق بود. احتمالاً ربات دیگر در آن کانال ادمین نیست، "
            "پیام دکمه‌ای نداشته، یا پیام حذف شده.\n"
            f"جزئیات: {e}")
        await state.clear()
        return
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        await msg.answer("❌ خطای غیرمنتظره‌ای پیش آمد.")
        await state.clear()
        return

    await state.clear()
    await msg.answer("✅ همهٔ دکمه‌های زیرِ همون پست در کانال برداشته شد؛ متنِ پست دست‌نخورده ماند.",
                     reply_markup=await smart_cancel_kb(bot))
    txt, kbm = await _chpost_menu(row.id)
    await msg.answer(txt, reply_markup=kbm)


async def _chpost_preview(msg_target: Message, state: FSMContext, bot_id: int, bot: Bot | None = None):
    """PATCH_CHPOST_FORMAT_BUTTONS_V1 — پیش‌نمایشِ عینِ چیزی که ارسال می‌شود؛ متنِ پست دیگر با متنِ راهنما
    قاطی/بریده نمی‌شود تا وسطِ یک تگِ HTML (بولد/لینک/ایموجیِ پرمیوم و...) قطع نشود.

    === PATCH_CHPOST_ATTACH_EXISTING_V1 ===
    اگر mode == 'attach' باشد (یعنی داریم فقط دکمه زیرِ پستی که خودِ ادمین قبلاً
    مستقیم در کانال گذاشته می‌چسبانیم)، پیش‌نمایشِ متن/عکس نشان داده نمی‌شود
    (چون چیزی برای ارسال ساخته نشده) و دکمهٔ نهایی «✅ ارسال به کانال» به
    «✅ چسباندنِ دکمه‌ها به همین پست» تغییر می‌کند.
    """
    data = await state.get_data()
    buttons = data.get("chpost_buttons") or []
    button_ids = data.get("chpost_button_ids") or []
    guide_keys = list(data.get("chpost_guide_keys") or [])  # PATCH_CHPOST_PICK_GUIDE_CHILDREN_V1
    mode = data.get("chpost_mode") or "new"
    kb = await _chpost_full_kb(bot_id, buttons, button_ids, bot=bot,
                               guide_keys=guide_keys)
    kb_rows = list(kb.inline_keyboard) if kb else []
    kb_rows.append([InlineKeyboardButton(text="➕ افزودن دکمهٔ لینک", callback_data="tadm:chpost:addbtn", style=ButtonStyle.SUCCESS)])
    if buttons:
        kb_rows.append([InlineKeyboardButton(text="🗑 حذف آخرین دکمهٔ لینک", callback_data="tadm:chpost:delbtn", style=ButtonStyle.DANGER)])
    kb_rows.append([InlineKeyboardButton(text="🔘 دکمه‌های ربات", callback_data="tadm:chpost:pickbtn", style=ButtonStyle.PRIMARY)])
    # === PATCH_CHPOST_PICK_GUIDE_CHILDREN_V2 ===
    # دکمهٔ مستقلِ چسباندنِ آموزش‌ها — فقط اگر ربات دکمهٔ «آموزش اتصال» داشته باشد.
    if await _has_vpn_help_button(bot_id):
        _ng = len(guide_keys)
        kb_rows.append([InlineKeyboardButton(
            text=("🧩 چسباندنِ دکمه‌هایِ آموزش" + (f" ({_ng})" if _ng else "")),
            callback_data="tadm:chpost:pickguide", style=ButtonStyle.PRIMARY)])
    # === PATCH_TENANT_CHPOST_CLEARBTN_V1 ===
    # قبلاً فقط می‌شد دکمه‌هایِ لینک رو یکی‌یکی (آخرین) حذف کرد و دکمه‌هایِ
    # انتخاب‌شدهٔ ربات (chpost_button_ids) اصلاً راهِ حذف نداشتن؛ اگه ادمین
    # می‌خواست پست رو کلاً بدونِ دکمه بفرسته باید تک‌تک می‌زد. حالا یک دکمهٔ
    # «حذف همهٔ دکمه‌ها» هست که هر دو نوع رو یک‌جا خالی می‌کنه.
    if buttons or button_ids:
        kb_rows.append([InlineKeyboardButton(text="🚫 حذف همهٔ دکمه‌ها از پست",
                                             callback_data="tadm:chpost:clearbtn",
                                             style=ButtonStyle.DANGER)])
    if mode == "attach":
        kb_rows.append([InlineKeyboardButton(text="✅ چسباندنِ دکمه‌ها به همین پست",
                                             callback_data="tadm:chpost:attach_apply", style=ButtonStyle.SUCCESS)])
    else:
        # === PATCH_TENANT_CHPOST_GROUP_V1 ===
        # باگ: اینجا قبلاً از «row.id» استفاده می‌شد، ولی row پارامترِ این تابع
        # نیست (فقط bot_id پاس داده می‌شه) → NameError: name 'row' is not
        # defined که با «خطایی پیش‌بینی‌نشده رخ داد» به کاربر نمایش داده می‌شد.
        _ch = await get_setting(bot_id, "chpost_chat_id", "")
        _gr = await get_setting(bot_id, "chpost_group_id", "")
        if _ch:
            kb_rows.append([InlineKeyboardButton(text="✅ ارسال به کانال",
                                                 callback_data="tadm:chpost:send",
                                                 style=ButtonStyle.SUCCESS)])
        if _gr:
            kb_rows.append([InlineKeyboardButton(text="👥 ارسال به گروه",
                                                 callback_data="tadm:chpost:send:gr",
                                                 style=ButtonStyle.SUCCESS)])
        if _ch and _gr:
            kb_rows.append([InlineKeyboardButton(text="📢👥 ارسال هم‌زمان به کانال و گروه",
                                                 callback_data="tadm:chpost:send:both",
                                                 style=ButtonStyle.PRIMARY)])
    kb_rows.append([InlineKeyboardButton(text="❌ انصراف", callback_data="tadm:chpost:cancel",
                                         style=ButtonStyle.DANGER)])
    preview_kb = InlineKeyboardMarkup(inline_keyboard=kb_rows)
    if mode == "attach":
        await msg_target.answer(
            "👀 <b>دکمه‌هایی که زیرِ پستِ موجود چسبانده می‌شود:</b>\n"
            "(متنِ خودِ پست دست‌نخورده می‌ماند؛ فقط همین دکمه‌ها زیرش اضافه می‌شود)",
            reply_markup=preview_kb)
        return
    photo = data.get("chpost_photo")
    text = data.get("chpost_text") or ""
    await msg_target.answer("👀 <b>پیش‌نمایش پست</b>\n\nاین همون چیزیه که توی کانال دیده می‌شه:")
    if photo:
        await msg_target.answer_photo(photo, caption=text or None)
    else:
        await msg_target.answer(text or "—")
    await msg_target.answer("👇 دکمه‌های پست:", reply_markup=preview_kb)


@tenant_router.message(ChannelPostFSM.wait_content)
async def tadm_chpost_content_recv(msg: Message, state: FSMContext, bot: Bot):
    row = await get_bot_row(bot)
    if not row or not await is_owner_or_admin(row.id, msg.from_user.id, row.owner_id):
        await state.clear()
        return
    if (msg.text or "").strip() == "❌ لغو":
        await state.clear()
        txt, kb = await _chpost_menu(row.id)
        await msg.answer("لغو شد.", reply_markup=await smart_cancel_kb(bot))
        await msg.answer(txt, reply_markup=kb)
        return
    if msg.checklist:
        await state.update_data(chpost_text=_checklist_to_text(msg.checklist), chpost_photo=None)
        await msg.answer(
            "ℹ️ تلگرام فعلاً اجازه نمی‌دهد بات‌های معمولی (غیرِ متصل به Business) چک‌لیستِ "
            "تعاملی به کانال بفرستند؛ این یک محدودیتِ خودِ تلگرامه، نه چیزی که از داخل ربات "
            "قابل دور زدن باشد. برای همین متنِ چک‌لیست را به یک پستِ متنیِ معمولی تبدیل کردم.")
    elif msg.photo:
        # PATCH_CHPOST_FORMAT_BUTTONS_V1 — msg.html_text خودش caption + caption_entities را با هم قالب‌بندی می‌کند
        # (بولد/ایتالیک/لینک/اسپویلر/ایموجیِ پرمیوم و بقیهٔ قالب‌بندی‌های تلگرام).
        plain_len = len(msg.caption or "")
        if plain_len > 1024:
            await msg.answer(
                f"❌ کپشنِ عکس {plain_len} کاراکتره؛ تلگرام حداکثر ۱۰۲۴ کاراکتر برای کپشنِ عکس "
                "اجازه می‌ده. کوتاه‌ترش کن و دوباره بفرست:")
            return
        await state.update_data(chpost_photo=msg.photo[-1].file_id, chpost_text=msg.html_text)
    elif msg.text:
        plain_len = len(msg.text or "")
        if plain_len > 4096:
            await msg.answer(
                f"❌ متنِ پست {plain_len} کاراکتره؛ تلگرام حداکثر ۴۰۹۶ کاراکتر برای یک پیامِ متنی "
                "اجازه می‌ده. کوتاه‌ترش کن و دوباره بفرست:")
            return
        await state.update_data(chpost_text=msg.html_text, chpost_photo=None)
    else:
        await msg.answer(
            "فقط متن، عکس یا چک‌لیستِ تلگرام پشتیبانی می‌شود (ویدیو/فایل/صدا هنوز نه). "
            "دوباره بفرست:")
        return
    await msg.answer("👌 گرفتم.", reply_markup=await smart_cancel_kb(bot))
    await _chpost_preview(msg, state, row.id, bot=bot)


