@tenant_router.message(ChannelPostFSM.wait_btn_label)
async def tadm_chpost_btn_label_recv(msg: Message, state: FSMContext, bot: Bot):
    row = await get_bot_row(bot)
    if not row or not await is_owner_or_admin(row.id, msg.from_user.id, row.owner_id):
        await state.clear()
        return
    _data0 = await state.get_data()
    _idle_state = (ChannelPostFSM.wait_attach_idle if _data0.get("chpost_mode") == "attach"
                   else ChannelPostFSM.wait_content)
    if (msg.text or "").strip() == "❌ لغو":
        await state.set_state(_idle_state)
        await msg.answer("لغو شد.", reply_markup=await smart_cancel_kb(bot))
        await _chpost_preview(msg, state, row.id, bot=bot)
        return
    label = (msg.text or "").strip()[:64]
    if not label:
        await msg.answer("متنِ دکمه نمی‌تواند خالی باشد. دوباره بفرست:")
        return
    await state.update_data(chpost_btn_label=label)
    await state.set_state(ChannelPostFSM.wait_btn_url)
    await msg.answer("🔗 حالا لینکِ دکمه را بفرست (باید با http:// یا https:// شروع شود):")


@tenant_router.message(ChannelPostFSM.wait_btn_url)
async def tadm_chpost_btn_url_recv(msg: Message, state: FSMContext, bot: Bot):
    row = await get_bot_row(bot)
    if not row or not await is_owner_or_admin(row.id, msg.from_user.id, row.owner_id):
        await state.clear()
        return
    _data0 = await state.get_data()
    _idle_state = (ChannelPostFSM.wait_attach_idle if _data0.get("chpost_mode") == "attach"
                   else ChannelPostFSM.wait_content)
    if (msg.text or "").strip() == "❌ لغو":
        await state.set_state(_idle_state)
        await msg.answer("لغو شد.", reply_markup=await smart_cancel_kb(bot))
        await _chpost_preview(msg, state, row.id, bot=bot)
        return
    url = (msg.text or "").strip()
    if not (url.startswith("http://") or url.startswith("https://")):
        await msg.answer("❌ لینک باید با http:// یا https:// شروع شود. دوباره بفرست:")
        return
    data = await state.get_data()
    buttons = list(data.get("chpost_buttons") or [])
    buttons.append([data.get("chpost_btn_label") or "لینک", url])
    await state.update_data(chpost_buttons=buttons, chpost_btn_label=None)
    await state.set_state(_idle_state)
    await msg.answer("✅ دکمه اضافه شد.", reply_markup=await smart_cancel_kb(bot))
    await _chpost_preview(msg, state, row.id, bot=bot)


