# === PATCH_TENANT_CHPOST_GROUP_V1 ===
@tenant_router.callback_query(F.data.in_({"tadm:chpost:send", "tadm:chpost:send:gr",
                                          "tadm:chpost:send:both"}))
async def tadm_chpost_send(cb: CallbackQuery, bot: Bot, state: FSMContext):
    row = await _gate(cb, bot, Feature.CHANNEL_POST)
    if not row:
        return
    _mode = cb.data.split(":")[3] if cb.data.count(":") > 2 else "ch"
    _ch = await get_setting(row.id, "chpost_chat_id", "")
    _gr = await get_setting(row.id, "chpost_group_id", "")
    targets = []
    if _mode in ("ch", "both") and _ch:
        targets.append((_ch, "کانال"))
    if _mode in ("gr", "both") and _gr:
        targets.append((_gr, "گروه"))
    if not targets:
        await cb.answer("مقصدی وصل نیست.", show_alert=True)
        await state.clear()
        return
    data = await state.get_data()
    text = data.get("chpost_text") or ""
    photo = data.get("chpost_photo")
    buttons = data.get("chpost_buttons") or []
    button_ids = data.get("chpost_button_ids") or []
    guide_keys = list(data.get("chpost_guide_keys") or [])  # PATCH_CHPOST_PICK_GUIDE_CHILDREN_V1
    kb = await _chpost_full_kb(row.id, buttons, button_ids, bot=bot,
                               guide_keys=guide_keys)
    if not photo and not text.strip():
        await cb.answer("متن پست خالی است.", show_alert=True)
        return
    # به همهٔ مقصدهای انتخاب‌شده می‌فرسته؛ شکستِ یکی بقیه رو متوقف نمی‌کنه.
    ok_list, fail_list = [], []
    for _cid, _word in targets:
        try:
            if photo:
                await bot.send_photo(_cid, photo, caption=text or None, reply_markup=kb)
            else:
                await bot.send_message(_cid, text, reply_markup=kb)
            ok_list.append(_word)
        except (TelegramBadRequest, TelegramForbiddenError) as e:
            fail_list.append(f"{_word} ({e})")
        except Exception as e:
            logger.exception("tenant chpost send failed for %s", _word)
            fail_list.append(f"{_word} ({e})")
    await state.clear()
    lines = []
    if ok_list:
        lines.append("✅ پست با موفقیت ارسال شد به: " + "، ".join(ok_list))
    for f in fail_list:
        lines.append(f"❌ ارسال ناموفق به {f}")
    if fail_list:
        lines.append("\nمعمولاً یعنی ربات دیگه اونجا ادمین نیست.")
    await cb.message.answer("\n".join(lines), reply_markup=await smart_cancel_kb(bot))
    txt, kbm = await _chpost_menu(row.id)
    await cb.message.answer(txt, reply_markup=kbm)
    await cb.answer()


