@tenant_router.message(Command("panel"))
async def tenant_web_panel_login(msg: Message, bot: Bot):
    """لینکِ ورودِ یک‌بارمصرف به پنلِ تحت وب را برایِ مالک/ادمین می‌فرستد."""
    row = await get_bot_row(bot)
    if not row:
        return
    if not await is_owner_or_admin(row.id, msg.from_user.id, row.owner_id):
        return
    if not has_feature(row.plan, Feature.WEB_PANEL):
        await msg.answer(
            "🖥 <b>پنل مدیریت تحت وب</b>\n\n"
            "این قابلیت فقط در پلنِ <b>حرفه‌ای</b> فعال است.")
        return
    from tenant.shared.web_panel import create_login_link
    link = await create_login_link(row.id, msg.from_user.id)
    if not link:
        await msg.answer("❌ آدرسِ وب برایِ این سرور تنظیم نشده. با پشتیبانی تماس بگیر.")
        return
    await msg.answer(
        "🖥 <b>ورود به پنل تحت وب</b>\n\n"
        "این لینک <b>۵ دقیقه</b> اعتبار دارد و فقط <b>یک‌بار</b> کار می‌کند.\n"
        "بعد از ورود، تا ۱۲ ساعت وارد می‌مانی.\n\n"
        "⚠️ این لینک را برای هیچ‌کس نفرست — هرکسی بازش کند وارد پنلِ تو می‌شود.",
        reply_markup=InlineKeyboardMarkup(inline_keyboard=[[
            # === PATCH_PANEL_MINIAPP_V1 ===
            # با WebApp، پنل داخلِ خودِ تلگرام باز می‌شود و آدرس در چت
            # نوشته نمی‌شود. اگر تلگرامِ کاربر قدیمی باشد و WebApp نگیرد،
            # همان دکمهٔ لینکِ قبلی فرستاده می‌شود.
            InlineKeyboardButton(text="🖥 بازکردنِ پنل",
                                 web_app=WebAppInfo(url=link))]]))


@tenant_router.callback_query(F.data == "emojitest:start")
async def tenant_emojitest_btn(cb: CallbackQuery, bot: Bot, state: FSMContext):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    await state.set_state(EmojiTestFSM.wait)
    try:
        await cb.message.edit_reply_markup(reply_markup=None)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.message.answer(
        "🧪 <b>تست دکمهٔ ایموجی پرمیوم</b>\n\n"
        "حالا یک <b>ایموجی پرمیوم</b> بفرست تا روی یک دکمهٔ تستی نمایشش بدهم و بررسی کنم "
        "رباتت می‌تواند آن را نشان دهد یا نه.",
        reply_markup=await smart_cancel_kb(bot))
    await cb.answer()


@tenant_router.message(Command("emojitest"))
async def tenant_emojitest(msg: Message, bot: Bot, state: FSMContext):
    """ابزار تشخیص: بررسی اینکه آیا این ربات می‌تواند ایموجی پرمیوم نمایش دهد.

    استفاده: ادمین یک ایموجی پرمیوم را همراه /emojitest یا در پاسخ بعدی بفرستد.
    ربات سعی می‌کند آن را هم در یک پیام، هم روی یک دکمهٔ تستی نمایش دهد و اگر
    تلگرام رد کرد، علت دقیق را نشان می‌دهد.
    """
    row = await get_bot_row(bot)
    if not row or not await is_owner_or_admin(row.id, msg.from_user.id, row.owner_id):
        return
    # شناسهٔ ایموجی پرمیوم را از همین پیام استخراج کن
    emoji_id = None
    for ent in (msg.entities or []):
        if ent.type == "custom_emoji" and getattr(ent, "custom_emoji_id", None):
            emoji_id = ent.custom_emoji_id
            break
    if not emoji_id:
        await state.set_state(EmojiTestFSM.wait)
        await msg.answer(
            "🧪 <b>تست ایموجی پرمیوم</b>\n\n"
            "حالا یک <b>ایموجی پرمیوم</b> بفرست تا بررسی کنم رباتت می‌تواند آن را "
            "نمایش دهد یا نه.",
            reply_markup=await smart_cancel_kb(bot))
        return
    await _run_emoji_test(msg, bot, emoji_id)


@tenant_router.message(EmojiTestFSM.wait)
async def tenant_emojitest_recv(msg: Message, bot: Bot, state: FSMContext):
    await state.clear()
    emoji_id = None
    for ent in (msg.entities or []):
        if ent.type == "custom_emoji" and getattr(ent, "custom_emoji_id", None):
            emoji_id = ent.custom_emoji_id
            break
    if not emoji_id:
        await msg.answer("❌ ایموجی پرمیوم پیدا نشد. (ایموجی معمولی فرستادی؟) دوباره /emojitest را بزن.")
        return
    await _run_emoji_test(msg, bot, emoji_id)


async def _run_emoji_test(msg: Message, bot: Bot, emoji_id: str):
    results = []
    # تست ۱: ایموجی پرمیوم داخل متنِ پیام
    try:
        await bot.send_message(
            msg.chat.id,
            f'تست متن: <tg-emoji emoji-id="{emoji_id}">🎁</tg-emoji>',
        )
        results.append("✅ متن پیام: ارسال شد (اگر ایموجی را رنگی/متحرک می‌بینی یعنی ربات پرمیوم دارد).")
    except Exception as e:
        results.append(f"❌ متن پیام رد شد: {type(e).__name__}: {str(e)[:120]}")
    # تست ۲: ایموجی پرمیوم روی دکمهٔ شیشه‌ای
    try:
        kb = InlineKeyboardMarkup(inline_keyboard=[[
            InlineKeyboardButton(text="دکمه ایموجی پرمیوم", callback_data="noop",
                                 icon_custom_emoji_id=emoji_id)
        ]])
        await bot.send_message(msg.chat.id, "تست دکمه:", reply_markup=kb)
        results.append("✅ دکمهٔ شیشه‌ای: ارسال شد (اگر ایموجی کنار متنِ دکمه است یعنی کامل کار می‌کند).")
    except Exception as e:
        results.append(f"❌ دکمهٔ شیشه‌ای رد شد: {type(e).__name__}: {str(e)[:120]}")
    await msg.answer(
        "🧪 <b>نتیجهٔ تست ایموجی پرمیوم</b>\n\n" + "\n\n".join(results) +
        "\n\n📌 اگر ارسال شد ولی ایموجی را نمی‌بینی، مشکل از <b>نسخهٔ اپ تلگرامِ توست</b> "
        "(باید آپدیت باشد) یا اینکه <b>حسابِ سازندهٔ ربات در BotFather پرمیوم ندارد</b>."
    )


@tenant_router.callback_query(F.data == "tadm:home")
async def tadm_home(cb: CallbackQuery, bot: Bot, state: FSMContext):
    """بازگشت به خانه از پنل مدیریت."""
    row = await get_bot_row(bot)
    if not row:
        await cb.answer()
        return
    await cb.answer()
    try:
        await state.clear()
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    if await get_setting(row.id, "menu_mode", "reply") == "inline":
        ikb = await main_inline_kb(row.id, row.owner_id, cb.from_user.id)
        await send_home_menu(cb, row.id, ikb, prefer_edit=True)
    else:
        try:
            await cb.message.delete()
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        kb = await main_kb_or_remove(row.id, row.owner_id, cb.from_user.id)
        await send_home_menu(cb, row.id, kb or ReplyKeyboardRemove())


@tenant_router.callback_query(F.data == "tadm:menu")
async def tadm_menu(cb: CallbackQuery, bot: Bot):
    row    = await get_bot_row(bot)
    field  = row.field if row else "vpn_sales"
    plan   = row.plan  if row else "free"
    # === PATCH_PARTNER_V8 ===
    # رباتِ همکار متنِ پنلِ خودش را دارد. بدونِ این، کیبوردِ همکار زیرِ
    # متنِ منویِ عمومی می‌نشست و مثلِ «برگشت به منویِ قدیمی» به‌نظر
    # می‌رسید — همان چیزی که در همهٔ دکمه‌هایِ بازگشت دیده می‌شد.
    if plan == "partner":
        from tenant.partner_bot.partner_menu import partner_home_text
        _txt = await partner_home_text(row.id)
    else:
        _txt = "🛠 <b>پنل مدیریت ربات</b>\n\nیک بخش انتخاب کن:"
    # === PATCH_ADMIN_NAV_SEND_DELETE_V1 ===
    await _sec_nav(cb, _txt, await tadmin_kb(row.id, field, plan, True))
    await cb.answer()


