async def _vs_prices_content(bot_id: int) -> tuple[str, InlineKeyboardMarkup]:
    """متن و کیبوردِ «تنظیم قیمت سرویس‌های مجازی» — مشترک بینِ نسخهٔ شیشه‌ای
    (callback) و نسخهٔ کیبوردی (reply)."""
    _vs_services = [
        ("vs_member",   "👥 افزایش ممبر کانال/گروه تلگرام"),
        ("vs_reaction", "❤️ افزایش ری‌اکشن پست تلگرام"),
        ("vs_view",     "👁 افزایش ویو پست تلگرام"),
        ("vs_like",     "👍 افزایش لایک تلگرام"),
        ("vs_vote",     "📊 افزایش رأی نظرسنجی تلگرام"),
        ("vs_comment",  "💬 افزایش کامنت تلگرام"),
    ]
    lines = ["💰 <b>قیمت سرویس‌های مجازی</b>\n",
             "برای تغییر قیمت هر سرویس روی آن بزنید:\n"]
    kb_rows = []
    for key, title in _vs_services:
        price = await get_setting(bot_id, f"vs_price_{key}", "0")
        price_txt = f"{int(price):,} تومان" if price and price != "0" else "تنظیم نشده"
        lines.append(f"• {title}: <b>{price_txt}</b>")
        kb_rows.append([InlineKeyboardButton(
            text=f"✏️ {title}",
            callback_data=f"tadm:vs_setprice:{key}", style=ButtonStyle.PRIMARY)])
    kb_rows.append([InlineKeyboardButton(text="⬅️ بازگشت", callback_data="tadm:sec:products", style=ButtonStyle.DANGER)])
    return "\n".join(lines), InlineKeyboardMarkup(inline_keyboard=kb_rows)


