class _FakeCbMessage:
    """جایگزینِ سبکِ cb.message وقتی از رویِ یک Message معمولی (نه CallbackQuery)
    یک صفحهٔ مدیریتیِ اینلاین را باز می‌کنیم (حالتِ کیبورد). به‌جای edit، همیشه
    پیامِ جدید می‌فرستد — کاملاً امن، چه هندلر try/except برای edit داشته باشد
    چه نه."""
    _is_fake = True

    def __init__(self, real_msg: Message):
        self._real = real_msg
        self.caption = None
        self.text = None
        self.photo = None
        self.document = None
        # فیلدهایِ فقط‌خواندنیِ پیامِ واقعی — خیلی از هندلرهایِ اینلاین
        # cb.message.chat.id / message_id را می‌خوانند و قبلاً با
        # AttributeError می‌ترکیدند.
        self.chat = real_msg.chat
        self.message_id = real_msg.message_id
        self.from_user = real_msg.from_user
        self.message_thread_id = getattr(real_msg, "message_thread_id", None)
        self.reply_markup = None

    async def edit_text(self, *a, **kw):
        return await self._real.answer(*a, **kw)

    async def edit_caption(self, *a, **kw):
        kw.pop("caption", None)
        return await self._real.answer(*a, **kw)

    async def edit_reply_markup(self, *a, **kw):
        return None

    async def answer(self, *a, **kw):
        return await self._real.answer(*a, **kw)

    async def delete(self):
        return None

    # === PATCH_CHPOST_CHANNEL_BTN_DEEPLINK_FIX_V1 ===
    # mbtn_tap (و بعضی هندلرهای دیگر) رویِ cb.message از model_copy/as_
    # استفاده می‌کنن (مالِ pydantic/aiogram Message واقعی) تا یک نسخهٔ
    # «مقیدشده به بات» بسازن. چون این کلاس پیامِ واقعی رو wrap می‌کنه، این دو
    # متد رو مستقیم به خودِ پیامِ واقعی پاس می‌دیم — وگرنه با AttributeError
    # کرش می‌کرد (دقیقاً همون چیزی که با ERR-201741 گزارش شد).
    def model_copy(self, *a, **kw):
        return self._real.model_copy(*a, **kw)

    def as_(self, bot):
        return self._real.as_(bot)


class _FakeCb:
    """جایگزینِ سبکِ CallbackQuery برای استفادهٔ دوباره از هندلرهای اینلاینِ
    موجود، وقتی کاربر (در حالتِ کیبورد) با تپ روی یک دکمهٔ کیبوردی وارد یک
    صفحهٔ مدیریتیِ عمیق می‌شود. این‌طوری منطقِ هر صفحه فقط یک‌بار (در هندلرِ
    اینلاینِ خودش) نوشته می‌شود و اینجا فقط صدا زده می‌شود — بدون تکرار کد."""
    def __init__(self, msg: Message, data: str = ""):
        self.from_user = msg.from_user
        self.message = _FakeCbMessage(msg)
        self.data = data
        self.bot = getattr(msg, "bot", None)

    async def answer(self, *a, **kw):
        return None


async def _owner_ok(cb: CallbackQuery, bot: Bot) -> BotRow | None:
    row = await get_bot_row(bot)
    if not row:
        await cb.answer()
        return None
    if not await is_owner_or_admin(row.id, cb.from_user.id, row.owner_id):
        await cb.answer()
        return None
    return row


async def _owner_ok_msg(msg: Message, bot: Bot) -> "BotRow | None":
    """همان _owner_ok اما برای message handler ها."""
    row = await get_bot_row(bot)
    if not row:
        return None
    if not await is_owner_or_admin(row.id, msg.from_user.id, row.owner_id):
        return None
    return row


