_TN_ANTISPAM_PAGE_SIZE = 15


async def _tn_antispam_kb(bot_id: int, plan: str = "") -> InlineKeyboardMarkup:
    on = (await get_setting(bot_id, "antispam_enabled", "on")) == "on"
    _thr, _mode, _mins = await _antispam_cfg(bot_id)   # PATCH_ANTISPAM_TEMP_LOCK_V1
    phone_on = (await get_setting(bot_id, "phone_verify_enabled", "off")) == "on"  # === PATCH_PHONE_VERIFY_V1 ===
    async with Session() as s:
        banned_count = await s.scalar(
            select(func.count()).select_from(BotUser)
            .where(BotUser.bot_id == bot_id, BotUser.is_banned == True)) or 0
    # === PATCH_PARTNER_SETTINGS_BACK_FIX_V1 ===
    # این صفحه هم از «دکمه‌ها و تنظیمات» (tadm:sec:settings — مستأجرها)
    # و هم از «تنظیمات عمومی ربات» (set:hub_general — فقط همکار) باز
    # می‌شود. برایِ همکار، tadm:sec:settings اصلاً در فهرستِ سفیدِ
    # partner_menu.py نیست، پس دکمهٔ بازگشتِ قدیمی کاربر را یک‌راست به
    # خانهٔ پنلِ همکار پرت می‌کرد، نه یک قدم عقب.
    _back_cb = "set:hub_general" if plan == "partner" else "tadm:sec:settings"
    return InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(
            text=("🟢 آنتی‌اسپم: روشن" if on else "🔴 آنتی‌اسپم: خاموش"),
            callback_data="set:toggle_antispam",
            style=(ButtonStyle.SUCCESS if on else ButtonStyle.DANGER))],
        # === PATCH_PHONE_VERIFY_V1 ===
        [InlineKeyboardButton(
            text=("🟢 تاییدِ شماره‌همراه: روشن" if phone_on else "🔴 تاییدِ شماره‌همراه: خاموش"),
            callback_data="set:toggle_phoneverify",
            style=(ButtonStyle.SUCCESS if phone_on else ButtonStyle.DANGER))],
        # === PATCH_ANTISPAM_TEMP_LOCK_V1 ===
        [InlineKeyboardButton(
            text=("⏳ حالت: قفلِ موقت (بدونِ بن) — زدن = بنِ دائمی" if _mode == "temp"
                  else "🚫 حالت: بنِ دائمی — زدن = قفلِ موقت"),
            callback_data="set:as_mode")],
        [InlineKeyboardButton(text=f"📨 آستانه: {_thr} پیام (زدن = تغییر)", callback_data="set:as_thr"),
         InlineKeyboardButton(text=f"⏱ مدتِ قفل: {_mins} دقیقه (زدن = تغییر)", callback_data="set:as_min")],
        # === PATCH_PAY_PHONE_VERIFY_V1 ===  # به «💰 مالی و کیف پول» منتقل شد
        [InlineKeyboardButton(text=f"🚫 نفرات بن‌شده ({banned_count})", callback_data="tas:banlist:0")],
        [InlineKeyboardButton(text="⬅️ بازگشت", callback_data=_back_cb, style=ButtonStyle.DANGER)],
    ])


async def _tn_antispam_text(bot_id: int) -> str:
    thr, mode, mins = await _antispam_cfg(bot_id)
    after = (f"• بار {_TN_ANTISPAM_MAX_WARNINGS + 1} دسترسی‌اش <b>{mins} دقیقه</b> محدود می‌شود و بعد خودکار پس می‌گیرد "
             "(بن نمی‌شود)\n\n"
             if mode == "temp" else
             f"• بار {_TN_ANTISPAM_MAX_WARNINGS + 1} به‌طور خودکار از همین ربات بن می‌شود\n\n"
             "کاربرِ بن‌شده هیچ پاسخی از این ربات نمی‌بیند تا وقتی آنبن شود.\n\n")
    return (
        "🛡 <b>آنتی‌اسپم</b>\n\n"
        f"اگر کسی {thr} پیام پشت‌سرهم (در کمتر از {_TN_ANTISPAM_WINDOW_SECONDS} ثانیه) "
        "به این ربات بفرستد:\n"
        f"• بار ۱ و ۲ فقط اخطار می‌گیرد\n"
        + after +
        "📱 <b>تاییدِ شماره‌همراه</b> (ضدِ رفرالِ فیک): اگه روشن باشه، هر کاربرِ "
        "جدید بعدِ عضویتِ اجباری و /start، مجبوره شماره‌شو با دکمهٔ تلگرام "
        "تایید کنه (فقط شماره‌هایِ ایران، +98) تا بتونه از ربات استفاده کنه."
    )


