# === PATCH_ANTISPAM_TEMP_LOCK_V1 ===
@tenant_router.callback_query(F.data.in_({"set:as_mode", "set:as_thr", "set:as_min"}))
async def tn_antispam_cfg_cycle(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    thr, mode, mins = await _antispam_cfg(row.id)
    what = cb.data
    if what == "set:as_mode":
        await set_setting(row.id, "antispam_mode", "ban" if mode == "temp" else "temp")
        note = "🚫 حالتِ بنِ دائمی" if mode == "temp" else "⏳ حالتِ قفلِ موقت (بدونِ بن)"
    elif what == "set:as_thr":
        nxt = _ANTISPAM_THRESHOLDS[(_ANTISPAM_THRESHOLDS.index(thr) + 1) % len(_ANTISPAM_THRESHOLDS)] \
            if thr in _ANTISPAM_THRESHOLDS else _TN_ANTISPAM_MSG_THRESHOLD
        await set_setting(row.id, "antispam_threshold", str(nxt))
        note = f"آستانه: {nxt} پیام"
    else:
        nxt = _ANTISPAM_LOCK_MINUTES[(_ANTISPAM_LOCK_MINUTES.index(mins) + 1) % len(_ANTISPAM_LOCK_MINUTES)] \
            if mins in _ANTISPAM_LOCK_MINUTES else 15
        await set_setting(row.id, "antispam_lock_min", str(nxt))
        note = f"مدتِ قفل: {nxt} دقیقه"
    try:
        await cb.message.edit_text(await _tn_antispam_text(row.id),
                                   reply_markup=await _tn_antispam_kb(row.id, row.plan))
    except Exception:
        logger.debug("به‌روزرسانیِ صفحهٔ آنتی‌اسپم ممکن نشد (بی‌اهمیت)")
    await cb.answer("✅ " + note)


