async def _tn_render_banlist(cb: CallbackQuery, bot_id: int, offset: int):
    async with Session() as s:
        total = await s.scalar(
            select(func.count()).select_from(BotUser)
            .where(BotUser.bot_id == bot_id, BotUser.is_banned == True)) or 0
        rows = (await s.scalars(
            select(BotUser).where(BotUser.bot_id == bot_id, BotUser.is_banned == True)
            .order_by(BotUser.id).offset(offset).limit(_TN_ANTISPAM_PAGE_SIZE))).all()

    if not rows:
        text = "🚫 <b>نفراتِ بن‌شدهٔ این ربات</b>\n\nهیچ کاربرِ بن‌شده‌ای وجود ندارد. ✅"
    else:
        lines = [f"🚫 <b>نفراتِ بن‌شدهٔ این ربات</b> ({total} نفر)\n"]
        for u in rows:
            uname = f"@{u.username}" if u.username else "—"
            lines.append(f"• <code>{u.telegram_id}</code> — {u.full_name or '—'} ({uname}) "
                        f"[اخطار: {u.spam_warnings or 0}]")
        text = "\n".join(lines)

    btn_rows = [[InlineKeyboardButton(text=f"✅ آنبن {u.telegram_id}",
                                      callback_data=f"tas:unban:{u.telegram_id}:{offset}")]
                for u in rows]
    nav_row = []
    if offset > 0:
        nav_row.append(InlineKeyboardButton(text="⬅️ قبلی",
                                            callback_data=f"tas:banlist:{max(0, offset - _TN_ANTISPAM_PAGE_SIZE)}"))
    if offset + _TN_ANTISPAM_PAGE_SIZE < total:
        nav_row.append(InlineKeyboardButton(text="بعدی ➡️",
                                            callback_data=f"tas:banlist:{offset + _TN_ANTISPAM_PAGE_SIZE}"))
    if nav_row:
        btn_rows.append(nav_row)
    btn_rows.append([InlineKeyboardButton(text="⬅️ بازگشت", callback_data="set:antispam", style=ButtonStyle.DANGER)])

    try:
        await cb.message.edit_text(text, reply_markup=InlineKeyboardMarkup(inline_keyboard=btn_rows))
    except Exception:
        await cb.message.answer(text, reply_markup=InlineKeyboardMarkup(inline_keyboard=btn_rows))


@tenant_router.callback_query(F.data.startswith("tas:banlist:"))
async def tn_antispam_banlist(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    offset = int(cb.data.split(":")[2])
    await _tn_render_banlist(cb, row.id, offset)
    await cb.answer()


@tenant_router.callback_query(F.data.startswith("tas:unban:"))
async def tn_antispam_unban(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    parts = cb.data.split(":")
    target_tg = int(parts[2])
    offset = int(parts[3]) if len(parts) > 3 else 0
    async with Session() as s:
        u = await s.scalar(select(BotUser).where(BotUser.bot_id == row.id, BotUser.telegram_id == target_tg))
        if u:
            u.is_banned = False
            u.spam_warnings = 0
            await s.commit()
    await cb.answer("✅ آنبن شد")
    await _tn_render_banlist(cb, row.id, offset)


# ───── PATCH_TENANT_GENERAL_HUB_V1 / PATCH_GENERAL_HUB_RETURN_V1 ─────
# پیامِ خوش‌آمد، معرفیِ پشتیبانی، عضویتِ اجباری و آنتی‌اسپم را یکجا نشان
# می‌دهد — با ارجاع به هندلرهایِ موجودِ set:welcome / tadm:forcejoin /
# set:antispam (بدونِ کپی/دوباره‌نویسیِ منطقِ آن‌ها). فقط «معرفیِ
# پشتیبانی» (set:support) این‌جا تازه ساخته می‌شود چون قبلاً اصلاً
# دکمه/فرمی برایِ ثبتِ support_contact وجود نداشت.
async def _tn_general_hub_kb(bot_id: int, plan: str = "free") -> InlineKeyboardMarkup:
    """=== PATCH_GENERAL_HUB_NOTIFY_TRUST_STATS_V2 ===
    نسخهٔ V1 باگ داشت: تاگل‌هایِ purchase_notify/new_user_notify از
    هندلرهایِ tadm:pnotify_toggle / tadm:newuser_notify_toggle استفاده
    می‌کردن که بعدِ زدن، پیام رو با reply_markup=_sec_stats_kb («آمار و
    گزارشات») رفرش می‌کردن — یعنی کاربر از وسطِ «تنظیمات عمومی ربات»
    ناخواسته می‌پرید به یه منویِ دیگه. الان این دو تاگل، هندلرِ اختصاصیِ
    خودشون رو دارن (ghub:pnotify_toggle / ghub:newuser_notify_toggle)
    که بعدِ عوض‌کردنِ تنظیم، همینجا (هابِ عمومی) رو رفرش می‌کنن، نه
    منویِ دیگه‌ای رو. کانال اعتمادسازی و آمار کلی ربات مشکلی نداشتن
    (رفتنِ روشون یه ناوبریِ روبه‌جلوی طبیعیه، نه یه رفرشِ اشتباه) و
    هندلرِ اصلیِ خودشون (tadm:trustreport / tadm:stats) رو دارن."""
    def ok(f): return has_feature(plan, f)
    antispam_on = (await get_setting(bot_id, "antispam_enabled", "on")) == "on"
    purchase_notify_v = await get_setting(bot_id, "purchase_notify", "1")
    new_user_notify_v = await get_setting(bot_id, "new_user_notify", "0")
    # === PATCH_SETTINGS_REGISTRY_V6_HOME_HUB ===
    # ردیف‌هایِ اختصاصیِ هر نوع (فعلاً «تیترِ صفحه‌ها» برایِ VPN) از رجیستری (بخشِ "hub").
    from tenant.settings_registry import visible_items as _rv_hub, section_key as _sk_hub
    async with Session() as _hs:
        _hbrow = await _hs.get(BotRow, bot_id)
    _vpn_title_rows = ([[InlineKeyboardButton(
                            text=_it.label, callback_data=_it.callback,
                            style=(getattr(ButtonStyle, _it.style.upper()) if _it.style else None))]
                        for _it in _rv_hub(_sk_hub("hub", _hbrow.field), plan)]
                       if _hbrow is not None else [])
    rows = [
        [InlineKeyboardButton(text="✏️ ویرایش پیام خوش‌آمد", callback_data="set:welcome", style=ButtonStyle.PRIMARY)],
        [InlineKeyboardButton(text="💬 معرفی پشتیبانی", callback_data="set:support", style=ButtonStyle.PRIMARY)],
        [InlineKeyboardButton(text="👤 متنِ اختصاصیِ «مشخصاتِ شما»", callback_data="set:profile_footer", style=ButtonStyle.PRIMARY)],
        *_vpn_title_rows,
        # === PATCH_TEXT_VARS_V1 === لیستِ کاملِ متغیرها (برایِ همهٔ انواعِ ربات)
        [InlineKeyboardButton(text="🔤 لیستِ متغیرهایِ متن‌ها", callback_data="tvars:list",
                              style=ButtonStyle.PRIMARY)],
        [InlineKeyboardButton(text="📢 عضویت اجباری در کانال", callback_data="tadm:forcejoin", style=ButtonStyle.PRIMARY)],
        [InlineKeyboardButton(
            text=("🟢 آنتی‌اسپم: روشن" if antispam_on else "🔴 آنتی‌اسپم: خاموش"),
            callback_data="set:antispam",
            style=(ButtonStyle.SUCCESS if antispam_on else ButtonStyle.DANGER))],
        [InlineKeyboardButton(
            text="🔔 اطلاع خودکار خرید: " + ("✅ فعال" if purchase_notify_v == "1" else "❌ غیرفعال"),
            callback_data="ghub:pnotify_toggle")],
        [InlineKeyboardButton(
            text="👤 اطلاع ورود کاربر جدید: " + ("✅ فعال" if new_user_notify_v == "1" else "❌ غیرفعال"),
            callback_data="ghub:newuser_notify_toggle")],
        [InlineKeyboardButton(text="🎖 کانال اعتمادسازی", callback_data="tadm:trustreport", style=ButtonStyle.PRIMARY)],
        # === PATCH_PARTNER_HUB_GIFT_DICE_V1 ===
        [InlineKeyboardButton(text="🎁 مبلغ هدیه دعوت (تومان)", callback_data="set:ref_reward", style=ButtonStyle.PRIMARY)],
        # === PATCH_PARTNER_DISCOUNT_V1 ===
        # پنلِ کاملِ کدهای تخفیف از قبل وجود داشت (tadm:discounts) ولی برایِ
        # همکار از هیچ مسیری در دسترس نبود؛ فقط ورودی‌اش اینجا اضافه شد.
        [InlineKeyboardButton(text="🏷 کدهای تخفیف", callback_data="tadm:discounts", style=ButtonStyle.PRIMARY)],
        [InlineKeyboardButton(text="🎲 بازی کن و جایزه بگیر", callback_data="dga:menu", style=ButtonStyle.PRIMARY)],
    ]
    # === PATCH_PARTNER_STATS_MOVE_V1 ===
    # برایِ ربات‌هایِ همکار، دکمهٔ آمار از این هاب برداشته شد؛ حالا با نامِ
    # «آمار و گزارشات» مستقیم در پنلِ مدیریتِ همکار (tenant/partner_menu.py)
    # است، چون همکارها معمولاً این را زودتر و پرتکرارتر لازم دارند.
    if ok(Feature.BOT_STATS) and plan != "partner":
        rows.append([InlineKeyboardButton(text="📊 آمار کلی ربات", callback_data="tadm:stats", style=ButtonStyle.PRIMARY)])
    # === PATCH_PARTNER_SETTINGS_BACK_FIX_V1 ===
    # این هاب برایِ رباتِ همکار یک آیتمِ سطحِ‌بالایِ خانهٔ پنل است (نه
    # زیرِ «دکمه‌ها و تنظیمات»)، پس بازگشتش باید به خانهٔ پنلِ همکار
    # باشد، نه به tadm:sec:settings که برایِ همکار اصلاً در دسترس نیست.
    _hub_back_cb = "pp:home" if plan == "partner" else "tadm:sec:settings"
    rows.append([InlineKeyboardButton(text="⬅️ بازگشت به تنظیمات", callback_data=_hub_back_cb,
                                      style=ButtonStyle.DANGER)])
    return InlineKeyboardMarkup(inline_keyboard=rows)


async def _tn_general_hub_text(bot_id: int) -> str:
    support = (await get_setting(bot_id, "support_contact", "")).strip()
    welcome = (await get_setting(bot_id, "welcome_text", "")).strip()
    purchase_notify_v = await get_setting(bot_id, "purchase_notify", "1")
    new_user_notify_v = await get_setting(bot_id, "new_user_notify", "0")
    async with Session() as s:
        fj_count = len((await s.scalars(select(ForceJoin).where(ForceJoin.bot_id == bot_id))).all())
    # === PATCH_PARTNER_HUB_GIFT_DICE_V1 ===
    ref_reward_v = await get_setting(bot_id, "referral_reward", "0")
    try:
        ref_reward_amt = int(float(ref_reward_v or 0))
    except ValueError:
        ref_reward_amt = 0
    async with Session() as s:
        dice_games_count = len((await s.scalars(select(DiceGame).where(DiceGame.bot_id == bot_id))).all())
        # === PATCH_PARTNER_DISCOUNT_V1 ===
        _codes = (await s.scalars(select(DiscountCode).where(
            DiscountCode.bot_id == bot_id))).all()
    from datetime import datetime as _dt
    _now = _dt.utcnow()
    _disc_live = sum(1 for c in _codes
                     if c.is_active and not (c.expires_at and c.expires_at < _now)
                     and not (c.max_uses and c.used_count >= c.max_uses))
    return (
        "🤖 <b>تنظیمات عمومی ربات</b>\n\n"
        f"✏️ پیام خوش‌آمد: {'✅ سفارشی' if welcome else '— پیش‌فرض —'}\n"
        f"💬 پشتیبانی: {support or '—'}\n"
        f"📢 کانال‌های عضویت اجباری: {fj_count}\n"
        f"🔔 اطلاع خودکار خرید: {'✅ فعال' if purchase_notify_v == '1' else '❌ غیرفعال'}\n"
        f"👤 اطلاع ورود کاربر جدید: {'✅ فعال' if new_user_notify_v == '1' else '❌ غیرفعال'}\n"
        f"🎁 مبلغ هدیه دعوت: {ref_reward_amt:,} تومان\n"
        f"🏷 کدهای تخفیف: {_disc_live} فعال از {len(_codes)}\n"
        f"🎲 بازی‌های «بازی کن و جایزه بگیر»: {dice_games_count}\n\n"
        "یک بخش را انتخاب کن 👇"
    )


@tenant_router.callback_query(F.data == "set:hub_general")
async def tn_general_hub(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    if row.plan != "partner":
        # === PATCH_GENERAL_HUB_PARTNER_ONLY_V1 ===
        # محافظِ اضافه: حتی اگه دکمه‌ی قدیمی/کش‌شده هنوز جایی نمایش داده
        # بشه، برایِ پلن‌هایِ غیرِ همکار این هاب باز نمی‌شه.
        await cb.answer()
        return
    txt = await _tn_general_hub_text(row.id)
    kb = await _tn_general_hub_kb(row.id, row.plan)
    try:
        await cb.message.edit_text(txt, reply_markup=kb)
    except Exception:
        await cb.message.answer(txt, reply_markup=kb)
    await cb.answer()


