def _unknown_profile_vars(text: str) -> list[str]:
    """اسم‌هایی که شبیهِ متغیرند ({{name}}) ولی ربات نمی‌شناسد — احتمالاً غلطِ املایی."""
    import re as _re
    from tenant.shared import text_vars as _tv
    found = {(m.group(1) or m.group(2)) for m in _tv._PATTERN.finditer(text or "")}
    return sorted(n for n in found if _tv.canonical(n) is None)


@tenant_router.message(AdminFSM.profile_template, F.text)
async def set_profile_template_save(msg: Message, state: FSMContext, bot: Bot):
    row = await get_bot_row(bot)
    if not row:
        await state.clear()
        return
    raw = (msg.text or "").strip()
    if raw == "/skip":
        await state.clear()
        await set_setting(row.id, "profile_template_text", "")
        await msg.answer("✅ به متنِ پیش‌فرضِ ربات برگشت.", reply_markup=await _profile_footer_back_kb(row))
        return
    html_text = msg.html_text
    # پیش‌نمایش با اطلاعاتِ خودِ ادمین؛ اگر تلگرام نپذیرفت (HTMLِ ناقص/طولِ زیاد) ذخیره نمی‌کنیم
    from tenant.shared.text_vars import render_text as _render_vars
    u = await get_or_create_user(row.id, msg.from_user.id, msg.from_user.full_name or "",
                                 msg.from_user.username or "")
    try:
        preview = await _render_vars(html_text, bot_id=row.id, user=u)
        await msg.answer("👁 <b>پیش‌نمایش (با اطلاعاتِ خودت):</b>\n\n" + preview, parse_mode="HTML")
    except TelegramBadRequest as e:
        logger.warning("[profile] قالبِ مشخصات پذیرفته نشد: %s", e)
        await msg.answer(
            "❌ تلگرام این متن را نپذیرفت (معمولاً یک تگِ HTML باز مانده یا متن خیلی بلند است) و "
            "<b>ذخیره نشد</b>.\nمتن را اصلاح کن و دوباره بفرست، یا «انصراف».", parse_mode="HTML")
        return                                  # در همان مرحله می‌ماند
    if len(html_text) > 3500:
        await msg.answer("❌ متن بیش از حد بلند است (بیش از ۳۵۰۰ نویسه) و ذخیره نشد؛ کوتاه‌ترش کن.")
        return
    await state.clear()
    await set_setting(row.id, "profile_template_text", html_text)
    unknown = _unknown_profile_vars(html_text)
    warn = ("\n\n⚠️ این اسم‌ها متغیرِ شناخته‌شده نیستند و همان‌طور که نوشتی نشان داده می‌شوند: "
            + "، ".join(f"<code>{{{{{n}}}}}</code>" for n in unknown)) if unknown else ""
    await msg.answer("✅ متنِ کاملِ «مشخصاتِ شما» ذخیره شد." + warn, parse_mode="HTML",
                     reply_markup=await _profile_footer_back_kb(row))


@tenant_router.callback_query(F.data == "set:pf:def")
async def set_profile_default_show(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    from tenant.shared.profile_stats import DEFAULT_TEMPLATE
    await cb.answer()
    await cb.message.answer(
        "📋 <b>متنِ پیش‌فرض با متغیرها</b> — پایین را کپی کن، هرجا خواستی عوض کن و از «✏️ تغییرِ کلِ متنِ مشخصات» "
        "بفرست:")
    # داخلِ یک پیامِ جدا و به‌صورتِ متنِ ساده تا کپی‌کردنش آسان باشد (نه رندرشده)
    await cb.message.answer(DEFAULT_TEMPLATE, parse_mode=None)


@tenant_router.callback_query(F.data == "set:pf:prev")
async def set_profile_preview(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    u = await get_or_create_user(row.id, cb.from_user.id, cb.from_user.full_name or "",
                                 cb.from_user.username or "")
    await cb.answer()
    await cb.message.answer("👁 پیش‌نمایشِ همان صفحه‌ای که کاربر می‌بیند (با اطلاعاتِ خودت):")
    await show_profile(cb.message, row.id, u)


@tenant_router.callback_query(F.data.startswith("set:pf:rst:"))
async def set_profile_reset(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    which = cb.data.rsplit(":", 1)[1]
    if which == "tpl":
        await set_setting(row.id, "profile_template_text", "")
        await cb.answer("✅ به متنِ پیش‌فرض برگشت.")
    elif which == "footer":
        await set_setting(row.id, "profile_footer_text", "")
        await cb.answer("✅ متنِ پایین حذف شد.")
    else:
        await cb.answer()
        return
    await _profile_menu_send(cb, row)


# === PATCH_PROFILE_FOOTER_VIRTUAL_ENTRY_V1 ===
# همکار → هابِ تنظیماتِ عمومی؛ بقیه (مثلاً خدماتِ مجازی) → «دکمه‌ها و تنظیمات».
async def _profile_footer_back_kb(row):
    if row.plan == "partner":
        return await _tn_general_hub_kb(row.id, row.plan)
    menu_mode_v = await get_setting(row.id, "menu_mode", "reply")
    return await _sec_settings_kb(row.id, row.plan, menu_mode_v, row.status == "paused")


