# === PATCH_RULES_VERSION_V1 ===
# درخواستِ Fadayi: با تغییرِ متنِ قوانین، دفعهٔ بعد که کاربر وارد همان بخش می‌شود قوانینِ جدید نشان داده شود و
# تأییدِ مجدد گرفته شود؛ تاریخ و نسخهٔ قوانینِ تأییدشده هم ذخیره و در کارتِ کاربر (پنلِ مدیریت) نشان داده شود.
def _rules_ver(text) -> str:
    import hashlib as _hl
    return _hl.sha1((text or "").strip().encode("utf-8")).hexdigest()[:8]


async def _btn_rules_accepted(bot_id: int, btn, user_id: int) -> bool:
    """آیا کاربر *نسخهٔ فعلیِ* قوانینِ این دکمه را تأیید کرده؟ مقدارِ قدیمی «1» (بدونِ نسخه) یک‌بار به نسخهٔ
    فعلی ارتقا پیدا می‌کند؛ از آن به بعد هر ویرایشِ متن، تأییدِ مجدد می‌خواهد."""
    key = f"rules_ok:{btn.id}:{user_id}"
    v = await get_setting(bot_id, key, "0")
    cur = _rules_ver(btn.rules)
    if v == "1":
        await set_setting(bot_id, key, f"{cur}|")
        return True
    return v.split("|")[0] == cur


async def _btn_rules_mark(bot_id: int, btn, user_id: int) -> None:
    await set_setting(bot_id, f"rules_ok:{btn.id}:{user_id}",
                      f"{_rules_ver(btn.rules)}|{_dt.datetime.utcnow().isoformat(timespec='seconds')}")


async def _rules_history_text(bot_id: int, u) -> str:
    """بخشِ «سابقهٔ تأییدِ قوانین» برایِ کارتِ کاربر در پنلِ مدیریت."""
    lines: list[str] = []

    def _fmt(iso: str | None) -> str:
        try:
            d, t = _jalali_date_time(_dt.datetime.fromisoformat(iso))
            return f"{d} {t}"
        except Exception:
            return "تاریخ ثبت نشده (تأییدِ قدیمی)"
    try:
        if getattr(u, "rules_accepted", False):
            cur = _rules_ver(await get_setting(bot_id, "vs_rules_text", ""))
            ver = getattr(u, "rules_version", None)
            ts = u.rules_accepted_at.isoformat() if getattr(u, "rules_accepted_at", None) else None
            state = "✅ نسخهٔ فعلی" if (ver == cur or ver is None) else "⚠️ نسخهٔ قدیمی (باید دوباره تأیید کند)"
            lines.append(f"   • قوانینِ ربات: {_fmt(ts)} — نسخه <code>{ver or '—'}</code> {state}")
        async with Session() as s:
            rows = (await s.scalars(select(Setting).where(
                Setting.bot_id == bot_id, Setting.key.like(f"rules_ok:%:{u.id}")))).all()
            ids = []
            for r in rows:
                try:
                    ids.append(int(r.key.split(":")[1]))
                except (ValueError, IndexError):
                    continue
            btns = {b.id: b for b in (await s.scalars(select(MainButton).where(
                MainButton.id.in_(ids or [0]), MainButton.bot_id == bot_id))).all()}
        for r in rows[:8]:
            try:
                bid = int(r.key.split(":")[1])
            except (ValueError, IndexError):
                continue
            b = btns.get(bid)
            if not b:
                continue
            ver, _, iso = (r.value or "").partition("|")
            if r.value == "1":
                ver, iso = "", ""
            state = "✅" if ver == _rules_ver(b.rules) else "⚠️ نسخهٔ قدیمی"
            lines.append(f"   • «{_html.escape(b.label or '')}»: {_fmt(iso or None)} — نسخه <code>{ver or '—'}</code> {state}")
    except Exception:
        logger.exception("ساختِ سابقهٔ تأییدِ قوانین ناموفق بود")
        return ""
    return ("\n📜 سابقهٔ تأییدِ قوانین:\n" + "\n".join(lines)) if lines else ""


def _btn_rules_once_enabled(mb) -> bool:
    """PATCH_BUTTON_RULES_ONCE_TOGGLE_V1 — آیا ادمین برایِ این دکمه انتخاب
    کرده که قوانین فقط یک‌بار برایِ هر کاربر نشون داده بشه؟ (پیش‌فرض: نه،
    یعنی رفتارِ قدیمیِ «هر بار نشون بده» حفظ می‌شه مگه اینکه ادمین صریحاً
    روشنش کنه.)"""
    if not mb.config:
        return False
    try:
        return bool((json.loads(mb.config) or {}).get("rules_once"))
    except Exception:
        return False


def _thb_kb_rule_detail(mb) -> InlineKeyboardMarkup:
    """PATCH_BUTTON_RULES_SUBMENU_V1 — زیرمنویِ خودِ «قوانین»: افزودن/ویرایش،
    و اگه قانونی ثبت شده، زیرش تیکِ «فقط بارِ اول» و دکمهٔ حذف."""
    has_rule = bool((mb.rules or "").strip())
    rows = [[InlineKeyboardButton(
        text=("✏️ ویرایشِ قوانین" if has_rule else "➕ افزودنِ قوانین"),
        callback_data=f"thb:ruleadd:{mb.id}", style=ButtonStyle.SUCCESS)]]
    if has_rule:
        _once = _btn_rules_once_enabled(mb)
        rows.append([InlineKeyboardButton(
            text=("✅ فقط بارِ اول نشون بده (روشن)" if _once else "⬜️ فقط بارِ اول نشون بده (خاموش)"),
            callback_data=f"thb:rulesonce:{mb.id}", style=(ButtonStyle.SUCCESS if _once else ButtonStyle.PRIMARY))])
        rows.append([InlineKeyboardButton(text="🗑 حذف قوانین", callback_data=f"thb:ruledel:{mb.id}", style=ButtonStyle.DANGER)])
    rows.append([InlineKeyboardButton(text="⬅️ بازگشت", callback_data=f"thb:cat:rules:{mb.id}", style=ButtonStyle.DANGER)])
    return InlineKeyboardMarkup(inline_keyboard=rows)


def _thb_kb_rules(mb) -> InlineKeyboardMarkup:
    """دستهٔ «قوانین و دسترسی و تست»: قوانینِ نمایشی + شرطی‌سازی/گیتِ زیرمجموعه + کدِ تخفیفِ اختصاصی."""
    has_rule = bool((mb.rules or "").strip())
    # === PATCH_BUTTON_RULES_SUBMENU_V1 ===
    # افزودن/ویرایش/حذف/تیکِ «فقط بارِ اول» همه رفتن تویِ زیرمنویِ خودِ
    # «قوانین» (thb:rule:) تا این‌جا فقط یک ورودی داشته باشه، شلوغ نشه.
    rows = [[InlineKeyboardButton(
        text=("📜 قوانین (ثبت‌شده — ویرایش/حذف)" if has_rule else "📜 افزودن و ویرایش قوانین"),
        callback_data=f"thb:rule:{mb.id}", style=ButtonStyle.SUCCESS)]]
    if mb.action == "referral_gate":
        rows.append([
            InlineKeyboardButton(text="🎯 ویرایش شرط زیرمجموعه", callback_data=f"gate:start:{mb.id}", style=ButtonStyle.PRIMARY),
            InlineKeyboardButton(text="❌ حذف شرط", callback_data=f"gate:off:{mb.id}", style=ButtonStyle.DANGER),
        ])
    elif mb.action in (None, "submenu"):
        rows.append([InlineKeyboardButton(text="🎯 شرطی‌سازی با زیرمجموعه", callback_data=f"gate:start:{mb.id}", style=ButtonStyle.PRIMARY)])
    else:
        rows.append([InlineKeyboardButton(text="🔒 گیتِ دسترسی با زیرمجموعه",
                                          callback_data=f"gate:mode:access:{mb.id}", style=ButtonStyle.PRIMARY)])
    _gated_keep_rules = None
    if mb.action == "referral_gate" and mb.config:
        try:
            _gated_keep_rules = (json.loads(mb.config) or {}).get("keep_action")
        except Exception:
            _gated_keep_rules = None
    if (mb.action in _EXDISC_SALE_ACTIONS or _is_panel_buy_action(mb.action)
            or _gated_keep_rules in _EXDISC_SALE_ACTIONS or _is_panel_buy_action(_gated_keep_rules)):
        # کد تخفیف اختصاصیِ همین دکمه — فقط برای دکمه‌های «خرید کانفیگ» که بستهٔ فروش
        # و جای وارد کردن کد تخفیف دارند معنا دارد (حتی اگر با شرط زیرمجموعه گیت شده باشد).
        rows.append([InlineKeyboardButton(text="🏷 کد تخفیف اختصاصی این دکمه",
                                          callback_data=f"thb:exdisc:{mb.id}", style=ButtonStyle.PRIMARY)])
    rows.append(_thb_back_row(mb))
    return InlineKeyboardMarkup(inline_keyboard=rows)


def _thb_kb_action(mb, bot_field: str = "", plan: str = "") -> InlineKeyboardMarkup:
    """دستهٔ «عملکرد دکمه»: تبدیل به انواع عملکرد + تنظیماتِ اختصاصیِ همان عملکرد.

    گزینه‌های «تبدیل به X» بر اساسِ زمینهٔ ربات (vpn_sales/digital_shop/booking/
    general) فیلتر می‌شوند تا مثلاً ربات فروشگاهی گزینه‌های مخصوصِ VPN را
    نبیند و برعکس — دو نوع ربات کاملاً مجزا بمانند.

    === PATCH_PARTNER_THB_ACTIONS_FIX_V1 ===
    این فیلتر فقط رویِ ستونِ field چک می‌کرد، نه پلن. برایِ رباتِ همکار
    (plan="partner")، ستونِ field همیشه لزوماً "partner" نیست (مثلاً اگر
    قبلِ تبدیل‌شدن به همکار "digital_shop" بوده)، پس گزینه‌هایِ مخصوصِ
    فروشگاه («تبدیل به اسلایدشو»، «نمایش فروشگاه»، «اتصال مستقیم به یک
    محصول») و VPN اشتباهاً برایِ ربات همکار هم نمایش داده می‌شدند —
    امکاناتی که اصلاً برایِ پلنِ همکار وجود ندارند. حالا هرجا این گزینه‌ها
    مخصوصِ یک زمینهٔ خاص‌اند، اول چک می‌شود که ربات همکار نباشد.
    """
    _is_partner = (plan == "partner")
    rows = []
    _gated_keep = None
    if mb.action == "referral_gate" and mb.config:
        try:
            _gated_keep = (json.loads(mb.config) or {}).get("keep_action")
        except Exception:
            _gated_keep = None
    if mb.action == "buy_config" or _gated_keep == "buy_config":
        rows.append([
            InlineKeyboardButton(text="📏 بازه حجم", callback_data=f"thb:rng:vols:{mb.id}", style=ButtonStyle.PRIMARY),
            InlineKeyboardButton(text="📅 بازه روز", callback_data=f"thb:rng:days:{mb.id}", style=ButtonStyle.PRIMARY),
        ])
        rows.append([
            InlineKeyboardButton(text="🔢 بازه تعداد", callback_data=f"thb:rng:counts:{mb.id}", style=ButtonStyle.PRIMARY),
            InlineKeyboardButton(text="♻️ بازگشت به بازهٔ سراسری", callback_data=f"thb:rngdel:{mb.id}", style=ButtonStyle.DANGER),
        ])
    if mb.action == "submenu":
        rows.append([InlineKeyboardButton(text="🗂 مدیریت زیرمنو", callback_data=f"thb:sub:{mb.id}", style=ButtonStyle.PRIMARY)])
        # === PATCH_SUBMENU_UNSET_V1 ===
        # قبلاً وقتی عملکردِ یه دکمه «زیرمنو» می‌شد، دیگه هیچ راهی نبود که
        # عملکردش عوض بشه — همهٔ گزینه‌هایِ «تبدیل به X» فقط وقتی action
        # خالی (None) بود نمایش داده می‌شدن، و زیرمنو برخلافِ همهٔ عملکردهایِ
        # دیگه (که هرکدوم یه دکمهٔ «↩️ حذف» داشتن) این دکمه رو نداشت.
        rows.append([InlineKeyboardButton(text="↩️ حذفِ زیرمنو (برایِ تغییرِ عملکرد)",
                                          callback_data=f"thb:unsetsubmenu:{mb.id}", style=ButtonStyle.DANGER)])
    elif mb.action in (None,):
        # === PATCH_THB_ACTION_CATEGORIES_V1 ===
        # قبلاً این‌جا (وقتی هنوز هیچ عملکردی انتخاب نشده) یه لیستِ تخت با
        # ۱۵+ گزینه نشون داده می‌شد که پیدا کردنِ چیزِ موردنظر توش سخت بود.
        # الان اول یه دسته‌بندیِ کوچیک نشون داده می‌شه: زیرمنو (ساختاری)،
        # محصول/فروش، یا ابزارهایِ عمومی — و لیستِ کاملِ همون دسته با زدنش
        # باز می‌شه (تویِ _thb_kb_action_pick پایین‌تر).
        rows.append([InlineKeyboardButton(text="🗂 تبدیل به زیرمنو", callback_data=f"thb:sub:{mb.id}", style=ButtonStyle.PRIMARY)])
