# === PATCH_THB_ACTION_CATEGORIES_V1 ===
def _thb_kb_action_pick(mb, bot_field: str = "", plan: str = "", category: str = "sell",
                        store_miniapp_ok: bool = True) -> InlineKeyboardMarkup:
    """لیستِ کاملِ «تبدیل به X» برایِ یک دسته‌ی خاص — category="sell" یعنی
    گزینه‌هایِ مربوط به محصول/سرویس (فروش)، category="tool" یعنی ابزارها و
    اطلاعاتِ عمومی. این تابع همون محتوایی رو می‌سازه که قبلاً یک‌جا و تخت
    تویِ _thb_kb_action بود، فقط الان فیلترشده بر اساسِ دسته."""
    _is_partner = (plan == "partner")
    rows = []
    if category == "sell":
        if not _is_partner:
            rows.append([InlineKeyboardButton(text="🎞 تبدیل به اسلایدشو",
                                              callback_data=f"thb:setslideshow:{mb.id}", style=ButtonStyle.PRIMARY)])
        if bot_field in ("digital_shop", "ad_bot") and not _is_partner:
            rows.append([InlineKeyboardButton(text="🛒 تبدیل به «نمایش فروشگاه»",
                                              callback_data=f"thb:setshop:{mb.id}", style=ButtonStyle.PRIMARY)])
            rows.append([InlineKeyboardButton(text="🛍 اتصال مستقیم به یک محصول",
                                              callback_data=f"thb:setproduct:{mb.id}", style=ButtonStyle.PRIMARY)])
        if bot_field == "virtual_service" and not _is_partner:
            rows.append([InlineKeyboardButton(text="🎯 اتصال مستقیم به یک سرویسِ خدماتِ مجازی",
                                              callback_data=f"thb:setsmmproduct:{mb.id}", style=ButtonStyle.PRIMARY)])
        if bot_field == "vpn_sales" and not _is_partner:
            rows.append([InlineKeyboardButton(text="🎁 تبدیل به «تست رایگان VPN»",
                                              callback_data=f"thb:setfreetrial:{mb.id}", style=ButtonStyle.PRIMARY)])
            rows.append([
                InlineKeyboardButton(text="🛒 خرید کانفیگ", callback_data=f"thb:setbuyconfig:{mb.id}", style=ButtonStyle.PRIMARY),
                InlineKeyboardButton(text="♾️ خرید نامحدود", callback_data=f"thb:setunlimited:{mb.id}", style=ButtonStyle.PRIMARY),
            ])
            rows.append([InlineKeyboardButton(
                text="🛒 تغییر اکشن: خرید کانفیگ از پنل",
                callback_data=f"thb:setvpnpanel:{mb.id}", style=ButtonStyle.PRIMARY)])
            # === PATCH_PANEL_SHOP_ACTION_V1 === عملکردِ مستقلِ فروشِ پنل (ثبت و فروش پنل)
            if has_feature(plan, Feature.VPN_PANEL_MARKET):
                rows.append([InlineKeyboardButton(
                    text="🏷 فروش پنل (ثبت و فروش پنل) — تبدیل به این",
                    callback_data=f"thb:setsimple:buy_panel_market:{mb.id}", style=ButtonStyle.SUCCESS)])
            # === PATCH_METERED_BTN_ACTION_V1 ===
            if has_feature(plan, Feature.METERED_PLAN):
                rows.append([InlineKeyboardButton(
                    text="💳 بستهٔ اعتباری (پرداخت به‌ازای مصرف) — تبدیل به این",
                    callback_data=f"thb:setsimple:buy_metered:{mb.id}", style=ButtonStyle.SUCCESS)])
            if has_feature(plan, Feature.COMBO_BUTTON):
                rows.append([InlineKeyboardButton(
                    text="🧩 خرید ترکیبی (چند دسته/پنل با هم)",
                    callback_data=f"thb:setbundle:{mb.id}", style=ButtonStyle.PRIMARY)])
            else:
                rows.append([InlineKeyboardButton(
                    text="🔒 خرید ترکیبی (ویژهٔ پلن حرفه‌ای)",
                    callback_data="thb:bundle_locked", style=ButtonStyle.DANGER)])
    else:  # "tool"
        rows.append([InlineKeyboardButton(text="🏆 تبدیل به «نفرات برتر»",
                                          callback_data=f"thb:settopcust:{mb.id}", style=ButtonStyle.PRIMARY)])
        rows.append([InlineKeyboardButton(text="🎫 تبدیل به «تیکت پشتیبانی»",
                                          callback_data=f"thb:setticket:{mb.id}", style=ButtonStyle.PRIMARY)])
        rows.append([InlineKeyboardButton(text="📢 تبدیل به «لینکِ مستقیم» (کانال/گروه/سایت)",
                                          callback_data=f"thb:setlink:{mb.id}", style=ButtonStyle.PRIMARY)])   # PATCH_BUTTON_CHANNEL_LINK_V1
        rows.append([InlineKeyboardButton(text="🌐 تبدیل به «ورود به لینک دلخواه» (وب‌اپ)",
                                          callback_data=f"thb:setwebapp:{mb.id}", style=ButtonStyle.PRIMARY)])
        for _akey, (_alabel, _confirm, _fields) in _SIMPLE_ACTIONS.items():
            if _fields is not None and bot_field not in _fields:
                continue
            # === PATCH_NFT_MARKET_BTN_ACTION_V1 ===
            # این یکی علاوه بر زمینه، پلن هم می‌خواهد (فقط حرفه‌ای).
            if _akey == "nft_market" and not has_feature(plan, Feature.NFT_MARKET):
                continue
            if _akey == "escrow" and not has_feature(plan, Feature.ESCROW):   # PATCH_ESCROW_V1
                continue
            # === PATCH_STORE_MINIAPP_GATE_V1 === فقط وقتی مینی‌اپ روشن و محلِ نمایشش «کیبورد» است
            if _akey == "store_miniapp" and not store_miniapp_ok:
                continue
            if _akey in ("buy_panel_market", "buy_metered"):
                continue   # PATCH_PANEL_SHOP_ACTION_V1 / PATCH_METERED_BTN_ACTION_V1: در دستهٔ «فروش» نشان داده می‌شوند
            rows.append([InlineKeyboardButton(text=f"{_alabel} — تبدیل به این",
                                              callback_data=f"thb:setsimple:{_akey}:{mb.id}", style=ButtonStyle.PRIMARY)])
    rows.append([InlineKeyboardButton(text="⬅️ بازگشت به دسته‌ها", callback_data=f"thb:cat:action:{mb.id}", style=ButtonStyle.DANGER)])
    return InlineKeyboardMarkup(inline_keyboard=rows)


@tenant_router.callback_query(F.data.startswith("thb:actcat:"))
async def thb_actcat_open(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    _, _, category, mb_id_s = cb.data.split(":")
    mb_id = int(mb_id_s)
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
    if not mb or mb.bot_id != row.id:
        await cb.answer("یافت نشد", show_alert=True)
        return
    is_dis = mb_id in await _disabled_btn_ids(row.id)
    title = "🛍 <b>اتصال به محصول یا سرویس (فروش)</b>" if category == "sell" else "🧰 <b>ابزارها و اطلاعاتِ عمومی</b>"
    text = title + "\n\n" + _thb_text(mb, is_dis)
    # === PATCH_STORE_MINIAPP_GATE_V1 ===
    try:
        # === PATCH_STORE_MINIAPP_ANY_PLACE_V1 === گزارش (ایلیا): «تبدیل به مینی‌اپ» را پیدا نکردم —
        # قبلاً فقط وقتی دیده می‌شد که «محلِ نمایش = داخل کیبورد» باشد؛ ولی خودِ دکمه با هر محلی کار می‌کند.
        _sm_ok = bool(getattr(row, "miniapp_enabled", False))
    except Exception:
        logger.exception("چکِ شرطِ نمایشِ «تبدیل به مینی‌اپ» ناموفق بود")
        _sm_ok = False
    kb = _thb_kb_action_pick(mb, row.field, row.plan, category, store_miniapp_ok=_sm_ok)
    try:
        await cb.message.edit_text(text, reply_markup=kb, parse_mode="HTML")
    except Exception:
        await cb.message.answer(text, reply_markup=kb, parse_mode="HTML")
    await cb.answer()


@tenant_router.callback_query(F.data.startswith("thb:cat:"))
async def thb_cat_open(cb: CallbackQuery, bot: Bot):
    """باز کردنِ یکی از دسته‌های تنظیماتِ یک دکمه (نام/ظاهر، پشتیبانی، قوانین، عملکرد)."""
    row = await _owner_ok(cb, bot)
    if not row:
        return
    _, _, cat, mb_id_s = cb.data.split(":")
    mb_id = int(mb_id_s)
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
    if not mb or mb.bot_id != row.id:
        await cb.answer("یافت نشد", show_alert=True)
        return
    is_dis = mb_id in await _disabled_btn_ids(row.id)
    builders = {
        "look": (_thb_kb_look(mb), "✏️ <b>نام، متن و ظاهرِ دکمه</b>"),
        "support": (await _thb_kb_support(mb), "💬 <b>پشتیبانیِ این دکمه</b>\n"
                    "روشن/خاموش‌کردن، تنظیمِ آدرس اختصاصی و حذفِ آن از همین‌جا."),
        "rules": (_thb_kb_rules(mb), "📜 <b>قوانین و دسترسی و تستِ این دکمه</b>"),
        "action": (_thb_kb_action(mb, row.field, row.plan), f"🎯 <b>عملکرد دکمه</b>\nعملکرد فعلی: {_thb_action_label(mb)}"),
    }
    if cat not in builders:
        await cb.answer()
        return
    kb, title = builders[cat]
    text = title + "\n\n" + _thb_text(mb, is_dis)
    try:
        await cb.message.edit_text(text, reply_markup=kb)
    except Exception:
        await cb.message.answer(text, reply_markup=kb)
    await cb.answer()


def _thb_text(mb, is_disabled: bool) -> str:
    has_rule = bool((mb.rules or "").strip())
    has_msg = bool((mb.message or "").strip())
    lines = [
        f"⚙️ دکمه: <b>{mb.label}</b>",
        f"وضعیت: {'🔴 غیرفعال' if is_disabled else '🟢 فعال'}",
        f"متن دکمه: {'✏️ دارد' if has_msg else '—'}",
        f"قانون: {'📜 دارد' if has_rule else '—'}",
        f"ایموجی پرمیوم: {'😎 دارد' if (mb.icon_emoji_id or '').strip() else '—'}",
        f"پشتیبان دکمه: {('🎧 ' + normalize_support(mb.support_contact)[1]) if (mb.support_contact or '').strip() else '—'}",
    ]
    if mb.action == "buy_config":
        cfg = {}
        if mb.config:
            try:
                cfg = json.loads(mb.config) or {}
            except Exception:
                cfg = {}
        def _rng(key, unit):
            vals = cfg.get(key)
            if not vals:
                return "سراسری"
            return (f"{min(vals)} تا {max(vals)} {unit}" if len(vals) > 1
                    else f"{vals[0]} {unit} (ثابت)")
        lines.append(f"📏 بازه حجم: {_rng('vols', 'گیگ')}")
        lines.append(f"📅 بازه روز: {_rng('days', 'روز')}")
        lines.append(f"🔢 بازه تعداد: {_rng('counts', 'عدد')}")
    if mb.action == "web_app":
        _wa = _webapp_url(mb)
        lines.append(f"🌐 لینک مینی‌اپ: {_wa or '⚠️ تنظیم نشده'}")
    if mb.action == "channel_link":          # PATCH_BUTTON_CHANNEL_LINK_V1
        lines.append(f"🔗 لینکِ مقصد: {_link_url(mb) or '⚠️ تنظیم نشده'}")
    # === PATCH_DICE_GAME_DIRECT_BTN_V1 ===
    if mb.action == "dice_game" and mb.config:
        try:
            _dg_id = (json.loads(mb.config) or {}).get("game_id")
        except Exception:
            _dg_id = None
        if _dg_id:
            lines.append(f"🎯 بازیِ متصل: (آیدی {_dg_id} — از «تغییرِ بازیِ متصل» می‌تونی اسمش رو ببینی)")
    _bc = _btn_command_of(mb)
    if _bc:
        lines.append(f"⌨️ کامند سفارشی: /{_bc}")
    if mb.action == "referral_gate":
        from tenant.shared.referral_gate import load_gate, gate_summary
        g = load_gate(mb)
        if g:
            lines.append("")
            lines.append(gate_summary(g))
        else:
            lines.append("🎯 شرط: <i>ناقص — دوباره تنظیم کن</i>")
    if mb.action == "buy_unlimited":
        lines.append("♾️ اکشن: خرید کانفیگ نامحدود")
    if mb.action == "free_trial":
        lines.append(f"🧪 نوع تست: {_TRIAL_MODE_LABELS.get(_trial_mode_of(mb), 'تنظیم سراسری ربات')}")
    if mb.action == "slideshow":
        lines.append("🎞 اکشن: اسلایدشو چندرسانه‌ای")
    if mb.action == "show_shop":
        lines.append("🛒 اکشن: نمایش فروشگاه")
    if mb.action and mb.action.startswith("buy_vpn_"):
        _panel_action_labels_text = {
            "buy_vpn_sanai":         "🔵 خرید از پنل سنایی",
            "buy_vpn_pasargad":      "🟣 خرید از پنل پاسارگاد",
            "buy_vpn_pasarguard":    "🛡️ خرید از پنل PasarGuard",
            "buy_vpn_marzban":       "🟠 خرید از پنل مرزبان",
            "buy_vpn_marzneshin":    "⚪️ خرید از پنل مرزنشین",
            "buy_vpn_hiddify":       "🟢 خرید از پنل هیدیفای",
            "buy_vpn_rebecca":       "🔴 خرید از پنل ربکا",
            "buy_vpn_alireza":       "🟢 خرید از پنل علیرضا",
            "buy_vpn_upanel_mizban": "🟡 خرید از یوپنل (مرزبان)",
            "buy_vpn_nodex":         "🔷 خرید از پنل نودکس",
            "buy_vpn_degeris":       "🟣 خرید از پنل DEGERIS",
            "buy_vpn_eylan":         "🟠 خرید از پنل ایلان",
            "buy_vpn_heimdall":      "🛡 خرید از پنل HEIMDALL",
            "buy_vpn_rickpanel":     "🟥 خرید از پنل RickPanel",
        }
        # === PATCH_MULTI_PANEL_INSTANCES_V1 ===
        _lbl = _panel_action_labels_text.get(mb.action)
        if not _lbl:
            from tenant.bots.vpn.vpn_admin import PANEL_LABELS as _PLBL4
            _k = mb.action[len("buy_vpn_"):]
            _lbl = f"خرید از {_PLBL4.get(_k, _k)}"
        lines.append(f"🛒 اکشن: {_lbl}")
    lines.append("")
    lines.append("یکی را انتخاب کن:")
    return "\n".join(lines)


@tenant_router.callback_query(F.data == "tadm:homebtns")
async def tadm_homebtns(cb: CallbackQuery, bot: Bot, state: FSMContext):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    await state.clear()
    async with Session() as s:
        btns = (await s.scalars(select(MainButton).where(
                MainButton.bot_id == row.id, MainButton.parent_id.is_(None))
                .order_by(MainButton.row, MainButton.col))).all()
    disabled = await _disabled_btn_ids(row.id)

    # نمایش شیشه‌ای: دکمه‌ها با همان چیدمان واقعی ربات نشان داده می‌شوند
    rows_map: dict[int, list] = {}
    for mb in btns:
        rows_map.setdefault(mb.row, []).append(mb)

    keyboard_rows = []
    for r_num in sorted(rows_map.keys()):
        row_btns = sorted(rows_map[r_num], key=lambda x: x.col)
        kb_row = []
        for mb in row_btns:
            st = "🔴" if mb.id in disabled else "🟢"
            sub_mark = " 🗂" if mb.action == "submenu" else ""
            rule_mark = " 📜" if (mb.rules or "").strip() else ""
            kb_row.append(InlineKeyboardButton(
                text=f"{st} {mb.label}{sub_mark}{rule_mark}",
                callback_data=f"thb:pick:{mb.id}", style=ButtonStyle.PRIMARY))
        keyboard_rows.append(kb_row)

    keyboard_rows.append([InlineKeyboardButton(text="➕ افزودن دکمه", callback_data="thb:add", style=ButtonStyle.SUCCESS)])
    keyboard_rows.append([InlineKeyboardButton(text="🔀 چیدمانِ سریع (بالا/پایین/کنارِهم)",
                                               callback_data="thbn:menu", style=ButtonStyle.PRIMARY)])  # PATCH_TENANT_QUICK_LAYOUT_V1
    keyboard_rows.append([InlineKeyboardButton(text="⬅️ بازگشت", callback_data="tadm:sec:settings",
                                               style=ButtonStyle.DANGER)])
    # === PATCH_DUPLICATE_BUTTON_LABEL_WARN_V1 ===
    # هشدارِ نامِ تکراری در *همهٔ* سطح‌ها (نه فقط صفحهٔ اصلی)، چون تطبیقِ
    # متنِ دکمه هم سطح نمی‌شناسد؛ دکمهٔ زیرمنو با دکمهٔ صفحهٔ اصلی هم
    # می‌تواند تداخل کند — همان چیزی که در عمل رخ داد.
    dup_note = ""
    try:
        async with Session() as s:
            all_lbl = (await s.scalars(select(MainButton.label).where(
                MainButton.bot_id == row.id))).all()
        seen, dups = set(), []
        for lb in all_lbl:
            if lb in seen and lb not in dups:
                dups.append(lb)
            seen.add(lb)
        if dups:
            shown = "، ".join(f"«{d}»" for d in dups[:5])
            more = f" و {len(dups) - 5} مورد دیگر" if len(dups) > 5 else ""
            dup_note = ("\n\n⚠️ <b>نامِ تکراری پیدا شد:</b> " + shown + more +
                        "\nربات دکمه‌ها را از رویِ نامشان تشخیص می‌دهد، پس "
                        "ممکن است اشتباهی را اجرا کند. یکی از هر جفت را "
                        "تغییرِ نام بده.")
    except Exception:
        logger.exception("بررسیِ نام‌هایِ تکراریِ دکمه ناموفق بود")

    txt = ("🏠 <b>مدیریت دکمه‌های صفحه اصلی</b>\n\n"
           "📱 چیدمان زیر دقیقاً همانند ربات شماست.\n"
           "🟢 فعال | 🔴 غیرفعال | 🗂 زیرمنو | 📜 دارای قانون\n\n"
           + ("روی هر دکمه بزن تا تغییرش بدهی، یا دکمهٔ جدید بساز:" if btns
              else "هنوز دکمه‌ای ساخته نشده. با «➕ افزودن دکمه» شروع کن.")
           + dup_note)
    try:
        await cb.message.edit_text(txt, reply_markup=InlineKeyboardMarkup(inline_keyboard=keyboard_rows))
    except Exception:
        await cb.message.answer(txt, reply_markup=InlineKeyboardMarkup(inline_keyboard=keyboard_rows))
    await cb.answer()


# ═══════════════════════════════════════════
#  چیدمانِ سریعِ دکمه‌های صفحهٔ اصلی — PATCH_TENANT_QUICK_LAYOUT_V1
# ═══════════════════════════════════════════
# همان روشی که در پلتفرمِ اصلی برایِ چیدمانِ منویِ خودِ بات‌ساز وجود دارد
# (بالا/پایین‌بردنِ کلِ ردیف، کنارِهم‌گذاشتنِ دو دکمهٔ تک‌ردیفِ پیاپی،
# جداکردن، جابه‌جاییِ دو دکمهٔ هم‌ردیف) — اینجا برایِ ربات‌هایِ مستأجر و
# همکار (که هر دو از همین tenant_router استفاده می‌کنند) هم پیاده شده.
# برخلافِ پلتفرم که چیدمان را در یک JSON در حافظه نگه می‌دارد، اینجا
# مستقیم رویِ ستون‌هایِ MainButton.row/col کارِ ذخیره انجام می‌شود — پس
# نیازی به یک ساختارِ دادهٔ موازی نیست.

async def _thb_rows_state(bot_id: int) -> tuple[list[list[int]], dict[int, "MainButton"]]:
    """فهرستِ ردیف‌ها (هرکدام لیستی از id دکمه‌ها) + دیکشنریِ id→دکمه،
    فقط برایِ دکمه‌هایِ سطحِ‌بالا (بدونِ parent_id)."""
    async with Session() as s:
        btns = (await s.scalars(select(MainButton).where(
            MainButton.bot_id == bot_id, MainButton.parent_id.is_(None)
        ).order_by(MainButton.row, MainButton.col))).all()
    by_id = {b.id: b for b in btns}
    rows_map: dict[int, list[int]] = {}
    for b in btns:
        rows_map.setdefault(b.row, []).append(b.id)
    rows_state = [rows_map[r] for r in sorted(rows_map.keys())]
    return rows_state, by_id


async def _thb_rows_save(bot_id: int, rows_state: list[list[int]]) -> None:
    """rows_state را رویِ ستون‌هایِ row/col همان ردیف‌های واقعیِ دیتابیس می‌نویسد."""
    async with Session() as s:
        for r_idx, btn_ids in enumerate(rows_state):
            for c_idx, btn_id in enumerate(btn_ids):
                b = await s.get(MainButton, btn_id)
                if b and b.bot_id == bot_id:
                    b.row = r_idx
                    b.col = c_idx
        await s.commit()


def _thb_layout_kb(rows_state: list[list[int]], by_id: dict[int, "MainButton"]) -> InlineKeyboardMarkup:
    kb_rows = []
    for i, btn_ids in enumerate(rows_state):
        parts = []
        for bid in btn_ids:
            b = by_id.get(bid)
            parts.append(b.label if b else "—")
        kb_rows.append([InlineKeyboardButton(text=f"{i+1}. " + "  |  ".join(parts),
                                             callback_data="noop")])
        ctrl = []
        if i > 0:
            ctrl.append(InlineKeyboardButton(text="⬆️", callback_data=f"thbn:rowmove:up:{i}",
                                             style=ButtonStyle.PRIMARY))
        if i < len(rows_state) - 1:
            ctrl.append(InlineKeyboardButton(text="⬇️", callback_data=f"thbn:rowmove:down:{i}",
                                             style=ButtonStyle.PRIMARY))
        if len(btn_ids) >= 2:
            if len(btn_ids) == 2:
                ctrl.append(InlineKeyboardButton(text="🔃 جابه‌جاییِ این دو",
                                                 callback_data=f"thbn:rowswap:{i}", style=ButtonStyle.PRIMARY))
            ctrl.append(InlineKeyboardButton(text="🔀 جدا از هم",
                                             callback_data=f"thbn:rowsplit:{i}", style=ButtonStyle.PRIMARY))
        # === PATCH_TENANT_QUICK_LAYOUT_3COL_V1 ===
        # قبلاً فقط وقتی ردیفِ فعلی دقیقاً یک دکمه داشت می‌شد کنارِ ردیفِ
        # بعدی گذاشتش (یعنی سقفِ همیشگی، دو دکمه در یک ردیف). حالا تا
        # سه دکمه در یک ردیف هم مجاز است — کافی‌ست جمعِ دو ردیف از سه
        # بیشتر نشود.
        if (i < len(rows_state) - 1
                and len(btn_ids) + len(rows_state[i + 1]) <= 3):
            ctrl.append(InlineKeyboardButton(text="↔️ کنارِ ردیفِ بعدی",
                                             callback_data=f"thbn:rowmerge:{i}", style=ButtonStyle.PRIMARY))
        if ctrl:
            kb_rows.append(ctrl)
    kb_rows.append([InlineKeyboardButton(text="⬅️ بازگشت", callback_data="tadm:homebtns",
                                         style=ButtonStyle.DANGER)])
    return InlineKeyboardMarkup(inline_keyboard=kb_rows)


_THBN_LAYOUT_TEXT = (
    "🔀 <b>چیدمانِ سریعِ دکمه‌ها</b>\n\n"
    "⬆️/⬇️ جابه‌جاییِ کلِ ردیف | ↔️ کنارِ هم گذاشتنِ دو دکمهٔ تک‌ردیفِ پیاپی | "
    "🔀 جدا کردنِ دو دکمهٔ هم‌ردیف | 🔃 عوض‌کردنِ جایِ دو دکمهٔ هم‌ردیف\n\n"
    "تغییر بلافاصله رویِ منویِ اصلیِ ربات اعمال می‌شه."
)


@tenant_router.callback_query(F.data == "thbn:menu")
async def thbn_menu(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    rows_state, by_id = await _thb_rows_state(row.id)
    if not rows_state:
        await cb.answer("هنوز هیچ دکمه‌ای نساخته‌ای.", show_alert=True)
        return
    kb = _thb_layout_kb(rows_state, by_id)
    try:
        await cb.message.edit_text(_THBN_LAYOUT_TEXT, reply_markup=kb, parse_mode="HTML")
    except Exception:
        await cb.message.answer(_THBN_LAYOUT_TEXT, reply_markup=kb, parse_mode="HTML")
    await cb.answer()


async def _thbn_refresh(cb: CallbackQuery, bot_id: int) -> None:
    rows_state, by_id = await _thb_rows_state(bot_id)
    kb = _thb_layout_kb(rows_state, by_id)
    try:
        await cb.message.edit_reply_markup(reply_markup=kb)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")


@tenant_router.callback_query(F.data.startswith("thbn:rowmove:"))
async def thbn_rowmove(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    _, _, direction, i_s = cb.data.split(":", 3)
    i = int(i_s)
    rows_state, _ = await _thb_rows_state(row.id)
    j = i - 1 if direction == "up" else i + 1
    if i < 0 or i >= len(rows_state) or j < 0 or j >= len(rows_state):
        await cb.answer()
        return
    rows_state[i], rows_state[j] = rows_state[j], rows_state[i]
    await _thb_rows_save(row.id, rows_state)
    await cb.answer("✅ جابه‌جا شد")
    await _thbn_refresh(cb, row.id)


@tenant_router.callback_query(F.data.startswith("thbn:rowswap:"))
async def thbn_rowswap(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    i = int(cb.data.split(":")[2])
    rows_state, _ = await _thb_rows_state(row.id)
    if i < 0 or i >= len(rows_state) or len(rows_state[i]) != 2:
        await cb.answer("نامعتبر", show_alert=True)
        return
    rows_state[i] = [rows_state[i][1], rows_state[i][0]]
    await _thb_rows_save(row.id, rows_state)
    await cb.answer("✅ جابه‌جا شد")
    await _thbn_refresh(cb, row.id)


@tenant_router.callback_query(F.data.startswith("thbn:rowsplit:"))
async def thbn_rowsplit(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    i = int(cb.data.split(":")[2])
    rows_state, _ = await _thb_rows_state(row.id)
    # === PATCH_TENANT_QUICK_LAYOUT_3COL_V1 ===
    # قبلاً فقط ردیفِ دقیقاً دوتایی را می‌شد جدا کرد. حالا برایِ ردیفِ
    # سه‌تایی هم کار می‌کند — هر بار فقط آخرین دکمه را به یک ردیفِ تازه
    # جدا می‌کند (سه‌تایی → دوتایی+یکی، دوتایی → یکی+یکی)، تا بشود
    # تدریجی و دقیق جداشان کرد.
    if i < 0 or i >= len(rows_state) or len(rows_state[i]) < 2:
        await cb.answer("نامعتبر", show_alert=True)
        return
    rest, last = rows_state[i][:-1], rows_state[i][-1]
    rows_state[i:i + 1] = [rest, [last]]
    await _thb_rows_save(row.id, rows_state)
    await cb.answer("✅ جدا شد")
    await _thbn_refresh(cb, row.id)


@tenant_router.callback_query(F.data.startswith("thbn:rowmerge:"))
async def thbn_rowmerge(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    i = int(cb.data.split(":")[2])
    rows_state, _ = await _thb_rows_state(row.id)
    # === PATCH_TENANT_QUICK_LAYOUT_3COL_V1 ===
    # سقفِ سه دکمه در هر ردیف — قبلاً فقط ۱+۱ مجاز بود، حالا ۱+۲ یا ۲+۱
    # هم مجاز است (تا زمانی که جمعشان از سه بیشتر نشود).
    if (i < 0 or i + 1 >= len(rows_state)
            or len(rows_state[i]) + len(rows_state[i + 1]) > 3):
        await cb.answer("نامعتبر", show_alert=True)
        return
    merged = rows_state[i] + rows_state[i + 1]
    rows_state[i:i + 2] = [merged]
    await _thb_rows_save(row.id, rows_state)
    await cb.answer("✅ کنارِ هم قرار گرفتن")
    await _thbn_refresh(cb, row.id)


