# نکته: عمداً فقط دکمه‌هایی اینجا هستند که رنگشان واقعاً اعمال می‌شود.
# دکمه‌های داخلِ هاب‌های مشترک (کد تخفیف، عضویت اجباری و…) استایلِ ثابت
# دارند؛ آوردنشان یعنی همکار رنگ عوض کند و هیچ اتفاقی نیفتد — همان
# اشکالی که این تغییر برایِ رفعش نوشته شد.

# نگه‌داشتن IBTN_CATALOG برای سازگاری با کدهای قدیمی
IBTN_CATALOG: dict[str, str] = {
    k: v
    for _, group in (IBTN_CATALOG_GROUPS + IBTN_CATALOG_GROUPS_PARTNER)
    for k, v in group.items()
}

_IBTN_COLOR_EMOJI = {"danger": "🔴", "success": "🟢", "primary": "🔵"}
_IBTN_COLOR_LABEL = {"danger": "قرمز (Danger)", "success": "سبز (Success)", "primary": "آبی (Primary)"}
_IBTN_COLOR_STYLE = {
    "danger":  ButtonStyle.DANGER,
    "success": ButtonStyle.SUCCESS,
    "primary": ButtonStyle.PRIMARY,
}


# === PATCH_TENANT_ADMIN_COLORS_V1 ===
def _tadm_opt_style(label: str) -> ButtonStyle:
    """رنگِ یک آیتمِ زیرمنویِ پنل مدیریت از رویِ برچسبش."""
    if any(k in label for k in ("بازگشت", "خانه", "🏠", "⬅️", "حذف", "غیرفعال", "🗑")):
        return ButtonStyle.DANGER
    if any(k in label for k in ("افزودن", "ساخت", "جدید", "➕", "فعال‌سازی")):
        return ButtonStyle.SUCCESS
    return ButtonStyle.PRIMARY


# === PATCH_TENANT_ADMIN_COLORS_V1 ===
# رنگِ پیش‌فرضِ دکمه‌هایِ پنل مدیریت وقتی مالکِ ربات هنوز رنگی انتخاب نکرده.
# قبلاً ibtn_style در این حالت None برمی‌گرداند و کلِ پنل خاکستری بود.
# قاعده: بازگشت/خانه/حذف قرمز، افزودن/فعال‌سازی سبز، بقیه آبی.
_IBTN_DEFAULT_DANGER = ("_home", "_back", "_del", "_remove", "_off", "_cancel")
_IBTN_DEFAULT_SUCCESS = ("_add", "_new", "_on", "_save", "_confirm")

# کشِ «آیا این ربات فیچرِ دکمهٔ رنگی دارد؟» — پلنِ رایگان ندارد، پس
# پنلِ ربات‌های رایگان دقیقاً مثل قبل بی‌رنگ می‌ماند.
_IBTN_COLORED_CACHE: dict[int, tuple[bool, float]] = {}


# === PATCH_FREE_PLAN_NO_COLORS_V1 ===
# قبلاً این کش هیچ‌وقت باطل نمی‌شد؛ ارتقا/تنزلِ پلن تا ری‌استارتِ سرویس
# اثری نداشت. حالا مثلِ _SETTING_CACHE عمرِ کوتاه دارد.
_IBTN_COLORED_TTL = 60.0


async def _ibtn_colored_allowed(bot_id: int) -> bool:
    import time as _time
    cached = _IBTN_COLORED_CACHE.get(bot_id)
    if cached is not None and cached[1] > _time.monotonic():
        return cached[0]
    allowed = False
    try:
        async with Session() as s:
            row = await s.get(BotRow, bot_id)
            if row:
                allowed = has_feature(row.plan, Feature.COLORED_BUTTONS)
    except Exception:
        logger.exception("خواندنِ پلنِ ربات برایِ رنگِ دکمه‌ها ناموفق بود")
        return False
    _IBTN_COLORED_CACHE[bot_id] = (allowed, _time.monotonic() + _IBTN_COLORED_TTL)
    return allowed


def _ibtn_default_style(key: str) -> ButtonStyle:
    if any(k in key for k in _IBTN_DEFAULT_DANGER):
        return ButtonStyle.DANGER
    if any(k in key for k in _IBTN_DEFAULT_SUCCESS):
        return ButtonStyle.SUCCESS
    return ButtonStyle.PRIMARY


async def ibtn_style(bot_id: int, key: str) -> ButtonStyle | None:
    """رنگِ ذخیره‌شده برای یک دکمهٔ اینلاین را از Setting برمی‌گرداند.

    === PATCH_TENANT_ADMIN_COLORS_V1 ===
    اگر مالک رنگی انتخاب نکرده باشد، برایِ دکمه‌هایِ پنل مدیریت
    (کلیدهایِ ibtn:adm*) یک رنگِ پیش‌فرضِ معقول برمی‌گردد — البته فقط
    وقتی پلنِ ربات فیچرِ «دکمه‌های رنگی» را داشته باشد (یعنی نه رایگان).
    انتخابِ دستیِ مالک همیشه اولویت دارد.
    """
    # === PATCH_FREE_PLAN_NO_COLORS_V1 ===
    # باگ: انتخابِ دستیِ مالک بدونِ هیچ چکِ پلنی برگردانده می‌شد. یعنی
    # رباتی که زمانی حرفه‌ای بوده و به رایگان برگشته، رنگ‌هایش را نگه
    # می‌داشت؛ و هر رنگی که از طریقِ صفحهٔ رنگ (که خودش هم گِیت نداشت)
    # ذخیره شده بود، رویِ پلنِ رایگان هم اعمال می‌شد.
    if not await _ibtn_colored_allowed(bot_id):
        return None
    val = await get_setting(bot_id, key, "")
    style = _IBTN_COLOR_STYLE.get(val)
    if style is not None:
        return style
    if key.startswith("ibtn:adm"):
        return _ibtn_default_style(key)
    return None


# گروه‌ها/کلیدهایی که فقط برای زمینه‌های خاص معنا دارند — تا مثلاً رباتِ
# فروشگاهی در «مدیریت رنگ دکمه‌ها» اسمی از کانفیگ/VPN نبیند.
_IBTN_GROUP_FIELDS: dict[str, set[str]] = {
    "📦 سرویس‌های من (کانفیگ)": {"vpn_sales"},
    "🛒 خرید / پلن": {"vpn_sales"},
    "🤖 پنل مدیریت — VPN خودکار": {"vpn_sales"},
}
_IBTN_KEY_FIELDS: dict[str, set[str]] = {
    "ibtn:adm_cfg": {"vpn_sales"},
    "ibtn:adm_vpn": {"vpn_sales"},
    "ibtn:adm_shop": {"digital_shop"},
    "ibtn:adm_booking": {"booking"},
}


async def _ibtn_list_kb(bot_id: int) -> InlineKeyboardMarkup:
    """کیبورد لیست همه دکمه‌های کاتالوگ با رنگ فعلی‌شان، دسته‌بندی‌شده.
    گروه‌ها/کلیدهای مخصوصِ زمینه‌های دیگر (مثلاً VPN برای ربات فروشگاهی) نمایش داده نمی‌شوند."""
    async with Session() as s:
        _brow = await s.get(BotRow, bot_id)
    _field = _brow.field if _brow else ""
    # === PATCH_PARTNER_BTN_COLORS_V1 ===
    _is_partner = bool(_brow and _brow.plan == "partner")
    _groups = IBTN_CATALOG_GROUPS_PARTNER if _is_partner else IBTN_CATALOG_GROUPS
    rows = []
    for group_title, group_items in _groups:
        _gf = None if _is_partner else _IBTN_GROUP_FIELDS.get(group_title)
        if _gf is not None and _field not in _gf:
            continue
        items = [(k, v) for k, v in group_items.items()
                 if _is_partner or _IBTN_KEY_FIELDS.get(k) is None
                 or _field in _IBTN_KEY_FIELDS[k]]
        if not items:
            continue
        # سرتیتر گروه — دکمه غیرقابل کلیک
        rows.append([InlineKeyboardButton(
            text=f"┄┄ {group_title} ┄┄",
            callback_data="noop",
        )])
        for key, label in items:
            saved = await get_setting(bot_id, key, "")
            emoji = _IBTN_COLOR_EMOJI.get(saved, "⚪️")
            style = _IBTN_COLOR_STYLE.get(saved)
            short = key.replace("ibtn:", "")
            rows.append([InlineKeyboardButton(
                text=f"{emoji} {label}",
                callback_data=f"mbc:pick:{short}",
                style=style,
            )])
    # === PATCH_PARTNER_BTN_COLORS_V1 ===
    rows.append([InlineKeyboardButton(
        text="⬅️ بازگشت",
        callback_data=("pp:home" if _is_partner else "tadm:sec:settings"),
        style=ButtonStyle.DANGER,
    )])
    return InlineKeyboardMarkup(inline_keyboard=rows)


@tenant_router.callback_query(F.data == "tadm:btn_colors")
async def tadm_btn_colors(cb: CallbackQuery, bot: Bot):
    # === PATCH_FREE_PLAN_NO_COLORS_V1 ===
    # گِیتِ واقعی: پنهان‌کردنِ دکمه کافی نیست، چون کیبوردهایِ قدیمی هنوز
    # در چتِ مالک‌ها هستند و callback همچنان می‌رسد.
    row = await _gate(cb, bot, Feature.COLORED_BUTTONS)
    if not row:
        return
    await cb.answer()
    kb = await _ibtn_list_kb(row.id)
    await cb.message.edit_text(
        "🎨 <b>مدیریت رنگ دکمه‌های اینلاین</b>\n\n"
        "رنگ فعلی هر دکمه روی خودش نمایش داده شده.\n"
        "روی هر دکمه بزن تا رنگش را تغییر دهی:\n\n"
        "🔴 قرمز | 🟢 سبز | 🔵 آبی | ⚪️ پیش‌فرض",
        reply_markup=kb,
    )


@tenant_router.callback_query(F.data.startswith("mbc:pick:"))
async def mbc_pick(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    short = cb.data.split(":", 2)[2]        # e.g. "renew"
    key = f"ibtn:{short}"
    label = IBTN_CATALOG.get(key, key)
    cur_color = await get_setting(row.id, key, "")
    cur_emoji = _IBTN_COLOR_EMOJI.get(cur_color, "⚪️")
    cur_label = _IBTN_COLOR_LABEL.get(cur_color, "پیش‌فرض")

    def _cell(val: str, txt: str, bstyle):
        mark = "✅ " if (cur_color == val) or (val == "none" and not cur_color) else ""
        kw = {"text": mark + txt, "callback_data": f"mbc:set:{short}:{val}"}
        if bstyle:
            kw["style"] = bstyle
        return InlineKeyboardButton(**kw)

    kb = InlineKeyboardMarkup(inline_keyboard=[
        [
            _cell("danger",  "🔴 قرمز",  ButtonStyle.DANGER),
            _cell("success", "🟢 سبز",   ButtonStyle.SUCCESS),
            _cell("primary", "🔵 آبی",   ButtonStyle.PRIMARY),
        ],
        [_cell("none", "⚪️ بی‌رنگ", None)],
        [InlineKeyboardButton(text="⬅️ بازگشت", callback_data="tadm:btn_colors",
                              style=ButtonStyle.DANGER)],
    ])
    await cb.message.edit_text(
        f"🎨 <b>رنگ دکمه:</b> {label}\n\n"
        f"رنگ فعلی: {cur_emoji} {cur_label}\n\n"
        "کدام رنگ را می‌خواهی؟",
        reply_markup=kb,
    )
    await cb.answer()


@tenant_router.callback_query(F.data.startswith("mbc:set:"))
async def mbc_setcolor(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    parts = cb.data.split(":")          # ["mbc","set","renew","danger"]
    short, color_val = parts[2], parts[3]
    key = f"ibtn:{short}"
    await set_setting(row.id, key, "" if color_val == "none" else color_val)
    label = ("⚪️ بی‌رنگ" if color_val == "none"
             else _IBTN_COLOR_EMOJI.get(color_val, "") + " " + _IBTN_COLOR_LABEL.get(color_val, ""))
    await cb.answer(f"✅ رنگ ذخیره شد: {label}", show_alert=True)
    # بازگشت به لیست با رنگ‌های به‌روز
    kb = await _ibtn_list_kb(row.id)
    await cb.message.edit_text(
        "🎨 <b>مدیریت رنگ دکمه‌های اینلاین</b>\n\n"
        "رنگ فعلی هر دکمه روی خودش نمایش داده شده.\n"
        "روی هر دکمه بزن تا رنگش را تغییر دهی:\n\n"
        "🔴 قرمز | 🟢 سبز | 🔵 آبی | ⚪️ پیش‌فرض",
        reply_markup=kb,
    )


@tenant_router.callback_query(F.data.startswith("thb:pick:"))
async def thb_pick(cb: CallbackQuery, bot: Bot, state: FSMContext):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    mb_id = int(cb.data.split(":")[2])
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
    if not mb or mb.bot_id != row.id:
        await cb.answer("یافت نشد", show_alert=True)
        return
    await state.clear()
    is_dis = mb_id in await _disabled_btn_ids(row.id)
    await cb.message.edit_text(_thb_text(mb, is_dis), reply_markup=_thb_kb(mb, is_dis))
    await cb.answer()


@tenant_router.callback_query(F.data.startswith("thb:toggle:"))
async def thb_toggle(cb: CallbackQuery, bot: Bot, state: FSMContext):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    mb_id = int(cb.data.split(":")[2])
