# === PATCH_DUPLICATE_BUTTON_LABEL_WARN_V1 ===
# ربات دکمه‌هایِ کیبوردی را از رویِ *متن* پیدا می‌کند، پس دو دکمه با یک
# نام قابلِ تفکیک نیستند و ربات ممکن است اشتباهی را اجرا کند — دقیقاً
# همان چیزی که باعثِ گزارشِ «دکمهٔ خرید تست می‌آورد» شد. این خرابی کاملاً
# بی‌صداست و کسی حدس نمی‌زند علتش نامِ تکراری باشد، پس همان لحظهٔ
# نام‌گذاری هشدار می‌دهیم. جلویِ کار را نمی‌گیریم؛ گاهی عمدی است.
async def _duplicate_label_note(bot_id: int, label: str,
                                exclude_id: int | None = None) -> str:
    label = (label or "").strip()
    if not label:
        return ""
    try:
        async with Session() as s:
            q = select(MainButton).where(MainButton.bot_id == bot_id,
                                         MainButton.label == label)
            if exclude_id:
                q = q.where(MainButton.id != exclude_id)
            others = (await s.scalars(q)).all()
        if not others:
            return ""
        acts = "، ".join(sorted({(b.action or "بدونِ عملکرد") for b in others}))
        return ("\n\n⚠️ <b>نامِ تکراری!</b>\n"
                f"دکمهٔ دیگری با همین نام وجود دارد (عملکرد: {acts}).\n"
                "ربات دکمه‌ها را از رویِ نامشان تشخیص می‌دهد، پس ممکن است "
                "اشتباهی را اجرا کند. بهتر است یکی‌شان را تغییرِ نام بدهی.")
    except Exception:
        logger.exception("بررسیِ نامِ تکراریِ دکمه ناموفق بود")
        return ""


@tenant_router.callback_query(F.data.startswith("thb:ren:"))
async def thb_ren_start(cb: CallbackQuery, bot: Bot, state: FSMContext):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    mb_id = int(cb.data.split(":")[2])
    await state.set_state(HomeBtnFSM.rename)
    await state.update_data(thb_id=mb_id)
    try:
        await cb.message.edit_reply_markup(reply_markup=None)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.message.answer("📝 اسم جدید دکمه را بنویس:", reply_markup=await smart_cancel_kb(bot))
    await cb.answer()


@tenant_router.message(HomeBtnFSM.rename, F.text)
async def thb_ren_save(msg: Message, bot: Bot, state: FSMContext):
    row = await get_bot_row(bot)
    if not row or not await is_owner_or_admin(row.id, msg.from_user.id, row.owner_id):
        await state.clear()
        return
    data = await state.get_data()
    mb_id = data.get("thb_id")
    new_label = (msg.text or "").strip()
    await state.clear()
    kb = await main_kb_or_remove(row.id, row.owner_id, msg.from_user.id)
    if new_label in ("❌ لغو", "❌ لغو / بازگشت"):
        await msg.answer("لغو شد.", reply_markup=kb or ReplyKeyboardRemove())
        return
    if not new_label or not mb_id:
        await msg.answer("نامعتبر بود.", reply_markup=kb or ReplyKeyboardRemove())
        return
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
        if mb and mb.bot_id == row.id:
            mb.label = new_label[:80]
            await s.commit()
    # === PATCH_THB_RETURN_TO_SETTINGS_V1 ===
    # قبلاً بعدِ ذخیره، کیبوردِ اصلیِ ربات (همون که مشتری می‌بینه) نشون داده
    # می‌شد، نه صفحهٔ تنظیماتِ همون دکمه‌ای که ادمین داشت روش کار می‌کرد —
    # یعنی ادمین باید دوباره از اول می‌رفت تویِ دکمه‌ها تا ادامه بده.
    note = await _duplicate_label_note(row.id, new_label[:80], exclude_id=mb_id)
    if mb and mb.bot_id == row.id:
        is_disabled = mb_id in await _disabled_btn_ids(row.id)
        await msg.answer(f"✅ نام دکمه به «{new_label[:80]}» تغییر یافت." + note)
        await msg.answer(_thb_text(mb, is_disabled), reply_markup=_thb_kb(mb, is_disabled))
    else:
        kb = await main_kb_or_remove(row.id, row.owner_id, msg.from_user.id)
        await msg.answer(f"✅ نام دکمه به «{new_label[:80]}» تغییر یافت." + note,
                         reply_markup=kb or ReplyKeyboardRemove())


# ───── کد تخفیف اختصاصیِ دکمه (فقط دکمه‌های «خرید کانفیگ») ─────

async def _exdisc_get(bot_id: int, mb_id: int) -> "DiscountCode | None":
    async with Session() as s:
        return await s.scalar(select(DiscountCode).where(
            DiscountCode.bot_id == bot_id, DiscountCode.button_id == mb_id))


def _exdisc_text(mb, dc) -> str:
    if not dc:
        return (
            "🏷 <b>کد تخفیف اختصاصی این دکمه</b>\n\n"
            "این کد فقط در جریانِ خریدِ همین دکمه قابل استفاده است و در بقیهٔ ربات کار نمی‌کند.\n\n"
            "فعلاً کدی برای این دکمه ساخته نشده."
        )
    status = "🟢 فعال" if dc.is_active else "🔴 غیرفعال"
    if dc.expires_at and dc.expires_at < _dt.datetime.utcnow():
        status = "⌛️ منقضی‌شده"
    exp_disp = _fmt_exp_jalali(dc.expires_at, with_time=False) if dc.expires_at else "ندارد"
    if (dc.disc_type or "percent") == "amount":
        value_disp = f"{int(round(float(dc.amount or 0))):,} تومان"
    else:
        value_disp = f"{dc.percent}٪"
    max_disp = "نامحدود" if not dc.max_uses else f"{dc.max_uses} بار"
    used_disp = f"{dc.used_count or 0}"
    user_disp = f"<code>{dc.restricted_user_id}</code>" if dc.restricted_user_id else "برای همه (بدون محدودیت)"
    return (
        "🏷 <b>کد تخفیف اختصاصی این دکمه</b>\n\n"
        f"کد: <code>{dc.code}</code>\n"
        f"نوع تخفیف: <b>{'مبلغ ثابت (تومان)' if (dc.disc_type or 'percent') == 'amount' else 'درصدی'}</b>\n"
        f"مقدار تخفیف: <b>{value_disp}</b>\n"
        f"سقف تعداد استفاده: <b>{max_disp}</b> (تاکنون مصرف‌شده: {used_disp})\n"
        f"اختصاص به کاربر: {user_disp}\n"
        f"وضعیت: {status}\n"
        f"تاریخ انقضا (شمسی): {exp_disp}\n\n"
        "این کد فقط در جریانِ خریدِ همین دکمه قابل استفاده است؛ روی بستهٔ فروشِ دکمهٔ دیگری کار نمی‌کند."
    )


def _exdisc_kb(mb, dc) -> InlineKeyboardMarkup:
    rows = []
    if not dc:
        rows.append([InlineKeyboardButton(text="➕ ساخت کد تخفیف اختصاصی",
                                          callback_data=f"thb:exdisc:setcode:{mb.id}", style=ButtonStyle.SUCCESS)])
    else:
        rows.append([InlineKeyboardButton(text="✏️ تغییر کد", callback_data=f"thb:exdisc:setcode:{mb.id}", style=ButtonStyle.PRIMARY)])
        is_amount = (dc.disc_type or "percent") == "amount"
        rows.append([InlineKeyboardButton(
            text=("💵 تغییر به تخفیف درصدی" if is_amount else "💰 تغییر به تخفیف تومانی"),
            callback_data=f"thb:exdisc:disctype:{mb.id}", style=ButtonStyle.PRIMARY)])
        if is_amount:
            rows.append([InlineKeyboardButton(text="🔢 تغییر مبلغ تخفیف (تومان)",
                                              callback_data=f"thb:exdisc:setamount:{mb.id}", style=ButtonStyle.PRIMARY)])
        else:
            rows.append([InlineKeyboardButton(text="🔢 تغییر درصد تخفیف",
                                              callback_data=f"thb:exdisc:setpercent:{mb.id}", style=ButtonStyle.PRIMARY)])
        rows.append([InlineKeyboardButton(text="🎯 سقف تعداد دفعات استفاده",
                                          callback_data=f"thb:exdisc:setmaxuses:{mb.id}", style=ButtonStyle.PRIMARY)])
        rows.append([InlineKeyboardButton(text="👤 اختصاص به یک کاربر خاص",
                                          callback_data=f"thb:exdisc:setuser:{mb.id}", style=ButtonStyle.PRIMARY)])
        if dc.restricted_user_id:
            rows.append([InlineKeyboardButton(text="♻️ حذف اختصاص کاربر (باز کردن برای همه)",
                                              callback_data=f"thb:exdisc:clearuser:{mb.id}", style=ButtonStyle.DANGER)])
        rows.append([InlineKeyboardButton(text="📅 تاریخ انقضا (شمسی)",
                                          callback_data=f"thb:exdisc:setexpire:{mb.id}", style=ButtonStyle.PRIMARY)])
        if dc.expires_at:
            rows.append([InlineKeyboardButton(text="♾️ حذف انقضا",
                                              callback_data=f"thb:exdisc:clearexpire:{mb.id}", style=ButtonStyle.DANGER)])
        rows.append([InlineKeyboardButton(
            text=("⛔️ غیرفعال‌سازی" if dc.is_active else "✅ فعال‌سازی"),
            callback_data=f"thb:exdisc:toggle:{mb.id}", style=ButtonStyle.DANGER)])
        rows.append([InlineKeyboardButton(text="🗑 حذف کد", callback_data=f"thb:exdisc:del:{mb.id}", style=ButtonStyle.DANGER)])
    rows.append(_thb_back_row(mb))
    return InlineKeyboardMarkup(inline_keyboard=rows)


@tenant_router.callback_query(F.data.startswith("thb:exdisc:"))
async def thb_exdisc(cb: CallbackQuery, bot: Bot, state: FSMContext):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    parts = cb.data.split(":")
    sub = parts[2]
    if sub.isdigit():
        action, mb_id = "view", int(sub)
    else:
        action, mb_id = sub, int(parts[3])
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
    _gated_keep_ed = None
    if mb and mb.action == "referral_gate" and mb.config:
        try:
            _gated_keep_ed = (json.loads(mb.config) or {}).get("keep_action")
        except Exception:
            _gated_keep_ed = None
    if not mb or mb.bot_id != row.id:
        await cb.answer("یافت نشد", show_alert=True)
        return
    _ok_exd = (mb.action in _EXDISC_SALE_ACTIONS or _is_panel_buy_action(mb.action)
               or _gated_keep_ed in _EXDISC_SALE_ACTIONS or _is_panel_buy_action(_gated_keep_ed))
    if not _ok_exd:
        await cb.answer("یافت نشد", show_alert=True)
        return

    if action == "view":
        dc = await _exdisc_get(row.id, mb_id)
        await cb.message.edit_text(_exdisc_text(mb, dc), reply_markup=_exdisc_kb(mb, dc))
        await cb.answer()
        return

    if action == "setcode":
        await state.set_state(HomeBtnFSM.exdisc_code)
        await state.update_data(exdisc_mb=mb_id)
        try:
            await cb.message.edit_reply_markup(reply_markup=None)
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        await cb.message.answer(
            "🏷 کد تخفیف اختصاصی را بفرست (فقط حروف/عدد انگلیسی، بدون فاصله):",
            reply_markup=await smart_cancel_kb(bot))
        await cb.answer()
        return

    if action == "setpercent":
        dc = await _exdisc_get(row.id, mb_id)
        if not dc:
            await cb.answer("اول باید کد را بسازی.", show_alert=True)
            return
        await state.set_state(HomeBtnFSM.exdisc_percent)
        await state.update_data(exdisc_mb=mb_id)
        try:
            await cb.message.edit_reply_markup(reply_markup=None)
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        await cb.message.answer("🔢 درصد تخفیف را به عدد بفرست (بین ۱ تا ۱۰۰):",
                                reply_markup=await smart_cancel_kb(bot))
        await cb.answer()
        return

    if action == "disctype":
        async with Session() as s:
            dc = await s.scalar(select(DiscountCode).where(
                DiscountCode.bot_id == row.id, DiscountCode.button_id == mb_id))
            if not dc:
                await cb.answer("اول باید کد را بسازی.", show_alert=True)
                return
            dc.disc_type = "amount" if (dc.disc_type or "percent") == "percent" else "percent"
            await s.commit()
        dc = await _exdisc_get(row.id, mb_id)
        await cb.message.edit_text(_exdisc_text(mb, dc), reply_markup=_exdisc_kb(mb, dc))
        await cb.answer("✅ نوع تخفیف تغییر یافت")
        return

    if action == "setamount":
        dc = await _exdisc_get(row.id, mb_id)
        if not dc:
            await cb.answer("اول باید کد را بسازی.", show_alert=True)
            return
        await state.set_state(HomeBtnFSM.exdisc_amount)
        await state.update_data(exdisc_mb=mb_id)
        try:
            await cb.message.edit_reply_markup(reply_markup=None)
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        await cb.message.answer("💰 مبلغ ثابتِ تخفیف را به تومان و به عدد بفرست:",
                                reply_markup=await smart_cancel_kb(bot))
        await cb.answer()
        return

    if action == "setmaxuses":
        dc = await _exdisc_get(row.id, mb_id)
        if not dc:
            await cb.answer("اول باید کد را بسازی.", show_alert=True)
            return
        await state.set_state(HomeBtnFSM.exdisc_maxuses)
        await state.update_data(exdisc_mb=mb_id)
        try:
            await cb.message.edit_reply_markup(reply_markup=None)
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        await cb.message.answer(
            "🎯 سقف تعداد دفعاتِ مجازِ استفاده از این کد را به عدد بفرست\n"
            "(مثلاً <code>1</code> برای یک‌بار مصرف، <code>2</code> برای دو بار و ...).\n"
            "برای «نامحدود» عدد <code>0</code> بفرست:",
            reply_markup=await smart_cancel_kb(bot))
        await cb.answer()
        return

    if action == "setuser":
        dc = await _exdisc_get(row.id, mb_id)
        if not dc:
            await cb.answer("اول باید کد را بسازی.", show_alert=True)
            return
        await state.set_state(HomeBtnFSM.exdisc_userid)
        await state.update_data(exdisc_mb=mb_id)
        try:
            await cb.message.edit_reply_markup(reply_markup=None)
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        await cb.message.answer(
            "👤 آیدی عددیِ تلگرامِ کاربری که این کد فقط برای او کار کند را بفرست\n"
            "(همان عددی که مثلاً ربات‌هایی مثل @userinfobot می‌دهند):",
            reply_markup=await smart_cancel_kb(bot))
        await cb.answer()
        return

    if action == "clearuser":
        async with Session() as s:
            dc = await s.scalar(select(DiscountCode).where(
                DiscountCode.bot_id == row.id, DiscountCode.button_id == mb_id))
            if dc:
                dc.restricted_user_id = None
                await s.commit()
        dc = await _exdisc_get(row.id, mb_id)
        await cb.message.edit_text(_exdisc_text(mb, dc), reply_markup=_exdisc_kb(mb, dc))
        await cb.answer("♻️ اختصاصِ کاربر حذف شد")
        return

    if action == "setexpire":
        dc = await _exdisc_get(row.id, mb_id)
        if not dc:
            await cb.answer("اول باید کد را بسازی.", show_alert=True)
            return
        await state.set_state(HomeBtnFSM.exdisc_expire)
        await state.update_data(exdisc_mb=mb_id)
        try:
            await cb.message.edit_reply_markup(reply_markup=None)
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        await cb.message.answer(
            "📅 تاریخ انقضا را به شمسی و به این فرمت بفرست:\n"
            "<code>YYYY-MM-DD</code>  مثال: <code>1404-10-15</code>",
            reply_markup=await smart_cancel_kb(bot))
        await cb.answer()
        return

    if action == "clearexpire":
        async with Session() as s:
            dc = await s.scalar(select(DiscountCode).where(
                DiscountCode.bot_id == row.id, DiscountCode.button_id == mb_id))
            if dc:
                dc.expires_at = None
                await s.commit()
        dc = await _exdisc_get(row.id, mb_id)
        await cb.message.edit_text(_exdisc_text(mb, dc), reply_markup=_exdisc_kb(mb, dc))
        await cb.answer("♾️ انقضا حذف شد")
        return

    if action == "toggle":
        async with Session() as s:
            dc = await s.scalar(select(DiscountCode).where(
                DiscountCode.bot_id == row.id, DiscountCode.button_id == mb_id))
            if not dc:
                await cb.answer("یافت نشد", show_alert=True)
                return
            dc.is_active = not dc.is_active
            await s.commit()
        dc = await _exdisc_get(row.id, mb_id)
        await cb.message.edit_text(_exdisc_text(mb, dc), reply_markup=_exdisc_kb(mb, dc))
        await cb.answer("✅ به‌روزرسانی شد")
        return

    if action == "del":
        async with Session() as s:
            dc = await s.scalar(select(DiscountCode).where(
                DiscountCode.bot_id == row.id, DiscountCode.button_id == mb_id))
            if dc:
                # === PATCH_EXDISC_DEL_FK_FIX_V1 ===
                # قبل از حذفِ خودِ کد، ردیف‌های مصرفِ آن (DiscountUsage) را هم پاک
                # کن؛ وگرنه اگر کد حداقل یک‌بار استفاده شده باشد، Postgres به‌خاطرِ
                # foreign key اجازهٔ حذف نمی‌دهد و کل عملیات با خطا مواجه می‌شود.
                usages = (await s.scalars(
                    select(DiscountUsage).where(DiscountUsage.discount_code_id == dc.id)
                )).all()
                for u in usages:
                    await s.delete(u)
                await s.delete(dc)
                await s.commit()
        await cb.message.edit_text(_exdisc_text(mb, None), reply_markup=_exdisc_kb(mb, None))
        await cb.answer("🗑 حذف شد")
        return


@tenant_router.message(HomeBtnFSM.exdisc_code, F.text)
async def thb_exdisc_code_save(msg: Message, bot: Bot, state: FSMContext):
    row = await get_bot_row(bot)
    if not row or not await is_owner_or_admin(row.id, msg.from_user.id, row.owner_id):
        await state.clear()
        return
    data = await state.get_data()
    mb_id = data.get("exdisc_mb")
    raw = (msg.text or "").strip()
    kb = await main_kb_or_remove(row.id, row.owner_id, msg.from_user.id)
    if raw in ("❌ لغو", "❌ لغو / بازگشت"):
        await state.clear()
        await msg.answer("لغو شد.", reply_markup=kb or ReplyKeyboardRemove())
        return
    code = re.sub(r"[^A-Za-z0-9_-]", "", raw).upper()[:40]
    if not code or not mb_id:
        await msg.answer("کد نامعتبر است؛ فقط حروف/عدد انگلیسی مجاز است. دوباره بفرست:")
        return
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
        if not mb or mb.bot_id != row.id:
            await state.clear()
            await msg.answer("دکمه یافت نشد.", reply_markup=kb or ReplyKeyboardRemove())
            return
        from sqlalchemy import or_
        dup = await s.scalar(select(DiscountCode).where(
            DiscountCode.bot_id == row.id, func.upper(DiscountCode.code) == code,
            or_(DiscountCode.button_id.is_(None), DiscountCode.button_id != mb_id)))
        if dup:
            await msg.answer("این کد قبلاً برای جای دیگری استفاده شده؛ کد دیگری بفرست:")
            return
        dc = await s.scalar(select(DiscountCode).where(
            DiscountCode.bot_id == row.id, DiscountCode.button_id == mb_id))
        if dc:
            dc.code = code
        else:
            dc = DiscountCode(bot_id=row.id, code=code, percent=10, disc_type="percent",
                              is_active=True, button_id=mb_id)
            s.add(dc)
        await s.commit()
    await state.clear()
    await msg.answer(f"✅ کد اختصاصی «{code}» ثبت شد.", reply_markup=kb or ReplyKeyboardRemove())
    await msg.answer("ادامهٔ مدیریت 👇", reply_markup=InlineKeyboardMarkup(inline_keyboard=[[
        InlineKeyboardButton(text="🏷 مدیریت کد تخفیف اختصاصی", callback_data=f"thb:exdisc:{mb_id}", style=ButtonStyle.PRIMARY)
    ]]))


@tenant_router.message(HomeBtnFSM.exdisc_percent, F.text)
async def thb_exdisc_percent_save(msg: Message, bot: Bot, state: FSMContext):
    row = await get_bot_row(bot)
    if not row or not await is_owner_or_admin(row.id, msg.from_user.id, row.owner_id):
        await state.clear()
        return
    data = await state.get_data()
    mb_id = data.get("exdisc_mb")
