@tenant_router.callback_query(F.data == "thb:add")
async def thb_add_start(cb: CallbackQuery, bot: Bot, state: FSMContext):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    await state.set_state(HomeBtnFSM.new_label)
    try:
        await cb.message.edit_reply_markup(reply_markup=None)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.message.answer(
        "➕ نامِ دکمهٔ جدید را بنویس (همان متنی که روی دکمه دیده می‌شود):",
        reply_markup=await smart_cancel_kb(bot),
    )
    await cb.answer()


@tenant_router.message(HomeBtnFSM.new_label, F.text)
async def thb_add_save(msg: Message, bot: Bot, state: FSMContext):
    row = await get_bot_row(bot)
    if not row or not await is_owner_or_admin(row.id, msg.from_user.id, row.owner_id):
        await state.clear()
        return
    label = (msg.text or "").strip()
    data = await state.get_data()
    parent_id = data.get("sub_parent")
    await state.clear()
    kb = await main_kb_or_remove(row.id, row.owner_id, msg.from_user.id)
    if label in ("❌ لغو", "❌ لغو / بازگشت"):
        await msg.answer("لغو شد.", reply_markup=kb or ReplyKeyboardRemove())
        return
    if not label:
        await msg.answer("نام نامعتبر بود.", reply_markup=kb or ReplyKeyboardRemove())
        return
    label = label[:80]
    async with Session() as s:
        dup = await s.scalar(select(MainButton).where(
            MainButton.bot_id == row.id, MainButton.label == label))
        if dup:
            # === PATCH_DUPLICATE_BUTTON_LABEL_WARN_V1 ===
            # پیامِ قبلی نمی‌گفت دکمهٔ هم‌نام کجاست؛ وقتی در زیرمنویِ دیگری
            # بود، مالک فکر می‌کرد ربات اشتباه می‌کند.
            _where = "در همین صفحه" if dup.parent_id is None else "در یکی از زیرمنوها"
            await msg.answer(
                f"⛔️ دکمه‌ای با همین نام از قبل وجود دارد ({_where}، عملکرد: "
                f"{dup.action or 'ندارد'}).\n\n"
                "ربات دکمه‌ها را از رویِ نامشان تشخیص می‌دهد، پس دو دکمهٔ "
                "هم‌نام قابلِ تفکیک نیستند. یک نامِ دیگر انتخاب کن.",
                reply_markup=kb or ReplyKeyboardRemove())
            return
        mx = await s.scalar(select(func.max(MainButton.row)).where(
            MainButton.bot_id == row.id,
            (MainButton.parent_id == parent_id) if parent_id else MainButton.parent_id.is_(None)))
        new_row = (mx if mx is not None else -1) + 1
        if parent_id:
            par = await s.get(MainButton, parent_id)
            if not par or par.bot_id != row.id or par.action != "submenu":
                await msg.answer("زیرمنوی والد یافت نشد.", reply_markup=kb or ReplyKeyboardRemove())
                return
        mb = MainButton(bot_id=row.id, row=new_row, col=0, label=label,
                        action=None, message=None, parent_id=parent_id)
        s.add(mb)
        await s.commit()
        mb_id = mb.id
    kb = await main_kb_or_remove(row.id, row.owner_id, msg.from_user.id)
    await msg.answer(
        f"✅ دکمهٔ «{label}» ساخته شد.\n"
        "حالا با «✏️ تنظیم متنِ دکمه» تعیین کن وقتی کاربر این دکمه را زد چه پیامی ببیند.",
        reply_markup=kb or ReplyKeyboardRemove(),
    )
    # مرحلهٔ بعد: انتخاب رنگ دکمه (مثل ربات‌ساز) — دومرحله‌ای با «ثبت رنگ»
    colored = has_feature(row.plan, Feature.COLORED_BUTTONS)
    note = ""
    if not colored:
        note = "\n\n⚠️ رنگی‌شدن دکمه فقط در پلن‌های رشد/حرفه‌ای نمایش داده می‌شود."
    await msg.answer(
        "🎨 مرحلهٔ ۲: یک رنگ انتخاب کن، سپس «✅ ثبت رنگ» را بزن تا اعمال شود:" + note,
        reply_markup=_thb_color_kb(mb_id, "", colored))


# === PATCH_TRIAL_WIZARD ===
_TRIAL_MODE_LABELS = {"manual": "📦 کانفیگ آماده (محدود)",
                      "unlimited": "♾️ کانفیگ نامحدود",
                      "auto": "🤖 کانفیگ خودکار (ساخت از پنل)"}
_TRIAL_SELECT_LABELS = {"fixed": "📌 دستی (مقدار ثابت)",
                        "range": "➕➖ بازه‌ای (کاربر خودش انتخاب کند)"}


def _trial_mode_of(mb) -> str | None:
    if not getattr(mb, "config", None):
        return None
    try:
        m = (json.loads(mb.config) or {}).get("trial_mode")
    except Exception:
        return None
    return m if m in _TRIAL_MODE_LABELS else None


def _trial_cfg_of(mb) -> dict:
    if not getattr(mb, "config", None):
        return {}
    try:
        return json.loads(mb.config) or {}
    except Exception:
        return {}


# === PATCH_TRIAL_GLOBAL_FALLBACK_V1 ===
# گزارشِ تیکت #849: «دو جا تنظیمِ تستِ رایگان هست؛ اونی که تویِ پنل مدیریت (تنظیمات تست رایگان) هست کار نمی‌کنه».
# ریشه: دکمهٔ «تست رایگان» تنظیمِ اختصاصیِ خودش را دارد و ویزاردِ دکمه با «✅ ثبت» مقدارهایِ پیش‌فرضِ ثابتِ ۲ گیگ/۳ روز را
# در دکمه می‌نوشت؛ پس مقدارِ تنظیماتِ کلیِ ربات هیچ‌وقت خوانده نمی‌شد. حالا هر مقداری که روی دکمه صراحتاً ثبت نشده باشد
# (حجم/مدت) از «تنظیماتِ تستِ رایگان» ربات می‌آید؛ مقدارِ صریحِ دکمه همچنان اولویت دارد.
# === PATCH_TRIAL_STALE_PANEL_KEYS_V1 ===
# تیکت #849 (دورِ سوم): دکمهٔ تست «upanel_mizban,pasargad» را نگه داشته بود در حالی که پنلِ یوپنل دیگر وجود نداشت (جایش مرزبان
# وصل شده بود). صفحهٔ انتخابِ پنل فقط پنل‌هایِ فعالِ فعلی را نشان می‌دهد، پس کلیدِ مرده دیده نمی‌شد و با هر تیک هم ذخیره می‌ماند؛
# نتیجه: نیمی از تست‌ها «کلیدِ مرده» را رندوم می‌کردند و به «اولین پنلِ فعال» می‌افتادند — یعنی از پنلِ دیگر هم ساخته می‌شد.
async def _trial_enabled_panel_keys(bot_id: int) -> list[str]:
    from models import VpnPanel
    async with Session() as s:
        return [k for k in (await s.scalars(select(VpnPanel.panel_key).where(
            VpnPanel.bot_id == bot_id, VpnPanel.enabled == True).order_by(VpnPanel.id))).all() if k]  # noqa: E712


async def _trial_pick_panel_key(bot_id: int, btn_cfg: dict) -> str | None:
    """پنلِ این تست: اگر چند پنل تیک خورده، رندوم فقط بینِ پنل‌هایی که همین الان فعال‌اند؛ وگرنه کلیدِ تکی. None = اولین پنلِ فعال."""
    raw = (btn_cfg.get("trial_panel_keys") or "").strip()
    if not raw:
        return btn_cfg.get("trial_panel_key")
    import random as _random
    keys = [k for k in raw.split(",") if k]
    live = set(await _trial_enabled_panel_keys(bot_id))
    ok = [k for k in keys if k in live]
    if keys and not ok:
        logger.warning("تستِ رایگان: هیچ‌کدام از پنل‌هایِ تیک‌خوردهٔ دکمه (%s) فعال نیست؛ اولین پنلِ فعال (bot_id=%s)", raw, bot_id)
    return _random.choice(ok) if ok else None


async def _trial_prune_panel_keys(mb_id: int, bot_id: int) -> bool:
    """کلیدهایِ پنلِ حذف/غیرفعال‌شده را از تنظیماتِ دکمه پاک می‌کند. True اگر چیزی عوض شد."""
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
    if not mb or mb.bot_id != bot_id:
        return False
    keys = [k for k in (_trial_cfg_of(mb).get("trial_panel_keys") or "").split(",") if k]
    if not keys:
        return False
    live = set(await _trial_enabled_panel_keys(bot_id))
    kept = [k for k in keys if k in live]
    if len(kept) == len(keys):
        return False
    await _trial_cfg_update(mb_id, trial_panel_keys=(",".join(kept) if kept else None))
    return True


async def _trial_fill_global(bot_id: int, cfg: dict | None) -> dict:
    out = dict(cfg or {})
    filled = []
    # === PATCH_TRIAL_GLOBAL_DIFF_V1 === مقدارِ اختصاصیِ دکمه که با «تنظیماتِ تستِ رایگان» فرق دارد (برایِ هشدار در صفحه)
    diffs = []
    try:
        if "trial_gb" in out:
            _g = float(await get_setting(bot_id, "trial_gb", "2"))
            if abs(float(out["trial_gb"]) - _g) > 1e-9:
                diffs.append(("gb", str(out["trial_gb"]), str(_g)))
        if "trial_days" in out or "trial_hours" in out:
            _gd = (int(float(await get_setting(bot_id, "trial_days", "3"))), int(float(await get_setting(bot_id, "trial_hours", "0") or 0)))
            _bd = (int(float(out.get("trial_days", 0) or 0)), int(float(out.get("trial_hours", 0) or 0)))
            if _bd != _gd:
                diffs.append(("duration", f"{_bd[0]}d{_bd[1]}h", f"{_gd[0]}d{_gd[1]}h"))
    except (TypeError, ValueError):
        diffs = []
    if diffs:
        out["_global_diff"] = diffs
    if "trial_gb" not in out:
        out["trial_gb"] = str(await get_setting(bot_id, "trial_gb", "2"))
        filled.append("gb")
    if "trial_days" not in out and "trial_hours" not in out:     # مدت یک واحد است (روز+ساعت)
        out["trial_days"] = str(await get_setting(bot_id, "trial_days", "3"))
        _h = str(await get_setting(bot_id, "trial_hours", "0"))
        if _h not in ("", "0"):
            out["trial_hours"] = _h
        filled.append("duration")
    if filled:
        out["_from_global"] = filled
    return out


async def _trial_cfg_update(mb_id: int, **updates) -> dict | None:
    """به‌روزرسانیِ چند کلید از config یک دکمهٔ تست و ذخیرهٔ آن. مقادیرِ None
    حذف می‌شوند. (خروجی برایِ نمایش با مقدارهایِ تنظیماتِ کلی پُر می‌شود؛ ذخیره‌شده فقط مقدارهایِ صریح است.)"""
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
        if not mb:
            return None
        cfg = {}
        if mb.config:
            try:
                cfg = json.loads(mb.config) or {}
            except Exception:
                cfg = {}
        for k, v in updates.items():
            if v is None:
                cfg.pop(k, None)
            else:
                cfg[k] = v
        mb.config = json.dumps(cfg, ensure_ascii=False) if cfg else None
        await s.commit()
        return await _trial_fill_global(mb.bot_id, cfg)


def _trial_summary_text(cfg: dict) -> str:
    mode = cfg.get("trial_mode")
    if not mode:
        return "🧪 <b>تنظیمات تست این دکمه</b>\n\nهنوز پیکربندی نشده — یکی از گزینه‌های زیر را انتخاب کن:"
    lines = ["🧪 <b>تنظیمات تست این دکمه</b>\n"]
    lines.append(f"نوع: <b>{_TRIAL_MODE_LABELS.get(mode, mode)}</b>")
    if mode == "auto":
        from tenant.bots.vpn.vpn_admin import PANEL_LABELS
        # === PATCH_TRIAL_MULTI_PANEL_RANDOM_V1 ===
        pkeys_raw = (cfg.get("trial_panel_keys") or "").strip()
        if pkeys_raw:
            pk_list = [k for k in pkeys_raw.split(",") if k]
            if len(pk_list) == 1:
                lines.append(f"پنل: <b>{PANEL_LABELS.get(pk_list[0], pk_list[0])}</b>")
            else:
                names = "، ".join(PANEL_LABELS.get(k, k) for k in pk_list)
                lines.append(f"پنل: 🎲 <b>رندوم بینِ {len(pk_list)} پنل</b> ({names})")
        else:
            pkey = cfg.get("trial_panel_key")
            lines.append(f"پنل: <b>{PANEL_LABELS.get(pkey, '— تنظیم نشده —')}</b>")
        lines.append(f"حجم: <b>{_trial_gb_label(str(cfg.get('trial_gb', '—')))}</b>")
        lines.append(f"مدت: <b>{cfg.get('trial_days', '—')} روز</b>")
        _u = str(cfg.get('trial_users', 0) or 0)
        lines.append(f"تعداد کاربر: <b>{'♾️ نامحدود' if _u == '0' else _u}</b>")
    else:
        _cat = cfg.get("trial_category")
        lines.append(f"دسته: <b>{_cat if _cat else 'همهٔ دسته‌ها'}</b>")
        sel = cfg.get("trial_select", "fixed")
        lines.append(f"روش: <b>{_TRIAL_SELECT_LABELS.get(sel, sel)}</b>")
        if sel == "range":
            min_gb, max_gb, step_gb, min_days, max_days, step_days = _trial_range_bounds(cfg)
            lines.append(f"بازهٔ حجم: <b>{min_gb}–{max_gb} گیگ</b> (گام {step_gb})")
            lines.append(f"بازهٔ مدت: <b>{min_days}–{max_days} روز</b> (گام {step_days})")
        else:
            if mode == "unlimited":
                lines.append("حجم: <b>♾️ نامحدود</b>")
            else:
                lines.append(f"حجم: <b>{_trial_gb_label(str(cfg.get('trial_gb', '—')))}</b>")
            lines.append(f"مدت: <b>{cfg.get('trial_days', '—')} روز</b>")
            _u = str(cfg.get('trial_users', 0) or 0)
            lines.append(f"تعداد کاربر: <b>{'♾️ نامحدود' if _u == '0' else _u}</b>")
    _limit = str(cfg.get("trial_claim_limit", 1) or 0)
    lines.append(f"سقفِ دفعات هر کاربر: <b>{'♾️ نامحدود' if _limit == '0' else _limit + ' بار'}</b>")
    if cfg.get("_global_diff"):
        _what = "، ".join({"gb": "حجم", "duration": "مدت"}.get(k, k) for k, _a, _b in cfg["_global_diff"])
        lines.append(f"\n⚠️ {_what} این دکمه با «🎁 تنظیمات تست رایگان VPN» فرق دارد و مقدارِ همین دکمه اولویت دارد. "
                     "اگر می‌خواهی فقط از آن تنظیمات خوانده شود، «♻️ حجم و مدت از تنظیماتِ تستِ رایگان» را بزن.")
    if cfg.get("_from_global"):
        lines.append("\nℹ️ حجم/مدتی که برایِ این دکمه جدا ثبت نکرده‌ای، از «🎁 تنظیمات تست رایگان VPN» (پنل مدیریت ← تنظیمات) گرفته می‌شود.")
    return "\n".join(lines)


@tenant_router.callback_query(F.data.startswith("thb:trialmode:"))
async def thb_trial_top_menu(cb: CallbackQuery, bot: Bot):
    """مرحلهٔ اول: کانفیگ خودکار (ساخت زنده از پنل) یا کانفیگ آماده (انبار)."""
    await _trial_top_render(cb, bot, int(cb.data.split(":")[2]))


async def _trial_top_render(cb: CallbackQuery, bot: Bot, mb_id: int):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    await _trial_prune_panel_keys(mb_id, row.id)      # PATCH_TRIAL_STALE_PANEL_KEYS_V1
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
    if not mb or mb.bot_id != row.id or mb.action != "free_trial":
        await cb.answer("یافت نشد", show_alert=True)
        return
    cfg = _trial_cfg_of(mb)
    rows = [
        [InlineKeyboardButton(text="🤖 کانفیگ خودکار (ساخت زنده از پنل)",
                              callback_data=f"thb:tr:auto:{mb_id}", style=ButtonStyle.SUCCESS)],
        [InlineKeyboardButton(text="📦 کانفیگ آماده (از انبار)",
                              callback_data=f"thb:tr:ready:{mb_id}", style=ButtonStyle.PRIMARY)],
    ]
    if cfg.get("trial_mode") in ("manual", "unlimited"):
        _tc = cfg.get("trial_category")
        rows.append([InlineKeyboardButton(
            text=f"🏷 دستهٔ انبارِ تست: {_tc if _tc else 'همهٔ دسته‌ها'}",
            callback_data=f"thb:trcatpick:{mb_id}:top", style=ButtonStyle.PRIMARY)])
    _claim_limit = str(cfg.get("trial_claim_limit", 1) or 0)
    _claim_lbl = "♾️ نامحدود" if _claim_limit == "0" else f"{_claim_limit} بار"
    rows.append([InlineKeyboardButton(text=f"🔢 دفعاتِ مجاز هر کاربر: {_claim_lbl}",
                                      callback_data=f"thb:trclaimask:{mb_id}", style=ButtonStyle.PRIMARY)])
    # تیکت #849 (دورِ دوم): دکمهٔ «حجم/مدت از تنظیماتِ کلی» فقط تویِ صفحهٔ عمقِ دوم بود و مشتری آن را
    # در همین صفحه پیدا نمی‌کرد؛ حالا همین‌جا هم هست (بدونِ دست‌زدن به پنل/نوعِ تحویل).
    _filled = await _trial_fill_global(row.id, cfg)
    if cfg.get("trial_mode") in ("auto", "manual", "unlimited") and \
            not ({"gb", "duration"} <= set(_filled.get("_from_global") or [])):
        rows.append([InlineKeyboardButton(
            text="♻️ حجم و مدت از «تنظیماتِ تستِ رایگان» (پاک‌کردنِ مقدارِ اختصاصیِ دکمه)",
            callback_data=f"thb:trglobal2:{mb_id}", style=ButtonStyle.SUCCESS)])
    rows.append([InlineKeyboardButton(text="♻️ ریست برای همه (دوباره‌قابل‌دریافت)",
                                      callback_data=f"thb:trreset:{mb_id}", style=ButtonStyle.SUCCESS)])
    if cfg.get("trial_mode"):
        rows.append([InlineKeyboardButton(text="🗑 پاک‌کردنِ تنظیماتِ تست این دکمه",
                                          callback_data=f"thb:trclear:{mb_id}", style=ButtonStyle.DANGER)])
    rows.append([InlineKeyboardButton(text="⬅️ بازگشت به دکمه",
                                      callback_data=f"thb:pick:{mb_id}", style=ButtonStyle.DANGER)])
    await cb.message.edit_text(_trial_summary_text(await _trial_fill_global(row.id, cfg)),
                               reply_markup=InlineKeyboardMarkup(inline_keyboard=rows))
    await cb.answer()


@tenant_router.callback_query(F.data.startswith("thb:trcatpick:"))
async def thb_trial_category_pick(cb: CallbackQuery, bot: Bot):
    """نمایشِ لیستِ دسته‌های موجود در انبار برای فیلترِ تحویلِ تست."""
    row = await _owner_ok(cb, bot)
    if not row:
        return
    parts = cb.data.split(":")
    mb_id = int(parts[2])
    src = parts[3] if len(parts) > 3 else "top"
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
        if not mb or mb.bot_id != row.id or mb.action != "free_trial":
            await cb.answer("یافت نشد", show_alert=True)
            return
        _cc = (await s.execute(
            select(Config.category, func.count()).where(
                Config.bot_id == row.id, Config.status == "in_stock",
                Config.price == 0, Config.category.is_not(None)
            ).group_by(Config.category))).all()
    _cnt = {c: n for c, n in _cc if c}
    cats = sorted(_cnt)
    rows = [[InlineKeyboardButton(text="🌐 همهٔ دسته‌ها",
                                  callback_data=f"thb:trcatset:{mb_id}:{src}:_all_", style=ButtonStyle.PRIMARY)]]
    for c in cats:
        rows.append([InlineKeyboardButton(text=f"{c} ({_cnt.get(c, 0)} موجود)",
                                          callback_data=f"thb:trcatset:{mb_id}:{src}:{c}", style=ButtonStyle.PRIMARY)])
    _back_cb = f"thb:trialmode:{mb_id}" if src == "top" else f"thb:trset:sel:fixed:{mb_id}"
    rows.append([InlineKeyboardButton(text="⬅️ بازگشت", callback_data=_back_cb)])
    _text = ("🏷 <b>انتخابِ دستهٔ کانفیگ برای تست</b>\n\nفقط کانفیگ‌هایِ همین دسته از انبار "
             "به‌عنوانِ تست تحویل داده می‌شوند (فقط کانفیگ‌هایِ آمادهٔ بدونِ قیمت، یعنی قیمتِ ۰). "
             "دسته را موقعِ «➕ افزودن کانفیگ آماده» با دکمهٔ «🏷 دسته‌بندی» می‌دهی.")
    if not cats:
        _text += "\n\n⚠️ در حال حاضر هیچ کانفیگیِ دسته‌بندی‌شده‌ای در انبار نیست."
    await cb.message.edit_text(_text, reply_markup=InlineKeyboardMarkup(inline_keyboard=rows),
                               parse_mode="HTML")
    await cb.answer()


