@tenant_router.message(_TrialBtnFSM.claim_limit, F.text)
async def thb_trial_claim_save(msg: Message, bot: Bot, state: FSMContext):
    row = await _owner_ok_msg(msg, bot)
    if not row:
        await state.clear(); return
    data = await state.get_data()
    mb_id = data.get("trial_mb_id")
    t = (msg.text or "").strip().translate(str.maketrans("۰۱۲۳۴۵۶۷۸۹", "0123456789"))
    if not t.isdigit():
        await msg.answer("❌ یک عدد صحیح بفرست (۰ = نامحدود).",
                         reply_markup=_trial_cancel_kb(mb_id))
        return
    cfg = await _trial_cfg_update(mb_id, trial_claim_limit=str(int(t))) or {}
    await state.clear()
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="⬅️ بازگشت به تنظیمات تست",
                              callback_data=f"thb:trialmode:{mb_id}", style=ButtonStyle.DANGER)]])
    await msg.answer("✅ ذخیره شد.\n\n" + _trial_summary_text(cfg), reply_markup=kb)


