def _trial_fix_view(cfg: dict, mb_id: int) -> tuple[str, InlineKeyboardMarkup]:
    """ویوی انتخاب اینلاین مقدارِ ثابتِ تست: حجم / روز / تعداد کاربر با ➕➖."""
    try:
        gb = float(cfg.get("trial_gb", 2) or 2)
    except (ValueError, TypeError):
        gb = 2.0
    try:
        days = int(cfg.get("trial_days", 3) or 3)
    except (ValueError, TypeError):
        days = 3
    try:
        users = int(cfg.get("trial_users", 0) or 0)
    except (ValueError, TypeError):
        users = 0
    gb_lbl = _trial_gb_label(str(gb))
    users_lbl = "♾️ نامحدود" if users == 0 else f"{users}"
    unlimited = cfg.get("trial_mode") == "unlimited"
    def _b(t, d):
        return InlineKeyboardButton(text=t, callback_data=d)
    fields = []
    if not unlimited:
        fields.append(_b(f"📦 حجم: {gb_lbl}", f"thb:trfixask:gb:{mb_id}"))
    fields.append(_b(f"📅 مدت: {days} روز", f"thb:trfixask:days:{mb_id}"))
    fields.append(_b(f"👥 کاربر: {users_lbl}", f"thb:trfixask:users:{mb_id}"))
    rows = [fields[i:i + 2] for i in range(0, len(fields), 2)]
    _cat = cfg.get("trial_category")
    rows.append([_b(f"🏷 دسته: {_cat if _cat else 'همهٔ دسته‌ها'}", f"thb:trcatpick:{mb_id}:fix")])
    # === PATCH_TRIAL_RESET_TO_GLOBAL_V1 === (تیکت #849) مقدارِ اختصاصیِ قدیمیِ دکمه (مثلاً ۲۵۰ مگابایت) تنظیماتِ کلی را
    # می‌پوشاند و مالک راهی برایِ برداشتنش نداشت؛ این دکمه حجم/مدتِ اختصاصی را پاک می‌کند تا «تنظیماتِ تستِ رایگان» حاکم شود.
    _from_g = set(cfg.get("_from_global") or [])
    if not ({"gb", "duration"} <= _from_g):
        rows.append([_b("♻️ حجم و مدت از «تنظیماتِ تستِ رایگان» (پاک‌کردنِ مقدارِ اختصاصیِ دکمه)",
                        f"thb:trglobal:{mb_id}")])
    rows.append([_b("✅ ثبت تنظیمات تست", f"thb:trfixok:{mb_id}")])
    rows.append([_b("⬅️ بازگشت", f"thb:trialmode:{mb_id}")])
    kb = InlineKeyboardMarkup(inline_keyboard=rows)
    mode = cfg.get("trial_mode")
    mode_lbl = _TRIAL_MODE_LABELS.get(mode, mode or "—")
    text = ("🧪 <b>مقدارِ ثابتِ تست را تنظیم کن</b>\n\n"
            f"نوع تحویل: <b>{mode_lbl}</b>\n"
            + ("📦 حجم: <b>♾️ نامحدود</b>\n" if unlimited else "")
            + "روی هر دکمه بزن و عددش را بفرست؛ عدد روی همان دکمه می‌نشیند.\n"
            "📦 حجم را هم می‌توانی به گیگ (مثلاً <code>2</code>) و هم به مگابایت "
            "(مثلاً <code>0.3</code> برابر ۳۰۰ مگابایت) وارد کنی.\n"
            "👥 کاربر = محدودیت اتصال هم‌زمان (0 = نامحدود). در پایان «✅ ثبت» را بزن.")
    return text, kb


