_TRIAL_FIX_PROMPTS = {
    "gb": ("📦 حجم تست را بفرست:\n"
           "• گیگ: مثلاً <code>2</code> (برابر ۲ گیگ)\n"
           "• مگابایت: مثلاً <code>0.300</code> (برابر ۳۰۰ مگابایت)"),
    "days": "📅 مدت تست را به <b>روز</b> بفرست (مثلاً <code>3</code>):",
    "users": "👥 تعداد کاربر مجاز (اتصال هم‌زمان) را بفرست — <code>0</code> یعنی نامحدود:",
}


@tenant_router.callback_query(F.data.startswith("thb:trfixask:"))
async def thb_trial_fix_ask(cb: CallbackQuery, bot: Bot, state: FSMContext):
    _, _, field, mb_id = cb.data.split(":")
    mb_id = int(mb_id)
    mb = await _trial_fix_mb(cb, bot, mb_id)
    if not mb:
        return
    if field not in _TRIAL_FIX_PROMPTS:
        await cb.answer()
        return
    prompt = await cb.message.answer(_TRIAL_FIX_PROMPTS[field],
                                     reply_markup=_trial_cancel_kb(mb_id))
    await state.set_state(_TrialBtnFSM.fix_value)
    await state.update_data(
        trial_mb_id=mb_id, fix_field=field,
        fix_prompt_id=prompt.message_id,
        fix_panel_chat=cb.message.chat.id,
        fix_panel_id=cb.message.message_id)
    await cb.answer()


@tenant_router.message(_TrialBtnFSM.fix_value, F.text)
async def thb_trial_fix_value(msg: Message, bot: Bot, state: FSMContext):
    row = await _owner_ok_msg(msg, bot)
    if not row:
        await state.clear(); return
    data = await state.get_data()
    field = data.get("fix_field")
    mb_id = data.get("trial_mb_id")
    t = (msg.text or "").strip().translate(str.maketrans("۰۱۲۳۴۵۶۷۸۹", "0123456789"))
    val = None
    if field == "gb":
        try:
            f = float(t)
            if f > 0:
                stored = str(round(f, 4)).rstrip("0").rstrip(".")
                val = str(int(f)) if "." not in stored else stored
        except ValueError:
            pass
    elif field == "days":
        if t.isdigit() and int(t) > 0:
            val = str(int(t))
    elif field == "users":
        if t.isdigit() and int(t) >= 0:
            val = str(int(t))
    if val is None:
        await msg.answer("❌ عدد معتبر بفرست." + (" (0 = نامحدود)" if field == "users" else ""),
                         reply_markup=_trial_cancel_kb(mb_id))
        return
    key = {"gb": "trial_gb", "days": "trial_days", "users": "trial_users"}[field]
    cfg = await _trial_cfg_update(mb_id, **{key: val}) or {}
    # پاک‌کردن پرسش و پاسخ تا چت تمیز بماند
    for mid in (data.get("fix_prompt_id"), msg.message_id):
        if mid:
            try:
                await bot.delete_message(msg.chat.id, mid)
            except Exception:
                logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await state.clear()
    # نشاندن عدد روی دکمهٔ همان منو
    text, kb = _trial_fix_view(cfg, mb_id)
    chat_id = data.get("fix_panel_chat") or msg.chat.id
    panel_id = data.get("fix_panel_id")
    try:
        if panel_id:
            await bot.edit_message_text(text, chat_id=chat_id, message_id=panel_id,
                                        reply_markup=kb)
        else:
            await msg.answer(text, reply_markup=kb)
    except Exception:
        await msg.answer(text, reply_markup=kb)


