@tenant_router.message(_TrialBtnFSM.max_days, F.text)
async def trial_btn_wait_max_days(msg: Message, bot: Bot, state: FSMContext):
    row = await _owner_ok_msg(msg, bot)
    if not row:
        await state.clear(); return
    val = _trial_int(msg.text)
    data = await state.get_data()
    _mb = data.get("trial_mb_id")
    if val is None or val < int(data.get("trial_min_days", 1)):
        await msg.answer("❌ باید عددی صحیح و بزرگ‌تر یا مساویِ حداقل باشد.",
                         reply_markup=_trial_cancel_kb(_mb))
        return
    await state.update_data(trial_max_days=val)
    await state.set_state(_TrialBtnFSM.step_days)
    await msg.answer("📅 گامِ تغییرِ مدت (روز) را وارد کن (مثلاً <code>1</code>):",
                     reply_markup=_trial_cancel_kb(_mb))


@tenant_router.message(_TrialBtnFSM.step_days, F.text)
async def trial_btn_wait_step_days(msg: Message, bot: Bot, state: FSMContext):
    row = await _owner_ok_msg(msg, bot)
    if not row:
        await state.clear(); return
    data = await state.get_data()
    mb_id = data.get("trial_mb_id")
    val = _trial_int(msg.text)
    if val is None:
        await msg.answer("❌ یک عددِ صحیحِ مثبت بفرست.", reply_markup=_trial_cancel_kb(mb_id))
        return
    updates = {
        "trial_min_days": str(data.get("trial_min_days")),
        "trial_max_days": str(data.get("trial_max_days")),
        "trial_step_days": str(val),
    }
    # کلیدهای حجم فقط اگر در همین گفتگو پرسیده شده باشند (حالت نامحدود گیگ ندارد)
    if data.get("trial_min_gb") is not None:
        updates["trial_min_gb"] = str(data.get("trial_min_gb"))
        updates["trial_max_gb"] = str(data.get("trial_max_gb"))
        updates["trial_step_gb"] = str(data.get("trial_step_gb"))
    cfg = await _trial_cfg_update(mb_id, **updates)
    await state.clear()
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="⬅️ بازگشت به تنظیمات دکمه", callback_data=f"thb:pick:{mb_id}", style=ButtonStyle.DANGER)]])
    await msg.answer("✅ ذخیره شد.\n\n" + _trial_summary_text(cfg or {}), reply_markup=kb)


