@tenant_router.callback_query(F.data.startswith("thb:cfgmode:"))
async def thb_cfgmode_set(cb: CallbackQuery, bot: Bot):
    """ثبتِ حالتِ انتخابی (بازه/بسته‌های آماده) و فعال‌سازیِ اکشنِ «خرید کانفیگ»."""
    row = await _owner_ok(cb, bot)
    if not row:
        return
    parts = cb.data.split(":")
    mode, mb_id = parts[2], int(parts[3])
    if mode not in ("range", "packages"):
        await cb.answer("نامعتبر", show_alert=True)
        return
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
        if mb and mb.bot_id == row.id:
            cfg = {}
            if mb.config:
                try:
                    cfg = json.loads(mb.config) or {}
                except Exception:
                    cfg = {}
            cfg["config_mode"] = mode
            mb.action = "buy_config"
            mb.config = json.dumps(cfg, ensure_ascii=False)
            await s.commit()
        mb = await s.get(MainButton, mb_id)
    if not mb:
        await cb.answer("یافت نشد", show_alert=True)
        return
    is_dis = mb_id in await _disabled_btn_ids(row.id)
    mode_lbl = "بازه‌ای (➕➖)" if mode == "range" else "بسته‌های آماده با قیمت ثابت"
    text = (
        f"✅ این دکمه حالا «خرید کانفیگ» با حالتِ «{mode_lbl}» است.\n"
        "⚙️ قیمت و بازه‌ها از «مدیریت کانفیگ ← تنظیم قسمت فروش کانفیگ» تنظیم می‌شود.\n\n"
        f"🎯 <b>عملکرد دکمه</b>\nعملکرد فعلی: {_thb_action_label(mb)}\n\n"
        + _thb_text(mb, is_dis)
    )
    try:
        await cb.message.edit_text(text, reply_markup=_thb_kb_action(mb, row.field, row.plan))
    except Exception:
        await cb.message.answer(text, reply_markup=_thb_kb_action(mb, row.field, row.plan))
    await cb.answer("تنظیم شد")


# === PATCH_WIREGUARD_KIND_FILTER_V1 ===
def _kind_picker_kb(action_type: str, mb_id: int, current: str | None) -> InlineKeyboardMarkup:
    # === PATCH_OPENVPN_CONFIG_V1 ===
    opts = [(None, "🌐 همه"), ("sublink", "🔌 فقط V2Ray/VLESS"),
            ("wireguard", "🛡️ فقط وایرگارد"),
            ("openvpn", "🔐 فقط اوپن‌وی‌پی‌ان"),
            ("panel", "🏷 فقط پنل‌های VPN")]  # === PATCH_VPN_PANEL_MARKET_V1 ===
    rows = []
    for val, lbl in opts:
        mark = "✅" if val == current else "⬜️"
        val_str = val or "all"
        rows.append([InlineKeyboardButton(
            text=f"{mark} {lbl}", callback_data=f"thb:kindset:{action_type}:{val_str}:{mb_id}", style=ButtonStyle.PRIMARY)])
    rows.append([InlineKeyboardButton(text="⬅️ بازگشت", callback_data=f"thb:cat:action:{mb_id}", style=ButtonStyle.DANGER)])
    return InlineKeyboardMarkup(inline_keyboard=rows)


