@tenant_router.callback_query(F.data.startswith("thb:kindset:"))
async def thb_kindset(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    parts = cb.data.split(":")
    action_type, val_str, mb_id = parts[2], parts[3], int(parts[4])
    # === PATCH_THB_KINDSET_PANEL_V1 ===
    # «panel» (گزینه‌ی «🏷 فقط پنل‌های VPN») به کیبورد اضافه شده بود
    # (PATCH_VPN_PANEL_MARKET_V1) ولی اینجا هیچ‌وقت به لیستِ معتبرها
    # اضافه نشده بود، پس همیشه «نامعتبر» می‌داد.
    if action_type not in ("cfg", "unli") or val_str not in ("all", "sublink", "wireguard", "openvpn", "panel"):  # === PATCH_OPENVPN_CONFIG_V1 ===
        await cb.answer("نامعتبر", show_alert=True)
        return
    val = None if val_str == "all" else val_str
    key = "config_kind" if action_type == "cfg" else "unlimited_kind"
    expected_action = "buy_config" if action_type == "cfg" else "buy_unlimited"
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
        if mb and mb.bot_id == row.id and mb.action == expected_action:
            cfg = {}
            if mb.config:
                try:
                    cfg = json.loads(mb.config) or {}
                except Exception:
                    cfg = {}
            cfg[key] = val
            mb.config = json.dumps(cfg, ensure_ascii=False)
            await s.commit()
        mb = await s.get(MainButton, mb_id)
    if not mb:
        await cb.answer("یافت نشد", show_alert=True)
        return
    is_dis = mb_id in await _disabled_btn_ids(row.id)
    text = (f"🎯 <b>عملکرد دکمه</b>\nعملکرد فعلی: {_thb_action_label(mb)}\n\n"
            + _thb_text(mb, is_dis))
    try:
        await cb.message.edit_text(text, reply_markup=_thb_kb_action(mb, row.field, row.plan))
    except Exception:
        await cb.message.answer(text, reply_markup=_thb_kb_action(mb, row.field, row.plan))
    await cb.answer("تنظیم شد")



async def _thb_cat_kb(bot_id: int, action_type: str, mb_id: int) -> InlineKeyboardMarkup:
    """کیبوردِ انتخابِ دستهٔ انبار برای یک دکمهٔ خاص (خرید کانفیگ/نامحدود) — نسخهٔ سریع
    که مستقیم از صفحهٔ «عملکرد دکمه» باز می‌شود — PATCH_MCFG_CATEGORY_THB_V1.
    از این پس چند-انتخابی است: هر دسته با تیک ✅/⬜️ کنارش toggle می‌شود و می‌توان
    چند دسته را هم‌زمان انتخاب کرد — PATCH_MCFG_CATEGORY_MULTI_V1."""
    cats = await _cfg_categories_for(bot_id, unlimited=(action_type == "buy_unlimited"))
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
    selected: list[str] = []
    if mb and mb.config:
        try:
            _c = json.loads(mb.config) or {}
        except Exception:
            _c = {}
        selected = _norm_cat_list(_c.get(_CFG_CATEGORY_KEY[action_type])) or []
    is_all = not selected
    rows = [[InlineKeyboardButton(
        text=("✅" if is_all else "⬜️") + " 🌐 همه (بدون فیلتر دسته)",
        callback_data=f"thb:allcat:{action_type}:{mb_id}", style=ButtonStyle.SUCCESS)]]
    for c in cats:
        mark = "✅" if c in selected else "⬜️"
        rows.append([InlineKeyboardButton(
            text=f"{mark} 🏷 {c}", callback_data=f"thb:togglecat:{action_type}:{mb_id}:{c}", style=ButtonStyle.PRIMARY)])
    rows.append([InlineKeyboardButton(text="⬅️ بازگشت", callback_data=f"thb:cat:action:{mb_id}", style=ButtonStyle.DANGER)])
    return InlineKeyboardMarkup(inline_keyboard=rows)


