@tenant_router.callback_query(F.data.startswith("thb:allcat:"))
async def thb_allcat(cb: CallbackQuery, bot: Bot):
    """پاک‌کردنِ فیلترِ دسته روی دکمه (انتخابِ «🌐 همه») — PATCH_MCFG_CATEGORY_MULTI_V1."""
    row = await _owner_ok(cb, bot)
    if not row:
        return
    parts = cb.data.split(":")  # thb:allcat:{action_type}:{mb_id}
    action_type = parts[2]
    mb_id = int(parts[3])
    if action_type not in _CFG_CATEGORY_KEY:
        await cb.answer("نامعتبر", show_alert=True)
        return
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
        if not mb or mb.bot_id != row.id or mb.action != action_type:
            await cb.answer("یافت نشد", show_alert=True)
            return
        cfg = {}
        if mb.config:
            try:
                cfg = json.loads(mb.config) or {}
            except Exception:
                cfg = {}
        cfg.pop(_CFG_CATEGORY_KEY[action_type], None)
        mb.config = json.dumps(cfg, ensure_ascii=False)
        await s.commit()
    kb = await _thb_cat_kb(row.id, action_type, mb_id)
    try:
        await cb.message.edit_reply_markup(reply_markup=kb)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.answer("✅ بدون فیلتر دسته")


@tenant_router.callback_query(F.data.startswith("thb:togglecat:"))
async def thb_togglecat(cb: CallbackQuery, bot: Bot):
    """تیک‌زدن/برداشتنِ یک دسته روی دکمه — می‌توان چند دسته را هم‌زمان انتخاب کرد
    (هم برای خرید کانفیگ، هم نامحدود) — PATCH_MCFG_CATEGORY_MULTI_V1."""
    row = await _owner_ok(cb, bot)
    if not row:
        return
    parts = cb.data.split(":", 4)  # thb:togglecat:{action_type}:{mb_id}:{cat}
    action_type = parts[2]
    mb_id = int(parts[3])
    category = parts[4] if len(parts) > 4 else None
    if action_type not in _CFG_CATEGORY_KEY or not category:
        await cb.answer("نامعتبر", show_alert=True)
        return
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
        if not mb or mb.bot_id != row.id or mb.action != action_type:
            await cb.answer("یافت نشد", show_alert=True)
            return
        cfg = {}
        if mb.config:
            try:
                cfg = json.loads(mb.config) or {}
            except Exception:
                cfg = {}
        key = _CFG_CATEGORY_KEY[action_type]
        selected = _norm_cat_list(cfg.get(key)) or []
        if category in selected:
            selected = [c for c in selected if c != category]
        else:
            selected = selected + [category]
        if selected:
            cfg[key] = selected
        else:
            cfg.pop(key, None)
        mb.config = json.dumps(cfg, ensure_ascii=False)
        await s.commit()
        newly_checked = category in selected
    kb = await _thb_cat_kb(row.id, action_type, mb_id)
    try:
        await cb.message.edit_reply_markup(reply_markup=kb)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.answer(f"{'✅' if newly_checked else '⬜️'} {category}")


# === PATCH_MANUAL_BTN_DISPLAY_CATS_V1 ===
# «🏷 دسته‌بندی‌های نمایشی» برایِ دکمه‌هایِ خریدِ دستی (خرید کانفیگ / نامحدود):
# همان تجربهٔ حالتِ پنل — لیستِ دسته‌ها با تیک ✅/⬜️ + تیکِ «♾️ نامحدود».
# ذخیره‌سازی رویِ همان کلیدهایِ قدیمیِ config دکمه انجام می‌شود
# (config_category / unlimited_category) تا هیچ دکمهٔ قبلی خراب نشود؛
# فقط یک کلیدِ تازه دارد: config_include_unlimited.

async def _mcat_all_categories(bot_id: int, action: str) -> list[str]:
    """دسته‌هایِ قابلِ نمایش: برایِ «خرید کانفیگ» هر دو نوعِ انبار (حجمی + نامحدود)،
    برایِ «نامحدود» فقط دسته‌هایِ نامحدود. ترتیبِ مرتب‌شده = ایندکسِ پایدار."""
    async with Session() as s:
        q = select(Config.category).where(
            Config.bot_id == bot_id, Config.category.isnot(None),
            Config.status == "in_stock")
        if action == "buy_unlimited":
            q = q.where(Config.volume_gb == 0)
        vals = (await s.scalars(q.distinct())).all()
    return sorted({v for v in vals if v})


async def _mcat_unlimited_cats(bot_id: int) -> set[str]:
    async with Session() as s:
        vals = (await s.scalars(
            select(Config.category).where(
                Config.bot_id == bot_id, Config.category.isnot(None),
                Config.status == "in_stock", Config.volume_gb == 0).distinct())).all()
    return {v for v in vals if v}


def _mcat_load_cfg(mb) -> dict:
    if not mb or not mb.config:
        return {}
    try:
        return json.loads(mb.config) or {}
    except Exception:
        return {}


async def _mcat_screen(cb: CallbackQuery, bot_id: int, mb_id: int):
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
    if not mb or mb.bot_id != bot_id or mb.action not in ("buy_config", "buy_unlimited"):
        await cb.answer("دکمه پیدا نشد.", show_alert=True)
        return
    is_cfg = (mb.action == "buy_config")
    cfg = _mcat_load_cfg(mb)
    key = _CFG_CATEGORY_KEY[mb.action]
    selected = _norm_cat_list(cfg.get(key)) or []
    incl_unl = bool(cfg.get("config_include_unlimited")) if is_cfg else True
    mode = cfg.get("config_mode" if is_cfg else "unlimited_mode", "both")
    cats = await _mcat_all_categories(bot_id, mb.action)
    unl_cats = await _mcat_unlimited_cats(bot_id) if is_cfg else set(cats)

    rows = []
    for i, c in enumerate(cats):
        mark = "✅" if (not selected or c in selected) else "⬜️"
        tag = " ♾️" if (is_cfg and c in unl_cats) else ""
        rows.append([InlineKeyboardButton(
            text=f"{mark} {c}{tag}", callback_data=f"thb:mcx:{mb_id}:{i}", style=ButtonStyle.PRIMARY)])
    if is_cfg:
        rows.append([InlineKeyboardButton(
            text=("✅ ♾️ نمایشِ کانفیگ‌هایِ نامحدود هم" if incl_unl
                  else "⬜️ ♾️ نمایشِ کانفیگ‌هایِ نامحدود هم"),
            callback_data=f"thb:mcunl:{mb_id}",
            style=(ButtonStyle.SUCCESS if incl_unl else ButtonStyle.PRIMARY))])
    rows.append([InlineKeyboardButton(text="♻️ نمایشِ همه (حذفِ فیلتر)",
                                      callback_data=f"thb:mcall:{mb_id}", style=ButtonStyle.DANGER)])
    rows.append([InlineKeyboardButton(text="⬅️ بازگشت", callback_data=f"thb:pick:{mb_id}",
                                      style=ButtonStyle.DANGER)])

    if not cats:
        state_txt = "هنوز کانفیگی با دسته‌بندی در انبار نیست"
    elif not selected:
        state_txt = "همهٔ دسته‌ها (فیلتری تنظیم نشده)"
    else:
        state_txt = f"{len(selected)} دسته انتخاب شده"
    txt = ("🏷 <b>دسته‌بندی‌های نمایشی</b>\n\n"
           f"دکمهٔ «{mb.label}» الان: <b>{state_txt}</b>\n\n"
           "رویِ هر دسته بزن تا نمایشش برایِ <b>همین دکمه</b> روشن/خاموش شود. "
           "این‌طوری می‌توانی برایِ هر دسته یک دکمهٔ جدا بسازی.\n\n")
    if is_cfg:
        txt += ("♾️ کنارِ اسمِ دسته یعنی در آن دسته کانفیگِ نامحدود هم هست. "
                "برایِ اینکه نامحدودها هم در این دکمه بیایند، تیکِ "
                "«نمایشِ کانفیگ‌هایِ نامحدود هم» را روشن کن.\n\n")
    txt += "💡 اگر همه ✅ باشند یا فیلتر نگذاری، مثلِ قبل همهٔ دسته‌ها نشان داده می‌شوند."
    if mode == "range":
        txt += ("\n\n⚠️ حالتِ نمایشِ این دکمه «بازه‌ای (➕➖)» است و دسته‌بندی فقط رویِ "
                "«بسته‌هایِ آماده» اثر دارد. از «🎯 عملکرد دکمه» حالتش را به "
                "«بسته‌هایِ آماده» یا «هر دو» تغییر بده.")
    kb = InlineKeyboardMarkup(inline_keyboard=rows)
    try:
        await cb.message.edit_text(txt, reply_markup=kb)
    except Exception:
        await cb.message.answer(txt, reply_markup=kb)
    await cb.answer()


@tenant_router.callback_query(F.data.startswith("thb:mcat:"))
async def thb_mcat_open(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    await _mcat_screen(cb, row.id, int(cb.data.split(":")[2]))


@tenant_router.callback_query(F.data.startswith("thb:mcx:"))
async def thb_mcat_toggle(cb: CallbackQuery, bot: Bot):
    """تیک‌زدن/برداشتنِ یک دسته (با ایندکس، تا callback_data از ۶۴ بایت رد نشود)."""
    row = await _owner_ok(cb, bot)
    if not row:
        return
    parts = cb.data.split(":")  # thb:mcx:{mb_id}:{idx}
    mb_id, idx = int(parts[2]), int(parts[3])
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
        if not mb or mb.bot_id != row.id or mb.action not in ("buy_config", "buy_unlimited"):
            await cb.answer("دکمه پیدا نشد.", show_alert=True)
            return
        cats = await _mcat_all_categories(row.id, mb.action)
        if idx >= len(cats):
            await cb.answer("لیست عوض شده؛ دوباره باز کن.", show_alert=True)
            return
        cat = cats[idx]
        cfg = _mcat_load_cfg(mb)
        key = _CFG_CATEGORY_KEY[mb.action]
        selected = _norm_cat_list(cfg.get(key))
        # «فیلتر تنظیم نشده» یعنی همه روشن‌اند؛ برایِ خاموش‌کردنِ یکی اول صریحش می‌کنیم
        cur = set(cats) if not selected else set(selected)
        if cat in cur:
            cur.discard(cat)
        else:
            cur.add(cat)
        if not cur:
            await cb.answer("حداقل یک دسته باید انتخاب بماند.", show_alert=True)
            return
        if cur == set(cats):
            cfg.pop(key, None)  # همه ⇒ بدونِ فیلتر (دستهٔ جدید خودکار دیده می‌شود)
        else:
            cfg[key] = sorted(cur)
        mb.config = json.dumps(cfg, ensure_ascii=False)
        await s.commit()
    await _mcat_screen(cb, row.id, mb_id)


@tenant_router.callback_query(F.data.startswith("thb:mcunl:"))
async def thb_mcat_unl(cb: CallbackQuery, bot: Bot):
    """روشن/خاموش‌کردنِ نمایشِ کانفیگ‌هایِ نامحدود داخلِ دکمهٔ «خرید کانفیگ»."""
    row = await _owner_ok(cb, bot)
    if not row:
        return
    mb_id = int(cb.data.split(":")[2])
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
        if not mb or mb.bot_id != row.id or mb.action != "buy_config":
            await cb.answer("دکمه پیدا نشد.", show_alert=True)
            return
        cfg = _mcat_load_cfg(mb)
        if cfg.get("config_include_unlimited"):
            cfg.pop("config_include_unlimited", None)
            msg_t = "کانفیگ‌هایِ نامحدود دیگر نشان داده نمی‌شوند."
        else:
            cfg["config_include_unlimited"] = True
            msg_t = "کانفیگ‌هایِ نامحدود هم نشان داده می‌شوند."
        mb.config = json.dumps(cfg, ensure_ascii=False)
        await s.commit()
    await cb.answer(msg_t)
    await _mcat_screen(cb, row.id, mb_id)


