# === PATCH_BTN_VPN_CATEGORY_FILTER_V1 ===

async def _vcat_screen(cb: CallbackQuery, bot, mb_id: int):
    """صفحهٔ انتخابِ دسته‌بندی‌هایی که این دکمه نمایش می‌دهد."""
    from tenant.bots.vpn.vpn_user import all_categories, allowed_categories, _NO_CAT
    row = await _owner_ok(cb, bot)
    if not row:
        return
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
    if not mb or mb.bot_id != row.id:
        await cb.answer("دکمه پیدا نشد.", show_alert=True)
        return
    panel_key = mb.action.replace("buy_vpn_", "") if mb.action.startswith("buy_vpn_") else None
    cats = await all_categories(row.id, panel_key)
    allowed = await allowed_categories(row.id, mb_id)

    rows = []
    if not cats:
        txt = ("🏷 <b>دسته‌بندی‌های نمایشی</b>\n\n"
               "هنوز هیچ پلنی برایِ این پنل ثبت نشده. اول از «🛰 VPN خودکار → "
               "📦 پلن‌های فروش» پلن بساز و برایشان دسته‌بندی بگذار، بعد "
               "این‌جا می‌توانی تعیین کنی این دکمه کدام‌ها را نشان بدهد.")
    else:
        for c in cats:
            label = "بدون دسته‌بندی" if c == _NO_CAT else c
            mark = "✅" if (allowed is None or c in allowed) else "⬜️"
            rows.append([InlineKeyboardButton(
                text=f"{mark} {label}", callback_data=f"thb:vcatx:{mb_id}:{c}", style=ButtonStyle.PRIMARY)])
        # === PATCH_BTN_HIDE_ALL_PLANS_V1 ===
        _hidden = (allowed is not None and len(allowed) == 0)
        rows.append([InlineKeyboardButton(
            text=("🙈 پلن‌ها پنهان‌اند — نمایششان بده" if _hidden
                  else "🙈 پنهان‌کردنِ همهٔ پلن‌ها (فقط فروشِ آنلاین)"),
            callback_data=f"thb:vcatnone:{mb_id}",
            style=(ButtonStyle.SUCCESS if _hidden else ButtonStyle.PRIMARY))])
        rows.append([InlineKeyboardButton(text="♻️ نمایشِ همه (حذفِ فیلتر)",
                                          callback_data=f"thb:vcatall:{mb_id}", style=ButtonStyle.DANGER)])
        state_txt = ("هیچ پلنی (فقط فروشِ آنلاین)" if _hidden
                     else "همهٔ دسته‌ها (فیلتری تنظیم نشده)" if allowed is None
                     else f"{len(allowed)} دسته انتخاب شده")
        txt = ("🏷 <b>دسته‌بندی‌های نمایشی</b>\n\n"
               f"دکمهٔ «{mb.label}» الان: <b>{state_txt}</b>\n\n"
               "رویِ هر دسته بزن تا نمایشش برایِ <b>همین دکمه</b> روشن/خاموش شود. "
               "این‌طوری می‌توانی برایِ هر دسته یک دکمهٔ جدا بسازی — مثلاً یک دکمه "
               "فقط «پلن‌های حجمی» و یک دکمهٔ دیگر فقط «پلن‌های نامحدود».\n\n"
               "💡 اگر همه ✅ باشند یا هیچ فیلتری نگذاری، مثلِ قبل همهٔ پلن‌ها "
               "نشان داده می‌شوند.\n\n"
               "🙈 اگر می‌خواهی این دکمه اصلاً پلنِ آماده نشان ندهد و کاربر فقط "
               "«فروشِ آنلاین (حجم/روزِ دلخواه)» را ببیند، دکمهٔ پنهان‌کردنِ "
               "همهٔ پلن‌ها را بزن.")
    rows.append([InlineKeyboardButton(text="⬅️ بازگشت", callback_data=f"thb:pick:{mb_id}", style=ButtonStyle.DANGER)])
    kb = InlineKeyboardMarkup(inline_keyboard=rows)
    try:
        await cb.message.edit_text(txt, reply_markup=kb)
    except Exception:
        await cb.message.answer(txt, reply_markup=kb)
    await cb.answer()


