@tenant_router.callback_query(F.data.startswith("thb:vcatx:"))
async def thb_vcat_toggle(cb: CallbackQuery, bot: Bot):
    """روشن/خاموش‌کردنِ یک دسته برایِ همین دکمه."""
    from tenant.bots.vpn.vpn_user import all_categories, allowed_categories
    row = await _owner_ok(cb, bot)
    if not row:
        return
    _, _, mb_id_s, cat = cb.data.split(":", 3)
    mb_id = int(mb_id_s)
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
    if not mb or mb.bot_id != row.id:
        await cb.answer("دکمه پیدا نشد.", show_alert=True)
        return
    panel_key = mb.action.replace("buy_vpn_", "") if mb.action.startswith("buy_vpn_") else None
    cats = await all_categories(row.id, panel_key)
    allowed = await allowed_categories(row.id, mb_id)
    # «فیلتر تنظیم نشده» یعنی همه روشن‌اند؛ برایِ خاموش‌کردنِ یکی، اول
    # وضعیتِ فعلی را صریح می‌کنیم تا بقیه روشن بمانند.
    cur = set(cats) if allowed is None else set(allowed)
    if cat in cur:
        cur.discard(cat)
    else:
        cur.add(cat)
    if not cur:
        # === PATCH_BTN_HIDE_ALL_PLANS_V1 ===
        # خالی‌شدن از راهِ تیک‌زدن هنوز جلوگیری می‌شود (معمولاً سهوی است)؛
        # اگر واقعاً پنهان‌کردن می‌خواهد، دکمهٔ صریحش وجود دارد.
        await cb.answer(
            "حداقل یک دسته باید انتخاب بماند. اگر می‌خواهی هیچ پلنی نمایش "
            "داده نشود، از دکمهٔ «🙈 پنهان‌کردنِ همهٔ پلن‌ها» استفاده کن.",
            show_alert=True)
        return
    # اگر همه انتخاب شدند، فیلتر را پاک می‌کنیم (یعنی «همه») تا اگر بعداً
    # دستهٔ جدیدی ساخته شد، خودکار در این دکمه هم دیده شود.
    value = "" if cur == set(cats) else "|".join(sorted(cur))
    await set_setting(row.id, f"btn_vpncats_{mb_id}", value)
    await _vcat_screen(cb, bot, mb_id)


