@tenant_router.message(HomeBtnFSM.set_command, F.text)
async def thb_cmd_set_save(msg: Message, bot: Bot, state: FSMContext):
    row = await get_bot_row(bot)
    if not row or not await is_owner_or_admin(row.id, msg.from_user.id, row.owner_id):  # PATCH_ADMIN_FSM_SAVE_V1
        await state.clear()
        return
    raw = (msg.text or "").strip()
    if raw in ("❌ لغو", "❌ لغو / بازگشت"):
        await state.clear()
        kb = await main_kb_or_remove(row.id, row.owner_id, msg.from_user.id)
        await msg.answer("لغو شد.", reply_markup=kb or ReplyKeyboardRemove())
        return
    cmd = raw.lstrip("/").split("@")[0].lower()
    if not _BTN_CMD_RE.match(cmd):
        await msg.answer("❌ کامند نامعتبر است. فقط a-z، 0-9 و «_» (حداکثر ۳۲ کاراکتر).\n"
                         "دوباره بفرست یا «لغو» را بزن:")
        return
    if cmd in _BTN_CMD_RESERVED:
        await msg.answer(f"❌ کامند /{cmd} رزرو شده است. یک کامند دیگر انتخاب کن:")
        return
    data = await state.get_data()
    mb_id = data.get("cmd_mb_id")
    # یکتایی بین دکمه‌های همین ربات
    dup = await _find_btn_by_command(row.id, cmd)
    if dup and dup.id != mb_id:
        await msg.answer(f"❌ کامند /{cmd} قبلاً روی دکمهٔ «{dup.label}» تنظیم شده. "
                         "یک کامند دیگر بفرست:")
        return
    async with Session() as s:
        mb = await s.get(MainButton, mb_id) if mb_id else None
        if not mb or mb.bot_id != row.id:
            await state.clear()
            kb = await main_kb_or_remove(row.id, row.owner_id, msg.from_user.id)
            await msg.answer("دکمه یافت نشد.", reply_markup=kb or ReplyKeyboardRemove())
            return
        cfg = {}
        if mb.config:
            try:
                cfg = json.loads(mb.config) or {}
            except Exception:
                cfg = {}
        cfg["command"] = cmd
        mb.config = json.dumps(cfg, ensure_ascii=False)
        _lbl = mb.label
        await s.commit()
    await state.clear()
    # === PATCH_THB_RETURN_TO_SETTINGS_V1 ===
    is_disabled = mb_id in await _disabled_btn_ids(row.id)
    await msg.answer(
        f"✅ کامند <code>/{cmd}</code> روی دکمهٔ «{_lbl}» تنظیم شد.\n"
        f"از این به بعد هر کس /{cmd} بفرستد، این دکمه برایش اجرا می‌شود.", parse_mode="HTML")
    await msg.answer(_thb_text(mb, is_disabled), reply_markup=_thb_kb(mb, is_disabled))


