@tenant_router.callback_query(F.data.startswith("thb:setsimple:"))
async def thb_set_simple_action(cb: CallbackQuery, bot: Bot):
    """فعال‌سازیِ یکی از عملکردهای «سادهٔ» آماده (کیف پول، پروفایل، سرویس‌های
    من، کانفیگ‌های من، آموزش اتصال، سیستم دعوت، خرید VPN با اولین پنل فعال)."""
    row = await _owner_ok(cb, bot)
    if not row:
        return
    parts = cb.data.split(":")
    action_key, mb_id = parts[2], int(parts[3])
    if action_key not in _SIMPLE_ACTIONS:
        await cb.answer("نامعتبر", show_alert=True)
        return
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
        if mb and mb.bot_id == row.id and mb.action is None:
            mb.action = action_key
            await s.commit()
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
    if not mb:
        await cb.answer("یافت نشد", show_alert=True)
        return
    is_dis = mb_id in await _disabled_btn_ids(row.id)
    _, confirm_msg, _ = _SIMPLE_ACTIONS[action_key]
    try:
        await cb.message.edit_text(f"✅ {confirm_msg}\n\n" + _thb_text(mb, is_dis),
                                   reply_markup=_thb_kb(mb, is_dis))
    except Exception:
        await cb.message.answer(_thb_text(mb, is_dis), reply_markup=_thb_kb(mb, is_dis))
    await cb.answer("تنظیم شد")


