@tenant_router.callback_query(F.data.startswith("thb:setproduct:"))
async def thb_setproduct_picker(cb: CallbackQuery, bot: Bot):
    """لیستِ محصولاتِ فروشگاه رو نشون می‌ده تا ادمین یکی رو مستقیم به این
    دکمه وصل کنه."""
    row = await _owner_ok(cb, bot)
    if not row:
        return
    mb_id = int(cb.data.split(":")[2])
    from models import Product
    async with Session() as s:
        products = (await s.scalars(select(Product).where(
            Product.bot_id == row.id, Product.is_active == True
        ).order_by(Product.sort_order, Product.id))).all()
    if not products:
        await cb.answer(
            "هنوز محصولی نساختی. اول از «🛒 فروشگاه دیجیتال ← ➕ محصول جدید» یه محصول بساز.",
            show_alert=True)
        return
    kb_rows = [[InlineKeyboardButton(text=f"🛍 {p.title}", callback_data=f"thb:pickproduct:{mb_id}:{p.id}", style=ButtonStyle.PRIMARY)]
              for p in products]
    kb_rows.append([InlineKeyboardButton(text="⬅️ بازگشت", callback_data=f"thb:show:{mb_id}", style=ButtonStyle.DANGER)])
    await cb.message.edit_text(
        "🛍 <b>اتصالِ مستقیم به محصول</b>\n\n"
        "کدوم محصول رو انتخاب کنی، با زدنِ این دکمه کاربر مستقیم صفحهٔ همون محصول رو می‌بینه "
        "(بدونِ نیازِ به بازکردنِ کلِ فروشگاه):",
        reply_markup=InlineKeyboardMarkup(inline_keyboard=kb_rows), parse_mode="HTML")
    await cb.answer()


