@tenant_router.callback_query(F.data.startswith("thb:setdicegame:"))
async def thb_setdicegame_picker(cb: CallbackQuery, bot: Bot):
    """لیستِ بازی‌های ثبت‌شده رو نشون می‌ده تا ادمین یکیش رو مستقیم به این
    دکمه وصل کنه (مثلاً فقط اسلات، بدون نمایشِ لیستِ بقیهٔ بازی‌ها)."""
    row = await _owner_ok(cb, bot)
    if not row:
        return
    mb_id = int(cb.data.split(":")[2])
    from models import DiceGame
    async with Session() as s:
        games = (await s.scalars(select(DiceGame).where(
            DiceGame.bot_id == row.id).order_by(DiceGame.id))).all()
    if not games:
        await cb.answer(
            "هنوز هیچ بازی‌ای نساختی. اول از «🎲 بازی کن و جایزه بگیر ← ➕ افزودن بازی» یه بازی بساز.",
            show_alert=True)
        return
    kb_rows = [[InlineKeyboardButton(
        text=f"{'✅' if g.active else '⛔️'} {g.emoji} {g.title}",
        callback_data=f"thb:pickdicegame:{mb_id}:{g.id}", style=ButtonStyle.SUCCESS)] for g in games]
    kb_rows.append([InlineKeyboardButton(text="⬅️ بازگشت", callback_data=f"thb:show:{mb_id}", style=ButtonStyle.DANGER)])
    await cb.message.edit_text(
        "🎯 <b>اتصال به یک بازیِ مشخص</b>\n\n"
        "کدوم بازی رو انتخاب کنی، با زدنِ این دکمه کاربر مستقیم همون بازی رو بازی می‌کنه "
        "(بدونِ نیاز به بازکردنِ لیستِ همهٔ بازی‌ها):",
        reply_markup=InlineKeyboardMarkup(inline_keyboard=kb_rows), parse_mode="HTML")
    await cb.answer()


