# === PATCH_SMM_PLATFORM_BUTTON_ACTION_V1 ===
# === PATCH_SMM_PLATFORM_MULTI_V1 ===
# درخواستِ ادمین: امکانِ وصل‌کردنِ چند پلتفرم (نه فقط یکی) به یک دکمه —
# مثلاً «تلگرام + اینستاگرام» رو با یه دکمهٔ مشترک بفروشه، ولی بقیهٔ
# پلتفرم‌ها همچنان تویِ لیستِ عمومی نمونن. حالا این صفحه چک‌باکسی است؛
# اگه فقط یک پلتفرم تیک بخوره، دقیقاً رفتارِ قبلی (مستقیم می‌ره سراغِ
# نوع‌سرویس‌ها)؛ اگه چندتا تیک بخوره، اول یه لیستِ کوچیکِ فقط همون
# پلتفرم‌ها نشون داده می‌شه.
async def _thb_smmplat_kb(bot_id: int, mb_id: int, selected: list[str]) -> InlineKeyboardMarkup:
    from tenant.bots.virtual_service.smm import smm_api as _smm_api, platform_label_for_bot as _plat_label
    from models import SmmService
    async with Session() as s:
        svcs = (await s.scalars(select(SmmService).where(
            SmmService.bot_id == bot_id, SmmService.is_active == True))).all()
    from tenant.bots.virtual_service.smm import classified_tree as _ctree
    tree = await _ctree(bot_id, svcs)   # PATCH_SMM_CUSTOMER_TREE_CLASSIFY_V1
    rows = []
    for pkey in sorted(tree.keys(), key=lambda k: -sum(len(x) for x in tree[k].values())):
        label = await _plat_label(bot_id, pkey)
        mark = "✅" if pkey in selected else "⬜️"
        rows.append([InlineKeyboardButton(
            text=f"{mark} {label}", callback_data=f"thb:togglesmmplat:{mb_id}:{pkey}", style=ButtonStyle.PRIMARY)])
    rows.append([InlineKeyboardButton(
        text=f"✅ ذخیره ({len(selected)} پلتفرم انتخاب شد)" if selected else "✅ ذخیره",
        callback_data=f"thb:donesmmplat:{mb_id}", style=ButtonStyle.SUCCESS)])
    rows.append([InlineKeyboardButton(text="⬅️ انصراف", callback_data=f"thb:show:{mb_id}", style=ButtonStyle.DANGER)])
    return InlineKeyboardMarkup(inline_keyboard=rows)


def _thb_smmplat_current(mb) -> list[str]:
    if not mb.config:
        return []
    try:
        _c = json.loads(mb.config) or {}
    except Exception:
        return []
    pls = _c.get("platforms")
    if pls:
        return [p for p in pls if p]
    return [_c["platform"]] if _c.get("platform") else []


@tenant_router.callback_query(F.data.startswith("thb:setsmmplat:"))
async def thb_setsmmplat_picker(cb: CallbackQuery, bot: Bot, state: FSMContext):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    mb_id = int(cb.data.split(":")[2])
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
    if not mb or mb.bot_id != row.id:
        await cb.answer("یافت نشد", show_alert=True)
        return
    from tenant.bots.virtual_service.smm import smm_api as _smm_api
    from models import SmmService
    async with Session() as s:
        has_svc = await s.scalar(select(func.count()).select_from(SmmService).where(
            SmmService.bot_id == row.id, SmmService.is_active == True))
    if not has_svc:
        await cb.answer(
            "هنوز هیچ سرویسِ فعالی نداری. اول از «📥 دریافت و انتخاب سرویس‌ها» چند سرویس اضافه کن.",
            show_alert=True)
        return
    selected = _thb_smmplat_current(mb)
    await state.update_data(thb_smmplat_mb_id=mb_id, thb_smmplat_selected=selected)
    kb = await _thb_smmplat_kb(row.id, mb_id, selected)
    text = (
        "🌐 <b>اتصال به پلتفرم(ها)</b>\n\n"
        "یک یا چند پلتفرم رو تیک بزن. اگه فقط یکی رو انتخاب کنی، کاربر با زدنِ این "
        "دکمه مستقیم می‌ره سراغِ نوع‌سرویس‌هایِ همون پلتفرم. اگه چندتا رو انتخاب کنی، "
        "اول فقط همون‌ها به‌عنوانِ یه لیستِ کوچیک نشون داده می‌شن."
    )
    try:
        await cb.message.edit_text(text, reply_markup=kb, parse_mode="HTML")
    except Exception:
        await cb.message.answer(text, reply_markup=kb, parse_mode="HTML")
    await cb.answer()


@tenant_router.callback_query(F.data.startswith("thb:togglesmmplat:"))
async def thb_togglesmmplat(cb: CallbackQuery, bot: Bot, state: FSMContext):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    _, _, mb_id_s, pkey = cb.data.split(":", 3)
    mb_id = int(mb_id_s)
    data = await state.get_data()
    if data.get("thb_smmplat_mb_id") != mb_id:
        await cb.answer("این صفحه منقضی شده؛ دوباره باز کن.", show_alert=True)
        return
    selected: list[str] = list(data.get("thb_smmplat_selected") or [])
    if pkey in selected:
        selected.remove(pkey)
    else:
        selected.append(pkey)
    await state.update_data(thb_smmplat_selected=selected)
    kb = await _thb_smmplat_kb(row.id, mb_id, selected)
    try:
        await cb.message.edit_reply_markup(reply_markup=kb)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.answer()


