@tenant_router.callback_query(F.data.startswith("thb:setvpnpanel:"))
async def thb_set_vpn_panel_choose(cb: CallbackQuery, bot: Bot):
    """نمایش منوی انتخاب پنل برای تنظیم اکشن دکمه."""
    row = await _owner_ok(cb, bot)
    if not row:
        return
    mb_id = int(cb.data.split(":")[2])

    # بررسی وضعیت هر پنل
    from tenant.bots.vpn.vpn_admin import get_all_panels
    panels_connected = await get_all_panels(row.id)
    connected_keys = {p.panel_key for p in panels_connected}
    enabled_keys = {p.panel_key for p in panels_connected if p.enabled}

    rows_kb = []
    panel_map = {
        "sanai":         ("buy_vpn_sanai",         "🔵 پنل سنایی"),
        "pasargad":      ("buy_vpn_pasargad",       "🟣 پنل پاسارگاد"),
        "pasarguard":    ("buy_vpn_pasarguard",     "🛡️ پنل PasarGuard"),
        "marzban":       ("buy_vpn_marzban",        "🟠 پنل مرزبان"),
        "marzneshin":    ("buy_vpn_marzneshin",     "⚪️ پنل مرزنشین"),
        "hiddify":       ("buy_vpn_hiddify",        "🟢 پنل هیدیفای"),
        "rebecca":       ("buy_vpn_rebecca",        "🔴 پنل ربکا"),
        "alireza":       ("buy_vpn_alireza",        "🟢 پنل علیرضا"),
        "upanel_mizban": ("buy_vpn_upanel_mizban",  "🟡 یوپنل (مرزبان)"),
        "nodex":         ("buy_vpn_nodex",          "🔷 پنل نودکس"),
        "degeris":       ("buy_vpn_degeris",        "🟣 پنل DEGERIS"),
        "eylan":         ("buy_vpn_eylan",          "🟠 پنل ایلان"),
        "heimdall":      ("buy_vpn_heimdall",       "🛡 پنل HEIMDALL"),
        "rickpanel":     ("buy_vpn_rickpanel",      "🟥 پنل RickPanel"),
    }
    # === PATCH_MULTI_PANEL_INSTANCES_V1 ===
    # پنل‌هایِ نمونه‌دار (pasargad#2 و ...) در panel_map نیستند چون آن نگاشت
    # فقط نوع‌هایِ پایه را دارد؛ اینجا از رویِ پنل‌هایِ واقعاً ثبت‌شدهٔ همین
    # ربات به فهرست اضافه می‌شوند، وگرنه مالک پنلِ دوم و سومش را در
    # «خرید از پنل» نمی‌دید.
    from tenant.bots.vpn.vpn_admin import PANEL_LABELS as _PLBL
    for _p in panels_connected:
        _k = _p.panel_key or ""
        if "#" in _k and _k not in panel_map:
            panel_map[_k] = (f"buy_vpn_{_k}", _PLBL.get(_k, _k))

    for key, (action, label) in panel_map.items():
        if key in enabled_keys:
            icon = "✅"
            note = " (فعال)"
        elif key in connected_keys:
            icon = "⚠️"
            note = " (متصل ولی غیرفعال)"
        else:
            icon = "❌"
            note = " (متصل نشده)"
        rows_kb.append([InlineKeyboardButton(
            text=f"{icon} {label}{note}",
            callback_data=f"thb:setvpnpanel_ok:{mb_id}:{key}", style=ButtonStyle.PRIMARY)])
    rows_kb.append([InlineKeyboardButton(text="⬅️ لغو", callback_data=f"thb:edit:{mb_id}", style=ButtonStyle.DANGER)])

    try:
        await cb.message.edit_text(
            "🛒 <b>تغییر اکشن دکمه — خرید از پنل</b>\n\n"
            "یک پنل را انتخاب کن:\n\n"
            "⚠️ اگر پنل «متصل نشده» است، اول در بخش «🛰 VPN خودکار» پنل را متصل و فعال کن.",
            reply_markup=InlineKeyboardMarkup(inline_keyboard=rows_kb))
    except Exception:
        await cb.message.answer(
            "🛒 <b>انتخاب پنل برای اکشن دکمه:</b>",
            reply_markup=InlineKeyboardMarkup(inline_keyboard=rows_kb))
    await cb.answer()


@tenant_router.callback_query(F.data.startswith("thb:setvpnpanel_ok:"))
async def thb_set_vpn_panel_ok(cb: CallbackQuery, bot: Bot):
    """ثبت اکشن خرید از پنل خاص روی دکمه."""
    row = await _owner_ok(cb, bot)
    if not row:
        return
    parts = cb.data.split(":")
    mb_id = int(parts[2])
    panel_key = parts[3]

    # === PATCH_MULTI_PANEL_INSTANCES_V1 === کلیدهای نمونه‌دار هم معتبرند
    from tenant.bots.vpn.vpn_admin import is_panel_key
    action = f"buy_vpn_{panel_key}" if is_panel_key(panel_key) else None
    if not action:
        await cb.answer("پنل نامعتبر", show_alert=True)
        return

    # بررسی اتصال پنل
    from tenant.bots.vpn.vpn_admin import get_panel, PANEL_LABELS
    panel = await get_panel(row.id, panel_key)
    label = PANEL_LABELS.get(panel_key, panel_key)

    if not panel:
        await cb.answer(
            f"⚠️ {label} هنوز متصل نشده!\n"
            "ابتدا در «🛰 VPN خودکار» پنل را ثبت کن.",
            show_alert=True)
        return

    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
        if mb and mb.bot_id == row.id:
            mb.action = action
            await s.commit()
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
    is_dis = mb_id in await _disabled_btn_ids(row.id)
    status_note = "✅ فعال" if (panel and panel.enabled) else "⚠️ غیرفعال (در VPN خودکار فعالش کن)"
    try:
        await cb.message.edit_text(
            f"✅ اکشن دکمه روی «خرید کانفیگ از {label}» تنظیم شد.\n"
            f"وضعیت پنل: {status_note}\n\n" + _thb_text(mb, is_dis),
            reply_markup=_thb_kb(mb, is_dis))
    except Exception:
        await cb.message.answer(_thb_text(mb, is_dis), reply_markup=_thb_kb(mb, is_dis))
    await cb.answer("تنظیم شد ✅")


@tenant_router.callback_query(F.data.startswith("thb:unsetvpnpanel:"))
async def thb_unset_vpn_panel(cb: CallbackQuery, bot: Bot):
    """حذف اکشن خرید از پنل."""
    row = await _owner_ok(cb, bot)
