# === PATCH_PLAN_FEATURE_GATING_V1 ===
@tenant_router.callback_query(F.data == "thb:bundle_locked")
async def thb_bundle_locked(cb: CallbackQuery):
    await cb.answer(upgrade_hint(Feature.COMBO_BUTTON), show_alert=True)


@tenant_router.callback_query(F.data.startswith("thb:setbundle:"))
async def thb_set_bundle_choose(cb: CallbackQuery, bot: Bot):
    """فهرستِ دسته‌های ترکیبیِ موجودِ این ربات برای وصل‌کردن به دکمه.

    این دسته‌ها همان MiniAppCategory هستند که برایِ فروشگاهِ مینی‌اپ ساخته
    می‌شوند؛ اینجا فقط نمایشِ چت‌محورِ تازه‌ای برایشان اضافه می‌شود — پس
    اگر مالک قبلاً دسته‌ای برایِ مینی‌اپ ساخته، همینجا هم می‌بیندش.
    """
    row = await _owner_ok(cb, bot)
    if not row:
        return
    # === PATCH_PLAN_FEATURE_GATING_V1 ===
    if not has_feature(row.plan, Feature.COMBO_BUTTON):
        await cb.answer(upgrade_hint(Feature.COMBO_BUTTON), show_alert=True)
        return
    mb_id = int(cb.data.split(":")[2])
    from models import MiniAppCategory
    async with Session() as s:
        cats = (await s.scalars(select(MiniAppCategory).where(
            MiniAppCategory.bot_id == row.id
        ).order_by(MiniAppCategory.sort_order, MiniAppCategory.id))).all()

    rows = [[InlineKeyboardButton(
        text=f"{'🟢' if c.active else '⚪️'} {c.icon or '🧩'} {c.title}",
        callback_data=f"thb:setbundle_ok:{mb_id}:{c.id}", style=ButtonStyle.PRIMARY)]
        for c in cats]
    # === PATCH_BUNDLE_ALL_MODES_V1 ===
    # دو گزینهٔ ویژه: به‌جایِ محدودشدن به یک دستهٔ ترکیبیِ خاص، همه‌چیز را
    # با هم نشان بده. کاملاً داخلِ همین دکمه است و هیچ ربطی به تنظیماتِ
    # مینی‌اپ ندارد.
    rows.append([InlineKeyboardButton(
        text="🌐 نمایشِ همهٔ دسته‌ها", callback_data=f"thb:setbundle_all:{mb_id}:cats",
        style=ButtonStyle.SUCCESS)])
    rows.append([InlineKeyboardButton(
        text="📦 نمایشِ همهٔ سرویس‌ها", callback_data=f"thb:setbundle_all:{mb_id}:svcs",
        style=ButtonStyle.SUCCESS)])
    rows.append([InlineKeyboardButton(
        text="➕ ساختنِ دستهٔ تازه", callback_data=f"thb:bundlenew:{mb_id}",
        style=ButtonStyle.SUCCESS)])
    rows.append([InlineKeyboardButton(text="⬅️ لغو", callback_data=f"thb:edit:{mb_id}",
                                      style=ButtonStyle.DANGER)])
    text = (
        "🧩 <b>خرید ترکیبی — انتخابِ دسته</b>\n\n"
        "یک دسته را انتخاب کن؛ هر پلنِ پنل (از هر پنلی) و هر دستهٔ انبار که "
        "زیرِ همین دسته گذاشته باشی، با هم زیرِ این دکمه نشان داده می‌شوند.\n\n"
        "یا اگر می‌خواهی به‌جایِ یک دستهٔ خاص، همه‌چیز را با هم نشان بدهی: "
        "«🌐 نمایشِ همهٔ دسته‌ها» فهرستِ همهٔ دسته‌ها را می‌دهد، و «📦 نمایشِ "
        "همهٔ سرویس‌ها» بدونِ هیچ محدودیتی همهٔ پلن‌ها و انبار را با هم "
        "نشان می‌دهد.\n\n"
        "اگر دسته‌ای نمی‌بینی یا می‌خواهی یکیِ تازه بسازی، «➕ ساختنِ دستهٔ "
        "تازه» را بزن؛ بعدش از همان‌جا می‌توانی پلن‌های چند پنل و "
        "دسته‌های انبار را زیرش جمع کنی."
    )
    try:
        await cb.message.edit_text(text, reply_markup=InlineKeyboardMarkup(inline_keyboard=rows))
    except Exception:
        await cb.message.answer(text, reply_markup=InlineKeyboardMarkup(inline_keyboard=rows))
    await cb.answer()


@tenant_router.callback_query(F.data.startswith("thb:bundlenew:"))
async def thb_bundle_new(cb: CallbackQuery, bot: Bot):
    """راهنمایی به صفحهٔ «دستهٔ جدید»یِ مینی‌اپ برای ساختنِ دستهٔ ترکیبی.

    عمداً هندلرِ miniapp_catnew را مستقیم صدا نمی‌زنیم (آن یک FSMContext
    واقعی از میان‌افزارِ دیسپچر می‌خواهد و اینجا نداریمش)؛ به‌جایش یک
    دکمهٔ واقعی با همان callback_data می‌دهیم تا خودِ تلگرام دوباره از
    مسیرِ عادیِ دیسپچ رد شود و state درست تزریق شود.
    """
    row = await _owner_ok(cb, bot)
    if not row:
        return
    mb_id = int(cb.data.split(":")[2])
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="➕ ساختنِ دستهٔ تازه", callback_data="miniapp:catnew",
                              style=ButtonStyle.SUCCESS)],
        [InlineKeyboardButton(text="⬅️ بازگشت", callback_data=f"thb:setbundle:{mb_id}",
                              style=ButtonStyle.DANGER)],
    ])
    await cb.message.answer(
        "🧩 برای ساختنِ دستهٔ تازه، «➕ ساختنِ دستهٔ تازه» را بزن — همان صفحهٔ "
        "معمولیِ دسته‌بندیِ مینی‌اپ باز می‌شود. بعدِ ساختنِ دسته و اضافه‌کردنِ "
        "پلن‌ها/انبار به آن، به همین دکمه برگرد و «🔁 تغییرِ دستهٔ ترکیبی» "
        "را دوباره بزن تا انتخابش کنی.", reply_markup=kb)
    await cb.answer()


@tenant_router.callback_query(F.data.startswith("thb:setbundle_ok:"))
async def thb_set_bundle_ok(cb: CallbackQuery, bot: Bot):
    """ثبتِ دستهٔ انتخاب‌شده روی دکمه."""
    row = await _owner_ok(cb, bot)
    if not row:
        return
    parts = cb.data.split(":")
    mb_id, cat_id = int(parts[2]), int(parts[3])
    from models import MiniAppCategory
    async with Session() as s:
        cat = await s.get(MiniAppCategory, cat_id)
        if not cat or cat.bot_id != row.id:
            await cb.answer("دسته پیدا نشد", show_alert=True)
            return
        mb = await s.get(MainButton, mb_id)
        if not mb or mb.bot_id != row.id:
            await cb.answer("یافت نشد", show_alert=True)
            return
        mb.action = "buy_bundle"
        mb.config = json.dumps({"miniapp_category_id": cat_id}, ensure_ascii=False)
        await s.commit()
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
    is_dis = mb_id in await _disabled_btn_ids(row.id)
    try:
        await cb.message.edit_text(
            f"✅ دکمه به دستهٔ «{cat.title}» وصل شد.\n\n" + _thb_text(mb, is_dis),
            reply_markup=_thb_kb(mb, is_dis))
    except Exception:
        await cb.message.answer(_thb_text(mb, is_dis), reply_markup=_thb_kb(mb, is_dis))
    await cb.answer("تنظیم شد ✅")


