@tenant_router.callback_query(F.data.startswith("thb:setbundle_all:"))
async def thb_set_bundle_all(cb: CallbackQuery, bot: Bot):
    """ثبتِ حالتِ «همهٔ دسته‌ها» یا «همهٔ سرویس‌ها» روی دکمه — بدونِ محدودشدن
    به یک دستهٔ ترکیبیِ خاص."""
    row = await _owner_ok(cb, bot)
    if not row:
        return
    parts = cb.data.split(":")  # thb:setbundle_all:{mb_id}:{cats|svcs}
    mb_id, kind = int(parts[2]), parts[3]
    if kind not in ("cats", "svcs"):
        await cb.answer("نامعتبر", show_alert=True)
        return
    mode = "all_categories" if kind == "cats" else "all_services"
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
        if not mb or mb.bot_id != row.id:
            await cb.answer("یافت نشد", show_alert=True)
            return
        mb.action = "buy_bundle"
        mb.config = json.dumps({"bundle_mode": mode}, ensure_ascii=False)
        await s.commit()
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
    is_dis = mb_id in await _disabled_btn_ids(row.id)
    label = "همهٔ دسته‌ها" if mode == "all_categories" else "همهٔ سرویس‌ها"
    try:
        await cb.message.edit_text(
            f"✅ دکمه رویِ «نمایشِ {label}» تنظیم شد.\n\n" + _thb_text(mb, is_dis),
            reply_markup=_thb_kb(mb, is_dis))
    except Exception:
        await cb.message.answer(_thb_text(mb, is_dis), reply_markup=_thb_kb(mb, is_dis))
    await cb.answer("تنظیم شد ✅")


