@tenant_router.callback_query(F.data.startswith("thb:suptoggle:"))
async def thb_support_toggle(cb: CallbackQuery, bot: Bot):
    """روشن/خاموش‌کردن دکمهٔ «پیام به پشتیبانی» زیر این دکمه."""
    row = await _owner_ok(cb, bot)
    if not row:
        return
    mb_id = int(cb.data.split(":")[2])
    warn = ""
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
        if mb and mb.bot_id == row.id:
            mb.support_btn = not bool(mb.support_btn)
            await s.commit()
    # اگر روشن شد ولی هیچ آدرس پشتیبانی‌ای (نه اختصاصیِ دکمه، نه عمومیِ قدیمی) تنظیم نشده، تذکر بده
    if not (await get_setting(row.id, "support_contact", "")) and \
       not ((mb.support_contact or "").strip() if mb else False):
        warn = "\n\n⚠️ هنوز پشتیبانی برای این دکمه تنظیم نشده؛ روی «🎧 پشتیبانِ این دکمه» بزن تا دکمه نمایش داده شود."
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
    if not mb:
        await cb.answer("یافت نشد", show_alert=True)
        return
    is_dis = mb_id in await _disabled_btn_ids(row.id)
    title = "💬 <b>پشتیبانیِ این دکمه</b>\nروشن/خاموش‌کردن، تنظیمِ آدرس اختصاصی و حذفِ آن از همین‌جا."
    text = title + "\n\n" + _thb_text(mb, is_dis) + warn
    try:
        await cb.message.edit_text(text, reply_markup=await _thb_kb_support(mb))
    except Exception:
        await cb.message.answer(text, reply_markup=await _thb_kb_support(mb))
    await cb.answer("تغییر کرد")


@tenant_router.callback_query(F.data.startswith("thb:supnotify:"))
async def thb_support_notify_toggle(cb: CallbackQuery, bot: Bot):
    """روشن/خاموش‌کردنِ «اطلاع از کلیک روی درخواست پشتیبانی کاربر» برای این دکمه.

    وقتی روشن باشد، هر بار کاربر روی دکمهٔ پشتیبانیِ این بخش بزند، به مالک و
    ادمین‌های پشتیبانی اعلان می‌رود که کاربر در آن بخش نیاز به پشتیبانی داشت."""
    row = await _owner_ok(cb, bot)
    if not row:
        return
    mb_id = int(cb.data.split(":")[2])
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
    if not mb or mb.bot_id != row.id:
        await cb.answer("یافت نشد", show_alert=True)
        return
    cur = await get_setting(row.id, f"sup_notify_{mb_id}", "0") == "1"
    await set_setting(row.id, f"sup_notify_{mb_id}", "0" if cur else "1")
    now_on = not cur
    is_dis = mb_id in await _disabled_btn_ids(row.id)
    title = ("💬 <b>پشتیبانیِ این دکمه</b>\n"
             "روشن/خاموش‌کردن، تنظیمِ آدرس اختصاصی و حذفِ آن از همین‌جا.")
    hint = ("\n\n🔔 اطلاع از کلیک: <b>روشن</b> — از این به بعد هر بار کاربری روی "
            "دکمهٔ پشتیبانیِ این بخش بزند، به شما و ادمین‌های پشتیبانی اعلان می‌رسد."
            if now_on else
            "\n\n🔕 اطلاع از کلیک: <b>خاموش</b> — کلیکِ کاربر روی دکمهٔ پشتیبانی "
            "بدون اعلان، مستقیم به چتِ پشتیبانی می‌رود.")
    text = title + "\n\n" + _thb_text(mb, is_dis) + hint
    try:
        await cb.message.edit_text(text, reply_markup=await _thb_kb_support(mb))
    except Exception:
        await cb.message.answer(text, reply_markup=await _thb_kb_support(mb))
    await cb.answer("تغییر کرد")


@tenant_router.callback_query(F.data.startswith("supclick:"))
async def support_click_notify(cb: CallbackQuery, bot: Bot):
    """کلیکِ کاربر روی دکمهٔ پشتیبانیِ یک بخش (وقتی «اطلاع از کلیک» روشن است):
    به ادمین‌ها اعلان می‌فرستد و لینکِ چتِ پشتیبانی را به کاربر می‌دهد."""
    row = await get_bot_row(bot)
    if not row:
        await cb.answer()
        return
    try:
        mb_id = int(cb.data.split(":")[1])
    except (ValueError, IndexError):
        await cb.answer()
        return
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
        u = await s.scalar(select(BotUser).where(
            BotUser.bot_id == row.id, BotUser.telegram_id == cb.from_user.id))
    if not mb or mb.bot_id != row.id:
        await cb.answer()
        return
    raw = (mb.support_contact or "").strip() or await get_setting(row.id, "support_contact", "")
    url, _disp = normalize_support(raw)
    if not url:
        await cb.answer("ℹ️ آدرس پشتیبانی هنوز تنظیم نشده است.", show_alert=True)
        return
    # اعلان به مالک و ادمین‌های پشتیبانی (اگر هنوز روشن باشد)
    if await get_setting(row.id, f"sup_notify_{mb.id}", "0") == "1":
        sec_label = _html.escape(mb.label or "—")
        cfg_block = await _admin_user_configs_block(row.id, u, bot_field=row.field)
        notif = (
            "🔔 <b>درخواست پشتیبانی</b>\n\n"
            f"{await _admin_user_block(u, cb.from_user.id, bot_id=row.id)}\n\n"
            + (f"{cfg_block}\n\n" if cfg_block else "")
            + f"📍 کاربر در بخش «<b>{sec_label}</b>» روی دکمهٔ پشتیبانی زد و "
            "نیاز به پشتیبانی داشت."
        )
        await _notify_admins(bot, row, notif)
    await cb.answer()
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="💬 ورود به چت پشتیبانی", url=url)],
    ])
    await cb.message.answer(
        "✅ درخواستت به پشتیبانی اطلاع داده شد.\n"
        "برای شروع گفتگو روی دکمهٔ زیر بزن 👇",
        reply_markup=kb,
    )


# === PATCH_PURCHASE_FOLLOWUP_V1 ===
@tenant_router.callback_query(F.data.startswith("vfup:cant:"))
async def vpn_followup_cant_connect(cb: CallbackQuery, bot: Bot):
    """کاربر روی «❌ متصل نشدم» زد: لینکِ پشتیبانی را بهش می‌دهیم و هم‌زمان به
    مالک/ادمین‌ها اطلاع می‌دهیم که این کاربر نیاز به پشتیبانی دارد + سرویس‌هایش."""
    row = await get_bot_row(bot)
    if not row:
        await cb.answer()
        return
    try:
        aid = int(cb.data.split(":")[2])
    except (ValueError, IndexError):
        await cb.answer()
        return
    async with Session() as s:
        a = await s.get(PanelAccount, aid)
        if a is not None and await _is_foreign(a, bot):   # PATCH_TENANT_SCOPE_V1
            a = None
        u = await s.scalar(select(BotUser).where(
            BotUser.bot_id == row.id, BotUser.telegram_id == cb.from_user.id))
    # آدرس پشتیبانی
    raw = await get_setting(row.id, "support_contact", "")
    url, _disp = normalize_support(raw)
    # اعلان به مالک/ادمین‌ها به‌همراه مشخصاتِ کاربر و سرویس‌هایش
    try:
        cfg_block = await _admin_user_configs_block(row.id, u, bot_field=row.field)
        notif = (
            "🆘 <b>کاربر در اتصال به مشکل خورده</b>\n\n"
            f"{await _admin_user_block(u, cb.from_user.id, bot_id=row.id)}\n\n"
            + (f"{cfg_block}\n\n" if cfg_block else "")
            + "📍 کاربر روی «❌ متصل نشدم» در پیگیریِ خرید زد و نیاز به پشتیبانی دارد."
        )
        await _notify_admins(bot, row, notif)
    except Exception:
        logger.exception("اعلانِ «نیاز به پشتیبانی» به مالک ناموفق بود")
    await cb.answer()
    if url:
        kb = InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text="💬 ورود به چت پشتیبانی", url=url)],
        ])
        await cb.message.answer(
            "متوجه شدم 🙏 نگران نباش، الان راهنماییت می‌کنیم.\n"
            "برای گفتگوی مستقیم با پشتیبانی روی دکمهٔ زیر بزن 👇\n"
            "(درخواستت همین الان به تیمِ ما هم اطلاع داده شد.)",
            reply_markup=kb,
        )
    else:
        await cb.message.answer(
            "متوجه شدم 🙏 درخواستت به پشتیبانیِ ربات اطلاع داده شد و "
            "به‌زودی باهات تماس می‌گیرند."
        )


