@tenant_router.message(HomeBtnFSM.set_btn_support, F.text)
async def thb_supcontact_save(msg: Message, bot: Bot, state: FSMContext):
    row = await get_bot_row(bot)
    if not row or not await is_owner_or_admin(row.id, msg.from_user.id, row.owner_id):
        await state.clear()
        return
    data = await state.get_data()
    mb_id = data.get("thb_id")
    raw = (msg.text or "").strip()
    kb = await main_kb_or_remove(row.id, row.owner_id, msg.from_user.id)
    if raw in ("❌ لغو", "❌ لغو / بازگشت"):
        await state.clear()
        await msg.answer("لغو شد.", reply_markup=kb or ReplyKeyboardRemove())
        return
    if not mb_id:
        await state.clear()
        await msg.answer("نامعتبر بود.", reply_markup=kb or ReplyKeyboardRemove())
        return
    url, disp = normalize_support(raw)
    if not url:
        await msg.answer("❌ ورودی نامعتبر بود. یک آیدی عددی، یوزرنیم یا لینک معتبر بفرست.")
        return
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
        if mb and mb.bot_id == row.id:
            mb.support_contact = raw
            await s.commit()
        mb = await s.get(MainButton, mb_id)
    await state.clear()
    await msg.answer(f"✅ پشتیبانِ این دکمه ذخیره شد: {disp}", reply_markup=kb or ReplyKeyboardRemove())
    if mb:
        is_dis = mb_id in await _disabled_btn_ids(row.id)
        await msg.answer(
            "💬 <b>پشتیبانیِ این دکمه</b>\n\n" + _thb_text(mb, is_dis),
            reply_markup=await _thb_kb_support(mb))


@tenant_router.callback_query(F.data.startswith("thb:supcontact_del:"))
async def thb_supcontact_del(cb: CallbackQuery, bot: Bot, state: FSMContext):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    mb_id = int(cb.data.split(":")[2])
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
        if not mb or mb.bot_id != row.id:
            await cb.answer("یافت نشد", show_alert=True)
            return
        had_contact = bool((mb.support_contact or "").strip())
        mb.support_contact = None
        await s.commit()
        mb = await s.get(MainButton, mb_id)
    await state.clear()
    is_dis = mb_id in await _disabled_btn_ids(row.id)
    title = "💬 <b>پشتیبانیِ این دکمه</b>\nروشن/خاموش‌کردن، تنظیمِ آدرس اختصاصی و حذفِ آن از همین‌جا."
    text = title + "\n\n" + _thb_text(mb, is_dis)
    try:
        await cb.message.edit_text(text, reply_markup=await _thb_kb_support(mb))
    except Exception:
        await cb.message.answer(text, reply_markup=await _thb_kb_support(mb))
    await cb.answer("✅ حذف شد" if had_contact else "چیزی برای حذف نبود")


_COLOR_NAMES = {"danger": "🔴 قرمز", "success": "🟢 سبز", "primary": "🔵 آبی", "none": "⚪️ پیش‌فرض"}


def _thb_color_kb(mb_id: int, sel: str = "", colored: bool = True) -> InlineKeyboardMarkup:
    """انتخابگر رنگ دومرحله‌ای: انتخاب (با تیک) → سپس «ثبت رنگ».

    sel: رنگِ انتخاب‌شدهٔ موقت (danger/success/primary/none).
    colored: اگر پلن دکمه‌های رنگی را پشتیبانی کند، خودِ دکمه‌های انتخاب هم رنگی می‌شوند.
    """
    def cell(val: str, label: str, style):
        txt = ("✅ " + label) if sel == val else label
        kw = {"text": txt, "callback_data": f"thb:colpick:{mb_id}:{val}"}
        if colored and style:
            kw["style"] = style
        return InlineKeyboardButton(**kw)

    rows = [
        [
            cell("danger", "قرمز", ButtonStyle.DANGER),
            cell("success", "سبز", ButtonStyle.SUCCESS),
            cell("primary", "آبی", ButtonStyle.PRIMARY),
        ],
        [cell("none", "⚪️ پیش‌فرض (بدون رنگ)", None)],
    ]
    # دکمهٔ ثبت فقط وقتی چیزی انتخاب شده باشد
    if sel:
        rows.append([InlineKeyboardButton(text=f"✅ ثبت رنگ ({_COLOR_NAMES.get(sel, sel)})",
                                          callback_data=f"thb:setcolor:{mb_id}:{sel}")])
    rows.append([InlineKeyboardButton(text="⬅️ بازگشت", callback_data=f"thb:pick:{mb_id}", style=ButtonStyle.DANGER)])
    return InlineKeyboardMarkup(inline_keyboard=rows)


@tenant_router.callback_query(F.data.startswith("thb:color:"))
async def thb_color_start(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    mb_id = int(cb.data.split(":")[2])
    colored = has_feature(row.plan, Feature.COLORED_BUTTONS)
    # رنگ فعلیِ دکمه به‌عنوان انتخابِ پیش‌فرض نشان داده می‌شود
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
        if mb is not None and await _is_foreign(mb, bot):   # PATCH_TENANT_SCOPE_V1
            mb = None
    cur = (mb.color if (mb and mb.color) else "")
    note = ""
    if not colored:
        note = ("\n\n⚠️ توجه: رنگی‌شدن دکمه‌ها فقط در پلن‌های رشد/حرفه‌ای نمایش داده می‌شود؛ "
                "در پلن فعلی رنگ ذخیره می‌شود ولی برای کاربران اعمال نمی‌شود.")
    txt = "🎨 یک رنگ انتخاب کن، سپس «✅ ثبت رنگ» را بزن تا اعمال شود:" + note
    try:
        await cb.message.edit_text(txt, reply_markup=_thb_color_kb(mb_id, cur, colored))
    except Exception:
        await cb.message.answer(txt, reply_markup=_thb_color_kb(mb_id, cur, colored))
    await cb.answer()


@tenant_router.callback_query(F.data.startswith("thb:colpick:"))
async def thb_color_pick(cb: CallbackQuery, bot: Bot):
    """انتخابِ موقت رنگ (هنوز ذخیره نمی‌شود) — فقط تیک می‌خورد و «ثبت» ظاهر می‌شود."""
    row = await _owner_ok(cb, bot)
    if not row:
        return
    parts = cb.data.split(":")
    mb_id, sel = int(parts[2]), parts[3]
    colored = has_feature(row.plan, Feature.COLORED_BUTTONS)
    try:
        await cb.message.edit_reply_markup(reply_markup=_thb_color_kb(mb_id, sel, colored))
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.answer(f"انتخاب شد: {_COLOR_NAMES.get(sel, sel)} — برای اعمال «ثبت رنگ» را بزن")


@tenant_router.callback_query(F.data.startswith("thb:setcolor:"))
async def thb_color_set(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    parts = cb.data.split(":")
