# ───── جابه‌جایی دکمه ─────

@tenant_router.callback_query(F.data.startswith("thb:move:"))
async def thb_move_start(cb: CallbackQuery, bot: Bot, state: FSMContext):
    """شروع فرآیند جابه‌جایی دکمه — پرسش ردیف مقصد."""
    row = await _owner_ok(cb, bot)
    if not row:
        return
    mb_id = int(cb.data.split(":")[2])
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
        if not mb or mb.bot_id != row.id:
            await cb.answer("یافت نشد", show_alert=True)
            return
        max_row = await s.scalar(
            select(func.max(MainButton.row)).where(
                MainButton.bot_id == row.id,
                MainButton.parent_id.is_(None) if mb.parent_id is None else MainButton.parent_id == mb.parent_id
            )
        ) or 1
        btn_label = mb.label
        current_row = mb.row

    await state.set_state(HomeBtnFSM.move_row)
    await state.update_data(thb_id=mb_id, move_max_row=max_row)
    try:
        await cb.message.edit_reply_markup(reply_markup=None)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")

    b = InlineKeyboardBuilder()
    for r_num in range(1, max_row + 2):
        suffix = ""
        if r_num == current_row:
            suffix = " ← فعلی"
        elif r_num == max_row + 1:
            suffix = " (ردیف جدید)"
        b.button(text=f"ردیف {r_num}{suffix}", callback_data=f"thb:moverow:{mb_id}:{r_num}", style=ButtonStyle.PRIMARY)
    b.button(text="❌ لغو", callback_data=f"thb:pick:{mb_id}", style=ButtonStyle.DANGER)
    b.adjust(1)

    await cb.message.answer(
        f"↕️ <b>جابه‌جایی دکمه «{btn_label}»</b>\n\n"
        f"ردیف فعلی: {current_row}\n\n"
        "کدام ردیف مقصد را انتخاب می‌کنی؟",
        reply_markup=b.as_markup()
    )
    await cb.answer()


@tenant_router.callback_query(F.data.startswith("thb:moverow:"))
async def thb_move_row_pick(cb: CallbackQuery, bot: Bot, state: FSMContext):
    """انتخاب ردیف — سپس پرسش موقعیت (چپ/وسط/راست)."""
    row = await _owner_ok(cb, bot)
    if not row:
        return
    parts = cb.data.split(":")
    mb_id, target_row = int(parts[2]), int(parts[3])

    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
        if not mb or mb.bot_id != row.id:
            await cb.answer("یافت نشد", show_alert=True)
            return
        btn_label = mb.label
        siblings = (await s.scalars(
            select(MainButton).where(
                MainButton.bot_id == row.id,
                MainButton.row == target_row,
                MainButton.id != mb_id,
                MainButton.parent_id.is_(None) if mb.parent_id is None else MainButton.parent_id == mb.parent_id
            ).order_by(MainButton.col)
        )).all()
        count = len(siblings)

    await state.update_data(move_target_row=target_row)
    await state.set_state(HomeBtnFSM.move_pos)

    pos_rows = []
    if count == 0:
        pos_rows.append([InlineKeyboardButton(text="✅ همین ردیف (تنها دکمه)", callback_data=f"thb:movepos:{mb_id}:{target_row}:0", style=ButtonStyle.SUCCESS)])
    else:
        pos_rows.append([InlineKeyboardButton(text="⬅️ چپ (اول)", callback_data=f"thb:movepos:{mb_id}:{target_row}:0", style=ButtonStyle.DANGER)])
        pos_rows.append([InlineKeyboardButton(text="⬆️ وسط", callback_data=f"thb:movepos:{mb_id}:{target_row}:mid", style=ButtonStyle.PRIMARY)])
        pos_rows.append([InlineKeyboardButton(text="➡️ راست (آخر)", callback_data=f"thb:movepos:{mb_id}:{target_row}:end", style=ButtonStyle.PRIMARY)])
        pos_rows.append([InlineKeyboardButton(text="1️⃣ تنها دکمه در این ردیف", callback_data=f"thb:movepos:{mb_id}:{target_row}:alone", style=ButtonStyle.PRIMARY)])
    pos_rows.append([InlineKeyboardButton(text="❌ لغو", callback_data=f"thb:pick:{mb_id}", style=ButtonStyle.DANGER)])

    await cb.message.edit_text(
        f"↕️ <b>جابه‌جایی «{btn_label}»</b>\n\n"
        f"ردیف مقصد: {target_row}"
        + (f"\nدکمه‌های موجود: {count}" if count > 0 else "\n(ردیف خالی)") +
        "\n\nکجا قرار بگیرد؟",
        reply_markup=InlineKeyboardMarkup(inline_keyboard=pos_rows)
    )
    await cb.answer()


@tenant_router.callback_query(F.data.startswith("thb:movepos:"))
async def thb_move_apply(cb: CallbackQuery, bot: Bot, state: FSMContext):
    """اعمال نهایی جابه‌جایی دکمه."""
    row = await _owner_ok(cb, bot)
    if not row:
        return
    parts = cb.data.split(":")
    mb_id, target_row, pos_raw = int(parts[2]), int(parts[3]), parts[4]

    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
        if not mb or mb.bot_id != row.id:
            await cb.answer("یافت نشد", show_alert=True)
            return
        siblings = list(await s.scalars(
            select(MainButton).where(
                MainButton.bot_id == row.id,
                MainButton.row == target_row,
                MainButton.id != mb_id,
                MainButton.parent_id.is_(None) if mb.parent_id is None else MainButton.parent_id == mb.parent_id
            ).order_by(MainButton.col)
        ))

        if pos_raw == "alone":
            new_col = 0
            # همه دکمه‌های این ردیف و پایین‌تر را یک ردیف پایین بکش
            all_btns_below = list(await s.scalars(
                select(MainButton).where(
                    MainButton.bot_id == row.id,
                    MainButton.row >= target_row,
                    MainButton.id != mb_id,
                    MainButton.parent_id.is_(None) if mb.parent_id is None else MainButton.parent_id == mb.parent_id
                )
            ))
            for b in all_btns_below:
                b.row = b.row + 1
        elif pos_raw == "0":
            new_col = 0
            for i, sib in enumerate(siblings):
                sib.col = i + 1
        elif pos_raw == "end":
            new_col = len(siblings)
        elif pos_raw == "mid":
            mid = len(siblings) // 2
            new_col = mid
            for i, sib in enumerate(siblings):
                sib.col = i + 1 if i >= mid else i
        else:
            new_col = 0

        mb.row = target_row
        mb.col = new_col
        await s.commit()
        mb = await s.get(MainButton, mb_id)

    await state.clear()
    await cb.answer(f"✅ دکمه به ردیف {target_row} منتقل شد.", show_alert=True)
    is_dis = mb_id in await _disabled_btn_ids(row.id)
    await cb.message.edit_text(_thb_text(mb, is_dis), reply_markup=_thb_kb(mb, is_dis))


