@tenant_router.callback_query(F.data.startswith("thb:dely:"))
async def thb_del_yes(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    mb_id = int(cb.data.split(":")[2])
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
        if mb and mb.bot_id == row.id:
            # حذف فرزندانِ زیرمنو (در صورت وجود)
            children = (await s.scalars(select(MainButton).where(
                MainButton.bot_id == row.id, MainButton.parent_id == mb_id))).all()
            child_ids = [c.id for c in children]
            # === PATCH_TICKET_SEND_BTN_DELETE_V1 ===
            # قبلِ حذفِ خودِ دکمه‌ها، رکوردهای «تست رایگانِ گرفته‌شده»
            # (button_trial_claims) که به این دکمه‌ها اشاره می‌کنن رو پاک
            # می‌کنیم — وگرنه فارین‌کیِ دیتابیس اجازه‌ی حذف نمی‌ده
            # (ForeignKeyViolationError: button_trial_claims_mb_id_fkey).
            from sqlalchemy import delete as _sa_delete
            from models import ButtonTrialClaim, GatedClaim, ButtonSlide, SlideFavorite
            all_ids = [mb_id, *child_ids]
            await s.execute(_sa_delete(ButtonTrialClaim).where(
                ButtonTrialClaim.mb_id.in_(all_ids)))
            # === PATCH_BTN_DELETE_FK_FIX_V1 ===
            # همون مشکلِ بالا برای دو جدولِ دیگه هم بود و باعثِ خطای
            # «ERR-XXXXXX» بدونِ هیچ پیامِ روشنی می‌شد: وقتی دکمه‌ای که
            # «گیتِ دسترسی/جایزهٔ پلکانی» روش فعال بود (gated_claims) یا
            # اسلایدشو داشت (button_slides) حذف می‌شد، دیتابیس با
            # ForeignKeyViolationError رد می‌کرد چون این دو جدول هم پاک
            # نمی‌شدن. الان قبل از حذفِ خودِ دکمه، این‌ها هم پاک می‌شن.
            await s.execute(_sa_delete(GatedClaim).where(
                GatedClaim.button_id.in_(all_ids)))
            # === PATCH_SLIDE_DELETE_FK_V1 ===
            # اسلایدهایِ این دکمه ممکنه تویِ علاقه‌مندی‌هایِ کاربرها باشن
            # (slide_favorites.slide_id → button_slides.id)؛ اگه اول اونا
            # پاک نشن، حذفِ خودِ اسلایدها با ForeignKeyViolationError رد می‌شه.
            _slide_ids = (await s.scalars(
                select(ButtonSlide.id).where(ButtonSlide.button_id.in_(all_ids)))).all()
            if _slide_ids:
                await s.execute(_sa_delete(SlideFavorite).where(
                    SlideFavorite.slide_id.in_(_slide_ids)))
            await s.execute(_sa_delete(ButtonSlide).where(
                ButtonSlide.button_id.in_(all_ids)))
            # === PATCH_BTN_DELETE_GATE_REFERRAL_FK_V1 ===
            # لینک‌های دعوتِ اختصاصیِ گیت که رویِ این دکمه‌ها ساخته شده‌ن،
            # به‌همراهِ عضوهایِ ثبت‌شده‌شون (gate_referral_joins).
            from models import GateReferralLink, GateReferralJoin
            _gate_link_ids = (await s.scalars(
                select(GateReferralLink.id).where(
                    GateReferralLink.button_id.in_(all_ids)))).all()
            if _gate_link_ids:
                await s.execute(_sa_delete(GateReferralJoin).where(
                    GateReferralJoin.link_id.in_(_gate_link_ids)))
                await s.execute(_sa_delete(GateReferralLink).where(
                    GateReferralLink.button_id.in_(all_ids)))
            for c in children:
                await s.delete(c)
            await s.delete(mb)
            await s.commit()
    # پاک‌کردن کلیدِ فعال/غیرفعالِ احتمالی
    try:
        await set_setting(row.id, f"hbtn_off:{mb_id}", "0")
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.answer("🗑 دکمه حذف شد")
    # بازگشت به فهرست دکمه‌ها با نمایش شیشه‌ای
    async with Session() as s:
        btns = (await s.scalars(select(MainButton).where(
                MainButton.bot_id == row.id, MainButton.parent_id.is_(None))
                .order_by(MainButton.row, MainButton.col))).all()
    disabled = await _disabled_btn_ids(row.id)

    rows_map: dict[int, list] = {}
    for b in btns:
        rows_map.setdefault(b.row, []).append(b)

    keyboard_rows = []
    for r_num in sorted(rows_map.keys()):
        row_btns = sorted(rows_map[r_num], key=lambda x: x.col)
        kb_row = []
        for b in row_btns:
            st = "🔴" if b.id in disabled else "🟢"
            sub_mark = " 🗂" if b.action == "submenu" else ""
            rule_mark = " 📜" if (b.rules or "").strip() else ""
            kb_row.append(InlineKeyboardButton(text=f"{st} {b.label}{sub_mark}{rule_mark}",
                                               callback_data=f"thb:pick:{b.id}", style=ButtonStyle.PRIMARY))
        keyboard_rows.append(kb_row)
    keyboard_rows.append([InlineKeyboardButton(text="➕ افزودن دکمه", callback_data="thb:add", style=ButtonStyle.SUCCESS)])
    keyboard_rows.append([InlineKeyboardButton(text="🔀 چیدمانِ سریع (بالا/پایین/کنارِهم)",
                                               callback_data="thbn:menu", style=ButtonStyle.PRIMARY)])  # PATCH_TENANT_QUICK_LAYOUT_V1
    keyboard_rows.append([InlineKeyboardButton(text="⬅️ بازگشت", callback_data="tadm:sec:settings",
                                               style=ButtonStyle.DANGER)])
    await cb.message.edit_text(
        "🏠 <b>مدیریت دکمه‌های صفحه اصلی</b>\n\n"
        "📱 چیدمان زیر دقیقاً همانند ربات شماست.\n"
        "🟢 فعال | 🔴 غیرفعال | 🗂 زیرمنو | 📜 دارای قانون\n\n"
        + ("روی هر دکمه بزن تا تغییرش بدهی، یا دکمهٔ جدید بساز:" if btns
           else "هنوز دکمه‌ای ساخته نشده. با «➕ افزودن دکمه» شروع کن."),
        reply_markup=InlineKeyboardMarkup(inline_keyboard=keyboard_rows),
    )


# ───── زیرمنو ─────

@tenant_router.callback_query(F.data.startswith("thb:sub:"))
async def thb_sub(cb: CallbackQuery, bot: Bot, state: FSMContext):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    mb_id = int(cb.data.split(":")[2])
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
        if not mb or mb.bot_id != row.id:
            await cb.answer("یافت نشد", show_alert=True)
            return
        if mb.action is None:
            mb.action = "submenu"
            await s.commit()
            mb = await s.get(MainButton, mb_id)
        elif mb.action != "submenu":
            await cb.answer("این دکمه عملکرد دیگری دارد و نمی‌تواند زیرمنو شود.", show_alert=True)
            return
        children = (await s.scalars(select(MainButton).where(
            MainButton.bot_id == row.id, MainButton.parent_id == mb_id)
            .order_by(MainButton.row, MainButton.col))).all()
        # breadcrumb: پدر دکمه را بخوان
        parent_mb = await s.get(MainButton, mb.parent_id) if mb.parent_id else None
    await state.clear()
    disabled = await _disabled_btn_ids(row.id)
    # === PATCH_SUBMENU_ROW_LAYOUT_V1 ===
    # قبلاً این‌جا هر دکمهٔ زیرمنو، فارغ از row/colِ واقعی‌اش، تکی و توی
    # ردیفِ خودش نمایش داده می‌شد — یعنی حتی اگه ادمین از «↕️ جابه‌جایی
    # دکمه» دو دکمه رو کنارِ هم (همون ردیف) گذاشته بود، همین‌جا (توی
    # مدیریتِ زیرمنو) بازم هرکدوم زیرِ هم دیده می‌شدن و چیدمانِ واقعی
    # اصلاً مشخص نبود. حالا دقیقاً مثلِ صفحهٔ «مدیریت دکمه‌های صفحهٔ اصلی»
    # دکمه‌ها بر اساسِ همون rowِ واقعی‌شون گروه‌بندی می‌شن؛ یعنی این صفحه
    # هم چیدمانِ واقعیِ زیرمنو رو (کنارِ هم/زیرِ هم) عیناً نشون می‌ده.
    rows_map: dict[int, list] = {}
    for c in children:
        rows_map.setdefault(c.row, []).append(c)
    rows = []
    for r_num in sorted(rows_map.keys()):
        row_btns = sorted(rows_map[r_num], key=lambda x: x.col)
        kb_row = []
        for c in row_btns:
            st = "🔴" if c.id in disabled else "🟢"
            sub_mark = " 🗂" if c.action == "submenu" else ""
            kb_row.append(InlineKeyboardButton(text=f"{st} {c.label}{sub_mark}",
                                               callback_data=f"thb:pick:{c.id}", style=ButtonStyle.PRIMARY))
        rows.append(kb_row)
    rows.append([InlineKeyboardButton(text="➕ افزودن دکمه به این زیرمنو",
                                      callback_data=f"thb:addsub:{mb_id}", style=ButtonStyle.SUCCESS)])
    # دکمه بازگشت: اگه خودش فرزنده، برگرد به زیرمنوی والدش؛ وگرنه به پنل دکمه
    rows.append([InlineKeyboardButton(text="⬅️ بازگشت به دکمه",
                                      callback_data=f"thb:pick:{mb_id}", style=ButtonStyle.DANGER)])
    # breadcrumb text
    if parent_mb:
        breadcrumb = f"📂 {parent_mb.label} ← 🗂 {mb.label}"
    else:
        breadcrumb = f"🗂 {mb.label}"
    await cb.message.edit_text(
        f"🗂 <b>زیرمنوی «{mb.label}»</b>  {('(سطح ۲+)' if parent_mb else '')}\n"
        f"<i>{breadcrumb}</i>\n\n"
        + ("📱 چیدمان زیر دقیقاً همانند خودِ زیرمنوی رباتته (دکمه‌های هم‌ردیف کنارِ هم دیده می‌شن).\n"
           "روی هر کدام بزن تا ویرایش شود؛ برای کنارِ‌هم/زیرِهم‌چیدن، وارد دکمه شو و «↕️ جابه‌جایی دکمه» را بزن:"
           if children
           else "این زیرمنو هنوز دکمه‌ای ندارد. با «➕ افزودن دکمه به این زیرمنو» شروع کن."),
        reply_markup=InlineKeyboardMarkup(inline_keyboard=rows),
    )
    await cb.answer()


# === PATCH_SUBMENU_UNSET_V1 ===
@tenant_router.callback_query(F.data.startswith("thb:unsetsubmenu:"))
async def thb_unsetsubmenu_ask(cb: CallbackQuery, bot: Bot):
    """قبل از تبدیلِ زیرمنو به عملکردِ دیگه، اگه فرزند داره هشدار می‌ده —
    چون تبدیل یعنی همهٔ دکمه‌هایِ داخلِ این زیرمنو هم حذف می‌شن (دقیقاً
    همون رفتاری که حذفِ خودِ دکمه هم داره)."""
    row = await _owner_ok(cb, bot)
    if not row:
        return
    mb_id = int(cb.data.split(":")[2])
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
        if not mb or mb.bot_id != row.id:
            await cb.answer("یافت نشد", show_alert=True)
            return
        n_children = await s.scalar(select(func.count()).select_from(MainButton).where(
            MainButton.bot_id == row.id, MainButton.parent_id == mb_id))
    if not n_children:
        # زیرمنویِ خالیه — نیازی به هشدار نیست، مستقیم ریست کن
        async with Session() as s:
            mb = await s.get(MainButton, mb_id)
            mb.action = None
            await s.commit()
        await cb.answer("✅ حذف شد؛ حالا می‌تونی عملکردِ جدید انتخاب کنی")
        is_disabled = mb_id in await _disabled_btn_ids(row.id)
        await cb.message.edit_text(_thb_text(mb, is_disabled), reply_markup=_thb_kb(mb, is_disabled))
        return
    await cb.message.edit_text(
        f"⚠️ این زیرمنو <b>{n_children}</b> تا دکمهٔ فرزند داره.\n\n"
        "اگه ادامه بدی، خودِ این دکمه از حالتِ «زیرمنو» درمیاد و <b>همهٔ دکمه‌هایِ "
        "داخلش هم حذف می‌شن</b> (مثلِ حذفِ کاملِ زیرمنو). این قابلِ‌برگشت نیست.\n\n"
        "اگه فقط می‌خوای بعضی از فرزندها رو نگه داری، اول از «🗂 مدیریتِ زیرمنو» "
        "برو داخلِ هرکدوم و جدا حذفشون کن، بعد برگرد اینجا.",
        parse_mode="HTML",
        reply_markup=InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text="✅ بله، زیرمنو و همهٔ فرزندانش حذف بشه",
                                  callback_data=f"thb:unsetsubmenuY:{mb_id}", style=ButtonStyle.DANGER)],
            [InlineKeyboardButton(text="❌ نه، بازگشت", callback_data=f"thb:pick:{mb_id}", style=ButtonStyle.DANGER)],
        ]))
    await cb.answer()


@tenant_router.callback_query(F.data.startswith("thb:unsetsubmenuY:"))
async def thb_unsetsubmenu_yes(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    mb_id = int(cb.data.split(":")[2])
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
        if not mb or mb.bot_id != row.id:
            await cb.answer("یافت نشد", show_alert=True)
            return
        children = (await s.scalars(select(MainButton).where(
            MainButton.bot_id == row.id, MainButton.parent_id == mb_id))).all()
        child_ids = [c.id for c in children]
        if child_ids:
            # === PATCH_SUBMENU_UNSET_V1 ===
            # همون پاکسازیِ جدول‌هایِ وابسته‌ای که حذفِ عادیِ دکمه (thb:dely:)
            # انجام می‌ده، عیناً برایِ فرزندانِ این زیرمنو هم لازمه — وگرنه
            # ForeignKeyViolationError می‌گیریم.
            from sqlalchemy import delete as _sa_delete
            from models import ButtonTrialClaim, GatedClaim, ButtonSlide, SlideFavorite, GateReferralLink, GateReferralJoin
            await s.execute(_sa_delete(ButtonTrialClaim).where(ButtonTrialClaim.mb_id.in_(child_ids)))
            await s.execute(_sa_delete(GatedClaim).where(GatedClaim.button_id.in_(child_ids)))
            _slide_ids = (await s.scalars(
                select(ButtonSlide.id).where(ButtonSlide.button_id.in_(child_ids)))).all()
            if _slide_ids:
                await s.execute(_sa_delete(SlideFavorite).where(SlideFavorite.slide_id.in_(_slide_ids)))
            await s.execute(_sa_delete(ButtonSlide).where(ButtonSlide.button_id.in_(child_ids)))
            _gate_link_ids = (await s.scalars(
                select(GateReferralLink.id).where(GateReferralLink.button_id.in_(child_ids)))).all()
            if _gate_link_ids:
                await s.execute(_sa_delete(GateReferralJoin).where(GateReferralJoin.link_id.in_(_gate_link_ids)))
                await s.execute(_sa_delete(GateReferralLink).where(GateReferralLink.button_id.in_(child_ids)))
            for c in children:
                await s.delete(c)
        mb.action = None
        mb.config = None
        await s.commit()
    # پاک‌کردن کلیدهایِ فعال/غیرفعالِ احتمالیِ فرزندانِ حذف‌شده
    for _cid in child_ids:
        try:
            await set_setting(row.id, f"hbtn_off:{_cid}", "0")
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.answer("✅ زیرمنو و فرزندانش حذف شدن؛ حالا می‌تونی عملکردِ جدید انتخاب کنی")
    is_disabled = mb_id in await _disabled_btn_ids(row.id)
    await cb.message.edit_text(_thb_text(mb, is_disabled), reply_markup=_thb_kb(mb, is_disabled))


