_RNG_META = {
    "vols":   ("📏 بازهٔ حجم (گیگ)", "گیگ"),
    "days":   ("📅 بازهٔ روز", "روز"),
    "counts": ("🔢 بازهٔ تعداد", "عدد"),
}


@tenant_router.callback_query(F.data.startswith("thb:rng:"))
async def thb_rng_start(cb: CallbackQuery, bot: Bot, state: FSMContext):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    _, _, key, mb_id = cb.data.split(":")
    if key not in _RNG_META:
        await cb.answer()
        return
    await state.set_state(HomeBtnFSM.btn_range)
    await state.update_data(thb_id=int(mb_id), rng_key=key)
    title = _RNG_META[key][0]
    try:
        await cb.message.edit_reply_markup(reply_markup=None)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.message.answer(
        f"{title} مخصوصِ این دکمه را بفرست:\n" + _RANGE_HINT,
        reply_markup=await smart_cancel_kb(bot),
    )
    await cb.answer()


@tenant_router.message(HomeBtnFSM.btn_range, F.text)
async def thb_rng_save(msg: Message, bot: Bot, state: FSMContext):
    row = await get_bot_row(bot)
    if not row or not await is_owner_or_admin(row.id, msg.from_user.id, row.owner_id):
        await state.clear()
        return
    data = await state.get_data()
    mb_id = data.get("thb_id")
    key = data.get("rng_key")
    raw = (msg.text or "").strip()
    kb = await main_kb_or_remove(row.id, row.owner_id, msg.from_user.id)
    if raw in ("❌ لغو", "❌ لغو / بازگشت"):
        await state.clear()
        await msg.answer("لغو شد.", reply_markup=kb or ReplyKeyboardRemove())
        return
    vals = [v for v in parse_opts(raw.replace("،", ","), []) if v > 0]
    if not vals or key not in _RNG_META:
        await msg.answer("نامعتبر. " + _RANGE_HINT)
        return
    await state.clear()
    async with Session() as s:
        mb = await s.get(MainButton, mb_id)
        if not mb or mb.bot_id != row.id:
            await msg.answer("دکمه یافت نشد.", reply_markup=kb or ReplyKeyboardRemove())
            return
        cfg = {}
        if mb.config:
            try:
                cfg = json.loads(mb.config) or {}
            except Exception:
                cfg = {}
        cfg[key] = vals
        mb.config = json.dumps(cfg, ensure_ascii=False)
        await s.commit()
        mb = await s.get(MainButton, mb_id)
    title, unit = _RNG_META[key]
    rng = (f"{min(vals)} تا {max(vals)} {unit}" if len(vals) > 1
           else f"{vals[0]} {unit} (ثابت)")
    await msg.answer(f"✅ {title} این دکمه: {rng}", reply_markup=kb or ReplyKeyboardRemove())
    is_dis = mb_id in await _disabled_btn_ids(row.id)
    await msg.answer(_thb_text(mb, is_dis), reply_markup=_thb_kb(mb, is_dis))


