@tenant_router.callback_query(F.data.startswith("thbtn:ok:"))
async def tenant_btn_rule_accept(cb: CallbackQuery, bot: Bot, state: FSMContext):
    mb_id = int(cb.data.split(":")[2])
    row = await get_bot_row(bot)
    if not row:
        await cb.answer()
        return
    bot_id = row.id
    async with Session() as s:
        btn = await s.get(MainButton, mb_id)
    if not btn or btn.bot_id != bot_id:
        await cb.answer("یافت نشد", show_alert=True)
        return
    if mb_id in await _disabled_btn_ids(bot_id):
        await cb.answer("این بخش غیرفعال است.", show_alert=True)
        return
    u = await get_or_create_user(bot_id, cb.from_user.id, cb.from_user.full_name,
                                 cb.from_user.username or "")
    # === PATCH_BUTTON_RULES_ONCE_PER_USER_V1 ===
    # از این به بعد این دکمه برایِ همین کاربر دیگه قوانین رو نشون نمی‌ده.
    await _btn_rules_mark(bot_id, btn, u.id)   # PATCH_RULES_VERSION_V1 (نسخه + تاریخ)
    await cb.answer()
    # === PATCH_RULES_EDIT_IN_PLACE_V1 === منویِ شیشه‌ای: بعد از پذیرشِ قوانین، همان پیام به صفحهٔ دکمه تبدیل می‌شود
    if cb.message is not None and await get_setting(bot_id, "menu_mode", "reply") == "inline":
        await _mbtn_proceed(cb, bot, state, row, u, bot_id, btn)
        return
    if cb.message is None:
        return
    # پیامِ قدیمی‌تر از ۴۸ ساعت InaccessibleMessage است و edit_reply_markup ندارد
    from bot_utils import is_live_message
    if is_live_message(cb.message):
        try:
            await cb.message.edit_reply_markup(reply_markup=None)
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    fake = cb.message.model_copy(update={"from_user": cb.from_user}).as_(bot)
    await _exec_main_button(btn, fake, bot, state, row, u, bot_id)



# ───── آمار ─────

@tenant_router.callback_query(F.data == "tadm:stats")
async def tadm_stats(cb: CallbackQuery, bot: Bot):
    row = await _gate(cb, bot, Feature.BOT_STATS)
    if not row:
        return
    start_utc, end_utc = _today_ir_range()
    async with Session() as s:
        users = await s.scalar(select(func.count()).select_from(BotUser).where(BotUser.bot_id == row.id))
        new_today = await s.scalar(select(func.count()).select_from(BotUser).where(
            BotUser.bot_id == row.id, BotUser.joined_at >= start_utc, BotUser.joined_at < end_utc)) or 0
        banned = await s.scalar(select(func.count()).select_from(BotUser).where(
            BotUser.bot_id == row.id, BotUser.is_banned == True)) or 0
        stock = await s.scalar(select(func.count()).select_from(Config).where(
            Config.bot_id == row.id, Config.status == "in_stock"))
        sold = await s.scalar(select(func.count()).select_from(Config).where(
            Config.bot_id == row.id, Config.status == "sold"))
        orders_paid = await s.scalar(select(func.count()).select_from(Order).where(
            Order.bot_id == row.id, Order.status == "paid"))
        revenue = await s.scalar(select(func.coalesce(func.sum(Order.amount), 0)).where(
            Order.bot_id == row.id, Order.status == "paid"))
        # کل مبلغ کارت‌به‌کارت‌شده (شارژ کیف‌پول + هر نوع خرید مستقیم با کارت‌به‌کارت)
        card_total = await s.scalar(select(func.coalesce(func.sum(Order.amount), 0)).where(
            Order.bot_id == row.id, Order.status == "paid",
            Order.pay_method.in_(["card", "card_charge", "mcfg_card", "vpn_card"]))) or 0
        # کل مبلغ شارژ کیف‌پول (از هر درگاهی/روشی: کارت، آقای‌پرداخت، سواپ‌ولت،
        # کریپتو، استارز، تون‌پیز، زرین‌پال، زیبال، آیدی‌پی، حساب‌پی، آبان‌گیت‌وی،
        # یونیک‌پی، تون/ترون مستقیم، و شارژِ دستیِ ادمین)
        # === PATCH_WALLET_CHARGE_TOTAL_ALL_KINDS_V1 ===
        # باگِ گزارش‌شده: این لیست فقط ۵ نوعِ قدیمیِ شارژ را می‌شمرد؛ شارژهایِ
        # واقعیِ کاربران از طریقِ TonPays یا تنظیمِ دستیِ ادمین (kind="admin")
        # اصلاً این‌جا حساب نمی‌شدند، در حالی که در جمعِ کلِ کارت‌به‌کارت هم
        # نبودند — یعنی گم می‌شدند و «کل شارژ کیف‌پول» را کمتر از واقعیت نشان
        # می‌دادند.
        wallet_charge_total = await s.scalar(select(func.coalesce(func.sum(WalletTxn.amount), 0)).where(
            WalletTxn.bot_id == row.id,
            WalletTxn.kind.in_([
                "charge", "aqp_charge", "swap_charge", "crypto_charge", "nowpay_charge",
                "tonpays_charge", "zarinpal_charge", "zibal_charge", "idpay_charge",
                "hesabpay_charge", "abangateway_charge", "abangateway_manual_admin", "abangw_manual",
                "uniquepay_charge", "apay_charge", "ton_direct", "tron_direct", "admin",
            ]))) or 0
        # کل تخفیفِ استفاده‌شده (تعداد کاربر یکتا + مجموع مبلغ صرفه‌جویی‌شده)
        discount_users = await s.scalar(
            select(func.count(func.distinct(DiscountUsage.telegram_id)))
            .where(DiscountUsage.bot_id == row.id)) or 0
        discount_total = await s.scalar(
            select(func.coalesce(func.sum(DiscountUsage.saved_amount), 0))
            .where(DiscountUsage.bot_id == row.id)) or 0
        tickets_open = await s.scalar(select(func.count()).select_from(TenantTicket).where(
            TenantTicket.bot_id == row.id, TenantTicket.status == "open"))
        # آمار زیرمجموعه‌گیری
        total_referrals = await s.scalar(
            select(func.count()).select_from(ReferralJoin).where(ReferralJoin.bot_id == row.id)
        ) or 0
        active_inviters = await s.scalar(
            select(func.count(func.distinct(ReferralJoin.inviter_user_id)))
            .select_from(ReferralJoin).where(ReferralJoin.bot_id == row.id)
        ) or 0
    # === PATCH_USER_LISTS_V1 ===
    async with Session() as s:
        blocked_cnt = await s.scalar(select(func.count()).select_from(BotUser).where(
            BotUser.bot_id == row.id, BotUser.is_blocked.is_(True))) or 0
        buyers_cnt = await s.scalar(
            select(func.count(func.distinct(Order.user_id))).where(
                Order.bot_id == row.id, Order.status == "paid")) or 0
        # === PATCH_BALANCE_HOLDERS_V1 ===
        # درخواستِ ادمین: یک منویِ شیشه‌ای برای دیدنِ کلیِ کاربرانی که موجودیِ
        # کیف‌پول‌شان بیشتر از صفر است (بدونِ نیاز به گشتن دستیِ لیستِ اعضا).
        balance_holders_cnt = await s.scalar(select(func.count()).select_from(BotUser).where(
            BotUser.bot_id == row.id, BotUser.balance > 0)) or 0
        balance_holders_total = await s.scalar(
            select(func.coalesce(func.sum(BotUser.balance), 0)).where(
                BotUser.bot_id == row.id, BotUser.balance > 0)) or 0
    kb_rows = [[InlineKeyboardButton(text="📊 گزارش زیرمجموعه‌ها", callback_data="tadm:ref_report", style=ButtonStyle.PRIMARY)]]
    kb_rows.append([InlineKeyboardButton(text=f"👥 اعضای ربات ({users})",
                                         callback_data="tadm:ulist:members:0", style=ButtonStyle.PRIMARY)])
    kb_rows.append([InlineKeyboardButton(text=f"👛 دارایِ موجودی ({balance_holders_cnt})",
                                         callback_data="tadm:ulist:balance:0", style=ButtonStyle.PRIMARY)])
    kb_rows.append([InlineKeyboardButton(text=f"🛒 خریدارانِ موفق ({buyers_cnt})",
                                         callback_data="tadm:ulist:buyers:0", style=ButtonStyle.PRIMARY)])
    kb_rows.append([InlineKeyboardButton(text=f"⛔️ بلاک‌کنندگانِ ربات ({blocked_cnt})",
                                         callback_data="tadm:ulist:blocked:0", style=ButtonStyle.PRIMARY)])
    kb_rows.append([InlineKeyboardButton(text=f"🚫 کاربران مسدود ({banned})",
                                         callback_data="tadm:ulist:banned:0", style=ButtonStyle.PRIMARY)])
    kb_rows.append([InlineKeyboardButton(text="⬅️ بازگشت", callback_data="tadm:sec:stats", style=ButtonStyle.DANGER)])
    kb = InlineKeyboardMarkup(inline_keyboard=kb_rows)
    _cfg_lines = (f"📦 کانفیگ موجود: {stock}\n"
                  f"✅ کانفیگ فروخته: {sold}\n") if row.field == "vpn_sales" else ""
    today_jdate = _jalali_date_time(_dt.datetime.utcnow())[0]
    discount_line = (f"🏷 تخفیفِ استفاده‌شده: {discount_users} کاربر — مجموعاً {rial(discount_total)}\n"
                     if discount_users else "🏷 تخفیفِ استفاده‌شده: هنوز استفاده نشده\n")
    await cb.message.edit_text(
        f"📊 <b>آمار ربات</b>\n\n"
        f"👥 اعضا: {users}\n"
        f"🆕 اعضای جدید امروز ({today_jdate}): {new_today}\n"
        f"🚫 کاربران مسدود: {banned}\n"
        + _cfg_lines +
        f"🧾 سفارش‌های موفق: {orders_paid}\n"
        f"💰 درآمد کل: {rial(revenue)}\n"
        f"💳 کل کارت‌به‌کارت‌شده: {rial(card_total)}\n"
        f"👛 کل شارژِ کیف‌پول: {rial(wallet_charge_total)}\n"
        f"👛 موجودیِ فعلیِ کاربران: {balance_holders_cnt} نفر — مجموعاً {rial(balance_holders_total)}\n"
        + discount_line +
        f"🎫 تیکت‌های باز: {tickets_open}\n\n"
        f"👥 کل دعوت‌های موفق: {total_referrals} نفر\n"
        f"🏆 کاربران فعال در دعوت: {active_inviters} نفر",
        reply_markup=kb,
    )
    await cb.answer()


# === PATCH_USER_LISTS_V1 ===

_ULIST_KINDS = {
    "members": ("👥 اعضای ربات", "هنوز کسی عضو نشده."),
    "buyers":  ("🛒 خریدارانِ موفق", "هنوز کسی خریدِ موفق نداشته."),
    "blocked": ("⛔️ بلاک‌کنندگانِ ربات", "فعلاً کسی ربات را بلاک نکرده "
                "(یا هنوز ارسالِ همگانی نزده‌ای تا مشخص شود)."),
    "banned":  ("🚫 کاربران مسدود", "هیچ کاربرِ مسدودی نیست."),
    # === PATCH_BALANCE_HOLDERS_V1 ===
    "balance": ("👛 دارایِ موجودی", "فعلاً هیچ کاربری موجودیِ کیف‌پولش بیشتر از صفر نیست."),
}


def _ulist_query(bot_id: int, kind: str):
    """کوئریِ پایهٔ هر لیست (بدونِ صفحه‌بندی)."""
    q = select(BotUser).where(BotUser.bot_id == bot_id)
    if kind == "blocked":
        q = q.where(BotUser.is_blocked.is_(True))
    elif kind == "banned":
        q = q.where(BotUser.is_banned.is_(True))
    elif kind == "buyers":
        paid = select(Order.user_id).where(Order.bot_id == bot_id,
                                           Order.status == "paid")
        q = q.where(BotUser.id.in_(paid))
    elif kind == "balance":
        # === PATCH_BALANCE_HOLDERS_V1 ===
        q = q.where(BotUser.balance > 0)
    return q


@tenant_router.callback_query(F.data.startswith("tadm:ulist:"))
async def tadm_user_list(cb: CallbackQuery, bot: Bot):
    """لیستِ کاربران به‌صورتِ دکمه‌هایِ شیشه‌ای؛ با زدنِ هر کدام کارتِ کامل باز می‌شود."""
    row = await _gate(cb, bot, Feature.BOT_STATS)
    if not row:
        return
    parts = cb.data.split(":")
    kind = parts[2]
    page = max(0, fa_to_int(parts[3]) or 0)
    if kind not in _ULIST_KINDS:
        await cb.answer("نامعتبر.", show_alert=True)
        return
    title, empty_note = _ULIST_KINDS[kind]
    per_page = 10
    base = _ulist_query(row.id, kind)
    # === PATCH_BALANCE_HOLDERS_V1 ===
    # برایِ لیستِ «دارایِ موجودی» مرتب‌سازی بر اساسِ بیشترین موجودی معنادارتر
    # است تا آیدیِ عددی (که برایِ بقیهٔ لیست‌ها همیشه صفحهٔ ثابتی تضمین می‌کند).
    order_col = BotUser.balance.desc() if kind == "balance" else BotUser.id.desc()
    async with Session() as s:
        total = await s.scalar(
            select(func.count()).select_from(base.subquery())) or 0
        items = (await s.scalars(
            base.order_by(order_col)
            .offset(page * per_page).limit(per_page))).all()

    rows = []
    if not items:
        text_out = f"{title}\n\n{empty_note}"
    else:
        pages = (total + per_page - 1) // per_page
        text_out = (f"<b>{title}</b> — {total} نفر "
                    f"(صفحهٔ {page + 1} از {pages})\n\n"
                    "رویِ هر کاربر بزن تا مشخصات و دکمه‌هایِ مدیریتش باز شود.")
        for u in items:
            uname = f"@{u.username}" if u.username else str(u.telegram_id)
            name = (u.full_name or "بی‌نام")[:28]
            # === PATCH_BALANCE_HOLDERS_V1 ===
            bal_suffix = f" — {rial(float(u.balance or 0))}" if kind == "balance" else ""
            rows.append([InlineKeyboardButton(
                text=f"👤 {name} — {uname}{bal_suffix}",
                callback_data=f"tadm:uinfo:{kind}:{page}:{u.telegram_id}", style=ButtonStyle.PRIMARY)])

    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton(text="◀️ قبلی",
                                        callback_data=f"tadm:ulist:{kind}:{page - 1}", style=ButtonStyle.PRIMARY))
    if (page + 1) * per_page < total:
        nav.append(InlineKeyboardButton(text="بعدی ▶️",
                                        callback_data=f"tadm:ulist:{kind}:{page + 1}", style=ButtonStyle.PRIMARY))
    if nav:
        rows.append(nav)
    rows.append([InlineKeyboardButton(text="⬅️ بازگشت به آمار", callback_data="tadm:stats", style=ButtonStyle.DANGER)])
    kb = InlineKeyboardMarkup(inline_keyboard=rows)
    try:
        await cb.message.edit_text(text_out, reply_markup=kb)
    except Exception:
        await cb.message.answer(text_out, reply_markup=kb)
    await cb.answer()


