@tenant_router.callback_query(F.data.startswith("tadm:banned_list:"))
async def tadm_banned_list(cb: CallbackQuery, bot: Bot):
    """لیستِ کاربرانِ مسدودشده، صفحه‌بندی‌شده (۱۰تا در هر صفحه)."""
    row = await _gate(cb, bot, Feature.BOT_STATS)
    if not row:
        return
    page = fa_to_int(cb.data.split(":")[-1]) or 0
    page = max(0, page)
    per_page = 10
    async with Session() as s:
        total = await s.scalar(select(func.count()).select_from(BotUser).where(
            BotUser.bot_id == row.id, BotUser.is_banned == True)) or 0
        banned_users = (await s.scalars(
            select(BotUser).where(BotUser.bot_id == row.id, BotUser.is_banned == True)
            .order_by(BotUser.id.desc()).offset(page * per_page).limit(per_page)
        )).all()
    if not banned_users:
        text_out = "🚫 <b>کاربران مسدود</b>\n\nهیچ کاربرِ مسدودی یافت نشد."
    else:
        lines = [f"🚫 <b>کاربران مسدود</b> — {total} نفر (صفحه {page + 1}):\n"]
        for u in banned_users:
            uname = f"@{u.username}" if u.username else "—"
            lines.append(f"• {_html.escape(u.full_name or '—')} ({uname}) — <code>{u.telegram_id}</code>")
        text_out = "\n".join(lines)
    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton(text="◀️ قبلی", callback_data=f"tadm:banned_list:{page-1}", style=ButtonStyle.PRIMARY))
    if (page + 1) * per_page < total:
        nav.append(InlineKeyboardButton(text="بعدی ▶️", callback_data=f"tadm:banned_list:{page+1}", style=ButtonStyle.PRIMARY))
    rows = [nav] if nav else []
    rows.append([InlineKeyboardButton(text="⬅️ بازگشت", callback_data="tadm:stats", style=ButtonStyle.DANGER)])
    try:
        await cb.message.edit_text(text_out, reply_markup=InlineKeyboardMarkup(inline_keyboard=rows))
    except Exception:
        await cb.message.answer(text_out, reply_markup=InlineKeyboardMarkup(inline_keyboard=rows))
    await cb.answer()



# گزارشِ تکراریِ «گزارش خریدها» (بخش آمار) حذف شد — نسخه‌ی کامل‌ترش
# («📊 گزارش کلی فروش ربات»، تابع _buyinfo_text_kb) در بخش مالی است.




# نام روزهای هفتهٔ شمسی به ترتیبِ weekday میلادی (Mon=0 .. Sun=6)
_JALALI_WEEKDAY_FA = {
    0: "دوشنبه", 1: "سه‌شنبه", 2: "چهارشنبه", 3: "پنجشنبه",
    4: "جمعه", 5: "شنبه", 6: "یکشنبه",
}


def _today_ir_range():
    """بازهٔ UTC معادلِ «امروز» به وقت ایران را برمی‌گرداند: (start_utc, end_utc)."""
    now_ir = _dt.datetime.utcnow() + _dt.timedelta(hours=3, minutes=30)
    start_ir = now_ir.replace(hour=0, minute=0, second=0, microsecond=0)
    end_ir = start_ir + _dt.timedelta(days=1)
    start_utc = start_ir - _dt.timedelta(hours=3, minutes=30)
    end_utc = end_ir - _dt.timedelta(hours=3, minutes=30)
    return start_utc, end_utc


def _today_ir_title() -> str:
    """تیتر «خریدهای امروز <روز هفته> — <تاریخ شمسی>»."""
    now_ir = _dt.datetime.utcnow() + _dt.timedelta(hours=3, minutes=30)
    wd = _JALALI_WEEKDAY_FA.get(now_ir.weekday(), "")
    if _jdt:
        date_str = _jdt.datetime.fromgregorian(datetime=now_ir).strftime("%Y/%m/%d")
    else:
        date_str = now_ir.strftime("%Y/%m/%d")
    return f"🛒 خریدهای امروز {wd} — {date_str}"


async def _buyinfo_text_kb(bot_id: int, scope: str, idx: int) -> tuple[str, InlineKeyboardMarkup]:
    """متن و کیبوردِ نمایشِ یک خرید در حالتِ «امروز» یا «کل».

    scope: "today" یا "all" — idx: جایگاه در لیست (۰=جدیدترین).
    """
    scope = "today" if scope == "today" else "all"
    async with Session() as s:
        base_q = select(Order).where(Order.bot_id == bot_id, Order.status == "paid")
        cnt_q = select(func.count(Order.id)).where(Order.bot_id == bot_id, Order.status == "paid")
        if scope == "today":
            start_utc, end_utc = _today_ir_range()
            base_q = base_q.where(Order.created_at >= start_utc, Order.created_at < end_utc)
            cnt_q = cnt_q.where(Order.created_at >= start_utc, Order.created_at < end_utc)

        total = await s.scalar(cnt_q) or 0

        # تیتر و دکمهٔ سوییچِ حالت
        if scope == "today":
            head = _today_ir_title()
            switch_btn = InlineKeyboardButton(
                text="📚 کل خریدهای ربات", callback_data="tadm:buyinfo:all:0", style=ButtonStyle.PRIMARY)
        else:
            head = "📚 کل خریدهای ربات"
            switch_btn = InlineKeyboardButton(
                text="🛒 خریدهای امروز", callback_data="tadm:buyinfo:today:0", style=ButtonStyle.PRIMARY)

        if total == 0:
            empty = ("هنوز امروز خریدی ثبت نشده." if scope == "today"
                     else "هنوز هیچ خرید موفقی ثبت نشده.")
            kb = InlineKeyboardMarkup(inline_keyboard=[
                [switch_btn],
                [InlineKeyboardButton(text="⬅️ بازگشت", callback_data="tadm:sec:finance", style=ButtonStyle.DANGER)],
            ])
            return f"📊 <b>گزارش کلی فروش ربات</b>\n\n{head}\n\n{empty}", kb

        idx = max(0, min(idx, total - 1))
        order = (await s.scalars(
            base_q.order_by(Order.created_at.desc(), Order.id.desc())
            .offset(idx).limit(1)
        )).first()

        buyer_block = "👤 خریدار: —"
        u = await s.get(BotUser, order.user_id) if order else None
        if u:
            uname = f"@{u.username}" if u.username else "—"
            buyer_block = (
                "👤 <b>مشخصات خریدار</b>\n"
                f"   • نام: {_html.escape(u.full_name or '—')}\n"
                f"   • یوزرنیم: {uname}\n"
                f"   • آیدی عددی: <code>{u.telegram_id}</code>\n"
                f"   • موجودی کیف پول: {rial(u.balance)}"
            )

        cfg = await s.get(Config, order.reserved_config_id) if order and order.reserved_config_id else None

    jdate, jtime = _jalali_date_time(order.created_at) if order else ("—", "—")

    if cfg:
        pkg_block = (
            "🛠 <b>بستهٔ فروخته‌شده</b>\n"
            f"   • کد کانفیگ: #{cfg.code}\n"
            f"   • حجم: {_cfg_vol_disp(cfg)} · مدت: {_cfg_days_disp(cfg)}\n"
            f"   • لینک: <code>{_html.escape((cfg.payload or '—')[:150])}</code>"
        )
    else:
        pkg_block = (
            "🛠 <b>مشخصات بسته</b>\n"
            f"   • حجم: {order.volume_gb} گیگ · مدت: {order.days} روز · تعداد: {order.count}\n"
            f"   • روش پرداخت: {order.pay_method}"
        )

    label = f" ({order.custom_label})" if order and order.custom_label else ""
    inv = order.invoice_no or "—"
    trk = order.tracking_code or "—"
    text_out = (
        f"📊 <b>گزارش کلی فروش ربات</b>\n"
        f"{head}\n"
        f"— خرید {idx + 1} از {total}\n\n"
        f"🧾 شناسه سفارش: <code>{_html.escape(str(trk if trk != '—' else inv))}</code>\n"
        f"🕒 تاریخ: {jdate} — ساعت: {jtime}\n"
        f"💰 مبلغ: {rial(order.amount)}{label}\n\n"
        f"{buyer_block}\n\n"
        f"{pkg_block}"
    )

    nav = []
    if idx < total - 1:
        nav.append(InlineKeyboardButton(text="◀️ قبلی", callback_data=f"tadm:buyinfo:{scope}:{idx+1}", style=ButtonStyle.PRIMARY))
    if idx > 0:
        nav.append(InlineKeyboardButton(text="بعدی ▶️", callback_data=f"tadm:buyinfo:{scope}:{idx-1}", style=ButtonStyle.PRIMARY))
    rows = []
    if nav:
        rows.append(nav)
    rows.append([switch_btn])
    rows.append([InlineKeyboardButton(text="⬅️ بازگشت", callback_data="tadm:sec:finance", style=ButtonStyle.DANGER)])
    kb = InlineKeyboardMarkup(inline_keyboard=rows)
    return text_out, kb


async def _charge_alert(bot: Bot, row: BotRow, *, buyer: "BotUser | None",
                        amount, method: str, new_balance=None) -> None:
    """اگر «اطلاع خودکار خرید» روشن باشد، شارژِ کیف پول را به ادمین‌ها گزارش می‌دهد.

    method: روشِ شارژ (مثلاً «کارت‌به‌کارت» یا «ارز دیجیتال»).
    """
    try:
        if await get_setting(row.id, "purchase_notify", "1") != "1":
            return
    except Exception:
        return
    if buyer is not None:
        uname = f"@{buyer.username}" if buyer.username else "—"
        buyer_line = (
            f"👤 کاربر: {_html.escape(buyer.full_name or '—')}\n"
            f"   • یوزرنیم: {uname}\n"
            f"   • آیدی عددی: <code>{buyer.telegram_id}</code>"
        )
    else:
        buyer_line = "👤 کاربر: —"
    jdate, jtime = _jalali_date_time(_dt.datetime.utcnow())
    bal_line = f"\n💼 موجودی جدید: {rial(new_balance)}" if new_balance is not None else ""
    text = (
        "💳 <b>شارژ کیف پول</b>\n\n"
        f"➕ مبلغ شارژ: {rial(amount)}\n"
        f"🔗 روش: <b>{_html.escape(method)}</b>{bal_line}\n"
        f"🕒 {jdate} — {jtime}\n\n"
        f"{buyer_line}"
    )
    try:
        await _notify_admins(bot, row, text)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")


async def _purchase_alert(bot: Bot, row: BotRow, *, buyer: "BotUser | None",
                          section: str, detail: str, amount,
                          order_id: int | None = None, product_id: int | None = None,
                          tracking_code: str | None = None, count: int = 1,
                          panel_name: str | None = None,
                          button_name: str | None = None,
                          public_detail: str | None = None) -> None:
    """دو کارِ مستقل انجام می‌دهد:
    ۱) اگر «اطلاع خودکار خرید» روشن باشد، به همهٔ ادمین‌ها پیامِ خرید جدید
       می‌فرستد — با یک دکمهٔ اینلاین برای بازکردنِ مستقیمِ پروفایلِ کاملِ
       خریدار. (PATCH_ALERT_PROFILE_BTN_V1)
    ۲) اگر یک «کانال اعتمادسازی» وصل باشد، گزارشِ عمومیِ این سفارش را
       آنجا هم پست می‌کند — این دو کاملاً مستقل‌اند (یکی خاموش بودنِ
       دیگری را متوقف نمی‌کند)، چون هدف‌شان فرق دارد: یکی اطلاع‌رسانیِ
       خصوصی به ادمین، دیگری تبلیغِ عمومیِ اعتمادسازی برایِ کانال.

    section: نوع/بخش خرید (مثلاً «فروشگاه دیجیتال» یا «سرویس VPN»).
    detail: توضیح بستهٔ خریداری‌شده (هم برایِ پیامِ ادمین، هم — اگر
    public_detail داده نشده باشد — به‌عنوانِ نامِ محصول در گزارشِ کانالِ
    اعتمادسازی استفاده می‌شود).

    === PATCH_TRUST_CHANNEL_NO_CUSTOM_LABEL_V1 ===
    گزارشِ کاربر: بعضی مسیرهایِ خرید (مثلاً VPN) اسمِ دلخواهی که خودِ
    خریدار برایِ کانفیگش تایپ کرده (custom_label) را به‌جایِ عنوانِ پلن در
    detail می‌گذارند؛ همان اسم — که می‌تواند اسمِ واقعیِ خریدار باشد —
    عمومی و بدونِ ماسک روی کانالِ اعتمادسازی پست می‌شد، درحالی‌که خودِ
    آیدیِ خریدار ماسک می‌شود. public_detail دقیقاً برایِ همین جداسازی
    است: وقتی پاس داده شود، کانالِ اعتمادسازی از آن استفاده می‌کند (نه از
    detail)، ولی پیامِ خصوصیِ ادمین همچنان detail را نشان می‌دهد.
    """
    try:
        from tenant.shared.trust_report import send_trust_channel_post
        await send_trust_channel_post(
            bot, row.id,
            buyer_telegram_id=(buyer.telegram_id if buyer else None),
            product_name=(public_detail or detail), amount=amount,
            order_id=order_id, product_id=product_id or order_id,
            tracking_code=tracking_code, count=count,
            bot_username=row.username,
            panel_name=panel_name,  # === PATCH_TRUST_CHANNEL_PANEL_NAME_V1 ===
            button_name=button_name,  # === PATCH_ORDER_BUTTON_ID_V1 ===
        )
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")

    try:
        if await get_setting(row.id, "purchase_notify", "1") != "1":
            return
    except Exception:
        return
    if buyer is not None:
        uname = f"@{buyer.username}" if buyer.username else "—"
        buyer_line = (
            f"👤 خریدار: <b>{_html.escape(buyer.full_name or '—')}</b>\n"
            f"   • یوزرنیم: {uname}\n"
            f"   • آیدی عددی: <code>{buyer.telegram_id}</code>"
        )
    else:
        buyer_line = "👤 خریدار: —"
    jdate, jtime = _jalali_date_time(_dt.datetime.utcnow())
    # === PATCH_ADMIN_ALERT_PANEL_NAME_V1 ===
    # panel_name/button_name قبلاً فقط برای پستِ کانالِ اعتمادسازی استفاده
    # می‌شد؛ اینجا هم اضافه می‌شود تا ادمین بداند خرید از کدام پنل یا
    # کدام پلنِ دستی انجام شده.
    source_line = ""
    if panel_name:
        source_line = f"🖥 پنل: <b>{_html.escape(panel_name)}</b>\n"
    elif button_name:
        source_line = f"📋 پلن: <b>{_html.escape(button_name)}</b>\n"
    text = (
        "🛍 <b>خرید جدید ثبت شد</b>\n"
        "┈┅━━⊷⊰✨⊱⊶━━┅┈\n"
        f"🗂 بخش: <b>{_html.escape(section)}</b>\n"
        f"📦 مشخصات: {detail}\n"
        f"{source_line}"
        f"💰 مبلغِ پرداخت‌شده: <b>{rial(amount)}</b>\n"
        f"🕒 {jdate} — {jtime}\n"
        "┈┅━━⊷⊰✨⊱⊶━━┅┈\n"
        f"{buyer_line}"
    )
    kb = None
    if buyer is not None:
        kb = InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text="👤 مشاهدهٔ پروفایل و جزئیاتِ خریدهای کاربر",
                                  callback_data=f"usr:back:{buyer.telegram_id}")],
        ])
    try:
        await _notify_admins(bot, row, text, kb=kb)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")


