async def _toggle_purchase_notify(cb: CallbackQuery, bot: Bot) -> None:
    """روشن/خاموش کردنِ «اطلاع خودکار خرید» و رفرشِ منویِ آمار و گزارشات.
    === PATCH_NOTIFY_TOGGLES_MOVED_TO_STATS_V1 === (قبلاً منویِ مالی رفرش می‌شد)."""
    row = await _gate(cb, bot, Feature.BOT_STATS)
    if not row:
        return
    cur = await get_setting(row.id, "purchase_notify", "1")
    new = "0" if cur == "1" else "1"
    await set_setting(row.id, "purchase_notify", new)
    await cb.answer("🔔 اطلاع خودکار خرید " + ("فعال شد" if new == "1" else "غیرفعال شد"))
    body = "📊 <b>آمار و گزارشات</b>\n\nآمار کاربران، تیکت‌ها و ارسال همگانی:"
    kb = await _sec_stats_kb(row.id, row.plan)
    try:
        await cb.message.edit_text(body, reply_markup=kb)
    except Exception:
        await cb.message.answer(body, reply_markup=kb)


