# ───── گزارش زیرمجموعه‌گیری ─────

@tenant_router.callback_query(F.data == "tadm:ref_report")
async def tadm_ref_report(cb: CallbackQuery, bot: Bot):
    """لیست کاربرانی که بیشترین زیرمجموعه آورده‌اند."""
    row = await _gate(cb, bot, Feature.BOT_STATS)
    if not row:
        return
    async with Session() as s:
        # برترین دعوت‌کنندگان (بر اساس join_count در ReferralLink)
        top_links = (await s.scalars(
            select(ReferralLink)
            .where(ReferralLink.bot_id == row.id, ReferralLink.join_count > 0)
            .order_by(ReferralLink.join_count.desc())
            .limit(20)
        )).all()
        # نام کاربران
        user_ids = [rl.user_id for rl in top_links]
        users_map = {}
        if user_ids:
            us = (await s.scalars(
                select(BotUser).where(BotUser.id.in_(user_ids))
            )).all()
            users_map = {u.id: u for u in us}
        # جمع کل دعوت‌های موفق
        total = await s.scalar(
            select(func.count()).select_from(ReferralJoin).where(ReferralJoin.bot_id == row.id)
        ) or 0

    # === PATCH_PARTNER_REF_REPORT_BACK_FIX_V1 ===
    # این صفحه برایِ ربات‌هایِ مستأجرِ معمولی زیرِ «آمار و گزارشات»ه، پس
    # بازگشتش به‌جا «tadm:stats» بود. ولی برایِ رباتِ همکار، «زیرمجموعه‌گیری»
    # مستقیماً از خانهٔ پنلِ همکار باز می‌شود (نه از زیرِ آمار)، پس دکمهٔ
    # بازگشت باید به «pp:home» برود؛ وگرنه کاربر سردرگم به صفحهٔ آمار
    # پرت می‌شد که اصلاً از آن‌جا وارد نشده بود.
    _back_cb = "pp:home" if row.plan == "partner" else "tadm:stats"

    if not top_links:
        await cb.message.edit_text(
            "📊 <b>گزارش زیرمجموعه‌گیری</b>\n\nهنوز هیچ دعوت موفقی ثبت نشده.",
            reply_markup=InlineKeyboardMarkup(inline_keyboard=[[
                InlineKeyboardButton(text="⬅️ بازگشت", callback_data=_back_cb, style=ButtonStyle.DANGER)
            ]])
        )
        await cb.answer()
        return

    # === PATCH_REF_INVITEE_LIST_V1 ===
    # هر دعوت‌کننده حالا یک دکمهٔ کلیک‌پذیر است که فهرستِ *دعوت‌شده‌هایش*
    # (یوزرنیم و آی‌دیِ عددی) را باز می‌کند.
    lines = []
    kb_rows = []
    for i, rl in enumerate(top_links, 1):
        u = users_map.get(rl.user_id)
        name = (u.full_name or f"کاربر {rl.user_id}") if u else f"کاربر {rl.user_id}"
        tg_id = u.telegram_id if u else "?"
        lines.append(
            f"{i}. <b>{name}</b> (<code>{tg_id}</code>)\n"
            f"   👥 دعوت موفق: {rl.join_count} | 👆 کلیک: {rl.click_count}"
        )
        kb_rows.append([InlineKeyboardButton(
            text=f"{i}. {name[:24]} — {rl.join_count} نفر",
            callback_data=f"refinv:{rl.user_id}:0",
            style=ButtonStyle.PRIMARY)])
    kb_rows.append([InlineKeyboardButton(
        text="⬅️ بازگشت", callback_data=_back_cb, style=ButtonStyle.DANGER)])

    text = (
        f"📊 <b>گزارش زیرمجموعه‌گیری</b>\n"
        f"کل دعوت‌های موفق: <b>{total}</b> نفر\n\n"
        + "\n".join(lines)
        + "\n\n👇 روی هر نفر بزن تا ببینی چه کسانی را دعوت کرده."
    )
    await cb.message.edit_text(
        text, reply_markup=InlineKeyboardMarkup(inline_keyboard=kb_rows))
    await cb.answer()


# === PATCH_REF_INVITEE_LIST_V1 ===
_REFINV_PAGE = 25


@tenant_router.callback_query(F.data.startswith("refinv:"))
async def tadm_ref_invitees(cb: CallbackQuery, bot: Bot):
    """فهرستِ کاربرانی که یک نفرِ خاص دعوتشان کرده — یوزرنیم و آی‌دیِ عددی."""
    row = await _gate(cb, bot, Feature.BOT_STATS)
    if not row:
        return
    parts = cb.data.split(":")
    inviter_uid = int(parts[1])
    page = int(parts[2]) if len(parts) > 2 else 0

    async with Session() as s:
        inviter = await s.get(BotUser, inviter_uid)
        if not inviter or inviter.bot_id != row.id:
            await cb.answer("کاربر پیدا نشد", show_alert=True)
            return
        total_inv = await s.scalar(
            select(func.count()).select_from(ReferralJoin).where(
                ReferralJoin.bot_id == row.id,
                ReferralJoin.inviter_user_id == inviter_uid)) or 0
        joins = (await s.scalars(
            select(ReferralJoin)
            .where(ReferralJoin.bot_id == row.id,
                   ReferralJoin.inviter_user_id == inviter_uid)
            .order_by(ReferralJoin.id.desc())
            .offset(page * _REFINV_PAGE).limit(_REFINV_PAGE)
        )).all()
        # اطلاعاتِ دعوت‌شده‌ها (اگر در همین ربات ثبت شده باشند)
        tg_ids = [j.referred_telegram_id for j in joins]
        inv_map = {}
        if tg_ids:
            us = (await s.scalars(select(BotUser).where(
                BotUser.bot_id == row.id,
                BotUser.telegram_id.in_(tg_ids)))).all()
            inv_map = {u.telegram_id: u for u in us}

    iname = inviter.full_name or f"کاربر {inviter_uid}"
    lines = [f"👥 <b>دعوت‌شدگانِ {iname}</b>",
             f"آی‌دی دعوت‌کننده: <code>{inviter.telegram_id}</code>",
             f"مجموع دعوت موفق: <b>{total_inv}</b> نفر\n"]
    if not joins:
        lines.append("در این صفحه چیزی نیست.")
    else:
        start = page * _REFINV_PAGE
        for i, j in enumerate(joins, start + 1):
            u = inv_map.get(j.referred_telegram_id)
            uname = f"@{u.username}" if (u and u.username) else "—"
            nm = (u.full_name if u and u.full_name else "کاربر")
            paid = int(float(j.reward_paid or 0))
            lines.append(
                f"{i}. {nm} · {uname}\n"
                f"   🆔 <code>{j.referred_telegram_id}</code>"
                + (f" · 🎁 {paid:,} تومان" if paid else ""))

    kb_rows = []
    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton(
            text="◀️ صفحهٔ قبل", callback_data=f"refinv:{inviter_uid}:{page-1}",
            style=ButtonStyle.PRIMARY))
    if (page + 1) * _REFINV_PAGE < total_inv:
        nav.append(InlineKeyboardButton(
            text="صفحهٔ بعد ▶️", callback_data=f"refinv:{inviter_uid}:{page+1}",
            style=ButtonStyle.PRIMARY))
    if nav:
        kb_rows.append(nav)
    kb_rows.append([InlineKeyboardButton(
        text="⬅️ بازگشت به فهرستِ دعوت‌کنندگان", callback_data="tadm:ref_report",
        style=ButtonStyle.DANGER)])

    txt = "\n".join(lines)
    if len(txt) > 3900:
        txt = txt[:3850] + "\n\n… (بقیه در صفحهٔ بعد)"
    try:
        await cb.message.edit_text(txt, reply_markup=InlineKeyboardMarkup(inline_keyboard=kb_rows))
    except Exception:
        await cb.message.answer(txt, reply_markup=InlineKeyboardMarkup(inline_keyboard=kb_rows))
    await cb.answer()


# ───── PATCH_VPN_PANEL_MARKET_V1 — ثبت و فروشِ پنل ─────

async def _pnlmkt_menu_content(row) -> tuple[str, InlineKeyboardMarkup]:
    """صفحه‌ی اصلیِ «🏷 ثبت و فروش پنل»: خلاصه + لیستِ ردیفیِ رنگیِ
    پنل‌هایِ موجود. پنل‌هایِ فروخته‌شده صفحه‌ی جدایِ خودشون رو دارن
    (pnlmkt:sold) — این‌جا فقط موجودی‌ها رو نشون می‌ده تا مدیریت راحت‌تر باشه."""
    async with Session() as s:
        panels = (await s.scalars(select(Config).where(
            Config.bot_id == row.id, Config.kind == "panel").order_by(Config.id.desc()))).all()
    stock_panels = [p for p in panels if p.status == "in_stock"]
    n_sold = len(panels) - len(stock_panels)
    rows = [
        [InlineKeyboardButton(text="➕ افزودنِ پنلِ جدید", callback_data="pnlmkt:add", style=ButtonStyle.SUCCESS)],
        [InlineKeyboardButton(text=f"🔴 پنل‌های فروخته‌شده ({n_sold})", callback_data="pnlmkt:sold",
                              style=ButtonStyle.DANGER)],
    ]
    for p in stock_panels[:50]:  # سقفِ نمایش، تا پیام خیلی بزرگ نشه
        try:
            d = json.loads(p.payload) or {}
        except Exception:
            d = {}
        name = d.get("name") or f"پنل #{p.code}"
        addr = d.get("address") or "—"
        uname = d.get("username") or "—"
        pw = d.get("password") or "—"
        rows.append([InlineKeyboardButton(
            text=f"🟢 {name} | {addr} | {uname} | {pw}",
            callback_data=f"pnlmkt:view:{p.id}", style=ButtonStyle.SUCCESS)])
    _br = await inline_back_row(row.id)
    if _br:
        rows.append(_br)
    text = (
        "🏷 <b>ثبت و فروش پنل</b>\n\n"
        f"🟢 موجود: <b>{len(stock_panels)}</b>   🔴 فروخته‌شده: <b>{n_sold}</b>\n\n"
        "برایِ فروشِ پنل به مشتری، یه دکمه بساز و «عملکردِ دکمه» ← «🏷 فروش پنل (ثبت و فروش پنل)» رو "
        "روش بذار؛ کاربر پنل‌هایِ موجود (به‌تفکیکِ دسته و قیمت) رو می‌بینه و از کیف پول می‌خره، "
        "بعد آدرس/یوزرنیم/پسوردِ همون پنل براش فرستاده می‌شه.\n\n"
        + ("رویِ هرکدوم از پنل‌های زیر بزن برایِ مدیریت (ویرایش/حذف):" if stock_panels else "هنوز پنلِ موجودی نداری.")
    )
    return text, InlineKeyboardMarkup(inline_keyboard=rows)


