_PNLF_FIELDS = {
    "name": ("🏷 نام/تگ", "pnl_name"),
    "category": ("📁 دسته‌بندی", "pnl_category"),
    "address": ("🌐 آدرس", "pnl_address"),
    "username": ("👤 یوزرنیم", "pnl_username"),
    "password": ("🔑 پسورد", "pnl_password"),
    "price": ("💰 قیمت (تومان)", "pnl_price"),
    # === PATCH_PANEL_SHOP_OPTIONAL_V1 === فیلدهایِ اختیاری (می‌شود خالی گذاشت)
    "traffic": ("📦 حجم (اختیاری)", "pnl_traffic"),
    "duration": ("📅 مدت (اختیاری)", "pnl_duration"),
    "inbounds": ("🔌 اینباندها (اختیاری)", "pnl_inbounds"),
    "features": ("✨ قابلیت‌ها/توضیحات (اختیاری)", "pnl_features"),
}
_PNLF_OPTIONAL = ("traffic", "duration", "inbounds", "features")


def _pnlf_text(data: dict) -> str:
    return ("🏷 <b>افزودنِ پنلِ جدید</b>\n\n"
            "رویِ هر دکمه بزن و مقدارش رو بفرست؛ وقتی همه پر شد «✅ ثبتِ پنل» رو بزن.\n"
            "فیلدهایِ «اختیاری» (حجم، مدت، اینباندها، قابلیت‌ها) رو می‌تونی خالی بذاری.")


def _pnlf_kb(data: dict) -> InlineKeyboardMarkup:
    def fmt(field: str) -> str:
        label, key = _PNLF_FIELDS[field]
        val = data.get(key)
        shown = f"{val:,}" if field == "price" and isinstance(val, int) else (val if val not in (None, "") else "—")
        shown = str(shown)
        if len(shown) > 28:   # PATCH_PANEL_MARKET_FIX_V3 مقدارِ بلند دکمه را نمی‌شکند
            shown = shown[:27] + "…"
        return f"{label}: {shown}"
    rows = [[InlineKeyboardButton(text=fmt(f), callback_data=f"pnlf:field:{f}", style=ButtonStyle.PRIMARY)]
            for f in _PNLF_FIELDS]
    rows.append([InlineKeyboardButton(text="✅ ثبتِ پنل", callback_data="pnlf:submit", style=ButtonStyle.SUCCESS)])
    rows.append([InlineKeyboardButton(text="⬅️ بازگشت", callback_data="pnlmkt:menu", style=ButtonStyle.DANGER)])
    return InlineKeyboardMarkup(inline_keyboard=rows)


async def _show_pnlf(target_msg: Message, state: FSMContext, edit: bool):
    """نمایش/به‌روزرسانیِ پیامِ فرمِ افزودنِ پنل — دقیقاً همون الگویِ
    _show_cfg_form (فرمِ افزودنِ کانفیگ): یه پیامِ واحد که سرِ جایِ خودش
    edit می‌شه، به‌جایِ فرستادنِ پیامِ تازه در هر مرحله."""
    data = await state.get_data()
    text, kb = _pnlf_text(data), _pnlf_kb(data)
    if edit:
        try:
            await target_msg.edit_text(text, reply_markup=kb)
            return
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    msg = await target_msg.answer(text, reply_markup=kb)
    await state.update_data(pnlf_chat_id=msg.chat.id, pnlf_msg_id=msg.message_id)


