@tenant_router.callback_query(PanelMarketFSM.form_wait, F.data.startswith("pnlf:field:"))
async def pnlf_field_pick(cb: CallbackQuery, bot: Bot, state: FSMContext):
    field = cb.data.split(":")[2]
    if field not in _PNLF_FIELDS:
        await cb.answer()
        return
    label, _ = _PNLF_FIELDS[field]
    extra_rows = []
    if field == "category":
        row = await get_bot_row(bot)
        if row:
            async with Session() as s:
                cats = [c for c in (await s.scalars(select(Config.category).where(
                    Config.bot_id == row.id, Config.kind == "panel",
                    Config.category.is_not(None)).distinct())).all() if c]
            for cat in cats:
                extra_rows.append([InlineKeyboardButton(
                    text=f"🏷 {cat}", callback_data=f"pnlf:catpick:{cat}", style=ButtonStyle.PRIMARY)])
        prompt = "📁 یکی از دسته‌هایِ موجود رو انتخاب کن، یا نامِ دسته‌ی جدید رو بفرست (برایِ بدون‌دسته «-» بفرست):"
    elif field == "price":
        prompt = f"{label} رو بفرست (فقط عدد، مثلاً 150000):"
    elif field in _PNLF_OPTIONAL:
        _ex = {"traffic": "مثلاً «500 گیگ» یا «2 ترابایت»", "duration": "مثلاً «3 ماه» یا «30 روز»",
               "inbounds": "مثلاً «VLESS-WS، Trojan-gRPC، Reality»",
               "features": "مثلاً «چندکاربره، ساب‌لینک، پشتیبانی ۲۴ ساعته»"}[field]
        prompt = f"{label} رو بفرست ({_ex}).\nبرای خالی‌گذاشتن/پاک‌کردن «-» بفرست:"
    else:
        prompt = f"{label} رو بفرست:"
    prompt_msg = await cb.message.answer(prompt, reply_markup=InlineKeyboardMarkup(inline_keyboard=[
        *extra_rows,
        [InlineKeyboardButton(text="⬅️ بازگشت به فرم", callback_data="pnlf:backform", style=ButtonStyle.DANGER)],
    ]))
    await state.update_data(pnlf_awaiting=field, pnlf_prompt_chat_id=prompt_msg.chat.id,
                            pnlf_prompt_msg_id=prompt_msg.message_id)
    await cb.answer()


async def _pnlf_refresh_form(bot: Bot, state: FSMContext, data: dict) -> None:
    """=== PATCH_PANEL_MARKET_FIX_V3 === فرم را رویِ همان پیام به‌روز می‌کند؛ اگر نشد (پیام پاک/قدیمی/خطایِ تلگرام)
    فرم را **از نو به‌صورتِ پیامِ جدید** می‌فرستد تا ادمین هرگز بدونِ دکمه نماند."""
    chat_id, form_msg_id = data.get("pnlf_chat_id"), data.get("pnlf_msg_id")
    text, kb = _pnlf_text(data), _pnlf_kb(data)
    try:
        await bot.edit_message_text(text, chat_id=chat_id, message_id=form_msg_id, reply_markup=kb)
        return
    except Exception as e:
        if "not modified" in str(e).lower():
            return
        logger.warning("ویرایشِ فرمِ پنل ممکن نشد؛ ارسالِ فرمِ تازه: %s", e)
    try:
        m = await bot.send_message(chat_id, text, reply_markup=kb)
        await state.update_data(pnlf_chat_id=m.chat.id, pnlf_msg_id=m.message_id)
    except Exception:
        logger.exception("ارسالِ فرمِ تازهٔ پنل هم ناموفق بود")


async def _pnlf_set_field_and_redisplay(target, state: FSMContext, bot: Bot, key: str, val) -> None:
    await state.update_data(**{key: val, "pnlf_awaiting": None})
    data = await state.get_data()
    prompt_chat_id, prompt_msg_id = data.get("pnlf_prompt_chat_id"), data.get("pnlf_prompt_msg_id")
    if prompt_chat_id and prompt_msg_id:
        try:
            await bot.delete_message(chat_id=prompt_chat_id, message_id=prompt_msg_id)
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await _pnlf_refresh_form(bot, state, data)


