@tenant_router.message(PanelMarketFSM.form_wait, F.text)
async def pnlf_field_value(msg: Message, bot: Bot, state: FSMContext):
    row = await get_bot_row(bot)
    if not row or not await is_owner_or_admin(row.id, msg.from_user.id, row.owner_id):
        await state.clear()
        return
    data = await state.get_data()
    field = data.get("pnlf_awaiting")
    if not field:
        return  # داره منتظرِ تپ‌کردنِ دکمه‌ست، نه تایپ
    raw = (msg.text or "").strip()
    try:
        await msg.delete()  # === پیامِ خودِ کاربر رو هم پاک کن تا چت شلوغ نشه ===
    except Exception:
        pass
    if field == "category":
        val = _sanitize_category(raw)   # === PATCH_PANEL_MARKET_FIX_V2 === حداکثر ۲۰ حرف، بدونِ «:»
    elif field == "price":
        val = fa_to_int(raw)
        if val is None or val < 0:
            data2 = await state.get_data()
            pchat, pmid = data2.get("pnlf_prompt_chat_id"), data2.get("pnlf_prompt_msg_id")
            if pchat and pmid:
                try:
                    await bot.edit_message_text("❗️ فقط عدد بفرست (مثلاً 150000):", chat_id=pchat, message_id=pmid,
                                                reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                                                    [InlineKeyboardButton(text="⬅️ بازگشت به فرم", callback_data="pnlf:backform", style=ButtonStyle.DANGER)]]))
                except Exception:
                    logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
            return
    elif field in _PNLF_OPTIONAL:
        val = None if raw in ("-", "") else raw[:300]   # PATCH_PANEL_SHOP_OPTIONAL_V1
    else:
        if not raw:
            return
        val = raw[:60] if field == "name" else raw[:500]   # PATCH_PANEL_MARKET_FIX_V2: نام ≤۶۰ (ستونِ custom_label)
    _, key = _PNLF_FIELDS[field]
    await _pnlf_set_field_and_redisplay(msg, state, bot, key, val)


@tenant_router.callback_query(PanelMarketFSM.form_wait, F.data == "pnlf:submit")
async def pnlf_submit(cb: CallbackQuery, bot: Bot, state: FSMContext):
    row = await _gate(cb, bot, Feature.VPN_PANEL_MARKET)
    if not row:
        return
    data = await state.get_data()
    missing = [lbl for f, (lbl, key) in _PNLF_FIELDS.items()
               if f != "category" and f not in _PNLF_OPTIONAL and not data.get(key)]
    if missing:
        await cb.answer(f"❗️ اول این‌ها رو پر کن: {'، '.join(missing)}", show_alert=True)
        return
    _pl = {
        "name": data.get("pnl_name"), "address": data.get("pnl_address"),
        "username": data.get("pnl_username"), "password": data.get("pnl_password"),
    }
    for _k in _PNLF_OPTIONAL:   # PATCH_PANEL_SHOP_OPTIONAL_V1
        if data.get(_PNLF_FIELDS[_k][1]):
            _pl[_k] = data.get(_PNLF_FIELDS[_k][1])
    payload = json.dumps(_pl, ensure_ascii=False)
    try:
        async with Session() as s:
            mx = await s.scalar(select(func.max(Config.code)).where(Config.bot_id == row.id))
            next_code = (mx + 1) if mx else CONFIG_CODE_START
            cfg = Config(bot_id=row.id, code=next_code, volume_gb=0, days=0,
                        payload=payload, status="in_stock", price=data.get("pnl_price") or 0,
                        category=data.get("pnl_category"), kind="panel",
                        custom_label=(data.get("pnl_name") or "")[:60])
            s.add(cfg)
            await s.commit()
    except Exception as _e:
        # === PATCH_PANEL_MARKET_FIX_V2 === قبلاً خطا بی‌صدا می‌ماند و ادمین «ثبت نمی‌شود» می‌دید
        logger.exception("ثبتِ پنل ناموفق بود")
        await cb.answer("❌ ثبت نشد: " + str(_e)[:150], show_alert=True)
        return
    await state.clear()
    await cb.answer("✅ ثبت شد")
    text, kb = await _pnlmkt_menu_content(row)
    text = f"✅ پنل «{data.get('pnl_name')}» ثبت شد.\n\n" + text
    try:
        await cb.message.edit_text(text, reply_markup=kb)
    except Exception:
        await cb.message.answer(text, reply_markup=kb)


