def _pnlmkt_detail_text_kb(p: "Config") -> tuple[str, InlineKeyboardMarkup]:
    """PATCH_VPN_PANEL_MARKET_EDIT_V1 — متن+کیبوردِ صفحه‌ی جزئیاتِ یه پنل،
    جدا شده تا هم نمایشِ اولیه هم بعدِ هر ویرایش، همینو دوباره بسازه و
    همون پیام رو edit کنه (نه پیامِ تازه)."""
    try:
        d = json.loads(p.payload) or {}
    except Exception:
        d = {}
    status_txt = "🟢 موجود (هنوز فروخته نشده)" if p.status == "in_stock" else "🔴 فروخته‌شده"
    _e = lambda v: _html.escape(str(v))   # PATCH_PANEL_MARKET_FIX_V2
    text = (
        f"🏷 <b>{_e(d.get('name') or f'پنل #{p.code}')}</b>\n\n"
        f"وضعیت: {status_txt}\n"
        f"دسته: {_e(p.category or '—')}\n"
        f"قیمت: {int(p.price or 0):,} تومان\n\n"
        f"🌐 آدرس: <code>{_e(d.get('address') or '—')}</code>\n"
        f"👤 یوزرنیم: <code>{_e(d.get('username') or '—')}</code>\n"
        f"🔑 پسورد: <code>{_e(d.get('password') or '—')}</code>"
        + (f"\n\n📦 حجم: {_e(d['traffic'])}" if d.get("traffic") else "")
        + (f"\n📅 مدت: {_e(d['duration'])}" if d.get("duration") else "")
        + (f"\n🔌 اینباندها: {_e(d['inbounds'])}" if d.get("inbounds") else "")
        + (f"\n✨ قابلیت‌ها: {_e(d['features'])}" if d.get("features") else "")
    )
    rows = []
    if p.status == "in_stock":
        rows.append([
            InlineKeyboardButton(text="✏️ نام", callback_data=f"pnlmkt:edit:name:{p.id}", style=ButtonStyle.PRIMARY),
            InlineKeyboardButton(text="✏️ آدرس", callback_data=f"pnlmkt:edit:address:{p.id}", style=ButtonStyle.PRIMARY),
        ])
        rows.append([
            InlineKeyboardButton(text="✏️ یوزرنیم", callback_data=f"pnlmkt:edit:username:{p.id}", style=ButtonStyle.PRIMARY),
            InlineKeyboardButton(text="✏️ پسورد", callback_data=f"pnlmkt:edit:password:{p.id}", style=ButtonStyle.PRIMARY),
        ])
        rows.append([
            InlineKeyboardButton(text="✏️ حجم", callback_data=f"pnlmkt:edit:traffic:{p.id}", style=ButtonStyle.PRIMARY),
            InlineKeyboardButton(text="✏️ مدت", callback_data=f"pnlmkt:edit:duration:{p.id}", style=ButtonStyle.PRIMARY),
        ])
        rows.append([
            InlineKeyboardButton(text="✏️ اینباندها", callback_data=f"pnlmkt:edit:inbounds:{p.id}", style=ButtonStyle.PRIMARY),
            InlineKeyboardButton(text="✏️ قابلیت‌ها", callback_data=f"pnlmkt:edit:features:{p.id}", style=ButtonStyle.PRIMARY),
        ])
        rows.append([InlineKeyboardButton(text="✏️ تغییرِ قیمت", callback_data=f"pnlmkt:edit:price:{p.id}",
                                          style=ButtonStyle.PRIMARY)])
        rows.append([InlineKeyboardButton(text="🗑 حذف", callback_data=f"pnlmkt:del:{p.id}",
                                          style=ButtonStyle.DANGER)])
    else:
        rows.append([InlineKeyboardButton(
            text="ℹ️ فروخته‌شده — قابلِ ویرایش/حذف نیست", callback_data="noop")])
    rows.append([InlineKeyboardButton(text="⬅️ بازگشت به لیست",
                                      callback_data=("pnlmkt:sold" if p.status != "in_stock" else "pnlmkt:menu"),
                                      style=ButtonStyle.DANGER)])
    return text, InlineKeyboardMarkup(inline_keyboard=rows)


@tenant_router.callback_query(F.data.startswith("pnlmkt:view:"))
async def pnlmkt_view(cb: CallbackQuery, bot: Bot, state: FSMContext):
    row = await _gate(cb, bot, Feature.VPN_PANEL_MARKET)
    if not row:
        return
    _st = await state.get_state()
    if _st and _st.startswith("PanelMarketFSM"):
        await state.clear()
    pid = int(cb.data.split(":")[2])
    async with Session() as s:
        p = await s.get(Config, pid)
    if not p or p.bot_id != row.id or p.kind != "panel":
        await cb.answer("یافت نشد", show_alert=True)
        return
    await cb.answer()
    text, kb = _pnlmkt_detail_text_kb(p)
    try:
        await cb.message.edit_text(text, reply_markup=kb)
    except Exception:
        await cb.message.answer(text, reply_markup=kb)


@tenant_router.callback_query(F.data.startswith("pnlmkt:del:"))
async def pnlmkt_del(cb: CallbackQuery, bot: Bot):
    row = await _gate(cb, bot, Feature.VPN_PANEL_MARKET)
    if not row:
        return
    pid = int(cb.data.split(":")[2])
    async with Session() as s:
        p = await s.get(Config, pid)
        if not p or p.bot_id != row.id or p.kind != "panel":
            await cb.answer("یافت نشد", show_alert=True)
            return
        if p.status != "in_stock":
            await cb.answer("این پنل فروخته شده؛ قابلِ حذف نیست.", show_alert=True)
            return
        await s.delete(p)
        await s.commit()
    await cb.answer("🗑 حذف شد")
    text, kb = await _pnlmkt_menu_content(row)
    try:
        await cb.message.edit_text(text, reply_markup=kb)
    except Exception:
        await cb.message.answer(text, reply_markup=kb)


# === PATCH_VPN_PANEL_MARKET_EDIT_V1 ===
# ویرایشِ هر ۵ فیلد (نام/آدرس/یوزرنیم/پسورد/قیمت) از یه هندلرِ واحد رد
# می‌شه: یه پیامِ کوچیکِ «مقدارِ جدید رو بفرست» زیرِ همون صفحه‌ی جزئیات
# می‌فرسته، و بعدِ دریافتِ جواب، پیامِ خودِ کاربر + همون پرامپت رو پاک
# می‌کنه و مستقیم رویِ همون پیامِ جزئیات (edit_text) نتیجه رو نشون می‌ده —
# هیچ پیامِ اضافه‌ای تو چت نمی‌مونه.
_PNLMKT_EDIT_LABELS = {
    "name": "🏷 نامِ جدید", "address": "🌐 آدرسِ جدید",
    "username": "👤 یوزرنیمِ جدید", "password": "🔑 پسوردِ جدید",
    "price": "💰 قیمتِ جدید (تومان)",
    "traffic": "📦 حجمِ جدید («-» برایِ پاک‌کردن)", "duration": "📅 مدتِ جدید («-» برایِ پاک‌کردن)",
    "inbounds": "🔌 اینباندهایِ جدید («-» برایِ پاک‌کردن)", "features": "✨ قابلیت‌هایِ جدید («-» برایِ پاک‌کردن)",
}


@tenant_router.callback_query(F.data.startswith("pnlmkt:edit:"))
async def pnlmkt_edit_start(cb: CallbackQuery, bot: Bot, state: FSMContext):
    row = await _gate(cb, bot, Feature.VPN_PANEL_MARKET)
    if not row:
        return
    _, _, field, pid_str = cb.data.split(":")
    pid = int(pid_str)
    if field not in _PNLMKT_EDIT_LABELS:
        await cb.answer()
        return
    async with Session() as s:
        p = await s.get(Config, pid)
    if not p or p.bot_id != row.id or p.kind != "panel" or p.status != "in_stock":
        await cb.answer("یافت نشد یا فروخته شده", show_alert=True)
        return
    await state.set_state(PanelMarketFSM.edit_field_wait)
    await state.update_data(pnl_edit_id=pid, pnl_edit_field=field,
                            pnl_edit_view_chat_id=cb.message.chat.id, pnl_edit_view_msg_id=cb.message.message_id)
    prompt_msg = await cb.message.answer(
        f"{_PNLMKT_EDIT_LABELS[field]} رو بفرست:",
        reply_markup=InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text="❌ لغو", callback_data="pnlmkt:editcancel", style=ButtonStyle.DANGER)]]))
    await state.update_data(pnl_edit_prompt_chat_id=prompt_msg.chat.id, pnl_edit_prompt_msg_id=prompt_msg.message_id)
    await cb.answer()


@tenant_router.callback_query(PanelMarketFSM.edit_field_wait, F.data == "pnlmkt:editcancel")
async def pnlmkt_edit_cancel(cb: CallbackQuery, bot: Bot, state: FSMContext):
    await state.clear()
    try:
        await cb.message.delete()
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.answer("لغو شد")


@tenant_router.message(PanelMarketFSM.edit_field_wait, F.text)
async def pnlmkt_edit_value(msg: Message, bot: Bot, state: FSMContext):
    row = await get_bot_row(bot)
    if not row or not await is_owner_or_admin(row.id, msg.from_user.id, row.owner_id):
        await state.clear()
        return
    data = await state.get_data()
    field = data.get("pnl_edit_field")
    pid = data.get("pnl_edit_id")
    raw = (msg.text or "").strip()
    try:
        await msg.delete()  # پیامِ خودِ کاربر رو هم پاک کن تا چت شلوغ نشه
    except Exception:
        pass
    prompt_chat_id, prompt_msg_id = data.get("pnl_edit_prompt_chat_id"), data.get("pnl_edit_prompt_msg_id")

    async def _reject(reason: str):
        if prompt_chat_id and prompt_msg_id:
            try:
                await bot.edit_message_text(
                    f"❗️ {reason}\n\n{_PNLMKT_EDIT_LABELS[field]} رو دوباره بفرست:",
                    chat_id=prompt_chat_id, message_id=prompt_msg_id,
                    reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                        [InlineKeyboardButton(text="❌ لغو", callback_data="pnlmkt:editcancel", style=ButtonStyle.DANGER)]]))
            except Exception:
                logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")

    if field == "price":
        val = fa_to_int(raw)
        if val is None or val < 0:
            await _reject("فقط عدد بفرست (مثلاً 150000):")
            return
    elif field in _PNLF_OPTIONAL:
        val = None if raw in ("-", "") else raw[:300]   # PATCH_PANEL_SHOP_OPTIONAL_V1
    else:
        if not raw:
            await _reject("یه مقدارِ معتبر بفرست:")
            return
        val = raw[:60] if field == "name" else raw[:500]   # PATCH_PANEL_MARKET_FIX_V2
    await state.clear()
    async with Session() as s:
        p = await s.get(Config, pid)
        if not p or p.bot_id != row.id or p.kind != "panel" or p.status != "in_stock":
            if prompt_chat_id and prompt_msg_id:
                try:
                    await bot.edit_message_text("⚠️ این پنل دیگه در دسترس نیست (شاید فروخته شده).",
                                                chat_id=prompt_chat_id, message_id=prompt_msg_id)
                except Exception:
                    logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
            return
        if field == "price":
            p.price = val
        else:
            try:
                d = json.loads(p.payload) or {}
            except Exception:
                d = {}
            if val is None:
                d.pop(field, None)
            else:
                d[field] = val
            p.payload = json.dumps(d, ensure_ascii=False)
            if field == "name":
                p.custom_label = val
        await s.commit()
        await s.refresh(p)
    # پرامپتِ کوچیک رو پاک کن، پیامِ اصلیِ جزئیات رو edit کن — هیچ پیامِ جدیدی نمی‌مونه.
    if prompt_chat_id and prompt_msg_id:
        try:
            await bot.delete_message(chat_id=prompt_chat_id, message_id=prompt_msg_id)
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    view_chat_id, view_msg_id = data.get("pnl_edit_view_chat_id"), data.get("pnl_edit_view_msg_id")
    text, kb = _pnlmkt_detail_text_kb(p)
    if view_chat_id and view_msg_id:
        try:
            await bot.edit_message_text(text, chat_id=view_chat_id, message_id=view_msg_id, reply_markup=kb)
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")




