def cfg_manage_kb(plan: str = "") -> InlineKeyboardMarkup:
    # === PATCH_OPENVPN_PLAN_GATE_V1 ===
    # بخشِ اوپن‌وی‌پی‌ان فقط برایِ پلن‌هایی که قابلیتش را دارند ساخته
    # می‌شود. اگر plan داده نشود (فراخوانی‌هایِ قدیمی)، محافظه‌کارانه
    # نمایش داده می‌شود و گیتِ اصلی در خودِ هندلر اعمال می‌شود.
    _ovpn_rows = []
    if (not plan) or has_feature(plan, Feature.OPENVPN_CONFIG):
        _ovpn_rows = [
            [InlineKeyboardButton(text="🔐 کانفیگ اوپن‌وی‌پی‌ان (فایل)", callback_data="noop")],
            [InlineKeyboardButton(text="➕ افزودن اوپن‌وی‌پی‌ان آماده",
                                  callback_data="tadm:cfg:add_ovpn", style=ButtonStyle.DANGER)],
            [InlineKeyboardButton(text="➕ افزودن اوپن‌وی‌پی‌ان نامحدود",
                                  callback_data="tadm:cfg:add_ovpn_unlimited", style=ButtonStyle.DANGER)],
        ]
    return InlineKeyboardMarkup(inline_keyboard=[
        # ── انبار / مدیریت ──
        [InlineKeyboardButton(text="📦 انبار کانفیگ‌های دستی", callback_data="noop")],
        [InlineKeyboardButton(text="📋 لیست انبار", callback_data="tadm:cfg:list", style=ButtonStyle.PRIMARY)],
        [InlineKeyboardButton(text="✏️ ویرایش کانفیگ", callback_data="tadm:cfg:edit", style=ButtonStyle.PRIMARY),
         InlineKeyboardButton(text="🗑 حذف کانفیگ", callback_data="tadm:cfg:del", style=ButtonStyle.DANGER)],
        [InlineKeyboardButton(text="🧨 حذف تمام کانفیگ‌های موجود",
                              callback_data="tadm:cfg:delall", style=ButtonStyle.DANGER)],
        [InlineKeyboardButton(text="🔍 جستجو با کد", callback_data="tadm:cfg:search", style=ButtonStyle.PRIMARY)],
        # ── یادداشت‌های انبار دستی ──
        [InlineKeyboardButton(text="📝 یادداشت‌های انبار دستی", callback_data="noop")],
        [InlineKeyboardButton(text="🧾 یادداشت پیش‌فاکتور", callback_data="mcfgnote:invoice"),
         InlineKeyboardButton(text="📦 یادداشت تحویل", callback_data="mcfgnote:delivery")],
        # === PATCH_STOCK_MANUAL_DELIVERY_V1 === صفِ تحویلِ دستیِ کانفیگ آماده (زیرِ همین انبار)
        [InlineKeyboardButton(text="📬 صف تحویل (تحویل دستیِ کانفیگ آماده)", callback_data="sdl:menu",
                              style=ButtonStyle.PRIMARY)],
        # === PATCH_STOCK_GIVE_TO_USER_V1 === دادن دستی کانفیگ انبار (آماده/نامحدود) به یک کاربر
        [InlineKeyboardButton(text="🎁 افزودن کانفیگ انبار به کاربر", callback_data="sg:menu",
                              style=ButtonStyle.SUCCESS)],
        # ── کانفیگ آماده ──
        [InlineKeyboardButton(text="🛒 کانفیگ آماده", callback_data="noop")],
        [InlineKeyboardButton(text="➕ افزودن کانفیگ آماده", callback_data="tadm:cfg:add", style=ButtonStyle.SUCCESS)],
        # === PATCH_CFG_BULK_SUBLINKS_V1 ===
        [InlineKeyboardButton(text="📚 ثبت دسته‌جمعی کانفیگ آماده", callback_data="tadm:cfg:bulk",
                              style=ButtonStyle.SUCCESS)],
        # ── کانفیگ نامحدود ──
        [InlineKeyboardButton(text="♾️ کانفیگ نامحدود", callback_data="noop")],
        [InlineKeyboardButton(text="➕ افزودن کانفیگ نامحدود", callback_data="tadm:cfg:add_unlimited", style=ButtonStyle.SUCCESS)],
        # === PATCH_CFG_BULK_SUBLINKS_V1 ===
        [InlineKeyboardButton(text="📚 ثبت دسته‌جمعی کانفیگ نامحدود", callback_data="tadm:cfg:bulk_unlimited",
                              style=ButtonStyle.SUCCESS)],
        # === PATCH_DNS_STOCK_V1 === بخشِ DNS (لینک ساب) ──
        [InlineKeyboardButton(text="🌐 DNS (با لینک ساب)", callback_data="noop")],
        [InlineKeyboardButton(text="➕ افزودن DNS", callback_data="tadm:cfg:add_dns", style=ButtonStyle.SUCCESS)],
        # === PATCH_WIREGUARD_CONFIG_V1 === کانفیگ وایرگارد (فایل) ──
        [InlineKeyboardButton(text="🛡️ کانفیگ وایرگارد (فایل)", callback_data="noop")],
        [InlineKeyboardButton(text="➕ افزودن وایرگارد آماده", callback_data="tadm:cfg:add_wg", style=ButtonStyle.DANGER)],
        [InlineKeyboardButton(text="➕ افزودن وایرگارد نامحدود", callback_data="tadm:cfg:add_wg_unlimited", style=ButtonStyle.DANGER)],
        # === PATCH_OPENVPN_CONFIG_V1 === بخشِ جدا برایِ اوپن‌وی‌پی‌ان ──
        *_ovpn_rows,
        # ── اتصال به دکمه‌های ربات ──
        # === PATCH_CFG_LINK_GUIDE_V1 ===
        # قبلاً اینجا دو دکمهٔ «اتصال «کانفیگ آماده»/«کانفیگ نامحدود» به
        # دکمه» بود که خودشان یک ویزاردِ جداگانه و گیج‌کننده برایِ
        # پیداکردن/ساختنِ دکمه در همین صفحه اجرا می‌کردند — درحالی‌که
        # راهِ درست و از‌قبل‌موجود، رفتن به «🎛 دکمه‌ها و تنظیمات» و از
        # آن‌جا تنظیمِ «عملکردِ دکمه» است. حالا به‌جایِ آن دو دکمه، فقط یک
        # راهنما هست که مسیرِ درست را نشان می‌دهد.
        [InlineKeyboardButton(text="📖 راهنمایِ اتصال به دکمه", callback_data="tadm:cfg:link_guide")],
        # ── بک‌آپ کانفیگ‌ها ──
        [InlineKeyboardButton(text="💾 بک‌آپ گیری از کانفیگ‌ها", callback_data="noop")],
        [InlineKeyboardButton(text="📤 بک‌آپ کانفیگ آماده", callback_data="tadm:cfg:backup_normal", style=ButtonStyle.PRIMARY),
         InlineKeyboardButton(text="📤 بک‌آپ کانفیگ نامحدود", callback_data="tadm:cfg:backup_unlimited", style=ButtonStyle.PRIMARY)],
        [InlineKeyboardButton(text="📥 ایمپورت بک‌آپ", callback_data="tadm:cfg:import", style=ButtonStyle.PRIMARY)],
        [InlineKeyboardButton(text="⬅️ بازگشت", callback_data="tadm:sec:products", style=ButtonStyle.DANGER)],
    ])


_MCFG_NOTE_META = {
    "invoice":  {"title": "یادداشت پیش‌فاکتور", "where": "زیر قیمت در پیش‌فاکتورِ خرید انبار دستی نمایش داده می‌شود."},
    "delivery": {"title": "یادداشت تحویل",       "where": "در پیام تحویل کانفیگِ انبار دستی نمایش داده می‌شود."},
}

# === PATCH_MCFG_NOTE_PER_SOURCE_V1 ===
# باگِ گزارش‌شده: «یادداشتِ تحویل» یک متنِ سراسری بود؛ یادداشتی که ادمین
# مخصوصِ کانفیگِ «نامحدود» نوشته بود، عیناً موقعِ تحویلِ کانفیگِ «حجمی
# (آماده)» هم نشان داده می‌شد و راهی برایِ جداکردنشان نبود. حالا مثلِ
# «آموزش اتصال»، هر یادداشت می‌تواند مخصوصِ یکی از این دو منبع باشد؛
# گزینهٔ «🌐 مشترک (پیش‌فرض)» همان یادداشتِ قدیمی/سراسری است که وقتی
# منبعی یادداشتِ اختصاصی ندارد، به آن برمی‌گردیم.
_MCFG_NOTE_SOURCES = [
    ("common", "🌐 مشترک (پیش‌فرض)"),
    ("manual", "📦 دستی حجمی (آماده)"),
    ("unlimited", "♾️ دستی نامحدود"),
]
_MCFG_NOTE_SOURCE_LABELS = dict(_MCFG_NOTE_SOURCES)


async def _mcfg_note_get(bot_id: int, kind: str, source: str) -> str:
    if source == "common":
        return await get_mcfg_note(bot_id, kind)
    return (await get_setting(bot_id, _mcfg_note_pkey_src(kind, source), "")).strip()


async def _mcfg_note_set(bot_id: int, kind: str, source: str, value: str):
    if source == "common":
        await set_mcfg_note(bot_id, kind, value)
    else:
        await set_mcfg_note_src(bot_id, kind, source, value)


def _mcfg_note_picker_kb(kind: str) -> InlineKeyboardMarkup:
    rows = [[InlineKeyboardButton(text=label, callback_data=f"mcfgnote:{kind}:src:{src}", style=ButtonStyle.PRIMARY)]
            for src, label in _MCFG_NOTE_SOURCES]
    rows.append([InlineKeyboardButton(text="⬅️ بازگشت", callback_data="tadm:cfg", style=ButtonStyle.DANGER)])
    return InlineKeyboardMarkup(inline_keyboard=rows)


def _mcfg_note_picker_text(kind: str) -> str:
    meta = _MCFG_NOTE_META[kind]
    return (
        f"{meta['title']}\n\n"
        f"{meta['where']}\n\n"
        "می‌تونی برایِ «دستی حجمی» و «دستی نامحدود» متنِ جداگانه بذاری — هرکدوم "
        "که یادداشتِ اختصاصیِ خودش را نداشته باشد، از یادداشتِ «🌐 مشترک» استفاده "
        "می‌کند.\n\n"
        "برای کدوم بخش می‌خوای تنظیم/ویرایش کنی؟"
    )


def _mcfg_note_kb(kind: str, source: str, current: str) -> InlineKeyboardMarkup:
    edit_label = "✏️ ویرایش متن" if current else "➕ افزودن متن"
    rows = [[InlineKeyboardButton(text=edit_label, callback_data=f"mcfgnote:{kind}:src:{source}:edit")]]
    if current:
        rows.append([InlineKeyboardButton(text="🗑 حذف متن", callback_data=f"mcfgnote:{kind}:src:{source}:del")])
    # === PATCH_MCFG_NOTE_CATMAP_V1 ===
    if source in ("manual", "unlimited"):
        rows.append([InlineKeyboardButton(
            text="🏷 یادداشت‌های اختصاصی بر اساس دسته‌بندی",
            callback_data=f"mcfgnote:catlist:{kind}:{source}", style=ButtonStyle.PRIMARY)])
    rows.append([InlineKeyboardButton(text="⬅️ بازگشت", callback_data=f"mcfgnote:{kind}", style=ButtonStyle.DANGER)])
    return InlineKeyboardMarkup(inline_keyboard=rows)


def _mcfg_note_text(kind: str, source: str, current: str) -> str:
    meta = _MCFG_NOTE_META[kind]
    src_label = _MCFG_NOTE_SOURCE_LABELS.get(source, source)
    cur_disp = current if current else "— (تنظیم نشده)"
    # === PATCH_MCFG_NOTE_CATMAP_V1 ===
    catnote = (
        "\n\nℹ️ این، یادداشتِ «عمومیِ» این بخش است. اگر پایین‌تر برای بعضی "
        "دسته‌بندی‌ها یادداشتِ اختصاصی تعریف کنی، کانفیگ‌های همون دسته‌ها "
        "به‌جای این متن، یادداشتِ اختصاصیِ خودشون رو نشون می‌دن؛ این متن فقط "
        "برایِ دسته‌هایی که یادداشتِ اختصاصی ندارن استفاده می‌شود."
    ) if source in ("manual", "unlimited") else ""
    return (
        f"{meta['title']} — {src_label}\n\n"
        f"{meta['where']}"
        f"{catnote}\n\n"
        f"متن فعلی:\n<blockquote>{cur_disp}</blockquote>"
    )


@tenant_router.callback_query(F.data.in_(["mcfgnote:invoice", "mcfgnote:delivery"]))
async def mcfg_note_open(cb: CallbackQuery, bot: Bot):
    """PATCH_MCFG_NOTE_PER_SOURCE_V1 — این دو کلید قبلاً مستقیم متنِ سراسری
    را باز می‌کردند؛ حالا اول صفحهٔ انتخابِ منبع (مشترک/حجمی/نامحدود) را
    نشان می‌دهند. دکمه‌هایِ قدیمیِ همین دو کلید در چت‌هایِ فعلی همچنان کار
    می‌کنند، فقط یک لایهٔ انتخاب اضافه شده — دقیقاً همان الگویِ «آموزش
    اتصال»."""
    if not await _gate(cb, bot, Feature.MANUAL_INVENTORY):
        return
    kind = cb.data.split(":")[1]
    row = await get_bot_row(bot)
    if not row:
        await cb.answer()
        return
    try:
        await cb.message.edit_text(_mcfg_note_picker_text(kind), reply_markup=_mcfg_note_picker_kb(kind))
    except Exception:
        await cb.message.answer(_mcfg_note_picker_text(kind), reply_markup=_mcfg_note_picker_kb(kind))
    await cb.answer()


@tenant_router.callback_query(F.data.startswith("mcfgnote:") & F.data.contains(":src:") & ~F.data.endswith(":edit") & ~F.data.endswith(":del"))
async def mcfg_note_open_src(cb: CallbackQuery, bot: Bot):
    # === PATCH_MCFGNOTE_DELIVERY_SUBSTRING_FIX_V1 ===
    # باگ: فیلترِ این هندلر با contains(":edit")/contains(":del") به‌جایِ
    # endswith چک می‌شد. مقدارِ kind برایِ یادداشتِ تحویل "delivery" است که
    # خودش با ":del" شروع می‌شود (":delivery")، پس callback_dataیِ
    # "mcfgnote:delivery:src:common" به‌اشتباه با contains(":del") مچ
    # می‌شد و از این هندلر رد می‌شد — یعنی همهٔ دکمه‌هایِ زیرمنویِ «یادداشت
    # تحویل» بی‌پاسخ می‌ماندند (فقط اسپینر بسته می‌شد). برایِ «یادداشت
    # پیش‌فاکتور» (invoice) این مشکل نبود چون کلمه "del" داخلش نیست.
    if not await _gate(cb, bot, Feature.MANUAL_INVENTORY):
        return
    parts = cb.data.split(":")
    kind, source = parts[1], parts[3]
    row = await get_bot_row(bot)
    if not row:
        await cb.answer()
        return
    current = await _mcfg_note_get(row.id, kind, source)
    try:
        await cb.message.edit_text(_mcfg_note_text(kind, source, current), reply_markup=_mcfg_note_kb(kind, source, current))
    except Exception:
        await cb.message.answer(_mcfg_note_text(kind, source, current), reply_markup=_mcfg_note_kb(kind, source, current))
    await cb.answer()


@tenant_router.callback_query(F.data.startswith("mcfgnote:") & F.data.contains(":src:") & F.data.endswith(":del"))
async def mcfg_note_delete(cb: CallbackQuery, bot: Bot):
    parts = cb.data.split(":")
    kind, source = parts[1], parts[3]
    row = await get_bot_row(bot)
    if not row:
        await cb.answer()
        return
    await _mcfg_note_set(row.id, kind, source, "")
    try:
        await cb.message.edit_text(_mcfg_note_text(kind, source, ""), reply_markup=_mcfg_note_kb(kind, source, ""))
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.answer("✅ حذف شد.")


@tenant_router.callback_query(F.data.startswith("mcfgnote:") & F.data.contains(":src:") & F.data.endswith(":edit"))
async def mcfg_note_edit_start(cb: CallbackQuery, bot: Bot, state: FSMContext):
    parts = cb.data.split(":")
    kind, source = parts[1], parts[3]
    row = await get_bot_row(bot)
    if not row:
        await cb.answer()
        return
    fsm_state = _ManualCfgNoteFSM.invoice if kind == "invoice" else _ManualCfgNoteFSM.delivery
    await state.set_state(fsm_state)
    await state.update_data(mcfgnote_source=source)
    await cb.answer()
    try:
        await cb.message.delete()
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    meta = _MCFG_NOTE_META[kind]
    src_label = _MCFG_NOTE_SOURCE_LABELS.get(source, source)
    await cb.message.answer(
        f"✏️ متنِ «{meta['title']} — {src_label}» را بفرست:\n"
        "(می‌توانی چند خط بنویسی. برای انصراف /cancel یا دکمهٔ لغو.)",
        reply_markup=cancel_kb())


async def _mcfg_note_save(msg: Message, bot: Bot, state: FSMContext, kind: str):
    row = await get_bot_row(bot)
    data = await state.get_data()
    source = data.get("mcfgnote_source", "common")
    await state.clear()
    if not row:
        return
    value = (msg.text or "").strip()[:700]
    await _mcfg_note_set(row.id, kind, source, value)
    current = await _mcfg_note_get(row.id, kind, source)
    await msg.answer("✅ ذخیره شد.\n\n" + _mcfg_note_text(kind, source, current), reply_markup=_mcfg_note_kb(kind, source, current))


@tenant_router.message(_ManualCfgNoteFSM.invoice, F.text)
async def mcfg_note_save_invoice(msg: Message, bot: Bot, state: FSMContext):
    await _mcfg_note_save(msg, bot, state, "invoice")


@tenant_router.message(_ManualCfgNoteFSM.delivery, F.text)
async def mcfg_note_save_delivery(msg: Message, bot: Bot, state: FSMContext):
    await _mcfg_note_save(msg, bot, state, "delivery")


# ─────── یادداشتِ اختصاصیِ چند-دسته‌بندی (چک‌باکسی) — PATCH_MCFG_NOTE_CATMAP_V1 ───────
# دقیقاً همان الگویِ «آموزشِ اتصالِ اختصاصی» (_cfgguide_catmap_*)، با کلیدهایِ
# ذخیره‌سازیِ جدا برایِ یادداشت‌ها.

async def _mcfgnote_catlist_content(bot_id: int, kind: str, source: str) -> tuple[str, InlineKeyboardMarkup]:
    entries = await _mcfgnote_catmap_get(bot_id, kind, source)
    rows = []
    for e in entries:
        cats = e["categories"]
        cat_txt = "، ".join(cats) if cats else "(بدون دسته!)"
        mark = "✅" if (e["enabled"] and e["text"].strip()) else "➖"
        label = f"{mark} {cat_txt}"
        if len(label) > 60:
            label = label[:57] + "…"
        rows.append([InlineKeyboardButton(
            text=label, callback_data=f"mcfgnote:catedit:{kind}:{source}:{e['id']}", style=ButtonStyle.PRIMARY)])
    rows.append([InlineKeyboardButton(
        text="➕ افزودن یادداشت جدید برای دسته(ها)",
        callback_data=f"mcfgnote:catnew:{kind}:{source}", style=ButtonStyle.SUCCESS)])
    rows.append([InlineKeyboardButton(text="⬅️ بازگشت", callback_data=f"mcfgnote:{kind}:src:{source}", style=ButtonStyle.DANGER)])
    meta = _MCFG_NOTE_META[kind]
    src_label = _MCFG_NOTE_SOURCE_LABELS.get(source, source)
    body = (
        f"🏷 <b>یادداشت‌های اختصاصیِ دسته‌بندی — {meta['title']} · {src_label}</b>\n\n"
        "می‌تونی چند دسته‌بندی رو با تیک‌زدن به یک یادداشت وصل کنی، و برای دسته‌های "
        "دیگه یادداشتِ جداگانه بسازی.\n\n"
        "برای دسته‌هایی که اینجا پوششش ندادی، یادداشتِ عمومیِ همین بخش (صفحهٔ قبل) "
        "نمایش داده می‌شود.\n\n"
        + ("هنوز هیچ یادداشتِ اختصاصی‌ای نساختی." if not entries else "برای ویرایش/فعال‌وغیرفعال‌کردن/حذف، روی هرکدوم بزن:")
    )
    return body, InlineKeyboardMarkup(inline_keyboard=rows)


async def _mcfgnote_catpick_kb(bot_id: int, kind: str, source: str, selected: list[str]) -> InlineKeyboardMarkup:
    cats = await _cfg_categories_for(bot_id, unlimited=(source == "unlimited"))
    rows = []
    for c in cats:
        mark = "✅" if c in selected else "⬜️"
        rows.append([InlineKeyboardButton(
            text=f"{mark} 🏷 {c}", callback_data=f"mcfgnote:cattoggle:{kind}:{source}:{c}", style=ButtonStyle.PRIMARY)])
    if not cats:
        rows.append([InlineKeyboardButton(text="ℹ️ هنوز کانفیگی دسته‌بندی نشده", callback_data="noop")])
    rows.append([InlineKeyboardButton(
        text=f"✅ ادامه ({len(selected)} دسته انتخاب شد)" if selected else "✅ ادامه",
        callback_data=f"mcfgnote:catdone:{kind}:{source}")])
    rows.append([InlineKeyboardButton(text="⬅️ انصراف", callback_data=f"mcfgnote:catlist:{kind}:{source}", style=ButtonStyle.DANGER)])
    return InlineKeyboardMarkup(inline_keyboard=rows)


@tenant_router.callback_query(F.data.startswith("mcfgnote:catlist:"))
async def mcfgnote_catlist(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    _, _, kind, source = cb.data.split(":", 3)
    body, kb = await _mcfgnote_catlist_content(row.id, kind, source)
    try:
        await cb.message.edit_text(body, reply_markup=kb)
    except Exception:
        await cb.message.answer(body, reply_markup=kb)
    await cb.answer()


@tenant_router.callback_query(F.data.startswith("mcfgnote:catnew:"))
async def mcfgnote_catnew(cb: CallbackQuery, bot: Bot, state: FSMContext):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    _, _, kind, source = cb.data.split(":", 3)
    await state.update_data(mcfgnote_cat_kind=kind, mcfgnote_cat_source=source,
                            mcfgnote_cat_entry_id=None, mcfgnote_cat_selected=[])
    kb = await _mcfgnote_catpick_kb(row.id, kind, source, [])
    text = (
        "🏷 <b>انتخابِ دسته‌بندی‌ها برای این یادداشت</b>\n\n"
        "روی هر دسته که بزنی تیک ✅ می‌خورد؛ می‌تونی چند دسته رو هم‌زمان انتخاب کنی. "
        "بعد از انتخاب، «✅ ادامه» رو بزن تا متنِ یادداشت رو بفرستی."
    )
    try:
        await cb.message.edit_text(text, reply_markup=kb)
    except Exception:
        await cb.message.answer(text, reply_markup=kb)
    await cb.answer()


@tenant_router.callback_query(F.data.startswith("mcfgnote:catedit:"))
async def mcfgnote_catedit(cb: CallbackQuery, bot: Bot, state: FSMContext):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    _, _, kind, source, entry_id = cb.data.split(":", 4)
    entries = await _mcfgnote_catmap_get(row.id, kind, source)
    entry = next((e for e in entries if e["id"] == entry_id), None)
    if not entry:
        await cb.answer("یافت نشد", show_alert=True)
        return
    await state.update_data(mcfgnote_cat_kind=kind, mcfgnote_cat_source=source,
                            mcfgnote_cat_entry_id=entry_id,
                            mcfgnote_cat_selected=list(entry["categories"]))
    cats_txt = "، ".join(entry["categories"]) if entry["categories"] else "—"
    status = "✅ فعال" if entry["enabled"] else "❌ غیرفعال"
    preview = f"\n\n📋 متن فعلی:\n<blockquote>{entry['text']}</blockquote>" if entry["text"].strip() else "\n\n📋 متن فعلی: (تنظیم نشده)"
    body = f"🏷 <b>یادداشتِ اختصاصی</b>\n\nدسته‌ها: {cats_txt}\nوضعیت: {status}{preview}"
    rows = [
        [InlineKeyboardButton(text="🏷 تغییرِ دسته‌ها", callback_data=f"mcfgnote:catpickedit:{kind}:{source}:{entry_id}", style=ButtonStyle.PRIMARY)],
        [InlineKeyboardButton(text=("✏️ ویرایش متن" if entry["text"].strip() else "✏️ تنظیم متن"),
                               callback_data=f"mcfgnote:cattext:{kind}:{source}:{entry_id}")],
    ]
    if entry["text"].strip():
        rows.append([InlineKeyboardButton(
            text=("⛔️ غیرفعال‌سازی" if entry["enabled"] else "✅ فعال‌سازی"),
            callback_data=f"mcfgnote:cattoggleen:{kind}:{source}:{entry_id}", style=ButtonStyle.DANGER)])
    rows.append([InlineKeyboardButton(text="🗑 حذفِ این یادداشت", callback_data=f"mcfgnote:catdel:{kind}:{source}:{entry_id}", style=ButtonStyle.DANGER)])
    rows.append([InlineKeyboardButton(text="⬅️ بازگشت به لیست", callback_data=f"mcfgnote:catlist:{kind}:{source}", style=ButtonStyle.DANGER)])
    kb = InlineKeyboardMarkup(inline_keyboard=rows)
    try:
        await cb.message.edit_text(body, reply_markup=kb)
    except Exception:
        await cb.message.answer(body, reply_markup=kb)
    await cb.answer()


