@tenant_router.callback_query(F.data.startswith("mcfgnote:cattoggle:"))
async def mcfgnote_cattoggle(cb: CallbackQuery, bot: Bot, state: FSMContext):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    _, _, kind, source, cat = cb.data.split(":", 4)
    data = await state.get_data()
    if data.get("mcfgnote_cat_kind") != kind or data.get("mcfgnote_cat_source") != source:
        await cb.answer("این صفحه منقضی شده؛ دوباره شروع کن.", show_alert=True)
        return
    selected: list[str] = list(data.get("mcfgnote_cat_selected") or [])
    if cat in selected:
        selected.remove(cat)
    else:
        selected.append(cat)
    await state.update_data(mcfgnote_cat_selected=selected)
    kb = await _mcfgnote_catpick_kb(row.id, kind, source, selected)
    try:
        await cb.message.edit_reply_markup(reply_markup=kb)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.answer()


@tenant_router.callback_query(F.data.startswith("mcfgnote:catdone:"))
async def mcfgnote_catdone(cb: CallbackQuery, bot: Bot, state: FSMContext):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    _, _, kind, source = cb.data.split(":", 3)
    data = await state.get_data()
