    if not selected:
        await cb.answer("حداقل یک دسته را انتخاب کن.", show_alert=True)
        return
    await state.set_state(AdminFSM.set_mcfg_note_cat)
    await state.update_data(mcfgnote_cat_kind=kind, mcfgnote_cat_source=source, mcfgnote_cat_selected=selected)
    meta = _MCFG_NOTE_META[kind]
    cats_txt = "، ".join(selected)
    try:
        await cb.message.edit_reply_markup(reply_markup=None)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.message.answer(
        f"✏️ <b>متنِ {meta['title']} — دسته‌ها: {cats_txt}</b>\n\n"
        "متنِ یادداشت را بفرست. برای انصراف /cancel یا دکمهٔ لغو.",
        reply_markup=cancel_kb(),
    )
    await cb.answer()


