        [InlineKeyboardButton(text="➕➖ انتخابی (قیمت کلی)", callback_data="cfg:mode:auto", style=ButtonStyle.DANGER)],
        # ── تنظیمات مخصوص حالت ➕➖ انتخابی ──
        [InlineKeyboardButton(text="⚙️ تنظیمات حالت ➕➖ انتخابی ⬇️", callback_data="noop")],
        [InlineKeyboardButton(text="💰 قیمت هر گیگ", callback_data="set:price_gb", style=ButtonStyle.PRIMARY),
         InlineKeyboardButton(text="💵 قیمت هر روز", callback_data="set:price_day", style=ButtonStyle.PRIMARY)],
        [InlineKeyboardButton(text="📏 بازه حجم", callback_data="set:vols", style=ButtonStyle.PRIMARY),
         InlineKeyboardButton(text="📅 بازه روز", callback_data="set:days", style=ButtonStyle.PRIMARY)],
        [InlineKeyboardButton(text="🔢 حداکثر تعداد", callback_data="set:counts", style=ButtonStyle.PRIMARY)],
