@tenant_router.callback_query(AdminFSM.add_cfg_mode, F.data.startswith("cfg:mode:"))
async def admin_cfg_mode_pick(cb: CallbackQuery, state: FSMContext, bot: Bot):
    mode = cb.data.split(":")[2]
    if mode not in ("manual", "auto"):
        mode = "manual"
    # manual → همان فرمِ دکمه‌ایِ کانفیگِ نامحدود (پر کردنِ آزادِ فیلدها) | auto → فرم +/− با قیمت کلی (روند قدیمی)
    await state.update_data(cfg_add_mode=mode,
                            cfg_display=("glass" if mode == "manual" else "form"))
    if mode == "manual":
        await state.update_data(cfg_unlimited=False, cfg_vol=None, cfg_days=None,
                                cfg_users=None, cfg_payload_val=None, cfg_price=None,
                                cfg_form_awaiting=None)
        await state.set_state(AdminFSM.add_cfg_form_wait)
        await _show_cfg_form(cb.message, state, edit=False)
        await cb.answer()
        return
    await state.set_state(AdminFSM.add_cfg_vol)
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="❌ لغو", callback_data="cfg:add:cancel", style=ButtonStyle.DANGER)],
    ])
    await cb.message.answer(
        "➕➖ <b>حالت انتخابی (قیمت کلی)</b>\n\nحجم کانفیگ را به گیگ بفرست:",
        reply_markup=kb)
    await cb.answer()


