# === PATCH_WIREGUARD_CONFIG_V1 ===
# نقطهٔ ورودِ وایرگارد — به‌جای فلوی جداگانه، مستقیم وارد همون فرمِ مشترکِ
# دستی/تکی می‌شه (نه انتخابیِ ➕➖، چون اونجا معنی نداره) با cfg_kind="wireguard"
# تا کاملاً همون تجربه/ظاهرِ کانفیگِ V2Ray/VLESS رو داشته باشه، فقط فیلدِ
# «لینک ساب/سرور» به «فایل(های) وایرگارد» تبدیل می‌شه.

@tenant_router.callback_query(F.data.in_({"tadm:cfg:add_wg", "tadm:cfg:add_wg_unlimited",
                                          "tadm:cfg:add_ovpn", "tadm:cfg:add_ovpn_unlimited"}))
async def tadm_cfg_add_wg_start(cb: CallbackQuery, bot: Bot, state: FSMContext):
    if not await _owner_ok(cb, bot):
        return
    # === PATCH_OPENVPN_CONFIG_V1 ===
    # همان فرمِ وایرگارد؛ فقط kind و برچسب‌ها فرق می‌کند.
    is_unlimited = cb.data.endswith("_unlimited")
    _kind = "openvpn" if "add_ovpn" in cb.data else "wireguard"
    # === PATCH_OPENVPN_PLAN_GATE_V1 ===
    if _kind == "openvpn":
        _row = await get_bot_row(bot)
        if not _row or not has_feature(_row.plan, Feature.OPENVPN_CONFIG):
            await cb.answer(upgrade_hint(Feature.OPENVPN_CONFIG), show_alert=True)
            return
    await state.update_data(
        cfg_kind=_kind, cfg_unlimited=is_unlimited,
        cfg_vol=(0 if is_unlimited else None), cfg_add_mode="manual",
        cfg_display="glass", cfg_days=None, cfg_users=None,
        cfg_payload_val=None, cfg_price=None, cfg_category=None,
        cfg_wg_files=[], cfg_form_awaiting=None,
    )
    await state.set_state(AdminFSM.add_cfg_form_wait)
    await _show_cfg_form(cb.message, state, edit=False)
    await cb.answer()


_WG_LINKS_PROMPT = ("🔗 لینک‌هایِ سابِ وایرگارد را بفرست — هر خط (یا هر فاصله) یعنی یک کانفیگِ جدا. "
                   "می‌توانی چند پیام پشتِ‌سرِهم بفرستی؛ بعد «⬅️ بازگشت» را بزن.")


# === PATCH_WG_BULK_SUBLINKS_V1 ===
def _wg_link_bulk_on(data: dict) -> bool:
    """وایرگارد/اوپن‌وی‌پی‌ان در حالتِ «لینکِ ساب»: چند لینک در یک‌بار (هر لینک = یک کانفیگِ جدا)."""
    return data.get("cfg_kind") in FILE_KINDS and data.get("cfg_wg_mode") == "link"


def _split_sub_links(text: str) -> tuple[list[str], list[str]]:
    """(لینک‌هایِ معتبرِ http/https، موردهایِ نامعتبر) از یک متنِ چندخطی/فاصله‌جدا."""
    good, bad = [], []
    for tok in (text or "").split():
        tok = tok.strip().strip(",;،؛")
        if not tok:
            continue
        (good if _wg_payload_is_link(tok) else bad).append(tok)
    return good, bad


# ─────────────── فرم دکمه‌ایِ افزودنِ کانفیگِ دستی/تکی (آماده یا نامحدود) ───────────────

_CFG_FORM_FIELDS = {
    "vol":      ("📦 حجم (گیگ)", "cfg_vol"),
    "days":     ("📅 روز", "cfg_days"),
    "users":    ("👥 تعداد کاربر", "cfg_users"),
    "payload":  ("🔗 لینک ساب/سرور", "cfg_payload_val"),
    "price":    ("💰 قیمت", "cfg_price"),
    "category": ("🏷 دسته‌بندی", "cfg_category"),
}
_CFG_CATEGORY_MAXLEN = 12


def _sanitize_category(raw: str) -> str | None:
    """نام دسته‌بندی را پاک‌سازی می‌کند: حذف ':' (برای امنِ‌بودن در callback_data)،
    کوتاه‌کردن به حداکثر طول مجاز. اگر ادمین متنی مثل «-» یا «حذف» بفرستد،
    یعنی می‌خواهد دسته را پاک کند و None برمی‌گردد."""
    val = (raw or "").strip()
    if val in ("-", "حذف", "بدون دسته", "پاک کن"):
        return None
    val = val.replace(":", "").strip()
    if not val:
        return None
    return val[:_CFG_CATEGORY_MAXLEN]


def _cfg_form_text(data: dict) -> str:
    mode = data.get("cfg_add_mode", "manual")
    mode_lbl = "✍️ دستی/تکی" if mode == "manual" else "➕➖ انتخابی (قیمت کلی)"
    is_wg = data.get("cfg_kind") in FILE_KINDS  # === PATCH_OPENVPN_CONFIG_V1 ===
    if is_wg:
        # === PATCH_OPENVPN_CONFIG_V1 ===
        _m = _kind_meta(data.get("cfg_kind"))
        title = (f"{_m['icon']} افزودن {_m['label']} نامحدود" if data.get("cfg_unlimited")
                 else f"{_m['icon']} افزودن {_m['label']} آماده")
        hint = ("روی هر دکمه بزن و مقدارش را بفرست؛ برای فیلدِ «فایل‌ها» می‌تونی چند فایلِ "
                f"{_m['ext']} پشتِ‌سرِهم بفرستی (هرکدوم یه کانفیگِ جدا می‌شه). وقتی همه پر شد "
                "«✅ ثبت کانفیگ» را بزن.")
        return f"{title}\n\n{hint}"
    title = "♾️ افزودن کانفیگ نامحدود" if data.get("cfg_unlimited") else "🛒 افزودن کانفیگ آماده"
    if data.get("cfg_bulk"):  # === PATCH_CFG_BULK_SUBLINKS_V1 ===
        n = len(data.get("cfg_bulk_links") or [])
        title = ("📚♾️ ثبت دسته‌جمعی کانفیگ نامحدود" if data.get("cfg_unlimited")
                 else "📚 ثبت دسته‌جمعی کانفیگ آماده")
        return (f"{title} — {mode_lbl}\n\n"
                "حجم/روز/کاربر/قیمت/دسته را یک‌بار پر کن — برای <b>همهٔ</b> "
                "لینک‌ها یکسان اعمال می‌شود.\n"
                "بعد روی «🔗 لینک‌های ساب» بزن و همهٔ ساب‌ها را بفرست.\n\n"
                + (f"✅ الان <b>{n}</b> لینک ثبت شده — با «✅ ثبت کانفیگ» "
                   f"<b>{n}</b> کانفیگ وارد انبار می‌شود."
                   if n else "هنوز هیچ لینکی نفرستاده‌ای."))
    return (f"{title} — {mode_lbl}\n\n"
            "روی هر دکمه بزن و مقدارش را بفرست؛ وقتی همه پر شد «✅ ثبت کانفیگ» را بزن.")


def _vol_with_mb(val) -> str:
    """اگر حجم کمتر از ۱ گیگ باشد، معادلِ مگابایتی را هم کنارش نشان می‌دهد.
    مثلاً 0.100 گیگ → «0.1 گیگ (100 مگابایت)»."""
    try:
        v = float(val)
    except (TypeError, ValueError):
        return str(val)
    if 0 < v < 1:
        mb = round(v * 1000)
        return f"{val} گیگ ({mb} مگابایت)"
    return str(val)


def _cfg_form_kb(data: dict) -> InlineKeyboardMarkup:
    def fmt(field: str) -> str:
        label, key = _CFG_FORM_FIELDS[field]
        val = data.get(key)
        shown = val if val not in (None, "") else "—"
        # === PATCH_CFG_FORM_ZERO_DAYS_V1 ===
        # «روز: 0» به‌نظر «پر نشده» می‌آید؛ صریح بنویس چه معنایی دارد.
        if field == "days" and val == 0:
            shown = "♾️ بی‌انقضا"
        elif field == "users" and val == 0:
            shown = "♾️ نامحدود"
        elif field == "vol" and shown != "—":
            shown = _vol_with_mb(shown)
        return f"{label}: {shown}"

    is_unlimited = bool(data.get("cfg_unlimited"))
    is_wg = data.get("cfg_kind") in FILE_KINDS  # === PATCH_OPENVPN_CONFIG_V1 ===
    rows = []
    if is_unlimited:
        rows.append([InlineKeyboardButton(text="📦 حجم: ♾️ نامحدود", callback_data="noop")])
    else:
        rows.append([InlineKeyboardButton(text=fmt("vol"), callback_data="cfgf:field:vol", style=ButtonStyle.PRIMARY)])
    rows.append([InlineKeyboardButton(text=fmt("days"), callback_data="cfgf:field:days", style=ButtonStyle.PRIMARY)])
    rows.append([InlineKeyboardButton(text=fmt("users"), callback_data="cfgf:field:users", style=ButtonStyle.PRIMARY)])
    if is_wg:
        # === PATCH_WIREGUARD_SUBLINK_V1 ===
        wg_mode = data.get("cfg_wg_mode")
        if wg_mode == "link":
            _nl = len(data.get("cfg_bulk_links") or [])
            wg_label = f"🔗 لینک‌هایِ ساب: {_nl} عدد" if _nl else "🔗 لینک‌هایِ ساب: —"   # PATCH_WG_BULK_SUBLINKS_V1
        else:
            n = len(data.get("cfg_wg_files") or [])
            wg_label = f"📎 فایل‌ها: {n} فایل" if n else "📎 فایل/لینک: —"
        rows.append([InlineKeyboardButton(text=wg_label, callback_data="cfgf:field:payload", style=ButtonStyle.PRIMARY)])
    elif data.get("cfg_bulk"):
        # === PATCH_CFG_BULK_SUBLINKS_V1 ===
        n = len(data.get("cfg_bulk_links") or [])
        lbl = f"🔗 لینک‌های ساب: {n} عدد" if n else "🔗 لینک‌های ساب: —"
        rows.append([InlineKeyboardButton(text=lbl, callback_data="cfgf:field:payload",
                                          style=ButtonStyle.PRIMARY)])
    else:
        rows.append([InlineKeyboardButton(text=fmt("payload"), callback_data="cfgf:field:payload", style=ButtonStyle.PRIMARY)])
    rows.append([InlineKeyboardButton(text=fmt("price"), callback_data="cfgf:field:price", style=ButtonStyle.PRIMARY)])
    rows.append([InlineKeyboardButton(text=fmt("category"), callback_data="cfgf:field:category", style=ButtonStyle.PRIMARY)])
    rows.append([InlineKeyboardButton(text="✅ ثبت کانفیگ", callback_data="cfgf:submit", style=ButtonStyle.SUCCESS)])
    rows.append([InlineKeyboardButton(text="⬅️ بازگشت", callback_data="cfg:add:cancel", style=ButtonStyle.DANGER)])
    return InlineKeyboardMarkup(inline_keyboard=rows)


async def _show_cfg_form(target_msg: Message, state: FSMContext, edit: bool):
    """نمایش/به‌روزرسانیِ پیامِ فرمِ افزودن کانفیگ (edit=True یعنی همان پیام ویرایش شود)."""
    data = await state.get_data()
    text, kb = _cfg_form_text(data), _cfg_form_kb(data)
    if edit:
        try:
            await target_msg.edit_text(text, reply_markup=kb)
            return
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    msg = await target_msg.answer(text, reply_markup=kb)
    await state.update_data(cfg_form_chat_id=msg.chat.id, cfg_form_msg_id=msg.message_id)


@tenant_router.callback_query(AdminFSM.add_cfg_form_wait, F.data.startswith("cfgf:field:"))
async def cfg_form_field_pick(cb: CallbackQuery, state: FSMContext, bot: Bot):
    field = cb.data.split(":")[2]
    if field not in _CFG_FORM_FIELDS:
        await cb.answer()
        return
    data = await state.get_data()
    is_wg = data.get("cfg_kind") in FILE_KINDS  # === PATCH_OPENVPN_CONFIG_V1 ===
    label, _ = _CFG_FORM_FIELDS[field]
    extra_rows = []
    if field == "category":
        # === PATCH_CFG_CATEGORY_REUSE_V1 ===
        # باگ: قبلاً این مرحله فقط یه پرامپتِ متنی بود — یعنی برایِ استفاده
        # از یه دسته‌بندیِ از قبل ساخته‌شده، باید اسمش رو کاراکتر‌به‌کاراکتر
        # درست دوباره تایپ می‌کردی (کوچیک‌ترین اختلاف = یه دستهٔ جدیدِ جدا).
        # حالا دسته‌بندی‌هایِ موجودِ همین ربات رو هم به‌صورتِ دکمه نشون
        # می‌دیم تا با یه تپ انتخاب بشه، بدونِ نیاز به تایپِ دستی.
        row = await get_bot_row(bot)
        if row:
            async with Session() as s:
                existing = (await s.scalars(
                    select(Config.category).where(
                        Config.bot_id == row.id, Config.category.is_not(None))
                    .distinct().order_by(Config.category)
                )).all()
            for cat in existing:
                if cat:
                    extra_rows.append([InlineKeyboardButton(
                        text=f"🏷 {cat}", callback_data=f"cfgf:catpick:{cat}", style=ButtonStyle.PRIMARY)])
        prompt = (f"🏷 یکی از دسته‌بندی‌هایِ موجود رو انتخاب کن، یا نامِ دستهٔ "
                  f"جدید رو بفرست (حداکثر {_CFG_CATEGORY_MAXLEN} کاراکتر، مثلاً «دسته ۱»)؛ "
                  "برای بدون‌دسته «-» بفرست:")
    elif field == "payload" and is_wg:
        # === PATCH_WIREGUARD_SUBLINK_V1 ===
        # قبلاً این فیلد همیشه فایل می‌خواست؛ حالا اول می‌پرسیم ادمین
        # می‌خواد فایل بفرسته یا لینکِ ساب — هرکدوم که خودش می‌خواد.
        wg_mode = data.get("cfg_wg_mode")
        if wg_mode not in ("file", "link"):
            await state.update_data(cfg_form_awaiting=field)
            prompt_msg = await cb.message.answer(
                # === PATCH_OPENVPN_CONFIG_V1 ===
                f"📎 برایِ این کانفیگِ {_kind_meta(data.get('cfg_kind'))['label']} "
                "چی می‌خوای ثبت کنی؟",
                reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                    [InlineKeyboardButton(text=f"📎 ارسالِ فایل ({_kind_meta(data.get('cfg_kind'))['ext']})", callback_data="cfgf:wgmode:file", style=ButtonStyle.PRIMARY)],
                    [InlineKeyboardButton(text="🔗 ارسالِ لینکِ ساب", callback_data="cfgf:wgmode:link", style=ButtonStyle.PRIMARY)],
                    [InlineKeyboardButton(text="⬅️ بازگشت", callback_data="cfgf:backform", style=ButtonStyle.DANGER)],
                    [InlineKeyboardButton(text="❌ لغو", callback_data="cfg:add:cancel", style=ButtonStyle.DANGER)]]))
            await state.update_data(cfg_form_prompt_chat_id=prompt_msg.chat.id,
                                    cfg_form_prompt_msg_id=prompt_msg.message_id)
            await cb.answer()
            return
        if wg_mode == "link":
            _nl = len(data.get("cfg_bulk_links") or [])
            prompt = _WG_LINKS_PROMPT + (f"\n\n(الان {_nl} لینک ثبت شده.)" if _nl else "")
        else:
            n = len(data.get("cfg_wg_files") or [])
            already = f"\n\n(الان {n} فایل انتخاب شده.)" if n else ""
            prompt = ("📎 فایل(های) <code>.conf</code> وایرگارد را یکی‌یکی بفرست — هر فایل یعنی یک "
                      f"کانفیگِ جدا در انبار. هرچند فایل که خواستی بفرست، بعد «⬅️ بازگشت» را بزن.{already}")
    elif field == "payload":
        prompt = "🔗 لینک ساب یا سرور را بفرست:"
    else:
        prompt = f"{label} را بفرست (فقط عدد؛ ۰ یعنی نامحدود/بدون محدودیت):"
    prompt_msg = await cb.message.answer(prompt, reply_markup=InlineKeyboardMarkup(inline_keyboard=[
        *extra_rows,
        [InlineKeyboardButton(text="⬅️ بازگشت", callback_data="cfgf:backform", style=ButtonStyle.DANGER)],
        [InlineKeyboardButton(text="❌ لغو", callback_data="cfg:add:cancel", style=ButtonStyle.DANGER)]]))
    await state.update_data(cfg_form_awaiting=field,
                            cfg_form_prompt_chat_id=prompt_msg.chat.id,
                            cfg_form_prompt_msg_id=prompt_msg.message_id)
    await cb.answer()


async def _cfg_form_set_field_and_redisplay(target, state: FSMContext, bot: Bot, key: str, val) -> None:
    """PATCH_CFG_CATEGORY_REUSE_V1 — منطقِ مشترکِ «مقداردهیِ یک فیلدِ فرم و
    بازگشت به فرم»، هم از مسیرِ تایپِ متن (cfg_form_field_value) هم از
    مسیرِ تپ‌کردنِ دستهٔ موجود (cfgf:catpick) صدا زده می‌شه."""
    extra = {}
    if key == "cfg_vol":
        extra["cfg_unlimited"] = (val == 0)
    await state.update_data(**{key: val, "cfg_form_awaiting": None}, **extra)
    data = await state.get_data()
    prompt_chat_id = data.get("cfg_form_prompt_chat_id")
    prompt_msg_id = data.get("cfg_form_prompt_msg_id")
    if prompt_chat_id and prompt_msg_id:
        try:
            await bot.delete_message(chat_id=prompt_chat_id, message_id=prompt_msg_id)
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    chat_id, form_msg_id = data.get("cfg_form_chat_id"), data.get("cfg_form_msg_id")
    text, kb = _cfg_form_text(data), _cfg_form_kb(data)
    try:
        await bot.edit_message_text(text, chat_id=chat_id, message_id=form_msg_id, reply_markup=kb)
    except Exception:
        target_chat = target.message.chat.id if isinstance(target, CallbackQuery) else target.chat.id
        m2 = await bot.send_message(target_chat, text, reply_markup=kb)
        await state.update_data(cfg_form_chat_id=m2.chat.id, cfg_form_msg_id=m2.message_id)


@tenant_router.callback_query(AdminFSM.add_cfg_form_wait, F.data.startswith("cfgf:catpick:"))
async def cfg_form_category_pick(cb: CallbackQuery, state: FSMContext, bot: Bot):
    cat = cb.data.split(":", 2)[2]
    await _cfg_form_set_field_and_redisplay(cb, state, bot, "cfg_category", cat)
    await cb.answer(f"✅ دستهٔ «{cat}» انتخاب شد.")


@tenant_router.message(AdminFSM.add_cfg_form_wait, F.text)
async def cfg_form_field_value(msg: Message, state: FSMContext):
    data = await state.get_data()
    field = data.get("cfg_form_awaiting")
    if not field or field not in _CFG_FORM_FIELDS:
        # کاربر بدون اینکه روی یکی از دکمه‌های فرم (روز/کاربر/لینک/قیمت) بزند
        # مستقیم متن فرستاده؛ قبلاً اینجا کاملاً بی‌صدا نادیده گرفته می‌شد که
        # باعث می‌شد کاربر فکر کند ربات هنگ کرده. حالا راهنمایی می‌کنیم.
        await msg.answer(
            "❗️ اول باید روی یکی از دکمه‌های فرم (مثلاً «🔗 لینک ساب/سرور») بزنی، "
            "بعد مقدارش را بفرستی.\n\n👇 فرم را از پایین ببین و روی فیلد موردنظر بزن:",
            reply_markup=_cfg_form_kb(data))
        return
    _, key = _CFG_FORM_FIELDS[field]
    # === PATCH_CFG_BULK_SUBLINKS_V1 ===
    # حالتِ دسته‌جمعی: هر پیام می‌تواند چندین لینک داشته باشد (هر خط یا با
    # فاصله جدا شده). لینک‌ها هیچ فاصله/خطِ جدیدی داخلِ خودشان ندارند، پس
    # جداکردن با whitespace امن است. مثلِ فایل‌هایِ وایرگارد، بعد از هر
    # پیام در همین فیلد می‌مانیم تا ادمین بتواند چند پیام پشتِ‌سرِهم بفرستد.
    if field == "payload" and (data.get("cfg_bulk") or _wg_link_bulk_on(data)):
        links = list(data.get("cfg_bulk_links") or [])
        _wg_bulk = _wg_link_bulk_on(data)       # === PATCH_WG_BULK_SUBLINKS_V1 ===
        if _wg_bulk:
            new, _bad = _split_sub_links(msg.text or "")
            if _bad and not new:
                await msg.answer("❗️ لینکِ معتبر پیدا نشد. هر لینک باید با <code>http://</code> یا "
                                 "<code>https://</code> شروع شود (هر خط یک لینک).")
                return
        else:
            new = [x.strip() for x in (msg.text or "").split() if x.strip()]
            _bad = []
        if not new:
            await msg.answer("❗️ هیچ لینکی پیدا نشد. لینک‌ها را با خطِ جدید یا فاصله جدا کن.")
            return
        dup = 0
        for lk in new:
            if lk in links:
                dup += 1
            else:
                links.append(lk)
        await state.update_data(cfg_bulk_links=links)
        try:
            await msg.delete()
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        dup_line = f"\n⚠️ {dup} لینکِ تکراری نادیده گرفته شد." if dup else ""
        if _bad:
            dup_line += f"\n⚠️ {len(_bad)} موردِ نامعتبر (بدونِ http/https) نادیده گرفته شد."
        new_text = (f"🔗 لینک‌های ساب را بفرست — هر خط (یا هر فاصله) یعنی یک کانفیگِ جدا.\n\n"
                    f"✅ الان <b>{len(links)}</b> لینک ثبت شده.{dup_line}\n\n"
                    "می‌تونی باز هم بفرستی، یا «⬅️ بازگشت» را بزن.")
        kb_back = InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text="🗑 پاک‌کردن همه", callback_data="cfgf:bulkclear", style=ButtonStyle.DANGER)],
            [InlineKeyboardButton(text="⬅️ بازگشت", callback_data="cfgf:backform", style=ButtonStyle.DANGER)]])
        pc, pm = data.get("cfg_form_prompt_chat_id"), data.get("cfg_form_prompt_msg_id")
        if pc and pm:
            try:
                await msg.bot.edit_message_text(new_text, chat_id=pc, message_id=pm, reply_markup=kb_back)
                return
            except Exception:
                logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        m2 = await msg.answer(new_text, reply_markup=kb_back)
        await state.update_data(cfg_form_prompt_chat_id=m2.chat.id, cfg_form_prompt_msg_id=m2.message_id)
        return
    if field == "payload" and data.get("cfg_kind") in FILE_KINDS:  # === PATCH_OPENVPN_CONFIG_V1 ===
        # === PATCH_WIREGUARD_SUBLINK_V1 ===
        # اگه ادمین صریحاً «🔗 ارسالِ لینکِ ساب» رو انتخاب کرده، متن مجازه؛
        # وگرنه (حالتِ فایل، یا هنوز چیزی انتخاب نکرده) طبقِ قبل رد می‌شه.
        if data.get("cfg_wg_mode") != "link":
            await msg.answer(
                f"❗️ این فیلد برای {_kind_meta(data.get('cfg_kind'))['label']} باید "
                f"<b>فایل</b> باشه (نه متن). فایلِ <code>{_kind_meta(data.get('cfg_kind'))['ext']}</code> "
                "رو به‌صورتِ سند (Document) بفرست؛ یا از فرم، «🔗 ارسالِ لینکِ ساب» رو انتخاب کن.")
            return
        val = msg.text.strip()
        if not val:
            await msg.answer("❗️ مقدار نامعتبر. دوباره بفرست.")
            return
    elif field == "payload":
        val = msg.text.strip()
        if not val:
            await msg.answer("❗️ مقدار نامعتبر. دوباره بفرست.")
            return
    elif field == "category":
        val = _sanitize_category(msg.text)
    else:
        val = fa_to_int(msg.text)
        if val is None or val < 0:
            await msg.answer("❗️ عدد نامعتبر. دوباره بفرست.")
            return
    extra = {}
    if field == "vol":
        # ۰ یعنی نامحدود؛ دکمهٔ «حجم» باید به «♾️ نامحدود» تبدیل شود و دیگر قابل‌کلیک نباشد.
        # اگر قبلاً نامحدود بود و الان عدد غیرصفر فرستاد، از حالت نامحدود خارج شود.
        extra["cfg_unlimited"] = (val == 0)
    await state.update_data(**{key: val, "cfg_form_awaiting": None}, **extra)
    data = await state.get_data()
    # پیامِ سؤال (پرامپت) و پیامِ خودِ ادمین را پاک کن تا فقط فرم با مقدارِ به‌روزشده بماند
    prompt_chat_id = data.get("cfg_form_prompt_chat_id")
    prompt_msg_id = data.get("cfg_form_prompt_msg_id")
    if prompt_chat_id and prompt_msg_id:
        try:
            await msg.bot.delete_message(chat_id=prompt_chat_id, message_id=prompt_msg_id)
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    try:
        await msg.delete()
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    chat_id, form_msg_id = data.get("cfg_form_chat_id"), data.get("cfg_form_msg_id")
    text, kb = _cfg_form_text(data), _cfg_form_kb(data)
    try:
        await msg.bot.edit_message_text(text, chat_id=chat_id, message_id=form_msg_id, reply_markup=kb)
    except Exception:
        m2 = await msg.answer(text, reply_markup=kb)
        await state.update_data(cfg_form_chat_id=m2.chat.id, cfg_form_msg_id=m2.message_id)


# === PATCH_WIREGUARD_SUBLINK_V1 ===
@tenant_router.callback_query(AdminFSM.add_cfg_form_wait, F.data.startswith("cfgf:wgmode:"))
async def cfg_form_wg_mode_pick(cb: CallbackQuery, state: FSMContext):
    """بعدِ انتخابِ فایل/لینک، مستقیم پرامپتِ مناسب رو نشون می‌ده."""
    mode = cb.data.split(":")[2]
    if mode not in ("file", "link"):
        await cb.answer()
        return
    await state.update_data(cfg_wg_mode=mode, cfg_form_awaiting="payload")
    _link_rows = []
    if mode == "link":
        prompt = _WG_LINKS_PROMPT
        _link_rows = [[InlineKeyboardButton(text="🗑 پاک‌کردن همه", callback_data="cfgf:bulkclear", style=ButtonStyle.DANGER)]]
    else:
        prompt = ("📎 فایل(های) <code>.conf</code> وایرگارد را یکی‌یکی بفرست — هر فایل یعنی یک "
                  "کانفیگِ جدا در انبار. هرچند فایل که خواستی بفرست، بعد «⬅️ بازگشت» را بزن.")
    try:
        await cb.message.edit_text(prompt, reply_markup=InlineKeyboardMarkup(inline_keyboard=[
            *_link_rows,
            [InlineKeyboardButton(text="⬅️ بازگشت", callback_data="cfgf:backform", style=ButtonStyle.DANGER)],
            [InlineKeyboardButton(text="❌ لغو", callback_data="cfg:add:cancel", style=ButtonStyle.DANGER)]]))
        await state.update_data(cfg_form_prompt_chat_id=cb.message.chat.id,
                                cfg_form_prompt_msg_id=cb.message.message_id)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.answer()


# === PATCH_WIREGUARD_CONFIG_V1 ===
@tenant_router.message(AdminFSM.add_cfg_form_wait, F.document)
async def cfg_form_field_wg_file(msg: Message, state: FSMContext):
    """آپلودِ فایلِ .conf وایرگارد وقتی فیلدِ «فایل‌ها» فعاله. برخلافِ بقیهٔ
    فیلدها که با یه مقدار برمی‌گردن به فرم، اینجا عمداً برنمی‌گردیم — چون
    ادمین معمولاً چندتا فایل پشتِ‌سرِهم می‌فرسته؛ با «⬅️ بازگشت» خودش
    برمی‌گرده به فرم وقتی تموم شد."""
    data = await state.get_data()
    field = data.get("cfg_form_awaiting")
    # === PATCH_OPENVPN_CONFIG_V1 ===
    if field != "payload" or data.get("cfg_kind") not in FILE_KINDS or data.get("cfg_wg_mode") != "file":
        await msg.answer("❗️ اول از فرم روی «📎 فایل‌ها» بزن و «📎 ارسالِ فایل» رو انتخاب کن، بعد فایل بفرست.")
        return
    files = list(data.get("cfg_wg_files") or [])
    files.append(msg.document.file_id)
    await state.update_data(cfg_wg_files=files)
    try:
        await msg.delete()
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    prompt_chat_id = data.get("cfg_form_prompt_chat_id")
    prompt_msg_id = data.get("cfg_form_prompt_msg_id")
    new_text = (
        f"📎 فایل‌های <code>{_kind_meta(data.get('cfg_kind'))['ext']}</code> "
        f"{_kind_meta(data.get('cfg_kind'))['label']} را یکی‌یکی بفرست — هر فایل یعنی یک "
        f"کانفیگِ جدا در انبار.\n\n✅ الان <b>{len(files)}</b> فایل انتخاب شده. فایلِ بعدی "
        "رو بفرست یا «⬅️ بازگشت» را بزن."
    )
    if prompt_chat_id and prompt_msg_id:
        try:
            await msg.bot.edit_message_text(new_text, chat_id=prompt_chat_id, message_id=prompt_msg_id,
                                             reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                                                 [InlineKeyboardButton(text="⬅️ بازگشت", callback_data="cfgf:backform", style=ButtonStyle.DANGER)],
                                                 [InlineKeyboardButton(text="❌ لغو", callback_data="cfg:add:cancel", style=ButtonStyle.DANGER)]]))
            return
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    m2 = await msg.answer(new_text, reply_markup=InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="⬅️ بازگشت", callback_data="cfgf:backform", style=ButtonStyle.DANGER)],
        [InlineKeyboardButton(text="❌ لغو", callback_data="cfg:add:cancel", style=ButtonStyle.DANGER)]]))
    await state.update_data(cfg_form_prompt_chat_id=m2.chat.id, cfg_form_prompt_msg_id=m2.message_id)


