@tenant_router.callback_query(F.data.startswith("tadm:cfg:linkmode:"))
async def tadm_cfg_linkmode(cb: CallbackQuery, bot: Bot):
    """قدم اول: نوع نمایش انتخاب شد → حالا درخت دکمه‌ها."""
    row = await _owner_ok(cb, bot)
    if not row:
        return
    parts = cb.data.split(":")  # tadm:cfg:linkmode:{action_type}:{mode}
    action_type, mode = parts[3], parts[4]
