@tenant_router.message(AdminFSM.add_cfg_days, F.text)
async def admin_cfg_days(msg: Message, state: FSMContext):
    v = fa_to_int(msg.text)
    if not v:
        await msg.answer("عدد نامعتبر.")
        return
    await state.update_data(cfg_days=v)
    data = await state.get_data()
    mode = data.get("cfg_add_mode", "auto")
    if mode == "manual":
        # حالت دستی: تعداد کاربر و قیمت اختصاصی را هم بپرس
        await _ask_cfg_users(msg, state)
    else:
        # حالت انتخابی (قیمت کلی): مستقیم سراغ خود کانفیگ — قیمت از تنظیمات کلی می‌آید
        await state.update_data(cfg_users=0, cfg_price=0)
        await state.set_state(AdminFSM.add_cfg_payload)
        await msg.answer(await _bulk_payload_prompt(state),
                         reply_markup=InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text="❌ لغو", callback_data="cfg:add:cancel", style=ButtonStyle.DANGER)]]))


@tenant_router.callback_query(AdminFSM.add_cfg_users, F.data == "cfg:users:skip")
async def admin_cfg_users_skip(cb: CallbackQuery, state: FSMContext):
    await state.update_data(cfg_users=0)
    await _ask_cfg_price(cb.message, state)
    await cb.answer()


@tenant_router.message(AdminFSM.add_cfg_users, F.text)
async def admin_cfg_users(msg: Message, state: FSMContext):
    v = fa_to_int(msg.text)
    if v is None or v < 0:
        await msg.answer("عدد نامعتبر.")
        return
    await state.update_data(cfg_users=v)
    await _ask_cfg_price(msg, state)


async def _ask_cfg_price(target_msg, state: FSMContext):
    """سوال قیمت ثابتِ این کانفیگ (مرحلهٔ مشترک حالت دستی)."""
    await state.set_state(AdminFSM.add_cfg_price)
    data = await state.get_data()
    d = data.get("cfg_days", 0)
    u = data.get("cfg_users", 0)
    pd = data.get("cfg_price_day", 0)
    vol = data.get("cfg_vol", 0)
    vol_lbl = "♾️ نامحدود" if (vol == 0 or data.get("cfg_unlimited")) else f"{vol} گیگ"
    summary = f"{vol_lbl} · {fmt_days(d)} · {u if u else '—'} کاربر"
    if pd:
        summary += f" · قیمت هر روز {pd:,}"
    skip_kb = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="⏭ بدون قیمت ثابت (محاسبه از قیمت روز)",
                              callback_data="cfg:price:skip", style=ButtonStyle.PRIMARY)],
        [InlineKeyboardButton(text="❌ لغو", callback_data="cfg:add:cancel", style=ButtonStyle.DANGER)],
    ])
    await target_msg.answer(
        f"{summary}\n\n💰 <b>قیمت این کانفیگ</b> را به تومان بفرست:\n"
        "(یا اگر می‌خواهی قیمت از «قیمت هر روز × روز» محاسبه شود، رد کن)",
        reply_markup=skip_kb)


@tenant_router.callback_query(AdminFSM.add_cfg_price, F.data == "cfg:price:skip")
async def admin_cfg_price_skip(cb: CallbackQuery, state: FSMContext):
    data = await state.get_data()
    # اگر قیمت روز داده شده، قیمت = روز × قیمت‌روز؛ وگرنه ۰ (قیمت سطح‌رباتی)
    pd = data.get("cfg_price_day", 0)
    d = data.get("cfg_days", 0)
    await state.update_data(cfg_price=(pd * d if pd else 0))
    await _finish_cfg_to_payload(cb.message, state)
    await cb.answer()


@tenant_router.message(AdminFSM.add_cfg_price, F.text)
async def admin_cfg_price(msg: Message, state: FSMContext):
    v = fa_to_int(msg.text)
    if v is None or v < 0:
        await msg.answer("عدد نامعتبر.")
        return
    await state.update_data(cfg_price=v)
    await _finish_cfg_to_payload(msg, state)


async def _bulk_payload_prompt(state: FSMContext) -> str:
    """=== PATCH_CFG_BULK_BOTH_MODES_V1 ===
    در حالتِ دسته‌جمعی، همین مرحله چند لینک می‌گیرد (هر خط یا با فاصله)."""
    data = await state.get_data()
    if data.get("cfg_bulk"):
        return ("حالا همهٔ لینک‌های ساب را بفرست — هر خط (یا جداشده با فاصله) "
                "یک کانفیگِ جدا در انبار می‌شود:")
    return "حالا خود کانفیگ یا لینک ساب را بفرست:"


async def _finish_cfg_to_payload(target_msg, state: FSMContext):
    """حالت نمایش قبلاً بر اساس حالتِ افزودن (دستی=شیشه‌ای / انتخابی=فرم) تعیین
    شده؛ مستقیم خود کانفیگ را می‌پرسیم."""
    await state.set_state(AdminFSM.add_cfg_payload)
    await target_msg.answer(await _bulk_payload_prompt(state),
                            reply_markup=InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text="❌ لغو", callback_data="cfg:add:cancel", style=ButtonStyle.DANGER)]]))


async def _ask_cfg_display(target_msg, state: FSMContext):
    """(منسوخ) سوال حالت نمایش — اکنون حالت از روی نوع افزودن تعیین می‌شود."""
    await _finish_cfg_to_payload(target_msg, state)


@tenant_router.callback_query(AdminFSM.add_cfg_display, F.data.startswith("cfg:disp:"))
async def admin_cfg_display_pick(cb: CallbackQuery, state: FSMContext):
    mode = cb.data.split(":")[2]
    if mode not in ("glass", "form"):
        mode = "glass"
    await state.update_data(cfg_display=mode)
    await state.set_state(AdminFSM.add_cfg_payload)
    await cb.message.answer("✅ حالت نمایش ثبت شد.\n\nحالا خود کانفیگ یا لینک ساب را بفرست:",
                            reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                                [InlineKeyboardButton(text="❌ لغو", callback_data="cfg:add:cancel", style=ButtonStyle.DANGER)]]))
    await cb.answer()


@tenant_router.message(AdminFSM.add_cfg_payload, F.text)
async def admin_cfg_payload(msg: Message, bot: Bot, state: FSMContext):
    row = await get_bot_row(bot)
    if not row:
        await state.clear()
        return
    data = await state.get_data()
    vol, days = data["cfg_vol"], data["cfg_days"]
    users = data.get("cfg_users", 0)
    price = data.get("cfg_price", 0)
    price_day = data.get("cfg_price_day", 0)
    display = data.get("cfg_display", "glass")
    # === PATCH_CFG_BULK_BOTH_MODES_V1 ===
    # حالتِ «➕➖ انتخابی» تا امروز فقط یک کانفیگ ثبت می‌کرد؛ حالا اگر از
    # مسیرِ «ثبت دسته‌جمعی» آمده باشیم، هر لینک یک ردیفِ جدا با کدِ خودش
    # می‌شود — دقیقاً مثلِ مسیرِ فرمِ دستی.
    is_bulk = bool(data.get("cfg_bulk"))
    payloads = ([x.strip() for x in (msg.text or "").split() if x.strip()]
                if is_bulk else [(msg.text or "").strip()])
    if not payloads:
        await msg.answer("❗️ هیچ لینکی پیدا نشد. لینک‌ها را با خطِ جدید یا فاصله جدا کن.")
        return
    codes: list[int] = []
    async with Session() as s:
        mx = await s.scalar(select(func.max(Config.code)).where(Config.bot_id == row.id))
        code = (mx + 1) if mx else CONFIG_CODE_START
        next_code = code
        for _payload in payloads:
            s.add(Config(bot_id=row.id, code=next_code, volume_gb=vol,
                         days=days, payload=_payload, status="in_stock",
                         price=price, price_per_day=price_day,
                         user_count=users, display_mode=display))
            codes.append(next_code)
            next_code += 1
        await s.commit()
        # کاربرانی که این بسته را در لیست انتظار داشتند
        reqs = (await s.scalars(select(StockRequest).where(
            StockRequest.bot_id == row.id, StockRequest.volume_gb == vol,
            StockRequest.days == days, StockRequest.fulfilled == False))).all()
        waiting_ids = list({r.user_telegram_id for r in reqs})
        for r in reqs:
            r.fulfilled = True
        if reqs:
            await s.commit()
    await state.clear()
    note = ""
    if waiting_ids:
        note = f"\n\n🔔 {len(waiting_ids)} کاربر در لیست انتظار این بسته بودند؛ به آن‌ها اطلاع داده شد."
    detail = ""
    add_mode = data.get("cfg_add_mode", "auto")
    disp_lbl = "🪟 شیشه‌ای" if display == "glass" else "➕➖ فرم"
    if vol == 0:  # کانفیگ نامحدود
        price_lbl = f"{price:,} تومان" if price else "قیمت کلی نامحدود"
        detail = (f"\n\n♾️ نامحدود · {fmt_days(days)}"
                  f"\n👥 کاربر: {users if users else '—'}"
                  f"\n💰 قیمت: {price_lbl}"
                  + (f"\n💵 قیمت هر روز: {price_day:,} تومان" if price_day else "")
                  + f"\n🖼 نمایش: {disp_lbl}")
    elif add_mode == "manual":  # کانفیگ محدودِ دستی → نمایش جزئیات قیمت اختصاصی
        price_lbl = f"{price:,} تومان" if price else "قیمت کلی"
        detail = (f"\n\n📦 {vol} گیگ · {fmt_days(days)}"
                  f"\n👥 کاربر: {users if users else '—'}"
                  f"\n💰 قیمت اختصاصی: {price_lbl}"
                  f"\n🖼 نمایش: {disp_lbl}")
    else:  # حالت انتخابی (قیمت کلی)
        detail = (f"\n\n📦 {vol} گیگ · {fmt_days(days)}"
                  f"\n💰 قیمت: از تنظیمات کلی (قیمت هر گیگ/روز)"
                  f"\n🖼 نمایش: ➕➖ فرم")
    # === PATCH_CFG_BULK_BOTH_MODES_V1 === سرخطِ نتیجه با تعدادِ واقعی
    if len(codes) > 1:
        headline = (f"✅ <b>{len(codes)}</b> کانفیگ وارد انبار شد."
                    f"\n🗂 کدها: {codes[0]} تا {codes[-1]}")
    else:
        headline = f"✅ کانفیگ با کد <b>{code}</b> ثبت شد."
    await msg.answer(f"{headline}{detail}{note}",
                     reply_markup=cfg_manage_kb(row.plan))
    # اطلاع به کاربران لیست انتظار
    for uid in waiting_ids:
        try:
            await bot.send_message(
                uid,
                f"🎉 بسته‌ای که می‌خواستی شارژ شد!\n"
                f"📦 {fmt_vol(vol)} / {fmt_days(days)}\n\n"
                "حالا می‌تونی از بخش «🛒 خرید کانفیگ» تهیه‌اش کنی.")
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")


# ═══════════ ابزارهای مشترک انبار (نمایش/صفحه‌بندی/جزئیات) ═══════════

_CFG_PAGE = 10  # تعداد کانفیگ در هر صفحه


def _cfg_vol_disp(c: "Config") -> str:
    return "♾️ نامحدود" if int(c.volume_gb or 0) == 0 else f"{c.volume_gb} گیگ"


# === PATCH_ZERO_DAYS_LABEL_V1 ===
# باگِ گزارش‌شده (تیکت #489): «۰ روز» به کاربر نشان داده می‌شد. برایِ حجم
# از قبل fmt_vol/_cfg_vol_disp وجود داشت و صفر را «نامحدود» می‌کرد، ولی
# معادلش برایِ «روز» هیچ‌جا نبود و هر جا خام چاپ می‌شد.
def fmt_days(days) -> str:
    """برچسبِ مدت — صفر یعنی بی‌انقضا، نه «۰ روز»."""
    d = int(days or 0)
    return "♾️ بی‌انقضا" if d == 0 else f"{d} روز"


def _cfg_days_disp(c: "Config") -> str:
    return fmt_days(getattr(c, "days", 0))


# === PATCH_UNLIMITED_LABEL_V1 ===
def fmt_vol(gb) -> str:
    """برچسبِ حجم — صفر یعنی نامحدود، نه «۰ گیگ»."""
    gb = int(gb or 0)
    return "♾️ نامحدود" if gb == 0 else f"{gb} گیگ"


def _cfg_status_disp(c: "Config") -> str:
    return {
        "in_stock": "✅ موجود",
        "sold": "🛒 فروخته‌شده",
        "stopped": "⛔️ متوقف‌شده",
        "reserved": "⏳ رزروِ موقت (در انتظارِ پرداخت)",
    }.get(c.status, c.status)


async def _cfg_buyer_block(s, c: "Config") -> str:
    """متن مشخصات خریدارِ یک کانفیگ فروخته‌شده."""
    if not c.owner_user_id:
        return "👤 خریدار: —"
    u = await s.get(BotUser, c.owner_user_id)
    if not u:
        return "👤 خریدار: (کاربر حذف شده)"
    uname = f"@{u.username}" if u.username else "—"
    return (
        "👤 <b>مشخصات خریدار</b>\n"
        f"   • نام: {u.full_name or '—'}\n"
        f"   • یوزرنیم: {uname}\n"
        f"   • آیدی عددی: <code>{u.telegram_id}</code>\n"
        f"   • موجودی کیف پول: {rial(u.balance)}"
    )


# === PATCH_CFG_EDIT_BACK_TO_LIST_V1 ===
# قبلاً دکمهٔ «⬅️ بازگشت» اینجا به callback_data="cfg:add:cancel" وصل بود؛
# آن هندلر همیشه state رو پاک می‌کند و ادمین رو به منوی اصلیِ «مدیریتِ
# کانفیگ‌ها» می‌فرستد — نه به همان صفحه از لیستِ «ویرایش کانفیگ» که ازش
# اومده بود. وقتی ادمین چندین کانفیگِ فروخته‌شده رو یکی‌یکی از همین صفحه
# (ویرایش → وضعیت/حذف) مدیریت می‌کرد، بعدِ هر کدام باید دوباره از اول
# «📦 انبار کانفیگ‌های دستی» → «✏️ ویرایش کانفیگ» → صفحه‌گردی می‌کرد.
# الان «بازگشت» و همهٔ نقاطِ پایانِ ویرایش (حذف/تغییرِ وضعیت/نمایش/مقدار)
# به همان صفحهٔ لیست (ذخیره‌شده در state با کلیدِ edit_page) برمی‌گردند.
def _cfg_edit_field_kb() -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="🔗 تغییر لینک کانفیگ", callback_data="cfef:payload", style=ButtonStyle.PRIMARY)],
        [InlineKeyboardButton(text="📏 تغییر حجم", callback_data="cfef:volume", style=ButtonStyle.PRIMARY),
         InlineKeyboardButton(text="📅 تغییر روز", callback_data="cfef:days", style=ButtonStyle.PRIMARY)],
        [InlineKeyboardButton(text="💰 قیمت اختصاصی", callback_data="cfef:price", style=ButtonStyle.PRIMARY),
         InlineKeyboardButton(text="👥 تعداد کاربر", callback_data="cfef:users", style=ButtonStyle.PRIMARY)],
        [InlineKeyboardButton(text="🏷 دسته‌بندی", callback_data="cfef:category", style=ButtonStyle.PRIMARY)],
        [InlineKeyboardButton(text="🖼 حالت نمایش (شیشه‌ای/فرم)", callback_data="cfef:display", style=ButtonStyle.PRIMARY)],
        [InlineKeyboardButton(text="🔄 وضعیت کانفیگ", callback_data="cfef:status", style=ButtonStyle.SUCCESS)],
        [InlineKeyboardButton(text="🗑 حذف کانفیگ", callback_data="cfef:delete", style=ButtonStyle.DANGER)],
        [InlineKeyboardButton(text="⬅️ بازگشت به لیست", callback_data="cfef:back", style=ButtonStyle.DANGER)],
    ])


async def _cfg_edit_list_text_kb(row: "TenantBot", page: int):
    """متن+کیبوردِ صفحهٔ «ویرایش کانفیگ» برایِ یک صفحهٔ مشخص — برایِ
    استفادهٔ مشترک در نمایشِ اولیه و در بازگشت بعدِ هر عملیاتِ ویرایش."""
    kb, page, total = await _cfg_list_page_kb(row.id, page, "edit")
    if total == 0:
        return "📦 انبار خالی است؛ کانفیگی برای ویرایش وجود ندارد.", cfg_manage_kb(row.plan)
    text = (
        "✏️ <b>ویرایش کانفیگ</b>\n"
        f"مجموع: <b>{total}</b> کانفیگ\n\n"
        "یک کانفیگ را برای ویرایش انتخاب کن، یا با کد اختصاصی جستجو کن:"
    )
    return text, kb


def _cfg_edit_field_text(cfg: "Config") -> str:
    price_lbl = f"{int(cfg.price):,} ت" if cfg.price else "قیمت کلی"
    disp_lbl = "🪟 شیشه‌ای" if cfg.display_mode == "glass" else "➕➖ فرم"
    vol_lbl = _cfg_vol_disp(cfg)
    cat_lbl = cfg.category or "—"
    payload = (cfg.payload or "").strip()
    if payload:
        # === PATCH_PAYLOAD_EDIT_PREVIEW_V1 === قبلاً در ۲۰۰ کاراکتر بریده می‌شد (لینکِ دومِ
        # SSH/NPV نصفه می‌ماند) و همه داخلِ یک <code> بود. حالا کامل و هر لینک جدا.
        if len(payload) <= 2800:
            _ph, _pm = _fmt_payload_html(payload)
            link_line = f"🔗 لینک/محتوا:\n{_ph if _pm else '<code>' + _html.escape(payload) + '</code>'}\n"
        else:
            link_line = f"🔗 لینک/محتوا:\n<code>{_html.escape(payload[:2800])}</code>…\n"
    else:
        link_line = "🔗 لینک/محتوا: <i>— خالی —</i>\n"
    # اگر رزرو مانده، هشدار بده
    warn = ""
    if cfg.status == "reserved":
        warn = ("\n⚠️ این کانفیگ در حالتِ «رزروِ موقت» است (کاربری واردِ خرید شده "
                "ولی پرداخت کامل نشده). اگر فروش نرفته، از دکمهٔ «🔄 وضعیت کانفیگ» "
                "آن را به «موجود» برگردان.\n")
    return (
        f"✏️ کانفیگ <b>#{cfg.code}</b> | {vol_lbl}/{cfg.days}روز | {_cfg_status_disp(cfg)}\n"
        f"💰 {price_lbl} · 👥 {cfg.user_count or '—'} · {disp_lbl} · 🏷 {cat_lbl}\n"
        f"{link_line}"
        f"{warn}\n"
        "کدام فیلد را ویرایش کنی؟"
    )


async def _cfg_list_page_kb(row_id: int, page: int, mode: str) -> tuple[InlineKeyboardMarkup, int, int]:
    """کیبورد صفحه‌بندی‌شدهٔ کانفیگ‌ها.
    mode="del"  → فقط کانفیگ‌های فروخته/متوقف‌شده (برای حذف/توقف)
    mode="edit" → همهٔ کانفیگ‌ها (برای ویرایش)
    خروجی: (کیبورد، صفحهٔ نرمال‌شده، تعداد کل)
    """
    async with Session() as s:
        q = select(Config).where(Config.bot_id == row_id)
        if mode == "del":
            q = q.where(Config.status.in_(["sold", "stopped", "reserved"]))
        q = q.order_by(Config.code)
        cfgs = (await s.scalars(q)).all()

    total = len(cfgs)
    pages = max(1, (total + _CFG_PAGE - 1) // _CFG_PAGE)
    page = max(0, min(page, pages - 1))
    chunk = cfgs[page * _CFG_PAGE:(page + 1) * _CFG_PAGE]

    verb = "delv" if mode == "del" else "editv"
    rows: list = []
    for c in chunk:
        tag = " ✍️" if int(c.price or 0) > 0 else ""
        cat_tag = f" 🏷{c.category}" if c.category else ""
        # برچسبِ برجستهٔ «رزرو» تا ادمین سریع ببیند کدام کانفیگ گیر کرده
        resv_tag = " ⏳رزرو" if c.status == "reserved" else ""
        label = (f"#{c.code} · {_cfg_vol_disp(c)}/{c.days}روز · "
                 f"{_cfg_status_disp(c)}{resv_tag}{tag}{cat_tag}")
        # === PATCH_CFG_EDIT_BACK_TO_LIST_V1 ===
        # برایِ حالتِ «edit» شمارهٔ صفحه را هم توی callback جاسازی می‌کنیم
        # تا بعدِ ویرایش/حذفِ یک کانفیگ بتوانیم دقیقاً به همین صفحه از
        # لیست برگردیم، نه به منویِ اصلیِ مدیریتِ کانفیگ‌ها (نگاه کن به
        # توضیحِ کاملِ پچ کنارِ _cfg_edit_field_kb).
        cb_data = f"tadm:cfg:{verb}:{c.id}:{page}" if mode == "edit" else f"tadm:cfg:{verb}:{c.id}"
        rows.append([InlineKeyboardButton(text=label, callback_data=cb_data, style=ButtonStyle.PRIMARY)])

    nav: list = []
    if page > 0:
        nav.append(InlineKeyboardButton(text="◀️ قبلی", callback_data=f"tadm:cfg:{mode}p:{page-1}", style=ButtonStyle.PRIMARY))
    nav.append(InlineKeyboardButton(text=f"صفحه {page+1}/{pages}", callback_data="noop"))
    if page < pages - 1:
        nav.append(InlineKeyboardButton(text="بعدی ▶️", callback_data=f"tadm:cfg:{mode}p:{page+1}", style=ButtonStyle.PRIMARY))
    if nav:
        rows.append(nav)

    # دکمهٔ حذف/ویرایش «با کد»
    if mode == "del":
        rows.append([InlineKeyboardButton(text="🔢 حذف با کد اختصاصی", callback_data="tadm:cfg:delc", style=ButtonStyle.DANGER)])
    else:
        rows.append([InlineKeyboardButton(text="🔢 ویرایش با کد اختصاصی", callback_data="tadm:cfg:editc", style=ButtonStyle.PRIMARY)])
    rows.append([InlineKeyboardButton(text="⬅️ بازگشت به انبار", callback_data="tadm:cfg", style=ButtonStyle.DANGER)])
    return InlineKeyboardMarkup(inline_keyboard=rows), page, total


@tenant_router.callback_query(F.data == "tadm:cfg:list")
async def tadm_cfg_list(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    async with Session() as s:
        cfgs = (await s.scalars(
            select(Config).where(Config.bot_id == row.id)
        )).all()

    if not cfgs:
        await cb.message.edit_text("📦 انبار خالی است.", reply_markup=cfg_manage_kb(row.plan))
        await cb.answer()
        return

    # ── تفکیک آماده / نامحدود و گروه‌بندی ──
    ready: dict = {}       # (vol, days) → {"stock":n, "sold":n, "stopped":n}
    unlimited: dict = {}   # days → {...}

    def _bucket(d, key, c):
        b = d.setdefault(key, {"stock": 0, "sold": 0, "stopped": 0})
        if c.status == "in_stock":
            b["stock"] += 1
        elif c.status == "stopped":
            b["stopped"] += 1
        else:
            b["sold"] += 1

    for c in cfgs:
        if int(c.volume_gb or 0) == 0:
            _bucket(unlimited, int(c.days), c)
        else:
            _bucket(ready, (int(c.volume_gb), int(c.days)), c)

    tot_stock = sum(1 for c in cfgs if c.status == "in_stock")
    tot_sold = sum(1 for c in cfgs if c.status == "sold")
    tot_stopped = sum(1 for c in cfgs if c.status == "stopped")

    def _mark(stock: int) -> str:
        if stock == 0:
            return "🔴"          # به صفر رسیده
        if stock <= 3:
            return "🟡"          # رو به اتمام
        return "🟢"              # موجودی خوب

    lines = [
        "📦 <b>انبار هوشمند کانفیگ</b>",
        f"🟢 موجود: <b>{tot_stock}</b>  ·  🛒 فروخته: <b>{tot_sold}</b>  ·  ⛔️ متوقف: <b>{tot_stopped}</b>",
        "<i>🟢 موجودی خوب · 🟡 رو به اتمام (≤۳) · 🔴 به صفر رسیده</i>",
    ]

    # ── بخش کانفیگ‌های آماده ──
    lines.append("\n🛒 <b>کانفیگ‌های آماده</b>")
    if ready:
        for (vol, days) in sorted(ready.keys()):
            b = ready[(vol, days)]
            extra = f" · ⛔️{b['stopped']}" if b["stopped"] else ""
            lines.append(
                f"{_mark(b['stock'])} {fmt_vol(vol)} / {fmt_days(days)} → "
                f"موجود <b>{b['stock']}</b> · فروخته {b['sold']}{extra}"
            )
    else:
        lines.append("— موردی ثبت نشده —")

    # ── بخش کانفیگ‌های نامحدود ──
    lines.append("\n♾️ <b>کانفیگ‌های نامحدود</b>")
    if unlimited:
        for days in sorted(unlimited.keys()):
            b = unlimited[days]
            extra = f" · ⛔️{b['stopped']}" if b["stopped"] else ""
            lines.append(
                f"{_mark(b['stock'])} نامحدود / {fmt_days(days)} → "
                f"موجود <b>{b['stock']}</b> · فروخته {b['sold']}{extra}"
            )
    else:
        lines.append("— موردی ثبت نشده —")

    text = "\n".join(lines)
    if len(text) > 3900:
        text = text[:3850] + "\n\n… (لیست طولانی بود، خلاصه شد)"

    # === PATCH_TENANT_CFG_LIST_NOT_MODIFIED_V1 ===
    # اگه ادمین دوبار پشتِ سرِ هم روی «📋 لیست انبار» بزنه (یا به‌خاطرِ لگِ
    # شبکه، تلگرام همون تپ رو دوباره بفرسته) و محتوای انبار از تپِ قبلی
    # عوض نشده باشه، متن و کیبورد دقیقاً همونیه که همین الان روی پیام
    # هست — تلگرام اینجا خطای «message is not modified» می‌ده که قبلاً
    # گرفته نمی‌شد و تا لایهٔ هندلرِ سراسریِ خطا بالا می‌رفت؛ ادمین به‌جای
    # دیدنِ همون لیست، پاپ‌آپِ «خطای پیش‌بینی‌نشده. کد: ERR-XXXXXX» می‌دید،
    # درحالی‌که لیست از قبل درست پشتِ اون پاپ‌آپ نمایش داده شده بود.
    try:
        await cb.message.edit_text(text, reply_markup=cfg_manage_kb(row.plan))
    except TelegramBadRequest as e:
        if "message is not modified" not in str(e).lower():
            raise
    await cb.answer()



