@tenant_router.callback_query(F.data.startswith("tadm:cfg:editv:"))
async def tadm_cfg_edit_view(cb: CallbackQuery, bot: Bot, state: FSMContext):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    # === PATCH_CFG_EDIT_BACK_TO_LIST_V1 ===
    # callback: tadm:cfg:editv:{cfg_id}:{page} — قسمتِ page ممکنه نباشه
    # (سازگاری با کیبوردهای قدیمیِ کش‌شده)، پس با دیفالتِ 0 می‌خونیمش.
    parts = cb.data.split(":")
    cfg_id = fa_to_int(parts[3]) if len(parts) > 3 else None
    edit_page = fa_to_int(parts[4]) if len(parts) > 4 else 0
    async with Session() as s:
        cfg = await s.get(Config, cfg_id)
        if not cfg or cfg.bot_id != row.id:
            await cb.answer("کانفیگ یافت نشد.", show_alert=True)
            return
        buyer = await _cfg_buyer_block(s, cfg) if cfg.owner_user_id else ""
    await state.update_data(edit_cfg_id=cfg.id, edit_page=edit_page)
    await state.set_state(AdminFSM.edit_cfg_field)
    text = _cfg_edit_field_text(cfg)
    if buyer:
        text = text.replace("\n\nکدام فیلد", f"\n\n{buyer}\n\nکدام فیلد")
    await cb.message.edit_text(text, reply_markup=_cfg_edit_field_kb())
    await cb.answer()


