@tenant_router.callback_query(F.data == "tadm:cfg:delall")
async def tadm_cfg_delall_confirm(cb: CallbackQuery, bot: Bot, state: FSMContext):
    """مرحلهٔ اول: فقط هشدار + گرفتنِ تایید. هیچ چیزی حذف نمی‌شود."""
    row = await _owner_ok(cb, bot)
    if not row:
        return
    await state.clear()
    async with Session() as s:
        total = await s.scalar(
            select(func.count()).select_from(Config).where(Config.bot_id == row.id)) or 0
        in_stock = await s.scalar(
            select(func.count()).select_from(Config).where(
                Config.bot_id == row.id, Config.status == "in_stock")) or 0
    sold = total - in_stock

    if total == 0:
        await cb.answer("انبار خالی است؛ چیزی برای حذف نیست.", show_alert=True)
        return

    await cb.message.edit_text(
        "🧨 <b>حذف تمام کانفیگ‌های موجود</b>\n\n"
        f"در انبار این ربات مجموعاً <b>{total}</b> کانفیگ ثبت شده:\n"
        f"• 📦 موجود (فروخته‌نشده): <b>{in_stock}</b>\n"
        f"• ✅ فروخته‌شده: <b>{sold}</b>\n\n"
        "⚠️ <b>هشدار جدی — این کار برگشت‌پذیر نیست!</b>\n"
        "با تایید، <b>همهٔ</b> کانفیگ‌های بالا (چه موجود و چه فروخته‌شده) برای همیشه از "
        "دیتابیس پاک می‌شوند. کانفیگ‌هایی که کاربران خریده‌اند هم از سرویس‌هایشان حذف "
        "می‌شود و هیچ راهی برای بازگرداندن آن‌ها وجود ندارد.\n\n"
        "💡 اگر مطمئن نیستی، اول از بخش «💾 بک‌آپ گیری از کانفیگ‌ها» یک بک‌آپ بگیر.\n\n"
        "آیا واقعاً می‌خواهی همه را حذف کنی؟",
        reply_markup=InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text=f"🧨 بله، هر {total} کانفیگ را حذف کن",
                                  callback_data=f"tadm:cfg:delallgo:{total}",
                                  style=ButtonStyle.DANGER)],
            [InlineKeyboardButton(text="⬅️ نه، منصرف شدم", callback_data="tadm:cfg", style=ButtonStyle.DANGER)],
        ]))
    await cb.answer()


@tenant_router.callback_query(F.data.startswith("tadm:cfg:delallgo:"))
async def tadm_cfg_delall_exec(cb: CallbackQuery, bot: Bot):
    """مرحلهٔ دوم: حذف واقعی، فقط بعد از تاییدِ صریحِ مالک."""
    row = await _owner_ok(cb, bot)
    if not row:
        return
    expected = fa_to_int(cb.data.split(":")[-1]) or 0
    async with Session() as s:
        total = await s.scalar(
            select(func.count()).select_from(Config).where(Config.bot_id == row.id)) or 0
        # اگر بین نمایشِ هشدار و تایید، تعداد عوض شده باشد دوباره تایید می‌گیریم
        if total != expected:
            await cb.answer(
                "تعداد کانفیگ‌ها از زمان نمایش هشدار تغییر کرده؛ لطفاً دوباره تلاش کن.",
                show_alert=True)
            return
        if total == 0:
            await cb.answer("انبار خالی است.", show_alert=True)
            return
        from sqlalchemy import delete as _sa_delete
        await s.execute(_sa_delete(Config).where(Config.bot_id == row.id))
        await s.commit()

    logger.warning("owner %s deleted ALL %s configs of bot_id=%s",
                   cb.from_user.id, total, row.id)
    await cb.message.edit_text(
        f"🧨 <b>{total}</b> کانفیگ حذف شد. انبار کانفیگ‌های دستی اکنون خالی است.\n\n"
        "این عملیات برگشت‌پذیر نیست؛ اگر بک‌آپ داری می‌تونی از «📥 ایمپورت بک‌آپ» بازیابی کنی.",
        reply_markup=InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text="⬅️ بازگشت به انبار", callback_data="tadm:cfg", style=ButtonStyle.DANGER)],
        ]))
    await cb.answer("همه حذف شدند.")


