@tenant_router.message(AdminFSM.search_user, F.text)
async def admin_search_user(msg: Message, state: FSMContext, bot: Bot):
    await state.clear()
    raw = (msg.text or "").strip()
    uid = fa_to_int(raw)
    if uid:
        # ورودی عددی → مستقیم با آیدی تلگرام
        await _render_user_detail(msg, bot, uid)
        return
    # در غیر این صورت به‌عنوان یوزرنیم جستجو کن (با یا بدون @، بدون حساسیت به حروف)
    uname = raw.lstrip("@").strip()
    if not uname:
        await msg.answer("شناسه نامعتبر. یک آیدی عددی یا یوزرنیم بفرست.")
        return
    row = await get_bot_row(bot)
    if not row:
        return
    async with Session() as s:
        u = await s.scalar(select(BotUser).where(
            BotUser.bot_id == row.id,
            func.lower(BotUser.username) == uname.lower()))
    if not u:
        await msg.answer(
            "کاربری با این یوزرنیم یافت نشد.\n"
            "(یوزرنیم فقط برای کاربرانی کار می‌کند که قبلاً با ربات در ارتباط بوده‌اند "
            "و در زمان تعامل، یوزرنیم داشته‌اند.)")
        return
    await _render_user_detail(msg, bot, u.telegram_id)


