@tenant_router.callback_query(F.data.startswith("usr:refs:"))
async def usr_refs(cb: CallbackQuery, bot: Bot):
    """فهرستِ زیرمجموعه‌هایِ یک کاربر، با صفحه‌بندی."""
    row = await get_bot_row(bot)
    if not row:
        return await cb.answer()
    if not await is_owner_or_admin(row.id, cb.from_user.id, row.owner_id):
        return await cb.answer("دسترسی ندارید", show_alert=True)

    parts = cb.data.split(":")
    uid, off = int(parts[2]), int(parts[3])
    PAGE = 15

    async with Session() as s:
        u = await s.scalar(select(BotUser).where(
            BotUser.bot_id == row.id, BotUser.telegram_id == uid))
        if not u:
            return await cb.answer("کاربر پیدا نشد", show_alert=True)
        total = await s.scalar(select(func.count()).select_from(ReferralJoin).where(
            ReferralJoin.bot_id == row.id, ReferralJoin.inviter_user_id == u.id))
        joins = (await s.scalars(select(ReferralJoin).where(
            ReferralJoin.bot_id == row.id, ReferralJoin.inviter_user_id == u.id
            ).order_by(ReferralJoin.id.desc()).limit(PAGE).offset(off))).all()
        tg_ids = [j.referred_telegram_id for j in joins]
        subs = {}
        if tg_ids:
            for su in (await s.scalars(select(BotUser).where(
                    BotUser.bot_id == row.id,
                    BotUser.telegram_id.in_(tg_ids)))).all():
                subs[su.telegram_id] = su

    if not total:
        return await cb.answer(
            "این کاربر هنوز کسی را دعوت نکرده است.", show_alert=True)

    lines = [f"👥 <b>زیرمجموعه‌هایِ</b> {_html.escape(u.full_name or '—')}",
             f"مجموع: <b>{total}</b> نفر\n"]
    for j in joins:
        su = subs.get(j.referred_telegram_id)
        nm = _html.escape((su.full_name if su else None) or "—")
        un = f"@{su.username}" if (su and su.username) else "—"
        d = j.created_at.strftime("%Y-%m-%d") if j.created_at else "—"
        mark = "💰" if j.purchase_rewarded else "⏳"
        lines.append(f"{mark} {nm} · {_html.escape(un)}")
        lines.append(f"   <code>{j.referred_telegram_id}</code> · {d}"
                     + (f" · پاداش {int(float(j.reward_paid)):,}" if j.reward_paid else ""))

    lines.append("\n💰 = خرید کرده و پاداش پرداخت شده · ⏳ = هنوز خریدی نداشته")

    nav = []
    if off > 0:
        nav.append(InlineKeyboardButton(text="⬅️ قبلی",
                                        callback_data=f"usr:refs:{uid}:{max(0, off - PAGE)}"))
    if off + PAGE < (total or 0):
        nav.append(InlineKeyboardButton(text="بعدی ➡️",
                                        callback_data=f"usr:refs:{uid}:{off + PAGE}"))
    kb = ([nav] if nav else []) + [[InlineKeyboardButton(
        text="⬅️ بازگشت به کارتِ کاربر", callback_data=f"usr:card:{uid}",
        style=ButtonStyle.DANGER)]]

    try:
        await cb.message.edit_text("\n".join(lines), parse_mode="HTML",
                                   reply_markup=InlineKeyboardMarkup(inline_keyboard=kb))
    except Exception:
        await cb.message.answer("\n".join(lines), parse_mode="HTML",
                                reply_markup=InlineKeyboardMarkup(inline_keyboard=kb))
    await cb.answer()


async def _render_user_detail(target, bot: Bot, uid: int, edit: bool = False) -> None:
    """نمایشِ کارتِ کاربر + دکمه‌های مدیریت. target باید متد answer() داشته باشد
    (هم Message و هم cb.message این متد را دارند). اگر edit=True باشد (فقط برای
    cb.message معتبر است)، به‌جای فرستادنِ پیامِ جدید، همان کارتِ موجود را
    edit_text می‌کند تا برچسبِ دکمه‌ها (مثلاً بعد از بن/آنبن) بلافاصله به‌روز شود."""
    row = await get_bot_row(bot)
    if not row:
        return
    async with Session() as s:
        u = await s.scalar(select(BotUser).where(
            BotUser.bot_id == row.id, BotUser.telegram_id == uid))
        if not u:
            await target.answer("کاربری با این شناسه یافت نشد.")
            return
        orders_count = await s.scalar(select(func.count()).select_from(Order).where(
            Order.bot_id == row.id, Order.user_id == u.id, Order.status == "paid"))
        txns_sum = await s.scalar(select(func.coalesce(func.sum(Order.amount), 0)).where(
            Order.bot_id == row.id, Order.user_id == u.id, Order.status == "paid"))
        # تعداد زیرمجموعه‌هایی که این کاربر آورده
        ref_link = (await s.scalars(select(ReferralLink).where(
            ReferralLink.bot_id == row.id, ReferralLink.user_id == u.id
            ).order_by(ReferralLink.id.asc()))).first()
        ref_join_count = int(ref_link.join_count) if ref_link else 0
        ref_real_count = int(await s.scalar(
            select(func.count()).select_from(ReferralJoin).where(
                ReferralJoin.bot_id == row.id,
                ReferralJoin.inviter_user_id == u.id)) or 0)
        ref_click_count = int(ref_link.click_count) if ref_link else 0
    ban_label = "🔓 بن‌شده — بزن آنبن شود" if u.is_banned else "🚫 بن کردن"
    # === PATCH_USR_DAYS_VPN_ONLY_V1 ===
    # دکمهٔ «افزودن روز به سرویس VPN» فقط برای ربات‌های فروش VPN معنا داره؛
    # قبلاً تو همهٔ زمینه‌ها (فروشگاه، تبلیغاتی و...) بی‌دلیل نشون داده می‌شد.
    kb_rows = [
        [InlineKeyboardButton(text="➕ شارژ کیف پول", callback_data=f"usr:add:{uid}"),
         InlineKeyboardButton(text="➖ کسر کیف پول", callback_data=f"usr:sub:{uid}")],
    ]
    if row.field == "vpn_sales":
        kb_rows.append([InlineKeyboardButton(text="📡 افزودن/کاهش روز سرویس VPN",
                                             callback_data=f"usr:days:{uid}")])
        # === PATCH_ADMIN_USER_SVC_MGMT_V1 ===
        kb_rows.append([InlineKeyboardButton(text="📦 افزودن/کاهش حجم سرویس VPN",
                                             callback_data=f"usr:gb:{uid}")])
        kb_rows.append([InlineKeyboardButton(text="⚙️ توقف/فعال‌سازی/حذفِ سرویس",
                                             callback_data=f"usr:svc:{uid}")])
        # === PATCH_TRIAL_RESET_ONE_USER_V1 ===
        # پیشنهادِ کاربردیِ ادمین: تا الان فقط «ریست برای همه» (رویِ هر
        # دکمهٔ تست، جدا) وجود داشت. این دکمه دقیقاً همون درخواست است: فقط
        # همین یک کاربر، بدونِ اینکه سهمیهٔ بقیه دست بخوره.
        kb_rows.append([InlineKeyboardButton(text="♻️ ریستِ تستِ رایگان برایِ این کاربر",
                                             callback_data=f"usr:trreset:{uid}")])
        _tu_raw = await get_setting(row.id, "trial_unlimited_users", "")
        _tu_on = str(u.telegram_id) in {x.strip() for x in _tu_raw.split(",") if x.strip()}
        kb_rows.append([InlineKeyboardButton(
            text=("♾ تستِ نامحدود: ✅ فعال (زدن = لغو)" if _tu_on else "♾ دادنِ تستِ نامحدود به این کاربر"),
            callback_data=f"usr:trunl:{uid}")])
    kb_rows += [
        [InlineKeyboardButton(text="🧾 رسیدها و خریدهای کاربر", callback_data=f"usr:receipts:{uid}")],
        # === PATCH_ADMIN_DM_USER_V1 ===
        [InlineKeyboardButton(text="💬 ارسال پیام اختصاصی", callback_data=f"usr:dm:{uid}")],
    ]
    # === PATCH_ADMIN_USER_REFS_V1 ===
    # درخواستِ ادمین: بشود دید هر کاربر دقیقاً چه کسانی را دعوت کرده،
    # نه فقط تعدادش. دادهٔ کامل از قبل در referral_joins موجود است.
    # === PATCH_ADMIN_USER_REFS_V2 ===
    kb_rows.append([InlineKeyboardButton(
        text=f"👥 زیرمجموعه‌هایِ این کاربر ({ref_real_count})",
        callback_data=f"usr:refs:{uid}:0")])

    # === PATCH_PUBLIC_API_PER_USER_V1 ===
    if row.field == "virtual_service":
        api_lbl = ("🔌 دسترسیِ API: 🔴 غیرفعال کن" if u.api_access else "🔌 دسترسیِ API: 🟢 فعال کن")
        kb_rows.append([InlineKeyboardButton(text=api_lbl, callback_data=f"usr:apitoggle:{uid}")])
        if u.api_access:
            disc_lbl = (f"💯 درصدِ تخفیفِ API ({float(u.api_discount_pct):g}٪)" if u.api_discount_pct
                       else "💯 تنظیمِ درصدِ تخفیفِ API")
            kb_rows.append([InlineKeyboardButton(text=disc_lbl, callback_data=f"usr:apidisc:{uid}")])
        # === PATCH_APIUSER_ISSUE_KEY_V1 ===
        # ادمین بدونِ اینکه منتظرِ کاربر بمونه، خودش کلید رو می‌سازه، تویِ
        # همین‌جا می‌بینه و مستقیم برایِ کاربر ارسال می‌شه.
        issue_lbl = ("📤 ساختِ کلیدِ جدید و ارسال به کاربر" if u.api_key
                     else "📤 ساختِ کلیدِ API و ارسال به کاربر")
        kb_rows.append([InlineKeyboardButton(
            text=issue_lbl, callback_data=f"apiuser:issue:{uid}",
            style=ButtonStyle.SUCCESS)])
    kb_rows += [
        [InlineKeyboardButton(text=ban_label, callback_data=f"usr:ban:{uid}")],
        [InlineKeyboardButton(text="⬅️ بازگشت", callback_data="tadm:sec:stats", style=ButtonStyle.DANGER)],
    ]
    kb = InlineKeyboardMarkup(inline_keyboard=kb_rows)
    ref_line = f"\n👥 زیرمجموعه‌های دعوت‌شده: {ref_join_count} نفر (👆 {ref_click_count} کلیک)" if (ref_join_count or ref_click_count) else ""
    # === PATCH_PUBLIC_API_PER_USER_V1 ===
    api_line = ""
    if row.field == "virtual_service":
        if u.api_access:
            disc_txt = f" — تخفیف: {float(u.api_discount_pct):g}٪" if u.api_discount_pct else " — بدونِ تخفیفِ اختصاصی"
            api_line = f"\n🔌 دسترسیِ API: ✅ فعال{disc_txt}"
        else:
            api_line = "\n🔌 دسترسیِ API: ❌ غیرفعال"
    text = (
        f"👤 کاربر <code>{uid}</code>\n"
        f"نام: {u.full_name or '—'}\n"
        f"یوزرنیم: @{u.username or '—'}\n"
        f"موجودی کیف پول: {rial(u.balance)}\n"
        f"خریدهای موفق: {orders_count}\n"
        f"مجموع خرید: {rial(txns_sum)}\n"
        f"وضعیت: {'🚫 بن‌شده' if u.is_banned else '✅ فعال'}"
        f"{ref_line}"
        f"{api_line}"
        f"{await _rules_history_text(row.id, u)}"
    )
    if edit:
        try:
            await target.edit_text(text, reply_markup=kb)
            return
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await target.answer(text, reply_markup=kb)


