@tenant_router.callback_query(F.data.startswith("usr:dm:"))
async def admin_dm_user_start(cb: CallbackQuery, bot: Bot, state: FSMContext):
    """ادمین می‌خواد به یک کاربرِ خاص پیامِ اختصاصی بفرسته."""
