@tenant_router.callback_query(F.data.startswith("usr:cfgdelc:"))
async def admin_user_cfg_del_exec(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    _, _, aid, uid = cb.data.split(":")
    aid = int(aid)
    async with Session() as s:
        a = await s.get(PanelAccount, aid)
        if not a or a.bot_id != row.id:
            await cb.answer("کانفیگ یافت نشد یا قبلاً حذف شده.", show_alert=True)
            try:
                await cb.message.delete()
            except Exception:
                logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
            return
        panel = await _panel_for_account(s, row.id, a)
        email = a.email
        panel_data = None
        if panel and panel.enabled:
            panel_data = (panel.base_url, panel.username, panel.password,
                          panel.sub_base or "", panel.inbound_ids, panel.panel_key, panel.api_key)  # PATCH_PANEL_API_KEY_PROPAGATION_V1

    panel_err = None
    if panel_data:
        client = make_panel_client_from_fields(
            panel_data[5], panel_data[0], panel_data[1], panel_data[2],
            sub_base=panel_data[3], inbound_ids_str=panel_data[4], api_key=panel_data[6])  # PATCH_PANEL_API_KEY_PROPAGATION_V1
        try:
            await client.delete_account(email)
        except PanelError as e:
            panel_err = str(e)
        except Exception as e:
            panel_err = str(e)
        finally:
            try:
                await client.close()
            except Exception:
                logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")

    async with Session() as s:
        a2 = await s.get(PanelAccount, aid)
        if a2 is not None and await _is_foreign(a2, bot):   # PATCH_TENANT_SCOPE_V1
            a2 = None
        if a2:
            await s.delete(a2)
            await s.commit()

    if panel_err:
        await cb.answer("کانفیگ از دیتابیس حذف شد ولی حذف روی پنل با خطا مواجه شد:\n" + panel_err[:150],
                        show_alert=True)
    else:
        await cb.answer("✅ کانفیگ حذف شد.", show_alert=True)
    try:
        await cb.message.edit_text(f"🗑 کانفیگ «{email}» حذف شد.", reply_markup=None)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    try:
        await bot.send_message(int(uid), f"⚠️ سرویس شما «{email}» توسط مدیریت حذف شد.")
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")


