    try:
        await bot.send_message(int(uid), f"⚠️ کانفیگ شما با کد «{code}» توسط مدیریت حذف شد.")
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")


