@tenant_router.callback_query(F.data.startswith("usr:phishc:"))
async def admin_user_phish_exec(cb: CallbackQuery, bot: Bot):
    """اجرای واقعیِ حذفِ گروهی: همهٔ PanelAccount (آنلاین) + همهٔ Config فروخته‌شدهٔ
    این کاربر (آماده/انبار/نامحدود) حذف می‌شوند و فهرستِ حذف‌شده‌ها به ادمین گزارش می‌شود."""
    row = await _owner_ok(cb, bot)
    if not row:
        return
    uid = int(cb.data.split(":")[2])
    await cb.answer("در حال حذف...")

    async with Session() as s:
        accts = (await s.scalars(select(PanelAccount).where(
            PanelAccount.bot_id == row.id, PanelAccount.user_telegram_id == uid))).all()
        u = await s.scalar(select(BotUser).where(
            BotUser.bot_id == row.id, BotUser.telegram_id == uid))
        manual_cfgs = []
        if u:
            manual_cfgs = (await s.scalars(select(Config).where(
                Config.bot_id == row.id, Config.owner_user_id == u.id,
                Config.status == "sold"))).all()

    removed_lines = []
    # حذفِ کانفیگ‌های آنلاین (تلاش برای حذف از روی پنل هم)
    for a in accts:
        async with Session() as s:
            panel = await _panel_for_account(s, row.id, a)
            panel_data = None
            if panel and panel.enabled:
                panel_data = (panel.base_url, panel.username, panel.password,
                              panel.sub_base or "", panel.inbound_ids, panel.panel_key, panel.api_key)  # PATCH_PANEL_API_KEY_PROPAGATION_V1
        if panel_data:
            try:
                client = make_panel_client_from_fields(
                    panel_data[5], panel_data[0], panel_data[1], panel_data[2],
                    sub_base=panel_data[3], inbound_ids_str=panel_data[4], api_key=panel_data[6])  # PATCH_PANEL_API_KEY_PROPAGATION_V1
                try:
                    await client.delete_account(a.email)
                except Exception:
                    logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
                finally:
                    await client.close()
            except Exception:
                logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        async with Session() as s:
            a2 = await s.get(PanelAccount, a.id)
            if a2:
                await s.delete(a2)
                await s.commit()
        removed_lines.append(f"📡 آنلاین — {_svc_label(a.plan_title, a.volume_gb, a.days, a.volume_mb)} — {a.email}")

    # حذفِ کانفیگ‌های آمادهٔ/انبارِ فروخته‌شده
    for c in manual_cfgs:
        async with Session() as s:
            c2 = await s.get(Config, c.id)
            if c2:
                await s.delete(c2)
                await s.commit()
        vol = "نامحدود" if int(c.volume_gb or 0) == 0 else f"{c.volume_gb} گیگ"
        removed_lines.append(f"🗄 آماده/انبار — کد {c.code} — {vol}/{c.days}روز")

    if removed_lines:
        report = "🎣 <b>گزارشِ فیشینگ ثبت شد.</b> کانفیگ‌های زیر از این کاربر حذف شدند:\n\n" + \
                 "\n".join(removed_lines)
    else:
        report = "این کاربر هیچ کانفیگ فعالی نداشت که حذف شود."
    try:
        await cb.message.edit_text(report, reply_markup=None)
    except Exception:
        await cb.message.answer(report)
    try:
        await bot.send_message(
            uid, "⚠️ به دلیل مغایرت در رسیدهای پرداخت، تمامی سرویس‌های شما توسط مدیریت حذف شدند. "
                 "برای پیگیری با پشتیبانی در ارتباط باشید.")
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")


@tenant_router.callback_query(F.data.startswith("usr:"))
async def admin_user_action(cb: CallbackQuery, state: FSMContext, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    _, action, uid = cb.data.split(":")
    uid = int(uid)
    if action == "ban":
        if _is_platform_admin(uid):   # PATCH_BAN_ONLY_MAIN_ADMIN_EXEMPT_V1
            await cb.answer("⛔️ این کاربر قابل‌بن‌کردن نیست.", show_alert=True)
            return
        async with Session() as s:
            u = await s.scalar(select(BotUser).where(
                BotUser.bot_id == row.id, BotUser.telegram_id == uid))
            if not u:
                await cb.answer("کاربر یافت نشد", show_alert=True)
                return
            u.is_banned = not u.is_banned
            now_banned = u.is_banned
            await s.commit()
        await cb.answer("🚫 بن شد" if now_banned else "🔓 آنبن شد", show_alert=True)
        # پیام به خودِ کاربر
        try:
            if now_banned:
                await bot.send_message(
                    uid, "🚫 دسترسی شما به این ربات توسط مدیریت مسدود (بن) شد.")
            else:
                await bot.send_message(
                    uid, "✅ مسدودیتِ شما برداشته شد و دوباره می‌توانی از ربات استفاده کنی.")
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        # بروزرسانیِ فوریِ کارت (تا برچسبِ دکمه بلافاصله «بن‌شده/آنبن» را نشان دهد)
        await _render_user_detail(cb.message, bot, uid, edit=True)
        return
    # === PATCH_PUBLIC_API_PER_USER_V1 ===
    if action == "apitoggle":
        import secrets as _secrets
        async with Session() as s:
            u = await s.scalar(select(BotUser).where(
                BotUser.bot_id == row.id, BotUser.telegram_id == uid).with_for_update())
            if not u:
                await cb.answer("کاربر یافت نشد", show_alert=True)
                return
            u.api_access = not u.api_access
            u.api_expires_at = None   # === PATCH_API_PAID_ACCESS_V1 === فعال‌سازیِ دستی = دائمی
            if u.api_access and not u.api_key:
                u.api_key = _secrets.token_hex(24)
            now_on = u.api_access
            await s.commit()
        await cb.answer("✅ دسترسیِ API فعال شد" if now_on else "🔴 دسترسیِ API غیرفعال شد", show_alert=True)
