# === PATCH_ADMIN_USER_SVC_MGMT_V1 ===
def _fa_to_signed_int(text: str) -> int | None:
    """مثلِ fa_to_int، ولی علامتِ منفی را هم قبول می‌کند — برایِ افزودن/کاهشِ
    دستیِ روز یا حجمِ سرویس توسطِ ادمین."""
    t = (text or "").strip()
    neg = t.startswith("-")
    if neg:
        t = t[1:].strip()
    n = fa_to_int(t)
    if n is None:
        return None
    return -n if neg else n


@tenant_router.message(AdminFSM.adjust_days, F.text)
async def admin_adjust_days(msg: Message, state: FSMContext, bot: Bot):
    data = await state.get_data()
    await state.clear()
    # === PATCH_ADMIN_USER_SVC_MGMT_V1 ===
    # قبلاً فقط عددِ مثبت قبول می‌شد (فقط افزودن). حالا عددِ منفی هم
    # قبول می‌شود تا ادمین بتواند روزِ سرویس را کم هم بکند.
    add_days = _fa_to_signed_int(msg.text)
    if not add_days or add_days == 0:
        await msg.answer("عدد نامعتبر. یک عددِ صحیح بفرست (مثلاً 30 یا -10).")
        return
    row = await get_bot_row(bot)
    if not row:
        return
    aid = data.get("target_account_id")
    target_uid = data.get("target_uid")
    async with Session() as s:
        a = await s.get(PanelAccount, aid)
        if not a or a.bot_id != row.id:
            await msg.answer("سرویس یافت نشد.")
            return
        panel = await _panel_for_account(s, row.id, a)
        if not panel or not panel.enabled:
            await msg.answer("پنلِ این سرویس یافت نشد یا غیرفعال است.")
            return
        email = a.email
        panel_data = (panel.base_url, panel.username, panel.password,
                      panel.sub_base or "", panel.inbound_ids, panel.panel_key, panel.api_key)  # PATCH_PANEL_API_KEY_PROPAGATION_V1

    client = make_panel_client_from_fields(
        panel_data[5], panel_data[0], panel_data[1], panel_data[2],
        sub_base=panel_data[3], inbound_ids_str=panel_data[4], api_key=panel_data[6])  # PATCH_PANEL_API_KEY_PROPAGATION_V1
    try:
        await client.renew(email, add_days)
    except PanelError as e:
        verb = "افزودنِ" if add_days > 0 else "کمِ"
        await msg.answer(f"❌ {verb} روز روی پنل ناموفق بود.\nخطا: {e}")
        try:
            await client.close()
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        return
    try:
        await client.close()
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")

    async with Session() as s:
        a2 = await s.get(PanelAccount, aid)
        if a2 is not None and await _is_foreign(a2, bot):   # PATCH_TENANT_SCOPE_V1
            a2 = None
        if a2:
            a2.expiry_notice = None
            # === PATCH_EXPIRY_WARN_QUOTA_V1 === با تمدید، چرخهٔ اخطار از نو
            a2.expiry_warn_count = 0
            a2.status = "active"
            base = a2.expires_at if a2.expires_at and a2.expires_at > _dt.datetime.utcnow() else _dt.datetime.utcnow()
            a2.expires_at = base + _dt.timedelta(days=add_days)
            a2.days = (a2.days or 0) + add_days
            await s.commit()

    # === PATCH_ADMIN_USER_SVC_MGMT_V1 === پیام سازگار با هر دو حالت افزودن/کم‌کردن
    if add_days > 0:
        summary = f"✅ {add_days} روز به سرویس «{email}» اضافه شد."
        notify = f"📡 مدیر ربات {add_days} روز به سرویسِ شما اضافه کرد."
    else:
        summary = f"✅ {-add_days} روز از سرویس «{email}» کم شد."
        notify = f"📡 مدیر ربات {-add_days} روز از سرویسِ شما کم کرد."
    await msg.answer(summary, reply_markup=await _admin_panel_kb(row))
    if target_uid:
        try:
            await bot.send_message(
                target_uid,
                notify + "\nاز «📡 سرویس‌های من» می‌تونی تاریخ انقضای جدید رو ببینی.")
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")


# ═══════════════════════════════════════════
#  افزودن/کاهشِ حجم — PATCH_ADMIN_USER_SVC_MGMT_V1
# ═══════════════════════════════════════════

@tenant_router.callback_query(F.data.startswith("usrgbacc:"))
async def admin_user_gb_pick(cb: CallbackQuery, state: FSMContext, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    _, aid, uid = cb.data.split(":")
    async with Session() as s:
        a = await s.get(PanelAccount, int(aid))
    if not a or a.bot_id != row.id:
        await cb.answer("سرویس یافت نشد.", show_alert=True)
        return
    # === PATCH_ADMIN_GB_MB_SERVICE_V1 ===
    # «نامحدود» فقط وقتی است که هم volume_gb صفر باشد و هم volume_mb خالی.
    # سرویسِ زیرِ ۱ گیگ (مثلِ تستِ ۲۰ مگابایتی) volume_gb=0 دارد ولی
    # volume_mb>0 — این نامحدود نیست و باید بشود حجم اضافه/کم کرد.
    if (a.volume_gb or 0) == 0 and not (a.volume_mb or 0):
        await cb.answer("این سرویس نامحدود است؛ افزودن/کاهشِ گیگ برایش معنی ندارد.",
                        show_alert=True)
        return
    if a.volume_mb and (a.volume_gb or 0) == 0:
        cur_txt = f"{fa_digits(a.volume_mb)} مگابایت"
    else:
        cur_txt = f"{fa_digits(a.volume_gb)} گیگ"
    await state.set_state(AdminFSM.adjust_gb)
    await state.update_data(target_account_id=int(aid), target_uid=int(uid))
    await cb.message.answer(
        f"حجمِ فعلیِ سرویس: {cur_txt}.\n\n"
        "چند گیگ اضافه/کم شود؟ (فقط عدد)\n"
        "برایِ افزودن، عددِ مثبت (مثلاً <code>5</code>)؛ برایِ کم‌کردن، با "
        "منفی بفرست (مثلاً <code>-2</code>).",
        reply_markup=await smart_cancel_kb(bot))
    await cb.answer()


@tenant_router.message(AdminFSM.adjust_gb, F.text)
async def admin_adjust_gb(msg: Message, state: FSMContext, bot: Bot):
    data = await state.get_data()
    await state.clear()
    add_gb = _fa_to_signed_int(msg.text)
    if not add_gb or add_gb == 0:
        await msg.answer("عدد نامعتبر. یک عددِ صحیح بفرست (مثلاً 5 یا -2).")
        return
    row = await get_bot_row(bot)
    if not row:
        return
    aid = data.get("target_account_id")
    target_uid = data.get("target_uid")
    async with Session() as s:
        a = await s.get(PanelAccount, aid)
        if not a or a.bot_id != row.id:
            await msg.answer("سرویس یافت نشد.")
            return
        # === PATCH_ADMIN_USER_SVC_MGMT_V1 ===
        # ۰ در volume_gb یعنی «نامحدود» در کلِ این پروژه؛ اگر بگذاریم با
        # کم‌کردن دقیقاً به ۰ برسد، سرویس اشتباهاً نامحدود می‌شود. برایِ
        # همین یا رد می‌کنیم، یا سقفِ مجازِ کم‌کردن را می‌گوییم.
        cur_vol = a.volume_gb or 0
        # === PATCH_ADMIN_GB_MB_SERVICE_V1 ===
        # سرویسِ زیرِ ۱ گیگ (volume_gb=0 ولی volume_mb>0) نامحدود نیست؛
        # افزودنِ گیگ به آن مجاز است (روی پنل به حجمِ مگابایتیِ فعلی اضافه
        # می‌شود). فقط وقتی هم gb صفر است و هم mb خالی، واقعاً نامحدود است.
        is_mb_service = (cur_vol == 0 and (a.volume_mb or 0) > 0)
        if cur_vol == 0 and not is_mb_service:
            await msg.answer("این سرویس نامحدود است؛ افزودن/کاهشِ گیگ برایش معنی ندارد.")
            return
        if not is_mb_service and cur_vol + add_gb <= 0:
            await msg.answer(
                f"❌ بیشترین مقداری که می‌توانی کم کنی {fa_digits(cur_vol - 1)} گیگ است "
                "(چون صفر یعنی نامحدود، نمی‌گذاریم دقیقاً صفر شود).")
            return
        if is_mb_service and add_gb < 0:
            await msg.answer(
                "این سرویس حجمِ زیرِ ۱ گیگ (مگابایتی) دارد؛ فعلاً فقط می‌توانی "
                "به آن گیگ اضافه کنی، نه کم. یک عددِ مثبت بفرست.")
            return
        panel = await _panel_for_account(s, row.id, a)
        if not panel or not panel.enabled:
            await msg.answer("پنلِ این سرویس یافت نشد یا غیرفعال است.")
            return
        email = a.email
        panel_data = (panel.base_url, panel.username, panel.password,
                      panel.sub_base or "", panel.inbound_ids, panel.panel_key, panel.api_key)

    client = make_panel_client_from_fields(
        panel_data[5], panel_data[0], panel_data[1], panel_data[2],
        sub_base=panel_data[3], inbound_ids_str=panel_data[4], api_key=panel_data[6])
    try:
        await client.add_traffic(email, add_gb)
    except PanelError as e:
        verb = "افزودنِ" if add_gb > 0 else "کمِ"
        await msg.answer(f"❌ {verb} حجم روی پنل ناموفق بود.\nخطا: {e}")
        try:
            await client.close()
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        return
    try:
        await client.close()
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")

    async with Session() as s:
        a2 = await s.get(PanelAccount, aid)
        if a2 is not None and await _is_foreign(a2, bot):   # PATCH_TENANT_SCOPE_V1
            a2 = None
        if a2:
            a2.volume_gb = max(1, (a2.volume_gb or 0) + add_gb)
            # === PATCH_ADMIN_GB_MB_SERVICE_V1 ===
            # وقتی به سرویسِ مگابایتی گیگ اضافه شد، دیگر بر حسبِ گیگ اندازه‌گیری
            # می‌شود؛ volume_mb را پاک می‌کنیم تا نمایش («X مگابایت») به گیگ
            # سوییچ کند و اشتباهاً همان رقمِ قدیمیِ مگابایت نماند.
            a2.volume_mb = None
            await s.commit()

    if add_gb > 0:
        summary = f"✅ {add_gb} گیگ به سرویس «{email}» اضافه شد."
        notify = f"📦 مدیر ربات {add_gb} گیگ به سرویسِ شما اضافه کرد."
    else:
        summary = f"✅ {-add_gb} گیگ از سرویس «{email}» کم شد."
        notify = f"📦 مدیر ربات {-add_gb} گیگ از سرویسِ شما کم کرد."
    await msg.answer(summary, reply_markup=await _admin_panel_kb(row))
    if target_uid:
        try:
            await bot.send_message(
                target_uid,
                notify + "\nاز «📡 سرویس‌های من» می‌تونی حجمِ باقی‌مانده رو ببینی.")
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")


