@tenant_router.message(AdminFSM.adjust_amount, F.text)
async def admin_adjust(msg: Message, state: FSMContext, bot: Bot):
    data = await state.get_data()
    amount = fa_to_int(msg.text)
    if not amount:
        await msg.answer("مبلغ نامعتبر.")
        return
    # === PATCH_WALLET_ADJUST_AMOUNT_BOUNDS_V1 ===
    MAX_WALLET_ADJUST_AMOUNT = 999_999_999_999
    if abs(amount) > MAX_WALLET_ADJUST_AMOUNT:
        await msg.answer(
            f"❌ مبلغ خیلی بزرگه (بیشتر از سقفِ مجاز: {rial(MAX_WALLET_ADJUST_AMOUNT)}).\n"
            "لطفاً دوباره چک کن که صفرِ اضافه وارد نکرده باشی.")
        return
    # === PATCH_WALLET_ADJUST_STALE_STATE_GUARD_V1 ===
    if "target_uid" not in data:
        await msg.answer("⚠️ این عملیات قبلاً انجام شده یا منقضی شده. لطفاً دوباره از منو شروع کن.")
        await state.clear()
        return
    uid = data["target_uid"]
    sign = data["adj_sign"]
    if sign < 0:
        # کسر: قبل از اعمال، دلیل پرسیده می‌شود (اختیاری) تا پیامِ نهایی به
        # کاربر شفاف و حرفه‌ای باشد، نه یک خطِ خشکِ «کسر شد».
        await state.set_state(AdminFSM.adjust_deduct_reason)
        await state.update_data(target_uid=uid, adj_amount=amount)
        skip_kb = InlineKeyboardMarkup(inline_keyboard=[[
            InlineKeyboardButton(text="⏭ بدون دلیل (رد شو)", callback_data="adjdeduct:skip"),
        ]])
        await msg.answer(
            f"📝 دلیلِ کسرِ {rial(amount)} از کیف‌پولِ این کاربر را بفرست — این دلیل عیناً "
            "به خودِ کاربر هم نشان داده می‌شود.\n"
            "اگر نمی‌خوای دلیلی ذکر کنی، دکمه‌ی زیر را بزن:",
            reply_markup=skip_kb)
        return
    await state.clear()
    await _apply_wallet_adjust(msg, bot, uid, amount, reason=None)


async def _apply_wallet_adjust(msg_or_cb, bot: Bot, uid: int, amount: int,
                               reason: str | None) -> None:
    """اعمالِ واقعیِ افزایش/کسرِ موجودی + پیامِ حرفه‌ای به کاربر.
    amount علامت‌دار است: مثبت یعنی افزودن، منفی یعنی کسر (reason فقط برای
    حالتِ کسر معنا دارد)."""
    row = await get_bot_row(bot)
    if not row:
        return
    is_msg = isinstance(msg_or_cb, Message)
    answer = msg_or_cb.answer if is_msg else msg_or_cb.message.answer
    try:
        async with Session() as s:
            u = await s.scalar(select(BotUser).where(
                BotUser.bot_id == row.id, BotUser.telegram_id == uid).with_for_update())
            if not u:
                await answer("کاربر یافت نشد.")
                return
            # Numeric(12, 0) allows absolute values below 10^12. محاسبه با
            # float می‌توانست مقدار نهایی را از سقف عبور دهد و خطای PostgreSQL
            # NumericValueOutOfRange ایجاد کند؛ قبل از commit نتیجه را دقیق کنترل کن.
            from decimal import Decimal
            _max_wallet_balance = Decimal("999999999999")
            _current_balance = Decimal(str(u.balance or 0))
            _new_balance = _current_balance + Decimal(str(amount))
            # === PATCH_WALLET_ADJUST_ALLOW_NEGATIVE_V1 ===
            # قبلاً اینجا کسرِ بیشتر از موجودی رد می‌شد («موجودی کافی نیست»).
            # طبقِ درخواستِ صریحِ مالک، این محدودیت برداشته شد: کسرِ دستیِ
            # ادمین دوباره می‌تواند موجودی را منفی کند (اعتبار/بدهکاریِ
            # مشتری — مثلاً سرویس می‌دهد، بعداً کاربر شارژ می‌کند و تسویه
            # می‌شود). فقط سقفِ بالاییِ دیتابیس (NumericValueOutOfRange)
            # همچنان چک می‌شود، چون آن یک محدودیتِ فنیِ واقعیه، نه تصمیمِ کسب‌وکار.
            if _new_balance > _max_wallet_balance:
                await answer(
                    "❌ موجودی نهایی از سقف مجاز دیتابیس بیشتر می‌شود؛ موجودی تغییر نکرد.\n"
                    f"سقف موجودی: {rial(int(_max_wallet_balance))}"
                )
                return
            u.balance = _new_balance
            s.add(WalletTxn(bot_id=row.id, user_id=u.id, amount=amount, kind="admin",
                            note=(f"تنظیم دستی ادمین — دلیل: {reason}" if reason else "تنظیم دستی ادمین")))
            await s.commit()
            new_bal = u.balance
            # === PATCH_TX_LOG_ALL_MOVEMENTS_V1 ===
            # مقادیر باید *داخلِ* بلاکِ سشن خوانده شوند (بعد از خروج، آبجکت
            # منقضی می‌شود) — پس فقط اسنپ‌شات می‌گیریم و ارسال را بیرون
            # انجام می‌دهیم تا شبکه جلوی کامیت را نگیرد.
            _log_user, _log_new = u, float(new_bal)
            _old_bal = int(_current_balance)
    except Exception as e:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        # === PATCH_WALLET_ADJUST_SAFE_ERROR_MSG_V1 ===
        from html import escape as _html_escape
        safe_err = _html_escape(str(e))[:300]
        try:
            await answer(f"❌ عملیات ناموفق بود.\nخطا: {safe_err}")
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (ارسالِ پیامِ خطا هم ناموفق بود)")
        return
    # صراحتِ نتیجه: نوعِ عملیات + موجودیِ قبل/بعد، تا ادمین بلافاصله ببیند کسر شد یا شارژ.
    _verb = "➕ شارژ شد" if amount >= 0 else "➖ کسر شد"
    await answer(
        f"✅ {_verb}: {rial(abs(amount))}\n"
        f"موجودیِ قبل: {rial(_old_bal)}\n"
        f"موجودیِ جدید: {rial(new_bal)}",
        reply_markup=await tadmin_kb(row.id))
    # === PATCH_TX_LOG_ALL_MOVEMENTS_V1 ===
    # افزایش/کاهشِ دستیِ ادمین هم باید در کانالِ لاگ ثبت شود — این تابع
    # تنها مسیرِ هر دو حالت است، پس یک بار صدازدن هر دو را پوشش می‌دهد.
    try:
        from tenant.shared.tx_channel import tx_log
        await tx_log(bot, row.id, buyer=_log_user, amount=amount,
                     gateway=("admin_add" if amount >= 0 else "admin_deduct"),
                     old_balance=_log_new - amount, new_balance=_log_new,
                     note=(reason or ""))
    except Exception:
        logger.exception("tx_log (admin adjust)")
    from tenant.gateways.wallet_receipt import build_wallet_charge_message, build_wallet_deduct_message
    try:
        if amount >= 0:
            utext, ukb = build_wallet_charge_message(amount, new_bal, "admin")
        else:
            utext, ukb = build_wallet_deduct_message(-amount, new_bal, reason=reason)
        await bot.send_message(uid, utext, reply_markup=ukb)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")


@tenant_router.callback_query(F.data == "adjdeduct:skip")
async def admin_adjust_deduct_skip(cb: CallbackQuery, state: FSMContext, bot: Bot):
    data = await state.get_data()
    await state.clear()
    uid = data.get("target_uid")
    amount = data.get("adj_amount")
    if not uid or not amount:
        await cb.answer("اطلاعات منقضی شده، دوباره تلاش کن.", show_alert=True)
        return
    try:
        await cb.message.edit_reply_markup(reply_markup=None)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.answer()
    await _apply_wallet_adjust(cb, bot, uid, -amount, reason=None)


@tenant_router.message(AdminFSM.adjust_deduct_reason, F.text)
async def admin_adjust_deduct_reason(msg: Message, state: FSMContext, bot: Bot):
    data = await state.get_data()
    await state.clear()
    uid = data.get("target_uid")
    amount = data.get("adj_amount")
    if not uid or not amount:
        await msg.answer("اطلاعات منقضی شده، دوباره تلاش کن.")
        return
    reason = (msg.text or "").strip()[:300]
    await _apply_wallet_adjust(msg, bot, uid, -amount, reason=reason or None)


# ───── سفارش‌ها ─────

@tenant_router.callback_query(F.data == "tadm:orders")
async def tadm_orders(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    async with Session() as s:
        pending = (await s.scalars(
            select(Order).where(Order.bot_id == row.id, Order.status == "awaiting_admin")
            .order_by(Order.id.desc()).limit(20)
        )).all()
        recent = (await s.scalars(
            select(Order).where(Order.bot_id == row.id, Order.status == "paid")
            .order_by(Order.created_at.desc(), Order.id.desc()).limit(10)
        )).all()
        # آمار کلی
        total_sales = await s.scalar(
            select(func.coalesce(func.sum(Order.amount), 0))
            .where(Order.bot_id == row.id, Order.status == "paid")) or 0
        total_count = await s.scalar(
            select(func.count(Order.id))
            .where(Order.bot_id == row.id, Order.status == "paid")) or 0

    lines = ["┈┅━━⊷⊰✨⊱⊶━━┅┈",
             f"📦 تعداد فروش: <b>{int(total_count)}</b>",
             f"💰 مجموع فروش: <b>{int(total_sales):,} تومان</b>",
             "┈┅━━⊷⊰✨⊱⊶━━┅┈",
             "<b>🕐 آخرین فروش‌ها</b> (روی هرکدام بزن برای مشخصاتِ کامل):"]
    txt = "🧾 <b>سفارش‌ها و فروش</b>\n\n" + "\n".join(lines)
    order_btns = []
    for o in recent:
        trk = o.tracking_code or f"#{o.id}"
        jdate, _jtime = _jalali_date_time(o.created_at)
        if o.pay_method == "card_charge":
            btn_txt = f"💳 {trk} — {rial(o.amount)} — {jdate}"
        else:
            btn_txt = f"📦 {trk} — {rial(o.amount)} — {jdate}"
        order_btns.append([InlineKeyboardButton(text=btn_txt, callback_data=f"tadm:order_detail:{o.id}", style=ButtonStyle.PRIMARY)])
    # === PATCH_PARTNER_SETTINGS_BACK_FIX_V1 ===
    _ord_back_cb = "pp:settings" if row.plan == "partner" else "tadm:sec:finance"
    kb = InlineKeyboardMarkup(inline_keyboard=(
        order_btns +
        [[InlineKeyboardButton(text="🔍 جستجو با کد پیگیری", callback_data="tadm:order_search", style=ButtonStyle.PRIMARY)],
         [InlineKeyboardButton(text="⬅️ بازگشت", callback_data=_ord_back_cb, style=ButtonStyle.DANGER)]]
    ))
    await _safe_edit(cb, txt, reply_markup=kb)
    await cb.answer()

    # رسیدهای در انتظار تأیید
    for o in pending:
        trk = o.tracking_code or f"#{o.id}"
        inv = o.tracking_code or o.invoice_no or f"#{o.id}"
        if o.pay_method == "card_charge":
            cap = f"💳 شارژ کیف‌پول\nفاکتور: {inv} | کد: {trk}\nمبلغ: {rial(o.amount)}"
            kb2 = InlineKeyboardMarkup(inline_keyboard=[
                [InlineKeyboardButton(text="✅ تأیید", callback_data=f"chadm:ok:{o.id}",
                                      style=ButtonStyle.SUCCESS),
                 InlineKeyboardButton(text="❌ رد", callback_data=f"chadm:no:{o.id}",
                                      style=ButtonStyle.DANGER)],
                [InlineKeyboardButton(text="🗑 حذف سفارش", callback_data=f"tadm:order_del:{o.id}", style=ButtonStyle.DANGER)],
            ])
        else:
            cap = (f"📦 {o.volume_gb}G/{o.days}D×{o.count}\n"
                   f"فاکتور: {inv} | کد: {trk}\n"
                   f"مبلغ: {rial(o.amount)}")
            # === PATCH_ORDER_LIST_VPN_CARD_ROUTING_V1 ===
            # قبلاً این شاخه (هر چیزی غیر از card_charge) همیشه دکمه‌های
            # rcadm:* می‌ساخت — یعنی چکِ انبارِ دستیِ Config. برایِ سفارش‌های
            # pay_method="vpn_card" (خریدِ زنده از پنل، چه پلنِ ثابت چه
            # حالتِ +/- دلخواه) این غلط است: تاییدشان باید از vcadm_decide
            # (ساختِ زنده رویِ پنل) رد شود، نه از چکِ موجودیِ انبار. نتیجهٔ
            # باگ: از همین صفحه (🧾 سفارش‌ها و فروش) زدنِ تأیید رویِ یک
            # سفارشِ vpn_card همیشه با «موجودی کانفیگ کافی نیست» رد می‌شد،
            # حتی وقتی پنل کاملاً سالم و در دسترس بود — چون اصلاً کد به
            # پنل سر نمی‌زد. توجه: پیامِ خودکارِ کانالِ تاییدِ رسید
            # (receipt_confirm در card_purchase.py) از قبل این تفکیک را
            # درست انجام می‌داد؛ این باگ فقط مخصوصِ همین صفحهٔ مدیریتی بود.
            if o.pay_method == "vpn_card":
                kb2 = InlineKeyboardMarkup(inline_keyboard=[
                    [InlineKeyboardButton(text="✅ تأیید", callback_data=f"vcadm:ok:{o.id}",
                                          style=ButtonStyle.SUCCESS),
                     InlineKeyboardButton(text="❌ رد", callback_data=f"vcadm:no:{o.id}",
                                          style=ButtonStyle.DANGER)],
                    [InlineKeyboardButton(text="🗑 حذف سفارش", callback_data=f"tadm:order_del:{o.id}", style=ButtonStyle.DANGER)],
                ])
            else:
                kb2 = InlineKeyboardMarkup(inline_keyboard=[
                    [InlineKeyboardButton(text="✅ تأیید", callback_data=f"rcadm:ok:{o.id}",
                                          style=ButtonStyle.SUCCESS),
                     InlineKeyboardButton(text="❌ رد", callback_data=f"rcadm:no:{o.id}",
                                          style=ButtonStyle.DANGER)],
                    [InlineKeyboardButton(text="🗑 حذف سفارش", callback_data=f"tadm:order_del:{o.id}", style=ButtonStyle.DANGER)],
                ])
        if o.receipt_file_id:
            await bot.send_photo(cb.from_user.id, o.receipt_file_id, caption=cap, reply_markup=kb2)
        else:
            await cb.message.answer(cap, reply_markup=kb2)


@tenant_router.callback_query(F.data.startswith("tadm:order_detail:"))
async def tadm_order_detail(cb: CallbackQuery, bot: Bot):
    """نمایشِ مشخصاتِ کاملِ یک سفارش (خریدار + بسته) — با زدن روی هرکدام از
    دکمه‌های «آخرین فروش‌ها» در tadm_orders باز می‌شود."""
    row = await _owner_ok(cb, bot)
    if not row:
        return
    oid = int(cb.data.split(":")[2])
    async with Session() as s:
        order = await s.get(Order, oid)
        if not order or order.bot_id != row.id:
            await cb.answer("سفارش یافت نشد.", show_alert=True)
            return
        buyer_block = "👤 خریدار: —"
        u = await s.get(BotUser, order.user_id)
        if u:
            uname = f"@{u.username}" if u.username else "—"
            buyer_block = (
                "👤 <b>مشخصات خریدار</b>\n"
                f"   • نام: {_html.escape(u.full_name or '—')}\n"
                f"   • یوزرنیم: {uname}\n"
                f"   • آیدی عددی: <code>{u.telegram_id}</code>\n"
                f"   • موجودی کیف پول: {rial(u.balance)}"
            )
        cfg = await s.get(Config, order.reserved_config_id) if order.reserved_config_id else None

    jdate, jtime = _jalali_date_time(order.created_at)
    if order.pay_method == "card_charge":
        pkg_block = "🛠 <b>نوعِ تراکنش</b>\n   • شارژ کیف پول"
    elif cfg:
        pkg_block = (
            "🛠 <b>بستهٔ فروخته‌شده</b>\n"
            f"   • کد کانفیگ: #{cfg.code}\n"
            f"   • حجم: {_cfg_vol_disp(cfg)} · مدت: {_cfg_days_disp(cfg)}\n"
            f"   • لینک: <code>{_html.escape((cfg.payload or '—')[:150])}</code>"
        )
    else:
        pkg_block = (
            "🛠 <b>مشخصاتِ بسته</b>\n"
            f"   • حجم: {order.volume_gb} گیگ · مدت: {order.days} روز · تعداد: {order.count}\n"
            f"   • روشِ پرداخت: {order.pay_method}"
        )

    label = f" ({_html.escape(order.custom_label)})" if order.custom_label else ""
    inv = order.invoice_no or "—"
    trk = order.tracking_code or "—"
    disc_line = f"\n🏷 کدِ تخفیف: {_html.escape(order.discount_code)}" if order.discount_code else ""
    text_out = (
        f"🧾 <b>جزئیاتِ سفارش</b>\n\n"
        f"🧾 شناسه سفارش: <code>{_html.escape(str(trk if trk != '—' else inv))}</code>\n"
        f"🕒 تاریخ: {jdate} — ساعت: {jtime}\n"
        f"💰 مبلغ: {rial(order.amount)}{label}{disc_line}\n\n"
        f"{buyer_block}\n\n"
        f"{pkg_block}"
    )
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="⬅️ بازگشت به لیست", callback_data="tadm:orders", style=ButtonStyle.DANGER)],
    ])
    try:
        await cb.message.edit_text(text_out, reply_markup=kb)
    except Exception:
        await cb.message.answer(text_out, reply_markup=kb)
    await cb.answer()


class _OrderSearchFSM(StatesGroup):
    waiting = State()


@tenant_router.callback_query(F.data == "tadm:order_search")
async def tadm_order_search_start(cb: CallbackQuery, bot: Bot, state: FSMContext):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    await state.set_state(_OrderSearchFSM.waiting)
    await cb.message.answer(
        "🔍 <b>جستجوی سفارش</b>\n\n"
        "کد پیگیری یا شماره فاکتور را بفرست:\n"
        "مثال: <code>AB12CD34</code> یا <code>BS5-0001</code>",
        reply_markup=InlineKeyboardMarkup(inline_keyboard=[[
            InlineKeyboardButton(text="❌ لغو", callback_data="tadm:orders", style=ButtonStyle.DANGER)]]))
    await cb.answer()


@tenant_router.message(_OrderSearchFSM.waiting)
async def tadm_order_search_exec(msg: Message, bot: Bot, state: FSMContext):
    row = await _owner_ok_msg(msg, bot)
    if not row:
        await state.clear(); return
    q = (msg.text or "").strip().upper()
    await state.clear()
    async with Session() as s:
        o = await s.scalar(select(Order).where(
            Order.bot_id == row.id,
            (Order.tracking_code == q) | (Order.invoice_no == q)))
        if not o:
            # === PATCH_UNIFIED_TRACKING_V1 === همان کد در سایرِ بخش‌ها (SMM/استارز/گیفت/محصول)
            from models import ProductOrder
            _extra = None
            so = await s.scalar(select(SmmOrder).where(
                SmmOrder.bot_id == row.id, SmmOrder.tracking_code == q))
            if so:
                _extra = (f"🛰 سفارشِ خدماتِ مجازی\n📦 {so.service_name or so.service_id}\n"
                          f"🔢 تعداد: {so.quantity:,}\n💰 {rial(so.price_toman)}\n📊 وضعیت: {so.status}\n"
                          f"👤 کاربر: <code>{so.user_telegram_id}</code>")
            else:
                go = await s.scalar(select(GiftOrder).where(
                    GiftOrder.bot_id == row.id, GiftOrder.tracking_code == q))
                if go:
                    _extra = (f"🎁 سفارشِ گیفت/استارز/پرمیوم\n📦 {go.gift_id} × {go.quantity or 1}\n"
                              f"→ {go.dest_label}\n💰 {rial(go.price_toman)}\n📊 وضعیت: {go.status}")
                else:
                    po = await s.scalar(select(ProductOrder).where(
                        ProductOrder.bot_id == row.id, ProductOrder.tracking_code == q))
                    if po:
                        _extra = (f"🛍 سفارشِ محصولِ دیجیتال\n💰 {rial(po.amount)}\n📊 وضعیت: {po.status}")
            if _extra:
                await msg.answer(f"🔍 <b>نتیجه جستجو</b>\n\n🆔 کد پیگیری: <code>{q}</code>\n"
                                 "┈┅━━⊷⊰✨⊱⊶━━┅┈\n" + _extra,
                                 reply_markup=InlineKeyboardMarkup(inline_keyboard=[[
                                     InlineKeyboardButton(text="⬅️ بازگشت", callback_data="tadm:orders",
                                                          style=ButtonStyle.DANGER)]]))
                return
            await msg.answer(f"❌ سفارشی با کد «{q}» یافت نشد.")
            return
        u = await s.get(BotUser, o.user_id)
    vol = "نامحدود" if o.volume_gb == 0 else f"{o.volume_gb} گیگ"
    dur = "بی‌انقضا" if o.days == 0 else f"{o.days} روز"
    uname = f"@{u.username}" if u and u.username else f"ID: {u.telegram_id}" if u else "نامشخص"
    status_map = {"paid":"✅ پرداخت‌شده","awaiting_admin":"⏳ در انتظار تأیید",
                  "awaiting_receipt":"📸 در انتظار رسید","rejected":"❌ رد‌شده","pending":"🔄 در انتظار"}
    st = status_map.get(o.status, o.status)
    txt = (
        f"🔍 <b>نتیجه جستجو</b>\n\n"
        f"🧾 شناسه سفارش: <code>{o.tracking_code or o.invoice_no or '—'}</code>\n"
        "┈┅━━⊷⊰✨⊱⊶━━┅┈\n"
        f"👤 خریدار: {uname}\n"
        f"📦 سرویس: {vol} / {dur} × {o.count}\n"
        f"💰 مبلغ: {rial(o.amount)}\n"
        f"💳 روش پرداخت: {o.pay_method}\n"
        f"📊 وضعیت: {st}\n"
    )
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="🗑 حذف سفارش", callback_data=f"tadm:order_del:{o.id}",
                              style=ButtonStyle.DANGER)],
        [InlineKeyboardButton(text="⬅️ بازگشت", callback_data="tadm:orders", style=ButtonStyle.DANGER)],
    ])
    if o.receipt_file_id:
        await msg.answer_photo(o.receipt_file_id, caption=txt, reply_markup=kb)
    else:
        await msg.answer(txt, reply_markup=kb)


@tenant_router.callback_query(F.data.startswith("tadm:order_del:"))
async def tadm_order_del(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    oid = int(cb.data.split(":")[2])
    async with Session() as s:
        o = await s.get(Order, oid)
        if o and o.bot_id == row.id:
            await s.delete(o)
            await s.commit()
    await cb.answer("سفارش حذف شد", show_alert=True)
    try:
        await cb.message.delete()
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")


    row = await _owner_ok(cb, bot)
    if not row:
        return
    async with Session() as s:
        orders = (await s.scalars(
            select(Order).where(Order.bot_id == row.id, Order.status == "awaiting_admin")
            .order_by(Order.id.desc()).limit(10)
        )).all()
        all_orders = (await s.scalars(
            select(Order).where(Order.bot_id == row.id)
            .order_by(Order.id.desc()).limit(10)
        )).all()
    lines = []
    for o in all_orders:
        if o.pay_method == "card_charge":
            desc = f"💳 شارژ کیف پول #{o.tracking_code or o.id} | {rial(o.amount)} | {o.status}"
        else:
            desc = f"#{o.tracking_code or o.id} | {o.volume_gb}گیگ/{o.days}روز×{o.count} | {rial(o.amount)} | {o.status}"
        lines.append(desc)
    txt = "🧾 <b>آخرین سفارش‌ها</b>\n\n" + ("\n".join(lines) if lines else "سفارشی ثبت نشده.")

    # رسیدهای در انتظار
    if orders:
        await cb.message.edit_text(txt, reply_markup=back_inline())
        await cb.answer()
        for o in orders:
            kb = InlineKeyboardMarkup(inline_keyboard=[[
                InlineKeyboardButton(text="✅ تایید", callback_data=f"rcadm:ok:{o.id}"),
                InlineKeyboardButton(text="❌ رد", callback_data=f"rcadm:no:{o.id}"),
            ]])
            cap = (f"رسید سفارش #{o.tracking_code or o.id}\n"
                   f"{'شارژ کیف پول' if o.pay_method=='card_charge' else f'{o.volume_gb}گیگ/{o.days}روز'}\n"
                   f"مبلغ: {rial(o.amount)}")
            if o.receipt_file_id:
                await bot.send_photo(cb.from_user.id, o.receipt_file_id, caption=cap, reply_markup=kb)
            else:
                await cb.message.answer(cap, reply_markup=kb)
    else:
        await cb.message.edit_text(txt + "\n\n✅ رسید در انتظاری نیست.", reply_markup=back_inline())
        await cb.answer()


