# === PATCH_BROADCAST_MEDIA_V1 ===
# گزارش: ادمین یک گیف با کپشن فرستاد و ربات هیچ واکنشی نداشت (فقط متن و عکس پذیرفته
# می‌شد و بقیه بی‌صدا نادیده گرفته می‌شد). حالا گیف/ویدیو/فایل/صوت هم با کپشن پذیرفته
# می‌شود، و هر نوعِ پشتیبانی‌نشده پیامِ روشن می‌گیرد.
_BC_MEDIA_SEND = {
    "photo": "send_photo", "animation": "send_animation", "video": "send_video",
    "document": "send_document", "audio": "send_audio", "voice": "send_voice",
}
_BC_MEDIA_ANSWER = {
    "photo": "answer_photo", "animation": "answer_animation", "video": "answer_video",
    "document": "answer_document", "audio": "answer_audio", "voice": "answer_voice",
}


@tenant_router.message(AdminFSM.broadcast_text,
                       F.animation | F.video | F.document | F.audio | F.voice)
async def bc_media(msg: Message, bot: Bot, state: FSMContext):
    if msg.animation:
        mtype, fid = "animation", msg.animation.file_id
    elif msg.video:
        mtype, fid = "video", msg.video.file_id
    elif msg.audio:
        mtype, fid = "audio", msg.audio.file_id
    elif msg.voice:
        mtype, fid = "voice", msg.voice.file_id
    else:
        mtype, fid = "document", msg.document.file_id
    body = msg.html_text if msg.caption else ""
    await state.update_data(bc_text=body, bc_photo=fid, bc_mtype=mtype, bc_button_ids=[])
    await _bc_after_content(msg, bot, state)


