async def _bc_after_content(msg: Message, bot: Bot, state: FSMContext):
    """=== PATCH_BROADCAST_PHOTO_CAPTION_V1 === ادامه‌ی مشترکِ مسیرِ متن/عکس."""
    await state.set_state(AdminFSM.broadcast_pick_buttons)
    await state.update_data(bc_guide_keys=[])  # PATCH_BROADCAST_PICK_GUIDE_V1
    row = await get_bot_row(bot)
    kb = await _broadcast_pick_kb(row.id, []) if row else None
    await msg.answer(
        "🔘 <b>دکمه‌های زیرِ پیام</b>\n\n"
        "اگه می‌خوای زیرِ این پیامِ همگانی، دکمه(هایی) از دکمه‌های خودِ ربات نمایش داده بشه "
        "(مثلاً «🛒 خرید جدید» یا «🆘 پشتیبانی»)، از لیستِ زیر انتخاب کن (چندتا هم می‌تونی بزنی). "
        "با زدنِ هرکدوم، تیک می‌خوره/برمی‌داره.\n\n"
        "اگه دکمه نمی‌خوای، «⏭ بدون دکمه، فقط متن» رو بزن.",
        reply_markup=kb,
    )


async def _broadcast_pick_kb(bot_id: int, selected_ids: list[int],
                             selected_guides: list[str] | None = None) -> InlineKeyboardMarkup:
    """PATCH_BROADCAST_BUTTONS_V1 — درختِ همهٔ دکمه‌های ربات (با زیرمنوها،
    به‌صورتِ تورفتگی) با تیکِ انتخاب، برای پیوست‌کردن به پیامِ همگانی."""
    async with Session() as s:
        btns = (await s.scalars(
            select(MainButton).where(MainButton.bot_id == bot_id)
            .order_by(MainButton.parent_id.is_(None).desc(), MainButton.row, MainButton.col)
        )).all()
    by_parent: dict[int | None, list] = {}
    for b in btns:
        by_parent.setdefault(b.parent_id, []).append(b)

    rows = []

    def _walk(parent_id, depth):
        for b in by_parent.get(parent_id, []):
            mark = "☑️" if b.id in selected_ids else "⬜"
            prefix = "↳ " * depth
            label = (b.label or "").strip() or f"دکمه #{b.id}"
            rows.append([InlineKeyboardButton(
                text=f"{mark} {prefix}{label}", callback_data=f"bc:pickbtn:{b.id}")])
            _walk(b.id, depth + 1)

    _walk(None, 0)
    # === PATCH_BROADCAST_PICK_GUIDE_V1 ===
    # درخواستِ کاربر: «آموزش اتصال» زیرمنویِ عادی نیست (یک دکمهٔ action="vpn_help"
    # با گزینه‌های داخلیِ اندروید/آیفون/ویندوز/سفارشی است — نگاه کن به
    # _guide_options)، پس تویِ درختِ بالا اصلاً ظاهر نمی‌شود. اگه ربات این
    # دکمه رو داره، یه ورودیِ جدا برایِ چسباندنِ یکی‌از گزینه‌هاش می‌ذاریم —
    # دقیقاً همون الگویی که برایِ «پستِ کانال» (tadm:chpost:pickguide) از قبل
    # هست، فقط اینجا چون تو چتِ خصوصیه، دکمه‌ها callback (نه دیپ‌لینک) میشن.
    if await _has_vpn_help_button(bot_id):
        _ng = len(selected_guides or [])
        rows.append([InlineKeyboardButton(
            text=("🧩 چسباندنِ دکمه‌هایِ آموزشِ اتصال" + (f" ({_ng})" if _ng else "")),
            callback_data="bc:pickguide")])
    rows.append([InlineKeyboardButton(text="⏭ بدون دکمه، فقط متن", callback_data="bc:pickskip")])
    n = len(selected_ids) + len(selected_guides or [])
    rows.append([InlineKeyboardButton(
        text=(f"✅ ادامه ({n} دکمه انتخاب‌شده)" if n else "✅ ادامه"),
        callback_data="bc:pickdone")])
    rows.append([InlineKeyboardButton(text="❌ لغو", callback_data="bc:cancel")])
    return InlineKeyboardMarkup(inline_keyboard=rows)


# === PATCH_BROADCAST_PICK_GUIDE_V1 ===
async def _bc_pick_guide_kb(bot_id: int, selected_guides: list[str]) -> InlineKeyboardMarkup:
    """انتخابگرِ مستقلِ گزینه‌هایِ «آموزش اتصال» برایِ پیوست به پیامِ همگانی
    — همون الگویِ _chpost_pick_guide_kb، فقط برمی‌گرده به انتخابگرِ همگانی."""
    rows = []
    for key, label in (await _guide_options(bot_id)).items():
        mark = "☑️" if key in selected_guides else "⬜"
        rows.append([InlineKeyboardButton(
            text=f"{mark} {label}", callback_data=f"bc:pickguidekey:{key}")])
    if not rows:
        rows.append([InlineKeyboardButton(
            text="⚠️ هنوز هیچ آموزشی تنظیم نشده", callback_data="noop")])
    n = len(selected_guides)
    rows.append([InlineKeyboardButton(
        text=(f"✅ بازگشت ({n} آموزش انتخاب‌شده)" if n else "✅ بازگشت"),
        callback_data="bc:pickguidedone")])
    return InlineKeyboardMarkup(inline_keyboard=rows)


@tenant_router.callback_query(AdminFSM.broadcast_pick_buttons, F.data == "bc:pickguide")
async def bc_pick_guide_open(cb: CallbackQuery, state: FSMContext, bot: Bot):
    row = await get_bot_row(bot)
    if not row:
        return
    data = await state.get_data()
    guides = list(data.get("bc_guide_keys") or [])
    kb = await _bc_pick_guide_kb(row.id, guides)
    try:
        await cb.message.edit_reply_markup(reply_markup=kb)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.answer()


@tenant_router.callback_query(AdminFSM.broadcast_pick_buttons, F.data.startswith("bc:pickguidekey:"))
async def bc_pick_guide_toggle(cb: CallbackQuery, state: FSMContext, bot: Bot):
    row = await get_bot_row(bot)
    if not row:
        return
    key = cb.data.split(":", 2)[2]
    data = await state.get_data()
    guides = list(data.get("bc_guide_keys") or [])
