async def _bc_ask_support_link(msg: Message, state: FSMContext):
    """PATCH_BROADCAST_SUPPORT_BTN_V1 — قبل از پیش‌نمایشِ نهایی، می‌پرسه آیا
    یه دکمهٔ جداگانهٔ «پشتیبانی» (لینک/یوزرنیم/شماره) هم زیرِ بقیهٔ دکمه‌ها
    اضافه بشه یا نه."""
    await state.set_state(AdminFSM.broadcast_support_link)
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="⏭ بدون دکمهٔ پشتیبانی", callback_data="bc:supportskip")],
        [InlineKeyboardButton(text="❌ لغو", callback_data="bc:cancel")],
    ])
    await msg.answer(
        "🆘 <b>دکمهٔ پشتیبانی</b>\n\n"
        "اگه می‌خوای یه دکمهٔ جداگانهٔ «پشتیبانی» هم زیرِ بقیهٔ دکمه‌ها اضافه بشه، "
        "لینک/یوزرنیم/شماره‌تماسِ پشتیبانی رو بفرست (مثلاً <code>@support_id</code> یا "
        "<code>https://t.me/support_id</code>).\n\n"
        "اگه نمی‌خوای، «⏭ بدون دکمهٔ پشتیبانی» رو بزن.",
        parse_mode="HTML", reply_markup=kb,
    )


@tenant_router.callback_query(AdminFSM.broadcast_support_link, F.data == "bc:supportskip")
async def bc_support_skip(cb: CallbackQuery, state: FSMContext, bot: Bot):
    await state.update_data(bc_support_link=None)
    await _bc_ask_audience(cb.message, state, bot)    # PATCH_BROADCAST_AUDIENCE_V1
    await cb.answer()


# === PATCH_BROADCAST_AUDIENCE_V1 === (تیکت #863)
async def _bc_ask_audience(msg: Message, state: FSMContext, bot: Bot):
    """قبل از تأیید: مخاطب را بپرس (همه / دارندگانِ سرویس / نامحدود / هر پنل / بدونِ سرویس). اگر ربات اصلاً
    سرویسِ VPN ندارد، مرحله رد می‌شود و برایِ همه می‌رود."""
    from tenant.shared.broadcast_runner import audience_options
    row = await get_bot_row(bot)
    # فقط رباتِ فروشِ VPN؛ رباتِ دیگر (خدماتِ مجازی، فروشگاه، رزرو، …) این مرحله را نمی‌بیند.
    opts = await audience_options(row.id) if (row and row.field == "vpn_sales") else []
    if not opts:
        await state.update_data(bc_audience="")
        await _bc_go_to_confirm(msg, state)
        return
    await state.set_state(AdminFSM.broadcast_audience)
    await state.update_data(bc_aud_keys=[k for k, _l, _n in opts])
    rows = [[InlineKeyboardButton(text=f"{lbl} ({n:,})", callback_data=f"bc:aud:{i}")]
            for i, (_k, lbl, n) in enumerate(opts)]
    rows.append([InlineKeyboardButton(text="❌ لغو", callback_data="bc:cancel")])
    await msg.answer(
        "🎯 <b>پیام برایِ چه کسانی ارسال شود؟</b>\n\n"
        "عددِ کنارِ هر گزینه تعدادِ مخاطبِ همان گروه است (بن‌شده‌ها همیشه کنار گذاشته می‌شوند).",
        parse_mode="HTML", reply_markup=InlineKeyboardMarkup(inline_keyboard=rows))


@tenant_router.callback_query(AdminFSM.broadcast_audience, F.data.startswith("bc:aud:"))
async def bc_audience_pick(cb: CallbackQuery, state: FSMContext):
    data = await state.get_data()
    keys = list(data.get("bc_aud_keys") or [])
    try:
        aud = keys[int(cb.data.split(":")[2])]
    except (ValueError, IndexError):
        await cb.answer("منقضی شد؛ دوباره شروع کن.", show_alert=True)
        return
    await state.update_data(bc_audience=aud)
    await cb.answer()
    await _bc_go_to_confirm(cb.message, state)


@tenant_router.callback_query(AdminFSM.broadcast_audience, F.data == "bc:cancel")
async def bc_audience_cancel(cb: CallbackQuery, state: FSMContext):
    await state.clear()
    await _bc_safe_edit(cb.message, "❌ ارسال همگانی لغو شد.")
    await cb.answer()


def _normalize_support_link(raw: str) -> str | None:
    """یوزرنیم/لینک/شماره‌تماسِ پشتیبانی رو به یه URLِ معتبر برای دکمهٔ
    اینلاین (یا نال اگه واقعاً نامعتبر بود) تبدیل می‌کنه."""
    raw = (raw or "").strip()
    if not raw:
        return None
    if raw.startswith("http://") or raw.startswith("https://") or raw.startswith("tg://"):
        return raw
    if raw.startswith("@"):
        return f"https://t.me/{raw[1:]}"
    if raw.startswith("+") or raw.replace(" ", "").isdigit():
        return f"tel:{raw.replace(' ', '')}"
    # فرض: یوزرنیمِ خام (بدون @)
    return f"https://t.me/{raw}"


@tenant_router.message(AdminFSM.broadcast_support_link, F.text)
async def bc_support_save(msg: Message, state: FSMContext, bot: Bot):
    if (msg.text or "").strip() in ("❌ لغو", "❌ لغو / بازگشت"):
        await state.clear()
        await msg.answer("❌ ارسال همگانی لغو شد.", reply_markup=ReplyKeyboardRemove())
        return
    link = _normalize_support_link(msg.text)
    await state.update_data(bc_support_link=link)
    await _bc_ask_audience(msg, state, bot)    # PATCH_BROADCAST_AUDIENCE_V1


async def _bc_go_to_confirm(msg: Message, state: FSMContext):
    data = await state.get_data()
    body = data.get("bc_text", "")
    button_ids = data.get("bc_button_ids") or []
    guide_keys = list(data.get("bc_guide_keys") or [])  # PATCH_BROADCAST_PICK_GUIDE_V1
    support_link = data.get("bc_support_link")  # PATCH_BROADCAST_SUPPORT_BTN_V1
    await state.set_state(AdminFSM.broadcast_confirm)
    preview_kb_rows = []
    if button_ids:
        async with Session() as s:
            btns = (await s.scalars(select(MainButton).where(MainButton.id.in_(button_ids)))).all()
        by_id = {b.id: b for b in btns}
        for bid in button_ids:
            b = by_id.get(bid)
            if b:
                preview_kb_rows.append([InlineKeyboardButton(
                    text=(b.label or f"دکمه #{bid}"), callback_data=f"mbtn:{bid}", style=ButtonStyle.PRIMARY)])
    if guide_keys:
        # === PATCH_BROADCAST_PICK_GUIDE_V1 ===
        # تو چتِ خصوصی (برخلافِ پستِ کانال) دیپ‌لینک لازم نیست؛ همون
        # callbackِ «vhelp:» که خودِ منویِ «آموزش اتصال» هم استفاده می‌کنه کافیه.
        row_owner = await get_bot_row(msg.bot)
        if row_owner:
            _glabels = await _guide_options(row_owner.id)
            for _k in guide_keys:
                _lbl = _glabels.get(_k)
                if _lbl:
                    preview_kb_rows.append([InlineKeyboardButton(
                        text=_lbl, callback_data=f"vhelp:{_k}", style=ButtonStyle.PRIMARY)])
    if support_link:
        preview_kb_rows.append([InlineKeyboardButton(text="🆘 پشتیبانی", url=support_link)])
    kb = InlineKeyboardMarkup(inline_keyboard=[
        *preview_kb_rows,
        [InlineKeyboardButton(text="✅ ارسال", callback_data="bc:send")],
        [InlineKeyboardButton(text="❌ لغو", callback_data="bc:cancel")],
    ])
    # === PATCH_BROADCAST_AUDIENCE_V1 === مخاطب و تعدادش در پیش‌نمایش
    _aud_line = ""
    _aud = data.get("bc_audience") or ""
    if _aud:
        from tenant.shared.broadcast_runner import audience_options, audience_label
        _row_aud = await get_bot_row(msg.bot)
        if _row_aud:
            _opts = await audience_options(_row_aud.id)
            _n = next((n for k, _l, n in _opts if k == _aud), 0)
            _aud_line = f"🎯 مخاطب: {audience_label(_opts, _aud)} — {_n:,} نفر\n\n"
    caption_suffix = (
        _aud_line
        + (f"({len(preview_kb_rows)} دکمه هم زیرش می‌ره)\n\n" if preview_kb_rows else "")
        + "آیا ارسال شود؟"
    )
    bc_photo = data.get("bc_photo")  # === PATCH_BROADCAST_PHOTO_CAPTION_V1 ===
    if bc_photo:
        _ans = getattr(msg, _BC_MEDIA_ANSWER.get(data.get("bc_mtype") or "photo", "answer_photo"))
        await _ans(
            bc_photo,
            caption=f"پیش‌نمایش:\n\n{body}\n\n{caption_suffix}",
            reply_markup=kb,
        )
    else:
        await msg.answer(
            f"پیش‌نمایش:\n\n{body}\n\n{caption_suffix}",
            reply_markup=kb,
        )


async def _bc_safe_edit(cb_message, text: str, reply_markup=None):
    """=== PATCH_BROADCAST_PHOTO_EDIT_FIX_V1 ===
    پیامِ پیش‌نمایشِ همگانی ممکنه عکس باشه (با کپشن) یا متنِ ساده؛ edit_text
    روی پیامِ عکس‌دار خطا می‌ده (تلگرام: «there is no text in the message
    to edit»). این تابع بر اساسِ نوعِ پیام، edit_caption یا edit_text
    مناسب رو صدا می‌زنه."""
    try:
        if cb_message.photo:
            await cb_message.edit_caption(caption=text, reply_markup=reply_markup)
        else:
            await cb_message.edit_text(text, reply_markup=reply_markup)
    except Exception:
        try:
            await cb_message.answer(text, reply_markup=reply_markup)
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")


@tenant_router.callback_query(AdminFSM.broadcast_confirm, F.data == "bc:cancel")
async def bc_cancel(cb: CallbackQuery, state: FSMContext):
    await state.clear()
    await _bc_safe_edit(cb.message, "❌ ارسال همگانی لغو شد.")
    await cb.answer()




@tenant_router.callback_query(AdminFSM.broadcast_confirm, F.data == "bc:send")
async def bc_send(cb: CallbackQuery, state: FSMContext, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        await state.clear()
        return
    data = await state.get_data()
    text = data["bc_text"]
    bc_photo = data.get("bc_photo")  # === PATCH_BROADCAST_PHOTO_CAPTION_V1 ===
    bc_mtype = data.get("bc_mtype") or "photo"   # PATCH_BROADCAST_MEDIA_V1
    button_ids = data.get("bc_button_ids") or []  # PATCH_BROADCAST_BUTTONS_V1
    guide_keys = list(data.get("bc_guide_keys") or [])  # PATCH_BROADCAST_PICK_GUIDE_V1
    support_link = data.get("bc_support_link")  # PATCH_BROADCAST_SUPPORT_BTN_V1
    bc_audience = data.get("bc_audience") or None   # PATCH_BROADCAST_AUDIENCE_V1
    await state.clear()
    bc_kb = None
    kb_rows = []
    if button_ids:
        async with Session() as s:
            btns = (await s.scalars(select(MainButton).where(MainButton.id.in_(button_ids)))).all()
        by_id = {b.id: b for b in btns}
        kb_rows = [[InlineKeyboardButton(text=(by_id[bid].label or f"دکمه #{bid}"),
                                         callback_data=f"mbtn:{bid}", style=ButtonStyle.PRIMARY)]
                   for bid in button_ids if bid in by_id]
    if guide_keys:
        # === PATCH_BROADCAST_PICK_GUIDE_V1 ===
        _glabels = await _guide_options(row.id)
        for _k in guide_keys:
            _lbl = _glabels.get(_k)
            if _lbl:
                kb_rows.append([InlineKeyboardButton(
                    text=_lbl, callback_data=f"vhelp:{_k}", style=ButtonStyle.PRIMARY)])
    if support_link:
        kb_rows.append([InlineKeyboardButton(text="🆘 پشتیبانی", url=support_link)])
    if kb_rows:
        bc_kb = InlineKeyboardMarkup(inline_keyboard=kb_rows)
    # === PATCH_BROADCAST_DURABLE_V1 ===
    # کار در دیتابیس ذخیره می‌شود و tenant/shared/broadcast_runner اجرایش می‌کند؛ اگر این پروسه ری‌استارت
    # شود، ورکر از همان نفری که مانده بود ادامه می‌دهد (قبلاً بی‌صدا قطع می‌شد و برایِ همیشه «sending» می‌ماند).
    from tenant.shared.broadcast_runner import audience_count as _aud_count
    n_users = await _aud_count(row.id, bc_audience)    # PATCH_BROADCAST_AUDIENCE_V1
    await _bc_safe_edit(cb.message, f"📢 در حال ارسال به {n_users:,} نفر...")
    async with Session() as s:
        bc = Broadcast(bot_id=row.id, text=text, status="sending",
                       media_id=bc_photo or None, media_type=(bc_mtype if bc_photo else None),
                       kb_json=(bc_kb.model_dump_json(exclude_none=True) if bc_kb else None),
                       chat_id=cb.message.chat.id, msg_id=cb.message.message_id,
                       cursor_uid=0, total_count=n_users, audience=bc_audience)
        s.add(bc)
        await s.commit()
        bc_id = bc.id
    kb_cancel = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="🛑 لغو ارسال", callback_data=f"bc:stop:{bc_id}")]
    ])
    await _bc_safe_edit(cb.message, f"📢 در حال ارسال به {n_users:,} نفر... (#{bc_id})", reply_markup=kb_cancel)
    await cb.answer()
    from tenant.shared.broadcast_runner import spawn as _bc_spawn
    _bc_spawn(bc_id)


@tenant_router.callback_query(F.data.startswith("bc:stop:"))
async def bc_stop(cb: CallbackQuery, bot: Bot):
    if not await _owner_ok(cb, bot):
        return
    bc_id = int(cb.data.split(":")[2])
    async with Session() as s:
        bc_row = await s.get(Broadcast, bc_id)
        if bc_row is not None and await _is_foreign(bc_row, bot):   # PATCH_TENANT_SCOPE_V1
            bc_row = None
        if bc_row and bc_row.status == "sending":
            bc_row.status = "cancelled"
            await s.commit()
    await cb.answer("ارسال لغو شد", show_alert=True)
    try:
        await cb.message.edit_reply_markup(reply_markup=None)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")


# ───── کدهای تخفیف ─────

# ═══════════════ PATCH_PAYMENT_GUIDE_BUTTON_V1 ═══════════════
# دکمهٔ «💰 راهنمای پرداخت و افزایش موجودی» که در صفحهٔ پیش‌فاکتور، بالایِ
# دکمهٔ بازگشت نشان داده می‌شود. متنش را مالک این‌جا می‌نویسد.
#
# متن با `html_text` ذخیره می‌شود نه `text`، تا بولد/ایتالیک/لینک/کد و
# بقیهٔ قالب‌بندی‌هایِ تلگرام حفظ شوند — چیزی که ادمین صریح خواسته بود.

class PayGuideFSM(StatesGroup):
    text = State()


async def _payguide_page(bot_id: int):
    on = await get_setting(bot_id, "payguide_on", "") == "1"
    invoice_on = await get_setting(bot_id, "payguide_show_invoice", "1") == "1"
    wallet_on = await get_setting(bot_id, "payguide_show_wallet", "0") == "1"
    txt = (await get_setting(bot_id, "payguide_text", "")).strip()
    body = (
        "💰 <b>راهنمای پرداخت و افزایش موجودی</b>\n\n"
        "این راهنما فقط وقتی برای کاربر نمایش داده می‌شود که متن ثبت شده و وضعیت اصلی روشن باشد.\n\n"
        f"وضعیت اصلی: <b>{'✅ روشن' if on else '❌ خاموش'}</b>\n"
        f"نمایش در فاکتور پرداخت: <b>{'✅ روشن' if invoice_on else '❌ خاموش'}</b>\n"
        f"نمایش در کیف پول: <b>{'✅ روشن' if wallet_on else '❌ خاموش'}</b>\n"
    )
    if txt:
        _prev = txt if len(txt) <= 600 else txt[:600] + "…"
        body += f"\n<b>متنِ فعلی:</b>\n{_prev}"
    else:
        body += ("\n<i>هنوز متنی ثبت نشده. تا وقتی متن نباشد، دکمه به کاربر "
                 "نشان داده نمی‌شود — حتی اگر روشن باشد.</i>")
    rows = [[InlineKeyboardButton(
        text=("🔴 خاموش کردن" if on else "🟢 روشن کردن"),
        callback_data="pg:toggle",
        style=(ButtonStyle.DANGER if on else ButtonStyle.SUCCESS))]]
    rows.append([InlineKeyboardButton(
        text=f"🧾 نمایش در فاکتور پرداخت: {'✅' if invoice_on else '❌'}",
        callback_data="pg:show_invoice",
        style=(ButtonStyle.SUCCESS if invoice_on else ButtonStyle.DANGER))])
    rows.append([InlineKeyboardButton(
        text=f"👛 نمایش در کیف پول: {'✅' if wallet_on else '❌'}",
        callback_data="pg:show_wallet",
        style=(ButtonStyle.SUCCESS if wallet_on else ButtonStyle.DANGER))])
    rows.append([InlineKeyboardButton(
        text=("✏️ ویرایشِ متن" if txt else "➕ نوشتنِ متن"),
        callback_data="pg:edit")])
    if txt:
        rows.append([InlineKeyboardButton(text="🗑 حذفِ متن", callback_data="pg:del",
                                          style=ButtonStyle.DANGER)])
    # === PATCH_PAYGUIDE_MOVE_FINANCE_PRO_V1 ===
    rows.append([InlineKeyboardButton(text="⬅️ بازگشت",
                                      callback_data="tadm:sec:finance",
                                      style=ButtonStyle.DANGER)])
    return body, InlineKeyboardMarkup(inline_keyboard=rows)


# === PATCH_PAYGUIDE_MOVE_FINANCE_PRO_V1 ===
@tenant_router.callback_query(F.data == "tadm:payguide")
async def tadm_payguide(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    if not has_feature(row.plan, Feature.PAYMENT_GUIDE):
        await cb.answer("⛔️ این قابلیت فقط در پلنِ حرفه‌ای فعال است.", show_alert=True)
        return
    txt, kb = await _payguide_page(row.id)
    try:
        await cb.message.edit_text(txt, reply_markup=kb, parse_mode="HTML")
    except Exception:
        await cb.message.answer(txt, reply_markup=kb, parse_mode="HTML")
    await cb.answer()


@tenant_router.callback_query(F.data.in_({"pg:toggle", "pg:del"}))
async def pg_action(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    # === PATCH_PAYGUIDE_MOVE_FINANCE_PRO_V1 ===
    if not has_feature(row.plan, Feature.PAYMENT_GUIDE):
        await cb.answer("⛔️ این قابلیت فقط در پلنِ حرفه‌ای فعال است.", show_alert=True)
        return
    if cb.data == "pg:toggle":
        cur = await get_setting(row.id, "payguide_on", "") == "1"
        await set_setting(row.id, "payguide_on", "" if cur else "1")
        note = "خاموش شد." if cur else "روشن شد."
        if not cur and not (await get_setting(row.id, "payguide_text", "")).strip():
            note = "روشن شد — ولی تا متن ننویسی به کاربر نشان داده نمی‌شود."
    else:
        await set_setting(row.id, "payguide_text", "")
        note = "متن حذف شد."
    txt, kb = await _payguide_page(row.id)
    try:
        await cb.message.edit_text(txt, reply_markup=kb, parse_mode="HTML")
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (رفرشِ صفحهٔ راهنمایِ پرداخت)")
    await cb.answer(note, show_alert=(cb.data == "pg:toggle"))


@tenant_router.callback_query(F.data.in_({"pg:show_invoice", "pg:show_wallet"}))
async def pg_visibility_toggle(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    if not has_feature(row.plan, Feature.PAYMENT_GUIDE):
        await cb.answer("⛔️ این قابلیت فقط در پلنِ حرفه‌ای فعال است.", show_alert=True)
        return
    key = "payguide_show_invoice" if cb.data == "pg:show_invoice" else "payguide_show_wallet"
    default = "1" if key == "payguide_show_invoice" else "0"
    current = await get_setting(row.id, key, default) == "1"
    await set_setting(row.id, key, "0" if current else "1")
    txt, kb = await _payguide_page(row.id)
    try:
        await cb.message.edit_text(txt, reply_markup=kb, parse_mode="HTML")
    except Exception:
        await cb.message.answer(txt, reply_markup=kb, parse_mode="HTML")
    label = "فاکتور پرداخت" if key == "payguide_show_invoice" else "کیف پول"
    await cb.answer(f"نمایش در {label} {'خاموش' if current else 'روشن'} شد.")


@tenant_router.callback_query(F.data == "pg:edit")
async def pg_edit_ask(cb: CallbackQuery, bot: Bot, state: FSMContext):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    # === PATCH_PAYGUIDE_MOVE_FINANCE_PRO_V1 ===
    if not has_feature(row.plan, Feature.PAYMENT_GUIDE):
        await cb.answer("⛔️ این قابلیت فقط در پلنِ حرفه‌ای فعال است.", show_alert=True)
        return
    await state.set_state(PayGuideFSM.text)
    await cb.message.answer(
        "✏️ متنِ راهنمایِ پرداخت را بفرست.\n\n"
        "هر قالب‌بندیِ تلگرام کار می‌کند: <b>بولد</b>، <i>ایتالیک</i>، "
        "<u>زیرخط</u>، <code>کد</code>، لینک و ایموجی — همان‌طور که در تلگرام "
        "می‌نویسی ذخیره می‌شود.\n\n"
        "<i>برایِ انصراف بنویس «لغو».</i>", parse_mode="HTML")
    await cb.answer()


@tenant_router.message(PayGuideFSM.text)
async def pg_edit_save(msg: Message, bot: Bot, state: FSMContext):
    # صفحهٔ ویرایش با _owner_ok برای مالک و ادمین باز می‌شود؛ ذخیره نیز باید
    # همان access control مشترک را استفاده کند، وگرنه ادمینِ فرعی متن را می‌فرستد
    # اما state بی‌صدا پاک می‌شود و منوی قبلی دوباره نمایش داده می‌شود.
    row = await _owner_ok_msg(msg, bot)
    if not row:
        await state.clear()
        return
    # === PATCH_PAYGUIDE_MOVE_FINANCE_PRO_V1 ===
    if not has_feature(row.plan, Feature.PAYMENT_GUIDE):
        await state.clear()
        await msg.answer("⛔️ این قابلیت فقط در پلنِ حرفه‌ای فعال است.")
        return
    if (msg.text or "").strip() in {"لغو", "❌ لغو", "انصراف", "بازگشت", "/cancel"}:
        await state.clear()
        await msg.answer("لغو شد.")
        return
    # html_text قالب‌بندی را حفظ می‌کند؛ text آن را دور می‌ریزد.
    body = (getattr(msg, "html_text", None) or msg.text or "").strip()
    if not body:
        await msg.answer("❌ متن خالی است. یک متن بفرست یا بنویس «لغو».")
        return
    if len(body) > 3500:
        await msg.answer("❌ متن خیلی بلند است (سقف حدود ۳۵۰۰ کاراکتر).")
        return
    await set_setting(row.id, "payguide_text", body)
    if (await get_setting(row.id, "payguide_on", "")) != "1":
        await set_setting(row.id, "payguide_on", "1")
    await state.clear()
    txt, kb = await _payguide_page(row.id)
    await msg.answer("✅ ثبت شد و دکمه روشن شد.")
    await msg.answer(txt, reply_markup=kb, parse_mode="HTML")


# ═══════════════ PATCH_FIRST_PURCHASE_DISCOUNT_V1 ═══════════════
# «تخفیفِ اولین خریدِ کاربر» — خودکار، بدونِ کد.
# مالک فقط درصد یا مبلغ می‌دهد؛ کاربر هیچ کدی وارد نمی‌کند و تخفیف در
# خلاصهٔ خرید خودش می‌نشیند — فقط رویِ نخستین خریدش از این ربات.

class FirstBuyFSM(StatesGroup):
    value = State()


# === PATCH_WELCOME_BONUS_V1 ===
class WelcomeBonusFSM(StatesGroup):
    value = State()


async def _welcomebonus_page(bot_id: int):
    on = await get_setting(bot_id, "welcome_bonus_on", "") == "1"
    val = await get_setting(bot_id, "welcome_bonus_amount", "0")
    txt = (
        "🎁 <b>هدیهٔ ورودِ کاربرانِ جدید</b>\n\n"
        "به هر کاربری که برایِ <b>اولین بار</b> رویِ این ربات /start بزنه "
        "(نه هر بار، فقط یک‌بار برایِ همیشه)، این مبلغ خودکار به کیف‌پولش "
        "اضافه می‌شه — بدونِ نیاز به کدِ دعوت یا خریدی.\n\n"
        f"وضعیت: <b>{'✅ روشن' if on else '❌ خاموش'}</b>\n"
        f"مبلغ: <b>{int(float(val or 0)):,} تومان</b>\n\n"   # PATCH_ADMIN_FSM_SAVE_V1 (مقدارِ اعشاری/خالی صفحه را نمی‌ترکاند)
        "<i>اگه ربات عضویتِ اجباری یا تاییدِ شماره داره، این هدیه فقط بعدِ "
        "قبولیِ اون‌ها داده می‌شه (ضدِ سوءاستفاده — استارتِ الکی هدیه "
        "نمی‌گیرد).</i>"
    )
    rows = [
        [InlineKeyboardButton(
            text=("🔴 خاموش کردن" if on else "🟢 روشن کردن"),
            callback_data="wcb:toggle",
            style=(ButtonStyle.DANGER if on else ButtonStyle.SUCCESS))],
        [InlineKeyboardButton(text="✏️ تنظیمِ مبلغ (تومان)", callback_data="wcb:val")],
        [InlineKeyboardButton(text="⬅️ بازگشت", callback_data="tadm:sec:finance",
                              style=ButtonStyle.DANGER)],
    ]
    return txt, InlineKeyboardMarkup(inline_keyboard=rows)


