@tenant_router.message(WelcomeBonusFSM.value, F.text)
async def wcb_save(msg: Message, bot: Bot, state: FSMContext):
    row = await get_bot_row(bot)
    if not row or not await is_owner_or_admin(row.id, msg.from_user.id, row.owner_id):  # PATCH_ADMIN_FSM_SAVE_V1
        await state.clear()
        return
    t = (msg.text or "").strip()
    if t in {"لغو", "❌ لغو", "انصراف", "بازگشت", "/cancel"}:
        await state.clear()
        await msg.answer("لغو شد.")
        return
    # === PATCH_ADMIN_FSM_SAVE_V1 === «5000 تومان» / «۵٬۰۰۰» هم پذیرفته شود
    _tn = t.translate(str.maketrans("۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩", "01234567890123456789"))
    _tn = _tn.replace(",", "").replace("،", "").replace("٬", "")
    _m = re.search(r"\d+", _tn)
    val = int(_m.group(0)) if _m else None
    if val is None or val < 0:
        await msg.answer("❌ عددِ معتبر بفرست (مثلاً 5000) یا بنویس «لغو».")
        return
    await set_setting(row.id, "welcome_bonus_amount", str(val))
    await state.clear()
    txt, kb = await _welcomebonus_page(row.id)
    await msg.answer("✅ ثبت شد.")
    await msg.answer(txt, reply_markup=kb, parse_mode="HTML")


async def _welcome_bonus_config(bot_id: int) -> tuple[bool, float]:
    """(روشن/خاموش, مبلغ) — یک‌جا برایِ صدا زدن از هندلرِ /start."""
    on = await get_setting(bot_id, "welcome_bonus_on", "") == "1"
    try:
        amt = float(await get_setting(bot_id, "welcome_bonus_amount", "0") or 0)
    except (TypeError, ValueError):
        amt = 0.0
    return on, amt


async def grant_welcome_bonus(bot: Bot, row, u) -> None:
    """اعطایِ هدیهٔ ورود به یک کاربرِ تازه‌ساخته‌شده — بی‌صدا از هر خطایی رد
    می‌شود، این جانبی‌ست و نباید خودِ /start را مختل کند."""
    try:
        on, amt = await _welcome_bonus_config(row.id)
        if not on or amt <= 0:
            return
        async with Session() as s:
            uu = await s.get(BotUser, u.id, with_for_update=True)
            if not uu:
                return
            uu.balance = float(uu.balance) + amt
            s.add(WalletTxn(bot_id=row.id, user_id=uu.id, amount=amt,
                            kind="welcome_bonus", note="هدیهٔ ورودِ کاربرِ جدید"))
            await s.commit()
        await bot.send_message(
            u.telegram_id,
            f"🎁 به‌عنوانِ هدیهٔ خوش‌آمد، <b>{int(amt):,} تومان</b> به کیف‌پولت اضافه شد!",
            parse_mode="HTML")
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (اعطایِ هدیهٔ ورودِ کاربرِ جدید)")


async def _firstbuy_page(bot_id: int):
    on = await get_setting(bot_id, "firstbuy_on", "") == "1"
    typ = await get_setting(bot_id, "firstbuy_type", "percent")
    val = await get_setting(bot_id, "firstbuy_value", "0")
    cap = await get_setting(bot_id, "firstbuy_max", "0")
    unit = "درصد" if typ == "percent" else "تومان"
    txt = (
        "🎁 <b>تخفیفِ اولین خریدِ کاربر</b>\n\n"
        "به هر کاربر، فقط در <b>نخستین خریدش از این ربات</b>، خودکار تخفیف "
        "می‌دهد. کاربر هیچ کدی وارد نمی‌کند — تخفیف خودش در صفحهٔ پرداخت "
        "نشان داده می‌شود.\n\n"
        f"وضعیت: <b>{'✅ روشن' if on else '❌ خاموش'}</b>\n"
        f"نوع: <b>{'درصدی' if typ == 'percent' else 'مبلغ ثابت'}</b>\n"
        f"مقدار: <b>{val} {unit}</b>\n"
    )
    if typ == "percent":
        txt += f"سقفِ تخفیف: <b>{'بی‌سقف' if cap in ('', '0') else cap + ' تومان'}</b>\n"
    txt += ("\n<i>کسی که قبلاً از این ربات خرید کرده باشد، این تخفیف را "
            "نمی‌گیرد.</i>")
    rows = [
        [InlineKeyboardButton(
            text=("🔴 خاموش کردن" if on else "🟢 روشن کردن"),
            callback_data="fb:toggle",
            style=(ButtonStyle.DANGER if on else ButtonStyle.SUCCESS))],
        [InlineKeyboardButton(
            text=("↔️ تغییر به مبلغِ ثابت" if typ == "percent"
                  else "↔️ تغییر به درصدی"),
            callback_data="fb:type")],
        [InlineKeyboardButton(text=f"✏️ تنظیمِ مقدار ({unit})",
                              callback_data="fb:val")],
    ]
    if typ == "percent":
        rows.append([InlineKeyboardButton(text="🧢 سقفِ تخفیف (تومان)",
                                          callback_data="fb:cap")])
    rows.append([InlineKeyboardButton(text="⬅️ بازگشت", callback_data="tadm:sec:finance",
                                      style=ButtonStyle.DANGER)])
    return txt, InlineKeyboardMarkup(inline_keyboard=rows)


