@tenant_router.callback_query(F.data.in_({"fb:toggle", "fb:type"}))
async def fb_toggle(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    if cb.data == "fb:toggle":
        cur = await get_setting(row.id, "firstbuy_on", "") == "1"
        await set_setting(row.id, "firstbuy_on", "" if cur else "1")
        note = "خاموش شد." if cur else "روشن شد."
    else:
        cur = await get_setting(row.id, "firstbuy_type", "percent")
        new = "amount" if cur == "percent" else "percent"
        await set_setting(row.id, "firstbuy_type", new)
        # مقدارِ قبلی با واحدِ تازه بی‌معنی است؛ صفر می‌شود تا اشتباهاً
        # «۲۰ تومان» به‌جایِ «۲۰ درصد» اعمال نشود.
        await set_setting(row.id, "firstbuy_value", "0")
        note = "نوع عوض شد؛ مقدار را دوباره تنظیم کن."
    txt, kb = await _firstbuy_page(row.id)
    try:
        await cb.message.edit_text(txt, reply_markup=kb, parse_mode="HTML")
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (رفرشِ صفحهٔ تخفیفِ اولین خرید)")
    await cb.answer(note)


@tenant_router.callback_query(F.data.in_({"fb:val", "fb:cap"}))
async def fb_ask(cb: CallbackQuery, bot: Bot, state: FSMContext):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    typ = await get_setting(row.id, "firstbuy_type", "percent")
    is_cap = cb.data == "fb:cap"
    await state.set_state(FirstBuyFSM.value)
    await state.update_data(fb_field="firstbuy_max" if is_cap else "firstbuy_value")
    if is_cap:
        q = ("🧢 سقفِ تخفیف را به تومان بفرست (مثلاً <code>50000</code>).\n"
             "<code>0</code> یعنی بی‌سقف.")
    elif typ == "percent":
        q = "✏️ درصدِ تخفیف را بفرست (عددی بین ۱ تا ۹۰، مثلاً <code>20</code>)."
    else:
        q = "✏️ مبلغِ تخفیف را به تومان بفرست (مثلاً <code>30000</code>)."
    await cb.message.answer(q + "\n\n<i>برایِ انصراف بنویس «لغو».</i>",
                            parse_mode="HTML")
    await cb.answer()


@tenant_router.message(FirstBuyFSM.value, F.text)
async def fb_save(msg: Message, bot: Bot, state: FSMContext):
    row = await get_bot_row(bot)
    if not row or not await is_owner_or_admin(row.id, msg.from_user.id, row.owner_id):  # PATCH_ADMIN_FSM_SAVE_V1
        await state.clear()
        return
    t = (msg.text or "").strip()
    if t in {"لغو", "❌ لغو", "انصراف", "بازگشت", "/cancel"}:
        await state.clear()
        await msg.answer("لغو شد.")
        return
    val = fa_to_int(t)
    if val is None or val < 0:
        await msg.answer("❌ عددِ معتبر بفرست یا بنویس «لغو».")
        return
    data = await state.get_data()
    field = data.get("fb_field", "firstbuy_value")
    typ = await get_setting(row.id, "firstbuy_type", "percent")
    if field == "firstbuy_value" and typ == "percent" and not (1 <= val <= 90):
        await msg.answer("❌ درصد باید بینِ ۱ تا ۹۰ باشد.")
        return
    await set_setting(row.id, field, str(val))
    await state.clear()
    txt, kb = await _firstbuy_page(row.id)
    await msg.answer("✅ ثبت شد.")
    await msg.answer(txt, reply_markup=kb, parse_mode="HTML")


