def _refdisc_text(bot_id_tiers: str | None, enabled: bool) -> str:
    from tenant.gateways.discount_engine import parse_referral_tiers
    tiers = parse_referral_tiers(bot_id_tiers)
    lines = ["🎁 <b>تخفیف پلکانیِ زیرمجموعه‌گیری</b>\n",
             "این تخفیف به‌صورت خودکار (بدون نیاز به کد) روی خرید VPN اعمال می‌شود؛ "
             "هرچه کاربر زیرمجموعهٔ بیشتری بیاورد، درصد تخفیف بالاتری می‌گیرد.\n",
             f"وضعیت: {'🟢 روشن' if enabled else '🔴 خاموش'}"]
    if tiers:
        lines.append("\n<b>پله‌های فعلی:</b>")
        for req, pct in tiers:
            lines.append(f"  • از <b>{req}</b> زیرمجموعه → <b>{pct}٪</b> تخفیف")
        lines.append("\n(کاربر بزرگ‌ترین پله‌ای که واجدش باشد را می‌گیرد.)")
    else:
        lines.append("\n<i>هنوز پله‌ای تعریف نشده.</i>")
    return "\n".join(lines)


async def _show_refdisc(msg, bot_id: int, edit: bool = False):
    raw = await get_setting(bot_id, "referral_disc_tiers", "")
    en = await get_setting(bot_id, "referral_disc_enabled", "1")
    enabled = en != "0"
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="✏️ تنظیم/ویرایش پله‌ها", callback_data="refdisc:set")],
        [InlineKeyboardButton(
            text="🔴 خاموش کردن" if enabled else "🟢 روشن کردن",
            callback_data="refdisc:toggle")],
        [InlineKeyboardButton(text="🗑 حذف همهٔ پله‌ها", callback_data="refdisc:clear")],
        [InlineKeyboardButton(text="⬅️ بازگشت", callback_data="tadm:discounts",
                              style=ButtonStyle.DANGER)],
    ])
    text = _refdisc_text(raw, enabled)
    if edit:
        try:
            await msg.edit_text(text, reply_markup=kb)
            return
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await msg.answer(text, reply_markup=kb)


