@tenant_router.callback_query(F.data == "refdisc:set")
async def refdisc_set_start(cb: CallbackQuery, bot: Bot, state: FSMContext):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    await state.set_state(AdminFSM.refdisc_tiers)
    await cb.message.answer(
        "✏️ پله‌های تخفیف را در یک پیام بفرست.\n\n"
        "هر پله به شکل <code>تعدادِ‌زیرمجموعه:درصد</code> و پله‌ها با کاما جدا شوند.\n\n"
        "مثال:\n<code>3:5, 10:10, 20:20</code>\n\n"
        "یعنی: ۳ زیرمجموعه → ۵٪، ۱۰ زیرمجموعه → ۱۰٪، ۲۰ زیرمجموعه → ۲۰٪.\n"
        "(درصد بین ۱ تا ۱۰۰)",
        reply_markup=await smart_cancel_kb(bot))
    await cb.answer()


@tenant_router.message(AdminFSM.refdisc_tiers, F.text)
async def refdisc_set_save(msg: Message, state: FSMContext, bot: Bot):
    if msg.text and msg.text.strip() in ("لغو", "انصراف", "/cancel"):
        await state.clear()
        row = await get_bot_row(bot)
        if row:
            await _show_refdisc(msg, row.id)
        return
    from tenant.gateways.discount_engine import parse_referral_tiers, format_referral_tiers
    tiers = parse_referral_tiers(msg.text)
    if not tiers:
        await msg.answer(
            "هیچ پلهٔ معتبری پیدا نشد. نمونهٔ درست:\n<code>3:5, 10:10, 20:20</code>",
            reply_markup=await smart_cancel_kb(bot))
        return
    row = await get_bot_row(bot)
    if not row:
        await state.clear()
        return
    await set_setting(row.id, "referral_disc_tiers", format_referral_tiers(tiers))
    await set_setting(row.id, "referral_disc_enabled", "1")
    await state.clear()
    summary = "، ".join(f"{req} نفر→{pct}٪" for req, pct in tiers)
    await msg.answer(f"✅ پله‌ها ذخیره و فعال شد:\n{summary}")
    await _show_refdisc(msg, row.id)


async def _show_discounts(msg, bot_id: int, edit: bool = False):
    """نمایش لیست کامل کدهای تخفیف با دکمه‌های مدیریت."""
    from datetime import datetime
    async with Session() as s:
        codes = (await s.scalars(
            select(DiscountCode).where(DiscountCode.bot_id == bot_id)
            .order_by(DiscountCode.id.desc())
        )).all()
        # === PATCH_PARTNER_DISCOUNT_V1 ===
        # همکار به بخشِ «مالی» دسترسی ندارد و از «تنظیمات عمومی» وارد
        # می‌شود؛ بازگشت باید به همان‌جا باشد وگرنه به صفحه‌ای می‌رسد
        # که برایش وجود ندارد.
        _brow = await s.get(BotRow, bot_id)
    _back_cb = ("set:hub_general" if _brow and _brow.plan == "partner"
                else "tadm:sec:finance")

    rows_kb = []
    rows_kb.append([InlineKeyboardButton(
        text="➕ افزودن کد تخفیف جدید", callback_data="disc:add",
        style=ButtonStyle.PRIMARY)])
    rows_kb.append([InlineKeyboardButton(
        text="🎁 تخفیف پلکانیِ زیرمجموعه‌گیری", callback_data="refdisc:menu")])

    lines = ["🏷 <b>کدهای تخفیف</b>\n"]
    if not codes:
        lines.append("هنوز کدی تعریف نشده.")
    else:
        now = datetime.utcnow()
        for c in codes:
            # وضعیت
            if not c.is_active:
                status = "🔴"
            elif c.expires_at and c.expires_at < now:
                status = "⌛️"
            else:
                status = "🟢"
            # نوع تخفیف
            if c.disc_type == "amount":
                disc_disp = f"{int(c.amount):,} تومان"
            else:
                disc_disp = f"{c.percent}٪"
            # تعداد استفاده
            uses = f"{c.used_count}/{c.max_uses}" if c.max_uses else f"{c.used_count}/∞"
            # انقضا
            exp = _fmt_exp_jalali(c.expires_at, with_time=False) if c.expires_at else "—"
            # پنل مخصوص (اگر تنظیم شده)
            panel_line = ""
            if c.panel_key:
                from tenant.bots.vpn.vpn_admin import PANEL_LABELS
                panel_line = f"\n   🛰 مخصوصِ: {PANEL_LABELS.get(c.panel_key, c.panel_key)}"
            # === PATCH_VS_DISCOUNT_V1 ===
            if getattr(c, "product_keys", None):
                panel_line += f"\n   📦 دسته‌ها: {_vsd_keys_label(c.product_keys)}"

            lines.append(
                f"{status} <code>{c.code}</code> — {disc_disp}\n"
                f"   استفاده: {uses}  |  انقضا: {exp}{panel_line}"
            )
            rows_kb.append([
                InlineKeyboardButton(
                    text=f"✏️ {c.code}", callback_data=f"disc:edit:{c.id}", style=ButtonStyle.PRIMARY),
                InlineKeyboardButton(
                    text="🔴 غیرفعال" if c.is_active else "🟢 فعال",
                    callback_data=f"disc:tog:{c.id}", style=ButtonStyle.DANGER),
                InlineKeyboardButton(
                    text="🗑", callback_data=f"disc:del:{c.id}", style=ButtonStyle.DANGER),
            ])

    rows_kb.append([InlineKeyboardButton(
        text="⬅️ بازگشت", callback_data=_back_cb,
        style=ButtonStyle.DANGER)])

    kb = InlineKeyboardMarkup(inline_keyboard=rows_kb)
    text = "\n".join(lines)
    if edit:
        try:
            await msg.edit_text(text, reply_markup=kb)
            return
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await msg.answer(text, reply_markup=kb)


# ── منوی ویرایش یک کد خاص ──

def _disc_edit_kb(dc_id: int, dc=None) -> InlineKeyboardMarkup:
    # === PATCH_PARTNER_DISCOUNT_V1 ===
    # «اختصاص به کاربر» و «حداقلِ مبلغِ خرید» در مدل از قبل بودند و در
    # موتورِ تخفیف هم اعمال می‌شدند، ولی از این پنل قابلِ تنظیم نبودند —
    # فقط از پنلِ کدِ اختصاصیِ دکمه. حالا اینجا هم هست.
    rows = [
        [InlineKeyboardButton(text="✏️ تغییر کد", callback_data=f"disc:edit:code:{dc_id}", style=ButtonStyle.PRIMARY),
         InlineKeyboardButton(text="💯 تغییر مقدار تخفیف", callback_data=f"disc:edit:pct:{dc_id}", style=ButtonStyle.PRIMARY)],
        [InlineKeyboardButton(text="🔢 تعداد مجاز استفاده", callback_data=f"disc:edit:uses:{dc_id}", style=ButtonStyle.PRIMARY),
         InlineKeyboardButton(text="📅 تاریخ انقضا", callback_data=f"disc:edit:expire:{dc_id}", style=ButtonStyle.PRIMARY)],
        [InlineKeyboardButton(text="👤 اختصاص به یک کاربر خاص", callback_data=f"disc:edit:user:{dc_id}",
                              style=ButtonStyle.PRIMARY)],
    ]
    if dc is not None and getattr(dc, "restricted_user_id", None):
        rows.append([InlineKeyboardButton(text="♻️ باز کردن برای همه",
                                          callback_data=f"disc:user:clear:{dc_id}", style=ButtonStyle.DANGER)])
    rows.append([InlineKeyboardButton(text="🧾 حداقلِ مبلغ خرید", callback_data=f"disc:edit:min:{dc_id}",
                                      style=ButtonStyle.PRIMARY)])
    # === PATCH_VS_DISCOUNT_V1 === محدود کردن به دسته‌هایِ محصولِ خدمات مجازی (خالی = همه)
    rows.append([InlineKeyboardButton(text="📦 دسته‌هایِ محصول (استارز/تون/گیفت/…)",
                                      callback_data=f"disc:prod:{dc_id}", style=ButtonStyle.PRIMARY)])
    if dc is not None and getattr(dc, "expires_at", None):
        rows.append([InlineKeyboardButton(text="♾️ حذف انقضا",
                                          callback_data=f"disc:expire:clear:{dc_id}", style=ButtonStyle.DANGER)])
    rows += [
        [InlineKeyboardButton(text="🔄 ریست تعداد استفاده", callback_data=f"disc:edit:resetuses:{dc_id}", style=ButtonStyle.SUCCESS)],
        [InlineKeyboardButton(text="🗑 حذف این کد", callback_data=f"disc:del:{dc_id}",
                              style=ButtonStyle.DANGER)],
        [InlineKeyboardButton(text="⬅️ بازگشت به لیست", callback_data="tadm:discounts", style=ButtonStyle.DANGER)],
    ]
    return InlineKeyboardMarkup(inline_keyboard=rows)


def _vsd_keys_label(raw) -> str:
    """PATCH_VS_DISCOUNT_V1 — برچسبِ دسته‌هایِ محصولِ یک کدِ تخفیف («همهٔ محصولات» اگر خالی)."""
    from tenant.bots.virtual_service.vs_discount import keys_label
    return keys_label(raw)


async def _disc_detail_text(dc) -> str:
    from datetime import datetime
    disc_disp = f"{int(dc.amount):,} تومان (مبلغ ثابت)" if dc.disc_type == "amount" else f"{dc.percent}٪"
    uses = f"{dc.used_count} از {dc.max_uses}" if dc.max_uses else f"{dc.used_count} (نامحدود)"
    exp = _fmt_exp_jalali(dc.expires_at) if dc.expires_at else "ندارد"
    status = "🟢 فعال" if dc.is_active else "🔴 غیرفعال"
    now = datetime.utcnow()
    if dc.expires_at and dc.expires_at < now:
        status = "⌛️ منقضی‌شده"
    # === PATCH_PARTNER_DISCOUNT_V1 ===
    user_disp = (f"<code>{dc.restricted_user_id}</code>"
                 if getattr(dc, "restricted_user_id", None) else "برای همه")
    try:
        _min = int(round(float(dc.min_amount or 0)))
    except (TypeError, ValueError):
        _min = 0
    min_disp = f"{_min:,} تومان" if _min else "ندارد"
    return (
        f"🏷 <b>کد تخفیف: <code>{dc.code}</code></b>\n\n"
        f"وضعیت: {status}\n"
        f"مقدار تخفیف: {disc_disp}\n"
        f"تعداد استفاده: {uses}\n"
        f"انقضا (شمسی): {exp}\n"
        f"اختصاص به کاربر: {user_disp}\n"
        f"حداقلِ مبلغ خرید: {min_disp}\n"
        f"📦 دسته‌هایِ محصول: {_vsd_keys_label(getattr(dc, 'product_keys', None))}\n\n"
        "از دکمه‌های زیر ویرایش کن:"
    )


# === PATCH_PARTNER_DISCOUNT_V1 === دو مسیرِ جدید هم باید از فیلترِ عمومی
# کنار گذاشته شوند، وگرنه هندلرِ «نمایشِ جزئیات» آن‌ها را می‌بلعد.
@tenant_router.callback_query(F.data.startswith("disc:edit:") & ~F.data.startswith("disc:edit:code:") &
                               ~F.data.startswith("disc:edit:pct:") & ~F.data.startswith("disc:edit:uses:") &
                               ~F.data.startswith("disc:edit:expire:") & ~F.data.startswith("disc:edit:resetuses:") &
                               ~F.data.startswith("disc:edit:user:") & ~F.data.startswith("disc:edit:min:"))
async def disc_edit_menu(cb: CallbackQuery, bot: Bot):
    if not await _owner_ok(cb, bot):
        return
    dc_id = int(cb.data.split(":")[2])
    async with Session() as s:
        dc = await s.get(DiscountCode, dc_id)
        if dc is not None and await _is_foreign(dc, bot):   # PATCH_TENANT_SCOPE_V1
            dc = None
    if not dc:
        await cb.answer("کد یافت نشد", show_alert=True)
        return
    text = await _disc_detail_text(dc)
    try:
        await cb.message.edit_text(text, reply_markup=_disc_edit_kb(dc_id, dc))
    except Exception:
        await cb.message.answer(text, reply_markup=_disc_edit_kb(dc_id, dc))
    await cb.answer()


# === PATCH_PARTNER_DISCOUNT_V1 ===
@tenant_router.callback_query(F.data.startswith("disc:edit:user:"))
async def disc_edit_user(cb: CallbackQuery, bot: Bot, state: FSMContext):
    """اختصاصِ کد به یک کاربرِ خاص (آی‌دیِ عددیِ تلگرام)."""
    row = await _owner_ok(cb, bot)
    if not row:
        return
    dc_id = int(cb.data.split(":")[3])
    await state.set_state(AdminFSM.discount_edit_user)
    await state.update_data(dc_id=dc_id)
    await cb.message.answer(
        "👤 <b>اختصاص کد به یک کاربر</b>\n\n"
        "آی‌دیِ عددیِ تلگرامِ کاربر را بفرست؛ از آن پس فقط همان کاربر "
        "می‌تواند این کد را استفاده کند.\n\n"
        "برای برداشتنِ محدودیت عدد <code>0</code> را بفرست.",
        reply_markup=await smart_cancel_kb(bot))
    await cb.answer()


@tenant_router.message(AdminFSM.discount_edit_user)
async def disc_edit_user_save(msg: Message, bot: Bot, state: FSMContext):
    row = await get_bot_row(bot)
    if not row or not await is_owner_or_admin(row.id, msg.from_user.id, row.owner_id):
        await state.clear()
        return
    raw = (msg.text or "").strip()
    if raw in ("❌ لغو", "لغو"):
        # === PATCH_CANCEL_BUTTONS_SHOW_MENU_V1 ===
        # قبلاً فقط «لغو شد.» می‌گفت، بدونِ هیچ دکمه‌ای — ادمین می‌موند
        # بدونِ راهی برایِ ادامه. حالا حداقل یه دکمه‌ی بازگشت‌به‌خونه داره.
        await state.clear()
        await msg.answer("لغو شد.", reply_markup=await inline_back_kb(row.id))
        return
    uid = fa_to_int(raw)
    if uid is None or uid < 0:
        await msg.answer("آی‌دی نامعتبر است. فقط عدد بفرست (یا 0 برای حذفِ محدودیت):")
        return
    data = await state.get_data()
    dc_id = data.get("dc_id")
    await state.clear()
    async with Session() as s:
        dc = await s.get(DiscountCode, dc_id)
        if not dc or dc.bot_id != row.id:
            await msg.answer("کد یافت نشد.")
            return
        dc.restricted_user_id = int(uid) or None
        await s.commit()
        await s.refresh(dc)
        txt = await _disc_detail_text(dc)
        kb = _disc_edit_kb(dc.id, dc)
    await msg.answer(
        ("✅ محدودیتِ کاربر برداشته شد؛ کد برای همه معتبر است."
         if not uid else f"✅ کد فقط برایِ کاربر <code>{uid}</code> معتبر شد."))
    await msg.answer(txt, reply_markup=kb)


