@tenant_router.callback_query(F.data.startswith("disc:edit:resetuses:"))
async def disc_edit_resetuses(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    dc_id = int(cb.data.split(":")[3])
    async with Session() as s:
        dc = await s.get(DiscountCode, dc_id)
        if dc and dc.bot_id == row.id:
            dc.used_count = 0
            # حذف همه DiscountUsage مربوطه
            usages = (await s.scalars(
                select(DiscountUsage).where(DiscountUsage.discount_code_id == dc_id)
            )).all()
            for u in usages:
                await s.delete(u)
            await s.commit()
    await cb.answer("✅ تعداد استفاده ریست شد", show_alert=True)
    async with Session() as s:
        dc = await s.get(DiscountCode, dc_id)
    text = await _disc_detail_text(dc)
    try:
        await cb.message.edit_text(text, reply_markup=_disc_edit_kb(dc_id, dc))
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")


