@tenant_router.message(AdminFSM.discount_edit_code, F.text)
async def disc_edit_code_save(msg: Message, bot: Bot, state: FSMContext):
    row = await get_bot_row(bot)
    if not row or not await is_owner_or_admin(row.id, msg.from_user.id, row.owner_id):  # PATCH_ADMIN_FSM_SAVE_V1
        return
    data = await state.get_data()
    new_code = msg.text.strip().upper()
    if not new_code or len(new_code) > 40:
        await msg.answer("کد نامعتبر. دوباره وارد کن:", reply_markup=await smart_cancel_kb(bot))
        return
    dc_id = data["edit_dc_id"]
    async with Session() as s:
        dc = await s.get(DiscountCode, dc_id)
        if dc and dc.bot_id == row.id:
            dc.code = new_code
            await s.commit()
    await state.clear()
    async with Session() as s:
        dc = await s.get(DiscountCode, dc_id)
    await msg.answer(f"✅ کد به <code>{new_code}</code> تغییر یافت.",
                     reply_markup=_disc_edit_kb(dc_id))


