@tenant_router.callback_query(F.data.startswith("disc:pcttype:"))
async def disc_pcttype_pick(cb: CallbackQuery, bot: Bot, state: FSMContext):
    if not await _owner_ok(cb, bot):
        return
    parts = cb.data.split(":")
    disc_type = parts[2]
