@tenant_router.message(AdminFSM.discount_edit_expire, F.text)
async def disc_edit_expire_save(msg: Message, bot: Bot, state: FSMContext):
    data = await state.get_data()
    # این حالت (discount_edit_expire) هم برای «ویرایش» و هم برای «ساخت جدید»
    # استفاده می‌شود. اگر edit_dc_id در state نبود، یعنی مسیر ساختِ کد جدید است
    # و باید هندلر ساخت (disc_new_expire_enter) اجرا شود؛ نه این.
    if not data.get("edit_dc_id"):
        await disc_new_expire_enter(msg, state, bot)
        return
    row = await get_bot_row(bot)
    if not row or not await is_owner_or_admin(row.id, msg.from_user.id, row.owner_id):  # PATCH_ADMIN_FSM_SAVE_V1
        return
    raw = msg.text.strip()
    exp_dt = _parse_exp_jalali(raw)
    if exp_dt is None:
        await msg.answer(
            "فرمت نامعتبر. لطفاً به این شکل (شمسی) وارد کن:\n<code>YYYY-MM-DD</code> مثال: <code>1404-10-15</code>",
            reply_markup=await smart_cancel_kb(bot))
        return
