@tenant_router.message(AdminFSM.discount_code_add, F.text)
async def disc_code_enter(msg: Message, state: FSMContext, bot: Bot):
    code = msg.text.strip().upper()
    if not code or len(code) > 40:
        await msg.answer("کد نامعتبر. دوباره وارد کن:", reply_markup=await smart_cancel_kb(bot))
        return
    # === PATCH_DISC_DUPLICATE_CODE_GUARD_V1 ===
    # قبلاً اینجا هیچ چکِ تکراری‌بودن نبود — برخلافِ مسیرِ کدِ اختصاصیِ
    # دکمه (disc:newpanel) که از قبل این چک را داشت. نتیجه: می‌شد دوبار
    # همان متنِ کد را برایِ همین ربات ساخت. چون DiscountCode.code هیچ
    # قیدِ یکتاییِ دیتابیسی ندارد، دو ردیف با یک متن ساخته می‌شد و
    # validate_discount (که فقط اولین ردیف را برمی‌دارد) گاهی به ردیفِ
    # قدیمی‌تر می‌خورد — همان که ممکن است سقفِ مصرف یا وضعیتِ متفاوتی
    # داشته باشد. هم‌زمان، حذفِ یکی از این دو ردیف از پنل، آن یکیِ دیگر
    # را دست‌نخورده باقی می‌گذاشت و کد هم‌چنان کار می‌کرد — دقیقاً همان
    # رفتارِ «هر کاری می‌کنم حذف نمی‌شه» که گزارش شد.
    row = await get_bot_row(bot)
    if row:
        async with Session() as s:
            dup = await s.scalar(select(DiscountCode).where(
                DiscountCode.bot_id == row.id, func.upper(DiscountCode.code) == code))
        if dup:
            await msg.answer(
                "⚠️ این کد قبلاً برای این ربات ثبت شده (حتی اگه غیرفعالش کرده باشی).\n"
                "یه کدِ دیگه بفرست، یا اول کدِ قبلی رو از لیستِ «کدهای تخفیف» حذف کن:",
                reply_markup=await smart_cancel_kb(bot))
            return
    await state.update_data(new_disc_code=code)
    await state.set_state(AdminFSM.discount_pct)
    type_kb = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="💯 درصدی (مثل 20٪)", callback_data="disc:newtype:percent", style=ButtonStyle.PRIMARY)],
        [InlineKeyboardButton(text="💵 مبلغ ثابت (تومان)", callback_data="disc:newtype:amount", style=ButtonStyle.PRIMARY)],
        [InlineKeyboardButton(text="❌ لغو", callback_data="disc:cancel_edit", style=ButtonStyle.DANGER)],
    ])
    await msg.answer(f"✅ کد: <code>{code}</code>\n\nنوع تخفیف را انتخاب کن:", reply_markup=type_kb)


