@tenant_router.message(AdminFSM.discount_uses, F.text)
async def disc_uses_enter(msg: Message, state: FSMContext, bot: Bot):
    data = await state.get_data()
    # اگر مرحله بعد از amount هستیم
    if data.get("_next_after_amount") == "uses":
        amt = fa_to_int(msg.text)
        if amt is None or amt <= 0:
            await msg.answer("مبلغ نامعتبر:", reply_markup=await smart_cancel_kb(bot))
            return
        await state.update_data(new_disc_amount=amt, new_disc_pct=0, _next_after_amount=None)
        await state.set_state(AdminFSM.discount_uses)
        await msg.answer("🔢 حداکثر تعداد استفاده (۰ = نامحدود):")
        return

    uses = fa_to_int(msg.text)
    if uses is None or uses < 0 or uses > MAX_USES:
        await msg.answer(f"عدد نامعتبر (۰ تا {MAX_USES:,}):", reply_markup=await smart_cancel_kb(bot))
        return
    await state.update_data(new_disc_uses=uses)

    # اگر بیش از یک پنل VPN وصل است، بپرس این کد فقط برای کدوم پنل باشد
    row = await get_bot_row(bot)
    panels = []
    if row:
        from tenant.bots.vpn.vpn_admin import get_all_panels, PANEL_LABELS
        panels = await get_all_panels(row.id)
    if len(panels) >= 2:
        await state.set_state(AdminFSM.discount_panel)
        rows = [[InlineKeyboardButton(text="🌐 همهٔ پنل‌ها", callback_data="disc:newpanel:", style=ButtonStyle.PRIMARY)]]
        for p in panels:
            lbl = PANEL_LABELS.get(p.panel_key, p.panel_key)
            rows.append([InlineKeyboardButton(text=lbl, callback_data=f"disc:newpanel:{p.panel_key}", style=ButtonStyle.PRIMARY)])
        await msg.answer(
            "🛰 این کد تخفیف فقط برای کدام پنل معتبر باشد؟\n"
            "(اگه می‌خوای رو همهٔ پنل‌ها کار کنه، «🌐 همهٔ پنل‌ها» رو بزن)",
            reply_markup=InlineKeyboardMarkup(inline_keyboard=rows))
        return

    await state.update_data(new_disc_panel_key=None)
    await _ask_discount_expiry(msg, state)


