async def _save_new_discount(msg, state: FSMContext, bot: Bot):
    from datetime import datetime
    row = await get_bot_row(bot)
    if not row:
        await state.clear()
        return
    data = await state.get_data()
    code = data.get("new_disc_code", "")
    pct = data.get("new_disc_pct", 0)
    amt = data.get("new_disc_amount", 0)
    uses = data.get("new_disc_uses", 0)
    disc_type = data.get("new_disc_type", "percent")
    expire_raw = data.get("new_disc_expire")
    panel_key = data.get("new_disc_panel_key")
    exp_dt = datetime.fromisoformat(expire_raw) if expire_raw else None
    await state.clear()

    async with Session() as s:
        s.add(DiscountCode(
            bot_id=row.id, code=code,
            percent=pct, disc_type=disc_type, amount=amt,
            max_uses=uses, expires_at=exp_dt, panel_key=panel_key,
        ))
        await s.commit()

    disc_disp = f"{int(amt):,} تومان" if disc_type == "amount" else f"{pct}٪"
    exp_disp = _fmt_exp_jalali(exp_dt, with_time=False) if exp_dt else "ندارد"
    uses_disp = "نامحدود" if uses == 0 else str(uses)
    panel_disp = "همهٔ پنل‌ها"
    if panel_key:
        from tenant.bots.vpn.vpn_admin import PANEL_LABELS
        panel_disp = PANEL_LABELS.get(panel_key, panel_key)
    await msg.answer(
        f"✅ کد تخفیف ساخته شد!\n\n"
        f"کد: <code>{code}</code>\n"
        f"تخفیف: {disc_disp}\n"
        f"حداکثر استفاده: {uses_disp}\n"
        f"مخصوصِ: {panel_disp}\n"
        f"انقضا: {exp_disp}",
        reply_markup=InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text="📋 بازگشت به لیست کدها", callback_data="tadm:discounts", style=ButtonStyle.DANGER)],
        ])
    )


