@tenant_router.callback_query(F.data.startswith("disc:del:"))
async def disc_delete(cb: CallbackQuery, bot: Bot):
    # === MARKER_DISC_DELETE_FK_V1 ===
    # قبلاً اگر این کد حتی یک‌بار در فروشگاه استفاده شده بود، حذف با
    # IntegrityError (نقضِ FK از ProductOrder.discount_code_id) شکست
    # می‌خورد و بی‌صدا هیچ اتفاقی نمی‌افتاد — دقیقاً همان کدهایی که
    # ادمین معمولاً می‌خواهد پاک کند. حالا قبل از حذفِ خودِ کد، آن
    # اشاره‌گر را روی سفارش‌های مرتبط NULL می‌کنیم (سفارش‌ها و گزارشِ
    # فروش دست‌نخورده می‌مانند).
    from tenant.bots.digital_shop.handlers import ProductOrder  # === PATCH_TENANT_SPLIT_PHASE3_DIGITAL_SHOP_V1 === (قبلاً tenant/shop.py)
    row = await _owner_ok(cb, bot)
    if not row:
        return
    cid = int(cb.data.split(":")[2])
    async with Session() as s:
        dc = await s.get(DiscountCode, cid)
        if dc and dc.bot_id == row.id:
            # حذف usageها هم
            usages = (await s.scalars(
                select(DiscountUsage).where(DiscountUsage.discount_code_id == cid)
            )).all()
            for u in usages:
                await s.delete(u)
            # MARKER_DISC_DELETE_FK_V1: باز کردنِ FK سفارش‌هایِ فروشگاه قبل از حذفِ کد
            orders = (await s.scalars(
                select(ProductOrder).where(ProductOrder.discount_code_id == cid)
            )).all()
            for o in orders:
                o.discount_code_id = None
            try:
                await s.delete(dc)
                await s.commit()
            except Exception:
                await s.rollback()
                logger.exception("حذفِ کد تخفیف ناموفق بود (id=%s)", cid)
                await cb.answer("❌ حذف ناموفق بود؛ دوباره امتحان کن.", show_alert=True)
                return
    await cb.answer("🗑 کد حذف شد")
    await _show_discounts(cb.message, row.id, edit=True)


# ───── عضویت اجباری ─────

async def _parse_channel(raw: str, bot: Bot):
    """از یوزرنیم/آیدی/لینک، (chat_id, title, invite_link, err) را استخراج می‌کند.

    === PATCH_FORCEJOIN_HEALTH_V1 ===
    قبلاً این تابع هر ورودی‌ای را بی‌چون‌وچرا قبول می‌کرد: اگر ربات به کانال
    دسترسی نداشت یا ادمینش نبود، `get_chat` خطا می‌داد، خطا بی‌صدا بلعیده
    می‌شد و کانال با عنوانِ خامِ خودش ذخیره می‌شد. نتیجه: مالک فکر می‌کرد
    عضویتِ اجباری فعال است، ولی چون بررسیِ عضویت هرگز موفق نمی‌شد،
    `check_force_join` (به‌درستی، برایِ قفل‌نشدنِ کاربرها) همه را رد می‌کرد و
    گیت عملاً وجود نداشت. حالا همان‌جا سرِ افزودن تشخیص داده و به مالک گفته
    می‌شود، به‌علاوهٔ اینکه برایِ کانالِ خصوصی یک لینکِ دعوتِ واقعی ساخته
    می‌شود (قبلاً `invite_link` تقریباً همیشه None بود و لینکِ دکمه خراب درمی‌آمد).

    err: None یعنی همه‌چیز سالم است؛ در غیر این صورت یک متنِ فارسیِ آماده.
    """
    raw = raw.strip()
    if "t.me/" in raw:
        username = raw.split("t.me/")[-1].strip("/").split("/")[0]
        chat_id = f"@{username}" if not username.startswith("@") else username
    elif raw.startswith("@") or raw.lstrip("-").isdigit():
        chat_id = raw
    else:
        chat_id = f"@{raw}"
    title = chat_id
    invite_link = None

    try:
        chat = await bot.get_chat(chat_id)
    except Exception as e:
        logger.warning("force-join: get_chat برایِ %s ناموفق بود: %s", chat_id, e)
        return chat_id, title, invite_link, (
            "⚠️ ربات به این کانال/گروه دسترسی ندارد. اول ربات را در آن‌جا "
            "ادمین کن، بعد دوباره اضافه‌اش کن — وگرنه عضویت اجباری کار نمی‌کند "
            "و همهٔ کاربران بدون عضویت رد می‌شوند.")

    title = chat.title or chat.username or chat_id
    if getattr(chat, "username", None):
        invite_link = f"https://t.me/{chat.username}"
    else:
        invite_link = chat.invite_link

    # ربات باید ادمین باشد، وگرنه get_chat_member هرگز جواب نمی‌دهد.
    err = None
    try:
        me = await bot.me()
        my_member = await bot.get_chat_member(chat.id, me.id)
        if my_member.status not in ("administrator", "creator"):
            err = ("⚠️ ربات در این کانال/گروه ادمین نیست، پس نمی‌تواند عضویت را "
                   "بررسی کند. تا وقتی ادمینش نکنی، این مورد نادیده گرفته می‌شود.")
    except Exception as e:
        logger.warning("force-join: بررسیِ ادمین‌بودنِ ربات در %s ناموفق: %s", chat_id, e)
        err = ("⚠️ نتوانستم بررسی کنم که ربات در این کانال/گروه ادمین است یا نه. "
               "اگر ادمین نباشد، عضویت اجباری برایش کار نمی‌کند.")

    if not invite_link and err is None:
        # کانالِ خصوصیِ سالم — یک لینکِ دعوتِ اختصاصی بساز تا دکمهٔ کاربر واقعاً کار کند.
        try:
            _lnk = await bot.create_chat_invite_link(chat.id, name="عضویت اجباری")
            invite_link = _lnk.invite_link
        except Exception as e:
            logger.warning("force-join: ساختِ لینکِ دعوت برایِ %s ناموفق: %s", chat_id, e)
            err = ("⚠️ این کانال/گروه خصوصی است و نتوانستم لینکِ دعوت بسازم "
                   "(دسترسیِ «دعوت کاربران» را به ربات بده)، پس دکمهٔ عضویت "
                   "ممکن است برای کاربر باز نشود.")

    # شناسهٔ عددی پایدارتر از یوزرنیم است (یوزرنیم قابلِ تغییر است و بعدِ
    # تغییر، بررسیِ عضویت بی‌صدا می‌شکست).
    chat_id = str(chat.id)
    return chat_id, title, invite_link, err


# === PATCH_FJ_TEXT_NAV_FIX_V1 ===
async def _fj_hub_kb(bot_id: int, plan: str) -> InlineKeyboardMarkup:
    """کیبوردِ مشترکِ هابِ «عضویتِ اجباری» — تا همه‌جا (نمایشِ هاب، بعدِ
    افزودنِ کانال، بعدِ ذخیرهٔ متن) دقیقاً یک صفحه ساخته شود و ناوبری
    گم نشود."""
    async with Session() as s:
        fjs = (await s.scalars(select(ForceJoin).where(ForceJoin.bot_id == bot_id))).all()
    rows_kb = []
    for fj in fjs:
        # === PATCH_FORCEJOIN_HEALTH_V1 ===
        # کانالی که بررسیِ عضویتش شکست خورده با ⚠️ مشخص می‌شود تا مالک
        # بفهمد چرا گیتش عملاً کار نمی‌کند (قبلاً کاملاً بی‌صدا بود).
        if fj.is_active and _FORCEJOIN_BROKEN.get((bot_id, fj.chat_id)):
            st = "⚠️"
        else:
            st = "🟢" if fj.is_active else "🔴"
        rows_kb.append([InlineKeyboardButton(
            text=f"{st} {fj.title or fj.chat_id}",
            callback_data=f"fj:view:{fj.id}"
        )])
    rows_kb.append([InlineKeyboardButton(text="➕ افزودن کانال", callback_data="fj:add")])
    if fjs:      # === PATCH_FJ_TEST_MODE_V1 ===
        _tm = (await get_setting(bot_id, "fj_test_mode", "0")) == "1"
        rows_kb.append([InlineKeyboardButton(text="🧪 بررسیِ وضعیتِ کانال‌ها و عضویتِ من", callback_data="fj:diag",
                                             style=ButtonStyle.PRIMARY)])
        rows_kb.append([InlineKeyboardButton(
            text=("🧪 حالتِ تست: ✅ روشن (مالک/ادمین هم عضویت را می‌بینند)" if _tm
                  else "🧪 حالتِ تست: ⛔️ خاموش (مالک/ادمین معاف‌اند)"),
            callback_data="fj:testmode", style=(ButtonStyle.SUCCESS if _tm else ButtonStyle.DANGER))])
    # === PATCH_TRUST_TEXT_PRO_ONLY_V1 ===
    # ویرایشِ متن فقط در پلنِ حرفه‌ای (و رباتِ همکار)؛ رایگان و رشد متنِ
    # پیش‌فرض را می‌گیرند.
    from plans import Feature as _Feat, has_feature as _hasf
    if _hasf(plan, _Feat.FORCE_JOIN_TEXT):
        rows_kb.append([InlineKeyboardButton(text="✏️ تغییر متن عضویت اجباری", callback_data="fj:text", style=ButtonStyle.PRIMARY)])
    # === PATCH_PARTNER_SETTINGS_BACK_FIX_V1 ===
    # برایِ رباتِ همکار این صفحه از داخلِ «تنظیمات عمومی ربات»
    # (set:hub_general) باز می‌شود، نه از زیرِ «ادمین‌ها و پشتیبانی»
    # (tadm:sec:admins) که برایِ همکار در دسترس نیست.
    _fj_back_cb = "set:hub_general" if plan == "partner" else "tadm:sec:admins"
    rows_kb.append([InlineKeyboardButton(text="⬅️ بازگشت", callback_data=_fj_back_cb,
                                         style=ButtonStyle.DANGER)])
    return InlineKeyboardMarkup(inline_keyboard=rows_kb)


@tenant_router.callback_query(F.data == "tadm:forcejoin")
async def tadm_forcejoin(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    await cb.message.edit_text(
        "📢 <b>عضویت اجباری</b>\n\nروی هر کانال بزن تا ویرایش/حذف یا فعال/غیرفعالش کنی:",
        reply_markup=await _fj_hub_kb(row.id, row.plan),
    )
    await cb.answer()


# === PATCH_FORCEJOIN_BTN_COLOR_V1 ===
_FJ_COLOR_LABELS = {
    "": "⚪️ بی‌رنگ",
    "primary": "🔵 آبی",
    "success": "🟢 سبز",
    "danger":  "🔴 قرمز",
}


def _fj_detail_kb(fj, colored_allowed: bool = False) -> InlineKeyboardMarkup:
    tog_text = "🔴 غیرفعال کردن" if fj.is_active else "🟢 فعال کردن"
    rows = [
        [InlineKeyboardButton(text=tog_text, callback_data=f"fj:tog:{fj.id}")],
    ]
    if colored_allowed:
        # یک ردیفِ کاملِ انتخابِ رنگ؛ رنگِ فعلی با ✅ مشخص می‌شود و خودِ هر
        # دکمه به همان رنگی است که نمایندگی‌اش می‌کند تا پیش‌نمایش باشد.
        rows.append([
            InlineKeyboardButton(
                text=("✅ " if (fj.btn_color or "") == key else "") + lbl,
                callback_data=f"fj:color:{fj.id}:{key or 'none'}",
                **({"style": _IBTN_COLOR_STYLE[key]} if key else {}))
            for key, lbl in _FJ_COLOR_LABELS.items()
        ])
    rows += [
        [InlineKeyboardButton(text="✏️ ویرایش", callback_data=f"fj:edit:{fj.id}"),
         InlineKeyboardButton(text="🗑 حذف", callback_data=f"fj:del:{fj.id}",
                              style=ButtonStyle.DANGER)],
        [InlineKeyboardButton(text="⬅️ بازگشت", callback_data="tadm:forcejoin",
                              style=ButtonStyle.DANGER)],
    ]
    return InlineKeyboardMarkup(inline_keyboard=rows)


@tenant_router.callback_query(F.data.startswith("fj:color:"))
async def fj_set_color(cb: CallbackQuery, bot: Bot):
    """رنگِ دکمهٔ یک کانالِ عضویتِ اجباری — فقط پلنِ حرفه‌ای."""
    row = await _owner_ok(cb, bot)
    if not row:
        return
    from plans import upgrade_hint as _uh
    if not has_feature(row.plan, Feature.FORCE_JOIN_COLOR):
        await cb.answer(_uh(Feature.FORCE_JOIN_COLOR), show_alert=True)
        return
    _, _, fid_s, key = cb.data.split(":", 3)
    color = "" if key == "none" else key
    if color and color not in _IBTN_COLOR_STYLE:
        await cb.answer("رنگ نامعتبر", show_alert=True)
        return
    async with Session() as s:
        fj = await s.get(ForceJoin, int(fid_s))
        if not fj or fj.bot_id != row.id:
            await cb.answer("یافت نشد", show_alert=True)
            return
        fj.btn_color = color or None
        await s.commit()
        await s.refresh(fj)
    await _fj_show_detail(cb, fj, colored_allowed=True)
    await cb.answer(f"رنگ روی «{_FJ_COLOR_LABELS[color]}» تنظیم شد.")


async def _fj_show_detail(cb: CallbackQuery, fj, colored_allowed: bool = False):
    st = "🟢 فعال" if fj.is_active else "🔴 غیرفعال"
    link = fj.invite_link or "—"
    # === PATCH_FORCEJOIN_HEALTH_V1 ===
    _broken = _FORCEJOIN_BROKEN.get((fj.bot_id, fj.chat_id))
    _warn = (f"\n\n⚠️ <b>این مورد الان کار نمی‌کند:</b> {_broken}.\n"
             "تا وقتی درست نشود، برایِ جلوگیری از قفل‌شدنِ کاربرها نادیده "
             "گرفته می‌شود (یعنی کاربر بدونِ عضویت رد می‌شود).") if _broken else ""
    txt = (f"📢 <b>{fj.title or fj.chat_id}</b>\n\n"
           f"شناسه: <code>{fj.chat_id}</code>\n"
           f"لینک: {link}\n"
           f"وضعیت: {st}" + _warn)
    try:
        await cb.message.edit_text(txt, reply_markup=_fj_detail_kb(fj, colored_allowed))
    except Exception:
        await cb.message.answer(txt, reply_markup=_fj_detail_kb(fj, colored_allowed))


@tenant_router.callback_query(F.data.startswith("fj:view:"))
async def fj_view(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    fid = int(cb.data.split(":")[2])
    async with Session() as s:
        fj = await s.get(ForceJoin, fid)
        if not fj or fj.bot_id != row.id:
            await cb.answer("یافت نشد", show_alert=True)
