@tenant_router.callback_query(F.data == "fj:text")
async def fj_text_start(cb: CallbackQuery, bot: Bot, state: FSMContext):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    # === PATCH_TRUST_TEXT_PRO_ONLY_V1 ===
    from plans import Feature as _Feat, has_feature as _hasf, upgrade_hint as _uh
    if not _hasf(row.plan, _Feat.FORCE_JOIN_TEXT):
        await cb.answer(_uh(_Feat.FORCE_JOIN_TEXT), show_alert=True)
        return
    current = await get_setting(row.id, "force_join_text", "")
    await state.set_state(AdminFSM.force_join_text)
