@tenant_router.callback_query(F.data == "tadm:settings")
async def tadm_settings(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    card = await get_setting(row.id, "card_number", "(ثبت نشده)")
    card_holder = await get_setting(row.id, "card_holder", "(ثبت نشده)")
    card_enabled = await get_setting(row.id, "card_enabled", "1")
    auto_approve = await get_setting(row.id, "auto_approve_receipts", "0")
    bot_paused = row.status == "paused"
    menu_mode_v = await get_setting(row.id, "menu_mode", "reply")
    kb_rows = [
        [InlineKeyboardButton(text="💳 ویرایش شماره کارت", callback_data="set:card", style=ButtonStyle.PRIMARY)],
        [InlineKeyboardButton(text="🧑 ویرایش نام صاحب کارت", callback_data="set:card_holder", style=ButtonStyle.PRIMARY)],
    ]
    if has_feature(row.plan, Feature.CUSTOM_WELCOME):
        kb_rows.append([InlineKeyboardButton(text="✏️ متن خوش‌آمدگویی", callback_data="set:welcome", style=ButtonStyle.PRIMARY)])
    if row.plan != "free":
        kb_rows.append([InlineKeyboardButton(text="🪙 درگاه ارز دیجیتال (NOWPayments)", callback_data="set:crypto", style=ButtonStyle.PRIMARY)])
        kb_rows.append([InlineKeyboardButton(text="🟦 درگاه سواپ‌ولت (SwapPay)", callback_data="set:swap", style=ButtonStyle.PRIMARY)])
    kb = InlineKeyboardMarkup(inline_keyboard=kb_rows + [
        [InlineKeyboardButton(text="🎁 پاداش دعوت (تومان)", callback_data="set:ref_reward", style=ButtonStyle.PRIMARY)],
    ] + (
        # === PATCH_PLAN_FEATURE_GATING_V1 ===
        [[InlineKeyboardButton(text="🏅 امتیازگیری با رفرال", callback_data="rpt:menu", style=ButtonStyle.PRIMARY)]]
        if has_feature(row.plan, Feature.REFERRAL_POINTS) else []
    ) + (
        # === PATCH_QR_BACKGROUND_VPN_ONLY_V1 ===
        [[InlineKeyboardButton(text="🖼 عکسِ پشتِ بارکد (QR)", callback_data="qrbg:menu", style=ButtonStyle.PRIMARY)]]
        if has_feature(row.plan, Feature.QR_BACKGROUND) and row.field == "vpn_sales" else []
    ) + (
        # === PATCH_TENANT_PREMIUM_EMOJI_V1 ===
        [[InlineKeyboardButton(text="⭐ افزودن ایموجی پرمیوم", callback_data="pemj:menu:0", style=ButtonStyle.PRIMARY)]]
        if has_feature(row.plan, Feature.PREMIUM_EMOJI) else []
    ) + [
        [InlineKeyboardButton(
            text="💳 کارت‌به‌کارت: " + ("✅ فعال" if card_enabled == "1" else "❌ غیرفعال"),
            callback_data="set:card_toggle", style=ButtonStyle.DANGER)],
        [InlineKeyboardButton(
            text="🤖 تایید خودکار رسید: " + ("✅ فعال" if auto_approve == "1" else "❌ غیرفعال"),
            callback_data="set:auto_approve_toggle", style=ButtonStyle.DANGER)],
        [InlineKeyboardButton(
            text="🤖 ربات: " + ("🔴 خاموش (کلیک برای روشن)" if bot_paused else "🟢 روشن (کلیک برای خاموش)"),
            callback_data="set:bot_toggle"
        )],
    ] + ([] if row.plan == "partner" else [[InlineKeyboardButton(
            # === PATCH_PARTNER_INLINE_ONLY_V1 === ربات‌های پلنِ همکار این دکمه را نمی‌بینند
            text="🎛 نوع منو: " + ("💠 شیشه‌ای (اینلاین)" if menu_mode_v == "inline" else "⌨️ کیبورد پایین"),
            callback_data="set:menu_mode"
        )]]) + [
        [InlineKeyboardButton(text="🎲 بازی کن و جایزه بگیر", callback_data="dga:menu", style=ButtonStyle.PRIMARY)],
        [InlineKeyboardButton(text="🏠 مدیریت دکمه‌های صفحه اصلی", callback_data="tadm:homebtns", style=ButtonStyle.DANGER)],
        [InlineKeyboardButton(text="🎨 مدیریت رنگ دکمه‌های اینلاین", callback_data="tadm:btn_colors", style=ButtonStyle.PRIMARY)],
        [InlineKeyboardButton(text="⬅️ بازگشت", callback_data="tadm:menu", style=ButtonStyle.DANGER)],
    ])
    txt = (
        f"⚙️ <b>تنظیمات</b>\n\n"
        f"شماره کارت: <code>{card}</code>\n"
        f"نام صاحب کارت: {card_holder}\n"
        f"کارت‌به‌کارت: {'✅ فعال' if card_enabled=='1' else '❌ غیرفعال'}\n"
        f"تایید خودکار رسید: {'✅ فعال' if auto_approve=='1' else '❌ غیرفعال'}\n"
        f"وضعیت ربات: {'🔴 خاموش' if bot_paused else '🟢 روشن'}"
    )
    try:
        await cb.message.edit_text(txt, reply_markup=kb, parse_mode="HTML")
    except Exception:
        await cb.message.answer(txt, reply_markup=kb, parse_mode="HTML")
    await cb.answer()


