@tenant_router.callback_query(F.data == "set:auto_approve_toggle")
async def set_auto_approve_toggle(cb: CallbackQuery, bot: Bot, forced_origin: str | None = None):
    """فعال/غیرفعال‌سازی تایید خودکار رسیدهای کارت‌به‌کارت (شارژ کیف پول
    و خرید کانفیگ). فعال‌سازی نیاز به تاییدِ صریحِ ادمین دارد (چون این روش
    دقیق نیست و ممکن است رسیدِ فیک را هم تایید کند)؛ غیرفعال‌سازی مستقیم
    انجام می‌شود.  # PATCH_AUTO_APPROVE_STATUS_AND_WARNING

    forced_origin: وقتی این هندلر از رویِ یک دکمهٔ کیبوردیِ فیزیکی (نه یک
    CallbackQuery واقعی) صدا زده می‌شود، پیامِ واقعی‌ای برای تشخیصِ خودکارِ
    مبدا (متنِ پنلِ فعلی) وجود ندارد — پس مبدا صراحتاً پاس داده می‌شود تا
    حدس اشتباه نزنیم و کاربر را به پنلِ اینلاینِ اشتباه نفرستیم."""
    row = await _owner_ok(cb, bot)
    if not row:
        return
    cur = await get_setting(row.id, "auto_approve_receipts", "0")

    # === PATCH_AUTO_APPROVE_NO_ACCIDENTAL_OFF_V1 ===
    # باگِ گزارش‌شده (تیکت #468): «هرچقدر فعالش می‌کنم فعال نمی‌شود».
    # علتش این بود که این یک دکمهٔ *تاگل* است که وضعیتِ فعلی را روی خودش
    # نشان می‌دهد — کاربر بعدِ اتمامِ ویزارد برمی‌گشت، روی «✅ فعال» می‌زد
    # تا *ببیند* فعال شده یا نه، و همان تپ بی‌هیچ پرسشی خاموشش می‌کرد.
    # فعال‌کردن یک ویزاردِ سه‌مرحله‌ای می‌خواست ولی خاموش‌کردن یک تپِ
    # اتفاقی — این عدمِ تقارن باعث می‌شد کاربر در یک حلقه گیر کند و فکر
    # کند تنظیمات ذخیره نمی‌شود. حالا خاموش‌کردن هم تایید می‌خواهد.
    if cur == "1":
        _origin_off = forced_origin or (
            "finance" if (("مالی" in ((cb.message.text or cb.message.caption or "") if cb.message else ""))
                          or ("کیف پول" in ((cb.message.text or cb.message.caption or "") if cb.message else "")))
            else "settings")
        kb_off = InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text="🔴 بله، غیرفعالش کن",
                                  callback_data=f"set:auto_approve_off:{_origin_off}", style=ButtonStyle.DANGER)],
            [InlineKeyboardButton(text="✅ نه، فعال بماند",
                                  callback_data=f"set:auto_approve_cancel:{_origin_off}", style=ButtonStyle.SUCCESS)],
        ])
        off_text = (
            "🤖 <b>تایید خودکار رسید هم‌اکنون فعال است.</b>\n\n"
            "این دکمه یک کلید است — زدنش آن را <b>خاموش</b> می‌کند. "
            "اگر فقط می‌خواستی وضعیتش را ببینی، «نه، فعال بماند» را بزن.\n\n"
            "می‌خواهی غیرفعالش کنم؟")
        try:
            await cb.message.edit_text(off_text, reply_markup=kb_off, parse_mode="HTML")
        except Exception:
            await cb.message.answer(off_text, reply_markup=kb_off, parse_mode="HTML")
        await cb.answer()
        return

    # در حال غیرفعال بودن → قبل از روشن کردن، هشدارِ مسئولیت نشان بده
    if forced_origin:
        origin = forced_origin
    else:
        src_text = (cb.message.text or cb.message.caption or "") if cb.message else ""
        origin = "finance" if ("مالی" in src_text or "کیف پول" in src_text) else "settings"
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="✅ فعال کن (با مسئولیت خودم)",
                              callback_data=f"set:auto_approve_confirm:{origin}", style=ButtonStyle.SUCCESS)],
        [InlineKeyboardButton(text="❌ انصراف", callback_data=f"set:auto_approve_cancel:{origin}", style=ButtonStyle.DANGER)],
    ])
    warn_text = (
        "⚠️ <b>هشدار قبل از فعال‌سازی</b>\n\n"
        "تایید خودکار رسید، مبلغ/شماره‌کارت/تاریخ نوشته‌شده روی رسید را می‌خواند "
        "و در صورت تطابق، بدون بررسی ادمین، سفارش را تایید می‌کند (کیف‌پول شارژ "
        "یا کانفیگ ارسال می‌شود).\n\n"
        "این روش <b>دقیق نیست</b> و امکان دارد رسیدِ جعلی/دستکاری‌شده (مثلاً یک "
        "عکسِ فتوشاپ‌شده با مبلغ درست) را هم تایید کند. برای هر تاییدِ خودکار یک "
        "گزارش کامل با دکمهٔ «لغو» برایت ارسال می‌شود تا در صورتِ فیک بودن، "
        "کیف‌پول/کانفیگ را برگردانی — اما این کار *بعد* از تحویل انجام می‌شود.\n\n"
        "با فعال‌کردن این گزینه، مسئولیتِ احتمالِ تاییدِ رسیدهای فیک بر عهدهٔ خودت است."
    )
    try:
        await cb.message.edit_text(warn_text, reply_markup=kb, parse_mode="HTML")
    except Exception:
        await cb.message.answer(warn_text, reply_markup=kb, parse_mode="HTML")
    await cb.answer()


@tenant_router.callback_query(F.data.startswith("set:auto_approve_confirm:"))
async def set_auto_approve_confirm(cb: CallbackQuery, bot: Bot, state: FSMContext):
    """PATCH_AUTO_APPROVE_MULTI_DEST_ID_V1 — قبل از فعال‌سازیِ نهایی، سه‌تا
    شناسهٔ مقصد (کارت/شبا/حساب) رو از ادمین می‌گیره تا هوش مصنوعی بتونه هر
    نوع رسیدی (چه فقط شماره‌کارت نشون بده، چه فقط شبا/حساب) رو درست تشخیص
    بده. هرکدوم رو نداشت، می‌تونه با فرستادنِ «-» ردش کنه."""
    row = await _owner_ok(cb, bot)
    if not row:
        return
    # === PATCH_RECEIPT_AI_OWN_KEY_V1 === اگر پلتفرم «کلیدِ اختصاصیِ هر ربات» را الزامی کرده
    from tenant.gateways.receipt_ai_key import needs_key_first
    if await needs_key_first(row.id):
        await cb.message.answer(
            "🔑 برایِ روشن‌کردنِ تایید خودکار رسید، اول باید <b>توکنِ هوش مصنوعیِ آروانِ خودت</b> را ثبت کنی "
            "(هزینهٔ تشخیصِ رسیدها از حسابِ آروانِ خودت کم می‌شود).",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(
                text="🔑 ثبتِ توکنِ آروان", callback_data="rai:menu", style=ButtonStyle.SUCCESS)]]))
        return await cb.answer()
    origin = cb.data.split(":")[-1]
    await state.update_data(aa_origin=origin)
    await state.set_state(AutoApproveDestFSM.card)
    cur_card = await get_setting(row.id, "card_number", "")
    hint = f"\n\nشمارهٔ فعلی: <code>{cur_card}</code> — برای نگه‌داشتنش «-» بفرست." if cur_card else ""
    try:
        await cb.message.edit_reply_markup(reply_markup=None)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.message.answer(
        "🤖 <b>راه‌اندازیِ تایید خودکار رسید</b>\n\n"
        "برای اینکه هوش مصنوعی بتونه «مقصدِ» درستِ پرداخت رو تشخیص بده، سه‌تا "
        "شناسهٔ مقصد ازت می‌پرسم (کارت، شبا، حساب) — هرکدوم رو نداری یا نمی‌خوای "
        "بدی، بنویس «-» تا رد بشه (نگه‌داشتنِ همون مقدارِ فعلی هم با «-» انجام می‌شه).\n\n"
        "۱) 💳 شمارهٔ کارتِ مقصد رو بفرست:" + hint,
        parse_mode="HTML", reply_markup=await smart_cancel_kb(bot))
    await cb.answer()


async def _send_back_to_main_menu(msg: Message, row: BotRow, text: str) -> None:
    """PATCH_AA_WIZARD_BACK_BTN_V1 — برخلافِ `main_kb_or_remove` به‌تنهایی (که
    برای بات‌های با «منویِ شیشه‌ای/اینلاین» فقط کیبوردِ پایینِ صفحه رو پاک
    می‌کنه، بدونِ فرستادنِ خودِ منوی اینلاین)، این تابع طبقِ همون الگویی که
    جاهای دیگهٔ کد (مثلِ `tenant_cancel`) استفاده می‌کنن، منوی درستِ متناسب
    با نوعِ ربات رو واقعاً نشون می‌ده — تا کاربر بعدِ اتمامِ یه ویزارد گیر
    نکنه و مجبور نشه دستی /start بزنه."""
    if await get_setting(row.id, "menu_mode", "reply") == "inline":
        ikb = await main_inline_kb(row.id, row.owner_id, msg.from_user.id)
        _note_msg = await msg.answer(text, reply_markup=ReplyKeyboardRemove())
        if ikb:
            await send_home_menu(msg, row.id, ikb, attach=_note_msg)
        return
    kb = await main_kb_or_remove(row.id, row.owner_id, msg.from_user.id)
    await msg.answer(text, reply_markup=kb or ReplyKeyboardRemove())


