async def _auto_approve_back_to_menu(cb: CallbackQuery, bot: Bot, row: "BotRow", origin: str | None = None) -> None:
    """بازگشت به همان زیرمنویی که کاربر از آن به تنظیماتِ تایید خودکار آمده بود
    (مالی و کیف‌پول یا تنظیمات)."""
    if origin is None:
        src_text = (cb.message.text or cb.message.caption or "") if cb.message else ""
        origin = "finance" if ("مالی" in src_text or "کیف پول" in src_text) else "settings"
    if origin == "finance":
        kb = await _sec_finance_kb(row.id, row.plan)
        menu_mode = await get_setting(row.id, "menu_mode", "reply")
        if menu_mode == "inline":
            try:
                await cb.message.edit_text(
                    "💰 <b>مالی و کیف پول</b>\n\nمدیریت سفارش‌ها، کارت‌به‌کارت و درگاه‌های پرداخت:",
                    reply_markup=kb)
            except Exception:
                await cb.message.answer(
                    "💰 <b>مالی و کیف پول</b>",
                    reply_markup=kb)
        else:
            try:
                await cb.message.delete()
            except Exception:
                logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
            await cb.message.answer(
                "💰 <b>مالی و کیف پول</b>\n\nمدیریت سفارش‌ها، کارت‌به‌کارت و درگاه‌های پرداخت:",
                reply_markup=kb)
    else:
        await tadm_settings(cb, bot)


@tenant_router.callback_query(F.data == "set:bot_toggle")
async def set_bot_toggle(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    async with Session() as s:
        r = await s.get(BotRow, row.id)
        if r:
            r.status = "paused" if r.status == "active" else "active"
            # === PATCH_BOT_OFF_REASON_V1 ===
            if r.status == "paused":
                r.lock_reason = f"توسط مالکِ ربات (آیدی {cb.from_user.id}) از طریقِ تنظیماتِ ربات خاموش شد"
            else:
                r.lock_reason = None
            await s.commit()
            invalidate_bot_row_cache(r.token)
            try:
                import tenant_status_bus
                await tenant_status_bus.publish_tenant_invalidate(r.token)
            except Exception:
                logger.exception("خطای نادیده‌گرفته‌شده در بی‌اعتبارسازی وضعیت ربات")
    await cb.answer("وضعیت ربات تغییر کرد", show_alert=True)
    await tadm_sec_settings(cb, bot)


