@tenant_router.callback_query(F.data == "set:menu_mode")
async def set_menu_mode(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    # === PATCH_PARTNER_INLINE_ONLY_V1 === ربات‌های پلنِ همکار حق سوییچ به کیبورد ندارند
    if row.plan == "partner":
        await cb.answer("پنلِ ربات‌های همکار همیشه اینلاین است.", show_alert=True)
        return
    cur = await get_setting(row.id, "menu_mode", "reply")
    new = "inline" if cur != "inline" else "reply"
    await set_setting(row.id, "menu_mode", new)
    await reset_kb_cleared(row.id)   # PATCH_NO_DOT_MSG_V1
    await cb.answer(
        ("💠 منوی شیشه‌ای فعال شد. کاربران با /start منوی جدید را می‌بینند."
         if new == "inline" else
         "⌨️ کیبورد پایین فعال شد. کاربران با /start منوی جدید را می‌بینند."),
        show_alert=True,
    )
    bot_paused = row.status == "paused"
    new_kb = await _sec_settings_kb(row.id, row.plan, new, bot_paused)
    if new == "inline":
        # هنوز اینلاین هستیم؛ edit روی همین پیام جواب می‌دهد.
        try:
            await cb.message.edit_text(
                "🎛 <b>دکمه‌ها و تنظیمات</b>\n\nمدیریت دکمه‌های منو، ظاهر و تنظیمات کلی:",
                reply_markup=new_kb)
        except Exception:
            await cb.message.answer(
                "🎛 <b>دکمه‌ها و تنظیمات</b>\n\nمدیریت دکمه‌های منو، ظاهر و تنظیمات کلی:",
                reply_markup=new_kb)
    else:
        # تلگرام اجازه نمی‌دهد کیبوردِ فیزیکی (Reply) را با edit روی پیامِ
        # قبلی (که اینلاین بوده) جایگزین کرد — باید حتماً پیامِ جدید فرستاده
        # شود تا کیبوردِ پایینِ صفحه واقعاً عوض شود. برای همین ابتدا دکمه‌های
        # اینلاینِ پیامِ قبلی را پاک می‌کنیم (که دکمهٔ مرده باقی نماند) و بعد
        # پیامِ جدید را با کیبوردِ فیزیکی می‌فرستیم.
        try:
            await cb.message.edit_reply_markup(reply_markup=None)
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        await cb.message.answer(
            "🎛 <b>دکمه‌ها و تنظیمات</b>\n\nمدیریت دکمه‌های منو، ظاهر و تنظیمات کلی:",
            reply_markup=new_kb)


def _trial_gb_label(gb_str: str) -> str:
    """تبدیل رشته حجم به برچسب نمایشی (گیگ یا مگابایت)."""
    try:
        val = float(gb_str)
    except (ValueError, TypeError):
        return f"{gb_str} گیگ"
    if val < 1:
        mb = int(round(val * 1024))
        return f"{mb} مگابایت"
    if val == int(val):
        return f"{int(val)} گیگ"
    return f"{val} گیگ"


# === PATCH_TRIAL_HOURLY_V1 ===
def _trial_duration_label(days_str: str, hours_str: str = "0") -> str:
    """برچسبِ نمایشیِ مدتِ تست؛ اگه ساعت‌ست، «X ساعت» نشون می‌ده، وگرنه
    «X روز». برای ترکیبی هم پشتیبانی: «۱ روز و ۱۲ ساعت»."""
    try:
        d = int(days_str or 0)
    except (ValueError, TypeError):
        d = 0
    try:
        h = int(hours_str or 0)
    except (ValueError, TypeError):
        h = 0
    if h > 0 and d > 0:
        return f"{d} روز و {h} ساعت"
    if h > 0:
        return f"{h} ساعت"
    return f"{d} روز" if d else "—"


# === PATCH_TRIAL_DELETE_HOURS_UI_V1 ===
# گزارشِ مالکِ ربات (تیکت #878): «تستِ رایگان هم مثلِ بقیهٔ سرویس‌ها بعد از مدتِ دلخواه خودکار از پنل پاک شود».
# حذفِ خودکار از قبل بود (trial_cleanup: بعد از پایانِ تست + trial_delete_hours، پیش‌فرض ۵ ساعت) ولی مالک
# راهی برایِ تغییرِ مهلت نداشت. این بخش همان کلیدِ trial_delete_hours را قابلِ تنظیم می‌کند (۱ ساعت تا ۷ روز).
TRIAL_DEL_MIN_H, TRIAL_DEL_MAX_H = 1, 168


def _trial_del_label(hours_str: str) -> str:
    try:
        v = float(hours_str or 5)
    except (ValueError, TypeError):
        v = 5.0
    v = min(max(v, 0.17), float(TRIAL_DEL_MAX_H))
    if v >= 24 and v % 24 == 0:
        return f"{int(v // 24)} روز بعد از پایانِ تست"
    if float(v).is_integer():
        return f"{int(v)} ساعت بعد از پایانِ تست"
    return f"{v:g} ساعت بعد از پایانِ تست"


# === PATCH_TRIAL_UNUSED_REMINDER_V1 ===
def _trial_unused_label(hours_str: str) -> str:
    """برچسبِ نمایشیِ «یادآوریِ عدمِ استفاده». صفر یا نامعتبر یعنی خاموش."""
    try:
        v = float(hours_str or 0)
    except (ValueError, TypeError):
        v = 0.0
    if v <= 0:
        return "🚫 غیرفعال"
    if v >= 24 and v % 24 == 0:
        d = int(v // 24)
        return f"{d} روز"
    if float(v).is_integer():
        return f"{int(v)} ساعت"
    return f"{v} ساعت"


def _parse_trial_duration_input(txt: str) -> tuple[int, int] | None:
    """پارسِ ورودیِ کاربر برای مدتِ تست. خروجی (days, hours) یا None اگه
    نامعتبر باشه. فرمت‌های قبولی:
      «3»          → (3, 0)  ← فرضِ روز
      «3d» یا «3 روز» → (3, 0)
      «6h» یا «6 ساعت» → (0, 6)
      «1d 12h»    → (1, 12)
      «1 روز 12 ساعت» → (1, 12)"""
    if not txt:
        return None
    # نرمال‌سازی ارقام فارسی و حروف
    txt = txt.strip().translate(str.maketrans("۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩",
                                                "01234567890123456789"))
    txt = txt.lower().replace("hours", "h").replace("hour", "h")
    txt = txt.replace("days", "d").replace("day", "d")
    txt = txt.replace("ساعت", "h").replace("روز", "d")
    # حذف فاصله‌ی اضافی
    txt = " ".join(txt.split())

    # اگه فقط عدد بود → فرضِ روز (backward compat)
    if txt.isdigit():
        return (int(txt), 0)

    import re
    days = 0
    hours = 0
    matched_any = False
    for m in re.finditer(r"(\d+)\s*([dh])", txt):
        matched_any = True
        n = int(m.group(1))
        if m.group(2) == "d":
            days += n
        else:
            hours += n

    if not matched_any:
        return None
    if days < 0 or hours < 0:
        return None
    if hours >= 24 * 30:  # سقفِ منطقی
        return None
    return (days, hours)


@tenant_router.callback_query(F.data == "set:trial")
async def set_trial_menu(cb: CallbackQuery, bot: Bot):
    """منوی تنظیمات تست رایگان."""
    row = await _owner_ok(cb, bot)
    if not row:
        return
    enabled = await get_setting(row.id, "trial_enabled", "0")
    source  = await get_setting(row.id, "trial_source", "panel")
    gb      = await get_setting(row.id, "trial_gb", "2")
    days    = await get_setting(row.id, "trial_days", "3")
    # === PATCH_TRIAL_HOURLY_V1 ===
    hours   = await get_setting(row.id, "trial_hours", "0")
    # === PATCH_TRIAL_UNUSED_REMINDER_V1 ===
    unused_h = await get_setting(row.id, "trial_unused_hours", "0")
    # === PATCH_TRIAL_ON_HOLD_V1 ===
    onhold = await get_setting(row.id, "trial_on_hold", "0") == "1"
    onhold_lbl = "⏸ از اولین اتصال" if onhold else "▶️ از لحظهٔ ساخت"
    toggle  = "✅ فعال" if enabled == "1" else "❌ غیرفعال"
    src_lbl = "📦 انبار دستی" if source == "stock" else "🤖 پنل خودکار"
    gb_label = _trial_gb_label(gb)
    duration_label = _trial_duration_label(days, hours)
    unused_label = _trial_unused_label(unused_h)
    del_label = _trial_del_label(await get_setting(row.id, "trial_delete_hours", "5"))   # PATCH_TRIAL_DELETE_HOURS_UI_V1
    # === PATCH_TRIAL_GLOBAL_DIFF_V1 === دکمه‌هایِ تستی که مقدارِ اختصاصی دارند و این صفحه را نادیده می‌گیرند
    _ovr = await _trial_overriding_buttons(row.id)
    kb = InlineKeyboardMarkup(inline_keyboard=[
        *([[InlineKeyboardButton(text="♻️ همهٔ دکمه‌هایِ تست از همین تنظیمات بخوانند",
                                 callback_data="set:trial_sync_buttons", style=ButtonStyle.SUCCESS)]] if _ovr else []),
        [InlineKeyboardButton(
            text=f"وضعیت: {toggle}",
            callback_data="set:trial_toggle", style=ButtonStyle.PRIMARY)],
        [InlineKeyboardButton(
            text=f"منبع: {src_lbl}",
            callback_data="set:trial_src", style=ButtonStyle.PRIMARY)],
        [InlineKeyboardButton(
            text=f"📦 حجم: {gb_label}",
            callback_data="set:trial_gb", style=ButtonStyle.PRIMARY)],
        [InlineKeyboardButton(
            text=f"📅 مدت: {duration_label}",
            callback_data="set:trial_duration", style=ButtonStyle.PRIMARY)],
        [InlineKeyboardButton(
            text=f"⏰ یادآوریِ عدمِ استفاده: {unused_label}",
            callback_data="set:trial_unused", style=ButtonStyle.PRIMARY)],
        # === PATCH_TRIAL_DELETE_HOURS_UI_V1 ===
        [InlineKeyboardButton(
            text=f"🗑 حذفِ خودکارِ تست از پنل: {del_label}",
            callback_data="set:trial_del", style=ButtonStyle.PRIMARY)],
        # === PATCH_TRIAL_ON_HOLD_V1 ===
        [InlineKeyboardButton(
            text=f"⏳ شروعِ زمانِ تست: {onhold_lbl}",
            callback_data="set:trial_onhold", style=ButtonStyle.PRIMARY)],
        [InlineKeyboardButton(text="🔑 کانالِ گزارشِ اکانتِ تست", callback_data="set:trrep",
                              style=ButtonStyle.SUCCESS)],     # PATCH_TRIAL_REPORT_CHANNEL_V1
        [InlineKeyboardButton(text="⬅️ بازگشت", callback_data="tadm:sec:settings", style=ButtonStyle.DANGER)],
    ])
    text = (
        "🎁 <b>تنظیمات تست رایگان VPN</b>\n\n"
        f"وضعیت: {toggle}\n"
        f"منبع: {src_lbl}\n"
        f"حجم: <b>{gb_label}</b>\n"
        f"مدت: <b>{duration_label}</b>\n"
        f"یادآوریِ عدمِ استفاده: <b>{unused_label}</b>\n"
        f"حذفِ خودکارِ تست از پنل: <b>{del_label}</b>\n"
        f"شروعِ زمانِ تست: <b>{onhold_lbl}</b>\n\n"
        "⚠️ هر کاربر فقط یک‌بار می‌تواند از تست رایگان استفاده کند.\n\n"
        + ("⚠️ این دکمه‌ها مقدارِ اختصاصی دارند و حجم/مدتِ بالا را <b>نادیده می‌گیرند</b>:\n"
           + "\n".join(f"• «{_n}» — {_d}" for _n, _d in _ovr)
           + "\nبا دکمهٔ «♻️ همهٔ دکمه‌هایِ تست از همین تنظیمات بخوانند» همه را یک‌جا یکی کن.\n\n" if _ovr else "")
        + "ℹ️ اگر از «تنظیم و مدیریت دکمه‌ها» یک دکمه را روی «تست رایگان VPN» گذاشته‌ای، حجم و مدتِ آن دکمه از همین‌جا "
        "خوانده می‌شود، مگر اینکه خودِ دکمه مقدارِ اختصاصی داشته باشد."
    )
    try:
        await cb.message.edit_text(text, reply_markup=kb)
    except Exception:
        await cb.message.answer(text, reply_markup=kb)
    await cb.answer()


# === PATCH_TRIAL_GLOBAL_DIFF_V1 ===
async def _trial_overriding_buttons(bot_id: int) -> list[tuple[str, str]]:
    """دکمه‌هایِ «تست رایگان» که حجم/مدتِ اختصاصیِ متفاوت از «تنظیماتِ تستِ رایگان» دارند: [(برچسب, توضیح)]."""
    async with Session() as s:
        btns = (await s.scalars(select(MainButton).where(
            MainButton.bot_id == bot_id, MainButton.action == "free_trial").order_by(MainButton.id))).all()
    out = []
    for mb in btns:
        cfg = await _trial_fill_global(bot_id, _trial_cfg_of(mb))
        parts = []
        for k, a, b in cfg.get("_global_diff") or []:
            if k == "gb":
                parts.append(f"حجم دکمه {_trial_gb_label(a)}")
            else:
                parts.append("مدتِ دکمه با تنظیماتِ کلی فرق دارد")
        if parts:
            out.append((mb.label, "، ".join(parts)))
    return out


@tenant_router.callback_query(F.data == "set:trial_sync_buttons")
async def set_trial_sync_buttons(cb: CallbackQuery, bot: Bot):
    """حجم/مدتِ اختصاصیِ همهٔ دکمه‌هایِ «تست رایگان» را پاک می‌کند تا از «تنظیماتِ تستِ رایگان» خوانده شود."""
    row = await _owner_ok(cb, bot)
    if not row:
        return
    async with Session() as s:
        ids = (await s.scalars(select(MainButton.id).where(
            MainButton.bot_id == row.id, MainButton.action == "free_trial"))).all()
    for mid in ids:
        await _trial_cfg_update(mid, trial_gb=None, trial_days=None, trial_hours=None)
    await cb.answer(f"✅ {len(ids)} دکمهٔ تست حالا حجم و مدت را از همین صفحه می‌خوانند", show_alert=True)
    await set_trial_menu(cb, bot)


@tenant_router.callback_query(F.data == "set:trial_toggle")
async def set_trial_toggle(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    cur = await get_setting(row.id, "trial_enabled", "0")
    await set_setting(row.id, "trial_enabled", "0" if cur == "1" else "1")
    await set_trial_menu(cb, bot)


# === PATCH_GATEWAY_DISPLAY_NAMES_V1 ===
# یک صفحهٔ مشترک برایِ تغییرِ اسمِ همهٔ درگاه‌ها، به‌جایِ افزودنِ دکمهٔ جدا
# به پنلِ تک‌تکشان. آبان گیت‌وی و تون‌پیز دکمهٔ خودشان را از قبل دارند و
# این‌جا هم فهرست می‌شوند تا کاربر یک جایِ واحد برایِ همه داشته باشد.
class GwNameFSM(StatesGroup):
    value = State()


def _gw_all() -> dict[str, tuple[str, str]]:
    # === PATCH_GATEWAY_EXACT_LABEL_V1 ===
    # آبان گیت‌وی و تون‌پیز حالا خودشان در GATEWAY_LABELS هستند، پس
    # فهرستِ جداگانه حذف شد تا دو جا نگه‌داری نشود.
    return dict(GATEWAY_LABELS)


async def _gwname_kb(bot_id: int) -> InlineKeyboardMarkup:
    rows = []
    for key, (default, skey) in _gw_all().items():
        cur = (await get_setting(bot_id, skey, "") or "").strip() or default
        mark = "✏️" if cur != default else "▫️"
        rows.append([InlineKeyboardButton(
            text=f"{mark} {cur}", callback_data=f"gwname:set:{key}",
            style=ButtonStyle.PRIMARY)])
    rows.append([InlineKeyboardButton(text="⬅️ بازگشت",
                                      callback_data="tadm:sec:settings",
                                      style=ButtonStyle.DANGER)])
    return InlineKeyboardMarkup(inline_keyboard=rows)


@tenant_router.callback_query(F.data == "gwname:menu")
async def gwname_menu(cb: CallbackQuery, bot: Bot):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    txt = ("🏷 <b>اسمِ نمایشیِ درگاه‌هایِ پرداخت</b>\n\n"
           "اسمی که مشتری رویِ دکمهٔ پرداخت می‌بیند. رویِ هر کدام بزن تا "
           "عوضش کنی.\n\n"
           "▫️ اسمِ پیش‌فرض · ✏️ اسمِ سفارشی\n\n"
           "<i>این فقط برچسب را عوض می‌کند، نه خودِ درگاه را.</i>")
    try:
        await cb.message.edit_text(txt, reply_markup=await _gwname_kb(row.id))
    except Exception:                                        # noqa: BLE001
        await cb.message.answer(txt, reply_markup=await _gwname_kb(row.id))
    await cb.answer()


@tenant_router.callback_query(F.data.startswith("gwname:set:"))
async def gwname_set(cb: CallbackQuery, bot: Bot, state: FSMContext):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    key = cb.data.rsplit(":", 1)[1]
    meta = _gw_all().get(key)
    if not meta:
        await cb.answer()
        return
    default, skey = meta
    cur = (await get_setting(row.id, skey, "") or "").strip() or default
    await state.set_state(GwNameFSM.value)
    await state.update_data(gw_key=key)
    await cb.message.answer(
        f"🏷 اسمِ تازه برایِ این درگاه را بفرست (فعلاً: <b>{cur}</b>؛ حداکثر ۴۰ حرف).\n\n"
        "برایِ بازگشت به اسمِ پیش‌فرض، کلمهٔ <code>پیش‌فرض</code> را بفرست.",
        reply_markup=await smart_cancel_kb(bot))
    await cb.answer()


@tenant_router.message(GwNameFSM.value, F.text)
async def gwname_save(msg: Message, bot: Bot, state: FSMContext):
    row = await _owner_ok_msg(msg, bot)
    data = await state.get_data()
    await state.clear()
    if not row:
        return
    meta = _gw_all().get(data.get("gw_key") or "")
    if not meta:
        return
    default, skey = meta
    name = (msg.text or "").strip()
    if name in ("پیش‌فرض", "پیشفرض", "default", "-"):
        await set_setting(row.id, skey, "")
        await msg.answer(f"✅ به اسمِ پیش‌فرض (<b>{default}</b>) برگشت.")
    elif not name:
        await msg.answer("اسمِ نامعتبر.")
        return
    else:
        await set_setting(row.id, skey, name[:40])
        await msg.answer(f"✅ اسمِ نمایشی رویِ «{name[:40]}» تنظیم شد.")
    await msg.answer("🏷 <b>اسمِ نمایشیِ درگاه‌ها</b>",
                     reply_markup=await _gwname_kb(row.id))


# === PATCH_PURCHASE_ON_HOLD_V1 ===
@tenant_router.callback_query(F.data == "set:buy_onhold")
async def set_buy_onhold(cb: CallbackQuery, bot: Bot):
    """شمارشِ مدتِ اشتراکِ *فروشی* از اولین اتصال، نه از لحظهٔ خرید.

    مثلِ همتایِ تستش فقط رویِ خانوادهٔ مرزبان (مرزبان/پاسارگاد/ربکا) اثر
    دارد؛ بقیهٔ پنل‌ها پرچم را نادیده می‌گیرند و مثلِ قبل active می‌سازند.
    رویِ تمدید اثری ندارد — تمدید همیشه از همان لحظه اعمال می‌شود.
    """
    row = await _owner_ok(cb, bot)
    if not row:
        return
    cur = await get_setting(row.id, "purchase_on_hold", "0")
    new = "0" if cur == "1" else "1"
    await set_setting(row.id, "purchase_on_hold", new)
    if new == "1":
        await cb.answer(
            "⏳ از این به بعد زمانِ اشتراکِ خریدها از اولین اتصالِ مشتری شروع می‌شود.\n\n"
            "فقط مرزبان، پاسارگاد، ربکا.\n"
            "پنل‌هایی که جدا تنظیم شده‌اند، تغییر نمی‌کنند.", show_alert=True)
    else:
        await cb.answer("▶️ برگشت به حالتِ عادی: زمان از لحظهٔ خرید شروع می‌شود.\n"
                        "(پنل‌هایی که جدا تنظیم شده‌اند، تغییر نمی‌کنند.)",
                        show_alert=True)
    await tadm_sec_settings(cb, bot)


