    await set_setting(row.id, "trial_on_hold", new)
    if new == "1":
        await cb.answer(
            "⏳ از این به بعد زمانِ تست از اولین اتصالِ کاربر شروع می‌شود.\n\n"
            "پشتیبانی: مرزبان، پاسارگاد، ربکا. رویِ بقیهٔ پنل‌ها بی‌اثر است "
            "و تست مثلِ قبل از لحظهٔ ساخت فعال می‌شود.", show_alert=True)
