@tenant_router.message(_TrialUnusedFSM.custom)
async def set_trial_unused_custom_save(msg: Message, bot: Bot, state: FSMContext):
    row = await _owner_ok_msg(msg, bot)
    if not row:
        await state.clear(); return
    parsed = _parse_trial_duration_input(msg.text or "")
    if not parsed:
        await msg.answer(
            "❌ فرمت نامعتبر. مثال درست:\n"
            "<code>1h</code> یا <code>24h</code> یا <code>2d</code>")
        return
    days, hours_part = parsed
    total_hours = days * 24 + hours_part
    if total_hours <= 0:
        await msg.answer("❌ حداقل باید یه عددِ بزرگ‌تر از صفر بذاری.")
        return
    await set_setting(row.id, "trial_unused_hours", str(total_hours))
    await state.clear()
    kb_back = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="⬅️ بازگشت به تنظیمات تست رایگان", callback_data="set:trial", style=ButtonStyle.DANGER)]
    ])
    label = _trial_unused_label(str(total_hours))
    await msg.answer(f"✅ یادآوریِ عدمِ استفاده: <b>{label}</b> ذخیره شد.", reply_markup=kb_back)


