@tenant_router.message(TrackOrderFSM.code, F.text)
async def track_order_lookup(msg: Message, bot: Bot, state: FSMContext):
    await state.clear()
    row = await get_bot_row(bot)
    if not row:
        return
    raw = (msg.text or "").strip()
    # === PATCH_ORDER_TRACKING_CANCEL_V1 ===
    # اگه به‌جایِ زدنِ دکمه، یکی از این متن‌ها رو تایپ کرد (مثلاً از رویِ
    # کیبوردِ پایینِ همیشگی)، به‌جایِ اینکه «کدِ نامعتبر» بهش بدیم، لغو
    # کن و منویِ اصلی رو نشون بده.
    if raw in ("❌ لغو و بازگشت", "❌ لغو", "لغو", "/cancel", "🏠 بازگشت به خانه", "⬅️ بازگشت"):
        if await get_setting(row.id, "menu_mode", "reply") == "inline":
            ikb = await main_inline_kb(row.id, row.owner_id, msg.from_user.id)
            await send_home_menu(msg, row.id, ikb, prefer_edit=False)
        else:
            kb = await main_kb_or_remove(row.id, row.owner_id, msg.from_user.id)
            await send_home_menu(msg, row.id, kb or ReplyKeyboardRemove())
        return
    code = raw.upper()
    if not code:
        await msg.answer("کدِ خالی قابلِ‌جست‌وجو نیست.")
        return

    kb = await inline_back_kb(row.id)
    tg_id = msg.from_user.id

    # === PATCH_ORDER_TRACKING_V1 ===
    # امنیت: جست‌وجو همیشه هم به bot_id هم به خودِ کاربرِ درخواست‌دهنده
    # محدود می‌شود — وگرنه هرکسی با حدس‌زدنِ کدِ یک نفرِ دیگر می‌توانست
    # جزئیاتِ سفارشِ او را ببیند.
    async with Session() as s:
        o = await s.scalar(select(Order).join(BotUser, Order.user_id == BotUser.id).where(
            Order.bot_id == row.id, Order.tracking_code == code,
            BotUser.telegram_id == tg_id))
        if o:
            status_label = _TRACK_STATUS_LABELS_ORDER.get(o.status, o.status)
            await msg.answer(
                f"🔖 <b>کد پیگیری: {code}</b>\n\n"
                f"📦 نوع: کانفیگ/محصول\n"
                f"💰 مبلغ: {int(o.amount):,} تومان\n"
                f"📅 تاریخ: {o.created_at.strftime('%Y-%m-%d %H:%M') if o.created_at else '—'}\n"
                f"📊 وضعیت: {status_label}",
                reply_markup=kb, parse_mode="HTML")
            return

        so = await s.scalar(select(SmmOrder).where(
            SmmOrder.bot_id == row.id, SmmOrder.tracking_code == code,
            SmmOrder.user_telegram_id == tg_id))
        # === PATCH_SMM_TRACKING_IS_ORDER_ID_V1 ===
        # کدِ پیگیریِ سفارش‌هایِ خدماتِ مجازی حالا «SMM-<شناسه>» است. برایِ
        # اینکه مشتری هر شکلی نوشت کار کند (SMM-123 / #123 / 123)، اگر با
        # خودِ رشته پیدا نشد، عددش را جدا می‌کنیم و با شناسهٔ سفارش می‌گردیم.
        # کدهایِ تصادفیِ قدیمی هم چون هنوز در ستون هستند کار می‌کنند.
        if not so:
            _digits = code.replace("SMM-", "").replace("#", "").strip()
            if _digits.isdigit():
                so = await s.scalar(select(SmmOrder).where(
                    SmmOrder.bot_id == row.id, SmmOrder.id == int(_digits),
                    SmmOrder.user_telegram_id == tg_id))
        if so:
            status_label = _TRACK_STATUS_LABELS_SMM.get(so.status, so.status)
            await msg.answer(
                f"🔖 <b>کد پیگیری: {so.tracking_code or f'SMM-{so.id}'}</b>\n\n"
                f"📦 سرویس: {so.service_name or so.service_id}\n"
                f"🔢 تعداد: {so.quantity:,}\n"
                f"💰 مبلغ: {int(so.price_toman):,} تومان\n"
                f"📅 تاریخ: {so.created_at.strftime('%Y-%m-%d %H:%M') if so.created_at else '—'}\n"
                f"📊 وضعیت: {status_label}",
                reply_markup=kb, parse_mode="HTML")
            return

        go = await s.scalar(select(GiftOrder).join(BotUser, GiftOrder.buyer_user_id == BotUser.id).where(
            GiftOrder.bot_id == row.id, GiftOrder.tracking_code == code,
            BotUser.telegram_id == tg_id))
        if go:
            status_label = _TRACK_STATUS_LABELS_GIFT.get(go.status, go.status)
            # === PATCH_TELEGRAM_PREMIUM_V1 ===
            # سفارش‌هایِ پرمیوم هم در همین جدول ذخیره می‌شوند (gift_id به
            # شکلِ "premium_N")؛ برایِ وضوح، برچسبِ نمایشی‌شان جدا از گیفتِ
            # معمولی است.
            if go.gift_id and go.gift_id.startswith("premium_"):
                months = go.gift_id.split("_")[1]
                item_line = f"🌟 پرمیومِ تلگرام {months} ماهه ({go.star_count} استارز)\n"
            elif go.gift_id and go.gift_id.startswith("tonsell_"):
                # === PATCH_TON_SELL_V1 === star_count صدم‌تون است
                item_line = f"💎 تون (TON): {(go.star_count or 0) / 100:g} TON\n"
            else:
                item_line = f"🎁 گیفت: {go.gift_emoji or '🎁'} ({go.star_count} استارز)\n"
            await msg.answer(
                f"🔖 <b>کد پیگیری: {code}</b>\n\n"
                f"{item_line}"
                f"💰 مبلغ: {int(go.price_toman):,} تومان\n"
                f"🎯 مقصد: {go.dest_label}\n"
                f"📅 تاریخ: {go.created_at.strftime('%Y-%m-%d %H:%M') if go.created_at else '—'}\n"
                f"📊 وضعیت: {status_label}",
                reply_markup=kb, parse_mode="HTML")
            return

    await msg.answer(
        "❌ سفارشی با این کد پیدا نشد.\n\n"
        "مطمئن شو کد را درست وارد کردی، و اگر سفارش را با اکانتِ تلگرامِ "
        "دیگری خریدی، باید با همان اکانت پیگیری کنی.",
        reply_markup=kb)


