@tenant_router.callback_query(F.data == "set:phonelog")
async def set_phonelog_start(cb: CallbackQuery, bot: Bot, state: FSMContext):
    """تعیینِ کانالِ خصوصی‌ای که شمارهٔ کاربران در آن ثبت شود."""
    row = await _owner_ok(cb, bot)
    if not row:
        return
    cur = (await get_setting(row.id, "phone_log_chat", "")).strip()
    await state.set_state(PhoneLogFSM.chat)
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="🚫 خاموش‌کردن", callback_data="set:phonelog:off",
                              style=ButtonStyle.DANGER)],
        [InlineKeyboardButton(text="❌ انصراف", callback_data="tadm:sec:finance",
                              style=ButtonStyle.DANGER)],
    ])
    await cb.message.answer(
        "📥 <b>کانالِ ثبتِ شماره‌ها</b>\n\n"
        "هر بار کاربری شماره‌اش را تایید کند (چه موقعِ ثبت‌نام، چه پیش از "
        "پرداخت)، مشخصاتش در این کانال ثبت می‌شود: نام، یوزرنیم، آیدی، "
        "شماره، تاریخ و ساعت، و موجودیِ کیفِ پولش.\n\n"
        f"وضعیت فعلی: <code>{_html.escape(cur) if cur else 'تنظیم نشده'}</code>\n\n"
        "آیدیِ عددیِ کانال را بفرست (مثلاً <code>-1001234567890</code>).\n\n"
        "⚠️ ربات باید در آن کانال <b>ادمین</b> باشد، وگرنه چیزی ارسال نمی‌شود.",
        reply_markup=kb)
    await cb.answer()


@tenant_router.callback_query(F.data == "set:phonelog:off")
async def set_phonelog_off(cb: CallbackQuery, bot: Bot, state: FSMContext):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    await state.clear()
    await set_setting(row.id, "phone_log_chat", "")
    await cb.answer("خاموش شد")
    await cb.message.answer("🚫 ثبتِ شماره‌ها در کانال خاموش شد.")


@tenant_router.message(PhoneLogFSM.chat, F.text)
async def set_phonelog_save(msg: Message, bot: Bot, state: FSMContext):
    row = await get_bot_row(bot)
    if not row or not await is_owner_or_admin(row.id, msg.from_user.id, row.owner_id):
        await state.clear()
        return
    chat = (msg.text or "").strip()
    await state.clear()
    # تستِ واقعی: اگر ربات آنجا ادمین نباشد، همین حالا بفهمیم نه وقتی
    # اولین کاربر شماره‌اش را داد و گزارش بی‌صدا گم شد.
    try:
        await bot.send_message(chat, "✅ این کانال برای ثبتِ شماره‌ها تنظیم شد.")
    except Exception as e:
        await msg.answer(
            "❌ نتوانستم به این کانال پیام بفرستم.\n"
            f"<code>{_html.escape(str(e)[:150])}</code>\n\n"
            "مطمئن شو آیدی درست است و ربات در کانال ادمین است، بعد دوباره "
            "امتحان کن.")
        return
    await set_setting(row.id, "phone_log_chat", chat)
    await msg.answer("✅ از این به بعد شمارهٔ کاربران در همین کانال ثبت می‌شود.")


@tenant_router.callback_query(F.data == "set:homemenutext")
async def set_homemenutext_start(cb: CallbackQuery, bot: Bot, state: FSMContext):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    # === PATCH_CUSTOM_HOME_MENU_TEXT_HIDE_V1 ===
    hidden = await home_menu_text_hidden(row.id)
    cur = await get_setting(row.id, "home_menu_text", HOME_MENU_TEXT_DEFAULT)
    _bw_on = await get_setting(row.id, "home_back_welcome", "1") != "0"   # PATCH_HOME_BACK_WELCOME_V1
    await state.set_state(HomeMenuTextFSM.text)
    hide_lbl = ("🙈 مخفی‌کردنِ این پیام: 🟢 فعال — بزن غیرفعال شود" if hidden
                else "🙈 مخفی‌کردنِ این پیام: 🔴 غیرفعال — بزن فعال شود")
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text=hide_lbl, callback_data="set:homemenutext:hide",
                              style=ButtonStyle.DANGER if hidden else ButtonStyle.SUCCESS)],
        # === PATCH_HOME_MENU_TEXT_EDIT_BTN_V1 ===
        # قبلاً فقط انتظارِ خاموشِ FSM بود و اگر مالک بعد از زدنِ دکمهٔ
        # مخفی‌سازی یا برگشت از یک صفحهٔ دیگر می‌آمد، معلوم نبود باید متن
        # بفرستد یا نه. این دکمه همان انتظار را صریح و دوباره فعال می‌کند.
        [InlineKeyboardButton(text="✏️ ویرایشِ متن", callback_data="set:homemenutext:edit",
                              style=ButtonStyle.PRIMARY)],
        [InlineKeyboardButton(text=("🏠 متنِ استارت رویِ منو (شیشه‌ای): 🟢 روشن — بزن خاموش شود"
                                    if _bw_on else "🏠 متنِ استارت رویِ منو (شیشه‌ای): 🔴 خاموش — بزن روشن شود"),
                              callback_data="set:homemenutext:bw", style=ButtonStyle.PRIMARY)],
        # === PATCH_HOME_KB_BUTTON_V1 ===
        [InlineKeyboardButton(text=("⌨️ دکمهٔ ثابتِ پایینِ چت: 🟢 روشن — بزن خاموش شود" if await home_kb_enabled(row.id)
                                    else "⌨️ دکمهٔ ثابتِ پایینِ چت (منوی اصلی): 🔴 خاموش — بزن روشن شود"),
                              callback_data="set:homemenutext:kb", style=ButtonStyle.PRIMARY)],
        [InlineKeyboardButton(text=f"✏️ اسمِ دکمهٔ پایینِ چت: «{await home_kb_label(row.id)}»",
                              callback_data="set:homemenutext:kblabel", style=ButtonStyle.PRIMARY)],
        [InlineKeyboardButton(text="♻️ بازگشت به پیش‌فرض", callback_data="set:homemenutext:reset", style=ButtonStyle.DANGER)],
        [InlineKeyboardButton(text="❌ انصراف", callback_data="tadm:sec:settings", style=ButtonStyle.DANGER)],
    ])
    state_line = ("🙈 الان این پیام <b>مخفیه</b> — کاربر موقعِ برگشت فقط دکمه‌ها "
                  "رو می‌بینه و هیچ متنی نشون داده نمی‌شه.\n\n"
                  if hidden else "")
    await cb.message.answer(
        "🏠 <b>متنِ بازگشت به صفحهٔ اصلی</b>\n\n"
        "این همون متنیه که وقتی کاربر از یه بخش برمی‌گرده عقب، بالای منوی "
        "اصلی نشون داده می‌شه.\n\n"
        f"{state_line}"
        f"متنِ فعلی:\n<code>{_html.escape(cur)}</code>\n\n"
        "متنِ جدید رو بفرست (هر فرمتی که تو تلگرام بزنی حفظ می‌شه):",
        reply_markup=kb)
    await cb.answer()


