# ═══════════════════════════════════════════
#  ری‌اکشن روی پیامِ استارت — PATCH_START_REACTION_V1
# ═══════════════════════════════════════════
# وقتی کاربر /start می‌زند، علاوه بر پیامِ خوش‌آمد، ربات یک ری‌اکشن هم روی
# همان پیامِ /start می‌گذارد (دقیقاً مثلِ آنچه در اسکرین‌شاتِ کاربر بود).
# تلگرام فقط یک فهرستِ محدود از ایموجی‌ها را به‌عنوانِ «ری‌اکشنِ سریع»
# قبول می‌کند؛ برایِ همین گزینه‌هایِ پیش‌فرض از همان فهرستِ رایج انتخاب
# شده‌اند تا خطایِ «ایموجیِ نامعتبر» پیش نیاید، و برایِ ایموجیِ دلخواه هم
# یک مسیرِ متنی با مدیریتِ خطا گذاشته شده.
_START_REACTION_PRESETS = ["👍", "❤️", "🔥", "🎉", "🥳", "👏", "😍", "💯"]


def _start_reaction_kb(current: str) -> InlineKeyboardMarkup:
    rows = []
    row_buf = []
    for emo in _START_REACTION_PRESETS:
        mark = "✅ " if emo == current else ""
        row_buf.append(InlineKeyboardButton(
            text=f"{mark}{emo}", callback_data=f"startreact:set:{emo}",
            style=ButtonStyle.SUCCESS if emo == current else ButtonStyle.PRIMARY))
        if len(row_buf) == 4:
            rows.append(row_buf)
            row_buf = []
    if row_buf:
        rows.append(row_buf)
    rows.append([InlineKeyboardButton(text="✏️ ایموجیِ دیگر", callback_data="startreact:custom",
                                      style=ButtonStyle.PRIMARY)])
    rows.append([InlineKeyboardButton(
        text=("🔴 خاموش‌کردن" if current else "خاموش است"),
        callback_data="startreact:off",
        style=ButtonStyle.DANGER if current else ButtonStyle.PRIMARY)])
    rows.append([InlineKeyboardButton(text="⬅️ بازگشت", callback_data="tadm:sec:settings",
                                      style=ButtonStyle.DANGER)])
    return InlineKeyboardMarkup(inline_keyboard=rows)


async def _start_reaction_text(current: str) -> str:
    st = f"روشن — {current}" if current else "خاموش"
    return (
        "😀 <b>ری‌اکشن روی پیامِ استارت</b>\n\n"
        f"وضعیت: {st}\n\n"
        "اگر روشن باشد، هر بار کاربری /start بزند، ربات همان لحظه رویِ پیامِ "
        "خودِ او این ایموجی را به‌عنوانِ ری‌اکشن می‌گذارد — درست مثلِ زمانی "
        "که خودت رویِ یک پیام ری‌اکشن می‌زنی.\n\n"
        "یکی از ایموجی‌های رایج را انتخاب کن، یا اگر ایموجیِ دیگری مدنظرت "
        "است «✏️ ایموجیِ دیگر» را بزن."
    )


@tenant_router.callback_query(F.data == "set:startreact")
async def set_start_reaction_menu(cb: CallbackQuery, bot: Bot, state: FSMContext):
    if not await _gate(cb, bot, Feature.CUSTOM_WELCOME):
        return
    row = await get_bot_row(bot)
    await state.clear()
    current = await get_setting(row.id, "start_reaction_emoji", "")
    try:
        await cb.message.edit_text(await _start_reaction_text(current),
                                   reply_markup=_start_reaction_kb(current))
    except Exception:
        await cb.message.answer(await _start_reaction_text(current),
                                reply_markup=_start_reaction_kb(current))
    await cb.answer()


