@tenant_router.callback_query(F.data.startswith("cfgguide:showcat:"))
async def cfgguide_showcat(cb: CallbackQuery, bot: Bot):
    """نمایشِ متنِ آموزشِ اتصالِ اختصاصیِ یک دسته‌بندی به کاربر."""
    row = await get_bot_row(bot)
    if not row:
        await cb.answer()
        return
    _, _, source, entry_id = cb.data.split(":", 3)
    entries = await _cfgguide_catmap_get(row.id, source)
    entry = next((e for e in entries if e["id"] == entry_id), None)
