@tenant_router.callback_query(F.data.startswith("guide_edit:"))
async def tadm_guide_edit_pick(cb: CallbackQuery, bot: Bot, state: FSMContext):
    row = await _owner_ok(cb, bot)
    if not row:
        return
    key = cb.data.split(":", 1)[1]
    setting_key = await _guide_text_key(row.id, key)
    if not setting_key:
        await cb.answer("یافت نشد", show_alert=True)
        return
    default_text = ""
    if key in _GUIDE_KEYS:
        from tenant.bots.vpn.vpn_user import _GUIDE as _VPN_GUIDE
        default_text = _VPN_GUIDE.get(key, "")
    current = await get_setting(row.id, setting_key, default_text)
    label = await _guide_label_of(row.id, key)
    await state.set_state(GuideEditFSM.text_edit)
    await state.update_data(guide_key=key, bot_id=row.id)
    cur_block = f"متن فعلی:\n<blockquote>{current}</blockquote>\n\n" if current.strip() else \
        "متن فعلی: (هنوز تنظیم نشده)\n\n"
    await cb.message.answer(
        f"✏️ <b>ویرایش متن آموزش {label}</b>\n\n"
        + cur_block +
        "متن جدید را بفرست.\n"
        "تمام قابلیت‌های متنی تلگرام پشتیبانی می‌شود: "
        "<b>بولد</b>، <i>ایتالیک</i>، <u>زیرخط</u>، <s>خط‌خورده</s>, "
        "<code>کد</code>، <a href='https://example.com'>لینک</a>، اسپویلر، بلاک‌کوت.\n\n"
        "می‌توانی لینک دانلود برنامه را هم به‌صورت هایپرلینک قرار دهی.\n\n"
        "(یا /skip برای بازگشت بدون تغییر)",
        reply_markup=await smart_cancel_kb(bot),
    )
    await cb.answer()


