@tenant_router.message(GuideEditFSM.new_name, F.text)
async def guide_add_name(msg: Message, state: FSMContext, bot: Bot):
    data = await state.get_data()
    bot_id = data.get("bot_id")
    if not bot_id:
        await state.clear()
        return
    raw = (msg.text or "").strip()
    if raw in ("/skip", "❌ لغو", "❌ لغو / بازگشت"):
        await state.clear()
        await msg.answer("لغو شد.", reply_markup=await tadmin_kb(bot_id))
        await _edit_guides_show(msg, bot_id)
        return
    if len(raw) > 40:
        await msg.answer("❌ نام دکمه خیلی طولانی است (حداکثر ۴۰ کاراکتر). یک نام کوتاه‌تر بفرست.")
        return
    customs = await _guide_custom_list(bot_id)
    nums = [int(g["key"][1:]) for g in customs
            if g["key"].startswith("c") and g["key"][1:].isdigit()]
    new_key = f"c{(max(nums) + 1) if nums else 1}"
    customs.append({"key": new_key, "label": raw})
    await _guide_save_custom_list(bot_id, customs)
    await state.set_state(GuideEditFSM.new_text)
    await state.update_data(guide_key=new_key)
    await msg.answer(
        f"✅ دکمهٔ «{_html.escape(raw)}» ساخته شد.\n\n"
        "حالا <b>متنِ آموزشِ</b> این دکمه را بفرست تا وقتی کاربر رویش زد نمایش داده شود.\n"
        "تمام قابلیت‌های متنی تلگرام (بولد، لینک و…) پشتیبانی می‌شود.\n\n"
        "(یا /skip که فعلاً بدون متن بماند — بعداً می‌تونی با «✏️ متن» تنظیمش کنی)",
        reply_markup=await smart_cancel_kb(bot),
    )


